-- Sources: data/i18n/ruRU. Lore text adapted from warcraft.wiki.gg (CC BY-SA 4.0); the core add-on's src fields name the articles.
local P = LoreForeverPacks.Begin("LoreForever_Lang_ruRU")
P.entries["quest:6482"] = {n="Свободу Руулу!",s="Глубоко в Крепости Колючего Меха на севере Ясеневого леса в клетке ждет спасения медведь по имени Руул, плененный испорченными фурболгами Колючего Меха. Искатели приключений из Орды могут помочь пленнику пробиться из логова фурболгов на свободу.",h="Глубоко в Крепости Колючего Меха на севере Ясеневого леса в клетке ждет спасения медведь по имени Руул...",kw={"ashenvale","druid escort","furbolg","ruul snowhoof","splintertree post","thistlefur hold","yama snowhoof","ясеневый лес","сопровождение друида","фурболг","руул снежное копыто","застава расщепленного дерева","крепость колючего меха","ями снежное копыто"},ang={["class:Druid"]="Плен Руула — скромное напоминание об опасности скитаний по диким землям в облике зверя, где оскверненные местные жители не отличают друга от добычи.",["faction:Horde"]="Каждая душа, спасенная из оскверненных логовищ севера Ясеневого леса, укрепляет шаткий аванпост Орды — Заставу Расщепленного Дерева.",["race:Tauren"]="Спасение заблудившегося брата по Кругу Кенария и избавление от тревоги его родичей на Заставе Расщепленного Дерева чтят узы Матери-Земли и Орды."},sec={{t="Друид в цепях",b="Странствуя по оскверненным лесам севера Ясеневого леса, друид Руул Снежное Копыто в облике медведя подошел слишком близко к Крепости Колючего Меха. Оскверненные фурболги, лишенные мудрости предков и охваченные диким безумием, приняли обернувшегося таурена за обычного зверя. Вместо почтения они посадили его в клетку и морили голодом, истощив его магические силы, так что он не смог освободиться сам."},{t="Побег из Логова",b="Ослабленный голодом и неволей, Руул не может ни сменить облик, ни пробиться через пещерное поселение фурболгов без помощи. После освобождения союзником Орды он рассчитывает на своего спасителя, который расчистит путь сквозь толпы враждебных воинов Колючего Меха. Благополучно добравшись до окрестностей Заставы Расщепленного Дерева, он ненадолго принимает истинный облик таурена, чтобы сердечно поблагодарить спасителя, а затем возвращается в дикую природу отсыпаться."}},faq={{q="Почему фурболги заперли Руула Снежного Копыта?",a="Руул исследовал леса в облике медведя. Оскверненные фурболги Колючего Меха не узнали в нем друида, приняли его за дикого зверя и заперли в клетке, где морили голодом, пока у него не осталось сил на побег.",al={"why is ruul trapped","how did ruul get captured","why caged","почему руул в плену","как руул попал в плен","почему в клетке"}},{q="Кто такая Ями Снежное Копыто?",a="Ями Снежное Копыто — сестра Руула, служащая на Заставе Расщепленного Дерева в Ясеневом лесу. Она сильно встревожилась, когда Руул несколько дней назад ушел в лес и не вернулся.",al={"ruul sister","yama splintertree","who is yama","сестра руула","ями снежное копыто","кто такая ями"}},{q="Почему Руул не мог просто сменить облик медведя и сбежать?",a="Долгий плен и намеренное голодание у фурболгов Колючего Меха сильно ослабили Руула. Без пищи и сил его запас природной энергии полностью иссяк, и он оставался беспомощным до спасения.",al={"why didnt ruul shapeshift","druid bear trap","почему руул не сменил облик","друид медведь клетка"}},{q="Что происходит после того, как Руул оказывается в безопасности?",a="Когда его выводят из враждебного логова к границам Заставы Расщепленного Дерева, Руул ненадолго принимает свой природный облик таурена, чтобы выразить благодарность, а затем снова обращается медведем и уходит искать тихое место, чтобы поспать и восстановить силы.",al={"where does ruul go","ruul ending","куда идет руул","концовка руула"}},{q="Все ли фурболги Ясеневого леса враждебны, как племя Колючего Меха?",a="Нет. Хотя многие племена фурболгов обладают благородным наследием и тесно связаны с природой, фурболги Колючего Меха на севере Ясеневого леса поддались темному, оскверняющему влиянию, которое сделало их агрессивными и непредсказуемыми.",al={"are furbolgs evil","thistlefur corruption","фурболги злые","порча колючего меха"}},{q="Где происходит спасение?",a="Руул заточен в Крепости Колючего Меха — логове фурболгов в холмах к северо-западу от Заставы Расщепленного Дерева и к северу от Астранаара в Ясеневом лесу.",al={"where is ruul","ruul snowhoof location","где руул","местонахождение руула снежное копыто"}}},fp="15,223,17.433.0,19.421.1,48.238.1,21.176.0,56.235.1,39.229.1,59.215.0,33.145.0"}
P.entries["quest:65"] = {n="Братство Справедливости",s="Это поручение — первый шаг к раскрытию тайного синдиката, терроризирующего Западный Край. По указанию Гриана Камнегрива из Сторожевого холма путники направляются на восток, в Красногорье, к сомнительному знакомому, который может знать, где прячутся воры.",h="Это поручение — первый шаг к раскрытию тайного синдиката, терроризирующего Западный Край.",kw={"defias","gryan stoutmantle","lakeshire","redridge","sentinel hill","westfall","wiley the black","братство справедливости","гриан камнегрив","приозерье","красногорье","сторожевой холм","западный край","вилли черный"},ang={["class:Rogue"]="Камнегрив понимает, что регулярными военными методами преступный синдикат не сокрушить: нужен тот, кто знает тени и уличные услуги, — и это ведет прямо к Вилли Черному.",["faction:Alliance"]="Долгий путь из Западного Края в Красногорье показывает, насколько сильно внешним землям Штормграда приходится полагаться друг на друга, пока столица остается равнодушной."},sec={{t="Угроза в пыли",b="Западный Край пришел в упадок: урожаи отняты, а землю наводнили бандиты в красных банданах. Гриан Камнегрив и Народное ополчение удерживают Сторожевой холм под почти непрерывными налетами, но действуют вслепую. Камнегрив понимает, что, отбиваясь от одиночных грабителей, край не спасти, пока не найдены главари картеля и тот, кто ими командует."},{t="Знакомый за пределами города",b="Вместо официальных военных каналов и штормградских знатных господ, не заботящихся о крае, Камнегрив обращается к личным долгам. Он посылает доверенных приключенцев через Элвиннский лес в Красногорье. В тихом озерном селении Приозерье, на верхнем этаже местной таверны, засел плут по имени Вилли Черный. Он знает преступный мир куда лучше любого капитана ополчения, и Вилли — первая нить к убежищам Братства."}},faq={{q="Кто такой Гриан Камнегрив?",a="Гриан Камнегрив — предводитель Народного ополчения, разношерстных сил обороны, расквартированных в Сторожевом холме в Западном Крае. Поскольку Штормград пренебрегает пограничными землями, он руководит защитой немногих оставшихся местных фермеров и беженцев.",al={"gryan stoutmantle","who gives this quest","quest giver westfall","гриан камнегрив","кто выдает это задание","персонаж, выдающий задания западный край"}},{q="Почему Камнегрив посылает вас в Приозерье?",a="У Народного ополчения нет подпольных осведомителей в самом Западном Крае. Камнегрив призывает старую личную услугу от Вилли Черного, плута, живущего в таверне Приозерья, в надежде, что связи в преступном мире помогут выяснить, кто возглавляет воров.",al={"why lakeshire","why go to redridge","why wiley","почему приозерье","почему идти в красногорье","почему вилли"}},{q="Кто такой Вилли Черный?",a="Вилли Черный — плут, остановившийся на втором этаже Таверны Приозерья в Красногорье. Он должен услугу Гриану Камнегриву, поэтому служит полезным источником слухов преступного мира и связей с преступниками.",al={"who is wiley","wiley lakeshire","wiley the black","кто такой вилли","вилли приозерье","вилли черный"}},{q="Что такое Братство Справедливости?",a="Братство Справедливости — безжалостный преступный картель в красных масках, захвативший фермы, дороги и заброшенные шахты Западного Края, изгоняющий поселенцев и бросающий вызов власти Штормграда.",al={"defias brotherhood","what is defias","red bandana bandits","братство справедливости","что такое дефиасы","бандиты в красных банданах"}},{q="Где найти Вилли в Приозерье?",a="Вилли Черный находится наверху, на втором этаже Таверны Приозерья, которая стоит возле моста в городке Приозерье в Красногорье.",al={"where is wiley","find wiley","wiley location","где вилли","найти вилли","местонахождение вилли"}},{q="Нужно ли в этом задании сражаться?",a="Нет. Этот начальный шаг чисто информационный. Вы просто отправляетесь из Сторожевого холма в Западном Крае через Элвиннский лес к таверне в Приозерье, чтобы встретиться с Вилли.",al={"is this quest hard","combat in defias brotherhood quest","enemies","сложно ли задание","бой в задании братства справедливости","враги"}}},fp="22,253,22.387.0,22.453.0,25.238.0,43.236.0,23.210.0,31.221.0,36.149.0,35.171.0"}
P.entries["quest:6503"] = {n="Вестницы Ясеневого леса",s="«Вестницы Ясеневого леса» — задание Орды по перехвату патрулей, выдаваемое Курай'бином в Ясеневом лесу. Разведчики ночных эльфов рассредоточились от Аванпоста Среброкрылых, собирая сведения о ближайших лагерях Орды, что требует упреждающего удара, чтобы скрыть оборону аванпоста. Выслеживая этих неуловимых разведчиков, Орда лишает местные силы Альянса зрения и отбивает охоту к новым вторжениям.",h="«Вестницы Ясеневого леса» — задание Орды по перехвату патрулей, выдаваемое Курай'бином в Ясеневом лесу.",kw={"alliance","ashenvale","ashenvale outrunners","horde","kuray'bin","night elf scouts","silverwing outpost","альянс","ясеневый лес","вестницы ясеневого леса","орда","курай'бин","разведчики ночных эльфов","аванпост среброкрылых"},ang={["class:Hunter"]="Выслеживание скрытых вестниц в глухих лесах требует острого чутья, обостренного чувства следа и меткой стрельбы.",["class:Rogue"]="Уничтожение вражеских вестниц оборачивает скрытность ночных эльфов против них самих, и лазутчики Орды остаются хозяевами лесных теней.",["faction:Horde"]="Каждая сраженная в Ясеневом лесу разведчица ночных эльфов защищает местные лагеря и лесозаготовки от согласованных контрударов Альянса."},sec={{t="Глаза в кронах",b="Чащи Ясеневого леса остаются спорным рубежом, где за каждой тропой и хребтом пристально следят. Разведка смертельна, как топор, и донесения, поступающие к Курай'бину, подтверждают: разведчицы ночных эльфов, известные как Вестницы Ясеневого леса, выскользнули из оплота Альянса — Аванпоста Среброкрылых. Действуя в густых дебрях к востоку от своей базы и к югу от владений Орды, эти разведчицы крадутся по лесным тропам, нанося на карту укрепления и отслеживая передвижения войск."},{t="Ослепить Альянс",b="Чтобы предотвратить организованное нападение, Орда стремится уничтожать вражескую разведку до ее возвращения. Выслеживая вестниц, воины Орды лишают командиров Аванпоста Среброкрылых важных сведений о численности войск и обороне периметра аванпоста. Лишившись передовых глаз, ночные эльфы теряют ориентацию и гораздо менее охотно рискуют проводить наступательные маневры в спорных лесах."}},faq={{q="Кто выдает задание «Вестницы Ясеневого леса»?",a="Задание выдает Курай'бин, координатор разведчиков Орды, расквартированный в Ясеневом лесу, который следит за передвижениями ночных эльфов в лесу и противодействует им.",al={"quest giver","who gives quest","kuray'bin quest","персонаж, выдающий задания","кто выдает задание","задание курай'бина"}},{q="Где находятся Вестницы Ясеневого леса?",a="Вестницы рыщут по лесам к востоку от Аванпоста Среброкрылых и к югу от лагеря Курай'бина, патрулируя подлесок и собирая сведения.",al={"outrunners location","where are outrunners","where to find outrunners","где вестницы","где находятся вестницы","где найти вестниц"}},{q="Чем вестницы опасны для Орды?",a="Вестницы — передовые разведчицы, действующие из Аванпоста Среброкрылых. Если им удастся нанести на карту лагеря Орды и подсчитать войска, Альянс сможет скоординировать точные налеты на уязвимые позиции.",al={"why kill outrunners","threat of outrunners","outrunner purpose","зачем убивать вестниц","угроза вестниц","цель вестниц"}},{q="Что такое Аванпост Среброкрылых?",a="Аванпост Среброкрылых — крупное военное укрепление ночных эльфов в Ясеневом лесу, передовая база сил Альянса, защищающих лес и противостоящих расширению Орды.",al={"silverwing outpost lore","what is silverwing outpost","silverwing alliance","аванпост среброкрылых","что такое аванпост среброкрылых","среброкрылые альянс"}},{q="Входит ли это задание в более длинную цепочку?",a="Это задание — прежде всего самостоятельная тактическая задача по сокращению разведки Альянса в этом районе, награждающая бойцов, которые помогают Курай'бину охранять периметр.",al={"quest chain","follow up quest","outrunner chain","цепочка заданий","следующее задание","цепочка вестниц"}},{q="Могут ли игроки Альянса выполнить это задание?",a="Нет, это задание доступно только Орде. Курай'бин действует строго в интересах передовых сил Орды в Ясеневом лесу.",al={"is this horde only","alliance version","can alliance do this","только для орды","версия для альянса","может ли альянс выполнить это"}}},fp="20,388,20.476.0,21.423.0,41.151.0,43.148.0,45.204.0,27.180.0,41.179.0,41.119.0"}
P.entries["quest:6504"] = {n="Утраченные страницы",s="Когда орчиха Гурда Печать Гнева везла только что купленную гоблинский крошшер из Кабестана на Лесозаготовки Песни Войны, внезапный порыв ветра унес руководство по эксплуатации машины. Застряв возле Заставы Расщепленного Дерева, она не может управлять этим сложным инженерным чудом, пока не соберет разлетевшиеся страницы.",h="Когда орчиха Гурда Печать Гнева везла только что купленную гоблинский крошшер из Кабестана на Лесозаготовки...",kw={"ashenvale","gurda ragescar","ratchet","shredder","shredder operating manual","splintertree post","the lost pages","warsong lumber camp","ясеневый лес","гурда печать гнева","кабестан","крошшер","руководство по эксплуатации крошшера","застава расщепленного дерева","утраченные страницы","лесозаготовки песни войны"},ang={["faction:Horde"]="Каждый крошшер, добравшийся до Лесозаготовок Песни Войны, ускоряет заготовку драгоценной древесины, необходимой для строительства стен, хижин и боевых кораблей в Дуротаре.",["profession:Engineering"]="Механики прекрасно поймут затруднение Гурды: управлять гоблинским крошшером без инструкции изготовителя — верный путь к катастрофическому взрыву котла.",["race:Orc"]="Тяжелый физический труд и воинские традиции оставляют мало терпения для подробных гоблинских бумаг, поэтому раздражение Гурды из-за потерянных технических листов вполне понятно."},sec={{t="Порыв неудачи",b="Клан Песни Войны сильно зависит от паровых крошшеров, купленных у гоблинов порта Кабестан, для вырубки леса в Ясеневом лесу. Управлять этими хрупкими шумными механизмами обычному орку-воину совсем не просто. Когда Гурда Печать Гнева отправилась на север с только что купленным крошшером, внезапный порыв ветра вырвал у нее из рук инструкцию и разбросал двенадцать хрупких пергаментных листов по лесной земле."},{t="Страницы в дебрях",b="Поскольку дикие ветры пронесли руководство над кронами, отдельные страницы оказались в руках бродячих существ, культистов и лесных обитателей по всему региону. Пока не собраны все три главы, сложный механизм остается неподвижной глыбой стали с жужжащими пилами, а Гурда застряла на дороге к Заставе Расщепленного Дерева и не может явиться на лесозаготовки."}},faq={{q="Кто такая Гурда Печать Гнева?",a="Гурда Печать Гнева — работница Орды, которой поручено доставить гоблинский крошшер из торгового порта Кабестан в Ясеневый лес для участия в вырубке на Лесозаготовках Песни Войны.",al={"gurda","ragescar","who is the quest giver","гурда","печать гнева","кто выдает задание"}},{q="Зачем Гурде нужно руководство, чтобы управлять крошшером?",a="Гоблинская инженерия славится капризностью и нелогичностью: она полагается на взрывоопасные котлы, хитрые клапаны давления и сложные рычаги. Даже усердный орк не может безопасно управлять механизмом, не прочитав руководство изготовителя.",al={"why manual","why cant she drive it","shredder operating manual","зачем руководство","почему она не может управлять","руководство по эксплуатации крошшера"}},{q="Как страницы руководства оказались разбросаны по всему Ясеневому лесу?",a="Когда Гурда ехала на север по лесной дороге, сильный порыв ветра вырвал книгу у нее из рук. Рассыпавшиеся страницы разлетелись по лесу, и у нее осталась лишь пустая обложка.",al={"how did pages get lost","wind blew pages","как потерялись страницы","ветер унес страницы"}},{q="Куда в итоге предназначен крошшер?",a="Машина предназначена для Лесозаготовок Песни Войны, где Орда ведет усиленную сплошную вырубку, чтобы снабжать древесиной Оргриммар и Дуротар.",al={"where is the shredder going","warsong shredder destination","куда направляется крошшер","назначение крошшера песни войны"}},{q="Где найти пропавшие страницы?",a="Ветры разнесли страницы далеко и широко, и их подобрали разные гуманоиды и враждебные лесные обитатели, бродящие по Ясеневому лесу.",al={"where to find pages","who drops the pages","где найти страницы","у кого страницы"}},{q="Почему Орда покупает механизмы в Кабестане?",a="Кабестан — ближайший нейтральный порт с действующими торговыми связями с гоблинскими картелями. Орда регулярно закупает специализированную технику, подрывные инструменты и паровые машины для усиления своей военной логистики.",al={"horde goblin machinery","ratchet trade horde","гоблинские механизмы орды","торговля кабестана с ордой"}}},fp="14,296,18.449.0,23.388.0,22.180.0,64.235.0,61.195.0,42.159.0,37.143.0,51.225.0"}
P.entries["quest:6523"] = {n="Защита Кайи",s="«Защита Кайи» — задание Орды с сопровождением в Когтистых горах. Обнаружив Кайю Плоское Копыто в плену у враждебных тауренов из племени Зловещего Тотема, искатели приключений проводят ее по опасным горным тропам до Лагеря Апарахе. Весть о ее спасении приносит огромное облегчение ее встревоженному отцу, Макабе Плоскому Копыту.",h="«Защита Кайи» — задание Орды с сопровождением в Когтистых горах.",kw={"camp aparaje","escort","grimtotem","kaya flathoof","makaba flathoof","protect kaya","stonetalon","tauren","лагерь апарахе","сопровождение","зловещий тотем","кайя плоское копыто","макаба плоское копыто","защита кайи","когтистые горы","таурен"},ang={["faction:Horde"]="Забота о безопасности путешествующих семей укрепляет с трудом завоеванные Ордой плацдармы и маршруты снабжения в Когтистых горах.",["race:Tauren"]="Спасение Кайи напрямую помогает сородичам, страдающим от агрессии клана Зловещего Тотема."},sec={{t="Пленница в скалах",b="В Когтистых горах среди тауренов бушуют острые распри, и нигде напряжение не сильнее, чем вокруг вероломного клана Зловещего Тотема. Глубоко на вражеской земле Кайя Плоское Копыто была схвачена и заточена. Бежать пешком означает пробираться по извилистым тропам, где поджидают хищники и бдительные враги, поэтому вооруженный эскорт — ее единственная реальная надежда добраться до дружественных земель."},{t="Бегство в Лагерь Апарахе",b="Лагерь Апарахе находится в восточной части Когтистых гор, и оттуда Кайя знает дорогу домой. Она стремится к лагерю, уверенная, что, добравшись до него, найдет путь сама. Если провести ее по тропам, полным засад, она избежит повторного плена, пока похитители не поняли, что она ускользнула."},{t="Облегчение отца",b="В ожидании вестей у юго-восточной границы Когтистых гор Макаба Плоское Копыто опасается худшего за пропавшую дочь. Когда гонцы приносят подтверждение, что Кайя благополучно добралась до Лагеря Апарахе, отчаяние Макабы сменяется безмерной благодарностью героям, вставшим между его дитя и ее похитителями."}},faq={{q="Кто такая Кайя Плоское Копыто?",a="Кайя Плоское Копыто — молодая таурен, захваченная враждебными силами Зловещего Тотема в Когтистых горах. Она надеется на проходящих мимо искателей приключений Орды, которые помогут ей бежать и проводят в безопасное место.",al={"who is kaya","kaya flathoof lore","kaya","кто такая кайя","кайя плоское копыто предания","кайя"}},{q="Куда нужно сопроводить Кайю?",a="Кайю нужно благополучно проводить по тропам до Лагеря Апарахе в восточных Когтистых горах, откуда она сама знает дорогу домой.",al={"kaya escort destination","where to take kaya","where does kaya go","куда сопровождать кайю","куда вести кайю","куда идет кайя"}},{q="Кто такой Макаба Плоское Копыто?",a="Макаба Плоское Копыто — отец Кайи, тревожно ждущий у юго-восточного входа в Когтистые горы. Он отчаивается из-за пропавшего ребенка, пока искатели приключений не приносят весть о ее спасении.",al={"who is makaba","makaba flathoof lore","kaya's father","кто такой макаба","макаба плоское копыто предания","отец кайи"}},{q="Кто похитил Кайю?",a="Кайю взяли в плен враждебные таурены из племени Зловещего Тотема, устроившие лагеря и засады среди скал Когтистых гор.",al={"who took kaya","who kidnapped kaya","kaya kidnappers","кто похитил кайю","кто взял кайю в плен","похитители кайи"}},{q="Что происходит после того, как Кайя добирается до Лагеря Апарахе?",a="Когда Кайя добирается до Лагеря Апарахе, она может найти дорогу сама, а игроку поручено вернуться к Макабе Плоскому Копыту и принести радостную весть о ее спасении.",al={"after protect kaya","what next after escort","protect kaya follow up","после защиты кайи","что дальше после сопровождения","защита кайи продолжение"}},{q="Доступно ли это задание игрокам Альянса?",a="Нет. Семья Плоское Копыто принадлежит к мирным тауренам, союзным Орде, поэтому это спасение доступно только искателям приключений Орды.",al={"can alliance do protect kaya","is kaya horde only","может ли альянс защита кайи","только ли орда кайя"}}},fp="12,311,22.400.0,22.295.0,17.322.1,21.195.0,36.131.0,23.190.0,18.115.0,45.162.0,44.137.0"}
P.entries["quest:6541"] = {n="Донесение Кадраку",s="Торк на Перекрестке направляет способных бойцов Орды на север, к сторожевой башне Кадрака у границы Ясеневого леса. Кадрак координирует расширение Орды в древний лес и готовит прибывающих новобранцев к предстоящим стычкам.",h="Торк на Перекрестке направляет способных бойцов Орды на север, к сторожевой башне Кадрака у границы Ясеневого...",kw={"ashenvale","barrens","crossroads","kadrak","splintertree","thork","watch tower","zoram strand","ясеневый лес","степи","перекресток","кадрак","застава расщепленного дерева","торк","сторожевая башня","зорамское взморье"},ang={["faction:Horde"]="Это поручение знаменует переход от обороны обжитых земель в Степях к защите жизненно важных ресурсных путей в спорных лесах на севере.",["race:Orc"]="Ясеневый лес — важное испытание для орков: древесина нужна, чтобы укрепить Оргриммар и создать прочный дом в Калимдоре."},sec={{t="Дорога на север",b="Пока Перекресток отбивается от свинобразов, кентавров и местных разбойников, более широкие территориальные интересы Орды обращены на север, к густым чащам Ясеневого леса. Торк выступает посредником, направляя опытных бойцов, проявивших себя в центральных Степях, к северной пограничной башне, которой командует Кадрак."},{t="Стратегия на границе",b="Кадрак руководит южными подступами к Ясеневому лесу, организуя подкрепление для плацдарма Орды за границей. С новыми лагерями, такими как Застава Расщепленного Дерева и форт на Зорамском взморье, Орда активно укрепляет свое присутствие в богатых древесиной лесах, несмотря на ожесточенное сопротивление местных ночных эльфов."}},faq={{q="Кто такой Торк?",a="Торк — офицер-орк, расквартированный на Перекрестке в Степях. Он помогает координировать местную оборону и направляет перспективных искателей приключений на региональные военные кампании, такие как война в Ясеневом лесу.",al={"thork crossroads","who gives report to kadrak","thork barrens","торк перекресток","кто дает донесение кадраку","торк степи"}},{q="Где находится Кадрак?",a="Кадрак стоит на северной сторожевой башне в Степях, прямо у главной дороги, ведущей в Ясеневый лес.",al={"kadrak location","where is kadrak","kadrak watch tower","где кадрак","расположение кадрака","сторожевая башня кадрака"}},{q="Почему Орда продвигается в Ясеневый лес?",a="Орде нужны древесина и ресурсы для строительства новых городов в Дуротаре и Степях. Расширение в Ясеневый лес дает жизненно важный лес, но ставит Орду в прямой конфликт с ночными эльфами.",al={"why ashenvale","horde in ashenvale","ashenvale invasion","почему ясеневый лес","орда в ясеневом лесу","вторжение в ясеневый лес"}},{q="Какие форпосты Орда основала в Ясеневом лесу?",a="Кадрак сообщает, что Орда основала Заставу Расщепленного Дерева на центральной дороге в лес и еще один форпост западнее, на Зорамском взморье.",al={"horde bases ashenvale","zoram strand base","splintertree","базы орды ясеневый лес","база зорамское взморье","застава расщепленного дерева"}},{q="Что будет после донесения Кадраку?",a="Когда вы доложите Кадраку, он расскажет вам о местной военной обстановке и поручит собрать отчеты на разных заставах клана Песни Войны в Ясеневом лесу.",al={"after kadrak","next quest after kadrak","what does kadrak give","после кадрака","следующее задание после кадрака","что дает кадрак"}},{q="Можно ли получить это задание не в Степях?",a="Да. Почти такой же приказ явиться к Кадраку получают бойцы Орды в Малака'джине в Когтистых горах.",al={"alternate kadrak quest","stonetalon kadrak quest","другое задание кадрака","задание кадрака когтистые горы"}}},fp="16,238,14.323.0,17.338.0,13.204.0,24.127.0,40.204.0,53.157.0,37.158.0,69.136.0"}
P.entries["quest:6542"] = {n="Донесение Кадраку",s="Этот военный приказ направляет воинов Орды из Малака'джина в Когтистых горах к сторожевому посту Кадрака на границе северных Степей. Он знаменует переход от обороны скал к усилению спорной военной кампании Орды в Ясеневом лесу. Доложив Кадраку, солдаты отправляются поддерживать передовые лагеря, такие как Застава Расщепленного Дерева и Зорамское взморье.",h="Этот военный приказ направляет воинов Орды из Малака'джина в Когтистых горах к сторожевому посту Кадрака на...",kw={"ashenvale","barrens","darn talongrip","kadrak","splintertree","stonetalon mountains","warsong reports","zoram strand","ясеневый лес","степи","дарн цепкохват","кадрак","застава расщепленного дерева","когтистые горы","отчет песни войны","зорамское взморье"},ang={["faction:Horde"]="Этот приказ включает вас в более широкие военные усилия Вождя, направляя бывалых бойцов границы в борьбу за ресурсы Ясеневого леса.",["race:Orc"]="Кампания в Ясеневом лесу крайне важна для клана Песни Войны и выживания Дуротара, поэтому пост Кадрака — испытательная площадка для молодых орков-воинов.",["race:Tauren"]="Дозорные Орды, такие как орк Дарн Цепкохват, безопасно проводят путников через горные границы, сохраняя связь между землями Кровавого Копыта и северным фронтом Вождя."},sec={{t="Призыв на северный фронт",b="В скалистом проходе Малака'джин орк Дарн Цепкохват следит за южными и горными рубежами Орды. Но главное военное давление приходится на север, в древние чащи Ясеневого леса, где часовые ночных эльфов беспрестанно сражаются с лесорубами клана Песни Войны. Видя бывалых бойцов, проходящих через Когтистые горы, Дарн направляет способных новобранцев к северной сторожевой башне в Степях, чтобы помочь в идущих кампаниях."},{t="Дозор Кадрака",b="Орк Кадрак стоит на северном рубеже, где засушливая саванна встречается с зеленым пологом Ясеневого леса, и руководит передвижением войск Орды на спорную территорию. Орда напористо укрепляет свои позиции, держа форпосты на западном Зорамском взморье и на Заставе Расщепленного Дерева на севере. Кадрак служит важным узлом для координации снабжения, войск и срочных донесений на этих осажденных лесных рубежах."}},faq={{q="Кто посылает вас к Кадраку из Когтистых гор?",a="Дарн Цепкохват, орк, расквартированный на форпосте Орды Малака'джин в Когтистых горах, дает этот приказ способным искателям приключений, направляющимся к границе леса.",al={"quest giver report to kadrak","who starts report to kadrak stonetalon","darn talongrip quest","персонаж, выдающий задания донесение кадраку","кто начинает донесение кадраку когтистые горы","задание дарна цепкохвата"}},{q="Где находится Кадрак?",a="Кадрак стоит на северной сторожевой башне в Степях и охраняет главную дорогу, ведущую на север, в Ясеневый лес.",al={"kadrak location","where is kadrak","find kadrak","где кадрак","расположение кадрака","найти кадрака"}},{q="Почему Орда набирает воинов для Ясеневого леса?",a="Орде нужна древесина для Оргриммара, и она создала укрепленные позиции, такие как Зорамское взморье и Застава Расщепленного Дерева. Поскольку им противостоят местные ночные эльфы, командирам постоянно нужно подкрепление, чтобы удержать территорию.",al={"why go to ashenvale","horde ashenvale campaign","why fight in ashenvale","зачем идти в ясеневый лес","кампания орды в ясеневом лесу","зачем воевать в ясеневом лесу"}},{q="Что происходит после донесения Кадраку?",a="Кадрак расскажет вам о стратегической обстановке в Ясеневом лесу и поручит доставлять и собирать военные донесения на спорных форпостах леса в задании «Отчет Песни Войны».",al={"what next after kadrak","the warsong reports","kadrak follow up quest","что дальше после кадрака","отчет песни войны","продолжение задания кадрака"}},{q="Отличается ли это задание от версии в Степях?",a="Оба задания — вводные и ведут к Кадраку на границе Ясеневого леса. Одно выдается в Степях (на Перекрестке), другое — в Когтистых горах; выполнение любого из них направляет вас в сюжетную линию Ясеневого леса.",al={"barrens vs stonetalon kadrak","two report to kadrak quests","kadrak breadcrumb duplicate","кадрак степи или когтистые горы","два задания донесение кадраку","дубликат вводного задания кадрака"}},{q="Что такое Зорамское взморье, упомянутое в инструктаже?",a="Зорамское взморье — прибрежная область на северо-западе Ясеневого леса у Сокрытого Моря. Орда основала там укрепленный пляжный форпост для тактических передвижений и обеспечения морского доступа.",al={"what is zoram strand","zoram strand outpost","ashenvale beach base","что такое зорамское взморье","форпост зорамское взморье","пляжная база ясеневый лес"}}},fp="16,398,28.440.0,14.447.0,40.174.0,24.128.0,51.274.0,39.186.0,49.221.0,51.197.0"}
P.entries["quest:6543"] = {n="Отчет Песни Войны",s="Это задание, выдаваемое Кадраком на пограничной башне между северными Степями и Ясеневым лесом, поручает гонцам координировать разведданные по всему спорному лесу. Искатели приключений должны доставить действующие приказы и собрать сведения с передовой у всадников близ Азшары, Заставы Расщепленного Дерева и Зорамского взморья.",h="Это задание, выдаваемое Кадраком на пограничной башне между северными Степями и Ясеневым лесом, поручает...",kw={"ashenvale","barrens","kadrak","splintertree post","warsong outrider","warsong reports","warsong runner","warsong scout","zoram strand","zoram'gar outpost","ясеневый лес","степи","кадрак","застава расщепленного дерева","всадник из клана песни войны","отчет песни войны","гонец клана песни войны","разведчик клана песни войны","зорамское взморье","форт зорам'гар"},ang={["class:Hunter"]="Выслеживание на коварных дорогах Ясеневого леса проверяет навыки ориентирования и выживания в дикой местности — как среди диких хищников, так и среди скрытых эльфийских лучников.",["faction:Horde"]="Доставка этих отчетов — один из первых настоящих шагов молодого воина Орды в борьбе за территории против ночных эльфов на севере Калимдора.",["race:Orc"]="Для орков поддержка клана Песни Войны — дело клановой чести и практической необходимости: она обеспечивает бесперебойные поставки древесины для строительства Оргриммара."},sec={{t="Снабжение границы",b="Стоя на укрепленной сторожевой башне на северном краю Степей, Кадрак следит за передвижением через узкий горный каньон, ведущий в Ясеневый лес. Для Орды важно удерживать этот проход: засушливые степи не дают огромного количества древесины, нужной Оргриммару, и клан Песни Войны вынужден углубляться в древние эльфийские леса. Чтобы снабжать и согласовывать разрозненные передовые дозоры, нужны надежные гонцы, способные уходить от засад ночных эльфов на коварных лесных тропах Ясеневого леса."},{t="Глаза над Ясеневым лесом",b="Задание прочерчивает дугу через весь древний лес. На дальнем западе, на туманном берегу Зорамского взморья, гонец клана Песни Войны следит за активностью наг и угрозами с моря близ Форта Зорам'гар. Глубже в лесу, на Заставе Расщепленного Дерева, разведчик координирует оборону от постоянных набегов Часовых. Дальше на восток, по извилистой дороге к разрушенным руинам Азшары, всадник наблюдает за восточными подступами. Сведения со всех трех постов дают Кадраку целостную картину передвижений войск ночных эльфов и уязвимых мест границы."}},faq={{q="Где начинается это задание?",a="Задание начинается у Кадрака, офицера-орка в деревянной сторожевой башне, охраняющей горный проход на границе северных Степей и южного Ясеневого леса.",al={"quest giver","kadrak location","who gives the warsong reports","where to start","персонаж, выдающий задания","где кадрак","кто дает отчет песни войны","где начать"}},{q="Почему Орда шпионит в Ясеневом лесу?",a="Орда сильно зависит от густых чащ Ясеневого леса для строительства и укрепления поселений, таких как Оргриммар. Местные ночные эльфы яростно защищают свои священные рощи, превращая весь край в действующую зону боевых действий, где нужна постоянная разведка, чтобы удерживать форпосты и линии снабжения.",al={"why ashenvale","warsong lumber","ashenvale conflict","почему ясеневый лес","лес песни войны","конфликт в ясеневом лесу"}},{q="Где найти трех разведчиков клана Песни Войны?",a="Гонец клана Песни Войны находится в Форте Зорам'гар на Зорамском взморье, на дальнем северо-западе. Разведчик клана Песни Войны расквартирован на Заставе Расщепленного Дерева у главной дороги. Всадник из клана Песни Войны патрулирует восточную дорогу к границе Азшары.",al={"scout locations","where are the scouts","outrider runner scout location","где разведчики","где найти разведчиков","расположение всадника гонца разведчика"}},{q="Кто такие всадники клана Песни Войны?",a="Всадники клана Песни Войны — разведчики и налетчики орочьего клана Песни Войны. Известные яростной кавалерией и тактикой стычек, они возглавляют расширение Орды, заготовку древесины и защиту территорий в чащах Ясеневого леса.",al={"warsong clan","who are warsong outriders","warsong clan ashenvale","клан песни войны","кто такие всадники песни войны","клан песни войны ясеневый лес"}},{q="Что происходит после возвращения с отчетами?",a="Получив собранные сведения, Кадрак использует тактические данные, чтобы планировать будущие передвижения войск, усиливать уязвимые форпосты, такие как Зорам'гар и Застава Расщепленного Дерева, и закреплять присутствие Орды глубже в лесу.",al={"reports turn in","next move","what does kadrak do","сдать отчеты","следующий шаг","что делает кадрак"}},{q="Безопасна ли дорога через Ясеневый лес для гонцов низкого уровня?",a="Нет. На главной дороге через Ясеневый лес часто устраивают засады скрытные Часовые ночных эльфов, враждебные животные, такие как кошки-охотники и медведи, и патрули Альянса из таких поселений, как Астранаар.",al={"ashenvale danger","is the road safe","night elf ganks","опасность ясеневого леса","безопасна ли дорога","убийства ночных эльфов"}}},fp="19,333,18.542.0,21.568.0,30.175.0,37.290.0,44.255.0,30.242.0,41.226.0,58.210.0"}
P.entries["quest:6544"] = {n="Налет Торека",s="Налет Торека — прямой рейд Орды из глуши Ясеневого леса против близлежащего гарнизона ночных эльфов на Аванпосте Среброкрылых. Под командованием орка-налетчика Торека по приказу Заставы Расщепленного Дерева отряд стремится сломить сопротивление местных Часовых и убить их командира, Дариэль Лунное Пламя. Это одна из самых дерзких и кровавых стычек в продолжающейся войне за границы Ясеневого леса.",h="Налет Торека — прямой рейд Орды из глуши Ясеневого леса против близлежащего гарнизона ночных эльфов на...",kw={"ashenvale","duriel moonfire","ertog ragetusk","raiders","sentinels","silverwing outpost","splintertree post","torek","ясеневый лес","дариэль лунное пламя","эртог лютоклык","налетчики","часовые","аванпост среброкрылых","застава расщепленного дерева","торек"},ang={["class:Warrior"]="Жестокая лобовая рукопашная схватка, проверяющая физическую выносливость в бою с опытными лучницами-Часовыми и мастерами клинка.",["faction:Alliance"]="Гибель Дариэль Лунное Пламя обнажает Аванпост Среброкрылых и угрожает исконным лесным владениям ночных эльфов.",["faction:Horde"]="Для Орды прорыв мимо Аванпоста Среброкрылых — важное испытание силы, ослабляющее блокаду ночных эльфов вокруг Заставы Расщепленного Дерева.",["race:NightElf"]="Рейд бьет по сердцу фронтового командования Часовых, проливая эльфийскую кровь под сенью Ясеневого леса."},sec={{t="Удар из тени",b="В Ясеневом лесу идет нарастающая приграничная война между лесозаготовительными лагерями Орды и коренными ночными эльфами. Стремясь прорвать оборонительный периметр Альянса, Торек собирает отряд налетчиков с Расщепленного Дерева неподалеку от Аванпоста Среброкрылых. Не дожидаясь ответного удара, Торек организует лобовую атаку, чтобы разрушить оборону аванпоста, пока ночные эльфы не подготовили усиленную кампанию против Заставы Расщепленного Дерева."},{t="Захват Среброкрылых",b="Аванпост Среброкрылых — укрепленный лесной оплот, который охраняют бдительные Среброкрылые Часовые и свирепые эльфийские воины. Главная цель Торека — их предводительница Дариэль Лунное Пламя. Ее гибель обезглавит военную иерархию ночных эльфов в этом районе, и налетчики смогут доложить о кровавой победе командиру Эртогу Лютоклыку у Реки Фалфаррен."}},faq={{q="Кто такой Торек?",a="Торек — агрессивный орк-налетчик с Заставы Расщепленного Дерева в Ясеневом лесу. Свирепый и жаждущий битвы, он командует отрядом налетчиков, которым поручено напрямую атаковать силы ночных эльфов, окопавшиеся в лесу.",al={"torek npc","who is torek","torek orc","торек","кто такой торек","орк торек"}},{q="Что такое Аванпост Среброкрылых?",a="Аванпост Среброкрылых — укрепленное поселение ночных эльфов в Ясеневом лесу. Его охраняют элитные Часовые и воины, а сам он служит военным оплотом, следящим за передвижениями войск Орды по лесным тропам.",al={"silverwing outpost","what is silverwing","аванпост среброкрылых","что такое среброкрылые"}},{q="Кто такая Дариэль Лунное Пламя?",a="Дариэль Лунное Пламя — командир ночных эльфов, защищающая Аванпост Среброкрылых. Как глава гарнизона, она направляет местных Часовых против вторжений Орды, пока отряд Торека не прорывается в лагерь, чтобы сразить ее.",al={"duriel moonfire","duriel","дариэль лунное пламя","дариэль"}},{q="Кто такой Эртог Лютоклык?",a="Эртог Лютоклык — офицер Орды на Заставе Расщепленного Дерева. Он является начальником Торека, руководит военными операциями в регионе и принимает донесения о победах над Альянсом.",al={"ertog ragetusk","ertog","эртог лютоклык","эртог"}},{q="Почему Орда нападает на Аванпост Среброкрылых?",a="Орда и ночные эльфы ведут активную борьбу за территории по всему Ясеневому лесу. Удар по Аванпосту Среброкрылых ослабляет давление на линии снабжения Орды и напрямую подрывает сеть обороны Часовых, охраняющих глубь леса.",al={"why attack silverwing","ashenvale conflict silverwing","зачем нападать на среброкрылых","конфликт в ясеневом лесу среброкрылые"}},{q="Где происходит это нападение?",a="Налет начинается неподалеку от Аванпоста Среброкрылых, к западу от Реки Фалфаррен в Ясеневом лесу, и завершается в самом лагере ночных эльфов.",al={"torek assault location","where is torek","где налет торека","где торек"}}},fp="15,390,25.430.0,17.377.0,13.236.0,27.204.0,23.224.1,22.206.0,45.234.0,34.153.0"}
P.entries["quest:6545"] = {n="Сведения гонца клана Песни Войны",s="Сведения гонца клана Песни Войны — задание Орды по передаче сообщений, связывающее передовые рубежи Ясеневого леса с командирами на границе. Донесение, доверенное гонцам и новобранцам, описывает растущее военное давление на разведчиков Песни Войны, в частности агрессию наступающих нага.",h="Сведения гонца клана Песни Войны — задание Орды по передаче сообщений, связывающее передовые рубежи Ясеневого...",kw={"ashenvale","kadrak","mor'shan","naga","rampart","report","runner","scout","warsong","ясеневый лес","кадрак","мор'шан","нага","застава","донесение","гонец","разведчик","песнь войны"},ang={["faction:Horde"]="На лесной границе важен каждый воин: поддержание связи между Степями и передовыми аванпостами критично для выживания.",["race:Orc"]="Клан Песни Войны полагается на стойкость и бдительность своих гонцов, чтобы удерживать земли, захваченные под командованием вождя Тралла."},sec={{t="Донесения с передовой",b="Клан Песни Войны держит по всему Ясеневому лесу цепочку разведчиков и гонцов, чтобы следить за враждебными силами и поддерживать линии снабжения. Из-за стычек с Часовыми ночных эльфов и суровой местности быстрые сведения жизненно важны. Гонцы с донесениями с передовой обеспечивают согласованность действий дальних гарнизонов с командирами, такими как Кадрак на Заставе Мор'шан."},{t="Угроза нага",b="Пока Орда ждет ожесточенного сопротивления ночных эльфов среди деревьев, часовые аванпоста сообщают о все более дерзких нападениях нага. Эти змеевидные захватчики бьют из водоемов и древних руин, испытывая на прочность баррикады аванпоста и заставляя защитников отвлекаться от лесозаготовок и пограничных дозоров. Сведения, доставленные на Заставу Мор'шан, бьют тревогу из-за этих согласованных амфибийных атак."}},faq={{q="Кому отправляется донесение?",a="Донесение доставляется прямо Кадраку, надзирателю на Заставе Мор'шан на границе Ясеневого леса и северных Степей.",al={"who receives update","kadrak report","where does report go","кто получает донесение","донесение кадраку","куда идет донесение"}},{q="Какие угрозы упомянуты в сведениях?",a="Разведчик сообщает, что местный аванпост выдержал неоднократные нападения, и указывает на растущую угрозу со стороны враждебных нага, действующих в ближних водах.",al={"what is in report","runner update content","naga attacks","что в донесении","содержание сведений гонца","нападения нага"}},{q="Почему Орда полагается здесь на пеших гонцов?",a="Густая листва, меткие стрелки ночных эльфов и изолированные аванпосты делают воздушные перелеты затруднительными или опасными в некоторых частях Ясеневого леса. Наземные посыльные позволяют быстро и незаметно передавать вести по охраняемым тропам.",al={"why runners","warsong runners lore","why not wyverns","почему гонцы","гонцы песни войны","почему не наездники на виверне"}},{q="Кто такие гонцы Песни Войны?",a="Это разведчики, посыльные и бойцы авангарда клана Песни Войны, которым поручено охранять линии снабжения и следить за передвижениями врага на спорных границах леса.",al={"warsong clan ashenvale","who are warsong runners","клан песни войны ясеневый лес","кто такие гонцы песни войны"}},{q="Где нападают нага в Ясеневом лесу?",a="Нага обосновались в укрепленных руинах на берегах и озерах Ясеневого леса, часто устраивая засады на путников и нападая на соседние лагеря.",al={"where are naga","ashenvale naga","где нага","нага ясеневого леса"}},{q="Для чего нужен аванпост в этой местности?",a="Застава служит пунктом раннего оповещения и опорой обороны, не давая врагам разорвать связь между лесозаготовками в глубине леса и Степями.",al={"why is the outpost here","horde camp purpose","зачем здесь аванпост","цель лагеря орды"}}},fp="21,288,20.419.0,15.446.0,32.153.0,41.157.0,45.206.0,31.170.0,42.139.0,43.172.0"}
P.entries["quest:6546"] = {n="Сведения всадника из клана Песни Войны",s="Сведения всадника из клана Песни Войны — задание Орды на доставку, начинающееся на опасных тропах восточного Ясеневого леса. Одинокий разведчик Песни Войны доверяет искателю приключений важные сведения об угрозах со стороны Альянса, засевших рядом сатиров и наступающих нага в соседнем Азшаре.",h="Сведения всадника из клана Песни Войны — задание Орды на доставку, начинающееся на опасных тропах восточного...",kw={"ashenvale","azshara","kadrak","mor'shan rampart","naga","satyr","warsong outrider","warsong report","ясеневый лес","азшара","кадрак","застава мор'шан","нага","сатиры","всадник песни войны","отчет песни войны"},ang={["faction:Horde"]="Каждое донесение, доставленное по линии Мор'шан, укрепляет хрупкий плацдарм Орды в густых чащах Ясеневого леса.",["race:Orc"]="Клан Песни Войны гордится тем, что держит авангард, но его разведчики знают: одной храбростью не остановить врагов, окружающих со всех сторон."},sec={{t="Глаза на краю леса",b="Восточный Ясеневый лес — спорная пограничная зона, где линии снабжения Орды постоянно подвергаются нападениям. Всадники Песни Войны бдительно следят за лесом, выявляя передвижения врага задолго до того, как налетчики ударят по таким аванпостам, как Застава Мор'шан или Застава Расщепленного Дерева. Встреча со всадником в дозоре означает оказаться в гуще разведывательной деятельности, где сведения решают, удержать укрепление или потерять его в засаде."},{t="Угрозы на каждом горизонте",b="Отчет, составленный всадником, рисует мрачную тактическую картину для Орды в центральных лесах Калимдора. Помимо постоянных стычек с ночными эльфами и Альянсом в целом, восточный Ясеневый лес кишит хитрыми демоническими сатирами. Опасность усугубляется тем, что разведчики обнаружили массовое присутствие нага в разрушенных прибрежных землях соседнего Азшара: командиры предупреждены, что Орда окружена враждебными силами почти со всех сторон."}},faq={{q="Что такое Отчет Песни Войны?",a="Это разведывательное донесение, написанное всадником Песни Войны, с описанием расположения вражеских войск и опасностей региона. В нем говорится об угрозах со стороны ближайших сил Альянса, действующих шабашей сатиров в восточном Ясеневом лесу и недавно обнаруженных передвижениях нага в Азшаре.",al={"warsong report quest item","what does the report say","scout report","отчет песни войны","что сказано в отчете","донесение разведчика"}},{q="Кто такой Кадрак?",a="Кадрак — командир Орды на Заставе Мор'шан, оборонительном рубеже, охраняющем северную границу между Степями и Ясеневым лесом. Он принимает прибывающих разведчиков и координирует передовые операции в лесу.",al={"who is kadrak","where is kadrak","kadrak turn in","кто такой кадрак","где кадрак","сдать задание кадраку"}},{q="Почему упомянуты нага в Азшаре?",a="Азшара непосредственно граничит с восточным Ясеневым лесом. Всадники следят за передвижениями чужаков в соседних землях, чтобы фланги Орды не были застигнуты врасплох крупным вторжением, пока она сражается с ночными эльфами.",al={"naga azshara connection","why mention azshara","azshara naga threat","нага азшара","зачем упоминать азшару","угроза нага азшара"}},{q="Чем так опасен восточный Ясеневый лес для Орды?",a="Регион зажат между действующими отрядами Альянса, древними руинами сатиров, пропитанными демонической скверной, и дикими лесными зверями, поэтому гонцы и патрули Орды уязвимы для засад со всех сторон.",al={"why is eastern ashenvale dangerous","ashenvale threats","satyr threat","чем опасен восточный ясеневый лес","угрозы ясеневого леса","угроза сатиров"}},{q="Кто такие Всадники Песни Войны?",a="Это передовой авангард и разведывательная конница клана Песни Войны в Ясеневом лесу, отвечающие за слежку за передвижениями ночных эльфов, прикрытие лесозаготовительных лагерей и охрану торговых дорог.",al={"what are outriders","warsong scouts","outriders lore","кто такие всадники","разведчики песни войны","всадники предания"}},{q="Почему всадник не может сам доставить отчет?",a="Всаднику поручено нести дозор на тропе и отслеживать вражеские передвижения в реальном времени. Если он покинет свой наблюдательный пост, передовая не заметит внезапного наступления Альянса или сатиров.",al={"why do i deliver report","why not deliver himself","почему я доставляю отчет","почему не доставит сам"}}},fp="23,283,26.482.0,24.477.0,27.264.0,14.230.0,38.209.0,56.218.0,30.187.0,50.208.0"}
P.entries["quest:6547"] = {n="Сведения разведчика клана Песни Войны",s="Сведения разведчика клана Песни Войны — задание Орды по передаче сообщений, связывающее командиров аванпостов на границах Ясеневого леса с передовыми разведчиками, наблюдающими за спорным лесом. Доставляя стратегические приказы Кадрака, гонцы помогают клану Песни Войны вести плотное наблюдение за ночными эльфами, устраивающими засады. Оно показывает шаткую, враждебную хватку, которую Орда стремится удержать над недавно занятыми землями.",h="Сведения разведчика клана Песни Войны — задание Орды по передаче сообщений, связывающее командиров аванпостов...",kw={"ashenvale","barrens","kadrak","night elves","report","scout","sentinels","warsong","ясеневый лес","степи","кадрак","ночные эльфы","донесение","разведчик","часовые","песнь войны"},ang={["faction:Horde"]="Каждый гонец, несущий приказы между Кадраком и дальними разведчиками, помогает удержать плацдарм Орды в Ясеневом лесу против неослабевающих засад ночных эльфов.",["race:NightElf"]="Присутствие разведчиков Песни Войны на границах — это постоянное осквернение священных лесов Элуны, от которого Часовые стремятся очистить землю.",["race:Orc"]="Наследие клана Песни Войны определяется его упорством в Ясеневом лесу: он добывает ценную древесину, несмотря на враждебность земли и ее древних защитников."},sec={{t="Глаза в тени",b="Пограничье Ясеневого леса остается пороховой бочкой, где никто не уступает ни пяди. Силы Орды под началом Кадрака сильно зависят от рассредоточенных разведчиков Песни Войны на опасных аванпостах: они следят за передвижениями ночных эльфов и защищают спорные линии снабжения. Поскольку сам лес дает естественное укрытие скрытным Часовым Альянса, регулярные донесения и письменные сведения необходимы, чтобы изолированные разведчики не оказались отрезаны и разгромлены."},{t="Удержать позиции",b="Для клана Песни Войны каждый расчищенный или занятый участок леса оплачен кровью. Разведчики постоянно высматривают ответные рейды ночных эльфов, стремящихся вернуть леса. Доставка приказов Кадрака убеждает авангард, что подкрепления и координация действуют, и разведчики могут доложить, что их оборонительные меры успешны, несмотря на непрерывное сопротивление эльфов."}},faq={{q="Кто такой Кадрак?",a="Кадрак — командир Орды на границе Степей и Ясеневого леса. Он координирует разведывательные вылазки, оборону границ и тыловое обеспечение операций Песни Войны, продвигающихся в древний лес.",al={"kadrak","who is kadrak","kadrak role","кадрак","кто такой кадрак","роль кадрака"}},{q="Почему разведчики Песни Войны так опасаются ночных эльфов?",a="Ночные эльфы естественно сливаются с тенями своих исконных лесов и внезапно устраивают засады на патрули Орды. Поскольку клан Песни Войны вырубает лес и заселяет землю, которую эльфы считают священной, разведчикам постоянно грозят смертельные внезапные нападения.",al={"why fear night elves","night elves in shadows","warsong scout elven danger","почему бояться ночных эльфов","ночные эльфы в тени","опасность эльфов для разведчиков"}},{q="Почему идет борьба за Ясеневый лес?",a="Орде нужны древесина и ресурсы Ясеневого леса для строительства Оргриммара и снабжения поселений в засушливых Степях и Дуротаре. Коренные ночные эльфы считают лес священной землей и яростно борются, чтобы изгнать орочьих лесорубов и гарнизоны.",al={"why fight over ashenvale","ashenvale war","horde ashenvale conflict","почему сражаются за ясеневый лес","война за ясеневый лес","конфликт орды в ясеневом лесу"}},{q="Какова роль клана Песни Войны здесь?",a="Клан Песни Войны возглавляет расширение Орды и добычу ресурсов в Ясеневом лесу. Приведенный в лес Громом Адским Криком еще во время Третьей войны, он прочно закрепился, держит лесозаготовительные лагеря и ведет постоянные стычки с Часовыми.",al={"warsong clan ashenvale","warsong role","клан песни войны ясеневый лес","роль песни войны"}},{q="Куда идут сведения после того, как дойдут до разведчика?",a="Когда разведчик получает обновленные указания Кадрака, он посылает весть об успехах против ответных ударов эльфов, чтобы руководство Орды знало об устойчивости передовой.",al={"who gets report","kadrak report","scout update result","кто получает отчет","донесение кадраку","итог сведений разведчика"}},{q="Успешны ли на данный момент планы Орды в Ясеневом лесу?",a="Передовые разведчики считают свои оборонительные усилия успешными: им удается удерживать укрепленные позиции и отражать удары эльфов, хотя регион остается ожесточенно оспариваемым полем боя, где ни одна сторона не добилась полного господства.",al={"is horde winning ashenvale","warsong progress","побеждает ли орда в ясеневом лесу","успехи песни войны"}}},fp="20,404,19.450.0,18.405.0,14.224.0,57.279.0,35.261.0,37.283.0,51.212.0,60.242.0"}
P.entries["quest:6548"] = {n="Отомсти за мою деревню",s="Макаб Плоское Копыто едва пережил жестокое нападение, когда налетчики из клана Зловещего Тотема обрушились на его деревню на юго-востоке Когтистых гор. Отрезанный от сородичей и окруженный мертвыми, он просит путников из Орды ударить по лагерю головорезов Зловещего Тотема и наемников, чтобы отомстить за павших соплеменников.",h="Макаб Плоское Копыто едва пережил жестокое нападение, когда налетчики из клана Зловещего Тотема обрушились на...",kw={"avenge my village","grimtotem","grimtotem mercenary","grimtotem ruffian","grundig darkcloud","makaba flathoof","stonetalon mountains","отомсти за мою деревню","зловещий тотем","наемник зловещего тотема","головорез зловещего тотема","грундиг темное облако","макаба плоское копыто","когтистые горы"},ang={["faction:Horde"]="Орда зависит от открытых и безопасных проходов между Степями и Когтистыми горами. Банда Зловещего Тотема, убивающая путников и союзные деревни, угрожает линиям снабжения Вождя в горах.",["race:Tauren"]="Предательство клана Зловещего Тотема сильнее всего бьет по путникам-тауренам. Видя, как своих же собратьев шу'хало режут их сородичи, остро ощущаешь мрачную реальность раскола кланов и опасность, которую Зловещий Тотем представляет для объединенного народа Кэрна."},sec={{t="Кровь в ущельях",b="У границы между Степями и красными каменными перевалами Когтистых гор Макаба Плоское Копыто остался единственным выжившим после жестокой резни. Налетчики под темными знаменами клана Зловещего Тотема напали без предупреждения и перебили почти всех в его поселении. Макаба яростно сражался и сразил нескольких нападавших, но в конце концов был вынужден скрыться, сохранив лишь жизнь и гнев."},{t="Угроза Зловещего Тотема",b="Клан Зловещего Тотема давно стал непокорной, агрессивной занозой для племен таурен, объединенных под началом верховного вождя Кэрна Кровавого Копыта. В отличие от мирных кочевников Мулгора, отряды Зловещего Тотема часто нанимают безжалостных головорезов и жадных до наживы наемников, чтобы захватывать земли и нападать на отдаленные поселения. Для Макабы дипломатия и родство племен теперь ничего не значат: лишь кровь, отплаченная кровью, может унять его горе."}},faq={{q="Кто выдал это задание?",a="Макаба Плоское Копыто — выживший таурен, разбивший лагерь у юго-восточного прохода в Когтистые горы. Он пережил жестокое разорение своей соседней деревни кланом Зловещего Тотема и жаждет возмездия налетчикам.",al={"quest giver","makaba flathoof","who is makaba","персонаж, выдающий задания","макаба плоское копыто","кто такой макаба"}},{q="Почему Зловещий Тотем нападает на других таурен?",a="Клан Зловещего Тотема так и не принял единство Орды и мирные замыслы Кэрна Кровавого Копыта. Яростные, враждебные к чужакам и агрессивные, они открыто нападают на поселения соперников, убивают чужаков и используют вооруженных громил и наемников, чтобы утвердить власть над такими землями, как Когтистые горы.",al={"why grimtotem hostile","tauren attacking tauren","grimtotem clan lore","почему зловещий тотем враждебен","таурены нападают на таурен","предания клана зловещего тотема"}},{q="Где находятся нападавшие из клана Зловещего Тотема?",a="Головорезы и наемники Зловещего Тотема расположились в лагере к западу от Макабы Плоского Копыта на юго-востоке Когтистых гор, среди скалистых холмов над проходом.",al={"where are the mobs","grimtotem camp location","where to find ruffians","где мобы","где лагерь зловещего тотема","где найти головорезов"}},{q="Кто такие наемники Зловещего Тотема?",a="Клан Зловещего Тотема часто пополняет ряды своих воинов, нанимая безжалостных бойцов и наемников для усиления отрядов, чтобы иметь достаточно силы для устрашения и разгрома отдаленных поселений.",al={"mercenaries","grimtotem sellswords","who are the mercs","наемники","наемники зловещего тотема","кто такие наемники"}},{q="Что происходит после этого задания?",a="Расправившись с головорезами и наемниками на передовой, Макаба просит вас нанести удар по предводителю резни, Грундигу Темное Облако, в следующем задании «Убить Грундига Темное Облако».",al={"next quest","what follows avenge my village","kill grundig darkcloud","следующее задание","что после отомсти за мою деревню","убить грундига темное облако"}},{q="Где находилась деревня Макабы?",a="Поселение Макабы было уединенным лагерем таурен у пограничных проходов на юго-востоке Когтистых гор. Налет Зловещего Тотема полностью уничтожил его, и Макаба остался одним из немногих известных выживших.",al={"flathoof village","where was the village","what village was destroyed","деревня плоское копыто","где была деревня","какая деревня уничтожена"}}},fp="17,328,18.429.0,20.448.0,20.222.0,45.297.0,42.185.0,34.212.0,30.187.1,35.214.0"}
P.entries["quest:6561"] = {n="Жестокость Черных Глубин",s="«Жестокость Черных Глубин» — срочная мольба умирающего воина Серебряного Рассвета, оказавшегося в ловушке в Непроглядной Пучине. Авантюристам Орды поручено покончить с Повелителем сумрака Келрисом, предводителем культа, который устраивает жуткие кровавые жертвоприношения древнему чудовищу в руинах внизу.",h="«Жестокость Черных Глубин» — срочная мольба умирающего воина Серебряного Рассвета, оказавшегося в ловушке в...",kw={"aku'mai","argent dawn","bashana runetotem","blackfathom deeps","blackfathom villainy","kelris","moon well","thaelrid","twilight lord kelris","twilight's hammer","аку'май","серебряный рассвет","башана рунический тотем","непроглядная пучина","жестокость черных глубин","келрис","лунный колодец","талрид","повелитель сумрака келрис","сумеречный молот"},ang={["class:Druid"]="Осквернение древнего лунного колодца ночных эльфов культистами, поклоняющимися Бездне, и нагами — мучительная рана на природном и духовном убежище Калимдора.",["class:Shaman"]="Смута, посеянная Келрисом и Аку'май, оскорбляет равновесие стихий, превращая чистые подземные воды в гниющее ложе тьмы и жертвоприношений.",["faction:Horde"]="Для Орды союз с разведчиком Серебряного Рассвета — редкий миг общих интересов против космической скверны, позволяющий заслужить ранее расположение Рассвета.",["race:Tauren"]="Башана Рунический Тотем видит в поражении Келриса важную защиту Матери-Земли, очищение от мерзости, пытавшейся ввергнуть природный порядок мира в изначальный хаос."},sec={{t="Отчаянный последний бой",b="Привлеченный подземным храмом на побережье Ясеневого леса, разведчик Серебряного Рассвета Талрид обнаружил ужасы куда страшнее обычных набегов наг. Раненый и лишенный сил в пещерах, ночной эльф понимает, что не сможет завершить задачу один. Чтобы его разведданные не погибли вместе с ним, он обращается к любым проходящим героям Орды, готовым ударить по темным предводителям затопленных залов."},{t="Жертвы Глубине",b="Цель задания — Повелитель сумрака Келрис, глава культистов Сумеречного Молота, укрепившихся в разрушенном Храме Луны. В союзе с местными нагами Келрис проводит темные ритуалы над оскверненным лунным колодцем, скармливая живых пленников Аку'май — ненасытной гидре и зверю Древних богов — в безумной погоне за космической силой и изначальным хаосом."},{t="Весть в Громовой Утес",b="Серебряный Рассвет считал Келриса погибшим или пропавшим, поэтому подтверждение его смерти крайне важно. Вместо того чтобы отправлять героев обратно в земли людей, Талрид велит доставить доказательство смерти предводителя культа Башане Рунический Тотем на Вершину Старейшин в Громовом Утесе. Башана, глубоко связанная с равновесием Матери-Земли, чтит победу, уничтожившую скверну, что стремилась ввергнуть Калимдор в первобытную гибель."}},faq={{q="Кто такой Повелитель сумрака Келрис?",a="Келрис — предводитель культистов Сумеречного Молота, занявших Непроглядную Пучину. Серебряный Рассвет считал его мертвым или пропавшим, но он тайно копил силу, принося живые жертвы древней гидре Аку'май у оскверненного лунного колодца.",al={"kelris","who is kelris","twilight lord kelris","келрис","кто такой келрис","повелитель сумрака келрис"}},{q="Почему член Серебряного Рассвета оказался в Непроглядной Пучине?",a="Страж Талрид из ордена Серебряного Рассвета пришел расследовать растущую угрозу в разрушенном храме ночных эльфов. Одолеваемый обитателями пещер и смертельно ослабленный, он остался в ловушке и вынужден полагаться на заглянувших искателей приключений, чтобы завершить свой долг и устранить Келриса.",al={"argent guard thaelrid","why is thaelrid here","argent dawn in bfd","страж талрид","почему талрид здесь","серебряный рассвет в непроглядной пучине"}},{q="Кто такой Аку'май?",a="Аку'май — чудовищная древняя многоглавая гидра, считающаяся изначальным слугой Древних богов. Дремавшая под затопленными руинами, она пробудилась, когда глубинная подземная скверна осквернила священные воды храма, и теперь пожирает пленников, которых приводит Сумеречный Молот.",al={"akumai","who is akumai","aku'mai lore","аку'май","кто такой аку'май","предания об аку'май"}},{q="Почему задание нужно сдать Башане Рунический Тотем?",a="Талрид направляет героев Орды к Башане Рунический Тотем на Вершине Старейшин в Громовом Утесе. Как хранительница равновесия Матери-Земли, Башана поддерживает связь с защитниками от древнего зла и считает поклонение Келриса Древним богам омерзительной язвой на теле Калимдора.",al={"bashana runetotem","why thunder bluff","where to turn in blackfathom villainy","башана рунический тотем","почему громовой утес","где сдать жестокость черных глубин"}},{q="Что случилось с руинами Непроглядной Пучины?",a="Давным-давно подземный комплекс был священным храмом богини луны Элуны. Катастрофические потрясения и древние темные течи из недр осквернили великий лунный колодец, и наги с культистами конца света захватили затопленные святилища для своей темной владычицы Аку'май.",al={"history of blackfathom deeps","temple of elune ruins","why is bfd corrupted","история непроглядной пучины","храм элуны руины","почему непроглядная пучина осквернена"}},{q="Какова цель культа Сумеречного Молота здесь?",a="Сумеречный Молот стремится вернуть мир в эпоху изначального хаоса, поклоняясь Древним богам. Келрис ищет личной силы через темное общение, скармливая невинных глубинам ради благосклонности древних сущностей.",al={"twilight's hammer motives","why cult in bfd","kelris goals","мотивы сумеречного молота","почему культ в непроглядной пучине","цели келриса"}}},fp="20,291,22.427.0,22.381.0,21.422.1,28.273.0,54.252.0,16.279.0,43.278.0,48.281.0,52.231.0"}
P.entries["quest:6562"] = {n="Угроза из Глубин",s="«Угроза из Глубин» — призыв о помощи, отправленный из Когтистых гор к далеким берегам Ясеневого леса. Цунаман направляет искателей приключений из Орды к тролльскому ученому Дже'неу Санкри в форт Зорам'гар, предупреждая об опасных силах на побережье.",h="«Угроза из Глубин» — призыв о помощи, отправленный из Когтистых гор к далеким берегам Ясеневого леса.",kw={"ashenvale","blackfathom deeps","je'neu sancrea","stonetalon mountains","tsunaman","windshear crag","zoram strand","zoram'gar outpost","ясеневый лес","непроглядная пучина","дже'неу санкри","когтистые горы","цунаман","утес ветрорезов","зорамское взморье","форт зорам'гар"},ang={["class:Shaman"]="Смута под волнами Зорамского взморья угрожает равновесию местных духов воды и требует духовного прозрения, чтобы очистить гниль.",["faction:Horde"]="Удержание форта Зорам'гар критически важно для защиты западного фланга Калимдора как от сил ночных эльфов, так и от прибрежных ужасов.",["race:Troll"]="Отклик на зов Дже'неу Санкри дает сородичам из племени Черного Копья важную возможность помочь одному из своих выдающихся ученых в раскрытии древних тайн Калимдора."},sec={{t="Зов к побережью",b="В засушливых ущельях Когтистых гор Цунаман понимает, что темные раскаты на севере требуют внимания. Он поручает способным путникам из Орды отправиться в Ясеневый лес — исконные леса ночных эльфов — и связаться с Дже'неу Санкри. Тот несет службу в форте Зорам'гар на дальнем западном краю, известном как Зорамское взморье, и столкнулся с растущей опасностью, требующей помощи извне."},{t="Дорога к Зорамскому взморью",b="Добраться до западного берега Ясеневого леса для путников из Орды непросто. Пробираясь через проходы Утеса Ветрорезов, потревоженные гоблинами, или двигаясь на север из Степей, они должны войти во враждебный лес, который яростно охраняют стражи ночных эльфов. Далеко за густыми кронами, на омываемом штормами побережье Зорамского взморья, одинокий форт борется за выживание, вглядываясь в темные воды рядом."},{t="Шепот под волнами",b="Когда путники прибывают на берег, Дже'неу Санкри рассказывает, что беда зреет в подземном храме Непроглядной Пучины. Древняя скверна, мерзкие водные элементали и культисты Сумеречного Молота собрались под приливами, маня древнее зло обратно в мир. Дже'неу рассчитывает, что герои спустятся под воду и сразятся с изначальным ужасом, пробужденным в затопленных залах."}},faq={{q="Кто выдает задание «Угроза из Глубин»?",a="Задание выдает Цунаман, находящийся в Когтистых горах. Он понимает, что союзникам на побережье Ясеневого леса нужно подкрепление, и направляет путешествующих искателей приключений из Орды к морю.",al={"quest giver","who starts trouble in the deeps","tsunaman","персонаж, выдающий задания","кто начинает угрозу из глубин","цунаман"}},{q="Где находится Дже'неу Санкри?",a="Дже'неу Санкри несет службу в форте Зорам'гар на Зорамском взморье, на дальнем западном побережье Ясеневого леса.",al={"where is je'neu","jeneu sancrea location","zoram'gar outpost","где дже'неу","дже'неу санкри местонахождение","форт зорам'гар"}},{q="Как добраться до форта Зорам'гар из Когтистых гор?",a="Путники могут отправиться на северо-восток через Утес Ветрорезов в Ясеневый лес или обойти с востока через Степи и войти в лес с юга. Из центра Ясеневого леса идите строго на запад до открытых вод Зорамского взморья.",al={"path to ashenvale","how to get to zoram strand","stonetalon to ashenvale route","путь в ясеневый лес","как добраться до зорамского взморья","маршрут из когтистых гор в ясеневый лес"}},{q="Какую беду расследует Дже'неу?",a="Дже'неу Санкри наблюдает за соседними руинами Непроглядной Пучины, где культисты и оскверненные водные существа пробуждают древние ужасы под поверхностью.",al={"what is happening at zoram strand","why does jeneu need help","что происходит на зорамском взморье","зачем дже'неу нужна помощь"}},{q="Какое задание следует за «Угрозой из Глубин»?",a="Разговор с Дже'неу Санкри ведет прямо к заданию «Сущность Аку'май», которое отправляет искателей приключений в Непроглядную Пучину за сапфировой сущностью элементаля.",al={"next quest","trouble in the deeps follow up","следующее задание","продолжение угрозы из глубин"}},{q="Почему путь через Ясеневый лес считается опасным?",a="Ясеневый лес — суверенные владения ночных эльфов, яростно сопротивляющихся любому вторжению Орды. Путники в лесу рискуют наткнуться на враждебных стражей и неуловимых нападающих из засады.",al={"ashenvale danger","night elf threat","опасность ясеневого леса","угроза ночных эльфов"}}},fp="20,265,22.435.0,24.425.0,24.420.1,41.195.0,32.121.0,51.230.0,37.161.0,40.162.0,57.194.0"}
P.entries["quest:6563"] = {n="Сущность Аку'май",s="Дже'неу Санкри из форта Зорам'гар заметил, что наги из Непроглядной Пучины добывают в пещерах мощные скопления сапфиров. Встревоженный их магическими свойствами и энергией стихии воды, шаман поручает авантюристам Орды забрать самоцветы, пока их не использовали во зло.",h="Дже'неу Санкри из форта Зорам'гар заметил, что наги из Непроглядной Пучины добывают в пещерах мощные...",kw={"ashenvale","blackfathom deeps","je'neu sancrea","naga","sapphire of aku'mai","trouble in the deeps","water spirits","zoram strand","ясеневый лес","непроглядная пучина","дже'неу санкри","наги","сапфиры аку'май","угроза из глубин","духи воды","зорамское взморье"},ang={["class:Shaman"]="Прочтение кристаллов Дже'неу Санкри выявляет беспокойных духов воды, заключенных в них, — тонкое предупреждение о том, что стихийные силы под храмом извращаются.",["faction:Horde"]="Плацдарм Орды в форте Зорам'гар опасен; не давая местным нагам получить сырую магическую силу, вы помогаете защитить прибрежный лагерь.",["race:Troll"]="Дже'неу Санкри — наблюдательный мистик из племени Черного Копья, который полагается на общение с духами и мудрость предков, чтобы справляться со странными угрозами Калимдора."},sec={{t="Угроза в глубинах",b="На окутанных туманом берегах Зорамского взморья шаман из племени Черного Копья Дже'неу Санкри наблюдает за древними руинами кальдораев, захваченными зловещими силами. В затопленных залах Непроглядной Пучины наги начали добывать яркие сапфировые образования, растущие на отсыревших стенах пещер. Чувствуя, что змеевидные захватчики стремятся подчинить эту непостоянную силу, Санкри хочет перехватить добычу, пока их замыслы не осуществились."},{t="Духи воды и тайная сила",b="Сапфиры Аку'май — гораздо больше, чем обычные самоцветы: они вибрируют стихийным резонансом и хранят в себе духов воды. В руках опытных чародеев такие проводники могли бы питать опасные тайные ритуалы или усиливать влияние теневой гидры Аку'май, чье темное присутствие пронизывает подземный храм. Забрав эти скопления, вы лишите нагов ценнейшего реагента и убережете побережье от неукротимой стихийной магии."}},faq={{q="Кто выдает это задание?",a="Задание выдает Дже'неу Санкри, шаман-тролль из племени Черного Копья, находящийся в форте Зорам'гар на Зорамском взморье на северо-западе Ясеневого леса.",al={"quest giver","who starts essence of akumai","jeneu sancrea location","персонаж, выдающий задание","кто начинает сущность аку'май","где дже'неу санкри"}},{q="Зачем нагам сапфиры Аку'май?",a="Их замысел до конца неясен, но сапфиры обладают мощной энергией стихии воды и сырой магической силой, что делает их крайне опасными реагентами для заклинаний нагов.",al={"why do naga want sapphires","what are the crystals for","sapphire purpose","зачем нагам сапфиры","для чего кристаллы","назначение сапфиров"}},{q="Где находятся скопления сапфиров?",a="Они покрывают стены и пол пещер во внешних туннелях и затопленных проходах Непроглядной Пучины, сразу за разрушенным подземным входом на Зорамском взморье.",al={"where to find sapphires","sapphire of akumai location","crystal spawns","где найти сапфиры","сапфир аку'май где","кристаллы где брать"}},{q="Кто такой Аку'май?",a="Аку'май — чудовищная трехглавая гидра, обитающая в глубине затопленных руин храма. Ее почитают культисты Сумеречного Молота, и ее боятся как излюбленной питомицы Древних богов.",al={"who is akumai","what is akumai","aku'mai","кто такой аку'май","что такое аку'май","аку'май"}},{q="Нужно ли для этого задания убивать боссов подземелья?",a="Нет. Скопления сапфиров растут на стенах пещер в первых затопленных туннелях, до встречи с главными боссами Непроглядной Пучины.",al={"do i need a full group","can i solo sapphires","boss requirement","нужна ли полная группа","можно ли в одиночку","требования к боссам"}},{q="Связано ли это задание с другими сюжетными линиями?",a="Да. Оно следует за заданием «Угроза из Глубин» и входит в расследование Дже'неу Санкри о растущей тьме и деятельности культистов в Непроглядной Пучине.",al={"quest chain","prerequisites","trouble in the deeps","цепочка заданий","предыдущие задания","угроза из глубин"}}},fp="22,287,22.461.0,30.455.0,21.143.0,46.181.0,38.169.0,16.183.0,52.144.0,47.168.0"}
P.entries["quest:6564"] = {n="Верность Древним богам",s="«Верность Древним богам» — задание Орды, которое начинается с находки отсыревшего послания у нагов в Непроглядной Пучине. Доставка записки Дже'неу Санкри в форт Зорам'гар раскрывает зловещий замысел ритуала в затопленных руинах Непроглядной Пучины.",h="«Верность Древним богам» — задание Орды, которое начинается с находки отсыревшего послания у нагов в...",kw={"aku'mai","allegiance","ashenvale","blackfathom deeps","damp note","je'neu sancrea","lorgus jett","old gods","wrathscale","zoram'gar outpost","аку'май","верность","ясеневый лес","непроглядная пучина","отсыревшая записка","дже'неу санкри","лоргус джетт","древние боги","наги","форт зорам'гар"},ang={["class:Shaman"]="Порабощение нагами духов воды в ритуальных кристаллах — тяжкое извращение естественного равновесия, требующее скорейшего исправления.",["faction:Horde"]="Найденная записка Лоргуса Джетта помогает защитить форт Зорам'гар от Сумеречного Молота и его союзников-нагов, угрожающих плацдарму Орды на западном побережье Ясеневого леса.",["race:Troll"]="Помогая сородичу из племени Черного Копья Дже'неу Санкри, вы разоблачаете древние космические сущности, возвращение которых грозило бы всем племенам Азерота."},sec={{t="Наспех нацарапанное заявление",b="Сражаясь с нагами Непроглядной Пучины, разведчики Орды находят отсыревшую смятую записку, написанную торопливым почерком. В ней содержатся указания жрицам нагов собирать кристаллы стихии воды. Это не просто грабеж: кристаллы собирают для призыва наг-аквамантов, чтобы собрать стихийные силы ради куда более мрачной цели."},{t="Шепот глубин",b="Найденные приказы раскрывают, что наги намерены использовать энергию стихий в кристаллах, чтобы умилостивить и полностью призвать Аку'май, чудовищную гидру, любимую древними космическими владыками. В записке дерзко провозглашается, что это возвестит возвращение «величайшей эпохи» мира — доисторического владычества Древних богов. Получив пергамент в форте Зорам'гар, мистик из племени Черного Копья Дже'неу Санкри называет автора заговора: культиста Сумеречного Молота Лоргуса Джетта."}},faq={{q="Что такое «Отсыревшая записка»?",a="«Отсыревшая записка» — найденные приказы, написанные культистом Сумеречного Молота Лоргусом Джеттом. В них жрицам нагов велено собирать кристаллы, наполненные стихиями, чтобы усилить их аквамантов и призвать чудовищного слугу Аку'май.",al={"damp note","what does the note say","note lore","отсыревшая записка","что сказано в записке","предыстория записки"}},{q="Кто такой Дже'неу Санкри?",a="Дже'неу Санкри — тролль из племени Черного Копья, провидец и ученый, находящийся в форте Зорам'гар в Ясеневом лесу. Представляя Служителей Земли, он исследует стихийные нарушения и древние угрозы, поднимающиеся из соседних руин Непроглядной Пучины.",al={"jeneu sancrea","who is jeneu","zoram outpost questgiver","дже'неу санкри","кто такой дже'неу","выдающий задания в зорам'гар"}},{q="Кто такой Лоргус Джетт?",a="Лоргус Джетт — человек-шаман из культа Сумеречного Молота, действующий в Непроглядной Пучине, где культисты заключили союз с нагами. Он руководит добычей стихийных кристаллов, чтобы усилить ритуалы нагов и пробудить темные древние ужасы.",al={"lorgus jett","who wrote the note","naga leader zoram","лоргус джетт","кто написал записку","предводитель нагов зорам"}},{q="Что такое Аку'май?",a="Аку'май — колоссальная трехглавая гидра, обитающая в затопленных глубинах Непроглядной Пучины. Тесно связанное с первозданной тьмой Древних богов, это существо почитают и культ Сумеречного Молота, и наги Непроглядной Пучины.",al={"akumai","who is akumai","aku'mai lore","аку'май","кто такой аку'май","аку'май предыстория"}},{q="Зачем наги собирают кристаллы воды?",a="Духи стихии воды, заточенные в кристаллах, дают нагам-аквамантам сырую силу. Высасывая эту стихийную магию, наги надеются умилостивить Аку'май и накопить достаточно силы, чтобы возвестить возвращение Древних богов.",al={"why naga crystals","elemental crystals naga","aquamancer crystals","зачем нагам кристаллы","стихийные кристаллы нагов","кристаллы аквамантов"}},{q="Куда ведет эта цепочка заданий?",a="Доставка записки Дже'неу Санкри ведет прямо к следующему поручению: выследить и убить Лоргуса Джетта, чтобы сорвать ритуальные планы культа в Непроглядной Пучине.",al={"what comes after allegiance to the old gods","allegiance to the old gods part 2","next quest","что после верности древним богам","верность древним богам часть 2","следующее задание"}}},fp="26,282,23.413.0,20.494.1,22.235.0,22.236.0,19.248.0,16.251.0,43.226.0,33.186.1"}
P.entries["quest:6565"] = {n="Верность Древним богам",s="«Верность Древним богам» — задание Орды: нужно уничтожить Лоргуса Джетта в глубинах Непроглядной Пучины. По поручению провидца из племени Черного Копья Дже'неу Санкри в форте Зорам'гар вам предстоит сорвать планы культистов Сумеречного Молота, стремящихся пробудить древние силы разрушения. Убийство Лоргуса наносит прямой удар по подрывной деятельности культа под побережьем Ясеневого леса.",h="«Верность Древним богам» — задание Орды: нужно уничтожить Лоргуса Джетта в глубинах Непроглядной Пучины.",kw={"allegiance to the old gods","ashenvale","blackfathom deeps","je'neu sancrea","lorgus jett","old gods","twilight's hammer","zoram'gar","верность древним богам","ясеневый лес","непроглядная пучина","дже'неу санкри","лоргус джетт","древние боги","сумеречный молот","зорам'гар"},ang={["class:Shaman"]="Сумеречный Молот стремится выпустить стихийную ярость на службе хаотичных Древних богов, поэтому для тех, кто поклялся хранить стихийное равновесие вместе со Служителями Земли, их истребление — первоочередная задача.",["faction:Horde"]="Убийство Лоргуса Джетта обезопасит окрестности форта Зорам'гар и защитит уединенный прибрежный лагерь Орды в Ясеневом лесу от коварных замыслов культистов.",["race:Troll"]="Помощь Дже'неу Санкри — дань мудрости уважаемого провидца из племени Черного Копья, который далеко от Островов Эха трудится ради защиты изначальных духов Азерота."},sec={{t="Угроза под фортом Зорам'гар",b="На взморье Ясеневого леса застава Орды в Зорам'гар настороженно следит за Непроглядной Пучиной. Затопленный храмовый комплекс стал рассадником темного колдовства, захваченным нагами, оскверненными тварями и фанатиками Сумеречного Молота в плащах. Дже'неу Санкри, провидец Служителей Земли на побережье, понимает, что культисты не чтят ни равновесие природы, ни духов земли. Они клянутся в верности Древним богам — чудовищным владыкам хаоса, побежденным в давние эпохи, чье злое касание все еще ощущается в забытых местах Азерота."},{t="Конец Лоргуса Джетта",b="Дже'неу поручает защитникам Орды проникнуть в подземные руины и выследить Лоргуса Джетта, важного предводителя культистов. Лоргус действует в глубине каменных коридоров между залами гигантской черепахи Гхаму-ра и водного элементаля барона Акваниса. Сам Дже'неу слишком слаб, чтобы идти в сырую тьму, поэтому убийство Лоргуса необходимо, чтобы прервать темные ритуалы, которые культист замышлял под волнами Ясеневого леса."},{t="Сдерживание хаоса",b="После смерти Лоргуса Джетта непосредственная ритуальная угроза побережью устранена, но Дже'неу признает, что Сумеречный Молот далеко не истреблен. Тихое проникновение культа в древние святыни говорит о более широкой, подкрадывающейся угрозе, цель которой — не меньше чем полное возвращение Древних богов. Для Орды в Зорам'гар смерть Лоргуса выигрывает ценное время в борьбе с врагом, скрывающимся в тенях мира."}},faq={{q="Кто такой Лоргус Джетт?",a="Лоргус Джетт — видный предводитель культистов Сумеречного Молота в Непроглядной Пучине. Он направляет ритуалы культа, призванные возвестить возвращение и владычество Древних богов.",al={"lorgus jett","who is lorgus","lorgus jett lore","лоргус джетт","кто такой лоргус","лоргус джетт предыстория"}},{q="Где в Непроглядной Пучине можно найти Лоргуса Джетта?",a="Лоргус Джетт обходит затопленные коридоры Непроглядной Пучины, в частности соединяющие залы между покоями Гхаму-ра и местом алтаря барона Акваниса.",al={"lorgus jett location","where is lorgus","find lorgus jett","где лоргус джетт","где лоргус","найти лоргуса джетта"}},{q="Кто такой Дже'неу Санкри?",a="Дже'неу Санкри — тролль-провидец из племени Черного Копья, связанный со Служителями Земли. Он находится в форте Зорам'гар на Зорамском взморье в Ясеневом лесу и следит за стихийными возмущениями и скверной в Непроглядной Пучине.",al={"je'neu sancrea","who gives allegiance to the old gods","jeneu","дже'неу санкри","кто выдает верность древним богам","дже'неу"}},{q="Почему Дже'неу заботит Сумеречный Молот?",a="Как провидец, стремящийся понять природу и стихийное равновесие, Дже'неу видит в Сумеречном Молоте смертельную угрозу. Культ служит Древним богам, хаотичным древним сущностям, чье возвращение разрушило бы гармонию мира.",al={"why fight twilight hammer","earthen ring old gods","зачем бороться с сумеречным молотом","служители земли древние боги"}},{q="Кто такие Древние боги?",a="Древние боги — первозданные существа хаоса и разрушения, правившие Азеротом в глубокой древности, пока не были побеждены и погребены. Культ Сумеречного Молота поклоняется им и замышляет разрушить их печати и вернуть их разрушительное владычество.",al={"old gods lore","who are old gods","creatures of chaos","предания о древних богах","кто такие древние боги","существа хаоса"}},{q="Почему Дже'неу Санкри не может сам убить Лоргуса Джетта?",a="Дже'неу признает, что слишком слаб, чтобы в одиночку встретить опасности Непроглядной Пучины, и полагается на способных защитников Орды, а сам следит за духовными и стихийными возмущениями из форта.",al={"why jeneu doesnt go","is jeneu weak","почему дже'неу не идет","слаб ли дже'неу"}}},fp="26,413,28.592.0,18.482.0,17.443.1,19.195.0,52.170.0,22.217.0,49.232.0,22.254.0,50.224.0"}
P.entries["quest:6571"] = {n="Поставка для Песни Войны",s="Поставка для Песни Войны — масштабное снабженческое задание Орды, которое выдает Локе Окарр на Заставе Расщепленного Дерева. Чтобы Лесозаготовки Песни Войны продолжали работу, нужно вернуть важное лесозаготовительное снаряжение, разбросанное по враждебным землям фурболгов и сатиров, а также получить грузы, прибывающие из далеких гоблинских портов.",h="Поставка для Песни Войны — масштабное снабженческое задание Орды, которое выдает Локе Окарр на Заставе...",kw={"ashenvale","booty bay","locke okarr","logging rope","pixel","saw blades","splintertree post","warsong lumber camp","warsong oil","warsong supplies","ясеневый лес","пиратская бухта","локе окарр","погрузочная веревка","пиксель","пилы","застава расщепленного дерева","лесозаготовки песни войны","масло песни войны","поставка для песни войны"},ang={["faction:Horde"]="Расширение Орды в Дуротаре целиком зависит от древесины, добываемой кланом Песни Войны. Возвращение этих инструментов напрямую укрепляет основу Оргриммара.",["profession:Engineering"]="Гоблинские детали этой поставки показывают, какая важная механическая цепочка снабжения нужна для вырубки древних лесов — от пил Пиксель до смазки для паровых двигателей.",["race:Orc"]="Чтить наследие клана Песни Войны в Ясеневом лесу — значит держать их топоры острыми, а лагеря снабженными, несмотря на постоянные нападения лесных обитателей."},sec={{t="Пилы должны вращаться",b="Кампания клана Песни Войны по заготовке древней древесины Ясеневого леса требует нескончаемого потока тяжелых инструментов. На своем аванпосту — Заставе Расщепленного Дерева — интенданты Орды постоянно сталкиваются с перебоями в снабжении. Локе Окарр отвечает за полное оснащение лесозаготовок, но местные поставки сорваны из-за набегов местных зверей и демонических культистов, и работа осталась без жизненно важного снаряжения."},{t="Разрозненная цепочка снабжения",b="Securing the needed equipment is an ordeal spanning much of Kalimdor and extending even across the sea. While circular saw blades await collection from the goblin courier Pixel right in Splintertree Post, the crate of heavy axes requires picking up a delivery from Wharfmaster Lozgil down in Booty Bay. The remaining essential goods must be ripped directly from enemy hands: sturdy logging ropes seized by hostile Foulweald and Thistlefur furbolgs, and barrels of Warsong machinery oil stolen by the satyrs of Night Run, Satyrnaar, and Xavian to fuel their profane rituals."}},faq={{q="Какие предметы входят в поставку для Песни Войны?",a="Locke Okarr needs four essential items: a shipment of Warsong Saw Blades held by the goblin Pixel, a crate of Warsong Axes shipped to Booty Bay, heavy Logging Rope looted by local furbolgs, and barrels of Warsong Oil stolen by Ashenvale's satyrs.",al={"warsong supplies list","what items needed","supplies needed","поставка для песни войны список","какие предметы нужны","что нужно собрать"}},{q="Кто такой Локе Окарр?",a="Локе Окарр — орк, находящийся на Заставе Расщепленного Дерева и отвечающий за координацию поставок материалов для Лесозаготовок Песни Войны. Под сильным давлением из-за необходимости избежать задержек он нанимает странствующих искателей приключений из Орды, чтобы вернуть разбросанные грузы.",al={"locke okarr lore","who gives warsong supplies","splintertree quest giver","локе окарр предания","кто выдает поставку для песни войны","персонаж на заставе расщепленного дерева"}},{q="Почему Орда получает снаряжение из Пиратской бухты?",a="Орда полагается на нейтральные торговые сети, такие как Картель Хитрая Шестеренка, чтобы ввозить специальные изделия, которые Дуротар и Степи не могут легко выпускать в больших количествах. Прочные лесорубные топоры, заказанные через гоблинов, проходят через морские торговые центры вроде Пиратской бухты, прежде чем попасть в Ясеневый лес.",al={"why booty bay","booty bay axe shipment","steamwheedle tools","почему пиратская бухта","топоры из пиратской бухты","инструменты хитрой шестеренки"}},{q="Зачем сатирам масло Песни Войны?",a="Сатиры, обитающие в таких руинах, как Сатирнаар, Ночная поляна и Ксавиан, используют украденное промышленное масло не для механизмов, а для темных, оскверненных обрядов, посвященных Пылающему Легиону и распространяющейся порче Оскверненного леса.",al={"satyr oil lore","why do satyrs have oil","warsong oil rituals","масло сатиров","зачем сатирам масло","ритуалы с маслом песни войны"}},{q="Какие фурболги украли погрузочную веревку?",a="Погрузочную веревку захватили из засады племена фурболгов Гиблой Чащи и Колючего Меха. Оба племени питают яростную враждебность к вырубке леса Ордой в Ясеневом лесу, считая эти земли своей территорией.",al={"who stole the rope","furbolg rope lore","foulweald thistlefur rope","кто украл веревку","веревка фурболгов","гиблая чаща колючий мех веревка"}},{q="Почему Лесозаготовки Песни Войны так важны для Орды?",a="Засушливые земли Дуротара почти не дают пригодной для строительства древесины. Клан Песни Войны был направлен в цветущие пограничные земли Ясеневого леса именно для заготовки огромных деревьев, необходимых для строительства Оргриммара и развития растущей военной инфраструктуры Орды.",al={"why harvest ashenvale","warsong lumber importance","orcs cutting trees","зачем рубить ясеневый лес","важность лесозаготовок песни войны","орки рубят деревья"}}},fp="16,290,25.415.0,27.573.0,39.246.0,19.252.0,51.303.0,35.229.0,38.197.0,53.269.0"}
P.entries["quest:6581"] = {n="Пилы Песни Войны",s="Пилы Песни Войны — поручение Орды, выполняемое на Заставе Расщепленного Дерева для лесозаготовительной кампании клана Песни Войны. Чтобы получить тяжелые пилы, привезенные из Кабестана, искателям приключений нужно заключить тайную сделку с курьером Пиксель, которая требует личной защиты, прежде чем отдать груз. Выполнив ее условие, вы получите важное оборудование, необходимое, чтобы лесопилки Орды в Ясеневом лесу продолжали работать.",h="Пилы Песни Войны — поручение Орды, выполняемое на Заставе Расщепленного Дерева для лесозаготовительной...",kw={"ashenvale","deadly blunderbuss","pixel","ratchet","splintertree post","warsong outriders","warsong saw blades","warsong supplies","ясеневый лес","смертоносный мушкетон","пиксель","кабестан","застава расщепленного дерева","пилы песни войны","поставка для песни войны"},ang={["faction:Horde"]="Лесозаготовки в Ясеневом лесу составляют жизненно важный каркас для расширения Оргриммара, поэтому каждая поставка оборудования необходима для выживания Орды в Калимдоре.",["profession:Engineering"]="Смертоносный мушкетон, который требует Пиксель, — обычное изделие умелых мастеров, показывающее, как гоблинская и людская инженерия обеспечивает снабжение на передовой.",["race:Orc"]="Клан Песни Войны поставил свою гордость на лесозаготовки в Ясеневом лесу под началом Громмаша Адского Крика; поддержание работы промышленных пил чтит неизменное присутствие клана в лесу."},sec={{t="Хитрая сделка курьера",b="Лесорубы Песни Войны в Ясеневом лесу целиком зависят от привозного тяжелого оборудования, чтобы справляться с древней древесиной глубокого леса. Пиксель благополучно доставила на Заставу Расщепленного Дерева партию специальных пил прямо из гоблинского порта Кабестан, но отдавать их просто так не собирается. В опасных глухих местах Ясеневого леса монеты стоят не так уж много, а личная безопасность — гораздо больше. Вместо золота Пиксель требует обменять тяжелые пилы на надежный Смертоносный мушкетон, чтобы защитить себя в опасных поездках по вражеской территории."},{t="Снабжение для военных усилий",b="Густые кроны Ясеневого леса высоко ценятся Ордой, которая страдает от острой нехватки древесины на засушливых равнинах Дуротара и в Степях. Однако рубка древних рощ-стражей быстро тупит обычные топоры, поэтому гоблинские промышленные лезвия необходимы. Груз Пиксель напрямую питает работу лесозаготовок Песни Войны, позволяя Орде и дальше строить аванпосты и боевые машины, несмотря на ожесточенное сопротивление ночных эльфов."}},faq={{q="Кто такая Пиксель и почему у нее пилы?",a="Пиксель — курьер, находящаяся сейчас на Заставе Расщепленного Дерева, которая привезла партию промышленных пил прямо из гоблинского порта Кабестан. Она удерживает груз, пока не получит надежное оружие для собственной защиты.",al={"who is pixel","pixie splintertree","saw blade courier","кто такая пиксель","пиксель застава расщепленного дерева","курьер с пилами"}},{q="Почему Пиксель хочет Смертоносный мушкетон вместо золота?",a="Путь через Степи и вглубь земель ночных эльфов в Ясеневом лесу крайне опасен. Зная об опасностях дороги, Пиксель ставит личную защиту выше денег и требует огнестрельное оружие инженерной работы, чтобы обезопасить свои поездки.",al={"why deadly blunderbuss","pixel gun trade","why want a gun","зачем смертоносный мушкетон","обмен пиксель на оружие","зачем ей ружье"}},{q="Почему эти пилы так важны для Орды?",a="Орде нужны огромные объемы древесины для строительства укреплений и боевых машин по всему Калимдору. Обычные режущие инструменты быстро изнашиваются о древние железные деревья Ясеневого леса, поэтому привозные механические пилы жизненно важны для лесозаготовительной техники клана Песни Войны.",al={"why are saw blades needed","warsong lumber importance","why warsong supplies","зачем нужны пилы","важность лесозаготовок песни войны","зачем поставка для песни войны"}},{q="Откуда изначально взялись пилы?",a="Пилы изготовили в Кабестане — нейтральном гоблинском порту на восточном побережье Степей — и оттуда отправили, а затем довезли по суше до Заставы Расщепленного Дерева.",al={"origin of saw blades","ratchet blades","where did saw blades come from","происхождение пил","пилы кабестан","откуда пилы"}},{q="Какое место это задание занимает в лесозаготовках Песни Войны?",a="Это задание — часть более широких усилий по сбору поставки для Песни Войны для лесозаготовок в Ясеневом лесу. Получение пил от Пиксель закрывает одно из ключевых требований снабжения, необходимых для поддержания лесозаготовок Орды.",al={"warsong supplies chain","warsong saw blades prerequisite","цепочка поставки для песни войны","пилы песни войны предыдущее задание"}},{q="Может ли кто-нибудь сделать оружие, которое хочет Пиксель?",a="Смертоносный мушкетон создают умелые инженеры из медных трубок, медных болтов, деревянного ложа и кожи, хотя курьеры и воины часто выменивают их на местных рынках или у других искателей приключений.",al={"how to get deadly blunderbuss","blunderbuss source","engineering gun","как получить смертоносный мушкетон","где взять мушкетон","инженерное ружье"}}},fp="18,421,25.614.0,24.461.0,50.244.0,57.244.0,51.275.0,46.173.0,58.237.0,39.210.0"}
P.entries["quest:66"] = {n="Легенда о Сталване",s="Легенда о Сталване начинается в Темнолесье с мрачного видения городской предсказательницы, Мадам Евы. Встревоженная предзнаменованием смерти своей внучки Алиссы, Ева обращается к картам и видениям в трансе и угадывает лишь одно оставшееся имя: Сталван. Чтобы распутать эту нить ужаса, она посылает путников изучить городские записи в Ратуше Темнолесья.",h="Легенда о Сталване начинается в Темнолесье с мрачного видения городской предсказательницы, Мадам Евы.",kw={"alyssa","clerk daltry","darkshire","death card","duskwood","madame eva","stalvan","town hall","алисса","клерк далтри","темнолесье","карта смерти","сумеречный лес","мадам ева","сталван","ратуша"},ang={["class:Priest"]="Жрецы, идущие по темным дорогам Темнолесья, часто прислушиваются к духовным предостережениям, поэтому жуткие предзнаменования смерти Мадам Евы становятся для них неотложным делом пастырского долга.",["faction:Alliance"]="Пока Сумеречный лес справляется без регулярной поддержки армии Штормграда, искатели приключений Альянса часто приходят на помощь городским старейшинам и защищают уязвимые семьи, такие как семья Мадам Евы."},sec={{t="Видение смерти",b="В вечном сумраке Сумеречного леса Мадам Ева служит провидицей Темнолесья: толкует знамения и гадает на картах встревоженным местным жителям. Резко проснувшись от ужасного потрясения, Ева обратилась к колоде для гадания и вытянула карту Смерти, связанную с ее юной внучкой Алиссой. Погрузившись в глубокий мрачный транс, чтобы пронзить мрак, она получила лишь одну подсказку: имя Сталван. Испуганная тем, что это знамение значит для ее семьи и города, она обращается к способным искателям приключений, чтобы они пошли по следу, пока не случилась беда."},{t="Расспросы в Ратуше",b="Ева знает, что для раскрытия правды о Сталване нужно изучить письменную историю Темнолесья. Она отправляет искателей приключений через площадь в Ратушу Темнолесья к Клерку Далтри, городскому хранителю книг учета и общественных архивов. Далтри ведает пыльными документами поселения, и только он может определить, был ли Сталван бывшим жителем, проезжим путником или чем-то гораздо более зловещим, похороненным в прошлом Сумеречного леса."}},faq={{q="Кто такая Мадам Ева?",a="Мадам Ева — гадалка и предсказательница, живущая в Темнолесье. Она использует карты и обряды транса, чтобы заглянуть в знамения будущего, и чувствует магические возмущения, перемещающиеся по Сумеречному лесу.",al={"madame eva","who is eva","darkshire fortune teller","мадам ева","кто такая ева","гадалка темнолесья"}},{q="Почему Мадам Еве нужна помощь?",a="Мадам Ева пережила ужасающее видение, указывающее, что ее внучке Алиссе грозит смертельная опасность. Карты выдали карту Смерти, а в трансе она узнала лишь имя «Сталван», поэтому она ищет помощи со стороны, чтобы разобраться с угрозой.",al={"why start stalvan","eva vision","why help eva","зачем начинать легенду о сталване","видение евы","почему помочь еве"}},{q="Кто такой Клерк Далтри?",a="Клерк Далтри — городской хранитель записей, находящийся в Ратуше Темнолесья. Он ведет городские книги учета, реестры и исторические документы, поэтому лучше всех подходит для вопросов о незнакомых именах.",al={"clerk daltry","daltry","who is town clerk","клерк далтри","далтри","кто городской клерк"}},{q="Что такое Ратуша Темнолесья?",a="Ратуша Темнолесья — административный центр города, в котором располагаются чиновники местной власти, исторические записи и командный состав Ночного Дозора.",al={"darkshire town hall","town hall duskwood","ратуша темнолесья","ратуша сумеречного леса"}},{q="Кто такая Алисса?",a="Алисса — юная внучка Мадам Евы, живущая в Темнолесье. Гадание Евы показало, что Алиссе грозит смертельное предзнаменование, связанное с неким Сталваном.",al={"alyssa","madame eva granddaughter","алисса","внучка мадам евы"}},{q="Куда ведет это расследование дальше?",a="Разговор с Клерком Далтри открывает городские записи и прошлые расследования и начинает обширное расследование в Сумеречном лесу и соседних землях, чтобы выяснить историю и судьбу Сталвана.",al={"stalvan next step","what does daltry say","сталван следующий шаг","что говорит далтри"}}},fp="21,363,17.562.0,22.470.0,18.192.0,30.244.0,20.208.0,28.162.0,14.163.0,40.181.0"}
P.entries["quest:6608"] = {s="«Больше учить нечему» — задание Орды, которое выдает наставник по рыбной ловле Оргриммара Лумак, когда рыболов перерос обычное обучение. Лумак отправляет своего искусного ученика к своему другу-человеку Нату Пэглу, который разбил лагерь на уединенном берегу Пылевых топей. Это переход от обычного обучения к непростому искусству рыбной ловли ранга искусника.",h="«Больше учить нечему» — задание Орды, которое выдает наставник по рыбной ловле Оргриммара Лумак, когда...",kw={"artisan fishing","dustwallow marsh","lumak","nat pagle","orgrimmar","theramore","you too good","рыбная ловля искусника","пылевые топи","лумак","нат пэгл","оргриммар","терамор","больше учить нечему"},ang={["faction:Horde"]="Это задание показывает, что за войной фракций отдельные личности порой завязывают дружбу между сторонами на почве безобидного ремесла и общих увлечений.",["race:Orc"]="Даже в воинственной твердыне Оргриммара Лумак доказывает, что терпение, хороший юмор и глубокое уважение к природе помогают оркам заводить друзей по ту сторону фронта."},sec={{t="Пределы Лумака",b="Лумак — главный наставник по рыбной ловле в Оргриммаре, в Аллее Чести, но даже терпеливый орк понимает, когда ученик сравнялся с ним в знании удочки и катушки. Не притворяясь, что ему есть чему еще научить, Лумак честно признает, что рыболов стал «слишком хорош» для обычных уроков. Чтобы достичь звания мастера, нужно выйти за городские стены и за пределы расовых границ."},{t="Неожиданная дружба",b="Несмотря на тлеющую вражду Орды и Альянса в Калимдоре, рыбалка часто сближает там, где пасует дипломатия. Лумак направляет путников к своему личному знакомому, Нату Пэглу, настойчиво подчеркивая, что человека нельзя ни обижать, ни есть. Нат разбил лагерь на островке к югу от острова Терамор в Пылевых топях и охотно игнорирует политику, пока рыба клюет."}},faq={{q="Кто посылает меня на это задание?",a="Лумак, наставник по рыбной ловле, живущий у воды в Аллее Чести в Оргриммаре, выдает вам это задание, когда ваше умение рыбной ловли достаточно высоко, чтобы продвинуться дальше уровня эксперта.",al={"who starts you too good","lumak quest giver","where to get you too good","кто дает больше учить нечему","лумак выдает задание","где взять больше учить нечему"}},{q="Где находится Нат Пэгл?",a="Нат Пэгл обосновался на островке у побережья Пылевых топей, к югу от человеческого поселения на острове Терамор.",al={"where is nat pagle","nat pagle location","find nat pagle","где нат пэгл","нат пэгл местонахождение","найти ната пэгла"}},{q="Почему у орка есть друг-человек?",a="Рыболовов по всему Азероту часто объединяет взаимное уважение, выходящее за рамки войны фракций. Лумак и Нат Пэгл сблизились исключительно на почве рыбалки, признав страсть друг друга вопреки жестокой вражде орков и людей.",al={"lumak and nat pagle friendship","why is nat pagle friends with an orc","дружба лумака и ната пэгла","почему нат пэгл дружит с орком"}},{q="Что будет, если я поговорю с Натом Пэглом?",a="Разговор с Натом Пэглом знакомит вас с его трудным испытанием для мастеров: вам придется пройти по всему Азероту, ловя редкую рыбу, прежде чем он лично продолжит ваше обучение.",al={"what does nat pagle teach","artisan fishing quest","чему учит нат пэгл","задание рыбная ловля искусника"}},{q="Безопасно ли Орде проходить через Терамор?",a="Нет, Терамор — город-крепость, строго охраняемый Альянсом. Искателям приключений из Орды приходится обходить город или идти вдоль берега, чтобы добраться до острова Ната и не навлечь гнев стражей Терамора.",al={"can horde go through theramore","getting to nat pagle as horde","может ли орда пройти через терамор","как добраться до ната пэгла за орду"}},{q="Почему Лумак сам не может учить меня дальше?",a="Лумак передал вам все, что знал. Истинное мастерство в рыбной ловле требует знаний Ната Пэгла, которого считают самым легендарным рыболовом известного мира.",al={"why lumak stops training","expert to artisan fishing horde","почему лумак перестает учить","рыбная ловля умелец искусник орда"}}},fp="13,350,14.413.0,22.406.0,27.165.0,27.118.0,36.227.0,39.176.0,44.197.0,41.164.0"}
P.entries["quest:6611"] = {n="Ступай в Прибамбасск!",s="«Ступай в Прибамбасск!» — путь поваров Орды, которые хотят выйти за пределы возможностей наставников своей столицы. По указанию Замджи в Оргриммаре начинающие повара отправляются на юг Калимдора, в Танарис, на поиски эксцентричного гоблина-мясника Могиля Быстроруба. Это задание знаменует переход к настоящему мастерству в кулинарном искусстве.",h="«Ступай в Прибамбасск!» — путь поваров Орды, которые хотят выйти за пределы возможностей наставников своей...",kw={"artisan cooking","cooking","dirge quikcleave","gadgetzan","orgrimmar","tanaris","valley of strength","zamja","кулинария искусника","кулинария","могиль быстроруб","прибамбасск","оргриммар","танарис","аллея силы","замджа"},ang={["faction:Horde"]="Оргриммар полагается на сторонних специалистов, например нейтральных гоблинов-поваров, чтобы поднять своих мастеров выше обычных племенных блюд.",["profession:Cooking"]="Это задание отмечает рубеж, когда повар перерастает обучение в столице и должен отправиться в опасные дикие земли, чтобы учиться у мастера."},sec={{t="Повар перерастает Оргриммар",b="В Тракте тролльша-повар Замджа кормит бесчисленных воинов и путников, идущих через красные каньоны Дуротара. Но когда усердный повар усваивает все рецепты и приемы Замджи, мастер признает свое поражение. Передав всю свою кулинарную магию, она отправляет опытного ученика на юг, в пески Танариса, признавая, что лишь настоящий знаток странного и экзотического мяса способен продвинуть талантливого повара дальше."},{t="Мясник в пустыне",b="Цель — Прибамбасск, паровой торговый центр, которым управляет Картель Хитрая Шестеренка. Там, в шумной городской таверне, трудится Могиль Быстроруб. Гоблин с необычным вкусом и полным отсутствием кулинарной брезгливости, Могиль известен по всему Калимдору тем, что готовит из чудовищной пустынной фауны — а порой и из обрезков кожи — сытные блюда, способные поддержать закаленных искателей приключений."}},faq={{q="Кто посылает вас в Прибамбасск?",a="Замджа, тролльша — наставник по кулинарии уровня эксперта, стоящая у костров для готовки в Тракте в Оргриммаре, дает это задание поварам, освоившим все, что она знает.",al={"quest giver","who starts this","zamja quest","персонаж, выдающий задания","кто дает это задание","задание замджи"}},{q="Почему Замджа отправляет вас прочь?",a="Замджа исчерпала все рецепты и кулинарные приемы, которым могла научить. Чтобы достичь ранга искусника в кулинарии, она направляет перспективных поваров к Могилю Быстрорубу в Танарисе — эксцентричному знатоку, известному умением готовить съедобные блюда из самых скудных пустынных ингредиентов.",al={"why gadgetzan","why dirge quikcleave","cooking master","почему прибамбасск","почему могиль быстроруб","мастер кулинарии"}},{q="Кто такой Могиль Быстроруб?",a="Могиль Быстроруб — гоблин-мясник и наставник по кулинарии ранга искусника, которого можно найти в таверне Прибамбасска. Он славится крутым нравом, странными теориями о питании — например, будто белок есть в старых кожаных сапогах, — и мастерством в изысканной экзотической кухне дикой природы.",al={"who is dirge","dirge gadgetzan","кто такой могиль","могиль прибамбасск"}},{q="Обязательно ли это задание для изучения кулинарии ранга искусника?",a="Нет. Это задание лишь направляет игроков Орды в Танарис. Повар с достаточным умением может сразу отправиться в Прибамбасск и поговорить с Могилем Быстрорубом, не получая направления от Замджи.",al={"do i need this quest","breadcrumb cooking","is it mandatory","нужно ли это задание","кулинария направление","обязательно ли"}},{q="Где находится Прибамбасск?",a="Прибамбасск — обнесенный стеной пустынный поселок Картеля Хитрая Шестеренка в северных песках Танариса, далеко на юге континента Калимдор, ниже Тысячи Игл.",al={"gadgetzan location","where is dirge","прибамбасск местонахождение","где могиль"}},{q="Учится ли Замджа чему-нибудь, когда вы возвращаетесь?",a="Хотя Замджа дерзко требует, чтобы вы вернулись и научили ее, когда станете главным поваром на районе, она остается наставником-экспертом в Оргриммаре и следит за своими кострами для следующих поколений путников.",al={"does zamja learn cooking","teach zamja","учится ли замджа кулинарии","научить замджу"}}},fp="20,356,25.422.0,25.395.0,27.158.0,29.269.0,24.267.0,48.224.0,27.179.0,51.206.0"}
P.entries["quest:6621"] = {n="Король Гиблой Чащи",s="«Король Гиблой Чащи» — военная операция Орды по поручению Каранга Амаккара из форта Зорам'гар. Чтобы усмирить порченых фурболгов Гиблой Чащи к юго-востоку от Астранаара, чемпионы Орды водружают боевое знамя прямо на священном тотемном кургане племени, вызывая и убивая его вождя, вождя Мургута.",h="«Король Гиблой Чащи» — военная операция Орды по поручению Каранга Амаккара из форта Зорам'гар.",kw={"ashenvale","foulweald","furbolg","greenpaw village","karang amakkar","murgut","totem mound","zoram'gar","ясеневый лес","гиблая чаща","фурболг","деревня зеленой лапы","каранг амаккар","мургут","тотемный курган","зорам'гар"},ang={["class:Shaman"]="Искаженные тотемы и агрессия племени Гиблой Чащи отражают сохраняющийся духовный разлад, терзавший местные племена Ясеневого леса после вторжения Пылающего Легиона.",["faction:Horde"]="Каранг Амаккар демонстрацией военного превосходства запугивает враждебные племена Ясеневого леса, обеспечивая безопасный проход для караванов снабжения Орды по центральным тропам.",["race:Orc"]="Водрузить знамя, чтобы вызвать вражеского вождя на поединок, — классическая орочья война: упор на силу и решительное столкновение, а не на долгие стычки."},sec={{t="Демонстрация силы",b="Пока ночные эльфы пытаются сдержать порченые местные племена Ясеневого леса, Орда подходит к угрозе с расчетливой агрессией. Каранг Амаккар из форта Зорам'гар понимает, что племя Гиблой Чащи, возможно, и не равно по численности северному племени Колючего Меха, но его необузданная свирепость — скрытая опасность для южной дороги. Не дожидаясь засад на патрули Орды, Каранг приказывает упреждающе продемонстрировать военное превосходство, чтобы сломить волю племени."},{t="Осквернение и вызов",b="Удар нацелен на Деревню Зеленой Лапы к северо-востоку от Озера Мистраль. Каранг изготавливает племенное боевое знамя, которое нужно вбить прямо в центр тотемного кургана Гиблой Чащи, — непростительное оскорбление предков-духов и гордости племени. Защитники-фурболги в отчаянии бросаются на курган, чтобы сорвать оскорбительное знамя, и вынуждают вождя Мургута выйти и защищать свою честь в открытом бою. Захват личного тотема Мургута разрушает их руководство и утверждает превосходство Орды в этих землях."}},faq={{q="Кто приказывает убить вождя Мургута?",a="Каранг Амаккар, орк из форта Зорам'гар на западном побережье Ясеневого леса, отдает это задание после изучения соседних фурболгов племени Колючего Меха.",al={"quest giver king of the foulweald","who gives king of the foulweald","karang amakkar quest","персонаж, выдающий задание король гиблой чащи","кто дает король гиблой чащи","задание каранга амаккара"}},{q="Где находится Деревня Зеленой Лапы?",a="Деревня Зеленой Лапы лежит к юго-востоку от поселения ночных эльфов Астранаар, к северо-востоку от Озера Мистраль, чуть южнее главной восточной дороги Ясеневого леса.",al={"where is greenpaw village","foulweald location","where to plant karang banner","где деревня зеленой лапы","гиблая чаща местонахождение","где установить знамя каранга"}},{q="Зачем Орда водружает знамя на тотемном кургане?",a="Водружение Знамени Каранга прямо на священном тотемном кургане племени — намеренная провокация. Осквернение священной земли заставляет племя Гиблой Чащи яростно напасть и вынуждает вождя Мургута открыто сражаться, защищая свое положение.",al={"why place banner","totem mound banner purpose","why challenge murgut","зачем ставить знамя","назначение знамени на кургане","зачем вызывать мургута"}},{q="Кто такие фурболги Гиблой Чащи?",a="Племя Гиблой Чащи — одно из нескольких племен фурболгов Ясеневого леса, впавших в безумие и порчу после Третьей войны. Хотя оно малочисленнее племени Колючего Меха, оно остается свирепым и враждебным к чужакам.",al={"what are the foulweald","foulweald tribe lore","who is chief murgut","что такое гиблая чаща","предания племени гиблой чащи","кто такой вождь мургут"}},{q="Что дает возвращение Тотема Мургута?",a="Доставка тотема вождя Мургута в форт Зорам'гар доказывает поражение вождя. Лишившись предводителя и с оскверненным священным курганом, уцелевшие фурболги Гиблой Чащи устрашены и избегают дальнейших столкновений с Ордой.",al={"murgut totem purpose","what happens after murgut dies","назначение тотема мургута","что будет после смерти мургута"}},{q="Как это задание связано с прежними расследованиями о фурболгах?",a="Это задание непосредственно продолжает задание «Между молотом и Колючим Мехом». Разобравшись с северным племенем Колючего Меха, Каранг обращает внимание на юг, чтобы упредить удар и сокрушить племя Гиблой Чащи, пока оно не начало согласованные набеги.",al={"between a rock and a thistlefur connection","prerequisite king of the foulweald","связь с between a rock and a thistlefur","предыдущее задание король гиблой чащи"}}},fp="21,312,15.490.0,25.511.0,37.180.0,34.158.0,53.240.0,31.222.0,47.227.0,64.229.0"}
P.entries["quest:6625"] = {n="Травматологи Альянса",s="«Травматологи Альянса» — вызов, направляющий опытных полевых медиков на Остров Терамор в Пылевых топях. Инструкторы первой помощи в столицах Альянса приглашают умелых целителей учиться у доктора Густава ван Склиффа, главного врача элитного медицинского корпуса Альянса.",h="«Травматологи Альянса» — вызов, направляющий опытных полевых медиков на Остров Терамор в Пылевых топях.",kw={"alliance trauma","dustwallow marsh","first aid","ironforge","nissa firestone","theramore","triage","vanhowzen","травматологи альянса","пылевые топи","первая помощь","стальгорн","нисса огневик","терамор","сортировка","ван склифф"},ang={["faction:Alliance"]="Травматологи Альянса обеспечивают бойцов на передовой по всему Калимдору и Восточным королевствам умелыми полевыми медиками, способными стабилизировать тяжелые ранения под огнем.",["race:Dwarf"]="Наставники вроде Ниссы Огневик в Стальгорне охотно отбирают перспективных целителей из Великой кузни, чтобы те представляли лучшие медицинские таланты Альянса в Тераморе."},sec={{t="Зов на передовую",b="Когда медик осваивает основные приемы, которым учат в великих городах Альянса, местные наставники уже мало что могут ему дать. Об тех, кто проявил исключительные способности в обращении с иглой, тканью и сортировкой, сообщают непосредственно доктору Густаву ван Склиффу. Из пограничной крепости на Острове Терамор он руководит Травматологами Альянса — организацией, призванной спасать жизни в самых жестоких зонах боевых действий Калимдора и за его пределами."},{t="Дорога в Терамор",b="Наставники вроде Ниссы Огневик в Стальгорне считают личный вызов от ван Склиффа исключительной привилегией. Остров Терамор постоянно страдает от региональных угроз, стычек и суровой природы, поэтому туда стабильно поступают тяжелораненые солдаты. Чтобы добраться до клиники ван Склиффа, нужно долгое морское путешествие в Пылевые топи, где лишь самые хладнокровные полевые хирурги могут надеяться выдержать его строгие требования к сортировке."}},faq={{q="Что такое Травматологи Альянса?",a="Травматологи Альянса — элитное медицинское подразделение, отвечающее за передовую полевую медицину и экстренную сортировку во всем Альянсе. Корпус возглавляет главный врач Густав ван Склифф и занимается тяжелыми ранениями, которые не под силу обычной полевой перевязке.",al={"alliance trauma lore","who are alliance trauma","травматологи альянса предания","кто такие травматологи альянса"}},{q="Кто посылает вас на это задание?",a="Инструкторы первой помощи Альянса, например Нисса Огневик в Великой кузне Стальгорна, направляют перспективных целителей, как только те достигают вершины обычной гражданской подготовки.",al={"who gives alliance trauma","ironforge first aid quest giver","кто дает травматологов альянса","персонаж, выдающий задание первой помощи в стальгорне"}},{q="Куда нужно отправиться?",a="Вам нужно отправиться в портовую крепость людей на Острове Терамор, расположенную у восточного побережья Пылевых топей на континенте Калимдор.",al={"where is vanhowzen","alliance trauma destination","где ван склифф","цель травматологов альянса"}},{q="Кто такой доктор Густав ван Склифф?",a="Доктор Густав ван Склифф — главный врач Травматологов Альянса. Он работает в военной клинике Терамора и считается одним из ведущих специалистов Альянса по неотложной медицине и хирургической сортировке.",al={"gustaf vanhowzen","chief physician vanhowzen","густав ван склифф","главный врач ван склифф"}},{q="Что происходит после встречи с доктором ван Склиффом?",a="По прибытии в Терамор ван Склифф подвергает кандидатов напряженной практической проверке сортировки: нужно спасти волны умирающих солдат, прежде чем их допустят в высшие ряды полевой медицины.",al={"what comes after alliance trauma","triage quest next","что после травматологов альянса","следующее задание сортировка"}},{q="Почему клиника находится в Тераморе, а не в Штормграде или Стальгорне?",a="Терамор — действующий пограничный гарнизон, окруженный враждебными болотами, опасными зверями и спорными территориями. Постоянный приток тяжелораненых делает его идеальной площадкой для интенсивного обучения травматологии.",al={"why theramore clinic","why dustwallow for trauma","почему клиника в тераморе","почему пылевые топи для травматологии"}}},fp="15,307,19.448.0,21.468.0,24.252.0,28.178.0,28.143.0,31.221.0,49.217.0,71.240.0"}
P.entries["quest:6627"] = {n="Испытание знаний",s="«Испытание знаний» — проверка ума и исторической памяти, которую устраивает отшельник Брауг Тусклый Дух в Когтистых горах. Добыв древний том «Наследие Аспектов», путники должны показать знание древней истории, ответив на вопрос Брауга. Тех, кто не усвоил текст, внезапно изгоняют в другую часть Калимдора.",h="«Испытание знаний» — проверка ума и исторической памяти, которую устраивает отшельник Брауг Тусклый Дух в...",kw={"aspects","braug dimspirit","earth warder","neltharion","stonetalon","taurajo","test of faith","weathered nook","аспекты","брауг тусклый дух","хранитель земли","нелтарион","когтистые горы","таурахо","испытание веры","угол семи ветров"},ang={["class:Mage"]="Маги сочтут защитное заклинание телепортации Брауга одновременно впечатляющим и карающим: оно показывает, что отшельники Когтистых гор владеют древней магией и наказывают небрежных ученых.",["faction:Horde"]="Испытания Орды в Калимдоре требуют не только грубой силы: от воинов и шаманов ждут понимания древних шрамов и мощи драконов, сформировавших континент.",["race:Tauren"]="Это испытание воплощает уважение таурен к мудрости предков и древней истории: молодые защитники не должны слепо идти вперед, не зная равновесия мира."},sec={{t="Испытание мудрости",b="Испытание знаний — часть более широкой цепочки испытаний, начатой Дорном Вольным Ловчим в Углу Семи Ветров. Оно переносит акцент с боевого выживания и слепого доверия на понимание древнего прошлого мира. Брауг Тусклый Дух, живущий среди скал Когтистых гор, требует, чтобы искатели добыли древние тексты и по-настоящему усвоили заключенные в них знания."},{t="Наследие Аспектов",b="Урок посвящен созданию и разделению Аспектов драконов, в частности роковому союзу, заключенному задолго до Великого Раскола. Брауг проверяет, что искатель помнит о Хранителе Земли Нелтарионе, чье погружение в безумие и предательство изменило облик Азерота. Тем, кто не чтит историю, путь мудрости закрыт."},{t="Цена догадок",b="Брауг не терпит праздных догадок. Искателя, давшего неверный ответ, мистическим образом изгоняют, и он оказывается за много миль оттуда, в Лагере Таурахо на юге Степей. Чтобы вернуть себе положение, нужно проделать долгий путь обратно в Когтистые горы и во второй раз предстать перед пристальным взором отшельника."}},faq={{q="Каков ответ на вопрос Брауга Тусклого Духа?",a="Брауг спрашивает о личности Хранителя Земли, описанного в томе «Наследие Аспектов». Правильный ответ — Нелтарион, Черный Аспект, который позже обратился против собратьев-драконов.",al={"braug question answer","test of lore answer","legacy of the aspects question","ответ на вопрос брауга","ответ испытание знаний","вопрос наследие аспектов"}},{q="Что будет, если ответить неверно?",a="Если назвать Браугу неверное имя, вас немедленно изгонят магией и перенесут прямо в Лагерь Таурахо в Степях. Чтобы повторить испытание, придется пройти весь путь обратно к его жилищу в Когтистых горах.",al={"wrong answer test of lore","failed test of lore","teleported to taurajo","неверный ответ испытание знаний","провал испытания знаний","телепорт в таурахо"}},{q="Кто такой Брауг Тусклый Дух?",a="Брауг Тусклый Дух — старый отшельник, живущий в Когтистых горах. Он проводит для Орды проверки знаний и преданий, продолжая цепочку духовных испытаний, начатую в Тысяче Игл.",al={"braug dimspirit","who gives test of lore","брауг тусклый дух","кто дает испытание знаний"}},{q="Как это связано с испытаниями в Тысяче Игл?",a="Цепочка началась с Дорна Вольного Ловчего в Углу Семи Ветров в Тысяче Игл с «Испытания веры». Дорн проверяет физическое и духовное доверие, а затем отправляет достойных посвященных по Калимдору, чтобы другие мудрые старейшины проверили их ум, решимость и силу.",al={"dorn plainstalker connection","test of faith chain","дорн вольный ловчий","цепочка испытание веры"}},{q="О какой книге Брауг задает вопросы?",a="Вопросы проверяют понимание «Наследия Аспектов» — древнего трактата о благословении титанами пяти великих Аспектов драконов, призванных охранять Азерот.",al={"what book braug","legacy of the aspects","какая книга у брауга","наследие аспектов"}},{q="Куда ведет эта цепочка заданий дальше?",a="Успешный ответ на вопросы Брауга об Аспектах драконов ведет к дальнейшим исследовательским испытаниям по древней истории, где искателям нужно обшаривать дальние земли в поисках утраченных записей и знаний предков.",al={"what is after test of lore","next quest in test of lore","что после испытания знаний","следующее задание испытания знаний"}}},fp="12,361,17.381.0,21.371.0,22.317.1,49.193.0,39.226.0,23.203.0,56.265.0,38.171.0,38.192.0"}
P.entries["quest:6628"] = {n="Испытание знаний",s="Это испытание — интеллектуальная проверка в более широкой череде духовных испытаний, начинающихся в Тысяче Игл. Обыскав мир в поисках исторических текстов, посвященные являются к Парквелу Финталласу в Подгороде, чтобы доказать, что понимают мрачные страницы истории, сформировавшие Азерот.",h="Это испытание — интеллектуальная проверка в более широкой череде духовных испытаний, начинающихся в Тысяче...",kw={"dorn plainstalker","lich king","mark of shame","nerzhul","parqual fintallas","test of lore","thousand needles","undercity","weathered nook","дорн вольный ловчий","король-лич","метка позора","нер'зул","парквел финталлас","испытание знаний","тысяча игл","подгород","угол семи ветров"},ang={["faction:Horde"]="Испытание укрепляет связи между племенами Калимдора и королевством под Лордероном, напоминая героям, что мудрость для выживания Орды так же важна, как и грубая сила.",["race:Tauren"]="Это испытание, идущее от традиций старейшин, побуждает путешественников-тауренов узнать мрачную историю их северных союзников, Отрекшихся, и мира за пределами Калимдора.",["race:Undead"]="Тема испытания затрагивает самую суть самосознания Отрекшихся: трагедию создания Нер'зула и возникновение проклятия, что сковывало их, пока Сильвана не разорвала хватку Короля-лича."},sec={{t="Испытание знаний",b="Хотя многие испытания Орды проверяют воинскую силу или выносливость, Испытание знаний требует усердия ученого. Путь начинается с духовных упражнений Дорна Вольного Ловчего в Углу Семи Ветров и уводит кандидатов далеко от изрезанных ветрами каньонов Тысячи Игл в сумрачные залы Подгорода. Экзаменатором выступает Парквел Финталлас, строго проверяющий знание истории."},{t="Происхождение Плети",b="Чтобы удовлетворить Парквела, посвященный должен изучить «Истоки угрозы нежити» — текст о проклятом происхождении Плети в Лордероне. Главный вопрос экзамена касается происхождения существа, правящего на Ледяном Троне: бывшего старейшины-шамана Нер'зула, чью сущность Пылающий Легион превратил в Короля-лича. Знание этой мрачной родословной считается необходимым для понимания существования Отрекшихся и опасностей, грозящих Калимдору и Восточным королевствам."}},faq={{q="Каков ответ на вопрос Парквела?",a="Парквел Финталлас спрашивает, как звали Короля-лича изначально. Правильный ответ — Нер'зул, древний орк-шаман, чей дух был прикован к Ледяному Трону.",al={"lich king answer","parqual question","test of lore answer","ответ король-лич","вопрос парквела","ответ испытание знаний"}},{q="Что будет, если ответить неправильно?",a="Неверный ответ накладывает на вас ослабляющий эффект «Метка позора», и придется дождаться окончания штрафа, прежде чем Парквел позволит вам пройти экзамен снова.",al={"mark of shame","wrong answer test of lore","метка позора","неверный ответ испытание знаний"}},{q="Где начинается эта цепочка заданий?",a="Все испытание начинается с Дорна Вольного Ловчего в Углу Семи Ветров, среди высоких скал Тысячи Игл.",al={"where does test of lore start","dorn plainstalker questline","где начинается испытание знаний","цепочка заданий дорна вольного ловчего"}},{q="Где находится Парквел Финталлас?",a="Парквел Финталлас обитает в Подгороде, среди подземных библиотек и коридоров Отрекшихся, где проверяет будущих учеников.",al={"find parqual","parqual fintallas location","найти парквела","где парквел финталлас"}},{q="На каком тексте основано это испытание?",a="Испытание основано на томе «Истоки угрозы нежити», где рассказывается о происхождении Чумы нежизни и создании Короля-лича.",al={"which book for test of lore","beginnings book","какая книга для испытания знаний","книга истоки"}},{q="Почему задание из Тысячи Игл отправляет игроков в Подгород?",a="Испытания тауренов призваны проверить все стороны искателя приключений. Чтобы проверить знания, кандидатов отправляют за море на поиски ученых записей, сохранившихся в руинах Лордерона.",al={"why go to undercity","thousand needles undercity","зачем идти в подгород","тысяча игл подгород"}}},fp="12,297,20.430.0,21.495.1,41.162.0,46.165.0,34.130.0,35.155.0,33.152.0,60.208.0"}
P.entries["quest:6629"] = {n="Убить Грундига Темное Облако",s="Убить Грундига Темное Облако — задание Орды, которое выдает Макаба Плоское Копыто на юго-восточной тропе в Когтистых горах. После расправы над разбойниками и наемниками Зловещего Тотема Макаба велит вам сразить предводителя, разорившего его дом, — Грундига Темное Облако. Гибель Грундига и его головорезов приносит справедливое возмездие за разоренное поселение.",h="Убить Грундига Темное Облако — задание Орды, которое выдает Макаба Плоское Копыто на юго-восточной тропе в...",kw={"brute","darkcloud","flathoof","grimtotem","grundig","makaba","post","stonetalon","головорез","темное облако","плоское копыто","зловещий тотем","грундиг","макаба","застава","когтистые горы"},ang={["faction:Horde"]="Когтистые горы — ключевая территория для расширения Орды в Калимдоре, а агрессивные вожди Зловещего Тотема вроде Грундига угрожают путям снабжения, соединяющим Степи с Приютом у Солнечного Камня.",["race:Tauren"]="Клан Зловещего Тотема продолжает сеять раздор среди тауренов, и резня Грундига показывает, что единству под знаменем Орды всегда будет противостоять их беспощадный экстремизм."},sec={{t="Мясник тропы",b="Макабе Плоскому Копыту удалось пережить внезапное жестокое нападение на его поселение на тропе в Когтистых горах, но его горе все еще свежо. Испытав вашу силу на пехотинцах Зловещего Тотема, он указывает вам на зачинщика кровопролития — Грундига Темное Облако. В отличие от простых налетчиков, Грундиг командует преданным отрядом головорезов и возглавил резню, сровнявшую деревню с землей."},{t="Удар по Заставе Зловещего Тотема",b="Грундиг разбил лагерь на Заставе Зловещего Тотема, дальше по горной дороге на западе. Чтобы отомстить за сородичей Макабы и защитить перевал от нового насилия, путникам нужно подняться в крепость, прорубиться через ближний круг головорезов Темного Облака и покончить с самим Грундигом, пока его отряд не обрушился на другие беззащитные лагеря."}},faq={{q="Кто такой Грундиг Темное Облако?",a="Грундиг Темное Облако — свирепый командир Зловещего Тотема, обосновавшийся на Заставе Зловещего Тотема на юго-востоке Когтистых гор. Он лично спланировал и возглавил жестокое нападение, уничтожившее деревню Макабы Плоского Копыта.",al={"grundig darkcloud","who is grundig","grimtotem leader","грундиг темное облако","кто такой грундиг","вождь зловещего тотема"}},{q="Где найти Грундига Темное Облако?",a="Грундиг Темное Облако находится на Заставе Зловещего Тотема, расположенной на горной тропе к западу от лагеря Макабы Плоского Копыта, неподалеку от границы Степей.",al={"grundig location","where is grundig","grimtotem post location","где грундиг","где найти грундига","застава зловещего тотема"}},{q="Почему Макаба Плоское Копыто дает это задание?",a="Макаба видел, как Зловещий Тотем перебил его сородичей и разорил дом. Уже отомстив их разбойникам и наемникам, он просит голову главаря, Грундига Темное Облако, чтобы обрести истинное завершение и возмездие.",al={"why kill grundig","makaba story","makaba revenge","зачем убивать грундига","история макабы","месть макабы"}},{q="Почему Зловещий Тотем нападает на мирные поселения здесь?",a="Клан Зловещего Тотема яростно презирает остальные племена тауренов, особенно тех, кто стал союзником Орды или выбрал более мягкие пути. Засады, набеги и грубая жестокость — их обычные средства, чтобы изгнать соперничающие кланы с земель, которыми они хотят владеть.",al={"why grimtotem attack","grimtotem hostility","почему нападает зловещий тотем","враждебность зловещего тотема"}},{q="Что будет после убийства Грундига Темное Облако?",a="Убийство Грундига Темное Облако и его головорезов завершает короткую цепочку мести Макабы Плоского Копыта. Со смертью мясника Макаба наконец может оплакать свою деревню, зная, что справедливость восторжествовала.",al={"what next after grundig","flathoof chain continuation","что дальше после грундига","продолжение цепочки макабы"}},{q="Какое задание нужно выполнить перед этим?",a="Сначала нужно выполнить задание «Отомсти за мою деревню», в котором Макаба Плоское Копыто проверяет вашу решимость, веля сразить разбойников и наемников Зловещего Тотема, расположившихся неподалеку к западу.",al={"prereq kill grundig","quest before grundig","предыдущее задание грундиг","задание перед грундигом"}}},fp="22,363,23.418.0,24.351.0,25.209.0,37.160.0,47.245.0,58.260.0,43.191.0,45.178.0"}
P.entries["quest:6641"] = {n="Ворша Хлестунья",s="Ворша Хлестунья — свирепая гидра, терроризирующая оплот Орды, Форт Зорам'гар, на побережье Ясеневого леса. Почитая ярость этого существа, местные наги держат на прибрежном острове жертвенную жаровню в ее честь. Погасив это священное пламя, герои Орды разъярят Воршу и выманят ее на берег, чтобы положить конец ее хищным нападениям.",h="Ворша Хлестунья — свирепая гидра, терроризирующая оплот Орды, Форт Зорам'гар, на побережье Ясеневого леса.",kw={"ashenvale","brazier","hydra","muglash","naga","vorsha","zoram strand","zoram'gar","ясеневый лес","жаровня","гидра","муглаш","нага","ворша","зорамское взморье","зорам'гар"},ang={["faction:Horde"]="Оборона Форта Зорам'гар необходима, чтобы удерживать северный логистический плацдарм в Ясеневом лесу, где пути снабжения постоянно подвергаются нападениям.",["race:Orc"]="Орки вроде Муглаша не прячутся за наспех сколоченными частоколами, а предпочитают выходить в прибой и встречать хищных чудовищ лицом к лицу."},sec={{t="Ужас из глубин",b="Форт Зорам'гар стоит на узкой полосе побережья на северо-западе Ясеневого леса, постоянно подвергаясь осаде враждебных зверей, ночных эльфов и змеевидных захватчиков. Среди самых разрушительных угроз Зорамского взморья — Ворша Хлестунья, гигантская гидра, известная жестокими нападениями на форт без всякого повода. Чудовище выходит из прибоя, сокрушает укрепления, убивает воинов и скрывается в глубоких водах."},{t="Жаровня нага",b="Местные наги не просто терпят прожорливую гидру — они почитают ее хищную злобу. На скалистом выступе у берега змеевидные порождения зла постоянно поддерживают огонь в жертвенной жаровне в дар Ворше. Муглаш, орк, решивший прекратить постоянные нападения на форт, понял, что осквернение этого ритуального пламени заставит чудовище в ярости подняться на поверхность, и защитники смогут заманить его в засаду, а не ждать очередной внезапной бойни."}},faq={{q="Кто такая Ворша Хлестунья?",a="Ворша Хлестунья — свирепая огромная гидра, обитающая в водах у Зорамского взморья. Она часто нападает на Форт Зорам'гар без повода, разрушая защитные сооружения и убивая людей Орды.",al={"vorsha","what is vorsha","vorsha hydra","ворша","кто такая ворша","гидра ворша"}},{q="Почему наги почитают Воршу?",a="Наги Зорамского взморья уважают Воршу за ее неукротимую свирепость и разрушительный аппетит. Они держат на острове у берега жаровню, горящую в честь ее злобной натуры, и видят в чудовище воплощение дикой ярости побережья.",al={"why naga like hydra","vorsha naga brazier","why worship vorsha","почему наги любят гидру","ворша наги жаровня","почему поклоняться ворше"}},{q="Как выманить Воршу на бой?",a="Муглаш ведет штурм острова, где наги поддерживают огонь в жаровне Ворши. Погасив священное пламя, вы глубоко разъярите и стражей-нагов, и саму гидру, и Ворша поднимется из моря, чтобы отомстить.",al={"how to summon vorsha","how do you call vorsha","brazier island vorsha","как призвать воршу","как вызвать воршу","остров жаровни ворша"}},{q="Кто такой Муглаш?",a="Муглаш — орк, служащий в Форте Зорам'гар. Устав жить в страхе перед беспричинными набегами Ворши на побережье, он придумал план погасить ритуальную жаровню нагов и сразиться с чудовищем вместе с надежными союзниками.",al={"who is muglash","muglash orc","zoramgar muglash","кто такой муглаш","орк муглаш","зорам'гар муглаш"}},{q="Почему Форт Зорам'гар уязвим для прибрежных чудовищ?",a="Форт Зорам'гар — изолированный и открытый пограничный лагерь прямо на берегу Ясеневого леса. Наги господствуют в руинах в море, а дикие гидры патрулируют прибой, поэтому близость воды делает его уязвимым для нападений со всех сторон.",al={"why is zoramgar attacked","zoram strand danger","почему нападают на зорам'гар","опасность зорамского взморья"}},{q="Что происходит после гибели Ворши?",a="После гибели гидры о победе сообщают гонцам Песни Войны, удерживающим рубежи у Форта Зорам'гар. Это облегчает бремя стражей границы и защищает ближайшее побережье от внезапных нападений.",al={"vorsha quest turn in","who to report vorsha to","сдать задание ворша","кому сообщить о ворше"}}},fp="17,352,22.436.0,23.501.0,25.213.0,29.228.0,33.236.0,15.226.0,54.269.0,35.221.1"}
P.entries["quest:67"] = {n="Легенда о Сталване",s="Это поручение начинает бумажный след судьбы Сталвана Мистмантла; его дает клерк Далтри из ратуши Темнолесья. Самые старые записи указывают на запад, к заброшенной Школе Луноречья в Западном Крае, и запускают классическое расследование о крушении жизни обычного человека.",h="Это поручение начинает бумажный след судьбы Сталвана Мистмантла; его дает клерк Далтри из ратуши Темнолесья.",kw={"daltry","duskwood","footlocker","forlorn spirit","mistmantle","moonbrook","schoolhouse","stalvan","westfall","далтри","сумеречный лес","сундук","неприкаянный дух","мистмантл","луноречье","школа","сталван","западный край"},ang={["class:Mage"]="Неприкаянный дух, охраняющий сундук, применяет превращение и изнуряющие проклятия, устраивая жутковатую встречу с магией, рожденной скорбью, в самой обыденной школьной обстановке.",["faction:Alliance"]="Этот этап расследования показывает, насколько сильно распались сельские города королевства: герои вынуждены пробираться через Западный Край, занятый Братством Справедливости, лишь ради запроса в реестр Темнолесья."},sec={{t="Просьба городского клерка",b="После первых расспросов в Темнолесье Клерк Далтри достает городской реестр, чтобы найти Сталвана Мистмантла. К его удивлению, книга не обновлялась годами и указывает последним известным местом жительства Сталвана школу в Луноречье далеко на западе. Не подозревая о зловещем характере расследования, Далтри считает это рутинным канцелярским делом и просит путников проверить адрес и собрать любые записи, которые помогут обновить пыльные архивы Темнолесья."},{t="Руины Луноречья",b="Идти по следу значит покинуть мрак Сумеречного леса и отправиться в беззаконную пыль Западного Края. Луноречье, некогда процветавшее земледельческое поселение, теперь кишит разбойниками из Братства Справедливости. Почти в центре опустевшего городка стоит заброшенная школа, безмолвная среди бандитской оккупации. Внутри старый сундук хранит первые осязаемые улики о прошлой жизни Сталвана как учителя, а также неутихающую, беспокойную скорбь, связанную с этим сундуком."},{t="Трагическое привидение",b="Если потревожить старый сундук, обнаружатся не только забытые страницы: он призывает Неприкаянного духа, который нападает на всякого, кто раскапывает прошлое Сталвана. Скорбная магия призрака проклинает незваных гостей и намекает на неразрешенную трагедию, связанную с уходом учителя из Западного Края; простое историческое расследование превращается в настоящее преследование призраком."}},faq={{q="Кто такой Клерк Далтри?",a="Клерк Далтри — хранитель городских записей в Ратуше Темнолесья в Сумеречном лесу. Он помогает, просматривая местный реестр в поисках упоминаний о Сталване Мистмантле, но находит лишь древние, устаревшие записи.",al={"daltry","darkshire clerk","who starts legend of stalvan 2","далтри","клерк темнолесья","кто начинает легенду о сталване 2"}},{q="Где находится Школа Луноречья?",a="Школа находится в Луноречье на юго-западе Западного Края. По архитектуре она напоминает ратушу Темнолесья и стоит посреди городка в окружении враждебных бандитов из Братства Справедливости.",al={"moonbrook schoolhouse location","where is the schoolhouse","where is stalvan footlocker","где школа луноречья","где находится школа","где сундук сталвана"}},{q="Что внутри старого сундука?",a="В сундуке лежат старые записи и личные вещи со времен, когда Сталван Мистмантл был учителем в Луноречье; они дают следующую зацепку в поисках его местонахождения.",al={"stalvan footlocker","what is in the footlocker","сундук сталвана","что в сундуке"}},{q="Почему при открытии сундука нападает призрак?",a="Открытие сундука призывает Неприкаянного духа, который нападает с превращением и проклятиями. Беспокойный призрак связан с мрачной трагедией прошлого Сталвана и его уходом из Луноречья.",al={"forlorn spirit","why does a ghost spawn","curse of stalvan ghost","неприкаянный дух","почему появляется призрак","проклятие сталвана призрак"}},{q="Почему Сталван покинул Западный Край?",a="Сталван был учителем в Луноречье, а затем отправился искать работу частным репетитором в другом уголке королевства, оставив свои школьные вещи запертыми в заброшенном городке.",al={"why did stalvan leave moonbrook","stalvan moonbrook history","почему сталван покинул луноречье","история сталвана в луноречье"}},{q="Безопасно ли входить в Луноречье?",a="Нет. Луноречье полностью перешло под власть Братства Справедливости, поэтому каждому, кто ищет школу, придется прорываться через вооруженных воров и разбойников.",al={"is moonbrook dangerous","mobs in moonbrook","опасно ли луноречье","монстры в луноречье"}}},fp="21,278,24.479.0,22.465.0,17.359.1,20.206.0,35.190.0,34.179.0,52.201.1,31.198.0,27.163.0"}
P.entries["quest:676"] = {n="Да падет молот",kw={"arathi highlands","boulderfist enforcer","boulderfist ogre","drum fel","hammerfall","hillsbrad foothills","stromgarde","tallow","tarren mill","the hammer may fall","нагорье арати","надсмотрщик тяжелого кулака","огр тяжелого кулака","драм желчный","павший молот","предгорья хилсбрада","стромгард","сальный","мельница таррен","да падет молот"},ang={["class:Warrior"]="Схватка с огромными надсмотрщиками Тяжелого Кулака — классическое испытание для бойцов первой линии, желающих заслужить уважение опытных орков-командиров вроде Драма Желчного.",["faction:Horde"]="Это задание знаменует главный переход от местных споров в Хилсбраде к более широкой обороне Нагорья Арати, укрепляя важный оплот Павшего Молота в регионе.",["race:Orc"]="Павший Молот имеет для орков глубокое сентиментальное и историческое значение: он основан там, где вождь Оргрим Молот Рока отдал жизнь во время кампаний по освобождению."},sec={{t="Грубый вызов",b="In Tarren Mill, Tallow harbors little patience for untested adventurers wandering through the Foothills. Seeing undisciplined recruits standing idle while distant allies bleed, he directs capable fighters east through Thoradin's Wall into the Arathi Highlands. The Horde outpost of Hammerfall stands besieged on multiple fronts, but Tallow refuses to send warm bodies unless they have proven their worth against substantial opposition first."},{t="Испытание Тяжелым Кулаком",b="Rather than allowing recruits to stumble blindly into Hammerfall, Tallow demands a demonstration of martial strength at the ogre mound northeast of Stromgarde. The Boulderfist tribe maintains a heavy presence in Arathi, their hulking ogres and enforcers posing an immediate threat to anyone traveling the highland trails. Slaying these brutes serves both to thin the hostile forces flanking the road and to ensure that only capable warriors arrive at the outpost."},{t="Доклад в Павшем Молоте",b="Upon clearing out the Boulderfist encampment, the path leads northeast to Hammerfall, an outpost named in memory of Warchief Orgrim Doomhammer. There, commander Drum Fel accepts fresh arrivals with weary skepticism. Whether Tallow intended to bolster the garrison or simply send fools to their deaths, Drum Fel wastes no time turning proven fighters toward the endless skirmishes threatening the outpost's survival."}},faq={{q="Где это задание начинается и заканчивается?",a="The quest is offered by Tallow in Tarren Mill, located in the Hillsbrad Foothills. After completing the required kills in Arathi Highlands, it is turned in to Drum Fel inside the Horde outpost of Hammerfall.",al={"where do i start the hammer may fall","quest turn in location","who gives the hammer may fall","где начать да падет молот","где сдать задание","кто выдает да падет молот"}},{q="Где находятся огры Тяжелого Кулака?",a="Огры Тяжелого Кулака обитают на заметном земляном кургане и в окружающем лагере к северо-востоку от руин Стромгарда в Нагорье Арати.",al={"boulderfist ogre location","where are the ogres in arathi","boulderfist mound","где огры тяжелого кулака","где огры в арати","курган тяжелого кулака"}},{q="Что такое застава Павший Молот?",a="Павший Молот — укрепленное поселение Орды на северо-востоке Нагорья Арати. Он назван в честь бывшего вождя Оргрима Молота Рока, павшего в бою неподалеку во время освобождения лагерей для интернированных орков.",al={"what is hammerfall","hammerfall lore","who founded hammerfall","что такое павший молот","предания павшего молота","кто основал павший молот"}},{q="Why does Tallow make you fight ogres before reporting to Hammerfall?",a="Павший Молот находится под постоянными атаками и отчаянно нуждается в способных бойцах. Сальный посылает новобранцев против огров Тяжелого Кулака как на суровое испытание, чтобы все, кто придет на подмогу Драму Желчному, действительно умели сражаться, а не становились лишним бременем.",al={"why kill ogres first","tallow motive","why test me","почему сначала убить огров","мотив сального","зачем меня проверяют"}},{q="Кто такой Драм Желчный?",a="Драм Желчный — опытный воин-орк и командир в Павшем Молоте в Нагорье Арати; ему поручено организовать оборону от враждебных животных, огров, троллей и остатков Альянса.",al={"drum fel identity","hammerfall commander","who is drum fel","кто такой драм желчный","командир павшего молота","драм желчный"}},{q="Что идет после этого задания?",a="Доклад Драму Желчному ведет прямо к кампании «Призыв к оружию» — череде военных операций по устранению окрестных угроз, включая племена троллей Сухокожих, угрожающие нагорью.",al={"next quest","hammer may fall followup","what comes after","следующее задание","продолжение да падет молот","что дальше"}}},fp="19,317,15.441.0,20.463.0,23.415.1,36.207.0,40.143.0,34.212.0,68.259.0,16.198.0,29.206.0"}
P.entries["quest:68"] = {n="Легенда о Сталване",s="Это расследование раскрывает забытую главу мрачной истории Сталвана Мистмантла. Пыльное неотправленное письмо из заброшенного сундука в Луноречье дает осязаемое доказательство того, где он жил, прежде чем его след исчез, и возвращает к записям Темнолесья.",h="Это расследование раскрывает забытую главу мрачной истории Сталвана Мистмантла.",kw={"clerk daltry","curse of stalvan","darkshire","duskwood","dusty unsent letter","footlocker","forlorn spirit","mistmantle","moonbrook","stalvan","клерк далтри","проклятие сталвана","темнолесье","сумеречный лес","пыльное неотправленное письмо","сундук","неприкаянный дух","мистмантл","луноречье","сталван"},ang={["class:Mage"]="Враждебная тень, охраняющая сундук, владеет коварными тайными искусствами вроде превращения, а также калечащим проклятием, что намекает на неестественные силы, сопровождающие Сталвана.",["class:Priest"]="Появление Неприкаянного духа, привязанного к простому сундуку с памятными вещами, говорит о мучительном душевном грузе, не позволившем упокоиться и после смерти.",["faction:Alliance"]="Раскрытие тайны Сталвана Мистмантла помогает осажденному Темнолесью учесть зловещих личностей, проходивших через границы региона."},sec={{t="Забытый след в Луноречье",b="Пока идут поиски истории Сталвана Мистмантла, старый сундук, спрятанный в Луноречье, выдает важную часть головоломки: пыльное неотправленное письмо. Луноречье, некогда процветавшее земледельческое поселение, пришло в упадок и теперь кишит разбойниками и неупокоенными призраками. Пребывание Сталвана здесь было достаточно недолгим, чтобы ускользнуть из общей памяти, но это забытое послание точно помещает его в деревушку."},{t="Привидение у сундука",b="Возня с вещами Сталвана не остается незамеченной. Потревоженный сундук пробуждает из теней Неприкаянного духа, готового охранять оставленные тайны. Призрак обрушивает чарующую магию и изнуряющее проклятие Сталвана, что говорит: какая бы судьба ни постигла этого человека, скорбь и темные чары прочно цепляются за его оставшиеся вещи."},{t="Обновление городского реестра",b="Доставив письмо через границу обратно в Темнолесье, вы дадите Клерку Далтри недостающий документ. Хотя Далтри находит странным, что письмо так и не отправили, доказательство неоспоримо. Теперь, когда связь с Луноречьем подтверждена, бумажный след наконец сможет направить расследование туда, куда Сталван бежал дальше."}},faq={{q="Что внутри старого сундука в Луноречье?",a="Внутри сундука лежит пыльное неотправленное письмо, написанное во время пребывания Сталвана Мистмантла в Луноречье. Оно служит осязаемым доказательством того, что он жил в городке до исчезновения.",al={"what did i find","footlocker contents","stalvan letter","что я нашел","содержимое сундука","письмо сталвана"}},{q="Почему при открытии сундука нападает дух?",a="Неприкаянный дух задерживается возле забытых вещей Сталвана и поднимается, чтобы напасть на всякого, кто потревожит сундук. Он владеет жуткой магией, включая страх, превращение и неотступное проклятие Сталвана.",al={"forlorn spirit","why am i attacked","footlocker ghost","неприкаянный дух","почему на меня напали","призрак сундука"}},{q="Зачем нести письмо Клерку Далтри?",a="Клерк Далтри ведает городскими записями и реестром в ратуше Темнолесья. Ему нужны веские документы, подтверждающие прошлое местонахождение Сталвана, прежде чем он сможет помочь в дальнейших поисках.",al={"who is clerk daltry","why daltry","darkshire town hall","кто такой клерк далтри","зачем далтри","ратуша темнолесья"}},{q="Почему важно, что письмо не было отправлено?",a="То, что письмо осталось спрятанным и брошенным в заброшенном сундуке, намекает на внезапный отъезд или растущую паранойю и усиливает жутковатую скрытность вокруг передвижений Сталвана.",al={"unsent letter mystery","why wasn't it mailed","тайна неотправленного письма","почему не отправили"}},{q="Что делает проклятие Сталвана?",a="Проклятие Сталвана, накладываемое Неприкаянным духом, который охраняет сундук, — изнуряющая порча, ослабляющая все основные характеристики жертвы на десять минут.",al={"curse of stalvan debuff","spirit curse","проклятие сталвана ослабление","проклятие духа"}},{q="Куда ведет след после передачи письма Далтри?",a="Когда Клерк Далтри обновит городской реестр по этому доказательству из Луноречья, он сможет направить ваши поиски к следующему известному месту пребывания Сталвана.",al={"what next","where after daltry","next clue","что дальше","куда после далтри","следующая улика"}}},fp="21,277,30.406.0,28.360.1,26.344.0,47.192.0,50.210.0,36.196.0,53.199.0,34.169.0,60.163.0"}
P.entries["quest:683"] = {n="Просьба Сары Балу",s="Просьба Сары Балу — печальное поручение, которое выполняется по просьбе скорбящей вдовы-дворфийки из Стальгорна. Не в силах предстать перед своим монархом в таком горе, Сара поручает передать личное обращение королю Магни Бронзобороду о ее погибшем муже, Салли Балу.",h="Просьба Сары Балу — печальное поручение, которое выполняется по просьбе скорбящей вдовы-дворфийки из...",kw={"a king's tribute","dun morogh","ironforge","magni bronzebeard","sara balloo","sully balloo","thandol span","королевские почести","дун морог","стальгорн","магни бронзобород","сара балу","салли балу","мост тандола"},ang={["faction:Alliance"]="Передача вестей между скорбящими жителями и руководством Альянса показывает, какую личную цену платят простые люди в конфликтах, защищающих королевство.",["race:Dwarf"]="Доставка просьбы скорбящей вдовы прямо вашему королю затрагивает глубокое значение, которое дворфы придают работе с камнем, родословной и почитанию жертв предков."},sec={{t="Просьба вдовы",b="Получив трагическое последнее письмо, поднятое из вод под мостом Тандола, Сара Балу оказалась парализована горем. Не желая, чтобы жертва ее мужа Салли была забыта, она написала просьбу, адресованную самому трону Стальгорна. Слишком убитая горем, чтобы явиться ко двору, она вручает запечатанный свиток надежному защитнику Альянса, чтобы тот ходатайствовал перед королем Магни Бронзобородом от ее имени."},{t="Прием у короля",b="Доставка личного прошения к Высокому трону Стальгорна — не рядовое дело, но Магни Бронзобород лично отмечает храбрых защитников Каз Модана. Получив послание, король откладывает государственные дела, чтобы прочесть скромную просьбу солдатской вдовы, и тем показывает свою связь с простыми дворфами, построившими и защищающими его горное королевство."}},faq={{q="Кто такая Сара Балу?",a="Сара Балу — дворфийка из Стальгорна, чей муж, солдат Салли Балу, погиб в трагедии на мосту Тандола. Она живет в городе, свято храня память о нем.",al={"sara balloo","who is sara","сара балу","кто такая сара"}},{q="Почему Сара хочет, чтобы к королю пошел я, а не она сама?",a="Сару сломило горе после того, как она наконец узнала о судьбе мужа. Она чувствует, что не сможет сохранить самообладание, подобающее при обращении к королю Магни Бронзобороду на Высоком троне.",al={"why cant sara go","sara grief","почему сара не может пойти","горе сары"}},{q="Кем был Салли Балу?",a="Салли Балу был дворфом-солдатом, защищавшим мост Тандола. Он погиб в бою на мосту, оставив жене намокшее письмо.",al={"sully balloo","saras husband","салли балу","муж сары"}},{q="Куда доставить Просьбу Сары Балу?",a="Просьбу нужно доставить лично королю Магни Бронзобороду на Высокий трон в центре Стальгорна.",al={"where is magni","king magni location","turn in location","где магни","где король магни","где сдать задание"}},{q="Что будет после того, как король Магни прочтет просьбу?",a="Прочитав просьбу Сары, король Магни решает достойно почтить павшего солдата, и это ведет прямо к заданию «Королевские почести», цель которого — воздвигнуть вечный памятник.",al={"quest continuation","next quest","продолжение задания","следующее задание"}},{q="Какая фракция может взять это задание?",a="Это поручение доступно только членам Альянса, так как касается внутренних дел дворфов и приема у короля Магни Бронзоборода.",al={"can horde do this","faction requirement","может ли орда","требования к фракции"}}},fp="18,262,17.468.0,22.359.1,19.156.0,63.195.0,21.158.0,38.100.0,45.158.1,37.137.0"}
P.entries["quest:686"] = {n="Королевские почести",s="Королевские почести — задание Альянса, которое дает король Магни Бронзобород на Высоком троне Стальгорна. Глубоко тронутый горем Сары Балу, чей муж Салли пал при защите моста Тандола, король решает почтить павшего солдата вечным памятником. Он посылает искателя приключений передать его королевский заказ Главному камнетесу Мраморщику.",h="Королевские почести — задание Альянса, которое дает король Магни Бронзобород на Высоком троне Стальгорна.",kw={"ironforge","magni bronzebeard","marblesten","memorial","sara balloo","sully balloo","thandol span","стальгорн","магни бронзобород","мраморщик","памятник","сара балу","салли балу","мост тандола"},ang={["faction:Alliance"]="Павшие на мосту Тандола отдали жизни, охраняя для Альянса важнейшие линии снабжения между Каз Моданом и северными королевствами.",["race:Dwarf"]="Это задание показывает преданность короля Магни своему народу: даже о самом простом дворфе-пехотинце помнит трон."},sec={{t="Бремя государя",b="Когда король Магни Бронзобород получает просьбу Сары Балу, он не отмахивается от скорбящей вдовы. Хотя он признает, что простым людям трудно понять жестокую необходимость войны, потеря каждого солдата под знаменем Альянса тяжко ложится на его совесть. Не в силах отменить мрачную неизбежность смерти на передовой, Магни решает сделать так, чтобы жертва Салли Балу не была забыта."},{t="Резец камнетеса",b="Вместо пустых утешений король решает воздвигнуть памятник в честь Салли. Он назначает искателя приключений хранителем своей королевской воли и отправляет его через весь Стальгорн к Главному камнетесу Мраморщику. Получив личный заказ короля, мастер-камнетес готовится высечь в камне память о павшем защитнике."}},faq={{q="Кем был Салли Балу?",a="Салли Балу был солдатом-дворфом, погибшим в боях за Альянс при обороне моста Тандола. Его вдова, Сара Балу, обратилась к королю Магни Бронзобороду, узнав о его смерти.",al={"who is sully","sully balloo lore","who died","кто такой салли","предания о салли балу","кто погиб"}},{q="Почему король Магни заказывает памятник?",a="Король Магни несет груз каждой дворфийской жизни, потерянной в непрекращающейся борьбе Альянса. Хотя он не может вернуть Салли вдове, он намерен почтить мужество солдата долговечным королевским памятником.",al={"why build memorial","magni motive","kings tribute purpose","зачем строить памятник","мотив магни","цель королевских почестей"}},{q="Кто такой Главный камнетес Мраморщик?",a="Главный камнетес Мраморщик — мастер-каменотес Стальгорна, которому поручено исполнение крупных городских и королевских архитектурных проектов. Король Магни рассчитывает, что он создаст памятник Салли Балу.",al={"who is marblesten","grand mason role","кто такой мраморщик","роль главного камнетеса"}},{q="Где происходит это задание?",a="Задание целиком проходит в Стальгорне: оно начинается на Высоком троне у короля Магни Бронзоборода и ведет к Главному камнетесу Мраморщику в другой части столицы.",al={"where is this quest","quest location","где это задание","место задания"}},{q="Что предшествует этому заданию?",a="Чтобы получить это задание, искатель приключений должен выполнить «Просьба Сары Балу» — доставить искреннее письмо вдовы лично королю Магни Бронзобороду.",al={"prerequisites","previous quest","требования","предыдущее задание"}},{q="Этот памятник только для Салли Балу?",a="Хотя памятник заказан именно во имя Салли Балу, чтобы утешить его вдову Сару, он символизирует почтение короля ко всем дворфийским воинам, погибшим на службе Альянсу.",al={"who does it honor","is it just for sully","кого он почитает","только ли для салли"}}},fp="16,352,20.431.0,18.361.0,21.205.0,42.213.0,30.205.0,33.167.0,29.154.0,39.193.0"}
P.entries["quest:689"] = {n="Королевские почести",s="Король Магни Бронзобород заказал памятник Салли Балу, дворфу-солдату, погибшему при защите моста Тандола. Чтобы почтить павшего воина с вечным достоинством, Главный камнетес Мраморщик посылает путников в Хилсбрад за чистым альтеракским гранитом.",h="Король Магни Бронзобород заказал памятник Салли Балу, дворфу-солдату, погибшему при защите моста Тандола.",kw={"alterac granite","darrow hill","ironforge","magni bronzebeard","marblesten","stonemason","sully balloo","thandol span","альтеракский гранит","холм дарроу","стальгорн","магни бронзобород","мраморщик","камнетес","салли балу","мост тандола"},ang={["faction:Alliance"]="Добыча материалов в Хилсбраде укрепляет присутствие Альянса на раздробленном севере и одновременно чтит простого солдата, отдавшего жизнь за общее дело.",["profession:Mining"]="Горняки понимают взыскательный взгляд Мраморщика: твердые, неподатливые жилы альтеракского гранита требуют опытных рук, чтобы извлечь их чисто, не расколов.",["race:Dwarf"]="Почтить Салли Балу — значит затронуть самую суть культуры дворфов, где работа по камню, жертва в бою и непоколебимая верность королю Бронзобороду тесно переплетены."},sec={{t="Королевский заказ",b="Когда король Магни Бронзобород решил, что павший солдат Салли Балу заслуживает вечного памятника, задача досталась лучшему мастеру Стальгорна — Главному камнетесу Мраморщику. Балу погиб во время бедствия на мосту Тандола, важнейшей артерии, соединяющей земли дворфов с северными королевствами, которая подверглась жестоким нападениям диверсантов из клана Черного Железа. Для Мраморщика исполнить королевский указ значит создать скульптуру, которая выстоит против времени и войны, чтобы жертва дворфов не осталась незамеченной и забытой в Великой кузне."},{t="Камень севера",b="Мастер-камнетес дворфов не удовольствуется обычным карьерным камнем для королевского проекта. Мраморщик настаивает, что облик Салли Балу можно передать только в альтеракском граните — плотном, прочном камне, ценимом за долговечность и чистую текстуру. Трудность в том, чтобы его добыть: лучшие залежи находятся у холма Дарроу в спорных предгорьях Хилсбрада. Путь вглубь неспокойного севера опасен, но дворфийская работа по камню требует материалов, достойных увековечиваемого героизма."}},faq={{q="Кем был Салли Балу?",a="Салли Балу был солдатом Альянса, погибшим при защите моста Тандола во время катастрофической диверсии. Пораженный его храбростью и письмом, найденным на его теле, король Магни Бронзобород приказал воздвигнуть в его честь постоянную статую.",al={"sully balloo","who was sully balloo","sully balloo lore","салли балу","кто такой салли балу","предания о салли балу"}},{q="Кто такой Главный камнетес Мраморщик?",a="Главный камнетес Мраморщик — мастер-скульптор и каменотес Стальгорна. Он работает в Общинном квартале города, выполняет королевские заказы и яростно гордится тем, что использует лишь лучшие местные камни.",al={"grand mason marblesten","marblesten ironforge","who is marblesten","главный камнетес мраморщик","мраморщик стальгорн","кто такой мраморщик"}},{q="Зачем нужен альтеракский гранит?",a="Альтеракский гранит славится по всем Восточным королевствам исключительной плотностью, мелким зерном и стойкостью к эрозии. Мраморщик настаивает, что лишь камень такого качества достоин королевского памятника, который простоит века.",al={"why alterac granite","alterac granite purpose","what is alterac granite","зачем альтеракский гранит","назначение альтеракского гранита","что такое альтеракский гранит"}},{q="Где находится холм Дарроу?",a="Холм Дарроу — холмистая местность на севере Предгорий Хилсбрада, чуть ниже Мыса и недалеко от границы Альтерака, где в пещерах находят альтеракский гранит.",al={"where is darrow hill","darrow hill location","find darrow hill","где холм дарроу","расположение холма дарроу","найти холм дарроу"}},{q="Что случилось на мосту Тандола?",a="Мост Тандола, колоссальный мост через пропасть между Болотиной и Нагорьем Арати, подвергся нападению диверсантов из клана Черного Железа, которые заложили взрывчатку, чтобы перерезать пути снабжения Альянса, и многие защитники погибли.",al={"thandol span tragedy","thandol span catastrophe","what happened to thandol span","трагедия на мосту тандола","катастрофа на мосту тандола","что случилось с мостом тандола"}},{q="Что будет после того, как я принесу гранит Мраморщику?",a="Получив альтеракский гранит, Мраморщик завершает памятник и просит вас сообщить королю Магни, что он готов.",al={"after turning in granite","marblesten statue progress","после сдачи гранита","ход работы мраморщика над статуей"}}},fp="16,272,18.565.0,18.498.0,20.240.0,30.213.0,30.242.0,21.161.0,34.232.0,54.131.0"}
P.entries["quest:69"] = {n="Легенда о Сталване",s="Это поручение — поворотный момент в поисках неуловимого Сталвана Мистмантла: оно уводит следователей из мрака Сумеречного леса обратно к сердцу королевства. Поспешная, полустертая запись в городской книге учета Темнолесья указывает через реку на Златоземье. Следовать бумажному следу к оживленной таверне Гордость Льва — следующий шаг к выяснению, куда отправился загадочный наставник.",h="Это поручение — поворотный момент в поисках неуловимого Сталвана Мистмантла: оно уводит следователей из мрака...",kw={"clerk daltry","darkshire","duskwood","elwynn forest","goldshire","innkeeper farley","lion's pride inn","stalvan","клерк далтри","темнолесье","сумеречный лес","элвиннский лес","златоземье","хозяин таверны фарли","таверна гордость льва","сталван"},ang={["faction:Alliance"]="Распутывание местных историй и остывших следов на южных землях Альянса требует перемещения между пограничными постами вроде Темнолесья и центральными поселениями вроде Златоземья.",["race:Human"]="Повторяя путь Сталвана, вы проходите через сердце Королевства Штормград, связывая мрачные рубежи Сумеречного леса с привычным уютом Элвиннского леса."},sec={{t="Подсказка в книге",b="Просматривая записи Темнолесья, Клерк Далтри замечает упущение в городской книге учета. Под более ранней записью о Сталване Мистмантле обнаруживается второй пункт назначения, наспех написанный и частично зачеркнутый, словно кто-то передумал или хотел скрыть свой путь. В записке сказано, что Сталван собирался отправиться на северо-запад, в Элвиннский лес, а именно в таверну Гордость Льва."},{t="Переход в Элвинн",b="Путь из тенистых рощ Сумеречного леса на солнечные дороги Златоземья дает резкий контраст, но тень прошлого Сталвана достигает и этих мест. Таверна Гордость Льва — оживленный перекресток Элвиннского леса, принимающий путников, торговцев и солдат. Хозяин таверны Фарли заправляет шумным залом, и потому лучше всех подойдет, чтобы расспросить об образованном страннике, искавшем ночлег."}},faq={{q="Почему след ведет в Златоземье?",a="Клерк Далтри обнаружил в книге учета Темнолесья под первой записью о Сталване второй, частично зачеркнутый адрес. Он ясно указывал, что тот направлялся в таверну Гордость Льва в Златоземье.",al={"why goldshire","why go to goldshire","stalvan in goldshire","почему златоземье","зачем идти в златоземье","сталван в златоземье"}},{q="Кто такой Клерк Далтри?",a="Клерк Далтри — хранитель записей, работающий в ратуше Темнолесья. Он ведет местные книги учета и помогает находить исторические документы о прежних жителях.",al={"daltry","who is daltry","далтри","кто такой далтри"}},{q="С кем говорить в таверне Гордость Льва?",a="Нужно поговорить непосредственно с Хозяином таверны Фарли, который управляет таверной Гордость Льва и следит за путниками и посетителями, проходящими через Златоземье.",al={"who to talk to","lion's pride contact","innkeeper goldshire","с кем поговорить","контакт в гордости льва","хозяин таверны златоземья"}},{q="Почему запись в книге зачеркнута?",a="Запись в книге была стерта лишь частично, что говорит о поспешной или намеренной попытке скрыть путь Сталвана в Элвиннский лес, когда он покинул Сумеречный лес.",al={"scratched out note","why scratched out","зачеркнутая запись","почему зачеркнуто"}},{q="Есть ли в этом задании сражения?",a="Нет. Этот этап расследования — лишь путешествие и расспросы, которые безопасно приведут вас из ратуши Темнолесья в таверну Златоземья.",al={"is there fighting","do i fight anything","есть ли бой","нужно ли сражаться"}},{q="Что такое таверна Гордость Льва?",a="Таверна Гордость Льва — центр Златоземья в Элвиннском лесу. Это известное место отдыха для путников, идущих между Штормградом, Западным Краем и Сумеречным лесом.",al={"lions pride inn","goldshire inn","таверна гордость льва","таверна златоземья"}}},fp="21,405,20.410.0,20.404.0,37.199.0,20.172.0,42.150.0,48.160.0,35.150.0,29.176.0"}
P.entries["quest:690"] = {n="Просьба Малина",s="Просьба Малина — задание Альянса, которое выдает верховный маг Малин в Квартале магов Штормграда. Малин просит опытных искателей приключений отправиться далеко на север, в Опорный пункт на Нагорье Арати, где экспедиция пытается вернуть ценные магические реликвии, оставленные при падении Стромгарда.",h="Просьба Малина — задание Альянса, которое выдает верховный маг Малин в Квартале магов Штормграда.",kw={"arathi highlands","malin","refuge pointe","skuerto","stormwind","stromgarde","tower of arathor","trelane","wizard's sanctum","нагорье арати","малин","опорный пункт","скуэрто","штормград","стромгард","башня аратора","трелан","святилище волшебника"},ang={["class:Mage"]="Для магов, посещающих Святилище волшебника, помощь Малину напрямую сохраняет драгоценные магические исследования и реликвии, связанные с наследием магов Аратора.",["faction:Alliance"]="Опорный пункт — хрупкий оставшийся плацдарм Альянса на Нагорье Арати, поэтому любое подкрепление из Штормграда крайне важно для удержания региона.",["race:Human"]="Стромгард был колыбелью человеческой цивилизации; помощь в возвращении его сокровищ — дело чести и исторического выживания для сынов и дочерей Аратора."},sec={{t="Потерянные вещи учителя",b="Верховный маг Малин, живущий в Святилище волшебника в Штормграде, действует от имени своего прежнего наставника, верховного мага Трелана. Когда воинственное королевство Стромгард погрузилось в хаос и разрушение, Трелан отчаянно оборонял Башню Аратора. Вынужденный покинуть пост, когда город пал под натиском врагов, Трелан оставил могущественные зачарованные вещи. Малин хочет вернуть эти артефакты, пока их не захватили враждебные руки, и направляет способных наемников на север, чтобы усилить его людей на месте."},{t="Осажденный Опорный пункт",b="Путь к реликвиям Трелана лежит через Опорный пункт — осажденный оплот сторонников Стромгарда в центре Нагорья Арати. Главный помощник Малина среди защитников — дворф Скуэрто. Однако Опорный пункт сильно теснят разбойники Синдиката, тролли Сухокожие и огры Тяжелого Кулака. Прибывшие путники быстро понимают, что Скуэрто и гарнизон слишком перегружены, чтобы радушно встретить гостей без немедленной помощи."}},faq={{q="Кто такой верховный маг Малин?",a="Верховный маг Малин — старший маг-человек, живущий в Святилище волшебника в Штормграде. Когда-то он был учеником верховного мага Трелана из Стромгарда, а теперь из Штормграда координирует усилия по возвращению магических исследований своего прежнего учителя.",al={"archmage malin","who is malin","malin stormwind","верховный маг малин","кто такой малин","малин штормград"}},{q="Почему Малину нужна помощь на Нагорье Арати?",a="Стромгард недавно пал в осаде, и верховный маг Трелан был вынужден бежать из Башни Аратора. Агенты Малина в этом районе пытаются вернуть брошенные магические реликвии Трелана, но им не справиться, и они нуждаются в подкреплении.",al={"why go to arathi","malin mission purpose","why arathi highlands","зачем идти на нагорье арати","цель задания малина","почему нагорье арати"}},{q="Где находится Скуэрто?",a="Скуэрто — дворф-разведчик, расквартированный в Опорном пункте, укрепленном лагере Альянса на главной торговой дороге через центр Нагорья Арати.",al={"find skuerto","skuerto location","where is refuge pointe","найти скуэрто","где скуэрто","где опорный пункт"}},{q="Что случилось с Башней Аратора?",a="Башня Аратора была магическим оплотом в Стромгарде. Во время падения королевства верховный маг Трелан пытался удержать укрепление от вторгшихся разбойников Синдиката и огров Тяжелого Кулака, но оборона не выдержала, и ему пришлось бежать.",al={"tower of arathor fall","what happened to stromgarde","trelane tower","падение башни аратора","что случилось со стромгардом","башня трелана"}},{q="Что будет после разговора со Скуэрто?",a="Скуэрто перегружен делами и встречает вас холодно, сразу направляя к своим товарищам в Опорном пункте, чтобы вы начали собирать разбросанные вещи Трелана.",al={"malin request follow up","next quest after malin","skuerto next quest","продолжение просьбы малина","следующее задание после малина","следующее задание скуэрто"}},{q="Кто такой верховный маг Трелан?",a="Верховный маг Трелан — выдающийся маг Стромгарда и наставник верховного мага Малина. Он был одним из главных защитников столицы Арати до падения королевства.",al={"archmage trelane","who is trelane","trelane stromgarde","верховный маг трелан","кто такой трелан","трелан стромгард"}}},fp="15,296,26.512.0,37.492.0,22.238.0,35.238.0,25.161.0,38.253.0,40.168.0,24.163.0"}
P.entries["quest:6921"] = {n="Среди руин",s="По поручению Дже'неу Санкри из Форта Зорам'гар авантюристы Орды отправляются в затопленный храм Непроглядной Пучины за глубинным ядром. Служители Земли ищут эту реликвию, чтобы раскрыть темные стихийные замыслы вторгшегося культа Сумеречного Молота.",h="По поручению Дже'неу Санкри из Форта Зорам'гар авантюристы Орды отправляются в затопленный храм Непроглядной...",kw={"amongst the ruins","ashenvale","blackfathom deeps","earthen ring","fathom core","fathom stone","je'neu sancrea","moonshrine ruins","twilight's hammer","zoram'gar outpost","среди руин","ясеневый лес","непроглядная пучина","служители земли","глубинное ядро","глубинный камень","дже'неу санкри","руины лунного святилища","сумеречный молот","форт зорам'гар"},ang={["class:Shaman"]="Добыча глубинного ядра напрямую служит миссии Служителей Земли — защитить духов воды и земли от принуждения со стороны Сумеречного Молота.",["faction:Horde"]="Уничтожая угрозы в Непроглядной Пучине, вы защищаете Форт Зорам'гар и укрепляете спорный плацдарм Орды на побережье Ясеневого леса.",["race:Troll"]="Помощь Дже'неу Санкри — это помощь собрату из племени Черного Копья, который связывает Орду со стражами стихий из Служителей Земли."},sec={{t="Угроза в глубинах",b="Древний храм ночных эльфов в Непроглядной Пучине, некогда священный для Элуны, попал под власть зловещих сил. В глубине его затопленных ходов культисты Сумеречного Молота устроили свой оплот. Шаман Черного Копья Дже'неу Санкри, находящийся на продуваемом ветрами берегу у Форта Зорам'гар в Ясеневом лесу, с растущей тревогой наблюдает за распространением порчи: он понимает, что культ намерен подчинить местные стихии и обратить их против земли и ее защитников."},{t="Глубинный камень",b="Чтобы расстроить планы культа, Дже'неу поручает защитникам Орды добыть глубинное ядро из подводного глубинного камня в Руинах Лунного святилища. Если умелые шаманы правильно расшифруют ядро, оно раскроет подробную летопись стихийных потоков и возмущений. С этим артефактом Служители Земли надеются проникнуть за завесу действий Сумеречного Молота и защитить край от стихийной катастрофы."}},faq={{q="Кто выдает задание «Среди руин»?",a="Задание выдает Дже'неу Санкри, тролль, представитель Служителей Земли в Форте Зорам'гар на Зорамском взморье в западной части Ясеневого леса.",al={"quest giver","where to get quest","who starts amongst the ruins","персонаж, выдающий задание","где взять задание","кто дает среди руин"}},{q="Что такое глубинное ядро?",a="Глубинное ядро — особый артефакт, хранящийся в затопленном глубинном камне среди руин. Когда шаманы читают его, оно дает подробную историю стихийной активности и показывает, как местные стихии принуждают и подчиняют.",al={"what is the fathom core","fathom stone purpose","what does the core do","что такое глубинное ядро","зачем нужен глубинный камень","что делает ядро"}},{q="Почему Служителей Земли беспокоит Непроглядная Пучина?",a="Служители Земли стремятся к равновесию между природными стихиями. Культисты Сумеречного Молота, захватившие затопленные руины, активно портят и принуждают стихии служить их темным целям, угрожая стабильности всего края.",al={"earthen ring motive","why does the earthen ring care","blackfathom deeps cultists","мотив служителей земли","почему служителей земли это волнует","культисты непроглядной пучины"}},{q="Где находится глубинный камень?",a="Глубинный камень лежит под водой в Руинах Лунного святилища внутри Непроглядной Пучины, поэтому исследователям нужно нырнуть, чтобы добыть ядро.",al={"where is the stone","fathom core location","moonshrine ruins fathom core","где камень","где глубинное ядро","глубинное ядро руины лунного святилища"}},{q="Могут ли игроки Альянса взять это задание?",a="Нет. Задание доступно только Орде, так как Дже'неу Санкри действует из форта Орды Зорам'гар и наряду с обязанностями Служителя Земли помогает стратегическому присутствию Орды в Ясеневом лесу.",al={"is this horde only","alliance version","can alliance do amongst the ruins","только для орды","версия для альянса","может ли альянс выполнить среди руин"}},{q="Какая группа заняла Непроглядную Пучину?",a="Пещерный храмовый комплекс захвачен Сумеречным Молотом — культом конца света, служащим зловещим Древним богам и обращающим стихии к катастрофическим целям.",al={"who is in blackfathom","enemies in bfd","twilight's hammer blackfathom","кто в непроглядной пучине","враги в непроглядной пучине","сумеречный молот непроглядная пучина"}}},fp="17,251,20.481.0,16.434.0,38.159.0,22.241.0,58.254.0,34.166.0,37.193.0,42.189.0"}
P.entries["quest:6922"] = {n="Барон Акванис",s="Победив водного элементаля барона Акваниса в Непроглядной Пучине, искатели приключений получают Странную водяную сферу с испорченной, зловонной жидкостью. Доставленный Дже'неу Санкри из Служителей Земли, артефакт становится важным свидетельством стихийной порчи, расползающейся под Ясеневым лесом. Дже'неу полагает, что сфера докажет, что испортило барона, и не удивился бы, окажись это культисты Сумеречного Молота, засевшие в затопленных руинах.",h="Победив водного элементаля барона Акваниса в Непроглядной Пучине, искатели приключений получают Странную...",kw={"ashenvale","baron aquanis","blackfathom deeps","earthen ring","elemental corruption","je'neu sancrea","strange water globe","twilight's hammer","zoram strand","ясеневый лес","барон акванис","непроглядная пучина","служители земли","стихийная порча","дже'неу санкри","странная водяная сфера","сумеречный молот","зорамское взморье"},ang={["class:Shaman"]="Служители Земли считают порчу стихийных духов тяжким нарушением природного порядка. Расследование осквернения барона Акваниса — ключ к восстановлению стихийного равновесия.",["faction:Horde"]="Дже'неу Санкри взаимодействует с разведчиками Орды в Форте Зорам'гар и ищет отважных защитников, чтобы очистить оскверненные воды под побережьем Ясеневого леса."},sec={{t="Испорченное сердце",b="Барон Акванис был не обычным духом воды, а могущественным элементалем, испорченным мерзкой магией в затопленных гротах Непроглядной Пучины. После его уничтожения остается Странная водяная сфера — несокрушимый шар с плещущейся зловонной жидкостью, которая, судя по всему, питала и искажала природную сущность существа. Предмет не поддается физическому урону и хранит энергии, глубоко тревожащие тех, кто чувствует равновесие стихий."},{t="Исследования Служителей Земли",b="Дже'неу Санкри, шаман Служителей Земли на Зорамском взморье, сразу узнает в артефакте свидетельство неестественного вмешательства. Он и его орден давно подозревали, что барон Акванис стал жертвой темных сил, и прямо указывали на культистов Сумеречного Молота, занявших затонувший храм. Изучая сферу, Дже'неу надеется не только подтвердить вину культа, но и выяснить, какими именно темными методами тот подчиняет и искажает стихийных духов Азерота."}},faq={{q="Кто такой барон Акванис?",a="Барон Акванис — могущественный элементаль воды, обитающий в подземных водах Непроглядной Пучины. Он не бродит свободно: его испортили и подчинили темные практики, обитающие в руинах храмового комплекса.",al={"who is aquanis","aquanis boss","baron aquanis lore","кто такой акванис","босс акванис","предания барон акванис"}},{q="Что такое Странная водяная сфера?",a="Странная водяная сфера — несокрушимый шар, остающийся после победы над бароном Акванисом. Внутри плещется мерзкая зловонная жидкость, источник оскверненной энергии, питавшей порчу элементаля.",al={"water globe","strange water globe","aquanis quest item","водяная сфера","странная водяная сфера","предмет задания акваниса"}},{q="Зачем Дже'неу Санкри нужна сфера?",a="Как член Служителей Земли, Дже'неу Санкри следит за стихийными возмущениями по всему Ясеневому лесу. Он изучает сферу, чтобы подтвердить, стоит ли за порчей Сумеречный Молот, и раскрыть ритуалы, искажающие духов.",al={"why bring to jeneu","jeneu sancrea purpose","зачем нести дже'неу","дже'неу санкри цель"}},{q="Кто стоит за порчей барона Акваниса?",a="Главные подозреваемые — культисты Сумеречного Молота, угнездившиеся в глубине Непроглядной Пучины. Их присутствие в храме согласуется с кампанией осквернения и темного общения с неестественными существами.",al={"who corrupted aquanis","aquanis twilight hammer","cultists blackfathom","кто испортил акваниса","акванис сумеречный молот","культисты непроглядной пучины"}},{q="Где находится Дже'неу Санкри?",a="Дже'неу Санкри — шаман Служителей Земли, разбивший лагерь на Зорамском взморье на северо-западном побережье Ясеневого леса, близ входа в пещерную систему Непроглядной Пучины.",al={"where is jeneu","turn in aquanis quest","where to turn in water globe","где дже'неу","сдать задание акваниса","куда сдать водяную сферу"}},{q="Что происходит после сдачи этого задания?",a="Передача сферы ведет к дальнейшему расследованию стихийного бедствия в крае, и искатели приключений продолжают помогать Служителям Земли против растущей скверны.",al={"next quest","elemental distress","следующее задание","стихийное бедствие"}}},fp="13,454,17.461.0,27.500.1,22.235.0,32.221.0,39.238.0,46.203.0,32.170.0,39.192.0"}
P.entries["quest:6962"] = {n="Угощение для Дедушки Зимы",s="Угощение для Дедушки Зимы — праздничное задание, которое предлагают во время Зимнего Покрова в Оргриммаре. Веселый персонаж, сидящий у лавки Пастбищ Дымного Леса, устал выслушивать праздничные пожелания и просит отзывчивого искателя приключений принести свежее имбирное печенье и молоко.",h="Угощение для Дедушки Зимы — праздничное задание, которое предлагают во время Зимнего Покрова в Оргриммаре.",kw={"gingerbread cookie","greatfather winter","holiday spices","ice cold milk","orgrimmar","smokywood pastures","treats for great-father winter","winter veil","имбирное печенье","дедушка зима","праздничные пряности","ледяное молоко","оргриммар","пастбища дымного леса","угощение для дедушки зимы","зимний покров"},ang={["faction:Horde"]="Праздник, привезенный в Оргриммар предприимчивыми гоблинами Пастбищ Дымного Леса, приносит в суровый город воинов редкую минуту беззаботного домашнего уюта.",["profession:Cooking"]="Эта праздничная традиция дает начинающим поварам простую возможность попрактиковаться в выпечке, превращая дикие яйца и сезонные пряности в праздничное имбирное печенье."},sec={{t="Усталый покровитель зимы",b="Хотя Дедушка Зима воплощает легендарный дух зимы и изобилия по всему Азероту, тот, кто встречает гостей в Аллее Силы, — трудолюбивый артист, нанятый Пастбищами Дымного Леса. Долгие смены, проведенные за выслушиванием жителей, мечтающих о праздничных лакомствах, пробуждают аппетит. Устав говорить о сезонных угощениях, Дедушка охотно просит проходящих путников утолить его тягу к теплой выпечке и холодному напитку."},{t="Кулинарный праздничный дух",b="Чтобы выполнить просьбу Дедушки, нужно немного домашней стряпни. Искателям приключений придется купить праздничные пряности у гоблинов-торговцев Пастбищ Дымного Леса, собрать мелкие яйца диких птиц и испечь классическое имбирное печенье. Вместе с кувшином ледяного молока из местной таверны это скромное угощение приносит пекарю праздничное настроение и небольшой знак благодарности от устроителей праздника."}},faq={{q="Кто такой Дедушка Зима в Оргриммаре?",a="Это актер, нанятый Пастбищами Дымного Леса, чтобы изображать легендарного Дедушку Зиму во время Зимнего Покрова. Он сидит у праздничной торговой лавки в Аллее Силы, приветствует жителей Орды, выслушивает праздничные просьбы и поддерживает веселье.",al={"who is great father winter","orgrimmar greatfather winter","is he the real winter father","кто такой дедушка зима","дедушка зима оргриммар","настоящий ли дедушка зима"}},{q="Какое угощение просит Дедушка Зима?",a="Дедушка Зима просит пять свежеиспеченных имбирных пряников и одну порцию ледяного молока, чтобы пережить долгий утомительный день встречи праздничных гостей.",al={"what does he want","treats requested","what cookies does he need","чего он хочет","какое угощение просит","какое печенье ему нужно"}},{q="Как приготовить имбирное печенье?",a="Рецепт и праздничные пряности продают торговцы Пастбищ Дымного Леса у праздничной лавки. Пекари соединяют праздничные пряности с мелкими яйцами диких птиц, а затем готовят печенье на огне.",al={"how to get gingerbread cookies","gingerbread cookie recipe","cookie ingredients","как получить имбирное печенье","рецепт имбирного печенья","ингредиенты печенья"}},{q="Где найти ледяное молоко?",a="Ледяное молоко можно купить почти у любого торговца едой и питьем, трактирщика или бармена в Оргриммаре и других крупных поселениях.",al={"where to get ice cold milk","buy milk","milk vendor","где взять ледяное молоко","купить молоко","торговец молоком"}},{q="Почему Дедушка Зима сам просит еду?",a="Целый день слушать болтовню детей и горожан о еде, подарках и праздниках — от этого артист сильно проголодался. Он не может просто так покинуть свой пост в Аллее Силы, поэтому просит проходящих искателей приключений принести ему перекус.",al={"why does he want treats","is greatfather winter hungry","почему он просит угощение","голоден ли дедушка зима"}},{q="Есть ли у этого задания аналог для Альянса?",a="Да. Такую же просьбу выдвигает Дедушка Зима в Стальгорне: он так же просит защитников Альянса принести имбирное печенье и холодное молоко во время праздника.",al={"alliance version","ironforge treats","версия для альянса","угощение стальгорн"}}},fp="30,298,24.478.0,23.452.0,39.285.0,44.177.0,36.224.0,33.144.0,50.248.0,45.180.0"}
P.entries["quest:6981"] = {n="Светящийся осколок",s="Светящийся осколок — загадочный самоцвет изумрудного цвета, добытый в темных глубинах Пещер Стенаний. Под его гладкой поверхностью клубится дымная сущность, и эта тревожная реликвия побуждает искателей приключений искать ответы в Кабестане и за его пределами.",h="Светящийся осколок — загадочный самоцвет изумрудного цвета, добытый в темных глубинах Пещер Стенаний.",kw={"barrens","druids of the fang","emerald nightmare","falla sagewind","glowing shard","ratchet","sputtervalve","wailing caverns","степи","друиды клыка","изумрудный кошмар","фолла ветер мудрости","светящийся осколок","кабестан","пароклапан","пещеры стенаний"},ang={["class:Druid"]="Для друидов изумрудный блеск и дымное ядро осколка — мрачное свидетельство того, что Изумрудный Кошмар просачивается в явный мир через павших собратьев в Пещерах Стенаний.",["faction:Alliance"]="Даже вдали от дома, в Калимдоре, исследователи Альянса понимают, какую угрозу всему миру несет темная сила, оскверняющая природу под Степями.",["faction:Horde"]="Разгадка тайны осколка помогает защитить важные перекрестки и торговые пути Степей от неестественных угроз, зарождающихся в подземных источниках.",["race:Tauren"]="Равновесие Степей дорого Шу'хало, и доставка этой противоестественной реликвии Фолле Ветер Мудрости помогает понять порчу, отравляющую их исконные земли."},sec={{t="Тревожная находка",b="Светящийся осколок, извлеченный из глубин Пещер Стенаний, сразу тревожит всякого, кто берет его в руки. Ярко-зеленый и на вид твердый, под кристаллической гранью он хранит клубящиеся туманные тени. Кристалл слегка притягивает, требуя внимания и излучая жуткую ауру, намекающую на порчу спящих друидов и их оскверненного кошмарами убежища."},{t="Поиск ответов в Кабестане",b="Не зная происхождения и природы камня, искатели приключений приносят артефакт в гоблинский порт Кабестан. Местный инженер Пароклапан осматривает диковину и понимает, что ее происхождение лежит за пределами гоблинской техники и обычной геологии. Он отправляет искателей вверх, на скалистые гребни над пещерами, где таурен-мистик Фолла Ветер Мудрости оберегает неспокойные души Степей."}},faq={{q="Что такое Светящийся осколок?",a="Это оскверненный светящийся зеленый кристалл, найденный в глубине Пещер Стенаний. Внутри его стеклянной оболочки клубится слабый дым, тревожа каждого, кто рассматривает его вблизи.",al={"glowing shard item","what is this green gem","shard from wailing caverns","светящийся осколок","что это за зеленый камень","осколок из пещер стенаний"}},{q="Кто может осмотреть осколок в Кабестане?",a="Осколок осматривает Пароклапан, инженер, живущий рядом с распорядителем полетов в Кабестане. Хотя он инженер, а не друид, он узнает странную энергию осколка и направляет вас к тому, кто разбирается в духовных вопросах.",al={"who in ratchet looks at shard","ratchet npc for shard","sputtervalve shard","кто в кабестане смотрит осколок","персонаж в кабестане для осколка","пароклапан осколок"}},{q="Где находится Фолла Ветер Мудрости?",a="Фолла Ветер Мудрости разбила лагерь на горных вершинах прямо над входом в Пещеры Стенаний в центральных Степях.",al={"falla sagewind location","where is falla","mountain above wailing caverns","где фолла ветер мудрости","где найти фоллу","гора над пещерами стенаний"}},{q="Есть ли над головой Пароклапана значок задания?",a="Нет. У Пароклапана нет активного значка задания. Нужно поговорить с ним напрямую и выбрать пункт диалога о странном светящемся осколке, чтобы продолжить.",al={"sputtervalve no question mark","cant turn in to sputtervalve","sputtervalve bugged","пароклапан нет вопросительного знака","не могу сдать пароклапану","пароклапан ошибка"}},{q="Почему кажется, что внутри осколка дым?",a="Дымный вихрь внутри кристалла отражает всепроникающую порчу, искажающую Пещеры Стенаний, и напрямую связан с Изумрудным Кошмаром, проникающим в мысли спящих Друидов Клыка.",al={"why does shard smoke","green smoke in gem","corruption in shard","почему осколок дымится","зеленый дым в камне","порча в осколке"}},{q="Кто может выполнить цепочку заданий после Фоллы Ветер Мудрости?",a="Эту историю могут пройти искатели приключений и Орды, и Альянса. Выводы Фоллы Ветер Мудрости напрямую ведут к заданию «Кошмары», отправляющему героев за советом к их вождям и старейшинам.",al={"is this quest horde only","alliance glowing shard","who gets in nightmares","только ли для орды это задание","светящийся осколок альянс","кто получает кошмары"}}},fp="17,241,22.398.0,26.419.1,26.170.0,37.225.0,32.126.0,52.167.0,47.196.0,54.208.1"}
P.entries["quest:6984"] = {n="Благодарность от \"Пастбищ Дымного Леса\"!",s="Это праздничное задание завершает усилия Пастбищ Дымного Леса по спасению зимних припасов в Оргриммаре. После возвращения похищенных угощений у Омерзительного Гринча торговец-гоблин Каймард Меднокноп направляет искателей приключений получить официальный праздничный знак признательности прямо от Дедушки Зимы.",h="Это праздничное задание завершает усилия Пастбищ Дымного Леса по спасению зимних припасов в Оргриммаре.",kw={"feast of winter veil","great-father winter","greench","kaymard copperpinch","orgrimmar","smokywood pastures","valley of strength","winter veil","зимний покров","дедушка зима","гринч","каймард меднокноп","оргриммар","пастбища дымного леса","аллея силы"},ang={["faction:Horde"]="Празднование Зимнего Покрова Ордой в Оргриммаре сочетает древнее шаманское почитание смены времен года с шумной гоблинской коммерцией.",["profession:Cooking"]="Сезонные припасы Пастбищ Дымного Леса — основа праздничной кухни: экзотические рецепты и праздничные ингредиенты, которых повара с нетерпением ждут каждый год."},sec={{t="Корпоративный праздник",b="Пастбища Дымного Леса стремятся извлечь выгоду из духа Зимнего Покрова, продавая угощения, рецепты и праздничное настроение в столицах Азерота. Когда их партию праздничных товаров похитили в заснеженных холмах Альтеракских гор, дела встали. Теперь, когда угощения возвращены, а Гринч-вор усмирен, торговец Каймард Меднокноп спешит выразить помощникам полную корпоративную благодарность — и устроить подобающе торжественную церемонию."},{t="Встреча с Дедушкой Зимой",b="Вместо того чтобы вручить обычный кошелек через прилавок, гоблины устраивают так, чтобы награду вручил сам Дедушка Зима. Восседая у праздничной елки в Аллее Силы, этот праздничный персонаж служит и покровителем традиций, и почетным символом торжеств. Он благодарит спасителей праздничных припасов сезонным благословением и Особым даром Пастбищ Дымного Леса."}},faq={{q="Кто отправляет меня поговорить с Дедушкой Зимой?",a="Каймард Меднокноп, представитель Пастбищ Дымного Леса в Аллее Силы в Оргриммаре, отправляет вас к Дедушке Зиме, когда вы успешно вернете похищенные праздничные угощения компании.",al={"who starts this quest","quest giver","kaymard role","кто начинает это задание","персонаж, выдающий задания","кто такой каймард"}},{q="Чем я заслужил благодарность Пастбищ Дымного Леса?",a="You tracked down the Abominable Greench in the Alterac Mountains and recovered the stolen holiday treats, saving the Feast of Winter Veil supply chain for the goblins.",al={"why do they thank me","what treats were stolen","greench background","почему меня благодарят","какие угощения украли","кто такой гринч"}},{q="Где в Оргриммаре находится Дедушка Зима?",a="Он сидит под большой украшенной елкой Зимнего Покрова в Аллее Силы, рядом с торговыми палатками Пастбищ Дымного Леса.",al={"great-father winter location","where is santa in org","winter veil tree org","где дедушка зима","где санта в оргриммаре","елка зимнего покрова оргриммар"}},{q="Кто такой Дедушка Зима?",a="В древних преданиях Дедушка Зима — элементаль или мифический вестник смены времен года, одевающий землю в зимний снег. На Зимний Покров смертные исполнители надевают его традиционное красное одеяние, чтобы нести добрую волю и раздавать угощения детям и искателям приключений.",al={"who is great-father winter","is great-father winter real","winter veil lore","кто такой дедушка зима","настоящий ли дедушка зима","предания зимнего покрова"}},{q="Что такое Пастбища Дымного Леса?",a="Пастбища Дымного Леса — кулинарное и сельскохозяйственное предприятие под управлением гоблинов. Во время Зимнего Покрова они поставляют праздничную еду, сезонные ингредиенты и декоративные безделушки и Орде, и Альянсу.",al={"smokywood pastures lore","who are smokywood pastures","goblin holiday vendor","предания пастбища дымного леса","кто такие пастбища дымного леса","гоблин праздничный торговец"}},{q="Получу ли я что-нибудь еще после разговора с ним?",a="Да. Дедушка Зима вручает вам Особый дар Пастбищ Дымного Леса от имени компании, а ваши усилия повышают репутацию у Картеля Хитрая Шестеренка.",al={"quest reward","disguise kit","mail gift","награда за задание","набор для маскировки","подарок по почте"}}},fp="32,308,19.481.0,33.410.0,47.210.0,52.167.0,50.128.0,27.272.0,27.214.0,51.154.0"}
P.entries["quest:7"] = {n="Нападение на лагерь кобольдов",s="«Нападение на лагерь кобольдов» — одно из первых военных поручений, которое маршал Макбрайд дает новоприбывшим рекрутам в Долине Североземья. Добровольцам предстоит истребить кобольдов-паразитов, засевших в северных лесах, чтобы агрессивные подземные мародеры не заполонили земли аббатства. Это первое настоящее испытание новобранца в защите границ Королевства Штормград.",h="«Нападение на лагерь кобольдов» — одно из первых военных поручений, которое маршал Макбрайд дает...",kw={"echo ridge","elwynn forest","kobold","marshal mcbride","northshire","northshire abbey","vermin","рудник горного эха","элвиннский лес","кобольд","маршал макбрайд","североземье","аббатство североземья","паразиты"},ang={["faction:Alliance"]="Беспорядки в Североземье показывают, насколько напряжены внутренние земли Штормграда: даже нашествия мелких мародеров требуют срочного созыва ополчения из добровольцев.",["race:Human"]="Для людей Североземья отражать кобольдов-паразитов — основной гражданский долг: нужно уберечь аббатство и фермерские земли от разорения."},sec={{t="Долина под давлением",b="Долина Североземья когда-то была тихим местом молитв, земледелия и обучения новичков, но в последние годы войска Штормграда оказались растянуты до предела. Король пропал, королевские гарнизоны рассеяны, и дикие твари вместе с лихими людьми смело наступают на границы цивилизации. Маршал Макбрайд организует местную оборону у самого Аббатства Североземья и рассчитывает на свежих добровольцев, чтобы подавить угрозы прежде, чем они нарушат жизнь аббатства или затронут окрестные виноградники."},{t="Паразиты в лесу",b="Кобольды по природе трусливые пещерные жители, помешанные на свечах; обычно они довольствуются тем, что ковыряют подземные жилы вдали от солнечного света. Однако целый клан вышел к северной кромке леса в Североземье. Если их не остановить, их многочисленность превратит мародерство в открытые набеги. Приказ Макбрайда истребить кобольдов-паразитов служит двойной цели: он ослабляет их авангард и показывает, хватит ли новобранцу решимости защищать королевство."}},faq={{q="Кто отдает приказ уничтожить лагерь кобольдов?",a="Приказ отдает маршал Макбрайд. Он стоит прямо у Аббатства Североземья и от имени Штормграда ведает приемом рекрутов и охраной долины.",al={"who gives this quest","quest giver","marshal mcbride role","кто дает это задание","персонаж, выдающий задание","роль маршала макбрайда"}},{q="Почему кобольды живут в северном лесу, а не в руднике?",a="Хотя кобольды обычно живут в норах и рудниках, в Североземье их стало так много, что они выплеснулись в открытый лес. Они устроили примитивные лагеря среди северных деревьев и бродят у края обжитых земель.",al={"why are kobolds outside","kobolds above ground","why woods","почему кобольды снаружи","кобольды на поверхности","почему в лесу"}},{q="Почему эти кобольды считаются угрозой для Штормграда?",a="Поодиночке кобольды-паразиты робки и слабы. Но стаей это наглые воры, способные устраивать засады на путников, грабить припасы и захватывать незащищенные форпосты, а Штормград не может этого допустить, пока его армия и так перегружена.",al={"are kobolds dangerous","why kill vermin","опасны ли кобольды","зачем убивать паразитов"}},{q="Куда ведет это задание дальше?",a="Когда поверхностные паразиты будут повыбиты, маршал Макбрайд просит рекрутов исследовать Рудник Горного Эха, где находится сердце нашествия кобольдов.",al={"what quest is next","next step","after camp cleanup","какое задание следующее","следующий шаг","после нападения на лагерь"}},{q="Получает ли Североземье регулярную поддержку королевской армии?",a="Нет. Из-за политической напряженности и нехватки войск по всему королевству после исчезновения короля Вариана местным командирам, таким как Макбрайд, приходится полагаться на добровольцев из числа гражданских, искателей приключений и новобранцев для охраны границ.",al={"where are stormwind guards","why volunteers","где стражи штормграда","почему добровольцы"}},{q="Почему кобольды так привязаны к своим свечам?",a="Кобольды почитают свечи как главную защиту от удушающей тьмы подземных туннелей. Пламя для них означает безопасность, зрение и собственность, поэтому они крайне враждебны к тем, кто пытается его отнять.",al={"why candles","candle obsession","почему свечи","помешанность на свечах"}}},fp="19,401,23.483.0,23.457.0,42.162.0,56.240.0,55.252.0,34.160.1,50.223.0,48.225.0"}
P.entries["quest:70"] = {n="Легенда о Сталване",s="Этот этап расследования направляет искателей к забытому письму, оставленному много лет назад в гостинице Златоземья. След Сталвана Мистмантла ведет из Элвиннского леса в Торговый квартал Штормграда.",h="Этот этап расследования направляет искателей к забытому письму, оставленному много лет назад в гостинице...",kw={"canals","caretaker folsom","goldshire","innkeeper farley","lion's pride inn","mistmantle","stalvan","stormwind","undelivered letter","каналы","управляющий фольсом","златоземье","хозяин таверны фарли","таверна гордость льва","мистмантл","сталван","штормград","недоставленное письмо"},ang={["faction:Alliance"]="Чтобы раскрыть тайну Сталвана, нужно пройти по сердцу земель Альянса и повторить старый путь от сонной деревушки Златоземье до величественных каналов столицы.",["race:Human"]="Это расследование обнажает темные течения Королевства Штормград: зло, преследующее Сумеречный лес, уходит корнями к самому порогу столицы."},sec={{t="Полуночный ужас",b="Когда Хозяина таверны Фарли из таверны Гордость Льва спрашивают о Сталване Мистмантле, он вспоминает грозовую ночь много лет назад. Странствующий курьер искал укрытия от ливня, но около полуночи в полной панике сбежал вниз. В одной ночной одежде он выскочил прямо в темную бурю, и больше его никто не видел."},{t="Оставленная посылка",b="В паническом бегстве курьер бросил сумку и личный сундук в комнате наверху. Среди забытого груза лежало неотправленное письмо с именем Сталвана, адресованное жителю Канального квартала Штормграда. Сундук так и стоял нетронутым в изножье кровати, пока Фарли не разрешил его открыть."},{t="Холодный прием",b="Доставив давно просроченное письмо в Штормград, вы попадаете к Управляющему Фольсому, который присматривает за домами вдоль каналов рядом с Парком. Вместо благодарности за доставку упомянутое имя Сталвана и вид его почерка вызывают у него немедленное отвращение и враждебность, намекая на давние скандалы, связанные с отправителем."}},faq={{q="Где хранится недоставленное письмо?",a="Письмо лежит в сундуке на верхнем этаже таверны Гордость Льва в Златоземье. Поднимитесь по лестнице, поверните направо и войдите в спальню с кроватью; сундук стоит в изножье кровати.",al={"find letter","stalvan chest location","where is the chest","найти письмо","где сундук сталвана","где сундук"}},{q="Почему письмо изначально не было доставлено?",a="Много лет назад курьер укрылся от ливня в таверне Гордость Льва. Около полуночи что-то так сильно напугало его, что он бежал в бурю в одной ночной одежде, бросив сундук и посылки.",al={"why abandoned letter","what scared the courier","why did messenger run","почему письмо брошено","что напугало курьера","почему посыльный убежал"}},{q="Где найти Управляющего Фольсома в Штормграде?",a="Управляющий Фольсом стоит у каналов в Штормграде, неподалеку от края квартала Парка.",al={"folsom location","where is caretaker folsom","canal district turn in","где фольсом","где управляющий фольсом","сдача в канальном квартале"}},{q="Почему Управляющий Фольсом сердится, получив письмо?",a="Фольсом сразу узнает почерк и имя Сталвана и реагирует с возмущением. Сталван Мистмантл оставил горькие воспоминания и негодование среди людей, связанных с его прошлым в Штормграде.",al={"why is folsom mad","folsom reaction","you have some nerve","почему фольсом зол","реакция фольсома","у вас хватает наглости"}},{q="Как это связано с бедой в Сумеречном лесу?",a="Городской совет Темнолесья расследует затянувшееся зло, связанное с именем Сталвана Мистмантла. Чтобы выяснить, кем Сталван был при жизни, нужно проследить его прежние путешествия и связи через Элвиннский лес и Штормград.",al={"why duskwood quest in goldshire","how does this relate to duskwood","почему задание сумеречного леса в златоземье","как это связано с сумеречным лесом"}},{q="Что происходит после передачи письма Управляющему Фольсому?",a="Резкий ответ Управляющего Фольсома открывает штормградскую главу расследования и подталкивает вас выяснить, где раньше служил Сталван и какие мрачные события произошли со знатным семейством, которому он служил.",al={"next step","what follows this quest","следующий шаг","что после этого задания"}}},fp="21,218,17.344.0,19.334.0,16.348.1,37.203.0,46.226.0,46.99.0,57.200.0,49.228.0,57.204.1"}
P.entries["quest:700"] = {n="Королевские почести",s="«Королевские почести» — заключительный шаг в чествовании жертвы павшего дворфийского солдата Салли Балу. После того как мелкозернистый гранит собран среди руин Лордерона, Главный камнетес Мраморщик по приказу короля Магни Бронзоборода создает в Стальгорне торжественный памятник.",h="«Королевские почести» — заключительный шаг в чествовании жертвы павшего дворфийского солдата Салли Балу.",kw={"a king's tribute","granite","ironforge","lordaeron","magni bronzebeard","marblesten","memorial","sully balloo","королевские почести","гранит","стальгорн","лордерон","магни бронзобород","мраморщик","памятник","салли балу"},ang={["class:Warrior"]="Слова Магни прямо чтят самоотверженную доблесть бойцов первой линии, таких как Салли Балу, отдавших в бою все.",["faction:Alliance"]="Памятник служит трогательным напоминанием о тяжелой цене, которую заплатили Каз Модан и северные королевства в недавних войнах.",["race:Dwarf"]="Для дворфов почитать павших предков-воинов в прочном камне — одна из самых священных культурных традиций."},sec={{t="Памятник, высеченный из скорби",b="Король Магни Бронзобород заказал постоянный памятник в честь Салли Балу, отважного дворфа, отдавшего жизнь за свой народ. Памятник создан Главным камнетесом Мраморщиком из качественного гранита, привезенного из истерзанных войной земель Лордерона, и стоит в Стальгорне как вечное свидетельство подвига павших солдат, чьи жертвы хранят королевство дворфов."},{t="Раздумья государя",b="Услышав о завершении памятника, Магни мрачно размышляет о пределах камня и смертности. Признавая, что высеченный камень никогда не сравнится с жизнью отважного дворфа, он надеется, что памятник устоит и грядущие поколения, живущие на Азероте, никогда не забудут героев, проливших кровь ради их завтрашнего дня."}},faq={{q="Кого почитает этот памятник?",a="Памятник воздвигнут в память о Салли Балу, отважном дворфийском солдате, отдавшем жизнь в доблестной борьбе за свой народ и Альянс.",al={"who is this memorial for","sully balloo monument","who died","кому памятник","памятник салли балу","кто погиб"}},{q="Почему камень добывали в Лордероне?",a="Главному камнетесу Мраморщику требовался лучший гранит, пригодный для долговечных королевских почестей. В Лордероне добывают превосходный камень, хотя сам край лежит в руинах после Плети.",al={"why lordaeron stone","lordaeron granite","marblesten stone","почему камень лордерона","гранит лордерона","камень мраморщика"}},{q="Где происходит это задание?",a="Задание начинается у Главного камнетеса Мраморщика и завершается у короля Магни Бронзоборода в Высоком троне Стальгорна.",al={"where to turn in","who completes quest","где сдать","кто завершает задание"}},{q="Почему король Магни лично заказывает эти почести?",a="Магни считает, что правители должны чтить простых солдат, защищающих их владения. Памятный камень, по его мнению, — важное напоминание будущим поколениям о высокой цене, которую рядовые солдаты платят за их безопасность.",al={"why does magni care","magni bronzebeard sully balloo","почему магни заботится","магни бронзобород салли балу"}},{q="Что происходит после завершения памятника?",a="Доклад королю Магни завершает цепочку заданий о памятнике. Готовая статуя остается в Стальгорне как торжественная, вечная веха в память о Салли Балу.",al={"what comes next","kings tribute follow up","что дальше","продолжение королевских почестей"}},{q="В чем значение статуи с точки зрения каменного мастерства?",a="Главный камнетес Мраморщик — один из самых искусных дворфийских мастеров Стальгорна. Работая с привезенным гранитом Лордерона, он превратил грубый камень в достойное общенародное произведение искусства от имени монарха.",al={"marblesten role","grand mason craft","роль мраморщика","ремесло главного камнетеса"}}},fp="16,279,26.381.0,24.333.0,38.142.0,42.209.0,33.116.0,55.206.0,44.143.0,47.209.0"}
P.entries["quest:7025"] = {n="Угощение для Дедушки Зимы",s="Во время Зимнего Покрова артист, изображающий Дедушку Зиму в Стальгорне, устает и просит прохожих о праздничном угощении. Если принести ему свежие пряничные печенья и ледяное молоко, он вручит праздничную награду и тепло поблагодарит.",h="Во время Зимнего Покрова артист, изображающий Дедушку Зиму в Стальгорне, устает и просит прохожих о...",kw={"feast of winter veil","gingerbread cookie","greatfather winter","ice cold milk","ironforge","smokywood pastures","treats for greatfather winter","зимний покров","пряничное печенье","дедушка зима","ледяное молоко","стальгорн","пастбища дымного леса","угощение для дедушки зимы"},ang={["faction:Alliance"]="Стальгорн — главный центр празднования Зимнего Покрова для Альянса: к праздничной ели в Общинном квартале съезжаются путники со всех Восточных королевств.",["profession:Cooking"]="Для задания нужны простые кулинарные навыки: смешать мелкие яйца и праздничные специи в праздничные пряничные печенья.",["race:Dwarf"]="Для дворфов Дедушка Зима — древняя легенда о титанах и зимних дарах, но вид такого дедушки, жующего печенье в Общинном квартале, возвращает миф на землю."},sec={{t="Долгий день на троне",b="Хотя Зимний Покров уходит корнями в древние предания титанов и мифы дворфов о бессмертном существе в зимней стуже, современные празднества во многом держатся на коммерческом спонсорстве Пастбищ Дымного Леса. У праздничной ели в Общинном квартале Стальгорна простой дворф долгие утомительные часы проводит в костюме Дедушки Зимы, выслушивая праздничные пожелания горожан и нетерпеливых детей."},{t="Выпечка праздничного настроения",b="Выслушав за день множество просьб о подарках, здешний Дедушка Зима неизбежно нагуливает собственный аппетит. Он просит не чего-то роскошного, а простой радости: пять свежеиспеченных пряничных печений с праздничными специями и ледяное молоко, чтобы их запить. Обмен дает передышку уставшему работнику праздника и разносит добрую волю по заснеженной столице."}},faq={{q="Где найти Дедушку Зиму в Стальгорне?",a="Дедушка Зима сидит возле большой праздничной ели и витрины Пастбищ Дымного Леса в Общинном квартале Стальгорна среди праздничных украшений.",al={"where is greatfather winter","greatfather winter location ironforge","ironforge santa location","где дедушка зима","дедушка зима стальгорн","санта в стальгорне"}},{q="Как испечь пряничные печенья?",a="Рецепт продают торговцы Пастбищ Дымного Леса рядом с Дедушкой Зимой. Для выпечки нужны навык кулинарии, праздничные специи, купленные у торговца на празднике, и мелкие яйца, собранные у диких птиц.",al={"where to get gingerbread cookies","gingerbread recipe","how to bake cookies","где взять пряничные печенья","рецепт пряников","как испечь печенье"}},{q="Где взять ледяное молоко?",a="Ледяное молоко можно купить почти у любого хозяина таверны, торговца едой или напитками в крупных городах Альянса, в том числе в тавернах Стальгорна.",al={"ice cold milk vendor","where to buy milk","milk ironforge","продавец ледяного молока","где купить молоко","молоко стальгорн"}},{q="Это тот самый легендарный Дедушка Зима?",a="Нет, это дворфийский артист, нанятый Пастбищами Дымного Леса, чтобы изображать легендарную, связанную с титанами фигуру на празднике Зимнего Покрова.",al={"is greatfather winter real","who is the guy in ironforge","is he really greatfather winter","настоящий ли дедушка зима","кто это в стальгорне","правда ли он дедушка зима"}},{q="Что присылает Дедушка Зима после выполнения задания?",a="Получив печенья и молоко, Дедушка Зима вручает вам Подарочный набор Пастбищ Дымного Леса в благодарность за старания.",al={"treats for greatfather winter reward","mail from greatfather winter","smokywood pastures sampler","награда угощение для дедушки зимы","почта от дедушки зимы","набор пастбищ дымного леса"}},{q="Могут ли игроки Орды выполнить это задание?",a="Это задание в Стальгорне дают игрокам Альянса. У Орды есть собственное подобное задание у Дедушки Зимы в Оргриммаре.",al={"can horde do this quest","horde treats for greatfather winter","может ли орда выполнить задание","угощение для дедушки зимы орда"}}},fp="29,254,22.401.0,20.427.0,48.152.0,36.212.0,29.152.0,50.150.0,64.134.1,47.154.0"}
P.entries["quest:71"] = {n="Доклад для Томаса",s="«Доклад для Томаса» — задание в восточной части Элвиннского леса, связанное с расследованием Стражника Томаса об исчезнувших штормградских стражниках у восточных водных путей. Искатель приключений помогает Стражнику Томасу у восточного моста: выясняет судьбу его пропавших товарищей и докладывает об обстановке вдоль реки.",h="«Доклад для Томаса» — задание в восточной части Элвиннского леса, связанное с расследованием Стражника Томаса...",kw={"bridge","elwynn forest","goldshire","guard thomas","malakai","medallions","murlocs","rolf","мост","элвиннский лес","златоземье","стражник томас","малакай","медальоны","мурлоки","рольф"},ang={["faction:Alliance"]="Гибель Рольфа и Малакая показывает уязвимость границ Элвиннского леса, где из-за нехватки людей может быть разгромлен даже обычный речной патруль.",["race:Human"]="Возвращение медальонов павших стражников приносит штормградским солдатам, погибшим при защите внутренних дорог королевства, некоторую честь и завершенность."},sec={{t="Мрачное подтверждение",b="Стражник Томас удерживал переправу между Златоземьем и Лесопилкой Восточной долины, почти не имея лишних людей. Когда двое его товарищей, Малакай и Рольф, пропали в речных землях, оставалась надежда, что они просто отрезаны или задержались. Возвращенные к мосту служебные медальоны гасят эту надежду: оба стражника были убиты у водных путей."},{t="Угроза у воды",b="Месяцами руководство Штормграда в основном считало мурлоков досадными речными обитателями, отдавая приоритет бандитам и более широким границам королевства. Гибель двух вооруженных штормградских стражников у внутренних ручьев говорит об организованной жестокости. Имея доказательства, Томас понимает, что восточному рубежу Элвиннского леса грозит настоящее нападение, и требует ответных мер, пока лесные дороги и поселения не были захвачены."}},faq={{q="Где стоит Стражник Томас?",a="Стражник Томас стоит на каменном мосту через реку в восточной части Элвиннского леса, на дороге между Златоземьем и Лесопилкой Восточной долины.",al={"thomas location","guard thomas bridge","where is guard thomas","где томас","стражник томас мост","где найти стражника томаса"}},{q="Кто такие Рольф и Малакай?",a="Рольф и Малакай были штормградскими стражниками, отправленными патрулировать восточную часть Элвиннского леса. Обоих одолели и убили мурлоки, скрывавшиеся вдоль берегов реки и озера Каменной Пирамиды.",al={"missing guards elwynn","who was rolf","who was malakai","пропавшие стражники элвиннский лес","кто такой рольф","кто такой малакай"}},{q="Зачем были нужны их медальоны?",a="Медальоны служили официальными опознавательными знаками городской стражи Штормграда. Их возвращение стало для Стражника Томаса неопровержимым доказательством того, что его пропавшие люди погибли при исполнении долга.",al={"why medallions","guard medallions purpose","зачем медальоны","назначение медальонов стражи"}},{q="Почему нападение мурлоков так важно?",a="Мурлоков обычно считали примитивными трусливыми вредителями, а не смертельной угрозой для обученных солдат. Гибель двух вооруженных стражников доказывает, что речные племена осмелели и способны на согласованные засады.",al={"why murlocs threat","are murlocs dangerous elwynn","почему мурлоки угроза","опасны ли мурлоки элвиннский лес"}},{q="Что происходит после доклада Томасу?",a="Томас просит вас доставить маршалу Дугхану в Златоземье донесение о гибели стражников и растущей угрозе мурлоков. Получив его, Дугхан предлагает нагрудный знак из доспеха.",al={"next quest after report to thomas","what does thomas do next","следующее задание после доклада для томаса","что делает томас дальше"}},{q="Почему Стражник Томас стоит на мосту один?",a="Армия Штормграда растянута по всему королевству: король Вариан Ринн пропал, а ресурсы ограничены. На отдаленных постах, таких как восточный мост, остается минимум людей для охраны важных путей.",al={"why is thomas alone","stormwind bridge guard alone","почему томас один","штормградский стражник на мосту один"}}},fp="16,314,19.388.0,26.440.0,30.156.0,26.176.1,36.175.1,41.224.1,44.177.1,47.209.0"}
P.entries["quest:7162"] = {n="Испытательные земли",s="«Испытательные земли» — обряд посвящения, который лейтенант Хаггердин дает новобранцам Альянса, вступающим в Стражу Грозовой Вершины в Альтераке. Чтобы получить официальный знак Грозовой Вершины, претенденты должны отправиться в кишащие гарпиями Пещеры Ледяного Крыла и вернуть установленное боевое знамя. Проявленное в пещере мужество — первый шаг к продвижению по военным рангам экспедиции.",h="«Испытательные земли» — обряд посвящения, который лейтенант Хаггердин дает новобранцам Альянса, вступающим в...",kw={"dun baldar","haggerdin","harpies","icewing caverns","insignia","proving grounds","stormpike","stormpike banner","дун болдар","хаггердин","гарпии","пещеры ледяного крыла","знак отличия","испытательные земли","грозовая вершина","знамя грозовой вершины"},ang={["faction:Alliance"]="Экспедиция Грозовой Вершины — главное военное предприятие Альянса в Альтераке, сочетающее археологические замыслы дворфов с обороной территории от Орды.",["race:Dwarf"]="Стражей Грозовой Вершины в основном возглавляют дворфы Стальгорна, ищущие древние реликвии и тайны титанов, так что это испытание — вход в одно из самых гордых военных подразделений вашей расы."},sec={{t="Мера мужества",b="Стража Грозовой Вершины ведет неустанную кампанию в Альтеракской долине против Клана Северного Волка. Лейтенант Хаггердин, координирующий силы из лагеря Альянса в Альтеракских горах, не отправляет зеленых новобранцев на поле боя без проверки. Прежде чем дать солдату официальное место в страже, Хаггердин требует доказать умение и выдержку, отправляя его в коварные Пещеры Ледяного Крыла к юго-западу от Дун Болдара."},{t="Пещеры Ледяного Крыла",b="Испытание просто по замыслу, но смертельно по исполнению: глубоко в подземных ледяных туннелях установлено знамя Грозовой Вершины. Пещеры не пусты: свирепые ледяные гарпии гнездятся в промерзших углублениях и охотно разрывают неосторожных чужаков. Возвращение со знаменем в целости показывает, что новобранец способен пройти по опасной местности, выстоять против жестоких хищников и сохранить дисциплину под давлением."},{t="Знак Грозовой Вершины",b="Тот, кто переживет пещеру и вернет знамя, получает знак отличия новичка Грозовой Вершины, официально принимающий его в экспедиционные силы. Как обещает Хаггердин, знак — не просто безделушка, а знак ранга, который можно улучшать по мере того, как солдат зарабатывает больше чести на поле боя, стремясь к легендарным наградам, таким как Око командования."}},faq={{q="Кто такой лейтенант Хаггердин?",a="Лейтенант Хаггердин — офицер Альянса, находящийся в Альтеракских горах, отвечающий за набор и поощрение бойцов Стражи Грозовой Вершины. Он проверяет будущих бойцов и награждает их за службу воинскими знаками отличия.",al={"lieutenant haggerdin","haggerdin","who gives proving grounds","лейтенант хаггердин","хаггердин","кто дает испытательные земли"}},{q="Где находятся Пещеры Ледяного Крыла?",a="Пещеры Ледяного Крыла лежат к юго-западу от оплота Альянса Дун Болдар, в ледяных просторах Альтеракской долины. Это запутанные подземные туннели, прорубленные во льду и камне.",al={"icewing caverns location","where is icewing caverns","banner location","где пещеры ледяного крыла","пещеры ледяного крыла расположение","где знамя"}},{q="Какие опасности таятся в Пещерах Ледяного Крыла?",a="Пещеры населяют свирепые ледяные гарпии. Лейтенант Хаггердин предупреждает новобранцев, что эти дикие создания без колебаний устроят засаду на чужаков и перегрызут им глотки.",al={"harpies","what is in icewing caverns","icewing harpies","гарпии","что в пещерах ледяного крыла","гарпии ледяного крыла"}},{q="Почему Стража Грозовой Вершины требует это испытание?",a="Битва с орками Северного Волка жестока и беспощадна. Хаггердин настаивает на отсеве неопытных новобранцев до того, как они попадут на основные линии, чтобы каждый солдат под их знаменем мог сражаться в суровых условиях.",al={"why proving grounds","why do the banner trial","stormpike initiation","почему испытательные земли","зачем испытание знамени","посвящение грозовой вершины"}},{q="Какова награда за прохождение «Испытательных земель»?",a="За прохождение испытания новобранец получает знак отличия новичка Грозовой Вершины. Хаггердин улучшает его до более мощных версий по мере того, как солдат накапливает честь в Альтеракской долине.",al={"stormpike insignia","eye of command","proving grounds reward","знак грозовой вершины","око командования","награда испытательные земли"}},{q="Кто такие Северные Волки, о которых говорит Хаггердин?",a="Клан Северного Волка — клан орков, живущий в Альтеракской долине со времен изгнания десятилетия назад. Стража Грозовой Вершины считает их враждебными дикарями, мешающими интересам Альянса и раскопкам в долине.",al={"frostwolf savages","who are the frostwolves","frostwolf clan","дикари северного волка","кто такие северные волки","клан северного волка"}}},fp="15,389,20.439.0,19.426.0,22.372.0,28.231.0,30.191.0,46.183.0,47.226.0,53.189.0,47.224.0"}
P.entries["quest:72"] = {n="Легенда о Сталване",s="Этот этап расследования направляет искателей в каналы Штормграда, где Управляющий Фольсом присматривает за оставшимся имуществом разорившейся семьи Флинтридж. Ища ответы о загадочном Сталване Мистмантле, герои должны перерыть ящики с вещами из поместья и сразиться с неприкаянными духами, связанными с давней резней.",h="Этот этап расследования направляет искателей в каналы Штормграда, где Управляющий Фольсом присматривает за...",kw={"canals","caretaker folsom","duskwood","flintridge","forlorn spirit","legend of stalvan","massacre","sealed crate","stormwind","tilloa","каналы","управляющий фольсом","сумеречный лес","флинтридж","неприкаянный дух","легенда о сталване","резня","запечатанный ящик","штормград","тиллоа"},ang={["class:Priest"]="Столкновение с плачущим Неприкаянным духом в городских каналах открывает затянувшиеся муки невинных душ, убитых до срока, которые взывают к покою от Света.",["faction:Alliance"]="Тихая трагедия семьи Флинтридж разворачивается прямо в столице королевства и показывает, как даже самые защищенные дворянские роды Штормграда могут быть жестоко уничтожены."},sec={{t="Отголоски резни",b="Следы Сталвана ведут из мрачных рощ Сумеречного леса в самое сердце Штормграда. У городских каналов Управляющий Фольсом присматривает за тем немногим, что осталось от дома Флинтридж. По словам Фольсома, его отец служил поместью до него и занимался жуткой работой: отмывал кровь после страшной резни в доме — трагедии, в центре которой был Сталван."},{t="Аукцион разоренного дома",b="Поскольку семейные средства Флинтридж полностью истощены, а королевские сборщики налогов кружат как стервятники, уцелевшие семейные реликвии и упакованные вещи назначены к продаже с аукциона. Все памятные вещи и бумаги, пережившие кровопролитие, сложены в грузовые ящики на набережной канала. Чтобы напасть на след Сталвана, нужно вскрыть эти запечатанные ящики, пока остатки имущества поместья не разошлись по коллекционерам королевства."},{t="Неупокоенная тень",b="Вторжение в ящики с вещами умерших не остается незамеченным. Ужас убийств все еще цепляется за эти спасенные вещи и проявляется в виде мстительного Неприкаянного духа, нападающего на всякого, кто роется в вещах семьи. Считается, что эта плачущая тень — призрак юной Тиллоа Флинтридж, которая остается прочно привязанной к вещам своей внезапно отнятой жизни."}},faq={{q="Где найти Управляющего Фольсома?",a="Управляющий Фольсом находится у каналов Штормграда, рядом со стопкой брошенных грузовых ящиков и домашних вещей у водного пути.",al={"caretaker folsom location","where is folsom","where is caretaker folsom in stormwind","управляющий фольсом где","где фольсом","где управляющий фольсом в штормграде"}},{q="Что случилось с семьей Флинтридж?",a="Флинтриджи были богатым семейством, разрушенным внезапной и жестокой резней. Как рассказывают предания управляющего, кровопролитие было таким страшным, что отцу Фольсома пришлось отмывать поместье, а в совершении убийства оказался замешан Сталван Мистмантл.",al={"flintridge massacre","what was the massacre","who killed the flintridge family","резня флинтридж","что за резня","кто убил семью флинтридж"}},{q="Почему вещи семьи упакованы в ящики у канала?",a="После трагедии семейные средства Флинтридж полностью иссякли. Под давлением королевских сборщиков налогов уцелевшие вещи поместья упаковали в ящики и выставили у каналов для продажи с аукциона.",al={"why auction flintridge items","why are crates in the canals","flintridge trust","почему аукцион флинтридж","почему ящики у каналов","средства флинтридж"}},{q="Почему при вскрытии ящика нападает дух?",a="Жестокая трагедия резни привязала души жертв к их прежним вещам. Неприкаянный дух, появляющийся для защиты ящиков, как считается, является тенью Тиллоа Флинтридж, одного из убитых детей.",al={"forlorn spirit stormwind","who is the forlorn spirit","why ghost in stormwind canals","неприкаянный дух штормград","кто неприкаянный дух","почему призрак в каналах штормграда"}},{q="Как это связано с Сумеречным лесом?",a="Расследование началось в Темнолесье как поиск пропавшего Сталвана Мистмантла. Изучение его прошлого привело к тому времени, когда он был учителем в семье Флинтридж в Элвиннском лесу и Штормграде, пока роковое кровопролитие не вынудило его скрыться в тени.",al={"stalvan duskwood connection","why are we in stormwind for a duskwood quest","legend of stalvan city connection","сталван сумеречный лес связь","почему штормград в задании сумеречного леса","легенда о сталване связь с городом"}},{q="Что находят внутри запечатанного ящика?",a="Среди упакованной мебели и личных вещей находятся документы и обрывки дневника, которые еще больше раскрывают безумие Сталвана и его одержимость этим семейством.",al={"what is in the crate","sealed crate clue","flintridge crate contents","что в ящике","улика запечатанный ящик","содержимое ящика флинтридж"}}},fp="21,349,20.399.0,29.431.0,16.377.1,34.153.0,39.251.0,66.215.0,50.234.0,39.247.0,41.190.0"}
P.entries["quest:729"] = {n="Рассеянный геолог",ang={["faction:Alliance"]="Это задание показывает совместное присутствие исследователей из Стальгорна, изучающих незнакомые древние земли своих союзников ночных эльфов в Калимдоре."},sec={{t="Опасные раскопки",b="Dispatched across the sea by the Explorers' League under orders from Master Greywhisker, Archaeologist Hollee was thrilled to apprentice under Prospector Remtravel. Renowned among Ironforge's academic circles for his groundbreaking discoveries, Remtravel was sent to investigate ancient ruins along the untamed coast of Darkshore. However, during an excavation into what appeared to be the remnants of an ancient, great civilization, violent stone golems burst forth from the earth, rapidly overrunning the dig site."},{t="Не замечая гибели",b="While Hollee fled in panic to seek help in the night elven port of Auberdine, Remtravel barely batted an eye. Wholly consumed by the relics he uncovered, the elderly prospector remained knee-deep in rubble, completely unbothered by the lumbering constructs surrounding his camp. Anyone who reaches him south of Auberdine finds him not cowering in fear, but grumbling about missing stone brushes and misplaced fossils."}},faq={{q="Who is Prospector Remtravel?",a="Prospector Remtravel is a celebrated dwarven researcher belonging to the Explorers' League of Ironforge. Famous in the dwarven academies for his monumental discoveries, he is equally infamous for an extreme lack of situational awareness whenever valuable relics are nearby.",al={"remtravel","prospector remtravel lore","who is the prospector"}},{q="Why is Archaeologist Hollee in Auberdine?",a="Hollee was assigned as an assistant to Remtravel by Master Greywhisker. When dangerous golems emerged from the ground at their dig site, she fled northward to Auberdine seeking reinforcements to mount a rescue.",al={"archaeologist hollee","hollee auberdine","why did hollee run"}},{q="Что раскапывали дворфы на Темных берегах?",a="The expedition had uncovered evidence of an ancient, advanced society buried beneath Darkshore. Remtravel discovered a mysterious fossil and various stone artifacts before the site was overtaken by subterranean constructs.",al={"what was remtravel digging","darkshore dig site","remtravel fossil"}},{q="Where can Prospector Remtravel be found?",a="Remtravel is located in southern Darkshore, perched among ancient ruins south of Auberdine, surrounded by dangerous golems while obsessively looking for his stone brush and fossil.",al={"where is remtravel","remtravel location","find prospector remtravel"}},{q="Кто отправил эту экспедицию на Темные берега?",a="The expedition was organized by the Explorers' League in Ironforge and directly assigned by Master Greywhisker, who tasked Hollee with assisting Remtravel in cataloging the region's ancient wonders.",al={"who sent hollee","master greywhisker","explorers league darkshore"}},{q="Is Remtravel in actual danger?",a="Yes. Hostile golems prowl the ruins directly around him. Remtravel is oblivious to the imminent threat, focusing entirely on cataloging his findings and wondering where his tools and assistant have wandered off to.",al={"is remtravel dead","remtravel alive","help remtravel"}}},fp="28,330,14.516.0,17.417.0,28.273.0,41.210.0,46.222.0,40.180.0,38.198.0,30.214.0"}
P.entries["quest:730"] = {n="Неприятности на Темных берегах?",ang={["faction:Alliance"]="Это задание показывает растущее сотрудничество Стальгорна и Дарнасса, связывающее путников между Тельдрассилом и материковым Калимдором.",["race:Dwarf"]="Для дворфов это задание связано с традицией Лиги исследователей раскапывать наследие титанов и древнюю историю на новых континентах.",["race:NightElf"]="Ночные эльфы могут смотреть на появление дворфов-раскопщиков с кирками в их древних прибрежных руинах с осторожным весельем или тихой тревогой."},sec={{t="Молчащая экспедиция",b="In the grand night elven capital of Darnassus, dwarven researchers from Ironforge pursue the ancient mysteries of Kalimdor. Chief Archaeologist Greywhisker sent an excavation party across the water to Darkshore to unearth artifacts of antiquity. When weeks go by without a single missive or progress report, Greywhisker grows anxious, fearing that his field crew has encountered perils they were ill-equipped to survive alone."},{t="Неотрытые угрозы",b="Greywhisker laments that many in the Alliance dismiss dwarven archaeology as little more than an eccentric hobby. However, findings in Khaz Modan have convinced his colleagues that an ancient, terrifying force threatens Azeroth spanning from Lordaeron to Kalimdor. Digging into Darkshore's ruins is not merely an academic endeavor—it is an effort to understand historic cataclysms and the deep-seated menaces buried beneath ancient soil."},{t="Встреча в Аубердине",b="Переплыв пролив от Тельдрассила к прибрежной гавани Аубердин, путники находят в городе Археолога Холли. Обрадованная, что Главный археолог прислал помощь, Холли сообщает, что экспедиция действительно в тяжелом положении: она попала в беду дальше по побережью в поисках древних реликвий."}},faq={{q="Who starts the quest Trouble in Darkshore?",a="Chief Archaeologist Greywhisker offers the quest in the night elven capital of Darnassus, seeking brave adventurers willing to check on his missing crew.",al={"who gives trouble in darkshore","quest giver trouble in darkshore","where to get trouble in darkshore","кто дает неприятности на темных берегах","персонаж, выдающий задание неприятности на темных берегах","где взять неприятности на темных берегах"}},{q="Куда нужно отправиться, чтобы выполнить это задание?",a="Вам нужно отправиться из Дарнасса через море в портовый городок Аубердин на Темных берегах, где вы найдете Археолога Холли.",al={"where do i go","turn in location","who do i turn this in to","куда идти","где сдать задание","кому сдавать задание"}},{q="Почему дворфийские археологи находятся в Дарнассе и на Темных берегах?",a="После недавних открытий в Каз Модане дворфийские исследователи начали изучать древние места по всему Калимдору, чтобы найти ключи к древним силам, угрожающим Азероту.",al={"why are dwarves in darnassus","dwarves in darkshore","dwarven archaeology kalimdor","почему дворфы в дарнассе","дворфы на темных берегах","дворфийская археология калимдор"}},{q="Что происходит после встречи с Археологом Холли?",a="Speaking with Archaeologist Hollee in Auberdine leads directly into 'The Absent Minded Prospector', asking you to venture into Darkshore's wilderness to locate Prospector Remtravel.",al={"what comes next","follow up quest","next quest","что дальше","продолжение задания","следующее задание"}},{q="Почему группа раскопок не сообщила о себе?",a="Группа столкнулась с неожиданными опасностями и неудачами в полевых условиях на Темных берегах, и ее члены оказались разделены и лишены возможности связаться с Дарнассом.",al={"what happened to the dig","why did they disappear","crew missing","что случилось с раскопками","почему они пропали","пропала группа"}},{q="What looming threat is Greywhisker referring to?",a="Greywhisker references discoveries unearthed in Khaz Modan that suggest an ancient, pervasive danger slumbering deep within Azeroth's historic ruins.",al={"what ancient threat","greywhisker warning","khaz modan threat"}}},fp="21,355,19.426.0,16.439.0,20.335.1,42.153.0,45.134.0,58.172.0,48.181.0,45.167.0,48.149.0"}
P.entries["quest:7321"] = {n="Нежный черепаховый суп",ang={["faction:Horde"]="Поддержка гарнизона Мельницы Таррен — это не только защита границ: запасы и боевой дух помогают Орде удержаться в спорном Хилсбраде.",["profession:Cooking"]="Это задание позволяет поварам освоить нежный черепаховый суп, превращая агрессивных рептилий озера Лордамер и рек Хилсбрада в восстанавливающее блюдо."},sec={{t="Гастрономия Отрекшихся",b="It is widely assumed that the Forsaken have entirely abandoned the comforts of life, including the art of fine dining. Christoph Jeffcoat, stationed in Tarren Mill, vigorously rejects that assumption. Boasting that his rich, soothing turtle bisque is good enough to tempt souls back from beyond the grave, Jeffcoat seeks to prove that undead hands are capable of delicate, heartwarming craft even in a land tainted by plague and war."},{t="Охота на кусачих черепах",b="Ordinarily, Jeffcoat gathered his own ingredients from the waterways of Hillsbrad Foothills and the eastern shores of Lordamere Lake in neighboring Alterac. However, duties in Tarren Mill and the encroaching presence of Alliance forces have pinned him down. He relies on passing Horde cooks to hunt the snapjaws, harvest their meat, and bring it back so the culinary tradition can endure."}},faq={{q="Зачем повару из Отрекшихся готовить горячий суп?",a="While the Forsaken do not require sustenance in the same manner as living mortals, individuals like Christoph Jeffcoat take great pride in their trade. Jeffcoat aims to disprove the prejudice that undead lack refined skill, joking that his signature broth is good enough to bring the deceased back to life.",al={"undead cooking","why make bisque","undead eat food","готовка нежити","зачем варить суп","нежить ест еду"}},{q="Где найти черепашье мясо для этого рецепта?",a="Черепашье мясо добывают у агрессивных кусачих черепах, живущих вдоль рек Предгорий Хилсбрада и Альтерака, а также на берегах озера Лордамер.",al={"where are turtles","turtle locations","snapjaw locations","где черепахи","места черепах","где кусачие черепахи"}},{q="Why can't Christoph Jeffcoat gather his own ingredients?",a="Jeffcoat claims he is tied down with responsibilities in Tarren Mill. He also expresses irritation at the encroaching Alliance forces nearby, which make personal hunting excursions far more hazardous.",al={"why doesn't christoph go","jeffcoat stuck in town"}},{q="Нужны ли знания кулинарии для этого задания?",a="Yes. Christoph Jeffcoat will only share his craft and recipe with fellow practitioners of the cooking profession, though it does not demand any advanced mastery to begin.",al={"do i need cooking","cooking profession requirement","нужна ли кулинария","требование профессии кулинария"}},{q="Какое значение имеет Мельница Таррен для Орды в Хилсбраде?",a="Мельница Таррен — главный оплот Орды в Предгорьях Хилсбрада. Прежде человеческая деревня, теперь она служит укрепленной базой Отрекшихся и их союзников и часто сталкивается с Южнобережьем и силами Альянса в регионе.",al={"what is tarren mill","tarren mill lore","что такое мельница таррен","предания мельницы таррен"}},{q="Бывает ли черепаший суп только у Орды?",a="Alliance cooks can acquire the recipe from local human chefs in Southshore who also make use of the local turtle population, but Christoph Jeffcoat's personal quest and perspective are exclusive to the Horde.",al={"alliance version","can alliance get turtle bisque","версия альянса","может ли альянс получить черепаховый суп"}}},fp="22,366,19.433.0,20.388.0,54.306.0,47.175.0,56.200.0,49.170.0,59.255.0,37.208.0"}
P.entries["quest:74"] = {n="Легенда о Сталване",s="Этот этап расследования ведет к старому ящику с семейными реликвиями Флинтриджей, оставленному у каналов Штормграда. В пыльных вещах находится обрывок страницы дневника — важная рукописная улика о прошлой жизни Сталвана Мистмантла, ведущая к маршалу Хаггарду в Элвиннском лесу.",h="Этот этап расследования ведет к старому ящику с семейными реликвиями Флинтриджей, оставленному у каналов...",kw={"duskwood","elwynn forest","forlorn spirit","marshal haggard","mistmantle","sealed crate","stalvan","torn journal page","сумеречный лес","элвиннский лес","неприкаянный дух","маршал хаггард","мистмантл","запечатанный ящик","сталван","обрывок страницы дневника"},ang={["faction:Alliance"]="Расследование давних нераскрытых дел в сердце Элвиннского леса показывает, как глубоко личные ужасы могут ускользнуть от взгляда маршалов Штормграда.",["race:Human"]="Маршал Хаггард олицетворяет стареющее поколение ветеранов Штормграда, хранящее важные воспоминания о королевстве до того, как Первая и Вторая войны разорвали семьи."},sec={{t="Вскрывая прошлое",b="Роясь в запечатанном ящике с затхлыми реликвиями, старыми охотничьими трофеями и семейными портретами, следователи находят под керамической вазой одинокий обрывок страницы дневника. Написанный рукой самого Сталвана Мистмантла, он дает личное представление о мыслях замкнутого ученого до наступления трагедии."},{t="Слабеющее зрение маршала",b="Маршал Хаггард, теперь старый и страдающий от слабого зрения, с трудом разбирает письмо на потрепанном пергаменте. И все же характерный почерк тревожно отзывается в его памяти, напоминая о документах и событиях минувших лет, до того как тьма отняла у него зрение."}},faq={{q="Где находится запечатанный ящик?",a="Запечатанный ящик стоит у Каналов Штормграда, прямо за управляющим Фольсомом, среди упакованных вещей семьи Флинтридж. Найденную там страницу затем относят маршалу Хаггарду на юго-востоке Элвиннского леса.",al={"crate location","where is crate","haggard crate","где ящик","расположение ящика","ящик хаггарда"}},{q="Что внутри запечатанного ящика?",a="В ящике лежат пыльные реликвии, семейный портрет, старые книги, охотничьи трофеи и керамическая ваза, под которой находится обрывок страницы из дневника Сталвана.",al={"crate contents","what is in the crate","torn page crate","содержимое ящика","что в ящике","обрывок страницы в ящике"}},{q="Кто такой маршал Хаггард?",a="Маршал Хаггард — пожилой офицер Штормграда в отставке, живущий один на юге Элвиннского леса. Несмотря на слабое зрение и дряхлость, его воспоминания о старых записях и путниках делают его важным свидетелем прошлых событий.",al={"who is haggard","marshal haggard lore","old marshal elwynn","кто такой хаггард","предания маршала хаггарда","старый маршал элвинн"}},{q="Почему эта страница дневника важна?",a="Обрывок страницы — прямое свидетельство, написанное самим Сталваном Мистмантлом. Его характерный почерк и оставшиеся мысли помогают связать разрозненные рассказы из Сумеречного леса и Элвиннского леса с его личным падением.",al={"why torn page matters","journal page clue","stalvan journal","почему важна страница","улика дневник","дневник сталвана"}},{q="Что происходит, когда ящик открывают?",a="Потревоженные останки прошлого Сталвана пробуждают беспокойных мертвецов: появляется мстительный неприкаянный дух и нападает на тех, кто пытается раскрыть эту трагедию.",al={"forlorn spirit spawn","ghost after crate","why did a ghost attack me","появление неприкаянного духа","призрак после ящика","почему напал призрак"}},{q="Куда ведет расследование дальше?",a="После того как обрывок страницы показан маршалу Хаггарду, его воспоминание о почерке направляет расследование дальше — к поискам других уцелевших фрагментов истории Сталвана.",al={"next step","after torn page","where do I go next","следующий шаг","после обрывка страницы","куда идти дальше"}}},fp="21,309,19.331.0,24.276.1,34.227.0,32.158.0,23.226.0,35.215.0,38.163.0,39.173.0"}
P.entries["quest:741"] = {n="Рассеянный геолог",s="В этом поручении странный окаменелый образец, найденный на диких берегах Темных берегов, нужно доставить в аванпост Лиги исследователей в Дарнассе. Археолог Холли не хочет бросать рассеянного коллегу в поле и поручает перевозку образца проходящему мимо искателю приключений. Прибытие окаменелости в столицу ночных эльфов тут же вызывает живой интерес Главного археолога Седоуса.",h="В этом поручении странный окаменелый образец, найденный на диких берегах Темных берегов, нужно доставить в...",kw={"archaeologist","darkshore","darnassus","explorers league","fossil","greywhisker","hollee","remtravel","археолог","темные берега","дарнасс","лига исследователей","окаменелость","седоус","холли","сомнамбулер"},ang={["faction:Alliance"]="Это задание показывает, как члены Альянса зависят друг от друга: дворфийские исследователи полагаются на странствующих искателей приключений, которые безопасно связывают дальние берега Темных берегов и высоты Дарнасса.",["race:Dwarf"]="Доставка окаменелости Сомнамбулера исполняет главную миссию Лиги исследователей: раскрыть глубочайшее прошлое мира и доказать безмерную ценность дворфийского упорства.",["race:NightElf"]="Смотреть, как дворфийские землекопы выносят древние останки из священной земли Темных берегов, может быть тяжело, но сотрудничество с Лигой сохраняет связи внутри Альянса."},sec={{t="Курьер в столицу",b="Раскопки Геолога Сомнамбулера на туманном побережье Темных берегов обнаружили любопытную окаменелость, но копать глубже для него важнее, чем соблюдать порядок. Археолог Холли не хочет оставлять блуждающего геолога одного среди опасных зверей и враждебных культистов побережья и остается присматривать за ним. Чтобы находка была задокументирована, ей нужен путник из Альянса, который доставит образец в Дарнасс, где у дворфийской гильдии есть ученое представительство."},{t="Интерес дворфов в Калимдоре",b="Дворфы из Стальгорна большими силами пересекли Великое море под знаменем Лиги исследователей, желая раскопать древние реликвии и утраченную историю под землей Калимдора. Приняв артефакт в эльфийской столице, Главный археолог Седоус тут же начинает восхищаться талантом Сомнамбулера находить древние сокровища. Если ночные эльфы считают свои леса живыми святилищами, то Лига видит в древних землях обширные раскопки, ждущие расшифровки."}},faq={{q="Что это за загадочная окаменелость?",a="Это неопознанный окаменелый образец, найденный на побережье Темных берегов Геологом Сомнамбулером. Его древность и необычная природа делают его ценной находкой для ученых Лиги исследователей в Дарнассе.",al={"mysterious fossil","what fossil is this","remtravel fossil","загадочная окаменелость","что это за окаменелость","окаменелость сомнамбулера"}},{q="Почему Холли остается на Темных берегах?",a="Археолог Холли считает своим долгом присматривать за Геологом Сомнамбулером. Он привык уходить в сторону и не замечать опасности во время раскопок, поэтому она не хочет оставлять его одного в глуши, пока его находки доставляют в Дарнасс.",al={"why doesn't hollee go","hollee staying","why hollee stays","почему холли не идет","холли остается","почему холли остается"}},{q="Кто такой Главный археолог Седоус?",a="Седоус — старший представитель Лиги исследователей Стальгорна, руководящий археологическими предприятиями на севере Калимдора. Он работает в Дарнассе и изучает реликвии, которые привозят с места работ дворфийские землекопы.",al={"greywhisker","who is greywhisker","chief greywhisker","седоус","кто такой седоус","главный археолог седоус"}},{q="Почему Лига исследователей работает в Дарнассе?",a="Король Магни Бронзобород учредил Лигу исследователей, чтобы раскрыть происхождение дворфов и древнюю историю всего Азерота. Дружественные дипломатические связи с ночными эльфами позволяют дворфийским ученым отправлять экспедиции из Дарнасса для изучения забытых земель Калимдора.",al={"dwarves in darnassus","explorers league darnassus","why are dwarves here","дворфы в дарнассе","лига исследователей дарнасс","почему здесь дворфы"}},{q="Куда попадет окаменелость после Дарнасса?",a="Главный археолог Седоус осматривает находку в Дарнассе, но открытия такого масштаба должны быть внесены в каталог или направлены дальше по каналам Лиги и обратно в великий музей Стальгорна.",al={"where does fossil go","fossil next step","куда попадет окаменелость","дальнейший путь окаменелости"}},{q="Где Сомнамбулер нашел образец?",a="Сомнамбулер обнаружил образец на диком побережье Темных берегов, где полно кораблекрушений, древних руин и окаменелых морских существ, живших еще до Великого Раскола.",al={"where was fossil found","remtravel dig site","где нашли окаменелость","место раскопок сомнамбулера"}}},fp="28,412,24.493.0,29.498.0,30.220.0,41.236.0,39.222.0,52.284.0,46.205.0,38.177.0"}
P.entries["quest:742"] = {n="Большая охота",s="Большая охота — это призыв, отправленный молодым героям Орды в Громовом Утесе: он зовет их на север, в густые кроны Ясеневого леса. Через глашатаев города путникам велят явиться к Сенани Громовое Сердце на Заставе Расщепленного Дерева и принять участие в испытательной охоте.",h="Большая охота — это призыв, отправленный молодым героям Орды в Громовом Утесе: он зовет их на север, в густые...",kw={"ashenvale","hunt","senani","splintertree","thunder bluff","thunderheart","windstrider","zoram strand","ясеневый лес","охота","сенани","расщепленное дерево","громовой утес","громовое сердце","быстрое копыто","зорамское взморье"},ang={["class:Hunter"]="Дикие хищники Ясеневого леса дают охотникам возможность освоить выслеживание в густом лесу, совсем не похожем на сухие открытые саванны юга.",["faction:Horde"]="Застава Расщепленного Дерева и Зорамское взморье — важнейшие плацдармы северных линий снабжения Орды, и им нужны свежие новобранцы, чтобы сдерживать диких зверей и враждебных местных жителей.",["race:Tauren"]="Для таурен, проходивших испытания на открытых равнинах Мулгора, густой и тенистый полог Ясеневого леса — непривычное священное испытание под бдительными взглядами сородичей, таких как Сенани."},sec={{t="Призыв с Высокой вершины",b="На безмятежных высотах Громового Утеса гонцы сообщают растущей Орде о возможностях за пределами Мулгора. Вестник Утеса Быстрое Копыто несет открытое приглашение для проверенных искателей приключений, ищущих более серьезных испытаний. Поскольку Орда закрепляется в глубине древнего леса к северу от Степей, молодых воинов призывают усилить эти аванпосты и испытать навыки выживания в куда более суровой среде."},{t="Северный рубеж",b="Ясеневый лес для Орды — это и богатые ресурсы, и серьезная опасность. Присутствие фракции в этих землях держится на двух крупных лагерях: Заставе Расщепленного Дерева у главной дороги и отдаленном аванпосте на западном побережье, на Зорамском взморье. Прибыв на Заставу Расщепленного Дерева, новобранцы оказываются под началом Сенани Громовое Сердце, опытной охотницы, которая организует масштабную охоту, чтобы укротить дикие земли и добыть славу для Орды."}},faq={{q="Кто дает это задание в Громовом Утесе?",a="Это поручение предлагает проходящим искателям приключений в Громовом Утесе Вестник Утеса Быстрое Копыто. Его долг — сообщать способным бойцам о стремлении Орды к расширению и направлять их в отдаленные аванпосты, нуждающиеся в помощи.",al={"who starts ashenvale hunt","quest giver ashenvale hunt","bluff runner windstrider","кто начинает большую охоту","персонаж, выдающий задание большая охота","вестник утеса быстрое копыто"}},{q="Где находится Застава Расщепленного Дерева?",a="Застава Расщепленного Дерева — укрепленное поселение Орды в восточной части Ясеневого леса. Чтобы добраться до нее, идите прямо на север через границу Степей в Ясеневый лес, а затем по восточной лесной тропе вглубь чащи.",al={"splintertree post location","how to get to splintertree post","where is splintertree","где застава расщепленного дерева","как добраться до заставы расщепленного дерева","где расщепленное дерево"}},{q="Кто такая Сенани Громовое Сердце?",a="Сенани Громовое Сердце — опытная охотница-таурен, расквартированная на Заставе Расщепленного Дерева. Она координирует охоту в Ясеневом лесу и проверяет силу и терпение новобранцев Орды в схватках с местными хищниками.",al={"senani thunderheart","who is senani","thunderheart npc","сенани громовое сердце","кто такая сенани","громовое сердце"}},{q="Почему Орда охотится в Ясеневом лесу?",a="Орда активно расширяет присутствие в Ясеневом лесу, чтобы добывать древесину и занять стратегически важные земли. Сама охота помогает сократить число опасных диких зверей, угрожающих лагерям, и позволяет молодым искателям приключений проявить себя на незнакомой местности.",al={"why hunt in ashenvale","ashenvale hunt purpose","horde ashenvale goals","зачем охотиться в ясеневом лесу","цель большой охоты","цели орды в ясеневом лесу"}},{q="Что такое Зорамское взморье, упомянутое в брифинге?",a="Зорамское взморье — прибрежный лагерь Орды на дальнем западном берегу Ясеневого леса, обращенный к морю. Он служит вторичным морским плацдармом и оплотом против наг и враждебных лесных обитателей.",al={"what is zoram strand","zoram strand outpost","zoram outpost","что такое зорамское взморье","аванпост зорамского взморья","аванпост зорам"}},{q="Что происходит после доклада Сенани?",a="Когда вы доложите Сенани Громовое Сердце, она поприветствует вас на аванпосте и сразу вовлечет в более широкие охотничьи задачи, направив вас выслеживать и побеждать самых свирепых зверей Ясеневого леса.",al={"what follows ashenvale hunt","next quest after senani","hunt continuation","что после большой охоты","следующее задание после сенани","продолжение охоты"}}},fp="18,291,28.451.0,21.468.0,39.213.0,35.220.0,27.211.0,38.261.0,51.196.0,39.197.0"}
P.entries["quest:743"] = {n="Опасности Ярости Ветра",s="Опасности Ярости Ветра — обряд боевой готовности, который предлагает Руул Орлиный Коготь в Деревне Кровавого Копыта. Молодым таурен и искателям приключений Орды поручено сразиться с дикими гарпиями Ярости Ветра, гнездящимися в юго-восточных утесах Мулгора. Охота на этих свирепых хищников — важная проверка мастерства и выживания перед выходом за пределы родины племен.",h="Опасности Ярости Ветра — обряд боевой готовности, который предлагает Руул Орлиный Коготь в Деревне Кровавого...",kw={"bloodhoof village","dangers of the windfury","harpies","mulgore","ruul eagletalon","tauren trial","windfury","windfury talons","деревня кровавого копыта","опасности ярости ветра","гарпии","мулгор","руул орлиный коготь","испытание таурен","ярость ветра","когти ярости ветра"},ang={["class:Warrior"]="Испытание Руула Орлиного Когтя особенно важно для будущих воинов, которым предстоит учиться отражать быстрые пикирующие удары и одолевать свирепых воздушных налетчиков твердой выучкой.",["faction:Horde"]="Союзники таурен, проходящие испытание Руула, показывают преданность делу защиты сердца земель Орды и завоевывают неизменное уважение Деревни Кровавого Копыта.",["race:Tauren"]="Для молодых таурен очистка гнезд Ярости Ветра — это и защита равнин, и священный переход во взрослую жизнь под бдительными взглядами старейшин деревни."},sec={{t="Оценка наставника",b="В Деревне Кровавого Копыта опытный воин Руул Орлиный Коготь наблюдает за всеми путниками, проходящими через сердце Мулгора. От тех, кто достиг зрелости или хочет доказать готовность к дальним странствиям, Руул требует вещественных доказательств боевых навыков. Выжить за пределами защищенных долин Мулгора можно лишь хладнокровно встречая агрессивных и хитрых врагов, и Руул оценивает стойкость юнцов на свирепейших местных хищниках."},{t="Угроза Ярости Ветра",b="Гарпии Ярости Ветра гнездятся на горном юго-восточном краю Мулгора, вдали от проторенных троп, но постоянно угрожают бродячим животным и одиноким путникам. Жестокие и вечно голодные до свежей плоти, эти крылатые чудовища полагаются на стремительные налеты и острейшие когти. Победа над ними и добыча их когтей показывают не только силу, нужную для устранения закрепившейся угрозы, но и скорость, необходимую против воздушных налетчиков."}},faq={{q="Кто такой Руул Орлиный Коготь?",a="Руул Орлиный Коготь — опытный воин и наставник из таурен, живущий в Деревне Кровавого Копыта. Он обучает молодых искателей приключений и устраивает испытания, чтобы убедиться, что у них хватает силы, реакции и стойкости, прежде чем они отправятся в более опасные уголки Калимдора.",al={"ruul eagletalon","who gives dangers of the windfury","ruul","руул орлиный коготь","кто дает опасности ярости ветра","руул"}},{q="Где в Мулгоре обитают гарпии Ярости Ветра?",a="Гарпии Ярости Ветра гнездятся в юго-восточных горах Мулгора. Свои грубые гнезда они строят высоко на скалах и склонах предгорий, вдали от главной дороги, пересекающей долину.",al={"windfury harpy location","where are windfury harpies","windfury nest location","где гарпии ярости ветра","расположение гарпий ярости ветра","гнезда ярости ветра"}},{q="Почему гарпии Ярости Ветра считаются природными врагами таурен?",a="Гарпии — известные своей агрессивностью хищные падальщики, защищающие свои территории и нападающие на всех, кто приближается к их гнездам. В Мулгоре стая Ярости Ветра славится ненасытной тягой к свежему мясу и неослабной злобой к путникам и пасущимся животным, из-за чего постоянно угрожает равнинам.",al={"why do tauren fight harpies","harpy threat mulgore","windfury lore","почему таурены сражаются с гарпиями","угроза гарпий мулгор","предания ярости ветра"}},{q="Какое доказательство требует Руул Орлиный Коготь после охоты?",a="Руул просит искателей приключений добыть восемь когтей Ярости Ветра прямо с убитых гарпий. Отсечь и принести эти когти — значит показать мастерство против основного природного оружия гарпий.",al={"dangers of the windfury proof","what to collect for ruul","windfury quest objective","доказательство опасности ярости ветра","что собрать для руула","цель задания ярости ветра"}},{q="Почему искатели приключений должны пройти это испытание перед уходом из Мулгора?",a="Руул считает свирепых гарпий Ярости Ветра идеальной мерой боевой готовности. Если искатель приключений не справляется со скоростью, яростью и когтями гарпии, у него мало шансов против более смертельных опасностей за оборонительными утесами Мулгора.",al={"purpose of the trial","why do dangers of the windfury","ruul's test","цель испытания","зачем опасности ярости ветра","испытание руула"}},{q="Где находится Деревня Кровавого Копыта?",a="Деревня Кровавого Копыта расположена в центральной части Мулгора у Озера Каменного Быка, к югу от Великих врат и Громового Утеса. Это главный центр культуры, торговли и обучения для таурен, путешествующих по равнинам.",al={"bloodhoof village location","where is bloodhoof","ruul location","где деревня кровавого копыта","где кровавое копыто","где руул"}}},fp="23,364,22.435.0,19.451.0,23.275.0,48.204.0,70.299.0,53.188.0,63.257.0,35.220.0"}
P.entries["quest:745"] = {n="Недобрые соседи",s="Это задание выдает Бейн Кровавое Копыто в Деревне Кровавого Копыта. Оно посылает юных искателей приключений из Орды сдержать разрушительное браконьерство местных гноллов Бледногривов. Истребляя их кожевников, свежевателей и браконьеров, вы защищаете дикую природу Мулгора и постигаете философию тауренов — жить в равновесии с Матерью-Землей.",h="Это задание выдает Бейн Кровавое Копыто в Деревне Кровавого Копыта.",kw={"baine bloodhoof","bloodhoof village","gnolls","mulgore","palemane","poachers","sharing the land","skinners","tanners","бейн кровавое копыто","деревня кровавого копыта","гноллы","мулгор","бледногривы","браконьеры","недобрые соседи","свежеватели","кожевники"},ang={["class:Druid"]="Друиды понимают, что безнаказанное браконьерство нарушает дух равнин и требует немедленного вмешательства, чтобы исцелить гармонию этой земли.",["class:Hunter"]="Свежеватели и браконьеры Бледногривов — противоположность настоящего охотника: они жестоко и расточительно убивают диких существ вместо того, чтобы уважать их.",["faction:Horde"]="Помощь Бейну Кровавому Копыту укрепляет связь между новыми искателями приключений из Орды и руководством юного народа тауренов.",["race:Tauren"]="Для молодых тауренов отклик на призыв Бейна — важный шаг к пониманию священного долга защищать Мулгор и чтить равновесие Матери-Земли."},sec={{t="Земля вне равновесия",b="Таурены глубоко почитают природу, берут от нее лишь необходимое для выживания и чтят Мать-Землю во всем. Гноллы Бледногривы, поселившиеся к югу от Деревни Кровавого Копыта и в пещере на западе, не питают такого уважения. Вместо умеренной охоты они жестоко истребляют зверей по всей равнине, оставляя за собой освежеванные туши и нарушенное равновесие природы. Для народа, стремящегося построить мирный дом в Мулгоре, эта бездумная бойня недопустима."},{t="Когда слова бессильны",b="Бейн Кровавое Копыто сначала надеялся решить дело миром и пытался начать переговоры с наступающими гноллами. Бледногривы отвергли все попытки, ответив на дипломатию враждебностью и продолжением разорения. Видя, что переговоры бесполезны, Бейн прибегает к силе. Юных воинов отправляют прямо в охотничьи лагеря, чтобы покончить с браконьерами, кожевниками и свежевателями, пока степи не получили непоправимый урон."},{t="Круг жизни и смерти",b="Это поручение — обряд посвящения и нравственный урок для растущих защитников. Когда искатель приключений возвращается с истребления, Бейн напоминает ему, что отнимать жизнь нужно не из злобы, а по необходимости, ради сохранения гармонии. Жизнь и смерть образуют единый круг, где одно не может существовать без другого, — это основополагающая истина, которую должен нести каждый защитник Мулгора."}},faq={{q="Кто выдает это задание?",a="Бейн Кровавое Копыто, сын верховного вождя Кэрна Кровавого Копыта, выдает это задание в Деревне Кровавого Копыта в центре Мулгора.",al={"quest giver","who starts sharing the land","baine quest","персонаж, выдающий задания","кто начинает недобрые соседи","задание бейна"}},{q="Почему таурены нацелились на гноллов Бледногривов?",a="Гноллы Бледногривы безрассудно охотятся на животных Мулгора и истощают стада, не чтя природное равновесие. Они также отвергли все попытки тауренов наладить мирный диалог.",al={"why kill gnolls","palemane problem","what did gnolls do","зачем убивать гноллов","проблема бледногривов","что сделали гноллы"}},{q="Где находятся эти гноллы?",a="Бледногривы устроили лагеря к югу от Деревни Кровавого Копыта и обитают в системе пещер Утеса Бледногривов на западе.",al={"gnoll locations","palemane camp","where to find palemanes","где гноллы","лагерь бледногривов","где найти бледногривов"}},{q="Пытались ли таурены сначала договориться о мире?",a="Да. Бейн отмечает, что таурены не раз пытались наладить общение и поделить землю, но гноллы с презрением отвергли все мирные предложения.",al={"did tauren talk to gnolls","palemane diplomacy","говорили ли таурены с гноллами","дипломатия бледногривов"}},{q="Какому уроку Бейн пытается научить?",a="Бейн хочет, чтобы юные защитники поняли: смерть и жизнь образуют нерушимый круг. Хотя порой приходится отнимать жизнь ради защиты равновесия, делать это нужно всегда с глубоким уважением к Матери-Земле.",al={"baine lesson","meaning of sharing the land","урок бейна","смысл недобрые соседи"}},{q="Кто такие гноллы Бледногривы?",a="Это примитивное гиеноподобное племя, обитающее в Мулгоре. Оно известно бледным мехом, территориальной агрессией и полным пренебрежением к гармонии равнин.",al={"who are palemanes","palemane tribe","кто такие бледногривы","племя бледногривов"}}},fp="16,309,21.523.0,15.429.0,28.396.0,21.114.0,49.178.0,31.122.0,39.155.0,42.222.0,28.160.0"}
P.entries["quest:746"] = {n="Дворфийские делишки",s="«Дворфийские делишки» — задание в Мулгоре, которое выдает Бейн Кровавое Копыто в Деревне Кровавого Копыта. Опасаясь, что раскопки дворфов разъярят местных зверей и осквернят священную землю, Бейн поручает юным защитникам Орды сорвать их работу: отобрать и разбить их кирки.",h="«Дворфийские делишки» — задание в Мулгоре, которое выдает Бейн Кровавое Копыто в Деревне Кровавого Копыта.",kw={"baine bloodhoof","bloodhoof village","dwarf","forge","kodo","mulgore","picks","prospector","бейн кровавое копыто","деревня кровавого копыта","дворф","горн","кодо","мулгор","кирки","старатель"},ang={["class:Shaman"]="Шаманы понимают: тревожить недра неосторожными раскопками — значит нарушать равновесие стихий и вызывать беспокойство среди духов и существ земли.",["faction:Horde"]="Вторжение лояльных Альянсу дворфов в сердце земель Орды подрывает хрупкий мир, установленный после Третьей войны, и демонстрирует явное пренебрежение границами племен.",["profession:Mining"]="Шахтеры почитают богатства, скрытые в камне, но методы дворфов в Мулгоре лишены уважения и гармонии и ведут к бездумному разрушению.",["race:Tauren"]="Тело Матери-Земли священно, и вид чужаков, буравящих холмистые степи Мулгора, — оскорбление, требующее немедленного и твердого ответа."},sec={{t="Незваные гости в холмах",b="К северо-западу от Деревни Кровавого Копыта дворфы-старатели начали обустраивать место раскопок среди холмов Мулгора. Лига исследователей и ее землекопы ищут по всему Калимдору реликвии титанов и тайны земли, но их работа редко уважает земли и обычаи коренных жителей. Для тауренов земля — живая мать, которую следует почитать, а не истощать и выдалбливать ради камня и металла."},{t="Защита священной земли",b="Бейн Кровавое Копыто понимает, что дворфийские машины и беспрестанные взрывы угрожают хрупкой гармонии равнин. Помимо разрушений, шум тревожит местных зверей и приводит кодо равнин в ярость. Разбив инструменты старателей у их же горнов, таурены надеются послать недвусмысленное предупреждение и остановить вторжение, пока не нанесен непоправимый вред."}},faq={{q="Зачем дворфы копают в Мулгоре?",a="Дворфы-старатели считают, что в недрах центрального Калимдора скрыты тайны и артефакты. Однако пренебрежение к землям племен и разрушительные методы добычи привели их к прямому конфликту с тауренами.",al={"dwarves in mulgore","why are prospectors here","dwarven excavation mulgore","дворфы в мулгоре","зачем здесь старатели","дворфийские раскопки мулгор"}},{q="Кто выдает задание «Дворфийские делишки»?",a="Задание выдает Бейн Кровавое Копыто, юный сын верховного вождя Кэрна Кровавого Копыта, в Деревне Кровавого Копыта в центре Мулгора.",al={"quest giver dwarven digging","who starts dwarven digging","кто выдает задание дворфийские делишки","кто начинает дворфийские делишки"}},{q="Почему Бейн хочет разбить инструменты, а не просто украсть?",a="Бейн хочет сделать снаряжение совершенно бесполезным, чтобы немедленно остановить раскопки. Уничтожение инструментов в горнах — ясное символическое и практическое послание: земля не раскроет свои тайны грубой силе и осквернению.",al={"why break the picks","smashing dwarven tools","зачем ломать кирки","разбить дворфийские инструменты"}},{q="Как раскопки влияют на животных Мулгора?",a="Громкий стук и глубокие раны на земле сильно тревожат местных существ, особенно огромных кодо, бродящих по холмам, и мирные стада становятся раздражительными и агрессивными.",al={"angry kodos","why are beasts mad","злые кодо","почему звери злятся"}},{q="Где можно разбить кирки?",a="Кирки можно перековать в обломки в любом действующем горне. Можно воспользоваться горном прямо в лагере дворфов-раскопщиков или отнести кирки кузнецам в Громовом Утесе.",al={"where is the forge","smash prospector picks forge","где горн","разбить кирки старателей в горне"}},{q="Связано ли это задание с общим присутствием Лиги исследователей в Калимдоре?",a="Да. Дворфийские экспедиции из Стальгорна основали форпосты по всему Калимдору, включая Мулгор, Степи и южный Калимдор, и нередко затевают стычки с расами Орды из-за власти над землями и священными местами.",al={"explorers league mulgore","ironforge in kalimdor","лига исследователей мулгор","стальгорн в калимдоре"}}},fp="15,289,24.392.0,26.388.0,35.232.0,36.137.0,63.245.0,52.187.0,31.201.0,75.232.0"}
P.entries["quest:747"] = {n="Охота начинается",s="«Охота начинается» — основополагающий обряд посвящения для юных искателей приключений в Лагере Нараче на Плато Красного Облака. По поручению Грулла Соколиного Ветра новички отправляются охотиться на местных степных ходоков, чтобы добыть мясо и перья для поселения. Это задание — первый шаг к уважению вождя Соколиного Ветра и будущему доступу в Громовой Утес.",h="«Охота начинается» — основополагающий обряд посвящения для юных искателей приключений в Лагере Нараче на...",kw={"camp narache","chief hawkwind","feathers","grull hawkwind","hunt begins","mulgore","plainstrider","red cloud mesa","лагерь нараче","вождь соколиный ветер","перья","грулл соколиный ветер","охота начинается","мулгор","степной ходок","плато красного облака"},ang={["class:Hunter"]="Выслеживание быстрых степных ходоков Плато Красного Облака — первое практическое упражнение в меткости, выслеживании и уважении к зверям, которые вас кормят.",["race:Tauren"]="Для юных шу'хало первая добыча — степной ходок плато — важный обряд посвящения: он подтверждает вашу связь с землей и долг кормить Лагерь Нараче."},sec={{t="Пропитание племени",b="На высотах Плато Красного Облака выживание и традиции неразделимы. Таурены охотятся по необходимости, чтобы кормить и одевать свой народ, а выслеживание и погоню считают также важным испытанием дисциплины и спортом. Когда запасы Лагеря Нараче оскудевают, община рассчитывает на молодежь, которая добудет свежее мясо ходоков для готовки и прочные перья для одежды племени."},{t="Заслужить признание",b="Ни один будущий герой не уйдет с Плато Красного Облака в просторы Мулгора, не доказав своей ценности. Грулл Соколиный Ветер — главный судья характера новичков, и он настаивает, что нужно доказать свои способности, прежде чем предстать перед его отцом, вождем Соколиным Ветром. Удачная охота показывает не только самостоятельность, но и преданность делу племени."}},faq={{q="Кто выдает это задание?",a="Это задание выдает Грулл Соколиный Ветер в Лагере Нараче. Он сын предводителя поселения, вождя Соколиного Ветра, и наставник молодых охотников и искателей приключений на Плато Красного Облака.",al={"quest giver","who starts the hunt begins","grull hawkwind","персонаж, выдающий задания","кто начинает охота начинается","грулл соколиный ветер"}},{q="Почему охотятся именно на степных ходоков, а не на других зверей?",a="Степных ходоков на плато много, и они дают питательное мясо, чтобы пополнить скудеющие запасы, и прочные перья для традиционной одежды и украшений тауренов.",al={"why plainstriders","plainstrider meat and feathers","hunting plainstriders","почему степные ходоки","мясо и перья ходоков","охота на ходоков"}},{q="Почему я должен доказывать свою ценность, прежде чем увижу вождя Соколиного Ветра?",a="Общество тауренов высоко ценит практическую пользу и охотничье мастерство. Грулл Соколиный Ветер требует от новичков показать навыки выживания и верность поселению, прежде чем вождь примет их и доверит им более важные дела.",al={"why prove to chief hawkwind","chief hawkwind approval","why hunt first","зачем доказывать вождю соколиному ветру","одобрение вождя соколиного ветра","почему сначала охота"}},{q="Какова общая цель этих испытаний на Плато Красного Облака?",a="Плато служит испытательной площадкой. Когда молодой таурен докажет свои способности вождю Соколиному Ветру и старейшинам Лагеря Нараче, он считается готовым спуститься в просторы Мулгора и войти в столицу — Громовой Утес.",al={"mesa trials purpose","why am i on red cloud mesa","leaving red cloud mesa","цель испытаний плато","почему я на плато красного облака","покинуть плато красного облака"}},{q="Что будет после этой охоты?",a="Если принести мясо и перья, Грулл одобрит это, и начнется задание «Охота продолжается», в котором новички выслеживают более крупную и неуловимую дичь на плато.",al={"next quest","followup","what is after the hunt begins","следующее задание","продолжение","что после охота начинается"}},{q="Охотятся ли таурены только ради выживания?",a="Хотя пропитание и ресурсы вроде кожи, кости и перьев необходимы, таурены также охотятся ради спорта и духовного единения, оттачивая чутье, которое делает племена бдительными и сильными.",al={"tauren hunting philosophy","hunt for sport","why do tauren hunt","философия охоты тауренов","охота ради спорта","зачем таурены охотятся"}}},fp="15,361,20.383.0,19.382.0,21.181.0,53.182.0,59.252.0,59.239.0,27.181.0,33.203.0"}
P.entries["quest:748"] = {n="Отравленная вода",s="Задание «Отравленная вода» открывает усилия таурен по очищению священных колодцев Мулгора от загрязнения. Муллу Громовому Рогу в Деревне Кровавого Копыта помогают молодые защитники Орды: они собирают в степях природные компоненты, чтобы создать целительный ритуальный тотем.",h="Задание «Отравленная вода» открывает усилия таурен по очищению священных колодцев Мулгора от загрязнения.",kw={"bloodhoof village","cleansing totem","mulgore","mull thunderhorn","plainstrider","poison water","prairie wolf","winterhoof water well","деревня кровавого копыта","тотем очищения","мулгор","мулл громовой рог","бегун по равнинам","отравленная вода","луговой волк","колодец заиндевевшего копыта"},ang={["class:Druid"]="Отравление чистых источников гоблинами — прямое нападение на природное равновесие, требующее немедленного ответа ради защиты хрупкой флоры и фауны Мулгора.",["class:Shaman"]="Очищение отравленных вод с помощью тотемов, наделенных силой зверей, показывает основы шаманства таурен: работать вместе с местной природой, чтобы исправлять нарушения стихий.",["race:Tauren"]="Осквернение чистой воды бьет в самую суть даров Матери-Земли, поэтому обряд очищения — основной долг любого тауренна, достигшего зрелости в Мулгоре."},sec={{t="Оскверненная земля",b="Травянистые равнины Мулгора — священная земля для таурен, но коварные силы начали угрожать их жизненно важному источнику. Мулл Громовой Рог, старейшина Деревни Кровавого Копыта, обнаруживает, что гоблины-чужаки и их прихвостни отравили драгоценные колодцы, которые поддерживают жизнь племен и местных животных. Загрязнение бьет прямо в духовное сердце кочевого народа, недавно поселившегося здесь."},{t="Сбор природной сущности",b="Чтобы противостоять промышленным загрязнениям, Мулл полагается на традиционное шаманство таурен, а не на грубые средства. Для очищения Колодца Заиндевевшего Копыта нужно создать мощный ритуальный тотем, наполненный жизненной силой коренных хищников Мулгора. Он посылает охотников добыть лапы луговых волков и когти взрослых бегунов по равнинам на юго-западных равнинах, призывая силу земли исцелить собственные раны."}},faq={{q="Кто отравил колодцы в Мулгоре?",a="За осквернение священных водопоев по всему Мулгору отвечают гоблины-захватчики и их наемники. Их разрушительная промышленная деятельность и пренебрежение природным равновесием угрожают и племенам таурен, и местным животным.",al={"who tainted the wells","who poisoned mulgore","who polluted the water","кто осквернил колодцы","кто отравил мулгор","кто загрязнил воду"}},{q="Зачем Муллу Громовому Рогу нужны волчьи лапы и когти бегунов по равнинам?",a="Мулл создает традиционные очищающие тотемы из частей местных зверей Мулгора. Используя природных духов и силу хищников равнин, он создает фокус, достаточно мощный для ритуала очищения воды.",al={"why wolf paws","why plainstrider talons","totem materials","зачем волчьи лапы","зачем когти бегуна по равнинам","материалы для тотема"}},{q="Какой колодец готовится очистить это задание?",a="В этом задании собирают материалы специально для создания очищающего тотема для Колодца Заиндевевшего Копыта — первого в череде загрязненных колодцев, которым требуется ритуальное очищение.",al={"what well is this for","which water well","для какого колодца это","какой колодец"}},{q="Где находится Мулл Громовой Рог?",a="Мулл Громовой Рог живет в Деревне Кровавого Копыта — главном поселении таурен в центральной части Мулгора, у вод Озера Каменного Быка.",al={"mull thunderhorn location","where is mull","where to turn in poison water","где мулл громовой рог","где мулл","куда сдать отравленная вода"}},{q="Где найти нужных волков и бегунов по равнинам?",a="Луговые волки и взрослые бегуны по равнинам бродят по холмистым равнинам к юго-западу от Деревни Кровавого Копыта.",al={"where to find prairie wolves","plainstrider location","hunting grounds","где найти луговых волков","где бегуны по равнинам","места охоты"}},{q="Что произойдет после того, как Мулл получит лапы и когти?",a="Мулл соединяет собранные компоненты в Тотем очищения колодца Заиндевевшего Копыта и поручает вам отнести его прямо к Колодцу Заиндевевшего Копыта, чтобы провести обряд очищения.",al={"next quest after poison water","what do i do next","следующее задание после отравленная вода","что делать дальше"}}},fp="12,238,17.428.0,26.435.0,40.234.0,65.236.0,46.172.0,34.141.0,58.96.0,53.172.0"}
P.entries["quest:749"] = {n="Разграбленный караван",s="Морин Ловец Облаков направляет путников осмотреть обломки разгромленного каравана Торговой Компании у северного берега Озера Каменного Быка. Хотя таурены сожгли обоз в отместку за павших товарищей, гоблины-старатели вернулись за уцелевшим грузом. Осмотр уцелевших ящиков с припасами показывает истинный промышленный размах деятельности Торговой Компании в Мулгоре.",h="Морин Ловец Облаков направляет путников осмотреть обломки разгромленного каравана Торговой Компании у...",kw={"morin cloudstalker","mulgore","ravaged caravan","stonebull lake","supply crate","venture co","venture company","морин ловец облаков","мулгор","разграбленный караван","озеро каменного быка","ящик с припасами","торговая компания"},ang={["faction:Horde"]="Бесконтрольная корпоративная экспансия в Мулгор угрожает стабильности Громового Утеса, и разведчикам Орды необходимо нарушать снабжение Торговой Компании.",["profession:Mining"]="Прочные ящики и заметки о снабжении показывают, что Торговая Компания ведет по всему Мулгору активную разведку и добычу полезных ископаемых.",["race:Tauren"]="Осквернение равнин машинами Торговой Компании и вырубка леса бьют прямо по земле ваших предков, поэтому возврат и уничтожение их припасов жизненно важны для защиты Мулгора."},sec={{t="Возмездие у озера",b="Обугленные остатки на северном берегу Озера Каменного Быка — результат быстрого удара таурен. Скорбя о двух товарищах, погибших в недавней стычке, Морин Ловец Облаков и его воины устроили засаду на вооруженный обоз Торговой Компании. Желая уничтожить плоды трудов чужаков, таурены сожгли повозки и оставили дымящиеся руины, полагая, что огонь поглотит все, что гоблины хотели увезти."},{t="Незаконченное дело",b="Вскоре таурены заметили, что старатели Торговой Компании роются в почерневших обломках, а значит, огонь не уничтожил самый важный груз. Не желая слепо рисковать жизнями, Морин посылает разведчиков осмотреть место. Среди закопченных обломков лежат целые ящики с эмблемой горного отдела Торговой Компании, упакованные и предназначенные для центральных перерабатывающих мощностей."}},faq={{q="Почему караван был уничтожен?",a="Морин Ловец Облаков и его воины-таурены напали на караван из засады и сожгли его в отместку за двух разведчиков, погибших в прежней стычке с Торговой Компанией.",al={"who destroyed the caravan","why is the caravan burned","caravan attack","кто уничтожил караван","почему караван сожжен","нападение на караван"}},{q="Где находится Разграбленный караван?",a="Сожженные повозки стоят на северном берегу Озера Каменного Быка, к востоку от Деревни Кровавого Копыта в Мулгоре.",al={"caravan location","where is the caravan","ravaged caravan spot","где караван","расположение каравана","разграбленный караван"}},{q="Почему гоблины возвращаются к обломкам?",a="Торговая Компания отправила старателей, потому что огонь уничтожил не весь груз. Они пытаются забрать прочные ящики с припасами, помеченные для отправки на их центральные перерабатывающие предприятия.",al={"why are salvagers here","venture co salvagers","what do the goblins want","зачем здесь старатели","старатели торговой компании","что нужно гоблинам"}},{q="Что лежит в ящиках с припасами?",a="На ящиках стоит эмблема горного отдела Торговой Компании; внутри — минеральные ресурсы, предназначенные для очистки и переработки на их главных промышленных предприятиях.",al={"crate contents","what is in the crate","sealed supply crate","содержимое ящика","что в ящике","запечатанный ящик с припасами"}},{q="Кто такой Морин Ловец Облаков?",a="Морин Ловец Облаков — таурен-разведчик и следопыт, находящийся к востоку от Деревни Кровавого Копыта. Он следит за вражескими вторжениями в центральный Мулгор, в особенности со стороны Торговой Компании.",al={"who is morin","morin cloudstalker role","кто такой морин","морин ловец облаков роль"}},{q="Что этот караван говорит о Торговой Компании?",a="Он показывает, что присутствие Торговой Компании в Мулгоре — не просто разведывательный отряд, а организованная промышленная добыча с вооруженными линиями снабжения и централизованной сетью переработки.",al={"venture co mulgore presence","why are goblins in mulgore","торговая компания в мулгоре","почему гоблины в мулгоре"}}},fp="19,390,23.438.0,19.408.0,30.169.0,37.102.0,46.197.0,33.171.0,26.190.0,56.201.0"}
P.entries["quest:7493"] = {n="Все еще только начинается!",s="«Все еще только начинается!» — задание Орды, которое выдают в Оргриммаре опытным кожевникам после победы над Ониксией. Властитель Рунтак признает мастерство героя и обучает редкому способу изготовления защитных плащей из чешуи матери драконов. Это важное ремесло готовит Орду к смертоносному пламени Вершины Черной горы.",h="«Все еще только начинается!» — задание Орды, которое выдают в Оргриммаре опытным кожевникам после победы над...",kw={"blackrock","broodmother","cloak","leatherworking","natoj","nefarian","onyxia","scale","черная гора","мать драконов","плащ","кожевничество","нефариан","ониксия","чешуя"},ang={["faction:Horde"]="Для Орды защитное снаряжение, выкованное из павших врагов, жизненно важно для защиты войск от новых драконьих разрушений."},sec={{t="Наследие матери драконов",b="Падение Ониксии — триумф Орды, но не конец угрозы со стороны черного драконьего рода. Чешуйчатая шкура матери драконов обладает замечательной стойкостью к драконьему пламени. Чтобы такие материалы не пропали зря, руководство Орды ищет мастеров, способных превратить останки дракона в защитные доспехи."},{t="Щит от пламени Тени",b="Властитель Рунтак учит одаренных кожевников сшивать Плащ из чешуи Ониксии. Эти знания нужны не для показа или престижа. В глубине Черной горы брат Ониксии, Нефариан, обладает разрушительным пламенным дыханием. Без зачарованной защиты из чешуи собственной матери любой авангард, выступивший против Владыки Черной горы, обратился бы в пепел."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Властитель Рунтак в Оргриммаре. Он признает защитников Орды, владеющих мастерством кожевника высшего уровня и помогавших в низвержении Ониксии.",al={"natoj quest giver","where is overlord natoj","quest start","кто выдает задание","где властитель рунтак","начало задания"}},{q="Что нужно для получения этого задания?",a="Это задание предлагают только опытным кожевникам, которые выполнили одно из заданий, следующих за победой над Ониксией, например «Победа Орды» или «Весьма загадочное обстоятельство».",al={"leatherworking requirement","how to get quest","prerequisites","требование кожевничества","как получить задание","необходимые условия"}},{q="Чему учит Властитель Рунтак?",a="Властитель Рунтак обучает кожевника способу изготовления Плаща из чешуи Ониксии из чешуи, собранной с павшей матери драконов.",al={"quest reward recipe","onyxia cloak pattern","what do i learn","рецепт награды","выкройка плаща ониксии","что я изучу"}},{q="Почему важен Плащ из чешуи Ониксии?",a="Плащ защищает владельца от смертоносного пламенного дыхания Нефариана, Владыки Черной горы. Без его особых защитных свойств встреча с повелителем рода была бы смертельной.",al={"why make cloak","cloak purpose","nefarian cloak","зачем делать плащ","назначение плаща","плащ от нефариана"}},{q="Кто такой Владыка Черной горы?",a="Владыка Черной горы — Нефариан, могучий черный дракон и брат Ониксии, который строит планы с высот Черной горы, чтобы подчинить смертные расы.",al={"who is lord of blackrock","nefarian identity","blackrock lord","кто такой владыка черной горы","кто такой нефариан","владыка черной горы"}},{q="Почему в названии задания сказано, что все только начинается?",a="Хотя Ониксия убита, более широкая война против черного драконьего рода и замыслы Нефариана внутри Черной горы лишь обострились.",al={"meaning of title","journey just begun why","значение названия","почему все только начинается"}}},fp="26,347,22.359.0,27.396.1,49.178.0,49.183.0,33.152.0,40.186.0,29.159.0,57.145.0"}
P.entries["quest:7497"] = {n="Все еще только начинается!",s="Это задание — заслуженное признание опытного мастера после победы над Ониксией. Майор Маттингли передает важный способ изготовления Плаща из чешуи Ониксии, превращая останки павшей матери драконов в необходимую защиту от ее брата.",h="Это задание — заслуженное признание опытного мастера после победы над Ониксией.",kw={"black dragonflight","blackrock","leatherworking","major mattingly","nefarian","onyxia","onyxia scale cloak","stormwind","черный драконий род","черная гора","кожевничество","майор маттингли","нефариан","ониксия","плащ из чешуи ониксии","штормград"},ang={["faction:Alliance"]="Это задание связывает нелегкую победу Штормграда над Ониксией с грядущим наступлением на ее брата Нефариана в Черной горе."},sec={{t="Редкое мастерство",b="Многие герои могут претендовать на победу над матерью драконов Ониксией, но лишь немногие сочетают боевую доблесть и мастерство кожевника высшего уровня, необходимое для работы с ее прочной шкурой. Когда герой с такими талантами докладывает Майору Маттингли в Штормграде, офицер признает, как важны эти ремесленные навыки для грядущих сражений."},{t="Защита от черного драконьего рода",b="Смерть Ониксии не отменяет угрозы черного драконьего рода. Маттингли учит мастера обрабатывать и сшивать чешую матери драконов в Плащ из чешуи Ониксии. Эта уникальная вещь дает особую защиту от разрушительного пламенного дыхания брата Ониксии, Нефариана, Владыки Черной горы."}},faq={{q="Кто выдает задание «Все еще только начинается!»?",a="Майор Маттингли в Штормграде выдает это задание героям Альянса, проявившим себя в походе против Ониксии и владеющим кожевничеством высшего уровня.",al={"who gives the journey has just begun","where to get journey has just begun","journey has just begun quest giver","кто дает все еще только начинается","где взять все еще только начинается","выдающий задание все еще только начинается"}},{q="Чему учит это задание?",a="Выполнение задания обучает мастеров-кожевников рецепту Плаща из чешуи Ониксии — вещи, созданной специально из чешуи Ониксии.",al={"what recipe do i get","onyxia cloak recipe","reward for journey has just begun","какой рецепт я получу","рецепт плаща ониксии","награда за все еще только начинается"}},{q="Почему нужен Плащ из чешуи Ониксии?",a="Плащ особо обработан, чтобы защищать владельца от смертоносного пламенного дыхания Нефариана, Владыки Черной горы, и потому незаменим в борьбе с оставшимися предводителями черного драконьего рода.",al={"why do i need onyxia cloak","what is onyxia scale cloak for","shadow flame protection","зачем нужен плащ ониксии","для чего плащ из чешуи ониксии","защита от пламени тени"}},{q="Кто такой Владыка Черной горы, упомянутый Майором Маттингли?",a="Владыка Черной горы — Нефариан, могучий черный дракон и брат Ониксии. Он правит Вершиной Черной горы и продолжает замыслы черного драконьего рода.",al={"who is lord of blackrock","who is nefarian","mattingly dragon warning","кто такой владыка черной горы","кто такой нефариан","предупреждение маттингли о драконе"}},{q="Почему герой должен быть кожевником, чтобы получить эти знания?",a="Способы добычи, закалки и сшивания драконьей чешуи без потери ее природной магической защиты требуют высокого мастерства опытного кожевника.",al={"why leatherworking only","can anyone get this quest","leatherworker requirement","почему только кожевничество","кто может получить задание","требование кожевника"}},{q="Покончила ли смерть Ониксии с угрозой черных драконов для Штормграда?",a="Нет. Хотя сама Ониксия убита, ее брат Нефариан по-прежнему повелевает Черной горой и продолжает плести заговоры против Альянса и смертных рас.",al={"is stormwind safe now","onyxia dead what next","black dragonflight after onyxia","безопасен ли штормград","ониксия мертва что дальше","черный драконий род после ониксии"}}},fp="26,276,14.360.0,41.323.1,48.169.0,27.153.0,40.206.0,58.168.0,63.179.0,65.161.1"}
P.entries["quest:75"] = {n="Легенда о Сталване",s="Расследование дела Сталвана Мистмантла выводит из Сумеречного леса к уединенному дому на юго-востоке Элвиннского леса. Маршал Хаггард, пожилой ветеран с ослабевшим зрением, направляет вас к сундуку наверху, где лежит старая пачка бумаг, оставшаяся с тех пор, как он поселился в доме.",h="Расследование дела Сталвана Мистмантла выводит из Сумеречного леса к уединенному дому на юго-востоке...",kw={"duskwood","elwynn forest","faded journal page","forlorn spirit","marshal haggard","stalvan","сумеречный лес","элвиннский лес","выцветшая страница дневника","неприкаянный дух","маршал хаггард","сталван"},ang={["faction:Alliance"]="Раскрытие наследия Сталвана обнажает мрачные страницы прошлого, тихо скрытые в мирных пасторальных землях Элвиннского леса.",["race:Human"]="Путь Сталвана пролегает через обычные человеческие поселения — это поучительная история об одиночестве и злобе, скрытых на виду."},sec={{t="Чердак ветерана",b="Маршал Хаггард живет вдали от города, на юго-восточной окраине Элвиннского леса, неподалеку от границ Сумеречного леса и Красногорья. Когда он поселился в уединенном доме, то нашел наверху спрятанный сундук, набитый старыми пергаментами. Из-за слабеющего зрения он оставил попытки их прочесть, и документы лежали нетронутыми, пока не пришел следователь с вопросами о Сталване."},{t="Неупокоенные тени",b="Бумаги в сундуке наверху — не обычный домашний хлам. Вторжение в вещи Сталвана обычно будоражит беспокойную магию и вызывает Неприкаянного духа, связанного с прошлым Мистмантла. Спрятанная внутри страница дневника — прямая запись личных мыслей Сталвана и веское доказательство того, что замкнутый ученый оставил след в Элвиннском лесу, прежде чем исчезнуть."}},faq={{q="Кто такой маршал Хаггард?",a="Маршал Хаггард — пожилой почти слепой ветеран, тихо живущий в уединенной хижине на юго-востоке Элвиннского леса. У него хранятся давно забытые бумаги Сталвана Мистмантла, найденные в его доме.",al={"marshal haggard","haggard elwynn","who is haggard","маршал хаггард","хаггард элвиннский лес","кто такой хаггард"}},{q="Почему след привел обратно в Элвиннский лес?",a="Улики, собранные в Темнолесье и Луноречье, прослеживают путь Сталвана по югу земель Штормграда. В усадьбе Хаггарда остались старые вещи, которые Сталван выбросил или бросил до того, как впал в безумие.",al={"why elwynn forest","stalvan elwynn","why go to haggard","почему элвиннский лес","сталван элвиннский лес","зачем идти к хаггарду"}},{q="Что лежит в сундуке наверху?",a="В сундуке лежит выцветшая страница дневника, написанная Сталваном Мистмантлом, среди связки пергаментов, которые Хаггард так и не смог как следует рассмотреть.",al={"upstairs chest","faded journal page","what is in the chest","сундук наверху","выцветшая страница дневника","что в сундуке"}},{q="Почему при открытии сундука нападает дух?",a="Неприкаянный дух преследует реликвии прежней жизни Сталвана и яростно проявляется, когда посторонний тревожит его личные записи и воспоминания.",al={"forlorn spirit","why ghost attacks","ghost in haggard house","неприкаянный дух","почему нападает призрак","призрак в доме хаггарда"}},{q="Как это продвигает расследование дела Сталвана?",a="Выцветшая страница — свидетельство из первых рук, написанное рукой самого Сталвана. Она помогает восстановить трагическую хронологию его службы, безответной одержимости и последовавшей череды убийств.",al={"stalvan mystery","what does the page reveal","stalvan questline step","тайна сталвана","что раскрывает страница","цепочка заданий сталвана"}},{q="Почему маршал Хаггард не смог прочесть бумаги сам?",a="Зрение Хаггарда с возрастом затуманилось и ослабло, и он не может разобрать мелкий или стершийся почерк на выцветших документах.",al={"haggard blind","why haggard needs help","хаггард слепой","почему хаггарду нужна помощь"}}},fp="21,280,17.391.0,17.382.1,23.216.0,45.212.0,34.157.0,50.144.0,48.172.1,53.140.0"}
P.entries["quest:751"] = {n="Разграбленный караван",s="Осмотр разбитого каравана в Мулгоре показывает, что гоблины-промышленники незаконно закрепились на землях тауренов. Разведчики достали документы из запертого ящика и подтвердили, что Торговая Компания планомерно вычерпывает минеральные богатства края. Это открытие побуждает Бегунов Кровавого Копыта встать на активную оборону родных равнин.",h="Осмотр разбитого каравана в Мулгоре показывает, что гоблины-промышленники незаконно закрепились на землях...",kw={"bloodhoof village","morin cloudstalker","mulgore","outrunners","ravaged caravan","supply crate","venture co","venture co documents","деревня кровавого копыта","морин ловец облаков","мулгор","бегуны","разграбленный караван","ящик с припасами","торговая компания","документы торговой компании"},ang={["class:Druid"]="Для друидов равновесие земли священно, поэтому разрушительная, задымленная открытая добыча Торговой Компании — осквернение, которое необходимо очистить.",["faction:Horde"]="Орда полагается на верность и устойчивость Мулгора; если позволить чужеземным торговым картелям разорять его холмы, под угрозой окажется безопасность самого Громового Утеса.",["profession:Mining"]="Высокосортная руда в ящике доказывает, что восточные холмы Мулгора скрывают богатые подземные жилы, которые чужаки спешат захватить.",["race:Tauren"]="Для тауренов вид грубых промышленных машин, вгрызающихся в родные равнины Мулгора, — оскорбление Матери-Земли и акт войны против их недавно обретенного мира."},sec={{t="Свидетельства эксплуатации",b="Обломки разграбленного каравана к востоку от Деревни Кровавого Копыта рассказывают тревожную историю. В запертом ящике с припасами лежит плотный запас добытой руды и минералов, а также связка документов Торговой Компании. Эти бумаги — неопровержимое доказательство того, что алчная Торговая Компания начала самовольную добычу в безмятежных долинах Мулгора."},{t="Дозор Бегунов",b="Морин Ловец Облаков и другие Бегуны осторожно следят за границами Мулгора, остерегаясь чужаков, желающих поживиться за счет их мирной родины. Доставленные документы подтверждают худшие опасения Морина: дым над восточными предгорьями — знак растущего коммерческого вторжения. У тауренов нет выбора, кроме как дать отпор осквернителям, пока их холмы не выпотрошили целиком."}},faq={{q="Что лежит в запертом ящике с припасами?",a="Вскрыв ящик, вы найдете плотный набор добытой руды, сырых минералов и связку документов Торговой Компании с описанием ее деятельности.",al={"supply crate loot","what is in the crate","crate contents","добыча из ящика","что в ящике","содержимое ящика"}},{q="Кто такой Морин Ловец Облаков?",a="Морин Ловец Облаков — таурен-Бегун, стоящий на дороге к востоку от Деревни Кровавого Копыта в сторону границы Степей. Он патрулирует Мулгор и выслеживает внешние угрозы.",al={"who is morin","morin cloudstalker role","outrunner morin","кто такой морин","морин ловец облаков","бегун морин"}},{q="Почему Торговая Компания в Мулгоре?",a="Торговая Компания стремится безжалостно использовать богатые природные ресурсы и рудные жилы Мулгора, вгрызаясь в холмы без оглядки на землю и ее коренной народ.",al={"why are goblins here","venture co goal mulgore","what do goblins want","почему здесь гоблины","цель торговой компании мулгор","чего хотят гоблины"}},{q="Откуда шел караван?",a="Караван принадлежал Торговой Компании и вез добытую руду и рабочие бумаги из ее предгорных рудников, пока не был уничтожен на дороге.",al={"whose caravan was it","caravan origin","who attacked the caravan","чей это караван","происхождение каравана","кто напал на караван"}},{q="Куда ведет расследование дальше?",a="Получив документы, Морин Ловец Облаков направляет воинов прямо к руководству Торговой Компании, чтобы свернуть ее добычу в восточных предгорьях.",al={"what comes next","next quest after ravaged caravan","following up on the caravan","что дальше","следующее задание после разграбленного каравана","продолжение истории каравана"}},{q="Почему это угрожает тауренам?",a="Таурены считают землю священной и почитают Мать-Землю. Безрассудная открытая добыча и промышленные отходы Торговой Компании оскверняют нетронутые пейзажи Мулгора.",al={"why do tauren care","venture co threat","threat to mulgore","почему тауренам не все равно","угроза торговой компании","угроза мулгору"}}},fp="19,373,24.371.0,21.434.0,39.146.0,26.176.0,38.180.0,32.169.0,40.178.1,34.178.0"}
P.entries["quest:752"] = {n="Скромная просьба",s="Скромная просьба — один из первых обрядов долга, который дает вождь Соколиный Ветер в Лагере Нараче. Пока вождь занят неотложными делами племени на Плато Красного Облака, он просит молодого искателя приключений отправиться на юго-восток и проведать его престарелую мать у местного колодца. Просьба подчеркивает общинную ответственность, почтение к старшим и повседневную гармонию, важную для жизни тауренов.",h="Скромная просьба — один из первых обрядов долга, который дает вождь Соколиный Ветер в Лагере Нараче.",kw={"a humble task","camp narache","chief hawkwind","greatmother hawkwind","mulgore","red cloud mesa","water well","скромная просьба","лагерь нараче","вождь соколиный ветер","великая мать соколиный ветер","мулгор","плато красного облака","колодец"},ang={["faction:Horde"]="Тихий, пасторальный характер заданий Нараче показывает, как мирная общинная философия тауренов контрастирует с более суровой, выживальческой жесткостью остальной молодой Орды.",["race:Tauren"]="Для юных тауренов-воинов отклик на призыв вождя воплощает главные основы учения Матери-Земли: уважение к старшим и безоговорочную преданность общему благополучию племени."},sec={{t="Общинная гармония и долг",b="В тени Лагеря Нараче от каждого члена племени ждут, что он внесет свой вклад в гармонию жизни. Для молодых тауренов, вступающих во взрослую жизнь, долг перед племенем измеряется не только боевой доблестью в схватках со свинобразами и хищниками: он начинается с простой социальной ответственности. Вождь Соколиный Ветер показывает это на деле: прикованный к посту управлением и обороной, он доверяет начинающим искателям приключений присмотр за уязвимыми старейшинами общины."},{t="Колодец к юго-востоку от Нараче",b="Плато Красного Облака в Мулгоре полагается на природные колодцы, разбросанные за пределами лагеря. Рано утром Великая Мать Соколиный Ветер ушла из деревни, чтобы набрать свежей воды из юго-восточного источника. В краю, где бродят территориальные звери и подступают свинобразы-Дыбогривы, отсутствие старейшины в течение нескольких часов вызывает тихую тревогу, и Соколиный Ветер посылает помощь, чтобы убедиться, что она невредима."}},faq={{q="Кто дает это задание и где его найти?",a="Задание дает вождь Соколиный Ветер, предводитель Лагеря Нараче на Плато Красного Облака в Мулгоре. Он стоит в центральном шатре лагеря и руководит местными делами.",al={"who gives a humble task","where to pick up quest","chief hawkwind location","кто дает скромную просьбу","где взять задание","где вождь соколиный ветер"}},{q="Где находится Великая Мать Соколиный Ветер?",a="Великая Мать Соколиный Ветер находится к юго-востоку от Лагеря Нараче: она хлопочет у колодца на нижнем уступе плато.",al={"greatmother hawkwind location","where is the mother","water well location","где великая мать соколиный ветер","где мать вождя","где колодец"}},{q="Почему вождь Соколиный Ветер не проведает мать сам?",a="Вождь Соколиный Ветер должен оставаться в Лагере Нараче, чтобы заниматься неотложными делами племени и наставлять молодых воинов. Как вождь, он опирается на общую ответственность племени и доверяет подающим надежды искателям приключений заботу о делах деревни.",al={"why cant chief go","why doesn't hawkwind check","chief hawkwind busy","почему вождь не может пойти","почему соколиный ветер не проверит","вождь соколиный ветер занят"}},{q="Грозит ли Великой Матери Соколиному Ветру опасность у колодца?",a="Хотя на окрестных равнинах водятся агрессивные горные пумы и долгоножки, Великая Мать Соколиный Ветер цела и невредима у колодца и приятно удивлена, что кто-то потрудился проведать старейшину.",al={"is she safe","is greatmother attacked","danger at water well","она в безопасности","напали ли на великую мать","опасность у колодца"}},{q="Какое культурное значение это задание имеет для тауренов?",a="Культура тауренов высоко ценит семью, сплоченность общины и почтение к старшим. Задание учит юных героев, что истинная сила — в скромном служении и защите своих близких, а не в погоне за личной славой.",al={"tauren culture humble task","why is this a humble task","tauren elders","культура тауренов скромная просьба","почему просьба скромная","старейшины тауренов"}},{q="Что будет после того, как вы найдете Великую Мать Соколиного Ветра?",a="Когда вы поговорите с Великой Матерью Соколиным Ветром, она завершает дело и просит о дальнейшей помощи: отнести наполненный кувшин с водой обратно в лагерь.",al={"next quest","a humble task follow up","what to do after finding mother","следующее задание","продолжение скромной просьбы","что делать после встречи с матерью"}}},fp="13,384,25.487.0,29.432.0,47.166.0,38.125.0,55.242.0,46.215.0,64.231.0,48.151.0"}
P.entries["quest:753"] = {n="Скромная просьба",s="«Скромная просьба» — вводный обряд служения на Плато Красного Облака, где старейшина проверяет смирение и усердие начинающего искателя приключений. Принося свежую колодезную воду через равнины вождю Лагеря Нараче, юные таурены узнают, что служение своему народу начинается с простейших обязанностей.",h="«Скромная просьба» — вводный обряд служения на Плато Красного Облака, где старейшина проверяет смирение и...",kw={"camp narache","chief hawkwind","greatmother hawkwind","humble task","mulgore","red cloud mesa","rites of the earthmother","water pitcher","лагерь нараче","вождь соколиный ветер","великая мать соколиный ветер","скромная просьба","мулгор","плато красного облака","обряды матери-земли","кувшин с водой"},ang={["faction:Horde"]="Уроки рода Соколиного Ветра показывают, как таурены сохраняют сплоченность и выживают в Мулгоре, образуя мирную, но непреклонную опору Орды Тралла.",["race:Tauren"]="Приносить воду старейшинам — основа тауренской добродетели заботы об общине, и это показывает, что вы готовы пойти путем Матери-Земли."},sec={{t="Жизненная сила молодости",b="Великая Мать Соколиный Ветер прошла много троп за свою долгую жизнь, и хотя ее дух остается твердым, ноги уже не несут ее по равнинам так быстро, как в молодости. Она находится у колодца на южных окраинах Плато Красного Облака и терпеливо исполняет свои обязанности. Когда на ее пути оказываются будущие защитники племени, она направляет их юную энергию на практические нужды общины, давая возможность доказать свою ценность службой, а не насилием."},{t="Служение племени",b="Посвящаемому нужно принести наполненный кувшин с водой на северо-запад, в Лагерь Нараче, и вручить его лично вождю поселения, вождю Соколиному Ветру, который приходится сыном Великой Матери. В обществе тауренов выживание на засушливых равнинах Мулгора требует общего труда и надежных запасов свежей воды. Уважение к старейшинам общины и готовность взять на себя их заботы считаются основой того, чтобы стать настоящим защитником племени."},{t="Путь к Громовому Утесу",b="Вождь Соколиный Ветер видит в пришедшем молодом страннике, принесшем воду от его матери, не просто выполненную работу. По обычаю тауренов, готовность отстаивать свой народ на дальних землях начинается со смирения и неподсказанного желания помочь. Проявив эту тихую дисциплину, посвящаемый привлекает внимание вождя и получает рекомендацию для древних Обрядов Матери-Земли — настоящих духовных испытаний, открывающих врата Громового Утеса."}},faq={{q="Кто такая Великая Мать Соколиный Ветер?",a="Великая Мать Соколиный Ветер — старейшина рода Соколиного Ветра, находящаяся у колодца на Плато Красного Облака. Она мать вождя Лагеря Нараче, вождя Соколиного Ветра, и наставляет молодых тауренов в смирении и племенных ценностях.",al={"greatmother hawkwind","who gives a humble task","hawkwind elder","великая мать соколиный ветер","кто выдает скромную просьбу","старейшина соколиный ветер"}},{q="Где находится колодец?",a="Колодец расположен к юго-востоку от Лагеря Нараче на травянистых равнинах Плато Красного Облака. Рядом с ним стоят кувшины со свежей колодезной водой, которые путники и смотрители лагеря могут отнести обратно.",al={"water well location","where is the well","find water pitcher","расположение колодца","где колодец","найти кувшин с водой"}},{q="Кто такой вождь Соколиный Ветер?",a="Вождь Соколиный Ветер — предводитель, управляющий Лагерем Нараче на Плато Красного Облака. Он руководит обучением и духовными обрядами молодых тауренов, готовя их к тому, чтобы отправиться в путь и служить всему племени в Мулгоре.",al={"chief hawkwind","who is the chief","camp narache leader","вождь соколиный ветер","кто такой вождь","глава лагеря нараче"}},{q="Почему это поручение считается важным испытанием?",a="Культура тауренов высоко ценит смирение, поддержку общины и уважение к старейшинам. Выполнение неприметных повседневных обязанностей показывает, что искатель приключений заботится о существовании своего народа, а не только о личной славе в бою.",al={"why carry water","why humble task","is this quest important","зачем нести воду","зачем скромная просьба","важно ли это задание"}},{q="Что следует после выполнения задания «Скромная просьба»?",a="Выполнив это задание, вы докажете свою дисциплину вождю Соколиному Ветру, и он направит вас пройти Обряды Матери-Земли — череду традиционных испытаний, обязательных для всех тауренов, достигших совершеннолетия.",al={"what comes next","next quest","after humble task","что дальше","следующее задание","после скромной просьбы"}},{q="Куда в итоге ведет этот путь?",a="Уважение старейшин Лагеря Нараче готовит вас к тому, чтобы покинуть уединенное плато и отправиться на просторы равнин Мулгора, а в конечном счете — к высоким плато столицы, Громовому Утесу.",al={"future destination","where are we going","thunder bluff goal","дальнейший путь","куда идти","цель громовой утес"}}},fp="13,288,21.500.0,20.469.0,27.468.0,28.220.0,32.178.0,22.203.0,47.236.0,42.202.0,37.209.0"}
P.entries["quest:754"] = {n="Очищение колодца Заиндевевшего Копыта",s="«Очищение колодца Заиндевевшего Копыта» — обряд, который Мулл Громовой Рог в Деревне Кровавого Копыта поручает искателям приключений из Орды. После того как гоблины загрязнили местные источники, освященный тотем нужно доставить на территорию Торговой Компании, чтобы очистить Колодец Заиндевевшего Копыта. Восстановление этого источника — первый важный шаг к исцелению отравленных вод центрального Мулгора.",h="«Очищение колодца Заиндевевшего Копыта» — обряд, который Мулл Громовой Рог в Деревне Кровавого Копыта...",kw={"bloodhoof village","cleansing","mulgore","mull thunderhorn","poison","totem","venture company","water well","winterhoof","деревня кровавого копыта","очищение","мулгор","мулл громовой рог","яд","тотем","торговая компания","колодец","заиндевевшее копыто"},ang={["class:Druid"]="Немедленное возвращение жаждущих зверей к очищенному источнику доказывает, как необходимо исцелять природу везде, где цивилизация грозит ее опустошить.",["class:Shaman"]="Направлять духов через тотемы, чтобы обратить вспять неестественную промышленную скверну, — главная цель связи шамана со стихией воды.",["faction:Horde"]="Обеспечение Мулгора свежей водой укрепляет сердце земель недавно поселившихся тауренов и южную опору молодой Орды.",["race:Tauren"]="Колодцы Мулгора — священные дарители жизни, ниспосланные Матерью-Землей; защищать их от гоблинской жадности — и гражданский долг, и священная обязанность каждого таурена."},sec={{t="Опустошенная земля",b="Травянистые равнины Мулгора зависят от хрупкой сети древних колодцев, которые поддерживают и дичь, и разрозненные племена тауренов. Недавно безжалостные промышленные наемники Торговой Компании обосновались в холмах к юго-востоку от Деревни Кровавого Копыта. Их работы загрязнили местные водоносные слои, и Колодец Заиндевевшего Копыта стал затхлым и ядовитым. Дикие звери избегают испорченной воды, а соседним лагерям грозит беда, если порча распространится дальше в земле."},{t="Обряд очищения вод",b="Чтобы противостоять промышленной грязи, Мулл Громовой Рог вырезает и зачаровывает ритуальный тотем очищения, наполненный благословением Матери-Земли. Но доставить это средство можно, лишь одолев вооруженных громил Торговой Компании, захвативших источник. Установив тотем прямо у колодца, искатель приключений рассеивает зловонные стоки, и из глубин земли снова поднимается чистая, дарующая жизнь вода."}},faq={{q="Где находится Колодец Заиндевевшего Копыта?",a="Колодец Заиндевевшего Копыта находится в холмах к юго-востоку от Деревни Кровавого Копыта в Мулгоре. Его усиленно охраняют гоблины-рабочие и наемники, служащие Торговой Компании.",al={"winterhoof well location","where is winterhoof well","how to find winterhoof well","расположение колодца заиндевевшего копыта","где колодец заиндевевшего копыта","как найти колодец заиндевевшего копыта"}},{q="Почему колодец был отравлен?",a="Торговая Компания устроила поблизости горные и земляные работы, позволив токсичным промышленным стокам и отходам просачиваться прямо в водоносный слой, из-за чего природный источник стал непригоден для питья местным зверям и тауренам.",al={"who poisoned the water","why is the well dirty","venture company well","кто отравил воду","почему колодец грязный","торговая компания колодец"}},{q="Кто такой Мулл Громовой Рог?",a="Мулл Громовой Рог — духовный старейшина в Деревне Кровавого Копыта. Он глубоко чувствует состояние земли и создает обрядовые тотемы, чтобы исправить разрушения природы, причиненные чужаками.",al={"who is mull","mull thunderhorn role","кто такой мулл","мулл громовой рог роль"}},{q="Что происходит после очищения колодца?",a="Когда вода в Колодце Заиндевевшего Копыта становится чистой и звери снова безопасно пьют из него, Мулл Громовой Рог обращает ваше внимание на другие загрязненные колодцы Мулгора, начиная с Тотема Громового Рога.",al={"what comes next","after winterhoof cleansing","what does mull do next","что дальше","после очищения колодца заиндевевшего копыта","что мулл делает дальше"}},{q="Кто охраняет колодец?",a="Колодец занимают рабочие и наемники Торговой Компании — беспринципного синдиката под началом гоблинов, который истощает земли ради природных ресурсов, не заботясь о местной экосистеме.",al={"who guards winterhoof well","what enemies are at the well","кто охраняет колодец заиндевевшего копыта","какие враги у колодца"}},{q="Как действует тотем очищения?",a="Тотем, вырезанный с помощью священных обрядов тауренов и защитных ритуалов, черпает силу природных духов и благословение Матери-Земли, чтобы изгнать неестественные химические загрязнения из истока источника.",al={"cleansing totem lore","how does mull totem work","предание о тотеме очищения","как действует тотем мулла"}}},fp="20,358,16.505.0,30.432.0,43.191.0,32.227.0,24.205.0,40.212.1,31.195.0,34.192.0"}
P.entries["quest:756"] = {n="Тотем Громового Рога",s="«Тотем Громового Рога» — задание, которое Мулл Громовой Рог в Деревне Кровавого Копыта дает для создания священного тотема очищения. Чтобы бороться с гоблинским загрязнением колодцев Мулгора, юным защитникам Орды нужно собрать природные когти хищников равнин и связать первобытную силу земли с ритуальным деревом.",h="«Тотем Громового Рога» — задание, которое Мулл Громовой Рог в Деревне Кровавого Копыта дает для создания...",kw={"bloodhoof village","cleansing","cougar claws","flatland cougar","mulgore","mull thunderhorn","prairie stalker","stalker claws","thunderhorn totem","water well","деревня кровавого копыта","очищение","когти пумы","пума плоскогорья","мулгор","мулл громовой рог","луговой скрад","когти скрада","тотем громового рога","колодец"},ang={["class:Hunter"]="Чтобы собрать когти, нужно понимать местных подкрадывающихся зверей равнин и чтить добычу, сохраняя экосистему.",["class:Shaman"]="Восстановление с помощью тотемов основано на призыве живых духов земли, чтобы очистить воду, оскверненную неестественным, небрежным предпринимательством.",["race:Tauren"]="Защита водоносных слоев Мулгора от чужой эксплуатации — священный долг племени, отражающий завет Матери-Земли жить в равновесии, а не грабить."},sec={{t="Охота на хищников равнин",b="Пока промышленная эксплуатация Торговой Компании отравляет драгоценные источники воды Мулгора, Мулл Громовой Рог спешно трудится над средствами исцеления. Для создания Тотема очищения колодца Громового Рога нужны природные сущности самых целеустремленных охотников равнин: луговых скрадов и пум плоскогорья. Забирая когти этих хищников, бродящих к востоку и западу от Деревни Кровавого Копыта, обряд направляет необузданную, неиспорченную хищную мощь животных прямо в тотем."},{t="Природа охоты",b="Традиция тауренов проводит глубокое различие между охотой ради пропитания или духовного равновесия и повальным грабежом гоблинов. Мулл подчеркивает, что чистота, с которой охотятся местные хищники, жизненно важна для очищения оскверненной земли. Там, где гоблинские машины оскверняют источники маслом и промышленными отходами, природная сила зверей, борющихся с землей, дает духовный катализатор, нужный для восстановления Колодца Громового Рога."}},faq={{q="Зачем Муллу Громовому Рогу когти хищников?",a="Мулл использует когти луговых скрадов и пум плоскогорья, чтобы направить чистый первобытный дух хищников равнин в тотем очищения. Он верит, что чистый дух природных охотников противостоит искусственной промышленной порче.",al={"why claws","purpose of stalker claws","cougar claws purpose","зачем когти","для чего когти скрада","для чего когти пумы"}},{q="Кто портит воду в Мулгоре?",a="Гоблины Торговой Компании, работающие в Мулгоре, загрязняют землю и воду. Их безрассудная добыча ресурсов и буровые установки сбрасывают токсичную жижу в водоносные слои, питающие колодцы племен.",al={"who tainted the well","why is the well poisoned","what poisoned mulgore","кто испортил колодец","почему колодец отравлен","что отравило мулгор"}},{q="Где обитают луговые скрады и пумы плоскогорья?",a="Оба зверя бродят по открытым равнинам центрального Мулгора, в основном по холмистым саваннам к востоку и западу от Деревни Кровавого Копыта.",al={"stalker location","where to find cougars","cougar claw locations","где скрады","где найти пум","где взять когти пумы"}},{q="Что происходит после создания Тотема Громового Рога?",a="Когда Мулл вырезает и зачаровывает тотем с помощью когтей, он отправляет вас прямо к оскверненному Колодцу Громового Рога, чтобы провести обряд очищения и изгнать яд.",al={"what next","after thunderhorn totem","totem follow up","что дальше","после тотема громового рога","продолжение тотема"}},{q="Как это связано с предыдущим очищением колодца Заиндевевшего Копыта?",a="Это часть продолжающихся усилий племени по сохранению священных вод Мулгора. Колодец Заиндевевшего Копыта был очищен первым, а теперь загрязнение угрожает колодцу Громового Рога дальше на севере.",al={"winterhoof connection","previous totem quest","связь с колодцем заиндевевшего копыта","предыдущее задание с тотемом"}},{q="Почему таурены не используют просто травяные средства вместо звериных когтей?",a="Ритуальное мастерство тауренов опирается на различные стихийные и физические стороны природы. Острая чистота верховных хищников дает деятельную, борющуюся духовную силу, необходимую, чтобы пробиться сквозь агрессивные гоблинские промышленные яды.",al={"why not herbs","shamanic totem materials","почему не травы","материалы шаманских тотемов"}}},fp="17,307,28.469.0,22.465.0,46.237.0,39.200.0,58.146.0,50.174.1,66.195.0,72.236.0"}
P.entries["quest:757"] = {n="Обряд Силы",s="Обряд Силы — первое испытание в традиционных Обрядах Матери-Земли, которые проходят молодые таурены в Лагере Нараче. Чтобы доказать свою храбрость и готовность защищать племя, испытуемые должны истребить вторгшихся в Ежевичную лощину свинобразов-Дыбогривов и принести их пояса вождю Соколиному Ветру.",h="Обряд Силы — первое испытание в традиционных Обрядах Матери-Земли, которые проходят молодые таурены в Лагере...",kw={"brambleblade ravine","bristleback","camp narache","chief hawkwind","earthmother","mulgore","quilboar","rite of strength","seer graytongue","ежевичная лощина","дыбогрив","лагерь нараче","вождь соколиный ветер","мать-земля","мулгор","свинобраз","обряд силы","провидец серая пасть"},ang={["faction:Horde"]="Защита плато обеспечивает один из главных источников пополнения Орды: молодые воины и шаманы смогут безопасно возмужать и помочь новому союзу.",["race:Tauren"]="Каждый молодой таурен начинает свой путь с этих древних обрядов и показывает, что готов защитить свой народ от угрозы свинобразов, прежде чем покинуть Плато Красного Облака."},sec={{t="Первое испытание",b="Для молодого таурена, который ищет признания старейшин племени и в будущем — принятия в Громовом Утесе, прохождение Обрядов Матери-Земли — обязательный долг. Обряд Силы, который назначает Провидец Серая Пасть, служит первым испытанием. Он требует физической отваги и решительных действий в защиту Плато Красного Облака и проверяет, способен ли испытуемый без страха встретить смертельных врагов племени."},{t="Угроза Дыбогривов",b="Местом испытания выбрана Ежевичная лощина — поросший колючками овраг к востоку от Лагеря Нараче, где обосновались свинобразы-Дыбогривы. Эти агрессивные чужаки постоянно вторгаются на земли предков, устраивают засады на охотничьи отряды и под покровом темноты грабят припасы лагеря. Убить их и забрать их пояса — это и доказательство доблести, и необходимая мера для безопасности поселения."}},faq={{q="Для чего нужен Обряд Силы?",a="Это основополагающий этап Обрядов Матери-Земли, призванный проверить храбрость молодого таурена в бою. Устранив врагов, угрожающих лагерю, испытуемый получает право на путь к настоящему уважению в Громовом Утесе.",al={"why do rite of strength","rite of strength lore","purpose of rite of strength","зачем нужен обряд силы","обряд силы предания","цель обряда силы"}},{q="Кто дает и оценивает это испытание?",a="Провидец Серая Пасть возлагает поручение на испытуемого и объясняет духовные и практические требования испытания. Когда будет собрано двенадцать поясов Дыбогривов, доказательство доблести нужно предъявить прямо вождю Соколиному Ветру в Лагере Нараче.",al={"who gives rite of strength","who turns in rite of strength","кто дает обряд силы","кому сдавать обряд силы"}},{q="Где находится Ежевичная лощина?",a="Ежевичная лощина лежит прямо к востоку от Лагеря Нараче на Плато Красного Облака. Это колючий каньон, кишащий враждебными свинобразами-Дыбогривами.",al={"where is brambleblade ravine","brambleblade location","где ежевичная лощина","расположение ежевичной лощины"}},{q="Почему целью выбраны Дыбогривы?",a="Дыбогривы вторгаются на исконные охотничьи угодья племени. Они то и дело устраивают засады на охотников-тауренов и по ночам крадут провизию из Лагеря Нараче, поэтому они — прямые враги племени.",al={"why kill bristlebacks","what did the quilboar do","зачем убивать дыбогривов","что сделали свинобразы"}},{q="Почему собирают пояса, а не другие трофеи?",a="Пояса — вещественный знак побежденных воинов: они доказывают, что испытуемый сразился со свинобразами лицом к лицу и одолел взрослых бойцов, а не просто подбирал добычу издали.",al={"why bristleback belts","why belts","пояса дыбогривов","зачем пояса"}},{q="Что происходит после Обряда Силы?",a="Прохождение Обряда Силы подтверждает доблесть посвящаемого и дает ему право на последующие испытания Матери-Земли, продолжая формальный путь к взрослой жизни и духовному положению в племени.",al={"what is after rite of strength","next earthmother rite","что после обряда силы","следующий обряд матери-земли"}}},fp="16,303,15.399.0,22.404.0,44.234.0,34.237.0,37.150.0,40.223.0,44.196.0,49.201.0"}
P.entries["quest:758"] = {n="Очищение колодца Громового Рога",s="Очищение колодца Громового Рога — важный духовный обряд в Мулгоре: путникам поручено очистить загрязненный Колодец Громового Рога. Вооружившись ритуальным тотемом, подготовленным Муллом Громовым Рогом, герои очищают оскверненный источник, жизненно важный для местного племени. Успешное очищение приносит искреннее одобрение предков Громового Рога.",h="Очищение колодца Громового Рога — важный духовный обряд в Мулгоре: путникам поручено очистить загрязненный...",kw={"ancestral spirits","bloodhoof village","cleansing totem","earth mother","mulgore","mull thunderhorn","thunderhorn cleansing","thunderhorn water well","духи предков","деревня кровавого копыта","тотем очищения","мать-земля","мулгор","мулл громовой рог","очищение колодца громового рога","колодец громового рога"},ang={["class:Druid"]="Очищение отравленной воды останавливает распространение порчи по экосистеме Мулгора и сохраняет природную гармонию равнин.",["class:Shaman"]="Направлять энергию предков через тотемы, чтобы исцелять оскверненные родники, — сама основа призвания шамана.",["faction:Horde"]="Помощь тауренам с их священными источниками укрепляет связь между молодой Ордой и ее гордыми союзниками из Шу'хало.",["race:Tauren"]="Восстановление священных источников чтит Мать-Землю и защищает ваших сородичей, которые обустраивают постоянный мирный дом в Мулгоре."},sec={{t="Отравленная жила жизни",b="Колодцы на просторных равнинах Мулгора — жизненно важные источники для кочевых племен тауренов, недавно поселившихся в этих степях. Когда подземные источники отравляет скверна, страдают и звери, и ближние поселения. Колодец Громового Рога к северу от Деревни Кровавого Копыта стал жертвой порчи, и исцелить израненную землю можно лишь духовным обрядом."},{t="Очищение предков",b="Чтобы одолеть порчу, Мулл Громовой Рог изготавливает освященный Тотем очищения, наполненный духовной силой. Принеся эту реликвию к отравленной воде, герои направляют силу предков в источник, рассеивают яды и возвращают природе чистое равновесие. Мулл получает прямое подтверждение успеха, когда духи предков Громового Рога являются ему во сне, чтобы выразить неизменную благодарность."}},faq={{q="Где находится Колодец Громового Рога?",a="Колодец Громового Рога лежит на равнинах к северу от Деревни Кровавого Копыта в Мулгоре. Это один из нескольких жизненно важных водопоев для местных кланов тауренов.",al={"thunderhorn well location","where is well","where do i use totem","где колодец громового рога","где колодец","где использовать тотем"}},{q="Кто начинает этот обряд очищения?",a="Обряд начинает Мулл Громовой Рог. Его можно найти в Деревне Кровавого Копыта, где он мастерит особые тотемы, чтобы исцелить пострадавшую природу Мулгора.",al={"who gives quest","mull thunderhorn location","quest giver","кто дает задание","где мулл громовой рог","персонаж, выдающий задание"}},{q="Почему нужно очищать колодцы Мулгора?",a="Колодцы по всему Мулгору стали жертвой неестественного отравления и порчи, что угрожает хрупкому равновесию равнин и выживанию племен тауренов, зависящих от чистой воды.",al={"why cleanse wells","what happened to the water","why is well poisoned","зачем очищать колодцы","что случилось с водой","почему колодец отравлен"}},{q="Как Мулл узнает, что обряд удался?",a="Когда обряд у колодца завершен, духи предков клана Громового Рога являются Муллу во сне, хваля деяния героя и принося благодарность предков.",al={"ancestor dream","how mull knows","well cleansed result","сон о предках","как мулл узнает","результат очищения колодца"}},{q="Что происходит после очищения колодца Громового Рога?",a="Очищение Колодца Громового Рога — часть более широких усилий по защите источников Мулгора. Затем Мулл отправляет путников помочь в другом неспокойном месте — создать Тотем Буйногривых.",al={"what next","next quest after thunderhorn","wildmane totem next","что дальше","следующее задание после громового рога","тотем буйногривых дальше"}},{q="Что такое Тотем очищения колодца Громового Рога?",a="Тотем очищения колодца Громового Рога — ритуально вырезанное духовное средоточие, которое подготовил Мулл Громовой Рог специально для очищения оскверненных вод родового колодца своего клана.",al={"cleansing totem","what is the totem item","mull totem","тотем очищения","что за тотем","тотем мулла"}}},fp="21,345,18.422.0,19.447.0,44.167.0,36.161.0,48.196.0,45.184.0,51.191.0,40.180.0"}
P.entries["quest:759"] = {n="Тотем Буйногривых",s="Тотем Буйногривых — третий и последний этап усилий Мулла Громового Рога по созданию очищающих тотемов для отравленных колодцев Мулгора. Чтобы очистить Колодец Буйногривых, обряд требует даров от самых свирепых хищников края — вожаков луговых волков.",h="Тотем Буйногривых — третий и последний этап усилий Мулла Громового Рога по созданию очищающих тотемов для...",kw={"bloodhoof village","mulgore","mull thunderhorn","prairie wolf alpha","thunder bluff","totem","water well","wildmane","деревня кровавого копыта","мулгор","мулл громовой рог","вожак лугового волка","громовой утес","тотем","колодец","буйногривые"},ang={["class:Hunter"]="Выслеживание хитрых волков-вожаков у высоких утесов проверяет уважение охотника к дикой природе и ее самым опасным хищникам.",["class:Shaman"]="Шаманы ценят тонкие обряды, в которых тотемы хищников сочетаются со стихией воды, чтобы изгнать ядовитую порчу.",["race:Tauren"]="Очищение родовых колодцев подчеркивает долг тауренов исправлять нарушенное равновесие природы и чтить жертвы, которых требует Мать-Земля."},sec={{t="Последний колодец",b="Добыв материалы для освящения тотемов для колодцев Заиндевевшего Копыта и Громового Рога, остается лишь один пораженный источник в центре Мулгора — Колодец Буйногривых. Отравленная вода на равнинах угрожает и кочующим зверям, и поселениям, и для восстановления равновесия земли нужны сильные первозданные ингредиенты."},{t="Сила хищника",b="Чтобы одолеть сильную порчу в северных водах, Мулл Громовой Рог требует жертвы свирепости. Вожаки луговых волков бродят по степям, особенно у высоких утесов под Громовым Утесом. Добытые зубы вкладывают неутомимый напор и стойкость верховных хищников Мулгора прямо в создание очищающего тотема."},{t="Жертва и равновесие",b="В духовной традиции тауренов обращение к существам земли имеет эмоциональный и стихийный вес. Мулл видит в сборе зубов вожаков не завоевание, а мрачную необходимость: жертва хищников Мулгора помогает исцелить израненные воды Матери-Земли."}},faq={{q="Для чего нужен Тотем Буйногривых?",a="Мулл Громовой Рог изготавливает тотем, чтобы очистить Колодец Буйногривых — последний загрязненный источник воды, угрожающий тауренам Мулгора.",al={"why make wildmane totem","wildmane totem purpose","зачем делать тотем буйногривых","назначение тотема буйногривых"}},{q="Почему нужны именно зубы вожаков луговых волков?",a="Чтобы очистить глубокую порчу в Колодце Буйногривых, нужно направить свирепую, непреклонную силу верховного хищника. Зубы вожаков стай дают необходимую первозданную мощь.",al={"why wolf teeth","prairie alpha teeth purpose","зачем волчьи зубы","назначение зубов вожаков"}},{q="Где в Мулгоре найти вожаков луговых волков?",a="Вожаки луговых волков бродят по северным равнинам Мулгора, обычно в степях у подножия Громового Утеса.",al={"prairie wolf alpha location","where to find prairie alphas","где вожак лугового волка","где найти вожаков луговых волков"}},{q="Кто изготавливает тотем?",a="Мулл Громовой Рог, духовный старейшина из Деревни Кровавого Копыта, изготавливает каждый очищающий тотем, когда испытуемый соберет нужные дары.",al={"who makes the totem","totem quest giver","кто делает тотем","кто выдает задание на тотем"}},{q="Что происходит после создания Тотема Буйногривых?",a="Когда Мулл Громовой Рог соберет тотем из зубов вожаков, вас отправят с ним на север, чтобы провести само очищение у Колодца Буйногривых.",al={"what comes next","wildmane totem next quest","что дальше","следующее задание тотема буйногривых"}},{q="Как этот обряд отражает верования тауренов?",a="Таурены считают лишение животного жизни торжественным обменом с природой. Мулл признает жертву волков с печалью об их смерти и с гордостью за их роль в исцелении земли.",al={"tauren philosophy totem","mull thunderhorn beliefs","философия тауренов тотем","верования мулла громового рога"}}},fp="14,272,14.339.0,23.367.0,21.277.0,38.141.0,55.192.0,47.130.0,21.146.0,48.147.0,44.199.0"}
P.entries["quest:76"] = {n="Яшмовая шахта",s="После того как выяснилось, что кобольды захватили Рудник Подземных Глубин, маршал Дугхан поручает разведчикам осмотреть Яшмовую шахту дальше на восток. Прибыв на место, они убеждаются в худшем: нашествие распространилось по важным рудным жилам Элвиннского леса, и оставшиеся защитники Штормграда оказались на пределе сил.",h="После того как выяснилось, что кобольды захватили Рудник Подземных Глубин, маршал Дугхан поручает разведчикам...",kw={"azora","dughan","elwynn","fargodeep","goldshire","jasperlode","kobold","mine","scout","азора","дугхан","элвиннский лес","подземные глубины","златоземье","яшмовая шахта","кобольд","шахта","разведчик"},ang={["faction:Alliance"]="Одновременная потеря Рудника Подземных Глубин и Яшмовой шахты показывает, насколько хрупкими стали внутренние земли Штормграда без централизованной королевской поддержки.",["profession:Mining"]="Для шахтера зрелище богатых подземных жил, захваченных вредителями, горько. В туннелях Яшмовой шахты немало ценных залежей, но чтобы добыть их, придется пробиваться через полчища кобольдов, защищающих свою территорию.",["race:Human"]="Разведчики-люди воочию видят, как постепенно рушится сельская инфраструктура Элвиннского леса: ресурсы окраин гибнут у самых порогов столицы."},sec={{t="Второе вторжение",b="Получив доказательства того, что кобольды наводнили туннели Рудника Подземных Глубин к югу от Златоземья, маршал Дугхан опасался, что нашествие — не единичный случай. Яшмовая шахта, расположенная в скалистых предгорьях к северо-востоку от Башни Азоры, — еще один важный источник камня и металла для королевства. Не имея возможности снять обычных стражей Штормграда с патрулирования города, Дугхан полагается на вольных искателей приключений: они должны отправиться на восток и выяснить, не захвачено ли и это место подземными вредителями со свечами."},{t="Растянутая оборона",b="Разведка в глубине залов Яшмовой шахты показывает, что кобольды полностью вытеснили шахтеров-людей и закрепились в темных проходах, укрепив их. Для маршала Дугхана этот мрачный доклад — очередной удар в нарастающем кризисе. Король Вариан Ринн пропал, а королевские войска не отправляют в отдаленные земли, поэтому местному гарнизону не хватает людей, чтобы очистить шахты. Сердце королевства страдает экономически и оказывается зажато в тисках."}},faq={{q="Где находится Яшмовая шахта?",a="Шахта находится в северных предгорьях восточной части Элвиннского леса. Чтобы добраться до нее, следуйте на восток по главной дороге мимо Златоземья до Башни Азоры, а затем поверните на север, в холмы.",al={"where is jasperlode","jasperlode mine location","how to find jasperlode","где яшмовая шахта","расположение яшмовой шахты","как найти яшмовую шахту"}},{q="Почему маршалу Дугхану нужен разведчик, а не стражи?",a="Стража Штормграда в Элвиннском лесу остро нуждается в людях из-за политического тупика в столице и исчезновения короля Вариана Ринна. Местные силы растянуты на защиту ферм и городов от бандитов и гноллов, поэтому маршалу Дугхану приходится полагаться на разведчиков из числа гражданских.",al={"why send adventurers","why no stormwind guard","where are the guards","почему искатели приключений","почему не стража штормграда","где стражи"}},{q="Почему кобольды захватывают шахты Элвиннского леса?",a="Кобольды — прирожденные проходчики, их привлекают подземные рудные жилы и сырые пещеры. Когда военное присутствие Штормграда ослабло, твари осмелели и стали наступать на разработки людей, такие как Рудник Подземных Глубин и Яшмовая шахта, чтобы завладеть золотом, рудой и землей.",al={"why kobolds in jasperlode","what do kobolds want","kobold infestation reason","почему кобольды в яшмовой шахте","чего хотят кобольды","причина нашествия кобольдов"}},{q="Что происходит после разведки Яшмовой шахты?",a="Когда вы сообщаете маршалу Дугхану о падении Яшмовой шахты, он признает мрачную реальность: Элвиннский лес осажден сразу с нескольких сторон. Раз восточные шахты потеряны, его внимание переключается на запад леса, где Гарнизон у Западного ручья испытывает сильное давление гноллов из племени Речной Лапы.",al={"what next after jasperlode","jasperlode follow up","что дальше после яшмовой шахты","продолжение яшмовой шахты"}},{q="Чем потеря Яшмовой шахты важна для Штормграда?",a="Шахты Элвиннского леса поставляют руду и камень, необходимые для экономики Штормграда и для ковки оружия и доспехов. Потеря и Рудника Подземных Глубин, и Яшмовой шахты останавливает добычу и серьезно подрывает усилия по восстановлению королевства.",al={"why jasperlode matters","jasperlode importance","почему важна яшмовая шахта","значение яшмовой шахты"}},{q="Кому принадлежит соседняя Башня Азоры?",a="Башня Азоры — небольшая башня магов у восточной дороги в Элвиннском лесу. Ею управляет Теокрит, верховный маг Азоры, а служат в ней слуги Азоры. Она служит ориентиром для путников, идущих к восточным предгорьям.",al={"what is tower of azora","who lives in azora tower","что такое башня азоры","кто живет в башне азоры"}}},fp="19,314,18.518.0,21.456.0,37.191.0,63.268.0,43.266.0,48.280.0,60.230.0,35.246.0"}
P.entries["quest:760"] = {n="Очищение колодца Буйногривых",s="Очищение колодца Буйногривых завершает усилия тауренов по ритуальной очистке важных водопоев Мулгора. По поручению Мулла Громового Рога из Деревни Кровавого Копыта герои несут готовый Тотем Буйногривых на север, чтобы очистить последний отравленный колодец. Изгнание гоблинских загрязнений восстанавливает равновесие равнин и обеспечивает пастушеский уклад племен тауренов.",h="Очищение колодца Буйногривых завершает усилия тауренов по ритуальной очистке важных водопоев Мулгора.",kw={"bloodhoof village","cleansing","earth mother","mulgore","mull thunderhorn","totem","venture company","water well","wildmane","деревня кровавого копыта","очищение","мать-земля","мулгор","мулл громовой рог","тотем","торговая компания","колодец","буйногривые"},ang={["class:Druid"]="Устранение вреда, причиненного гоблинами природе, прямо отражает завет Кенария — исцелять оскверненные экосистемы и охранять зеленые пастбища.",["class:Shaman"]="Использование ритуальных тотемов для устранения механического загрязнения служит примером долга шаманов — поддерживать гармонию между стихиями природы и живыми общинами.",["race:Tauren"]="Восстановление трех древних колодцев Мулгора — основополагающий обряд посвящения, доказывающий преданность молодого воина сохранению даров Матери-Земли."},sec={{t="Очищение дара Матери-Земли",b="Вода — священный источник жизни на залитых солнцем равнинах Мулгора: она поддерживает стада, почву и кочевые племена, недавно собравшиеся вокруг Громового Утеса. Когда Торговая Компания и наступающие гоблины начали загрязнять эти водоносные слои токсичными промышленными стоками, старейшины тауренов осознали смертельную угрозу. После очищения колодцев Заиндевевшего Копыта и Громового Рога Колодец Буйногривых остается третьим и последним оскверненным местом, где требуется духовное вмешательство."},{t="Тотем Буйногривых",b="Тотем очищения колодца Буйногривых, созданный из особых элементов, собранных по всей области, направляет исцеляющую силу духов предков и стихии земли. Установленный возле оскверненных вод к северу от Громового Утеса, он рассеивает грязные химикаты, вытягивает токсины и возрождает естественный ток воды. Завершив ритуал, таурены защищают свой народ от болезней и ясно дают понять, что осквернение их священной земли терпеть не будут."}},faq={{q="Почему отравили Колодец Буйногривых?",a="Гоблинские предприятия, движимые промышленной жадностью и лесозаготовками, привнесли гнусные яды и химические отходы в подземные воды Мулгора, угрожая как местным животным, так и поселениям племен.",al={"who poisoned the well","why is the well dirty","goblin poison","кто отравил колодец","почему колодец грязный","гоблинский яд"}},{q="Где находится Колодец Буйногривых?",a="Колодец Буйногривых расположен на равнинах прямо к северу от высоких плато Громового Утеса.",al={"wildmane well location","where is wildmane well","finding wildmane well","где колодец буйногривых","расположение колодца буйногривых","найти колодец буйногривых"}},{q="Кто начинает этот ритуал очищения?",a="Мулл Громовой Рог, старейшина из Деревни Кровавого Копыта, проводит вас через создание тотемов и отправляет очищать колодцы.",al={"who gives wildmane cleansing","quest giver","mull thunderhorn location","кто дает очищение колодца буйногривых","персонаж, выдающий задания","где мулл громовой рог"}},{q="Какие еще колодцы входят в эти усилия по очищению?",a="Колодец Буйногривых — третий из трех важных источников воды. Ему предшествуют Колодец Заиндевевшего Копыта и Колодец Громового Рога, оба к югу.",al={"other wells","mulgore wells","winterhoof thunderhorn wells","другие колодцы","колодцы мулгора","колодцы заиндевевшего копыта и громового рога"}},{q="Как действует тотем очищения?",a="Тотем наполнен магией предков и очищенными природными стихиями: он направляет исцеляющую духовную энергию в подземные воды и нейтрализует гоблинские загрязнения.",al={"cleansing totem mechanic","how does totem clean water","как работает тотем очищения","как тотем очищает воду"}},{q="Что значит завершение этого ритуала для Деревни Кровавого Копыта?",a="Очищение трех колодцев гарантирует безопасную питьевую воду всем племенам центрального Мулгора и почитает священный долг тауренов исцелять Мать-Землю от промышленной эксплуатации.",al={"outcome of quest","why cleanse the wells","tauren lore importance","итог задания","зачем очищать колодцы","значение для предания тауренов"}}},fp="18,371,33.509.0,18.481.0,41.206.0,41.104.0,36.139.0,54.153.0,34.166.0,60.179.0"}
P.entries["quest:761"] = {n="Охота на перепелятников",s="Охота на перепелятников — обряд выслеживания и меткой стрельбы, который предлагает Харкен Тотем Ветра в Деревне Кровавого Копыта. Чтобы доказать свою смекалку и терпение, охотникам и путникам предлагается выследить неуловимых птиц на холмистых равнинах Мулгора. Возвращение с нетронутыми трофейными перьями свидетельствует о преданности охоте и уважении к природным испытаниям Матери-Земли.",h="Охота на перепелятников — обряд выслеживания и меткой стрельбы, который предлагает Харкен Тотем Ветра в...",kw={"bloodhoof village","harken windtotem","mulgore","swoop","swoop hunting","tauren trial","trophy swoop quill","деревня кровавого копыта","харкен тотем ветра","мулгор","перепелятник","охота на перепелятников","испытание тауренов","трофейное перо перепелятника"},ang={["class:Druid"]="Выслеживание перепелятников на продуваемых ветрами плато сближает друидов с хищными птицами, которые поддерживают равновесие в небесах Мулгора.",["class:Hunter"]="Эта охота — первый урок в стрельбе по воздушной цели с упреждением, оценке повадок и точных ударах по бдительным хищникам.",["race:Tauren"]="Для молодых тауренов и странников охота на быстрых перепелятников Мулгора — древний обряд посвящения, оттачивающий навыки выслеживания и поддерживающий охотничьи обычаи предков."},sec={{t="Испытание зоркого глаза",b="Травянистые степи Мулгора кишат зверями, но немногие проверяют чутье преследователя так, как местные перепелятники. Эти крупные хищные птицы сливаются с небом и равниной, кружа над головой или скользя низко над высокой травой. В отличие от неповоротливых виверн равнин или пасущихся кодо, перепелятники требуют острого внимания и быстрых ног, чтобы их догнать, поэтому охота на них — традиционное испытание для молодых охотников, стремящихся заслужить место среди племен."},{t="Знаки охоты",b="Для Харкена Тотема Ветра сбор трофейных перьев — не столько истребление дичи, сколько воспитание дисциплины. В культуре тауренов трофеи тяжелой охоты означают смекалку и стойкость. Предъявив эти безупречные перья старейшинам Деревни Кровавого Копыта, искатель приключений показывает, что способен кормить и защищать общину, что его копыта быстры, а чувства достаточно остры, чтобы покорить широкий мир."}},faq={{q="Какова цель охоты на перепелятников для Харкена Тотема Ветра?",a="Харкен Тотем Ветра поручает охотникам выслеживать перепелятников по всему Мулгору, чтобы проверить их смекалку, скорость и преданность. Целые трофейные перья служат признанным доказательством мастерства охотника и приносят почет среди тауренов Деревни Кровавого Копыта.",al={"why hunt swoops","harken windtotem quest purpose","swoop hunting purpose","зачем охотиться на перепелятников","цель задания харкена тотема ветра","цель охоты на перепелятников"}},{q="Где обычно встречаются перепелятники?",a="Перепелятники встречаются по всем открытым равнинам Мулгора: они парят над прериями или высматривают добычу в траве за пределами поселений вроде Деревни Кровавого Копыта.",al={"where are swoops","swoop locations mulgore","find swoops","где перепелятники","где найти перепелятников в мулгоре","найти перепелятников"}},{q="Почему на перепелятников сложно охотиться?",a="В отличие от стадных животных, которые движутся вместе по равнинам, перепелятники — быстрые и настороженные хищные птицы, рассеянные по округе и внимательные. Чтобы выследить их, нужно острое зрение, чтобы заметить пути полета, и быстрый шаг, чтобы сбить их до того, как они уйдут.",al={"why are swoops hard to catch","swoop behavior","почему трудно поймать перепелятников","повадки перепелятников"}},{q="Что означают трофейные перья для тауренов?",a="В традициях тауренов трофейные перья перепелятника означают терпение, острое зрение и успешную охоту. Их ношение показывает, что у охотника есть чутье, необходимое, чтобы кормить и защищать племя.",al={"trophy swoop quill meaning","significance of quills","значение трофейного пера перепелятника","значение перьев"}},{q="Кто такой Харкен Тотем Ветра?",a="Харкен Тотем Ветра — уважаемый таурен, живущий в Деревне Кровавого Копыта. Он наблюдает за новичками и начинающими охотниками и оценивает их находчивость в традиционных испытаниях на равнинах.",al={"who gives swoop hunting","harken windtotem lore","кто дает охоту на перепелятников","предания о харкене тотеме ветра"}},{q="Влияет ли эта охота на равновесие природы в Мулгоре?",a="Таурены относятся к охоте как к священному диалогу с Матерью-Землей, а не как к бессмысленной бойне. Сбор перьев — взвешенное испытание дисциплины, которое чтит смекалку добычи и сохраняет равновесие племени.",al={"is swoop hunting overhunting","swoop balance mulgore","не чрезмерна ли охота на перепелятников","равновесие перепелятников в мулгоре"}}},fp="13,385,19.466.0,18.451.0,59.252.0,39.172.0,41.246.0,48.215.0,24.192.0,55.222.0"}
P.entries["quest:763"] = {n="Обряды Матери-Земли",ang={["faction:Horde"]="Традиционные обряды укрепляют единство племен по всему Мулгору и гарантируют, что новые защитники Орды обладают и воинским мастерством, и глубокой духовной основой.",["race:Tauren"]="Каждый молодой таурен должен пройти путь Матери-Земли, чтобы доказать свою ценность старейшинам и найти свое место среди объединенных племен."},sec={{t="Прощание с плато",b="Из поколения в поколение молодые таурены испытывали свою силу в безопасном Лагере Нараче на Плато Красного Облака. Прохождение первых испытаний доказывает, что у человека хватает дисциплины и решимости, чтобы выжить, но священные Обряды Матери-Земли требуют гораздо большего, чем борьба с местными зверями. Вождь Соколиный Ветер понимает, когда посвящаемый перерос защищенные охотничьи угодья плато и должен шагнуть в более широкую общину."},{t="Знак для Бейна",b="Чтобы облегчить путь между Нараче и главными поселениями, вождь Соколиный Ветер вручает вам вырезанный вручную тотем как знак представления. Неся этот символ по извилистой тропе в Деревню Кровавого Копыта, вы являетесь к Бейну Кровавому Копыту, молодому вождю деревни и сыну верховного вождя Кэрна Кровавого Копыта. Тотем свидетельствует о вашей готовности к обрядам духа и мудрости, которые ждут впереди."}},faq={{q="Для чего нужно это задание?",a="Это обряд перехода, который выводит вас из начальной области Лагеря Нараче и направляет в Деревню Кровавого Копыта, связывая вас со следующей главой церемониальных испытаний тауренов.",al={"why do rites of the earthmother","what does this quest do","purpose of quest","зачем обряды матери-земли","что дает это задание","цель задания"}},{q="Кто такой Бейн Кровавое Копыто?",a="Бейн Кровавое Копыто — сын верховного вождя Кэрна Кровавого Копыта. Он управляет Деревней Кровавого Копыта и является уважаемым местным вождем, наблюдающим за продолжающимися духовными и боевыми испытаниями молодых тауренов.",al={"who is baine","baine lore","son of cairne","кто такой бейн","бейн предания","сын кэрна"}},{q="What is the Totem of Hawkwind?",a="Это деревянный тотем, вырезанный вручную вождем Соколиным Ветром из Лагеря Нараче. Он служит официальной грамотой и знаком одобрения и доказывает Бейну Кровавому Копыту, что вы заслужили благословение Соколиного Ветра на дальнейшие обряды.",al={"totem of hawkwind","hawkwinds totem","carved totem"}},{q="Какие обряды идут после этого?",a="Когда вы прибудете в Деревню Кровавого Копыта и встретитесь с Бейном, вам поручат Обряд прозрения, который проверяет вашу духовную связь с помощью священных видений предков.",al={"next rites","what comes after","next quest","следующие обряды","что дальше","следующее задание"}},{q="Где находится Деревня Кровавого Копыта?",a="Деревня Кровавого Копыта лежит к северу от Лагеря Нараче, на берегах Озера Каменного Быка в центральном Мулгоре. Путникам достаточно спуститься по главной дороге с плато и идти на север.",al={"where is bloodhoof village","how to find bloodhoof village","path to bloodhoof","где деревня кровавого копыта","как найти деревню кровавого копыта","путь в деревню кровавого копыта"}},{q="Почему нужно пройти обряды Матери-Земли?",a="Обряды Матери-Земли — глубоко священные традиции тауренов. Прохождение всех их этапов демонстрирует физическую стойкость, духовную связь и мудрость и приносит посвящаемому истинное признание старейшин Громового Утеса.",al={"why earthmother rites","tauren trials purpose","rites of earthmother lore","зачем обряды матери-земли","цель испытаний тауренов","предания обрядов матери-земли"}}},fp="24,305,16.421.0,17.420.0,34.199.0,23.201.0,30.219.0,27.170.0,35.185.0,44.246.0"}
P.entries["quest:764"] = {n="Торговая Компания",s="Расследование судьбы разграбленного каравана Торговой Компании в Мулгоре выявляет агрессивное скопление гоблинов Торговой Компании, зарывшихся в восточные холмы. Получив категорический отказ на официальные просьбы о разрешении на добычу, компания все равно начала разработку земли Матери-Земли, и Морин Ловец Облаков заказал смертельный ответ.",h="Расследование судьбы разграбленного каравана Торговой Компании в Мулгоре выявляет агрессивное скопление...",kw={"goblin","mining rights","morin cloudstalker","mulgore","ravaged caravan","venture co","venture co mine","venture company","гоблин","право на добычу","морин ловец облаков","мулгор","разграбленный караван","торговая компания","шахта торговой компании"},ang={["faction:Horde"]="Защита Мулгора от коммерческой эксплуатации подтверждает вашу решимость оберегать народ Кэрна Кровавого Копыта, пока он стремится обезопасить свою новую родину.",["profession:Mining"]="Торговая Компания действует исключительно грубой силой: халтурит и расшатывает землю, не заботясь ни о естественном равновесии, ни о безопасности горного дела.",["race:Tauren"]="Для тауренов Мать-Земля священна. Открытые разработки Торговой Компании — не просто вторжение, а насильственное осквернение родного дома предков, заслуживающее немедленного и решительного изгнания."},sec={{t="Промышленное вторжение",b="Таурены Мулгора чтят землю как продолжение Матери-Земли и берегут ее нетронутые равнины и сбалансированный животный мир. Когда Торговая Компания обратилась к племенам за правом взрывать и вскрывать холмы ради сырой руды, ей категорически отказали. Не смутившись ни племенными решениями, ни территориальным суверенитетом, неумолимый картель тайно провел тяжелую технику, рабочих и надсмотрщиков прямо в восточные гряды Мулгора для незаконной добычи."},{t="Недвусмысленное послание",b="Таурены-разведчики вроде Морина Ловца Облаков понимают, что с корпоративной жадностью нельзя договориться дипломатическими призывами, когда кирки уже бьют по камню. Документы, найденные в разграбленном караване Торговой Компании, подтверждают наличие горных работ, и Морин посылает защитников Орды перебить и надсмотрщиков, щелкающих кнутами, и рабочих у буров. Кровавое возмездие должно заставить Торговую Компанию счесть цену вторжения слишком высокой."}},faq={{q="Почему Торговая Компания находится в Мулгоре?",a="Торговая Компания устроила на восточных холмах Мулгора незаконный лагерь и шахту для добычи минералов и природных ресурсов. После того как таурены официально отказали ей в праве на добычу, картель проигнорировал власть племен и все равно начал работы.",al={"why are goblins in mulgore","venture co mulgore motive","what does venture co want","почему гоблины в мулгоре","мотивы торговой компании в мулгоре","чего хочет торговая компания"}},{q="Кто отдал приказ напасть на шахтеров?",a="Приказ отдает Морин Ловец Облаков, таурен, несущий дозор возле Деревни Кровавого Копыта. Он считает, что отказ картеля принять отказ племени — прямое нарушение, требующее силы, а не новых разговоров.",al={"who gives this quest","morin cloudstalker role","quest giver","кто выдает это задание","роль морина ловца облаков","персонаж, выдающий задания"}},{q="Где находится шахта Торговой Компании?",a="Главная шахта Торговой Компании расположена в предгорьях к востоку от Разграбленного каравана и Деревни Кровавого Копыта. Небольшую группу служащих компании можно также встретить в лагере среди утесов к северо-востоку от северных подъемников Громового Утеса.",al={"venture co mine location","where are the supervisors","where to find venture co","расположение шахты торговой компании","где бригадиры","где найти торговую компанию"}},{q="Пытались ли таурены вести переговоры с гоблинами?",a="Да. Торговая Компания просила у тауренов официального права на добычу в Мулгоре. Вожди племен отказались позволить разорять их родовые земли открытыми разработками, но гоблины попросту решили копать без разрешения.",al={"did tauren permit mining","mining rights mulgore","did goblins ask permission","разрешили ли таурены добычу","право на добычу мулгор","просили ли гоблины разрешения"}},{q="Относятся ли эти гоблины к Картелю Хитрая Шестеренка?",a="Нет. Торговая Компания — независимый, пользующийся дурной славой хищнический промышленный картель, отличный от нейтральных торговых объединений вроде Картеля Хитрая Шестеренка. Где бы она ни добывала ресурсы, она поддерживает враждебные отношения с местным населением.",al={"are these ratchet goblins","is venture co friendly","venture company faction","это гоблины кабестана","дружелюбна ли торговая компания","фракция торговая компания"}},{q="Как это связано с разграбленными караванами?",a="Разграбленный караван был обозом Торговой Компании, уничтоженным тауренами. Ящики горного отдела и документы, найденные среди обломков, раскрыли планы компании в Мулгоре и вызвали этот удар по ее шахте.",al={"caravan connection","did venture co attack caravans","the ravaged caravan connection","связь с караваном","нападала ли торговая компания на караваны","разграбленный караван"}}},fp="15,339,20.472.0,23.485.0,38.269.0,40.215.0,42.253.0,54.219.0,50.237.0,46.224.0"}
P.entries["quest:765"] = {n="Бригадир Шумовик",s="Бригадир Шумовик — высокопоставленный надсмотрщик Торговой Компании, расположившийся в горных туннелях Мулгора. По поручению Морина Ловца Облаков положить конец расчетливому грабежу гоблинского предприятия, искатели приключений Орды входят в шахту, чтобы убить его и забрать его подробную планшетку.",h="Бригадир Шумовик — высокопоставленный надсмотрщик Торговой Компании, расположившийся в горных туннелях...",kw={"clipboard","fizsprocket","mine","morin cloudstalker","mulgore","supervisor","venture co","планшетка","шумовик","шахта","морин ловец облаков","мулгор","бригадир","торговая компания"},ang={["faction:Horde"]="Помощь тауренам против наступающих корпоративных грабителей укрепляет защиту Ордой недавно занятых земель Калимдора.",["race:Tauren"]="Открытый замысел Торговой Компании вытеснить ваше племя и разграбить священную землю делает убийство Шумовика актом жизненно важной защиты территории."},sec={{t="Заговор против равнин",b="Документы из уничтоженного каравана Торговой Компании показали, что компания не просто добывала руду — она намеренно строила планы полностью изгнать тауренов из Мулгора. Выселив местных, алчная корпорация рассчитывала получить свободу вычерпать из холмов и глубоких подземных жил все природные ресурсы."},{t="Удар по десятнику",b="Морин Ловец Облаков, разгневанный корпоративными злодеяниями, замышляемыми против его народа, направляет героев в шахту Торговой Компании к востоку от разоренных торговых фургонов. В глубине правых туннелей, в окружении рабочих и младших начальников, делами заправляет Бригадир Шумовик. Если убить Бригадира Шумовика и забрать его планшет, местная координация будет нарушена, а вы получите важные сведения о будущих замыслах компании."}},faq={{q="Кто такой Бригадир Шумовик?",a="Бригадир Шумовик — начальник Торговой Компании, руководящий работами в горных туннелях восточного Мулгора. Он надзирает за рабочими, вгрызающимися в землю, и осуществляет корпоративные стратегии расширения их деятельности по всему региону.",al={"fizsprocket","who is fizsprocket","fizsprocket lore","шумовик","кто такой шумовик","шумовик предания"}},{q="Почему Морин Ловец Облаков хочет смерти Шумовика?",a="Морин нашел в разграбленном караване документы, доказывающие, что Торговая Компания замышляла ради прибыли изгнать тауренов с родовых земель. Шумовик — непосредственный начальник, осуществляющий эти расчетливые планы эксплуатации.",al={"why kill fizsprocket","morin cloudstalker motivation","зачем убивать шумовика","мотивы морина ловца облаков"}},{q="Где находится Бригадир Шумовик?",a="Он находится внутри шахты Торговой Компании, прямо к востоку от Разграбленного каравана в Мулгоре. В шахте идите по крайнему правому туннелю до зала, где он стоит в окружении рабочих и надсмотрщиков.",al={"where is fizsprocket","fizsprocket mine location","fizsprocket map","где шумовик","шахта шумовика","карта шумовика"}},{q="Какое доказательство победы над Шумовиком требует Морин?",a="Морин Ловец Облаков требует личную планшетку Шумовика, где хранятся учетные книги и записи, способные раскрыть дальнейшие замыслы Торговой Компании в Мулгоре.",al={"proof of death","fizsprocket clipboard","доказательство смерти","планшетка шумовика"}},{q="Почему Торговая Компания находится в Мулгоре?",a="Торговая Компания — беспринципный коммерческий картель, стремящийся ободрать нетронутые земли ради древесины, минералов и ценных подземных богатств, совершенно не считаясь с коренными жителями и природным равновесием.",al={"venture co mulgore","why are goblins in mulgore","торговая компания мулгор","почему гоблины в мулгоре"}},{q="Прогонит ли убийство Шумовика Торговую Компанию окончательно?",a="Нет. Хотя гибель Шумовика нарушает местное руководство и дает Морину Ловцу Облаков важные записи об их планах, Торговая Компания остается постоянной угрозой, укоренившейся в холмах Мулгора.",al={"is venture co gone","after fizsprocket dies","ушла ли торговая компания","после смерти шумовика"}}},fp="22,298,25.371.0,21.456.1,30.251.0,50.232.0,40.207.0,54.160.0,38.219.0,67.204.0"}
P.entries["quest:766"] = {n="Маззранач",s="Маур Заклинатель Дождя из Деревни Кровавого Копыта стал жертвой ядовитого укуса Маззранача — легендарного бегуна по равнинам, который за поколение до этого терроризировал его деда. Таурен мечется в лихорадке и бредовых кошмарах, и ему нужно сильное лекарство из местных животных Мулгора, пока инфекция не отняла у него жизнь.",h="Маур Заклинатель Дождя из Деревни Кровавого Копыта стал жертвой ядовитого укуса Маззранача — легендарного...",kw={"bloodhoof village","flatland cougar","maur raincaller","mazzranache","mulgore","plainstrider","prairie wolf","swoop","деревня кровавого копыта","равнинный кугуар","маур заклинатель дождя","маззранач","мулгор","луговой бегун","луговой волк","налетчик"},ang={["class:Hunter"]="Выслеживание луговых волков, кугуаров, луговых бегунов и налетчиков по всему Мулгору — практический урок чтения равнин и понимания особенностей местной дикой природы саванны.",["faction:Horde"]="Защита Деревни Кровавого Копыта от суровых опасностей Мулгора жизненно важна для мира и стабильности на родине тауренов.",["race:Tauren"]="Снадобье, которое готовит Маур, отражает древнюю практику тауренов — черпать лекарства прямо из растительного и животного мира Матери-Земли."},sec={{t="Наследие равнин",b="Долгие годы Маур Заклинатель Дождя считал Маззранача не более чем жуткой семейной историей, которую рассказывал его дед. Старый таурен говорил о необычайно свирепом бегуне по равнинам со светящимися красными глазами, острыми как бритва когтями и ядовитым укусом, не свойственным мирным животным Мулгора. Когда Маур встретил зверя на открытой равнине, легенда оказалась слишком реальной: он был тяжело ранен и с трудом добрался до безопасного места."},{t="Борьба с заражением",b="The creature's venom works swiftly, inducing high fevers and nightmarish delirium. To purge the venom before it turns fatal, traditional tauren medicine relies on the vitality of the local beasts. Maur requires a prairie wolf heart, a flatland cougar femur, a plainstrider scale, and a swoop gizzard. By combining the essences of these varied hunters and scavengers, he can brew a concoction capable of halting the necrotic spread and nursing him back to health."}},faq={{q="Кто такой Маззранач?",a="Mazzranache is an infamous plainstrider roaming the grasslands of Mulgore. Unlike common striders, it is known for vivid plumage, demonic red eyes, fierce talons, and an unusually venomous bite. It has terrorized travelers across multiple generations.",al={"who is mazzranache","what kind of beast is mazzranache","mazzranache lore","кто такой маззранач","что за зверь маззранач","маззранач предания"}},{q="Кто такой Маур Заклинатель Дождя?",a="Маур Заклинатель Дождя — таурен, живущий в Деревне Кровавого Копыта. Когда он пересекал Мулгор, на него напал Маззранач и укусил в плечо, и теперь Маур прикован к постели смертельно опасной ядовитой инфекцией.",al={"maur raincaller","who gave me this quest","who is the sick tauren","маур заклинатель дождя","кто дал это задание","кто больной таурен"}},{q="Почему Мауру нужны части четырех разных зверей?",a="Traditional tauren remedies draw upon the natural strengths and spiritual essences of plains animals to neutralize potent toxins. The heart of a wolf, the dense marrow of a cougar femur, a plainstrider scale, and a swoop gizzard together form an antidote strong enough to counteract Mazzranache's venom.",al={"why wolf heart cougar femur","why animal ingredients","mazzranache remedy ingredients"}},{q="Убил ли дед Маура Маззранача?",a="Нет. Дед Маура сражался со свирепым луговым бегуном много лет назад, но не смог его одолеть и выжил лишь для того, чтобы передать потомкам предостережения о его яркой окраске и жестоких нападениях.",al={"did grandfather defeat mazzranache","maur grandfather mazzranache","who fought mazzranache before"}},{q="Нужно ли в этом задании охотиться на самого Маззранача?",a="Нет. Главное для Маура сейчас — пережить лихорадку. Задание целиком посвящено сбору составляющих для его лекарства, а не охоте на легендарную птицу.",al={"do i kill mazzranache","where is mazzranache","hunt mazzranache"}},{q="Где находится Деревня Кровавого Копыта?",a="Деревня Кровавого Копыта лежит в центральной части Мулгора, к югу от Громового Утеса и чуть восточнее Озера Каменного Быка. Это главное поселение, откуда молодые тауренские воины отправляются в широкие равнины.",al={"where is bloodhoof village","bloodhoof village location","где деревня кровавого копыта","расположение деревни кровавого копыта"}}},fp="11,313,22.471.0,20.462.0,20.251.0,23.208.0,52.303.0,40.198.0,55.180.0,35.193.0"}
P.entries["quest:767"] = {n="Обряд прозрения",s="Обряд прозрения — важнейшее испытание на пороге зрелости в Обрядах Матери-Земли, проверяющее духовную зрелость юного искателя приключений. По поручению Бейна Кровавого Копыта соискателям предстоит обратиться за советом к провидцу деревни Зарельману Две Луны. Это путешествие необходимо всем, кто ищет благословения и уважения старейшин на холмах Громового Утеса.",h="Обряд прозрения — важнейшее испытание на пороге зрелости в Обрядах Матери-Земли, проверяющее духовную...",kw={"baine bloodhoof","bloodhoof village","mulgore","rite of vision","rites of the earthmother","tauren trial","thunder bluff","zarlman two-moons","бейн кровавое копыто","деревня кровавого копыта","мулгор","обряд прозрения","обряды матери-земли","испытание тауренов","громовой утес","зарельман две луны"},ang={["class:Druid"]="Прямое общение с видениями Матери-Земли укрепляет призвание друидов внимательно прислушиваться к мудрости и шепоту живого мира.",["class:Shaman"]="Поиски Зарельмана Две Луны и путь видений глубоко созвучны долгу шамана — сохранять равновесие между мирскими делами и волей предков.",["faction:Horde"]="Прохождение этих традиционных священных обрядов доказывает вашу преданность и уважение к культуре старейшин тауренов, помогающих направлять Орду.",["race:Tauren"]="Обряд прозрения — важная культурная веха для каждого молодого таурена, знаменующая ваш переход в ряды доверенных защитников и ходоков по духам племен."},sec={{t="Священная ступень",b="Поколениями кочевые таурены обращались к Матери-Земле, чтобы она вела их народ по равнинам Калимдора. Теперь, собравшись в безопасных границах Мулгора, они сохраняют духовные традиции как основу своего общества. Обряд прозрения — одно из древних испытаний, известных как Обряды Матери-Земли. Если прежние испытания проверяют физическую силу посвященного и его связь с охотой, то Обряд прозрения требует путешествия вглубь себя и призывает юных тауренов и почетных союзников напрямую общаться с духами."},{t="Наставление провидца",b="Прежде чем искать духовное видение, посвященного должен подготовить человек, умудренный древней мудростью. В Деревне Кровавого Копыта это поручено почитаемому шаману Зарельману Две Луны. Бейн Кровавое Копыто доверил ему готовить путников; Зарельман обладает острым зрением, позволяющим распознать идущих путем предков, и проводит предварительные обряды и священные приготовления, необходимые, чтобы проникнуть сквозь завесу физического мира."}},faq={{q="Что такое Обряд прозрения?",a="Обряд прозрения — священный ритуал в рамках Обрядов Матери-Земли. Он призван расширить духовное зрение искателя приключений, позволяя ему общаться с духами предков и показать старейшинам Громового Утеса свою духовную готовность.",al={"rite of vision quest","what is rite of vision","rite of vision lore","задание обряд прозрения","что такое обряд прозрения","обряд прозрения предания"}},{q="Кто дает это задание?",a="Задание дает Бейн Кровавое Копыто, сын верховного вождя Кэрна Кровавого Копыта. Бейн присматривает за Деревней Кровавого Копыта и направляет достойных путников к духовным старейшинам деревни.",al={"who gives rite of vision","rite of vision quest giver","кто дает обряд прозрения","обряд прозрения персонаж, выдающий задания"}},{q="Кто такой Зарельман Две Луны?",a="Зарельман Две Луны — опытный тауренский шаман и духовный лидер Деревни Кровавого Копыта. Он готовит путников и посвященных, желающих пройти священные испытания, такие как Обряд прозрения.",al={"who is zarlman","zarlman two moons lore","кто такой зарельман","зарельман две луны предания"}},{q="Почему Обряды Матери-Земли важны для тауренов?",a="Обряды Матери-Земли — традиционный обряд перехода во взрослую жизнь для тауренов. Успешное прохождение доказывает физическую силу, духовную гармонию и неизменное уважение к земле и приносит честь в глазах высших старейшин.",al={"earthmother rites meaning","why do rites of earthmother","значение обрядов матери-земли","зачем обряды матери-земли"}},{q="Can non-tauren undertake the Rite of Vision?",a="Да. Союзникам из Орды, которые путешествуют по Мулгору и заслужили доверие племени Кровавого Копыта, позволено идти путем Матери-Земли, проявляя уважение к традициям тауренов в обмен на благосклонность старейшин.",al={"can orcs do rite of vision","non tauren earthmother","могут ли орки пройти обряд прозрения","не таурены мать-земля"}},{q="Где проходит это испытание?",a="Испытание начинается в Деревне Кровавого Копыта, значительном тауренском поселении у берегов Озера Каменного Быка в центральном Мулгоре, к югу от Громового Утеса.",al={"where is rite of vision","rite of vision location","где обряд прозрения","место обряда прозрения"}}},fp="14,381,23.535.0,19.443.0,27.255.0,22.205.0,25.190.0,61.255.0,44.208.0,33.154.0"}
P.entries["quest:768"] = {n="Добывание шкур",s="«Добывание шкур» — простое торговое задание, которое выдает Верен Долгоног на возвышенностях Громового Утеса. Чтобы обеспечивать столицу и испытывать молодых охотников, Верен обменивает связку выделанных шкур тонкой кожи на изготовленные изделия. Это показывает глубоко укоренившуюся традицию тауренов превращать плоды охоты на равнинах в необходимую одежду и доспехи.",h="«Добывание шкур» — простое торговое задание, которое выдает Верен Долгоног на возвышенностях Громового Утеса.",kw={"gathering leather","leatherworking","light leather","mulgore","tauren hunt","thunder bluff","veren tallstrider","добывание шкур","кожевничество","тонкая кожа","мулгор","охота тауренов","громовой утес","верен долгоног"},ang={["class:Hunter"]="Охотники, выходящие на равнины Мулгора, от природы мастерски выслеживают добычу и собирают тонкие шкуры, которые нужны Верену.",["faction:Horde"]="Снабжение мастеров Громового Утеса сырьем укрепляет молодую столицу, пока она усиливает оборону и торговые связи.",["race:Tauren"]="Для охотников-тауренов почтить убитого зверя, превратив его шкуру в полезные вещи, — важнейшая культурная традиция, передающаяся из поколения в поколение."},sec={{t="Забота о Громовом Утесе",b="В недавно основанной столице на высоких плато Мулгора ремесло и выживание идут рука об руку. Верен Долгоног обрабатывает шкуры, делая одежду и защитные доспехи для растущего населения Громового Утеса. Вместо того чтобы добывать все самому, он призывает молодых искателей приключений, отправляющихся на равнины, приносить свою добычу, превращая обычную охоту в почетную службу обществу."},{t="Путь охоты",b="Для тауренов охота на зверей в степях — не забава, а почетное дело, которое кормит, одевает и укрывает племя. Верен Долгоног ищет охотников, стремящихся принести честь своему клану, и просит именно тонкую кожу, снятую с местных животных. За двенадцать хорошо сохраненных шкур он расплачивается с охотником крепкими изделиями, укрепляя взаимную поддержку, на которой держится общество тауренов."}},faq={{q="Кто такой Верен Долгоног?",a="Верен Долгоног — кожевник, живущий в Громовом Утесе. Он изготавливает одежду и защитные доспехи для народа тауренов и обменивает готовые изделия у охотников, которые приносят ему свежие шкуры с равнин.",al={"veren tallstrider","who gives gathering leather","leather questgiver thunder bluff","верен долгоног","кто выдает задание добывание шкур","кожа персонаж, выдающий задания громовой утес"}},{q="Что нужно Верену Долгоногу?",a="Верен просит двенадцать кусков тонкой кожи, добытой со зверей, бродящих по Мулгору и соседним землям, чтобы изготовить изделия для Громового Утеса.",al={"gathering leather requirements","what to bring veren","gathering leather materials","добывание шкур требования","что принести верену","добывание шкур материалы"}},{q="Где происходит это задание?",a="Задание начинается и заканчивается у Верена Долгонога на вершине Громового Утеса, хотя для его выполнения нужно охотиться на диких зверей в степях внизу.",al={"where is veren tallstrider","gathering leather location","где верен долгоног","добывание шкур местоположение"}},{q="Почему тауренам так важна охота на зверей?",a="В культуре тауренов охота — священное равновесие с Матерью-Землей. Каждая часть убитого зверя находит применение: мясо кормит племя, а кости и выделанные шкуры идут на орудия, шатры и прочные доспехи.",al={"tauren hunting culture","why hunt leather","tauren leather lore","охота тауренов","зачем охотиться на кожу","предания тауренов о коже"}},{q="Может ли любой искатель приключений из Орды взяться за это задание?",a="Да, любой путник, верный Орде, в ком Верен видит желание испытать себя на равнинах, может помочь ему с добыванием шкур.",al={"who can do gathering leather","is gathering leather horde only","кто может выполнить добывание шкур","добывание шкур только для орды"}},{q="Что происходит после доставки кожи?",a="Верен проверяет качество шкур, хвалит охотника за работу и в честный обмен выдает изготовленный предмет снаряжения.",al={"gathering leather turn in","veren tallstrider reward","добывание шкур сдать","верен долгоног награда"}}},fp="17,360,24.407.0,19.436.0,25.210.0,33.153.0,33.147.0,61.219.0,45.137.0,43.128.0"}
P.entries["quest:769"] = {n="Сумка из шкуры кодо",s="«Сумка из шкуры кодо» — торговое задание, которое выдает Верен Долгоног, искусный кожевник-таурен на высоких плато Громового Утеса. В обмен на основные материалы для ремесла он передает традиционный равнинный способ шитья прочных дорожных сумок из крепкой звериной шкуры. Это ранний обряд посвящения для учеников кожевников в Мулгоре.",h="«Сумка из шкуры кодо» — торговое задание, которое выдает Верен Долгоног, искусный кожевник-таурен на высоких...",kw={"coarse thread","kodo","kodo hide bag","leatherworking","light leather","mulgore","thunder bluff","veren tallstrider","грубая нить","кодо","сумка из шкуры кодо","кожевничество","тонкая кожа","мулгор","громовой утес","верен долгоног"},ang={["faction:Horde"]="Мастера Громового Утеса поставляют необходимые материальные товары, которые поддерживают снаряжение охотников, разведчиков и воинов Орды по всему центральному Калимдору.",["race:Tauren"]="Для Шу'хало умение делать надежное снаряжение из шкур могучих кодо — важный шаг к почитанию даров Матери-Земли и сохранению заветов предков."},sec={{t="Урок на плато",b="На ремесленных возвышенностях Громового Утеса Верен Долгоног чтит давнюю кочевую традицию ничего не тратить впустую после охоты. Чтобы заслужить его наставления, начинающий кожевник должен принести ему выделанную тонкую кожу и прочную нить. Показав умение обращаться с основными материалами, ученики доказывают, что готовы создавать вещи, достойные того, чтобы носить в них снаряжение для выживания по суровым просторам Калимдора."},{t="Дух кодо",b="Для тауренов кодо — символ выносливости, силы и твердой решимости. Его толстая шкура защищает от колючих зарослей, пронизывающего ветра и звериных когтей. Изготовление сумок и одежды из шкуры кодо — не просто практичное дело, а выражение почтения к животному, которое кормило и носило Шу'хало на протяжении бесчисленных поколений на равнинах Мулгора."}},faq={{q="Кто выдает задание «Сумка из шкуры кодо»?",a="Задание выдает Верен Долгоног, таурен — учитель кожевничества и торговец из Громового Утеса.",al={"quest giver","where to get kodo hide bag quest","veren tallstrider location","персонаж, выдающий задания","где взять задание сумка из шкуры кодо","где верен долгоног"}},{q="Кто может взяться за это задание?",a="Это учебное задание от Верена Долгонога могут получить только искатели приключений, обученные кожевничеству и достигшие уровня навыка ученика не ниже 10.",al={"who can take this quest","quest requirements","profession requirement","кто может взять задание","требования задания","требования к профессии"}},{q="Какие материалы нужны Верену Долгоногу?",a="Ему нужны четыре куска тонкой кожи и четыре мотка грубой нити, чтобы пополнить торговые запасы, прежде чем поделиться выкройкой.",al={"what items are needed","kodo hide bag materials","quest turn-in items","какие предметы нужны","сумка из шкуры кодо материалы","предметы для сдачи задания"}},{q="Почему шкура кодо так важна для ремесленников-тауренов?",a="Кодо воплощают стойкость и физическую мощь — качества, глубоко ценимые тауренами. Изготовление прочного снаряжения из их шкур чтит дух животного и дает надежные вещи путникам, пересекающим равнины.",al={"why kodo hide","tauren kodo meaning","kodo importance","зачем шкура кодо","значение кодо для тауренов","важность кодо"}},{q="Чему учит Верен Долгоног после выполнения задания?",a="Получив материалы, Верен обучает ремесленника особым знаниям, необходимым для пошива сумки из шкуры кодо.",al={"quest reward","what do i get","bag pattern","награда за задание","что я получу","выкройка сумки"}},{q="Где можно достать нужные материалы?",a="Тонкую кожу добывают, снимая шкуры с низкоуровневых зверей по всему Мулгору и соседним землям, а грубую нить можно купить у торговцев и торговцев портняжными товарами.",al={"where to get light leather","where to get coarse thread","где взять тонкую кожу","где взять грубую нить"}}},fp="13,362,20.426.0,18.388.0,35.113.0,39.149.0,46.133.0,59.224.0,50.125.0,46.176.0"}
P.entries["quest:770"] = {n="Поцарапанный демоном плащ",s="«Поцарапанный демоном плащ» — рваная шкура, снятая с легендарного белого волка Призрачного Воя, бродящего по травянистым равнинам Мулгора. Отмеченная неизлечимой раной, нанесенной в прошлых схватках с Пылающим Легионом, шкура служит доказательством освобождения зверя от мучений. Доставка ее старейшинам Деревни Кровавого Копыта завершает историю одной трагической местной легенды.",h="«Поцарапанный демоном плащ» — рваная шкура, снятая с легендарного белого волка Призрачного Воя, бродящего по...",kw={"burning legion","camp sungraze","demon scarred cloak","ghost howl","mulgore","skorn whitecloud","white wolf","пылающий легион","поцарапанный демоном плащ","призрачный вой","мулгор","скорн белое облако","белый волк"},ang={["class:Druid"]="Друиды видят в шкуре со следами демонов мрачное напоминание о том, что земля и ее дикие обитатели до сих пор несут незажившие раны после демонического вторжения в Калимдор.",["class:Hunter"]="Для охотника выследить одинокого израненного вожака вроде Призрачного Воя — важнейшее испытание, которое приносит высокую похвалу и дар мастера-охотника от старейшины Скорна Белого Облака.",["race:Tauren"]="Для Шу'хало охота на Призрачного Воя — не жестокость и не завоевание, а мрачный обряд, дарующий измученному существу покой от остаточной скверны Пылающего Легиона."},sec={{t="Память о скверных ранах",b="Призрачный Вой — неуловимый белый волк, известный по всему Мулгору как своей свирепостью, так и скорбным воем. Когда его убивают, он оставляет шкуру, на которой заметны шрамы от гнусной демонической порчи. Эти следы остались после отчаянных сражений волка с вторгшимися демонами Пылающего Легиона — столкновения, которое ранило Призрачного Воя телом и духом задолго после окончания Третьей войны."},{t="Покой для измученного духа",b="Таурены Мулгора глубоко уважают диких зверей своей родины, почитая их как детей Матери-Земли. Передав израненный плащ Скорну Белому Облаку в Деревне Кровавого Копыта, вы подтверждаете гибель измученного хищника. Скорн понимает, какое огромное мастерство требуется, чтобы выследить и одолеть Призрачного Воя, и с грустью надеется, что после смерти истерзанный дух волка наконец обрел покой."}},faq={{q="Что такое «Поцарапанный демоном плащ»?",a="Это рваная шкура, снятая с Призрачного Воя, легендарного белого волка Мулгора. На шкуре видны шрамы от энергии Скверны, оставшиеся после старой битвы с Пылающим Легионом.",al={"what is demon scarred cloak","demon scarred cloak item","ghost howl pelt","что такое поцарапанный демоном плащ","предмет поцарапанный демоном плащ","шкура призрачного воя"}},{q="Откуда на плаще демонические шрамы?",a="Призрачный Вой получил раны в схватках с Пылающим Легионом, когда демонические захватчики двинулись по Калимдору во время Третьей войны.",al={"why is ghost howl scarred","how did ghost howl get scarred","ghost howl legion","почему у призрачного воя шрамы","как призрачный вой получил шрамы","призрачный вой легион"}},{q="Кому отнести плащ?",a="Отнесите плащ Скорну Белому Облаку, старому охотнику-таурену, живущему в Деревне Кровавого Копыта в Мулгоре.",al={"where do i turn in demon scarred cloak","who wants demon scarred cloak","skorn whitecloud turn in","где сдать поцарапанный демоном плащ","кому нужен поцарапанный демоном плащ","скорн белое облако сдать"}},{q="Почему Скорна Белого Облака волнует Призрачный Вой?",a="Скорн Белое Облако — отошедший от дел охотник, который считает Призрачного Воя грозным зверем, сильно пострадавшим от демонической порчи. Он уважает мастерство, нужное для победы над таким существом, и надеется, что его дух наконец обретет покой.",al={"skorn whitecloud lore","why does skorn want ghost howl","скорн белое облако предания","зачем скорну призрачный вой"}},{q="Где найти Призрачного Воя?",a="Призрачный Вой — редкий белый волк, бродящий по холмистым равнинам Мулгора. Обычно его замечают на северных или центральных открытых полях между Плато Красного Облака и Громовым Утесом.",al={"where to find ghost howl","ghost howl location","ghost howl spawn","где найти призрачного воя","местоположение призрачного воя","появление призрачного воя"}},{q="Почему тауренам хочется, чтобы дух волка обрел покой?",a="Культура тауренов подчеркивает гармонию с природой и почтение к диким духам. Поскольку демоническая порча принесла Призрачному Вою бесконечные мучения, его гибель считается милосердным возвращением к Матери-Земле.",al={"tauren belief ghost howl","ghost howl spirit","вера тауренов призрачный вой","дух призрачного воя"}}},fp="23,378,21.424.0,27.421.0,32.174.0,49.141.0,28.104.0,48.224.0,26.172.0,53.220.0"}
P.entries["quest:771"] = {n="Обряд прозрения",s="Обряд прозрения — основополагающее духовное испытание молодых тауренов, покидающих Плато Красного Облака ради остального Мулгора. Чтобы прозреть и получить наставление духов предков, неофиты должны собрать природные реагенты и сварить Воду Провидцев под присмотром Зарельмана Две Луны в Деревне Кровавого Копыта.",h="Обряд прозрения — основополагающее духовное испытание молодых тауренов, покидающих Плато Красного Облака ради...",kw={"ambercorn","bloodhoof village","earth mother","mulgore","rite of vision","water of the seers","well stones","zarlman two-moons","янтарные зерна","деревня кровавого копыта","мать-земля","мулгор","обряд прозрения","вода провидцев","камни колодцев","зарельман две луны"},ang={["class:Druid"]="Друиды глубоко чтят янтарные зерна и камни колодцев, видя в них прямое воплощение растений и живительных вод, которые поддерживают равновесие Мулгора.",["class:Shaman"]="Шаманы узнают в приготовлении Воды Провидцев традиционный ритуал единения с землей, настраивающий дух на незримые стихии перед прямой беседой с духами.",["race:Tauren"]="Для тауренов Обряд прозрения — важная веха в жизни племени, связывающая будущего воина, охотника или мистика с духовным наследием Матери-Земли и предков."},sec={{t="Дары земли",b="Прежде чем будет дано видение, неофит должен показать глубокое понимание природных даров Мулгора. Зарельман Две Луны велит искателю собрать камни колодцев, лежащие возле священных общинных колодцев, и янтарные зерна, упавшие под корни древних деревьев Мулгора. Эти природные элементы — не просто предметы: для тауренов в них заключены скрытая магия и жизненная сила Матери-Земли, готовые к использованию в обряде."},{t="Приготовление Воды Провидцев",b="Собрав все необходимое, Зарельман смешивает камни и янтарные зерна в могучую Воду Провидцев. Если выпить этот обрядовый напиток у племенного огня деревни, разум проясняется и появляется призрачный проводник. Путь за этим видением по равнинам — истинная суть обряда: он проверяет, способен ли неофит ходить между физическим миром и духовным шепотом земли."}},faq={{q="Для чего нужен Обряд прозрения?",a="Обряд прозрения — духовное испытание для тауренов, достигших зрелости и ищущих свой путь. Приготовив и выпив Воду Провидцев, неофит учится общаться с духами и следовать знамениям предков по равнинам Мулгора.",al={"what is rite of vision","why do rite of vision","purpose of rite of vision","что такое обряд прозрения","зачем нужен обряд прозрения","цель обряда прозрения"}},{q="Кто такой Зарельман Две Луны?",a="Зарельман Две Луны — таурен-шаман и провидец из Деревни Кровавого Копыта. Он руководит духовными испытаниями молодых искателей приключений, готовит обрядовые напитки, такие как Вода Провидцев, и толкует знамения Матери-Земли.",al={"who is zarlman","zarlman two moons role","questgiver zarlman","кто такой зарельман","зарельман две луны","персонаж, выдающий задания зарельман"}},{q="Где найти камни колодцев и янтарные зерна?",a="Камни колодцев собирают с земли возле колодцев с пресной водой, разбросанных по Мулгору. Янтарные зерна можно найти у корней больших раскидистых деревьев, растущих на окрестных травянистых равнинах.",al={"where to find ambercorn","well stones location","reagents for rite of vision","где найти янтарные зерна","камни колодцев где","реагенты для обряда прозрения"}},{q="Что происходит после того, как выпьешь Воду Провидцев?",a="Напиток, выпитый у племенного огня, открывает духовное зрение, и появляется призрачный зверь-проводник. Искатель должен следовать за этим духом по равнинам, чтобы узнать следующий этап священного пути.",al={"what happens next rite of vision","water of the seers effect","vision quest follow-up","что дальше обряд прозрения","действие воды провидцев","продолжение задания прозрения"}},{q="Почему тауренам так священны колодцы?",a="Вода — источник жизни Мулгора и драгоценный дар Матери-Земли. Колодцы — священные общинные места, питающие и землю, и стада, поэтому камни, собранные рядом с ними, наполнены духовной силой.",al={"tauren water wells","why are wells sacred","mulgore water","колодцы тауренов","почему колодцы священны","вода мулгора"}},{q="Ведет ли это задание к другим обрядам?",a="Да. Это задание — часть многоэтапной церемонии. Когда Зарельман приготовит Воду Провидцев, неофиты должны выпить ее, проследовать за появившимся видением и предстать перед старейшинами Мулгора.",al={"next quest in rite of vision","is rite of vision a chain","tauren rites chain","следующее задание обряда прозрения","цепочка обряда прозрения","цепочка обрядов тауренов"}}},fp="14,335,24.476.0,30.397.0,42.238.0,25.234.0,42.210.0,51.214.1,47.219.0,38.207.1"}
P.entries["quest:772"] = {n="Обряд прозрения",s="Обряд прозрения — духовная кульминация древнего испытания молодых тауренов в Деревне Кровавого Копыта. Выпив священную Воду Провидцев у племенного костра, неофиты призывают призрачного проводника, который ведет их к предначертанной судьбе.",h="Обряд прозрения — духовная кульминация древнего испытания молодых тауренов в Деревне Кровавого Копыта.",kw={"bloodhoof village","ghost wolf","mulgore","rite of vision","seer wiserunner","tribal fire","water of the seers","zarlman two-moons","деревня кровавого копыта","призрачный волк","мулгор","обряд прозрения","провидец хранитель мудрости","племенной огонь","вода провидцев","зарельман две луны"},ang={["class:Druid"]="Обряд укрепляет почтение к миру природы и духовное смирение перед наставлением звериных обличий.",["class:Shaman"]="Следование за призрачным волком предков — ранний урок хождения между мирами, укрепляющий связь шамана с духами, ведущими Орду.",["race:Tauren"]="Для юных тауренов Обряд прозрения — глубоко священный переход во взрослую жизнь, выражающий единение с предками и послушание духовному наставлению."},sec={{t="Вода Провидцев",b="Собрав необходимые обрядовые травы и пройдя первые испытания веры, неофит получает Воду Провидцев от деревенского шамана Зарельмана Две Луны. Этот могучий напиток нужно выпить перед ревущим племенным огнем в сердце Деревни Кровавого Копыта. Если пить его со сосредоточенным и почтительным умом, священная вода расширяет восприятие за пределы физического зрения, стирая завесу между материальным миром и миром духов."},{t="Вслед за призрачным волком",b="Когда неофит выпивает отвар, в пламени возникает призрачное видение — волк-дух предков. Он не говорит и не сражается, а молча бежит на северо-запад по холмистым равнинам Мулгора. Истинный неофит должен последовать его тихим путем — прочь от деревни, вглубь скалистых холмов, где в уединенном размышлении ждет отшельник Провидец Хранитель Мудрости."},{t="Путь к мудрости",b="Встреча с Провидцем Хранителем Мудрости у входа в его горную пещеру означает успешное завершение видения. Этот путь по травянистым холмам проверяет терпение неофита, доверие к наставлению предков и связь с Матерью-Землей. Пройдя этот обряд, юный искатель приключений получает право на высшее испытание зрелости — Обряд мудрости."}},faq={{q="Что произойдет, если я выпью Воду Провидцев?",a="Если выпить воду у племенного огня в Деревне Кровавого Копыта, она открывает ваши духовные чувства. Вскоре после этого перед пламенем появляется призрачный волк-дух, чтобы указать вам путь.",al={"how does water of seers work","drinking water of the seers","what does the water do","как действует вода провидцев","выпить воду провидцев","что делает вода"}},{q="Куда ведет меня дух-проводник?",a="Призрачный волк бежит на северо-запад от Деревни Кровавого Копыта по холмам Мулгора и ведет прямо к скалистой пещере, где обитает Провидец Хранитель Мудрости.",al={"where does ghost wolf go","who does the wolf lead to","wolf destination","куда идет призрачный волк","к кому ведет волк","цель волка"}},{q="Кто такой Зарельман Две Луны?",a="Зарельман Две Луны — известный таурен-шаман в Деревне Кровавого Копыта, который готовит неофитов к духовной зрелости с помощью обрядов предков и священных отваров.",al={"who gives the rite of vision","zarlman two moons role","кто дает обряд прозрения","зарельман две луны"}},{q="Кто такой Провидец Хранитель Мудрости?",a="Провидец Хранитель Мудрости — старый таурен-мистик, живущий в размышлениях среди скал к северо-западу от Деревни Кровавого Копыта. Неофиты, следующие за своим духовным видением, находят его, чтобы завершить испытание.",al={"who is wiserunner","seer in cave mulgore","кто такой хранитель мудрости","провидец в пещере мулгор"}},{q="Почему воду нужно пить у племенного огня?",a="Племенной костер служит священным якорем для духов предков Деревни Кровавого Копыта. Освященное пламя и священная вода позволяют видению проникнуть в мир яви.",al={"why tribal fire","bonfire rite of vision","почему племенной огонь","костер обряд прозрения"}},{q="Какой обряд следует за Обрядом прозрения?",a="Завершив Обряд прозрения у Провидца Хранителя Мудрости, неофиты направляются на Обряд мудрости — последнее духовное испытание их раннего пути в Мулгоре.",al={"next quest after rite of vision","what comes next","следующее задание после обряда прозрения","что дальше"}}},fp="14,249,22.467.0,24.371.0,16.362.0,49.192.0,36.150.0,25.171.0,23.189.0,49.197.0,41.173.0"}
P.entries["quest:773"] = {n="Обряд мудрости",s="Обряд мудрости — завершающее испытание в традиционных Обрядах Матери-Земли, которые проходят юные искатели приключений в Мулгоре. Очистив зрение Обрядом прозрения, просители отправляются на священное кладбище Красных скал, чтобы пообщаться с Духом предков и получить благословение мертвых.",h="Обряд мудрости — завершающее испытание в традиционных Обрядах Матери-Земли, которые проходят юные искатели...",kw={"ancestral spirit","mulgore","red rocks","rite of wisdom","rites of the earthmother","seer wiserunner","thunder bluff","water of the seers","дух предков","мулгор","красные скалы","обряд мудрости","обряды матери-земли","провидец хранитель мудрости","громовой утес","вода провидцев"},ang={["class:Druid"]="Обряд показывает равновесие между миром живых и вечным круговоротом, за которым присматривает Мать-Земля, и укореняет юных друидов в долге перед землей.",["class:Shaman"]="Прямое общение с Духом предков укрепляет основной долг шамана — чтить мертвых и хранить верность духам, оберегающим Мулгор.",["race:Tauren"]="Для шу'хало получение покрова от предков у Красных скал — высшая веха перехода во взрослую жизнь и принятия среди старейшин племени."},sec={{t="Испытание Красных скал",b="Очистив восприятие Обрядом прозрения, юные защитники направляются к востоку от Громового Утеса, к Красным скалам. На этом древнем кладбище покоятся останки и неупокоенные духи тех, кто сражался и погиб ради мирной жизни в Мулгоре. Чтобы пройти испытание, нужно подойти к месту упокоения с должным почтением, преодолеть все угрозы, бродящие по холмам, и обратиться за советом к почитаемым мертвым."},{t="Передача покрова",b="На вершине Красных скал общение с Духом предков — это испытание не боевой силы, а духовной готовности и преемственности. Покоящиеся там духи представляют поколение, которое сражалось бок о бок с Кэрном Кровавым Копытом, чтобы основать Громовой Утес и защитить племена. Получив их благословение, проситель официально наследует торжественный долг защищать город и занимает свое место признанного взрослого и защитника, достойного с гордостью войти в Громовой Утес."}},faq={{q="Для чего нужен Обряд мудрости?",a="Обряд мудрости завершает Обряды Матери-Земли, соединяя видения юности с серьезной ответственностью взрослой жизни. Получив благословение духов предков, просители доказывают, что чтят жертвы предшественников и готовы защищать Громовой Утес.",al={"why do rite of wisdom","what does rite of wisdom do","rite of wisdom purpose","зачем нужен обряд мудрости","что дает обряд мудрости","цель обряда мудрости"}},{q="Кто посылает на Обряд мудрости?",a="Провидец Хранитель Мудрости в своей пещере к северо-западу от Деревни Кровавого Копыта посылает неофитов на это испытание, когда они успешно завершили Обряд прозрения и выпили Воду Провидцев.",al={"who gives rite of wisdom","where do i start rite of wisdom","кто дает обряд мудрости","где начать обряд мудрости"}},{q="Где найти Дух предков?",a="Дух предков находится у Красных скал — древнего кладбища тауренов среди скалистых утесов к востоку от Громового Утеса.",al={"ancestral spirit location","where is the spirit","where to find ancestral spirit","где дух предков","где находится дух","как найти дух предков"}},{q="Почему сначала нужен Обряд прозрения?",a="Только те, кто выпил Воду Провидцев и очистил свое духовное зрение, способны воспринять и получить благословение древних духов у Красных скал.",al={"why do vision first","rite of vision prerequisite","water of seers requirement","почему сначала прозрение","требование обряда прозрения","вода провидцев требование"}},{q="Что происходит после завершения Обряда мудрости?",a="Заслужив одобрение предков, неофиты получают указание совершить свое официальное путешествие на высокие уступы Громового Утеса.",al={"what next after rite of wisdom","next quest after rite of wisdom","что дальше после обряда мудрости","следующее задание после обряда мудрости"}},{q="Какие существа угрожают землям Красных скал?",a="На священное кладбище у Красных скал вторглись агрессивные гноллы Бледногривы, которые таятся на каменистых тропах, ведущих к древнему месту погребения.",al={"enemies at red rocks","what guards red rocks","gnolls at red rocks","враги у красных скал","кто охраняет красные скалы","гноллы у красных скал"}}},fp="14,321,22.468.0,18.492.0,42.310.0,36.186.0,39.137.0,41.175.0,49.138.0,49.160.0"}
P.entries["quest:775"] = {n="Путешествие в Громовой Утес",s="Путешествие в Громовой Утес — заключительное паломничество, завершающее испытания юного героя в Мулгоре. Пройдя священные Обряды Матери-Земли под руководством духов, искатель приключений удостаивается встречи с верховным вождем тауренов Кэрном Кровавым Копытом.",h="Путешествие в Громовой Утес — заключительное паломничество, завершающее испытания юного героя в Мулгоре.",kw={"ancestral spirit","cairne bloodhoof","high rise","journey into thunder bluff","mulgore","rites of the earthmother","thunder bluff","дух предков","кэрн кровавое копыто","высокая вершина","путешествие в громовой утес","мулгор","обряды матери-земли","громовой утес"},ang={["faction:Horde"]="Готовность тауренов принять любую союзную расу, прошедшую их священные традиции, говорит о взаимном уважении, на котором держится молодая Орда.",["race:Tauren"]="Для молодого таурена встреча с Кэрном Кровавым Копытом после завершения обрядов Матери-Земли — окончательный порог взрослости и племенной чести."},sec={{t="Завершенный обряд посвящения",b="Прежде чем любой путник или молодой воин сможет по-настоящему считать, что проявил себя в Мулгоре, он должен пройти древние Обряды Матери-Земли. Эти испытания проверяют силу, зоркость и мудрость на холмистых равнинах и в местах предков этой земли. Когда Дух предков признает последний обряд, посвящаемый считается достойным войти в город Громовой Утес не как простой гость, а как почетный защитник народа тауренов."},{t="Подъем на Высокую вершину",b="Задание направляет путника от священной земли, где бродят духи, прямо на головокружительные высоты Громового Утеса. Город, расположенный на вершинах плоскогорий, — маяк мира, высеченный из красного камня и поддерживаемый длинными веревочными мостами и огромными деревянными подъемниками. Там, на Высокой вершине, верховный вождь Кэрн Кровавое Копыто ждет, чтобы лично поприветствовать тех, кто прошел путем предков."}},faq={{q="Кто отправляет вас в это путешествие?",a="Задание выдает Дух предков после того, как вы завершите Обряд мудрости — последний этап традиционных Обрядов Матери-Земли.",al={"who gives quest","ancestral spirit quest","quest giver","кто дает задание","задание духа предков","дух предков","персонаж, выдающий задания"}},{q="Где найти Кэрна Кровавого Копыта?",a="Кэрн Кровавое Копыто обитает на Высокой вершине — центральном возвышенном плато Громового Утеса, с которого открывается вид на окружающие красные плато и равнины.",al={"cairne location","where is cairne","thunder bluff leader","где кэрн","местонахождение кэрна","предводитель громового утеса"}},{q="В чем значение выполнения этого задания?",a="Оно служит официальным выпуском из начальных приключений Мулгора. Явившись к Кэрну, вы будете признаны руководством тауренов и готовы выполнять обязанности по всей Орде.",al={"why visit cairne","rites meaning","significance of thunder bluff journey","зачем идти к кэрну","смысл обрядов","значение путешествия в громовой утес"}},{q="Только ли таурены проходят это путешествие?",a="Хотя это глубоко традиционный обряд посвящения тауренов, любой представитель Орды, доказавший свою преданность через Обряды Матери-Земли, удостаивается той же чести и отправляется на встречу с верховным вождем.",al={"can orcs do this","who can do journey to thunder bluff","races","могут ли орки","кто может пройти путешествие в громовой утес","расы"}},{q="Что происходит после разговора с Кэрном?",a="Кэрн приветствует вас в своем доме, признает ваши деяния и направляет вас к более масштабным конфликтам, с которыми Орда сталкивается по всему Калимдору.",al={"next quest","what after cairne","after journey into thunder bluff","следующее задание","что после кэрна","после путешествия в громовой утес"}},{q="Как добраться до Высокой вершины в Громовом Утесе?",a="Поднимитесь на огромных механических подъемниках с равнин на плато, затем пересеките веревочные и деревянные мосты, ведущие к центральной площадке Высокой вершины, где стоит жилище вождя.",al={"getting to high rise","how to get to cairne","thunder bluff elevators","как добраться до высокой вершины","как попасть к кэрну","подъемники громового утеса"}}},fp="26,296,27.451.0,26.407.0,30.141.0,34.138.0,50.216.0,37.208.0,38.141.0,48.197.0"}
P.entries["quest:776"] = {n="Обряды Матери-Земли",s="Это испытание, назначенное лично верховным вождем Кэрном Кровавым Копытом, поручает восходящим героям выследить великого кодо Арра'чею на равнинах Мулгора. Даже если посвящаемый прошел традиционные обряды, Кэрн ждет, что его народ будет постоянно подтверждать свою силу, умение выслеживать и преданность племени. Рог Арра'чеи доказывает, что искатель приключений готов служить всей Орде за пределами плоскогорий.",h="Это испытание, назначенное лично верховным вождем Кэрном Кровавым Копытом, поручает восходящим героям...",kw={"arra'chea","arrachea","bloodhoof","cairne","earthmother","horn","hunt","kodo","mulgore","thunder bluff","арра'чея","кровавое копыто","кэрн","мать-земля","рог","охота","кодо","мулгор","громовой утес"},ang={["class:Hunter"]="Выслеживание одинокого бродячего исполина вроде Арра'чеи на золотистых равнинах воплощает древние охотничьи философии, которые следопыты-таурены передают из поколения в поколение.",["faction:Horde"]="Победа над Арра'чеей дает Громовому Утесу необходимые пищу, кожу и материалы и показывает дух общего выживания, на котором держится молодая Орда.",["race:Tauren"]="Предстать перед Кэрном Кровавым Копытом с рогом Арра'чеи — высший обряд посвящения для молодого шу'хало, доказывающий, что ваше мастерство чтит и ваших предков, и стада Мулгора."},sec={{t="Мерило вождя",b="Прибытие в Громовой Утес означает конец простой юности для тауренов, но верховный вождь Кэрн Кровавое Копыто не позволяет молодым охотникам почивать на лаврах. Для Кэрна место среди высоких утесов — лишь начало ответственности перед Объединенными племенами тауренов. Вместо того чтобы посылать посвящаемых против мелких вредителей, он требует доказательства настоящего охотничьего мастерства: выследить и чисто добыть одного из самых известных странствующих зверей Мулгора."},{t="Охота на Арра'чею",b="Цель — Арра'чея, огромный легендарный кодо, чей кольцевой путь пролегает по золотистым травам к северо-востоку от Громового Утеса. Чтобы сразить такое создание, нужна не только грубая сила: нужно терпеливо подкрадываться по открытой саванне и уважать титана равнин. Рог Арра'чеи, доставленный на Высокую вершину, приносит не только личную славу, но и припасы для города: Кэрн тут же отправляет свежевальщиков и собирателей, чтобы ничто от священного зверя не пропало."}},faq={{q="Кто выдает это задание?",a="Верховный вождь Кэрн Кровавое Копыто лично поручает это дело со своего места на вершине Громового Утеса.",al={"quest giver","who gives rites of the earthmother","cairne quest","персонаж, выдающий задания","кто дает обряды матери-земли","задание кэрна"}},{q="Кто такой Арра'чея?",a="Арра'чея — грозный, известный кодо, бродящий по равнинам Мулгора. Его огромный рог служит доказательством умения охотника выслеживать добычу и его боевой доблести.",al={"who is arrachea","what is arrachea","arrachea lore","кто такой арра'чея","что такое арра'чея","предания об арра'чее"}},{q="Где найти Арра'чею?",a="Арра'чея обычно бродит по широкой круговой тропе к северо-востоку от утесов Громового Утеса, медленно обходя открытые холмистые равнины по часовой стрелке.",al={"where is arrachea","arrachea location","arrachea path","где арра'чея","местонахождение арра'чеи","путь арра'чеи"}},{q="Почему Кэрн просит об этой охоте, если я уже прошел прежние обряды?",a="В культуре тауренов получение первого места — не конец долга. Кэрн учит, что силу, смирение и охотничье мастерство нужно постоянно доказывать ради блага племени.",al={"why do this quest","why kill arrachea","point of rites","зачем это задание","зачем убивать арра'чею","смысл обрядов"}},{q="Что происходит с телом Арра'чеи после того, как рог взят?",a="Следуя тауренским традициям почитания добычи, Кэрн посылает отряд собирателей забрать мясо и шкуру павшего зверя, чтобы добыча накормила и одела Громовой Утес.",al={"arrachea meat","what happens to the kodo","carcass lore","мясо арра'чеи","что будет с кодо","туша"}},{q="Это то же самое задание, что и начальные обряды?",a="Нет. Пока ранние испытания в Лагере Нараче обучают посвящаемого основам Обрядов Матери-Земли, это заключительное испытание в Громовом Утесе — личная проверка Кэрна, достойны ли вы по-прежнему называться охотником.",al={"rites of the earthmother differences","which rites quest","camp narache rites","различия обрядов матери-земли","какое задание обрядов","обряды лагеря нараче"}}},fp="24,439,21.449.0,22.491.0,21.108.0,18.161.0,27.154.0,78.183.0,57.183.0,50.204.0"}
P.entries["quest:7781"] = {n="Владыка Черной горы",s="Владыка Черной горы — задание Альянса, которое начинается, когда вы забираете отсеченную голову черного дракона Нефариана в Логове Крыла Тьмы. Доставка этого чудовищного трофея верховному лорду Болвару Фордрагону в Крепость Штормграда возвещает падение хозяина Черной горы. Это одна из величайших военных побед, которые Альянс праздновал в недавней истории.",h="Владыка Черной горы — задание Альянса, которое начинается, когда вы забираете отсеченную голову черного...",kw={"blackrock mountain","blackwing lair","highlord bolvar fordragon","head of nefarian","lord of blackrock","nefarian","stormwind keep","черная гора","логово крыла тьмы","верховный лорд болвар фордрагон","голова нефариана","владыка черной горы","нефариан","крепость штормграда"},ang={["faction:Alliance"]="Преподнесение головы черного дракона Нефариана — одно из высших военных достижений Альянса, решительно сокрушившее замыслы драконьего рода против земель людей.",["race:Human"]="Штормград пережил бесчисленные вторжения и заговоры, устроенные из Черной горы; поражение ее владыки приносит королевству долгожданное возмездие и облегчение."},sec={{t="Памятник победе",b="Нефариан, коварный повелитель черного драконьего рода и владыка Верхней Вершины Черной горы, давно отбрасывал жуткую тень на окрестные человеческие королевства. Его убийство — не просто акт выживания, оно означает полный крах его извращенных опытов и интриг. Доставка его огромной, покрытой боевыми шрамами головы в Штормград служит неопровержимым доказательством того, что Владыка Черной горы пал от рук величайших героев Альянса."},{t="Прием в Крепости Штормграда",b="Жуткий трофей приносят прямо верховному лорду Болвару Фордрагону, который правит королевством из тронного зала Крепости Штормграда. Внезапное появление отсеченной головы дракона в королевском дворе потрясает присутствующих и вызывает мгновенное благоговение. Для королевства, и без того измученного внутренними политическими распрями и внешними угрозами, эта победа становится мощным подъемом боевого духа и незабываемой страницей в летописи Альянса."}},faq={{q="О чем задание «Владыка Черной горы»?",a="Это задание начинается, когда искатели приключений забирают отсеченную Голову Нефариана в Логове Крыла Тьмы. Победителю предлагается доставить грандиозный трофей в Штормград и вручить его верховному лорду Болвару Фордрагону от имени королевства.",al={"lord of blackrock quest","nefarian head quest alliance","head of nefarian stormwind","задание владыка черной горы","задание голова нефариана альянс","голова нефариана штормград"}},{q="Кто такой Нефариан?",a="Нефариан — великий черный дракон, сын Смертокрыла. Правя с высот Логова Крыла Тьмы в Черной горе, он командовал орками Черной горы и проводил зловещие опыты по созданию разноцветного драконьего рода.",al={"who is nefarian","lord of blackrock","nefarian lore","кто такой нефариан","владыка черной горы","предания о нефариане"}},{q="Кто такой верховный лорд Болвар Фордрагон?",a="Верховный лорд Болвар Фордрагон — паладин, правящий Штормградом в качестве регента в отсутствие короля Вариана Ринна. Он вершит суд в тронном зале Крепости Штормграда и присматривает за юным принцем Андуином Ринном.",al={"bolvar fordragon","who is bolvar","highlord bolvar","болвар фордрагон","кто такой болвар","верховный лорд болвар"}},{q="Почему трофей приносят в Крепость Штормграда?",a="Владычество Нефариана в Черной горе было смертельной угрозой для королевства Штормград и всего южного континента. Доставка трофея прямо военному руководству королевства подтверждает гибель дракона и позволяет королевству сплотиться вокруг героического подвига.",al={"why stormwind","why bring head to keep","why bolvar","почему штормград","зачем нести голову в крепость","почему болвар"}},{q="Что происходит после передачи головы Болвару?",a="Верховный лорд Болвар Фордрагон потрясен подвигом и объявляет, что эта победа навсегда останется в истории. Это ведет к следующему этапу события, когда голову публично выставляют на обозрение всему Штормграду.",al={"what happens next","lord of blackrock part 2","nefarian head turn in","что дальше","владыка черной горы часть 2","сдача головы нефариана"}},{q="Влияет ли сдача этой головы на весь город?",a="Да. Когда голову Нефариана доставляют в столицу и поднимают над городскими воротами, это возвещает о гибели дракона всем горожанам и солдатам и наполняет защитников Штормграда торжествующей решимостью.",al={"city buff","rallying cry","head of nefarian buff","бонус города","боевой клич","бонус головы нефариана"}}},fp="21,369,21.471.0,26.462.0,42.234.0,16.232.0,33.202.0,45.280.0,45.243.0,48.221.0"}
P.entries["quest:7782"] = {n="Владыка Черной горы",s="Это задание — заключительный итог кампании против сил Черной горы. Доложив верховному адмиралу Джес-Терет в Крепости Штормграда, герои направляются на Аллею Героев, где Фельдмаршал Стоунбридж организует у городских ворот публичное чествование на глазах у всего Альянса.",h="Это задание — заключительный итог кампании против сил Черной горы.",kw={"blackrock","dragonslayer","jes-tereth","nefarian","rallying cry","stonebridge","stormwind","valley of heroes","черная гора","убийца драконов","джес-терет","нефариан","боевой клич","стоунбридж","штормград","аллея героев"},ang={["class:Warrior"]="Огромное воодушевление, которое дает Боевой клич убийцы драконов, придает сил воинам, отправляющимся на защиту королевства.",["faction:Alliance"]="Демонстрация головы Нефариана на Аллее Героев объединяет все расы Альянса и напоминает жителям Стальгорна, Дарнасса и Гномрегана, что темные силы, терзающие Восточные королевства, можно сокрушить.",["race:Human"]="Для королевства Штормград победа над повелителем Черной горы устраняет смертельную угрозу со стороны драконов, притаившихся прямо на северной границе."},sec={{t="Триумф города",b="Кампания против клана Черной горы и отродий черного драконьего рода завершается публичной демонстрацией победы. После того как отрубленную голову Нефариана представили в Крепости Штормграда, верховный лорд Болвар Фордрагон направляет героев через весь город на Аллею Героев. Там их ожидает Фельдмаршал Стоунбридж, чтобы принять жуткий трофей и начать празднования по всему городу."},{t="Сплочение Альянса",b="Когда Фельдмаршал Стоунбридж вздергивает отрубленную голову Нефариана на большие арки главного входа в Штормград, весь город ощущает это потрясение. Зрелище сопровождается Боевым кличем убийцы драконов, который вдохновляет защитников города, приезжих сановников и простых горожан: отродье Смертокрыла получило сокрушительный удар."}},faq={{q="Что произойдет, когда вы выполните это задание?",a="Фельдмаршал Стоунбридж вешает отрубленную голову Нефариана высоко на каменной арке ворот на Аллее Героев. Это накладывает на весь Штормград эффект Боевого клича убийцы драконов, повышающий боевую мощь всех дружественных игроков и стражей.",al={"nefarian head quest turn in","what does stonebridge do","rallying cry trigger","сдать голову нефариана","что делает стоунбридж","боевой клич убийцы драконов"}},{q="Кто такой Фельдмаршал Стоунбридж?",a="Фельдмаршал Стоунбридж — высокопоставленный офицер армии Штормграда, расквартированный на Аллее Героев возле входа в Штормград. Он организует публичное чествование крупных военных побед, в том числе вывешивание голов поверженных драконьих угроз.",al={"stonebridge","field marshal stonebridge","стоунбридж","фельдмаршал стоунбридж"}},{q="Почему верховный лорд Болвар Фордрагон посылает вас сюда?",a="Получив в тронном зале подтверждение поражения Нефариана, Болвар приказывает вам принести весть к городским воротам, чтобы военные Альянса открыто явили победу и подняли боевой дух по всей столице.",al={"bolvar","why go to valley of heroes","болвар","зачем идти на аллею героев"}},{q="Влияет ли эта сдача задания на весь город?",a="Да. Когда Стоунбридж принимает трофей, по Штормграду разносится торжественное объявление, и Боевой клич убийцы драконов накладывается на всех в пределах города.",al={"world buff nefarian","does stormwind get buff","бонус нефариана","дает ли штормград бонус"}},{q="Где находится Аллея Героев?",a="Аллея Героев — величественная въездная дорога в Штормград, обрамленная высокими статуями героев Второй войны, прошедших через Темный портал.",al={"valley of heroes location","where is stonebridge","где аллея героев","где стоунбридж"}},{q="Кто такой «Владыка Черной горы»?",a="Владыка Черной горы — черный дракон Нефариан, старший сын Смертокрыла и правитель верхних шпилей Черной горы.",al={"who is lord of blackrock","nefarian identity","кто владыка черной горы","кто такой нефариан"}}},fp="21,326,16.395.1,21.375.0,42.263.1,33.273.0,49.210.1,40.173.1,38.167.0,32.128.2"}
P.entries["quest:7783"] = {n="Владыка Черной горы",s="Это задание завершает штурм Логова Крыла Тьмы: героям поручено доставить отрубленную голову Нефариана в Оргриммар. Принеся чудовищный трофей вождю Траллу, они получают доказательство того, что отродья черного драконьего рода сломлены. Это момент великого триумфа Орды над одним из ее самых коварных врагов.",h="Это задание завершает штурм Логова Крыла Тьмы: героям поручено доставить отрубленную голову Нефариана в...",ang={["class:Warrior"]="Принести самому Вождю огромный отрубленный череп повелителя драконов — одно из высших свидетельств воинской славы.",["faction:Horde"]="Гибель Нефариана восстанавливает честь Орды и освобождает земли Черной горы от власти дракона, поработившего отступническую Темную Орду.",["race:Orc"]="Для орков вручение головы Нефариана Траллу — возмездие чудовищу, которое дергало за ниточки Ренда Чернорука и порабощало кланы орков ради своих опытов."},sec={{t="Трофей разрушения",b="Нефариан, вдохновитель Логова Крыла Тьмы и предводитель черных драконов в Восточных королевствах, наконец пал. Его огромная голова со следами битв — неопровержимое доказательство его гибели. Для воинов Орды вынести такой великий трофей из пылающих высот Черной горы и доставить его через Великое море в Дуротар — деяние непревзойденной славы."},{t="Суд Вождя",b="Трофей вручают прямо вождю Траллу. Тралл знает порчу Черной горы лучше почти всех: он освободил свой народ из лагерей для военнопленных и увел его от демонической жажды крови Старой Орды. Гибель сына Смертокрыла оправдывает годы борьбы и разрушает жестокую власть темного дракона над орками клана Черной горы."},{t="Тени отца",b="Хотя смерть Нефариана прекращает извращенные генетические опыты черного драконьего рода, его падение не устраняет всех опасностей. Увидев обезглавленного дракона, Тралл замечает, что сам Смертокрыл наверняка пробуждается, узнав о гибели сына. Победа настоящая, но она служит суровым напоминанием о более страшных ужасах, дремлющих под поверхностью мира."}},faq={{q="Кто такой Нефариан?",a="Нефариан — огромный черный дракон, сын Смертокрыла. Со своего насеста высоко в Логове Крыла Тьмы на Черной горе он проводил извращенные опыты по созданию радужного драконьего рода и манипулировал смертными расами, особенно Темной Ордой, заставляя их исполнять его волю.",al={"nefarian backstory","who is nefarian","black dragon lord","история нефариана","кто такой нефариан","повелитель черных драконов"}},{q="Почему трофей доставляют Траллу?",a="Тралл — Вождь Орды. Он вывел орков из лагерей для военнопленных и увел от демонической жажды крови Старой Орды, поэтому доказательство гибели дракона, поработившего орков Черной горы и Темную Орду, должно быть в его руках.",al={"why thrall","who receives the head","почему тралл","кто получает голову"}},{q="Что происходит в Оргриммаре, когда сдают голову?",a="Когда голову Нефариана возвращают и водружают в Оргриммаре, в городе начинается празднование. Вся столица получает Боевой клич убийцы драконов, повышающий боевую мощь всех находящихся рядом представителей Орды.",al={"head buff","orgrimmar world buff","rallying cry buff","бонус головы","бонус оргриммара","боевой клич убийцы драконов"}},{q="Есть ли у этого задания аналог для Альянса?",a="Да, герои Альянса выполняют такое же задание с названием «Владыка Черной горы», доставляя голову Нефариана верховному лорду Болвару Фордрагону в Крепости Штормграда, чтобы даровать своему городу то же благословение.",al={"alliance version","alliance counterpart","версия альянса","аналог альянса"}},{q="Why is Deathwing a concern?",a="Deathwing is Nefarian's father and the patriarch of the black dragonflight. Defeating his son does not remove the danger posed by the dragonfather.",al={"evil one stirs","who is the evil one","злой пробуждается","кто злой"}},{q="Откуда берется голова?",a="Задание начинается с добычи Головы Нефариана прямо с трупа Нефариана после победы над ним на вершине Логова Крыла Тьмы.",al={"how to get head of nefarian","quest starter item","как получить голову нефариана","предмет начала задания"}}},fp="21,364,16.380.0,23.395.0,21.372.1,16.273.0,38.243.0,53.225.0,44.200.0,27.147.0,30.135.0"}
P.entries["quest:7784"] = {n="Владыка Черной горы",s="Это задание — последняя доставка отрубленной головы Нефариана руководителям Оргриммара. Доказав Траллу гибель черного дракона, герои направляются к верховному правителю Саурфангу в Аллее Силы, чтобы выставить трофей перед всей Ордой.",h="Это задание — последняя доставка отрубленной головы Нефариана руководителям Оргриммара.",kw={"blackwing lair","eitrigg","head of nefarian","natoj","orgrimmar","nefarian","valley of strength","логово крыла тьмы","эйтригг","голова нефариана","натож","оргриммар","нефариан","аллея силы"},ang={["faction:Horde"]="Публичный показ головы Нефариана укрепляет новый порядок Тралла и доказывает мощь обновленной Орды перед черным драконом, который манипулировал орками Черной горы.",["race:Orc"]="Для орков падение дракона, державшего клан Черной горы в рабстве, — глубокое очищение, смывающее бесчестную тень с их народа."},sec={{t="Трофей для Орды",b="После того как черный дракон Нефариан убит на вершине Логова Крыла Тьмы, его голову приносят в Оргриммар как доказательство победы. Вождь Тралл подтверждает гибель сына Смертокрыла и отправляет победителя к верховному правителю Саурфангу в Аллее Силы. Там жуткие останки готовят к публичному показу — как предостережение врагам и боевой клич для истинной Орды."},{t="Наследие завоевано",b="Нефариан властвовал на высотах Черной горы, подчиняя своей воле орков Черной горы и Темную Орду. Сразив его и высоко подняв его голову в Аллее Силы, Орда вождя Тралла наносит мощный удар по черному драконьему роду, а Саурфанг призывает весь Оргриммар насладиться Боевым кличем убийцы драконов."}},faq={{q="Для чего нужно это задание?",a="Это заключительная сдача за убийство Нефариана. Показав доказательство Траллу, вы докладываете верховному правителю Саурфангу в Аллее Силы Оргриммара, чтобы получить почести и выставить отрубленную голову на всеобщее обозрение.",al={"what does this quest do","lord of blackrock turn in","why go to saurfang","что дает это задание","сдача владыки черной горы","зачем идти к саурфангу"}},{q="Кто такой верховный правитель Саурфанг?",a="Верховный правитель Саурфанг — опытный орк-воин и один из величайших героев Орды. Он находится в Аллее Силы в Оргриммаре, где принимает голову и велит водрузить ее на всеобщее обозрение.",al={"who is saurfang","high overlord saurfang role","кто такой саурфанг","верховный правитель саурфанг","роль саурфанга"}},{q="Почему голову Нефариана выставляют на показ?",a="Водружение головы черного дракона бесспорно доказывает, что повелитель Черной горы пал. Это укрепляет боевой дух защитников Оргриммара, а на всех в городе накладывается Боевой клич убийцы драконов.",al={"why mount nefarians head","nefarian head display orgrimmar","зачем вешать голову нефариана","голова нефариана в оргриммаре"}},{q="Кем был Нефариан?",a="Нефариан был огромным черным драконом и сыном Смертокрыла. Из Логова Крыла Тьмы на Черной горе он командовал орками Черной горы и Темной Ордой и вывел радужный драконий род.",al={"who was nefarian","nefarian lore","кто такой нефариан","предыстория нефариана"}},{q="Где находится верховный правитель Саурфанг?",a="Саурфанг несет стражу в Аллее Силы — центральном входном районе Оргриммара.",al={"where is saurfang","saurfang location","где саурфанг","местонахождение саурфанга"}},{q="Какую роль в этом играет Тралл?",a="Вождь Тралл принимает голову первым. Подтвердив смерть Нефариана, он отправляет вас к Саурфангу, чтобы трофей официально водрузили.",al={"why thrall","thrall involvement","почему тралл","роль тралла"}}},fp="21,264,22.393.0,19.348.1,34.226.0,30.206.0,38.233.0,17.190.0,40.95.0,35.139.0"}
P.entries["quest:780"] = {n="Боевые вепри",s="«Боевые вепри» — охотничье задание-посвящение, которое выдает Грулл Соколиный Ветер в Лагере Нараче. Молодым тауренам поручено истреблять свирепых обученных для боя вепрей Ежевичной лощины, чтобы защитить земли племени и накормить молодежь поселения.",h="«Боевые вепри» — охотничье задание-посвящение, которое выдает Грулл Соколиный Ветер в Лагере Нараче.",kw={"battleboar","brambleblade ravine","bristleback","camp narache","grull hawkwind","mulgore","quilboar","red cloud mesa","боевой вепрь","ежевичная лощина","дыбогрив","лагерь нараче","грулл соколиный ветер","мулгор","свинобраз","плато красного облака"},ang={["class:Hunter"]="Столкновение со зверями, которых Дыбогривы обучили злобе, учит молодых охотников резкому различию между дикой природой и животными, превращенными в орудия войны.",["profession:Cooking"]="Просьба принести бока и рыла подчеркивает основу тауренской кулинарии: даже жесткое, грубое мясо всегда можно превратить в сытное, питательное рагу.",["race:Tauren"]="Это задание воплощает тауренский баланс: защищать земли Матери-Земли и при этом не терять ничего из добытого в бою, превращая боевых зверей врагов в пищу для телят лагеря."},sec={{t="Угроза на границе",b="К востоку от Плато Красного Облака лежит Ежевичная лощина — поросший колючками шрам, который удерживают свинобразы из племени Дыбогривов. По мере того как напряженность между Шу'хало и свинобразами перерастает в открытую войну, Дыбогривы обучили свирепых боевых вепрей, чтобы прощупывать границы тауренов и терроризировать их исконные охотничьи угодья. Если их не остановить, эти агрессивные звери будут угрожать не только охотничьим тропам, но и безопасности самого Лагеря Нараче."},{t="Прокормить племя",b="Для тауренов охота — одновременно оборона и общая пища. Грулл Соколиный Ветер велит посвящаемым приносить рыла и бока убитых боевых вепрей. Даже звери, обученные свинобразами, не пропадают зря: их мясо и хрящи идут на сытное рагу для молодежи племени, и оружие свинобразов становится пищей для следующего поколения защитников-тауренов."}},faq={{q="Почему боевые вепри нападают на плато?",a="Боевых вепрей намеренно вырастили и обучили свинобразы Дыбогривы, обитающие в Ежевичной лощине. Свинобразы используют их как ударных животных, чтобы донимать тауренов и вторгаться в охотничьи угодья племени на Плато Красного Облака.",al={"battleboar aggression","why battleboars hostile","battleboars attacking","агрессия боевых вепрей","почему вепри враждебны","боевые вепри нападают"}},{q="Кто посылает игроков на эту охоту?",a="Грулл Соколиный Ветер, выдающийся охотник и старейшина в Лагере Нараче, направляет молодых тауренов через заключительные испытания их начального обучения.",al={"quest giver battleboars","who gives the battleboars quest","grull hawkwind role","кто выдает задание боевые вепри","роль грулла соколиного ветра"}},{q="Где можно найти боевых вепрей?",a="Они бродят рядом с Ежевичной лощиной и внутри нее — суровым каньоном к востоку от Лагеря Нараче, на восточном краю Плато Красного Облака.",al={"battleboar location","where are battleboars","brambleblade ravine boars","где боевые вепри","расположение боевых вепрей","вепри ежевичной лощины"}},{q="Что делают с мясом, добытым у вепрей?",a="Бока и рыла боевых вепрей приносят в Лагерь Нараче, где из них варят рагу для детей и старейшин поселения, следуя тауренской традиции использовать все, что добыто на охоте.",al={"battleboar flanks use","what is boar meat for","boar stew","бока боевых вепрей","для чего мясо вепря","рагу из вепря"}},{q="Как это задание вписывается в конфликт со свинобразами?",a="Оно служит ранним введением в открытую вражду между тауренами и племенем Дыбогривов. Истребление их боевых животных — прямое послание свинобразам до начала открытых столкновений с самими Дыбогривами.",al={"tauren quilboar war","bristleback conflict","quilboar lore","война тауренов и свинобразов","конфликт с дыбогривами","предания о свинобразах"}},{q="Какое задание предшествует «Боевым вепрям»?",a="Ему предшествует «Охота продолжается» — прежнее задание Грулла Соколиного Ветра, посвященное знакомству с охотничьими угодьями Плато Красного Облака.",al={"battleboars prerequisite","previous quest battleboars","hunt continues chain","предыдущее задание боевые вепри","охота продолжается","цепочка боевых вепрей"}}},fp="15,237,22.418.0,17.402.0,43.234.0,31.147.0,32.137.0,50.191.0,57.232.0,36.132.0"}
P.entries["quest:781"] = {n="Нападение на Лагерь Нараче",s="«Нападение на Лагерь Нараче» — важная находка в логове свинобразов в Ежевичной лощине. Карта с пятнами грязи показывает, что агрессивное племя Дыбогривов замышляет организованную осаду Лагеря Нараче. Передав эти планы вождю Соколиному Ветру, вы предупреждаете Лагерь Нараче вовремя, чтобы призвать помощь из Деревни Кровавого Копыта.",h="«Нападение на Лагерь Нараче» — важная находка в логове свинобразов в Ежевичной лощине.",kw={"attack plans","bloodhoof village","brambleblade ravine","bristleback","camp narache","chief hawkwind","dirt-stained map","quilboar","red cloud mesa","планы нападения","деревня кровавого копыта","ежевичная лощина","дыбогрив","лагерь нараче","вождь соколиный ветер","карта с пятнами грязи","свинобраз","плато красного облака"},ang={["faction:Horde"]="Сохранение позиций тауренов в Мулгоре обеспечивает Орде жизненно важный южный оплот в центральном Калимдоре.",["race:Tauren"]="Для юных тауренов-воинов, совершающих первые обряды на плато, перехват этой карты доказывает вашу верность племени и защищает ваших сородичей от внезапной резни."},sec={{t="Заговор в зарослях",b="Разведывая глубины пещер Ежевичной лощины, юные таурены-искатели приключений находят на каменном полу грубую карту с пятнами грязи. При внимательном осмотре на пергаменте обнаруживаются продуманные тактические отметки свинобразов Дыбогривов. Свинобразы не просто устраивают случайные стычки, а готовят полномасштабную длительную осаду Лагеря Нараче."},{t="Предупредить вождя",b="Доставив планы нападения в Лагерь Нараче, вы даете вождю Соколиному Ветру важнейшие сведения. Понимая, какая грозная опасность нависла над почти незащищенным лагерем и его юными посвящаемыми, Соколиный Ветер готовится послать весть в Деревню Кровавого Копыта за подкреплением. Перехваченная карта превращает возможную катастрофическую засаду в подготовленную оборону."}},faq={{q="Где найти планы нападения Дыбогривов?",a="Планы лежат на карте с пятнами грязи в пещере Ежевичной лощины, чуть выше по тропе справа от хижины вождя Острого Бивня.",al={"map location","where is dirt-stained map","find the plans","где карта","где карта с пятнами грязи","найти планы"}},{q="Кому передают планы нападения Дыбогривов?",a="Планы нужно доставить напрямую вождю Соколиному Ветру в центр Лагеря Нараче.",al={"who to turn in to","who gets the map","quest ender","кому сдавать задание","кто получает карту","завершение задания"}},{q="Почему свинобразы Дыбогривы нацелились на Лагерь Нараче?",a="Племя Дыбогривов стремится изгнать тауренов с Плато Красного Облака и вернуть охотничьи угодья и священные равнины Мулгора своему народу.",al={"why attack camp narache","quilboar motives mulgore","bristleback siege","зачем нападать на лагерь нараче","мотивы свинобразов мулгор","осада дыбогривов"}},{q="Как вождь Соколиный Ветер планирует противостоять осаде?",a="Благодаря раннему предупреждению от перехваченной карты вождь Соколиный Ветер намерен призвать собратьев из Деревни Кровавого Копыта, чтобы усилить плато и отразить нападение.",al={"hawkwind plan","reinforcements camp narache","план соколиного ветра","подкрепление лагеря нараче"}},{q="Нужно ли с кем-то говорить, прежде чем взять карту?",a="Нет. Задание начинается прямо с Карты с пятнами грязи, лежащей на полу пещеры в Ежевичной лощине, и после подбора карта превращается в планы сражения.",al={"quest starter","dirt stained map starter","how to start attack on camp narache","начало задания","карта с пятнами грязи начало","как начать нападение на лагерь нараче"}},{q="Что будет, если Лагерь Нараче падет?",a="Лагерь Нараче — главное убежище для молодых тауренов-воинов и обрядов посвящения; его потеря подорвет безопасность Плато Красного Облака и лишит Мулгор духовных тренировочных земель.",al={"stakes of camp narache","why defend narache","что на кону в лагере нараче","зачем защищать нараче"}}},fp="22,330,22.393.0,21.361.0,45.143.0,42.85.0,56.152.0,50.168.0,69.149.0,35.185.0"}
P.entries["quest:783"] = {n="Внутренняя угроза",s="Задание «Внутренняя угроза» знаменует начало службы для защитников, откликнувшихся на призыв Штормграда в Долине Североземья. Новобранцев направляют в Аббатство Североземья к маршалу Макбрайду, и они узнают, что войска королевства разбросаны по дальним землям, а местные гарнизоны не справляются с внутренними бедами без помощи гражданских.",h="Задание «Внутренняя угроза» знаменует начало службы для защитников, откликнувшихся на призыв Штормграда в...",kw={"a threat within","abbey","elwynn forest","marshal mcbride","northshire","recruitment","stormwind guard","volunteers","внутренняя угроза","аббатство","элвиннский лес","маршал макбрайд","североземье","набор","стража штормграда","добровольцы"},ang={["faction:Alliance"]="Задание подчеркивает напряжение, с которым сталкивается Великий Альянс: военные обязательства в дальних землях оставляют даже самые надежные коренные области уязвимыми перед внутренним развалом.",["race:Human"]="Поскольку Долина Североземья — стартовая долина для защитников-людей, отклик на призыв маршала Макбрайда становится вашей первой официальной клятвой защищать родину и Королевство Штормград."},sec={{t="Королевство на пределе сил",b="Долина Североземья когда-то была тихим уголком, посвященным молитве, земледелию и монашеским наукам. Сегодня это первая линия обороны от внутренних беспорядков в Элвиннском лесу. Регулярные войска Штормграда разосланы по дальним фронтам, и коренные земли столицы остались опасно малолюдными. Из-за нехватки солдат в этих краях Страже Штормграда приходится принимать любого добровольца, пришедшего к воротам аббатства."},{t="Призыв маршала",b="В Аббатстве Североземья маршал Макбрайд руководит обороной долины в условиях растущей напряженности в регионе. Пока иноземные опасности угрожают Альянсу издалека, разбойники, расплодившиеся вредители и подземные твари пользуются безвластием прямо у порога королевства. Откликнувшись на этот призыв, новобранцы сразу вступают в боевую службу: сначала очищают окрестности аббатства, а затем сталкиваются с более глубокой гнилью, пускающей корни по всему Элвиннскому лесу."}},faq={{q="В чем смысл этого задания?",a="Это вводный призыв для только что прибывших новобранцев в Долине Североземья. Вам предписано войти в Аббатство Североземья и доложить маршалу Макбрайду, чтобы присоединиться к местной обороне.",al={"threat within quest","what is this quest","northshire intro quest","внутренняя угроза задание","что это за задание","вводное задание североземья"}},{q="Кто такой маршал Макбрайд?",a="Маршал Макбрайд — старший офицер Стражи Штормграда, расквартированный в Аббатстве Североземья. Он руководит обороной долины, направляет новобранцев и раздает поручения, чтобы сдерживать угрозы в ближайшей округе.",al={"marshal mcbride","who is mcbride","abbey commander","маршал макбрайд","кто такой макбрайд","командир аббатства"}},{q="Почему Штормград набирает добровольцев вместо того, чтобы прислать регулярные войска?",a="Постоянные армии Штормграда отправлены за границу в дальние походы защищать интересы Альянса. Из-за такой нагрузки гарнизоны коренных земель критически малочисленны, и местным командирам приходится полагаться на недавно прибывших искателей приключений и добровольцев, чтобы защищать собственные дома.",al={"why volunteers","where are the guards","why is stormwind understaffed","почему добровольцы","где стража","почему в штормграде не хватает солдат"}},{q="Какие угрозы сейчас донимают Долину Североземья?",a="Долина сталкивается сразу с несколькими бедами: агрессивные кобольды заселили соседние шахты и холмы, больные или хищные вредители досаждают окрестным виноградникам, а организованные шайки разбойников и бандитов пользуются ослабленным местным гарнизоном.",al={"valley threats","what is attacking northshire","northshire problems","угрозы долины","кто нападает на североземье","проблемы североземья"}},{q="Куда ведет это задание дальше?",a="Доклад маршалу Макбрайду открывает несколько срочных поручений в Североземье: новобранцев отправляют уничтожать вторжения кобольдов на холмах, помогать местным фермерам и рабочим и выяснять, откуда взялось столько организованных бандитов.",al={"next quest","what comes after threat within","mcbride follow up","следующее задание","что после внутренней угрозы","продолжение макбрайда"}},{q="Почему Аббатство Североземья используется как военный командный пункт?",a="Хотя Аббатство Североземья — священное место учения и веры, его укрепленные каменные стены и расположение в центре делают его единственной подходящей базой в долине. Когда местная власть оказалась перегружена, Стража Штормграда разместила командование прямо в его залах.",al={"why military in abbey","northshire church military","holy abbey soldiers","почему военные в аббатстве","церковь североземья военные","солдаты в аббатстве"}}},fp="15,323,24.457.0,18.466.0,34.210.0,23.230.0,75.292.0,54.256.0,37.227.0,62.272.0"}
P.entries["quest:784"] = {n="Бей предателей!",s="«Бей предателей!» — военный удар Орды по приказу Га'Тока из Колючего Холма: нужно отбить Крепость Тирагард у человеческих захватчиков. Силы Кул Тираса под командованием лейтенанта Бенедикта вновь заняли твердыню, прямо нарушив хрупкий мир между Дуротаром и Терамором. Уничтожение гарнизона крайне важно для безопасности восточного побережья родины орков.",h="«Бей предателей!» — военный удар Орды по приказу Га'Тока из Колючего Холма: нужно отбить Крепость Тирагард у...",kw={"daelin proudmoore","durotar","gar'thok","kul tiras","lieutenant benedict","marines","razor hill","sailors","tiragarde keep","vanquish the betrayers","даэлин праудмур","дуротар","га'ток","кул тирас","лейтенант бенедикт","морпехи","колючий холм","моряки","крепость тирагард","бей предателей"},ang={["faction:Horde"]="Захват Крепости Тирагард силами Кул Тираса — продолжающийся акт войны прямо на пороге Дуротара. Уничтожение отряда Бенедикта показывает, что Орда способна защитить свой новый дом от чужеземных флотов.",["race:Orc"]="Орки чтут перемирие, заключенное с Джайной на Горе Хиджал, но Кул Тирас пробуждает горькие воспоминания о Второй войне. Отразить морпехов Бенедикта — вопрос выживания и гордости предков.",["race:Troll"]="Крепость Тирагард находится неприятно близко к поселению Черного Копья — Деревне Сен'джин. Расправа с этими враждебными моряками напрямую защищает уязвимый новый дом троллей."},sec={{t="Разрушенное перемирие",b="Когда Тралл привел Орду через Великое море в Калимдор, он заключил непрочный союз с леди Джайной Праудмур, чтобы победить Пылающий Легион на Горе Хиджал. Этот мир был нарушен, когда отец Джайны, с которым она была в разладе, верховный адмирал Даэлин Праудмур, прибыл с мощным флотом Кул Тираса. Виня всех орков в зверствах Старой Орды, адмирал вторгся в Дуротар и захватил опорные пункты на побережье, включая Крепость Тирагард. Хотя Даэлин в итоге был убит в Тераморе, остатки его флота отказываются чтить любые договоры и отступиться от своей ненависти."},{t="Возрождение Бенедикта",b="После гибели Верховного адмирала Крепость Тирагард ненадолго пала, но резервы Кул Тираса под командованием лейтенанта Бенедикта с тех пор вновь отбили твердыню. Из этого укрепленного оплота между Колючим Холмом и Деревней Сен'джин моряки и морпехи донимают путников и угрожают восточным морским подступам. Га'Ток видит в их укрепившейся позиции непосредственную опасность для безопасности Дуротара и призывает воинов Орды ударить прямо по штабу Бенедикта."}},faq={{q="Почему люди из Кул Тираса нападают на Дуротар?",a="Это остатки экспедиционного флота под командованием верховного адмирала Даэлина Праудмура. Адмирал не желал мирного сосуществования людей и орков и стремился полностью истребить Дуротар. Даже после его смерти его приверженцы продолжают занимать прибрежные редуты вроде Крепости Тирагард, бросая вызов Орде.",al={"why are humans in durotar","kul tiras attacking","tiragarde keep humans lore","почему люди в дуротаре","кул тирас нападает","люди крепость тирагард"}},{q="Кто такой лейтенант Бенедикт?",a="Лейтенант Бенедикт — командир резервов Кул Тираса, которые сейчас удерживают Крепость Тирагард. После поражения верховного адмирала Праудмура Бенедикт собрал уцелевших морпехов и моряков, чтобы отбить прибрежное укрепление и вести постоянные операции против орков.",al={"who is benedict","lieutenant benedict lore","leader tiragarde keep","кто такой бенедикт","лейтенант бенедикт","командир крепости тирагард"}},{q="Поддерживает ли Джайна Праудмур этих людей?",a="Нет. Джайна заключила с вождем Траллом договор о взаимном выживании и открыто выступила против агрессивного похода отца ради сохранения мира. Войска, удерживающие Крепость Тирагард, — отколовшиеся остатки Кул Тираса, отвергающие дипломатию Терамора и считающие перемирие Джайны изменой.",al={"does jaina support them","theramore kul tiras alliance","jaina proudmoore tiragarde","поддерживает ли джайна","терамор кул тирас союз","джайна праудмур тирагард"}},{q="Почему их называют «предателями»?",a="Га'Ток считает их предателями, потому что их вторжение прямо нарушило дипломатическое согласие между Траллом и Джайной Праудмур, достигнутое для победы над Архимондом в Третьей войне. Их постоянное военное присутствие на суверенной земле Орды нарушает послевоенные границы, установленные в Калимдоре.",al={"why betrayers","who betrayed who","betrayers meaning","почему предатели","кто кого предал","значение предателей"}},{q="Где находится Крепость Тирагард?",a="Крепость Тирагард расположена на восточном побережье Дуротара, к югу от Колючего Холма и чуть северо-восточнее Деревни Сен'джин. Ее высокие каменные стены возвышаются над прибрежными водами, давая захватчикам стратегическую базу рядом с поселениями Орды.",al={"tiragarde keep location","where is tiragarde keep","where to find benedict","где крепость тирагард","расположение крепости тирагард","где найти бенедикта"}}},fp="22,366,17.559.0,21.469.0,43.323.0,27.292.0,43.277.0,32.304.0,32.240.0"}
P.entries["quest:786"] = {n="Предотвращение агрессии племени Колкар",s="«Предотвращение агрессии племени Колкар» — важное оборонительное задание Орды, которое дает разведчик Лар Ночной Клык близ Деревни Сен'джин. Игроки должны проникнуть в Утес Колкара и уничтожить три комплекта согласованных планов вторжения, пока племя кентавров не нанесло удар по молодым поселениям Дуротара.",h="«Предотвращение агрессии племени Колкар» — важное оборонительное задание Орды, которое дает разведчик Лар...",kw={"durotar","kolkar","kolkar crag","lar prowltusk","orgrimmar","sen'jin village","thwarting kolkar aggression","valley of trials","дуротар","колкар","утес колкара","лар ночной клык","оргриммар","деревня сен'джин","предотвращение агрессии племени колкар","долина испытаний"},ang={["faction:Horde"]="Остановив наступление Колкара, молодая Орда избегает изнурительной территориальной войны на несколько фронтов прямо на пороге своего нового дома.",["race:Orc"]="В Долине Испытаний юные орки проходят обряды взросления, поэтому агрессия кентавров там — оскорбление самих основ воинской культуры орков.",["race:Troll"]="Уже потеряв свой древний островной дом, тролли Черного Копья не могут допустить, чтобы Деревню Сен'джин захлестнули грабители-кентавры."},sec={{t="Надвигающееся вторжение",b="Разведывая запад Дуротара, тролль-следопыт Лар Ночной Клык под покровом ночи проник в Утес Колкара. Увиденное встревожило его: кентавры Колкара не просто устраивали разрозненные набеги на побережье, а готовили масштабное вторжение по трем направлениям, нацеленное прямо на земли орков и Черного Копья. Военачальники кентавров разделили боевые планы между тремя предводителями, намереваясь ударить по Долине Испытаний, Деревне Сен'джин и самим вратам Оргриммара."},{t="Удар по каньонам",b="Чтобы предотвратить катастрофические бои в сухих красных каньонах Дуротара, новобранцев посылают в глубь Утеса Колкара, чтобы отсечь змее голову. Проникновение в пыльный лагерь и сожжение трех свитков с планами нападения нарушает цепь командования кентавров. Хотя Лар Ночной Клык уверен, что Орда неизбежно сокрушит любое полномасштабное вторжение, уничтожение этих документов избавит защитников Дуротара от дорогостоящего кровопролития, пока молодое государство еще только встает на ноги."}},faq={{q="Кто дает задание «Предотвращение агрессии племени Колкар»?",a="Задание дает Лар Ночной Клык, разведчик-тролль из племени Черного Копья, находящийся недалеко от Деревни Сен'джин на южных обрывах Дуротара.",al={"quest giver","who gives quest","lar prowltusk location","персонаж, выдающий задание","кто дает задание","где лар ночной клык"}},{q="Какие цели планируют атаковать кентавры Колкара?",a="Боевые планы Колкара описывают согласованное наступление в три удара по Долине Испытаний, Деревне Сен'джин и столице Орды — Оргриммару.",al={"centaur targets","what are attack plans","three targets","цели кентавров","какие планы нападения","три цели"}},{q="Где находится Утес Колкара?",a="Утес Колкара — выжженный солнцем комплекс каньонов, спрятанный к западу за скалистыми хребтами от Деревни Сен'джин на юге Дуротара.",al={"kolkar crag location","where is the crag","centaur village durotar","где утес колкара","расположение утеса колкара","деревня кентавров дуротар"}},{q="Где в утесе найти планы нападения?",a="Три свитка с чертежами вторжения хранятся у трех разных предводителей Колкара, охраняющих разные лагеря по всему утесу.",al={"attack plan locations","where are scrolls","centaur leaders","где планы нападения","где свитки","предводители кентавров"}},{q="Почему Колкар хотят вторгнуться в Дуротар?",a="Колкар — агрессивное, экспансионистское племя кентавров, коренных жителей засушливых земель Калимдора. Они считают прибывших орков и троллей Черного Копья чужаками, посягающими на их территорию и охотничьи угодья.",al={"why are centaur attacking","centaur motive","kolkar lore","почему нападают кентавры","мотив кентавров","колкар предания"}},{q="Что происходит после уничтожения планов?",a="Уничтожение документов предотвращает согласованную осаду, расстраивает тактическое наступление Колкара и защищает хрупкие поселения Дуротара от внезапного разорения.",al={"quest aftermath","does centaur attack stop","последствия задания","прекратится ли нападение кентавров"}}},fp="27,294,18.498.0,20.475.0,49.137.0,55.154.0,29.121.0,49.157.0,41.207.0,43.179.0"}
P.entries["quest:787"] = {n="Новая Орда",s="«Новая Орда» — вводное задание в Долине Испытаний, которое выдает ветеран-воин Эйтригг. Он велит новобранцам явиться к Горнеку в Логово, чтобы начать обучение. В этом кратком поручении Эйтригг рассказывает о своем пути и о замысле Тралла — возрожденной Орде.",h="«Новая Орда» — вводное задание в Долине Испытаний, которое выдает ветеран-воин Эйтригг.",kw={"burning legion","durotar","eitrigg","gornek","new horde","the den","thrall","valley of trials","пылающий легион","дуротар","эйтригг","горнек","новая орда","логово","тралл","долина испытаний"},ang={["faction:Horde"]="Это задание воплощает основополагающий дух правления Тралла: полный разрыв с демоническим рабством во имя чести, выживания и наследия предков.",["race:Orc"]="Для молодых орков, вступающих в Долину Испытаний, Эйтригг — живая память о трагическом прошлом их народа и об искуплении под началом Тралла.",["race:Troll"]="Тролли Черного Копья проходят обучение вместе с орками в Долине Испытаний: они приняли замысел Тралла о совместном выживании и чести."},sec={{t="Возвращение ветерана",b="Эйтригг находится в Долине Испытаний по приказу вождя Тралла: он должен оценивать и наставлять новейших кандидатов в Орду. Он покинул Старую Орду после Второй войны, разочаровавшись из-за ее порабощения Пылающим Легионом, и жил в тихом изгнании, пока его не захватили люди. Спасенный Траллом, он решил вернуться, узнав о мечте молодого Вождя: честной Орде, основанной на шаманизме предков и полностью свободной от демонических владык."},{t="Явиться в Логово",b="Прежде чем новобранец сможет покинуть суровые каньоны Долины Испытаний, он должен доказать свою доблесть. Эйтригг отправляет новичков в затененную пещеру, известную как Логово, к Горнеку. Хотя Горнек редко выбирает слова, говоря о неприглядном состоянии новых кандидатов, его надзор гарантирует, что в дальние земли Дуротара попадут лишь те, кто овладел дисциплиной и умением выживать."}},faq={{q="Кто такой Эйтригг?",a="Эйтригг — немолодой орк-ветеран, на собственном опыте видевший, как Пылающий Легион развратил Старую Орду. Разочаровавшись, он удалился в добровольное изгнание в Лордерон. После того как его захватили люди, а затем освободил Тралл, он присягнул на верность вновь созданной Орде Тралла и теперь помогает руководить обучением новобранцев в Долине Испытаний.",al={"who is eitrigg","eitrigg backstory","eitrigg lore","кто такой эйтригг","эйтригг история","эйтригг предыстория"}},{q="Почему Эйтригг говорит о «Новой Орде»?",a="Первоначальная Орда была обманута и порабощена демонической жаждой крови под властью Пылающего Легиона. Новая Орда Тралла была создана, чтобы отбросить демонический контроль, возродить традиционный шаманизм и построить честное, независимое будущее для орков и их союзников в Калимдоре.",al={"what is the new horde","difference between old and new horde","new horde meaning","что такое новая орда","разница между старой и новой ордой","новая орда значение"}},{q="Где находится Горнек?",a="Горнек стоит сразу у входа в Логово — приметную пещеру в северной скальной стене Долины Испытаний.",al={"where is gornek","find gornek","gornek location","где горнек","найти горнека","горнек местонахождение"}},{q="Что происходит после доклада Горнеку?",a="Горнек принимает вас в число учеников Эйтригга и дает первые полевые поручения: вы защищаете долину, а он проверяет, готовы ли вы служить Орде.",al={"next quest after the new horde","what does gornek do","gornek quest","следующее задание после новой орды","что делает горнек","задание горнека"}},{q="Почему Эйтригг был изгнан?",a="Эйтригг покинул Орду, потому что ему были отвратительны демоническая порча и бессмысленная резня, устроенные чернокнижниками на службе Пылающего Легиона во время прежних войн.",al={"why did eitrigg leave","eitrigg exile reason","eitrigg demon corruption","почему эйтригг ушел","причина изгнания эйтригга","эйтригг демоны"}},{q="Почему новобранцев обучают в Долине Испытаний?",a="Долина Испытаний — уединенное суровое место в Дуротаре, где молодые орки и союзные новички могут сразиться с опасными зверями и скорпидами под присмотром опытных наставников, прежде чем отправиться в большой мир.",al={"why valley of trials","purpose of the valley of trials","valley of trials training","почему долина испытаний","назначение долины испытаний","обучение в долине испытаний"}}},fp="13,299,18.465.0,20.397.0,15.378.0,44.288.0,24.139.0,39.181.0,23.179.0,49.232.0"}
P.entries["quest:79"] = {n="Легенда о Сталване",s="Это задание — момент, когда разрозненные слухи о Сталване Мистмантле превращаются в неоспоримое доказательство жестокого преступления. Хозяин таверны Смиттс передает давно скрытые грязные страницы дневника и направляет следователя прямо к командиру Ночного Дозора Алтее Чернодрев.",h="Это задание — момент, когда разрозненные слухи о Сталване Мистмантле превращаются в неоспоримое...",kw={"darkshire","duskwood","ebonlocke","investigation","mistmantle","muddy journal","night watch","smitts","stalvan","темнолесье","сумеречный лес","чернодрев","расследование","мистмантл","грязный дневник","ночной дозор","смиттс","сталван"},ang={["class:Paladin"]="Раскрытие давно похороненных убийств отвечает призванию паладина: он требует ответа за невинные жизни, насильно отнятые во мраке Сумеречного леса.",["class:Rogue"]="Сопоставление образцов почерка в тавернах и пыльных сундуках отражает терпеливую работу сыщика, нередко нужную, чтобы выследить неуловимую добычу.",["faction:Alliance"]="Расследование показывает, что южным землям приходится полагаться на странствующих героев Альянса, чтобы вершить правосудие, когда официальной поддержки Штормграда нет совсем."},sec={{t="Прорыв в Темнолесье",b="Годами мрачная судьба знатной семьи, приезжавшей в Сумеречный лес, оставалась нераскрытой трагедией. Хозяин таверны Смиттс и маршал Хаггард, тогда один из командиров Стражи Штормграда, осмотрели место убийства и нашли несколько рваных грязных страниц дневника. Без образцов почерка и подтверждающих бумаг записи лежали без движения и не могли официально уличить затворника, который, по слухам, жил в глуши. Улики, собранные в Элвиннском лесу, Западном Крае и Сумеречном лесу, наконец связывают почерк со Сталваном Мистмантлом и превращают городские сплетни в бесспорное дело об убийстве."},{t="Передать дело Дозору",b="Темнолесье живет в постоянной осаде нежити, диких зверей и еще худших ужасов, бродящих во мраке леса. У командира Алтеи Чернодрев мало терпения для небылиц и необоснованных подозрений, когда выживание города висит на волоске. Доставка этих грязных страниц соединяет давнюю историю с немедленным военным правосудием. Получив веское доказательство резни на земле Сумеречного леса, Ночной Дозор наконец вынужден признать Сталвана Мистмантла не просто чудаковатым отшельником или героем страшных историй, а опасным беглецом, которого необходимо покарать."}},faq={{q="Какие улики все это время были у хозяина таверны Смиттса?",a="Много лет назад Смиттс вместе с Хаггардом расследовал убийство приезжих дворян. На месте они нашли рваные грязные страницы дневника, но у них не было образцов почерка, чтобы доказать, что их автор — Сталван Мистмантл. До сих пор.",al={"smitts journal pages","muddy journal pages","what did smitts find","страницы дневника смиттса","грязные страницы дневника","что нашел смиттс"}},{q="Почему Смиттс не сообщил об этом командиру Чернодрев раньше?",a="Без доказательств, связывающих почерк на грязных страницах с отшельником-учителем, у Смиттса и Хаггарда были лишь косвенные обрывки. Если бы они принесли командиру Чернодрев непроверенные слухи, их сочли бы бесполезной тратой и без того ограниченного времени Ночного Дозора.",al={"why wait so long","why keep the pages secret","why didn't smitts tell the guard","почему так долго ждали","почему скрывали страницы","почему смиттс не сказал страже"}},{q="Кто такая командир Алтея Чернодрев?",a="Командир Алтея Чернодрев — глава Ночного Дозора, измученного городского ополчения, которое охраняет Темнолесье и патрулирует дороги Сумеречного леса, защищая их от Плети и лесных хищников.",al={"who is ebonlocke","althea ebonlocke role","commander of darkshire","кто такая чернодрев","алтея чернодрев должность","командир темнолесья"}},{q="Какая резня произошла в Сумеречном лесу?",a="Несколько лет назад в Сумеречном лесу была убита приезжая знатная семья. Слухи указывали на их бывшего учителя, Сталвана Мистмантла, но у местных следователей сначала не было неопровержимых улик для обвинения.",al={"what massacre","slaughter of nobles","who was murdered","какая резня","убийство дворян","кого убили"}},{q="Какое место этот этап занимает во всем расследовании?",a="Этот этап — переход от частного расследования к официальному правосудию. Изучив реестры, школьные записи и семейные сундуки в трех землях, вы передаете собранные улики местным властям, чтобы они приняли меры против Сталвана.",al={"stalvan quest chain step","how far in is this","is this the end of the quest","этап цепочки сталвана","как далеко это","это конец задания"}},{q="Почему Ночной Дозор так неохотно расследует старые преступления?",a="Темнолесью ежедневно грозит немедленное уничтожение от бродячих чудовищ, стай воргенов и пауков. Командир Чернодрев должна направить всех стражников на выживание, поэтому для старых дел нужны неопровержимые доказательства, прежде чем она выделит людей.",al={"why is ebonlocke busy","darkshire defense priority","night watch priorities","почему чернодрев занята","оборона темнолесья","приоритеты ночного дозора"}}},fp="21,266,27.595.0,22.573.1,51.232.0,61.273.0,34.200.0,37.217.0,56.266.0,62.245.0"}
P.entries["quest:79008"] = {n="... и записка, которую ты нашел",s="Эта обожженная записка, найденная среди углей догорающего костра в Западном Крае, оставляет загадочную единственную подсказку. Ее опаленное послание намекает на место где-то в мире и призывает нашедшего отыскать «землю-близнеца».",h="Эта обожженная записка, найденная среди углей догорающего костра в Западном Крае, оставляет загадочную...",kw={"blistered note","campfire","charred note","embers","note","twin land","westfall","обожженная записка","костер","обугленная записка","угли","записка","земля-близнец","западный край"},ang={["class:Rogue"]="Расшифровывать загадочные подсказки в потайных лагерях — вторая натура для тех, кто живет шепотом, тайнами и скрытыми посланиями.",["faction:Alliance"]="Для искателей приключений, пытающихся навести порядок в Западном Крае, неопознанный лагерь и загадочный шифр — еще одна тайна на границе королевства."},sec={{t="Догорающий костер",b="Среди заброшенных полей, разграбленных ферм и продуваемых ветрами равнин Западного Края путники часто натыкаются на лагеря бродяг, разбойников и отчаявшихся скитальцев. Но этот небольшой лагерь покинули в спешке или тайком: припасы брошены, а угли еще слабо тлеют. Среди разбросанного мусора лежит опаленный клочок пергамента, переживший огонь."},{t="Загадочное послание",b="На обожженной записке всего два коротких предложения: «Не все, что горит, потеряно. Найди землю-близнеца, найди место». Окутанные тайной слова служат и загадкой, и приглашением, указывая прочь от пустынных полей Западного Края к другой земле, связанной именем, географией или судьбой."}},faq={{q="Что говорится в записке?",a="В обожженной записке сказано: «Не все, что горит, потеряно. Найди землю-близнеца, найди место». Это единственная подсказка, оставленная на заброшенной стоянке.",al={"note text","what is written on the note","blistered note words","текст записки","что написано в записке","слова обожженной записки"}},{q="Где найдена эта записка?",a="Записку находят среди остатков недавнего костра и разбросанных припасов в глуши Западного Края.",al={"note location","where is the note","campfire location","место записки","где записка","где костер"}},{q="Кто оставил костер?",a="Автор неизвестен. Тот, кто разжег костер, ушел недавно, оставив разбросанные припасы и опаленное послание в углях.",al={"who left the note","campfire owner","note author","кто оставил записку","хозяин костра","автор записки"}},{q="Что означает «земля-близнец»?",a="Эта фраза — загадка, указывающая на другой край мира, который отражает землю, где найдена записка, или связан с ней, хотя обугленная записка ничего больше не поясняет.",al={"twin land meaning","what is twin land","where is twin land","значение земли-близнеца","что такое земля-близнец","где земля-близнец"}},{q="Почему записка обгорела?",a="Записка обгорела и обуглилась в углях костра, что говорит о том, что кто-то либо пытался уничтожить ее в спешке, либо небрежно бросил, когда пламя угасало.",al={"why was it burned","did someone try to burn the note","charred note","почему сожжена","пытались ли сжечь записку","обугленная записка"}},{q="Связано ли это с Братством Справедливости?",a="Хотя Западный Край заполонили Братство Справедливости и нищие бродяги, загадочный характер послания говорит о чем-то более темном, чем обычная переписка разбойников.",al={"defias note","is it defias","brotherhood campfire","записка братства справедливости","это справедливость","костер братства"}}},fp="27,250,12.383.0,19.311.0,23.150.0,25.118.0,22.142.0,35.187.0,24.172.0,44.179.0"}
P.entries["quest:791"] = {n="Больше сумок – больше добычи!",s="«Больше сумок – больше добычи!» — вводное задание, которое дает Фурл Хмурый Лоб на сторожевой башне над Колючим Холмом. Старый шрамированный ветеран больше не может сражаться на передовой и просит молодых авантюристов Орды добыть парусину у местных враждебных людей и кентавров, чтобы сшить припасы для их путешествия.",h="«Больше сумок – больше добычи!» — вводное задание, которое дает Фурл Хмурый Лоб на сторожевой башне над...",kw={"canvas scraps","carry your weight","durotar","furl scornbrow","kolkar","razor hill","razor hill watchtower","tiragarde","обрывки парусины","больше сумок – больше добычи","дуротар","фурл хмурый лоб","колкар","колючий холм","сторожевая башня колючего холма","тирагард"},ang={["faction:Horde"]="Каждый молодой солдат в Дуротаре полагается на закаленных ветеранов вроде Фурла Хмурого Лба, которые напоминают новичкам: служить Орде — значит исполнять любой долг, которого требует родина, будь то охрана заставы или шитье из парусины.",["profession:Tailoring"]="Фурл показывает практичное, грубое портняжное дело пограничья: он превращает брошенную плотную парусину людей-захватчиков и кентавров-налетчиков в прочное снаряжение для выживания в глуши.",["race:Orc"]="Фурл воплощает старшее поколение орков, освободившихся от демонической порчи, пересекших море с Траллом и теперь посвящающих последние годы заботе о будущем своей молодой нации."},sec={{t="Призвание ветерана",b="Фурл Хмурый Лоб — ветеран Третьей войны, шедший рядом с вождем Траллом при освоении Дуротара и в отчаянной обороне на горе Хиджал. Теперь годы и старые раны замедлили его, и он больше не берется за топор в бою. Вместо этого он несет бессменную стражу на сторожевой башне Колючего Холма, подает сигнал тревоги при набегах и поддерживает следующее поколение защитников."},{t="Добытая парусина",b="Сигналы рога звучат все реже, по мере того как Орда укрепляет власть в регионе, и Фурл проводит часы за изготовлением полезного снаряжения. Прочную парусину трудно найти в засушливых каньонах Дуротара, но ее в изобилии носят и култирасцы-захватчики на восточном берегу, и кочевые кентавры Колкар, бродящие по равнинам. Обрывки, добытые у этих врагов, дают Фурлу ткань, нужную, чтобы сшить походные сумки для разведчиков."}},faq={{q="Кто такой Фурл Хмурый Лоб?",a="Фурл Хмурый Лоб — стареющий орк-ветеран, несущий службу на сторожевой башне над Колючим Холмом. Он сражался рядом с Траллом при основании Дуротара и стоял в объединенных рядах, победивших Архимонда на горе Хиджал. Не имея возможности биться на передовой, он служит наблюдателем, а в свободное время мастерит походное снаряжение для молодых воинов Орды.",al={"who is furl","furl scornbrow lore","who gives carry your weight","кто такой фурл","фурл хмурый лоб предания","кто дает задание больше сумок – больше добычи"}},{q="Где в Дуротаре найти обрывки парусины?",a="Обрывки парусины можно собрать у култирасцев, занимающих Крепость Тирагард на побережье Дуротара, и у кентавров Колкар, разбивших лагеря на равнинах. И те, и другие носят плотные тканые материалы, которые можно забрать из их лагерей и вещей.",al={"where to get canvas scraps","who drops canvas scraps","canvas scrap locations","где взять обрывки парусины","с кого падают обрывки парусины","места обрывков парусины"}},{q="Где находится сторожевая башня, на которой стоит Фурл?",a="Башня Фурла стоит на высоких скалистых утесах прямо к северо-западу от Колючего Холма. Извилистая тропа за поселением ведет на вершину, где возвышается деревянная смотровая постройка.",al={"where is furl scornbrow","razor hill watchtower location","find razor hill watchtower","где фурл хмурый лоб","сторожевая башня колючего холма","найти башню колючего холма"}},{q="Что Фурл мастерит из обрывков парусины?",a="Фурл сшивает собранные обрывки парусины в прочную походную сумку. Молодым авантюристам, странствующим по Дуротару, дополнительная вместимость для провизии, пайков и трофейного оружия необходима, чтобы выжить в суровой глуши.",al={"what does furl make","what is the canvas used for","canvas scraps reward","что делает фурл","для чего нужна парусина","награда за обрывки парусины"}},{q="Почему старый воин шьет сумки, а не сражается?",a="Десятилетия непрерывных боев сказались на теле Фурла, и он не может соответствовать скорости и силе, которых требует поле боя. Вместо того чтобы сетовать на отставку, он находит честь в охране Колючего Холма и изготовлении снаряжения, которое помогает молодым бойцам защищать родину.",al={"why is furl crafting","why does furl stay in the tower","why isn't furl fighting","почему фурл шьет","почему фурл остается в башне","почему фурл не сражается"}},{q="В какой войне сражался Фурл?",a="Фурл сражался под началом вождя Тралла в Третьей войне, участвовал в заселении Дуротара и в решающей битве на горе Хиджал против Пылающего Легиона. Он с гордостью вспоминает, как откликнулся на боевой клич во время вынужденного временного перемирия между Ордой, ночными эльфами и Альянсом ради победы над Архимондом.",al={"furl battle history","what did furl do before","archimonde furl","боевой путь фурла","что фурл делал раньше","архимонд фурл"}}},fp="17,302,19.390.0,16.458.0,22.359.0,44.251.0,46.190.0,44.239.0,56.310.0,27.327.0"}
P.entries["quest:79192"] = {n="Ступени",s="«Ступени» — расследование, начинающееся с потрепанной записки, оставленной в суровых глубинах Степей. В небрежно исписанном пергаменте сказано, что двое курьеров доставляли грузы для Новой чумы, а то, что с ними случилось, названо простыми несчастными случаями аптекарей. Таинственный автор призывает нашедшего отыскать укромное горное убежище на границе Пустошей.",h="«Ступени» — расследование, начинающееся с потрепанной записки, оставленной в суровых глубинах Степей.",kw={"desolace","mercenaries","mountains","new plague","note","royal apothecary society","stepping stones","the barrens","пустоши","наемники","горы","новая чума","записка","королевское фармацевтическое общество","ступени","степи"},ang={["class:Rogue"]="Выслеживать анонимных осведомителей и проверять тайные тайники в глубинке между Пустошами и Степями — вторая натура для тех, кто имеет дело с кинжалами и разведкой.",["faction:Horde"]="Странникам Орды в Степях предстоит решить, угрожают ли их землям и союзам слухи о доставках смертоносной чумы на землю Калимдора.",["race:Undead"]="Для путешествующих Отрекшихся любое упоминание Королевского фармацевтического общества и его исследований заразы — срочный вопрос безопасности или опасный заговор изнутри."},sec={{t="Записка в глуши",b="Сообщение кое-как прикреплено к деревянной доске в лагере в глубинке и выделяется на фоне суровой природы Степей. В таких лагерях часто тихо сменяются наемники, головорезы и бродяги, ищущие временный приют вдали от чужих глаз Перекрестка или Кабестана. Рваная записка сразу выделяется среди обыденных разговоров в глуши и приглашает к встрече, полной интриги и мрачных намеков."},{t="Шепотки о Новой чуме",b="Автор записки сообщает, что двое агентов доставляли грузы для Новой чумы, а то, что с ними случилось, называет простыми несчастными случаями аптекарей. Курьеры, перевозящие по Калимдору нестабильную заразу, сильно рискуют, и автор предлагает уютное местечко в горах между Степями и Пустошами как безопасное место для разговора."}},faq={{q="О чем говорится в записке, найденной у «Ступеней»?",a="Записка раскрывает, что курьеры, перевозившие материалы для Новой чумы Отрекшихся, внезапно погибли. Автор называет это простыми несчастными случаями аптекарей, но предлагает место встречи в горах, чтобы спокойно обсудить дело.",al={"stepping stones note","what is the note about","stepping stones quest text","записка ступени","о чем записка","текст задания ступени"}},{q="Куда велит идти записка?",a="Автор приглашает читателя в тайный лагерь высоко в горах, разделяющих Степи и Пустоши, вдали от обычных патрульных маршрутов и торговых путей.",al={"where to go stepping stones","cozy spot mountains","stepping stones location","куда идти ступени","уютное местечко в горах","ступени местоположение"}},{q="Что такое Новая чума, упомянутая в письме?",a="Новая чума — смертоносное варево, которое разрабатывает в Подгороде Королевское фармацевтическое общество Отрекшихся. Она предназначена для уничтожения и Плети, и живых врагов, а ее испытания и доставки курьерами по континентам окружены тайной и смертельной опасностью.",al={"what is new plague","royal apothecary plague","apothecary deliveries","что такое новая чума","чума фармацевтического общества","поставки аптекарей"}},{q="Кто написал записку, прикрепленную к доске?",a="Сообщение оставлено анонимно на грубой деревянной доске в лагере в глубинке. Автор не назван и лишь предлагает уютное местечко в горах между Степями и Пустошами как безопасное место для разговора.",al={"who wrote the note","stepping stones author","who is waiting in the mountains","кто написал записку","автор ступеней","кто ждет в горах"}},{q="Почему курьеры Отрекшихся оказались в Калимдоре?",a="Аптекари Отрекшихся часто собирают экзотические яды, споры и реагенты из суровой флоры и фауны Калимдора, организуя поставки через аванпосты Орды и маршруты в глуши.",al={"forsaken in barrens","why new plague in kalimdor","apothecaries in the barrens","отрекшиеся в степях","почему новая чума в калимдоре","аптекари в степях"}},{q="Почему для таких записок используют лагеря в глубинке?",a="Степи обширны и слабо управляются за пределами крупных поселений. Нейтральные станции, места отдыха наемников и лагеря изгоев позволяют путникам, контрабандистам и осведомителям незаметно оставлять вести, не привлекая внимания Орды или местных застав.",al={"backcountry camp lore","mercenary camps barrens","лагерь в глубинке","лагеря наемников степи"}}},fp="15,374,19.427.0,26.331.1,56.229.0,35.175.0,47.261.0,39.206.0,51.192.0,51.273.0"}
P.entries["quest:792"] = {n="Злобные фамильяры",s="«Злобные фамильяры» — раннее задание, которое Зурита Востроглазая дает новоприбывшим бойцам в Долине Испытаний. Наблюдая за испытаниями в долине, Зурита обнаружила коварный грот Пылающего Клинка в соседней пещере. Чтобы сдержать его стремительное распространение, новобранцев отправляют охотиться на демонических фамильяров, выбирающихся на красную землю Дуротара.",h="«Злобные фамильяры» — раннее задание, которое Зурита Востроглазая дает новоприбывшим бойцам в Долине...",kw={"burning blade","burning blade coven","durotar","imps","the den","valley of trials","vile familiars","zureetha fargaze","пылающий клинок","грот пылающего клинка","дуротар","бесы","логово","долина испытаний","злобные фамильяры","зурита востроглазая"},ang={["class:Warlock"]="Орки и тролли-чернокнижники должны считаться с реальностью отступников-заклинателей тьмы, которые используют демонические договоры для разрушения, а не направляют энергию Скверны на выживание Орды.",["faction:Horde"]="Пылающий Клинок — одна из самых непосредственных внутренних угроз Дуротару: он стремится изгнить молодую Орду изнутри, пока она не утвердила свою власть.",["race:Orc"]="Для орков, стремящихся чтить отказ Тралла от демонического рабства, встреча со скверной Пылающего Легиона на священных тренировочных землях — горькое напоминание о том, что наследие Совета Теней все еще гноится."},sec={{t="Тень в долине",b="Долина Испытаний должна быть местом, где молодые орки и тролли Черного Копья доказывают силу, дисциплину и преданность Орде Тралла. Она предназначена для проверки новобранцев на местных хищниках вроде скорпидов и кабанов, а не на демонической порче. Однако в пещере на северо-востоке агенты, называющие себя Пылающим Клинком, устроили тайный грот прямо под бдительным взором надзирателей долины."},{t="Истребление бесов",b="Зурита Востроглазая, инструктор, направленный наставлять новичков возле Логова, заметила тонкую скверну прежде, чем она захлестнула каньон. Мелкие демонические существа, известные как злобные фамильяры, начали выползать из устья пещеры, метая огонь и угрожая любому, кто подойдет слишком близко. Пока Орда не вырвала с корнем хозяев, скрывающихся во тьме, молодым новобранцам поручено истреблять этих младших слуг, чтобы сохранить безопасность долины."}},faq={{q="Кто дает задание «Злобные фамильяры»?",a="Задание дает Зурита Востроглазая. Она стоит у входа в Логово в центре Долины Испытаний.",al={"vile familiars quest giver","who gives vile familiars","where to pick up vile familiars","злобные фамильяры кто дает задание","кто дает злобных фамильяров","где взять злобных фамильяров"}},{q="Кто такие злобные фамильяры?",a="Злобные фамильяры — небольшие демонические существа, похожие на бесов, которых призывают и подчиняют культисты Пылающего Клинка. Они служат мелкими приспешниками и питомцами и жгут нарушителей огнем.",al={"what are vile familiars","vile familiar lore","vile familiars mob type","кто такие злобные фамильяры","предания злобные фамильяры","тип существ злобные фамильяры"}},{q="Где находится Грот Пылающего Клинка?",a="Грот скрыт в пещере на северо-востоке Долины Испытаний, за бродящими пестрыми кабанами и скорпидами-рабочими.",al={"burning blade coven location","where is burning blade coven","cave in valley of trials","грот пылающего клинка местоположение","где грот пылающего клинка","пещера в долине испытаний"}},{q="Почему Пылающий Клинок оказался в Долине Испытаний?",a="Пылающий Клинок — тайный культ, стремящийся подорвать новую Орду Тралла и распространить демоническую порчу. Проникнув в Долину Испытаний, культисты могут скрытно затаиться и угрожать новейшему поколению бойцов Орды.",al={"why is burning blade here","burning blade motives","what does burning blade want","почему здесь пылающий клинок","цели пылающего клинка","чего хочет пылающий клинок"}},{q="Что происходит после выполнения задания «Злобные фамильяры»?",a="Когда фамильяров у пещеры станет меньше, Зурита Востроглазая велит вам спуститься в пещеру, сразиться с предводителем культистов и забрать Медальон Пылающего Клинка.",al={"vile familiars follow up","what comes after vile familiars","burning blade medallion quest","злобные фамильяры продолжение","что после злобных фамильяров","задание медальон пылающего клинка"}},{q="Нужно ли идти вглубь пещеры, чтобы найти фамильяров?",a="Нет. Хотя они обитают в пещере, множество злобных фамильяров кружит у входа и на дне каньона прямо перед устьем пещеры.",al={"are vile familiars inside cave","where to kill vile familiars","farm vile familiars","злобные фамильяры в пещере","где убивать злобных фамильяров","фарм злобных фамильяров"}}},fp="14,360,22.441.0,16.434.0,35.126.0,24.175.0,41.139.0,49.232.0,45.174.1,57.140.0"}
P.entries["quest:794"] = {n="Медальон Пылающего Клинка",s="Это задание выдает чернокнижница Зурита Востроглазая. Оно отправляет молодых новобранцев Орды в глубь пещеры Грот Пылающего Клинка в Долине Испытаний. Там игрокам предстоит схватиться с затаившимся сектантом и вернуть артефакт темной магии — Медальон Пылающего Клинка. Задание показывает, что демоническая скверна активно пускает корни прямо под носом у Орды.",h="Это задание выдает чернокнижница Зурита Востроглазая.",kw={"burning blade","coven","durotar","medallion","the den","valley of trials","warlock","yarrog baneshadow","zureetha fargaze","пылающий клинок","грот","дуротар","медальон","логово","долина испытаний","чернокнижник","йоррог тень проклятия","зурита востроглазая"},ang={["class:Shaman"]="Возвращение оскверненной реликвии помогает Зурите Востроглазой разоблачить демоническую скверну, оскверняющую землю Дуротара.",["class:Warlock"]="Схватка с Йоррогом напоминает об опасностях самовольного поклонения демонам вне дозволенных, тщательно скрываемых договоров, заключенных при власти Тралла.",["faction:Horde"]="Задание становится для молодых новобранцев последним испытанием и показывает их готовность отправиться в дикие земли Дуротара на защиту молодого государства.",["race:Orc"]="Охота на Йоррога Тень Проклятия показывает внутреннюю борьбу новой Орды за искоренение остатков демонической скверны старых порядков прямо в своих учебных лагерях."},sec={{t="Скрытая угроза в долине",b="Пока молодые орки и тролли проходят в Долине Испытаний начальные испытания боем и выживанием, в тени таится коварная опасность. С помощью гаданий чернокнижница Зурита Востроглазая чувствует, что мерзкие прислужники, наводнившие северные утесы, — лишь авангард более темной силы. Глубоко в соседней пещере культ Пылающего Клинка устроил тайный грот, где практикует темные искусства и хранит опасные реликвии демонической силы."},{t="Схватка с Йоррогом Тень Проклятия",b="Сам медальон находится в руках Йоррога Тень Проклятия — орка-чернокнижника, действующего как агент Пылающего Клинка. Йоррог скрывается на возвышенном уступе в глубине подземного логова и повелевает демоническими тварями и темной магией вдали от бдительных глаз надзирателей Долины. Если убить его и забрать медальон, местное руководство культа будет ослаблено, прежде чем его ритуалы проникнут глубже в сердце Дуротара."},{t="Затянувшаяся тень",b="Обретение талисмана подтверждает худшие опасения Зуриты Востроглазой. Хотя грот в Долине Испытаний разгромлен, медальон доказывает, что Пылающий Клинок действует организованно и целенаправленно. Влияние культа простирается далеко за пределы мест посвящения, и это значит, что молодой Орде предстоит столкнуться с куда более обширными демоническими заговорами по всему Дуротару."}},faq={{q="Где найти Грот Пылающего Клинка?",a="Грот Пылающего Клинка находится внутри пещеры в утесах к северу и западу от Логова в Долине Испытаний, среди бесоподобных мерзких прислужников.",al={"coven cave location","where is the cave","burning blade cave valley of trials","где пещера грота","где находится пещера","пещера пылающего клинка долина испытаний"}},{q="У кого находится Медальон Пылающего Клинка?",a="Медальон носит Йоррог Тень Проклятия, орк-сектант-отступник, которого можно найти глубоко в пещере, на возвышенном каменном уступе за неглубоким прудом.",al={"who drops the medallion","yarrog baneshadow","medallion mob","кто носит медальон","йоррог тень проклятия","моб с медальоном"}},{q="Что такое Пылающий Клинок?",a="Пылающий Клинок — коварный культ орков и чернокнижников, оскверненных скверной и преданных демоническим силам. Из тайных логовищ и лагерей они активно плетут интриги против новой Орды Тралла.",al={"who are burning blade","burning blade cult","what is burning blade","кто такие пылающий клинок","культ пылающего клинка","что такое пылающий клинок"}},{q="Почему медальон так важен для Зуриты Востроглазой?",a="Зурита увидела медальон в своих гаданиях. Это предмет силы, питающий темные ритуалы культа, и неоспоримое доказательство того, что демонические агенты проникают в Долину Испытаний.",al={"why does zureetha want it","what is the medallion","zureetha fargaze medallion","зачем он нужен зурите","что за медальон","зурита востроглазая медальон"}},{q="Означает ли победа над Йоррогом конец культа в Дуротаре?",a="Нет. Хотя гибель Йоррога очищает пещеру в Долине Испытаний, Зурита предупреждает, что этот ковен — лишь небольшая ячейка, а у Пылающего Клинка гораздо более масштабные замыслы по всему Дуротару.",al={"is the burning blade destroyed","are they gone","after burning blade medallion","уничтожен ли пылающий клинок","они исчезли","после медальона пылающего клинка"}},{q="Что происходит после сдачи медальона?",a="Доказав свою доблесть, убив Йоррога и вернув реликвию, вы считаетесь готовым покинуть Долину Испытаний и получаете приказ явиться в Деревню Сен'джин на южном побережье Дуротара.",al={"next quest","what comes next","after this quest","следующее задание","что дальше","после этого задания"}}},fp="23,363,29.453.0,29.434.1,20.361.1,40.168.0,44.165.0,26.180.0,54.208.0,53.189.0,44.190.0"}
P.entries["quest:8"] = {n="Выгодная сделка",s="Казалось бы, обычная услуга Кальвину Монтеччи в Могильнике отправляет путника в таверну «Петля висельника» в Брилле. Поручение — доставить Хозяйке таверны Ренни загадочное письмо без адреса под видом обычной курьерской работы.",h="Казалось бы, обычная услуга Кальвину Монтеччи в Могильнике отправляет путника в таверну «Петля висельника» в...",kw={"brill","calvin montague","deathknell","gallows end","innkeeper renee","nondescript letter","rogue","tirisfal glades","брилл","кальвин монтеччи","могильник","петля висельника","хозяйка таверны ренни","ненадписанное письмо","разбойник","тирисфальские леса"},ang={["class:Rogue"]="Частное поручение курьера Кальвина Монтеччи дает представление о неформальных делах, которые ведутся в Могильнике и Брилле.",["faction:Horde"]="Доставка прямо ведет в Брилл и знакомит недавно прибывших союзников с региональным центром управления и отдыха Отрекшихся в Тирисфале.",["race:Undead"]="Для недавно восставших Отрекшихся это поручение — первое путешествие прочь от безопасного кладбища Могильника к шумному Бриллу."},sec={{t="Дружеский курьер",b="Расположившись среди мрачных могил и разрушенных часовен Могильника, Кальвин Монтеччи выдает себя за измученного бойца, которому досаждают зомби Плети и ползучие пауки. Заявив, что ему просто нужна помощь с доставкой послания в Брилл, он вручает проходящим искателям приключений ненадписанное письмо. Его беспечный вид и обещание щедрой платы делают поручение безобидной услугой, призванной направить недавно пробудившихся Отрекшихся в главный город региона."},{t="Таверна «Петля висельника»",b="Дорога ведет на восток через погибающие деревья Тирисфальских лесов, мимо поместья «Остывший Очаг», к поселению Брилл. За стойкой местной таверны хозяйка таверны Ренни поначалу встречает новичков пугающе солнечным настроем и заботится об удобстве посетителей. Однако получив письмо Монтеччи, она тут же теряет радушие. Отбросив напускную любезность, она притворяется, что получила весть от любимой матери, затем отчитывает посыльного за любопытство и требует что-нибудь купить или уйти. Возвращение к Кальвину приводит к новому сюрпризу: вместо мирной выплаты обещанной награды он вызывает посыльного на дуэль."}},faq={{q="Кто такой Кальвин Монтеччи?",a="Кальвин Монтеччи — разбойник из Могильника, который просит только что пробудившихся путников отнести письмо хозяйке таверны Ренни в Брилле. Он представляет это как простую услугу и обещает хорошо заплатить.",al={"calvin montague","who gives a rogues deal","quest giver","кальвин монтеччи","кто дает задание выгодная сделка","персонаж, выдающий задания"}},{q="Что внутри Ненадписанного письма?",a="The letter's exact contents are not recorded. Calvin gives the courier an unmarked message to deliver to Innkeeper Renee in Brill.",al={"nondescript letter contents","what is in the letter","calvins letter","содержание ненадписанного письма","что в письме","письмо кальвина"}},{q="Почему Хозяйка таверны Ренни ведет себя так странно?",a="Ренни держит таверну в Брилле и настаивает, что ее переписка личная. Узнать ее реакцию на доставку можно, принеся ей письмо Монтеччи.",al={"innkeeper renee attitude","why is renee fake","renee mother excuse","отношение хозяйки таверны ренни","почему ренни притворяется","отговорка про мать ренни"}},{q="Платит ли Кальвин Монтеччи за доставку на самом деле?",a="Монтеччи обещает хорошо заплатить за доставку. Когда письмо попадает к Ренни, она предлагает еду или воду; после этого вернитесь к Кальвину, чтобы продолжить дела, связанные с обещанной платой.",al={"did calvin scam me","where is my money","montague reward","кальвин обманул","где мои деньги","награда монтеччи"}},{q="Где находится Брилл?",a="Брилл расположен к северо-востоку от Могильника. Путники идут по главной дороге на восток из начальной долины, поворачивают направо у поместья «Остывший Очаг» и по крытому мосту попадают в поселение.",al={"how to get to brill","road to brill","brill directions","как добраться до брилла","дорога в брилл","как пройти в брилл"}},{q="Что происходит после передачи письма Ренни?",a="Продолжение — еще одно задание под названием «Выгодная сделка». Вернитесь к Кальвину Монтеччи в Могильнике, чтобы продолжить дела с ним.",al={"next quest","a rogues deal follow up","what to do after renee","следующее задание","продолжение выгодной сделки","что делать после ренни"}}},fp="14,250,18.483.0,23.691.1,23.180.0,38.130.0,40.160.0,51.182.0,23.181.0,46.130.1"}
P.entries["quest:804"] = {n="Саркот",s="Отомстив за раненого тролля Хана'зуа и убив чудовищного скорпида Саркота, искатель приключений должен доставить весть о его беде в Логово. Горнека необходимо предупредить, чтобы помощь успела дойти до пострадавшего разведчика, пока ядовитые раны не отняли у него жизнь.",h="Отомстив за раненого тролля Хана'зуа и убив чудовищного скорпида Саркота, искатель приключений должен...",kw={"darkspear","durotar","gornek","hana'zua","sarkoth","scorpid","the den","valley of trials","черное копье","дуротар","горнек","хана'зуа","саркот","скорпид","логово","долина испытаний"},ang={["faction:Horde"]="Новая Орда строится на взаимной выручке в суровой, безжалостной земле; не бросать товарища — основополагающий принцип, который прививают с первых шагов новобранца.",["race:Orc"]="Культура орков ценит личную силу, но защита чести беспомощного союзника доказывает сердце настоящего воина.",["race:Troll"]="Зарождающийся союз племени Черного Копья и орков Тралла крепнет благодаря поступкам братства, таким как спасение Хана'зуа от медленной, мучительной смерти от яда."},sec={{t="Беда разведчика",b="Разведчик племени Черного Копья Хана'зуа застрял на высоких утесах Долины Испытаний: отравленный ядом, он не мог без помощи спуститься по опасным тропам. Хотя Саркот — грозный скорпид, сразивший его, — был наказан, одной гордостью не пронести отравленного воина по сухим камням. Прикованный к своей скале, он надеется, что проходящий мимо новобранец передаст весть вниз, в лагерь обучения."},{t="Честь в Логове",b="Возвращение к Горнеку в Логове завершает испытание. Горнек сразу понимает, какую угрозу представляет Саркот, и быстро организует помощь Хана'зуа. По мнению командиров Орды, готовность отложить собственное обучение, чтобы отомстить за павшего незнакомца и спасти его, воплощает истинную честь и доказывает ценность новобранца задолго до того, как он выйдет в Дуротар."}},faq={{q="Кто такой Хана'зуа и почему он застрял?",a="Хана'зуа — молодой разведчик-тролль из племени Черного Копья. Он забрался высоко в Долину Испытаний, где на него напал и отравил чудовищный скорпид Саркот. Он слишком слаб, чтобы спуститься сам, и ему нужно спасение.",al={"hanazua","who is hanazua","why is the troll hurt","хана'зуа","кто такой хана'зуа","почему тролль ранен"}},{q="Кто такой Горнек?",a="Горнек — орк-надзиратель, расквартированный в Логове в Долине Испытаний. Он оценивает новобранцев, дает задания на выживание и организует помощь, когда новички сталкиваются со смертельной опасностью в ущелье.",al={"gornek","where is gornek","den leader","горнек","где горнек","глава логова"}},{q="Что такое Саркот?",a="Саркот — известный огромный скорпид, обитающий на скалистых утесах над Долиной Испытаний. Его яд и свирепость делают его легендарной опасностью среди испытаний молодых орков и троллей.",al={"sarkoth beast","what kind of monster is sarkoth","саркот","что за чудовище саркот","скорпид саркот"}},{q="Выживет ли Хана'зуа после ран?",a="Да. Выслушав ваш доклад, Горнек сразу посылает на утесы спасательный отряд, чтобы вылечить его от яда и благополучно вернуть в лагерь.",al={"does the troll live","is hanazua okay","hanazua saved","выживет ли тролль","в порядке ли хана'зуа","хана'зуа спасен"}},{q="Почему Горнек так высоко ценит этот поступок?",a="Выжить в испытаниях — это ожидаемо, но отложить свои дела, чтобы отстоять честь незнакомца и спасти ему жизнь, — пример основных ценностей, которые новая Орда стремится воспитать в своих воинах.",al={"why does gornek care","gornek honor speech","почему горнека это волнует","речь горнека о чести"}},{q="Где находится Логово?",a="Логово — главная учебная пещера и сборный пункт в самом сердце Долины Испытаний на юго-западе Дуротара.",al={"where is the den","den location durotar","где логово","логово дуротар"}}},fp="7,254,16.425.0,16.363.0,39.228.0,14.201.0,16.197.0,33.141.1,43.198.0,25.125.0"}
P.entries["quest:805"] = {n="Деревня Сен'джин",s="Задание «Деревня Сен'джин» отмечает момент, когда молодые новобранцы Орды покидают уединенную Долину Испытаний, чтобы предупредить троллей Черного Копья о деятельности демонического культа. По поручению Зуриты Востроглазой гонцы несут весть о Пылающем Клинке Мастеру Гадрину и узнают, что магия тени уже угрожает ближним берегам.",h="Задание «Деревня Сен'джин» отмечает момент, когда молодые новобранцы Орды покидают уединенную Долину...",kw={"burning blade","darkspear","durotar","echo isles","master gadrin","sen'jin village","valley of trials","zureetha fargaze","пылающий клинок","черное копье","дуротар","острова эха","мастер гадрин","деревня сен'джин","долина испытаний","зурита востроглазая"},ang={["faction:Horde"]="Это задание показывает важное сотрудничество основных рас Орды Тралла, обменивающихся сведениями для защиты молодых поселений друг друга.",["race:Orc"]="Для молодых орков уход из Долины Испытаний на помощь племени Черного Копья — ранняя проверка чести и солидарности с союзниками, стоявшими рядом с Траллом за Великим морем.",["race:Troll"]="Возвращение в Деревню Сен'джин лицом к лицу сводит героев Черного Копья с изгнанием их народа и продолжающейся борьбой за возвращение Островов Эха."},sec={{t="Уход из Логова",b="Доказав боевую доблесть и добыв темные медальоны в Гроте Пылающего Клинка в Долине Испытаний, новички считаются готовыми к большому миру. Зурита Востроглазая понимает, что демоническое присутствие на священной земле испытаний — не случайная досада, а признак подкрадывающейся порчи по всему Дуротару. Она направляет молодых героев на восток за выход из ущелья, а затем на юг к побережью, чтобы предупредить племя Черного Копья."},{t="Тени над побережьем",b="Прибыв в прибрежное поселение Деревня Сен'джин, путники передают предупреждение Мастеру Гадрину, старейшему знахарю, ведущему племя Черного Копья в изгнании. Гадрин подтверждает, что сам Пылающий Клинок на пески деревни не наступал, но сообщает, что темная магия пустила корни неподалеку, на Островах Эха. Донесение показывает, насколько хрупок оплот молодой Орды: пока союзники спешат на помощь друг другу, древнее племенное предательство и скверна Скверны бьют по их флангам одновременно."}},faq={{q="Почему Зурита Востроглазая отправляет людей из Долины Испытаний?",a="Обнаружив демоническую деятельность в Долине Испытаний, Зурита Востроглазая опасается, что культ Пылающего Клинка представляет организованную угрозу для всего Дуротара. Она посылает проверенных новобранцев за пределы долины, чтобы предупредить союзные поселения и выяснить, как далеко распространилось влияние культа.",al={"why leave valley","why go to senjin","zureetha fargaze orders","почему покинуть долину","почему идти в сен'джин","приказ зуриты востроглазой"}},{q="Кто такой Мастер Гадрин?",a="Мастер Гадрин — старейший знахарь и духовный лидер троллей Черного Копья, живущих в Деревне Сен'джин. Он советник вождя Вол'джина и руководит делами племени, пока над их временным прибрежным убежищем нависают угрозы.",al={"master gadrin lore","who is gadrin","мастер гадрин","кто такой гадрин"}},{q="Нападал ли Пылающий Клинок на Деревню Сен'джин?",a="Нет, Пылающий Клинок напрямую на Деревню Сен'джин не нападал. Однако Мастер Гадрин отмечает, что родственная темная магия и предательство пустили корни неподалеку, на Островах Эха, а значит, троллям самим грозит неминуемая опасность.",al={"is burning blade in senjin","cult in senjin","пылающий клинок в сен'джин","культ в сен'джин"}},{q="Где находится Деревня Сен'джин?",a="Деревня Сен'джин лежит на восток от главного выхода из каньона Долины Испытаний, а затем на развилке дороги нужно повернуть на юг, к юго-восточному побережью Дуротара.",al={"how to get to senjin","senjin village direction","как добраться до сен'джин","где деревня сен'джин"}},{q="Какую угрозу на Островах Эха упоминает Мастер Гадрин?",a="Мастера Гадрина тревожит черное предательство Залазана, такого же тролля-знахаря, который коварными порчами поработил соплеменников и захватил власть над Островами Эха, вытеснив уцелевших троллей Черного Копья на материк.",al={"echo isles trouble","what happened at echo isles","беда на островах эха","что случилось на островах эха"}},{q="Что происходит после доклада Мастеру Гадрину?",a="Выслушав ваш доклад и рассказ о беде троллей, Гадрин просит вас помочь против опасностей, угрожающих побережью, а дальнейшие указания отправляют вас на северо-запад к Оргнилу Душегрызу в Колючий Холм.",al={"next quest after report to senjin","what to do after gadrin","следующее задание после деревни сен'джин","что делать после гадрина"}}},fp="25,322,15.449.0,22.510.1,70.285.0,21.259.0,47.227.0,33.168.0,57.234.0,46.216.0"}
P.entries["quest:806"] = {n="Сгущаются черные тучи",s="«Сгущаются черные тучи» — важное задание Оргнила Душегрыза из Колючего Холма: уничтожить мятежного чернокнижника, оскверняющего землю. Гоблин по имени Пшикс Черношквал закрепился в Громовом хребте от имени коварного культа Пылающего Клинка. Его устранение жизненно важно, чтобы защитить Дуротар от демонического возрождения, пока культисты не распространились дальше.",h="«Сгущаются черные тучи» — важное задание Оргнила Душегрыза из Колючего Холма: уничтожить мятежного...",kw={"burning blade","dark storms","durotar","fizzle darkstorm","fizzle's claw","orgnil soulscar","razor hill","thunder ridge","пылающий клинок","сгущаются черные тучи","дуротар","пшикс черношквал","клешня пшикса","оргнил душегрыз","колючий холм","громовой хребет"},ang={["class:Shaman"]="Темные обряды Пшикса и его приспешников нарушают природных духов Громового хребта, тревожат его зверей и требуют восстановления баланса стихий.",["class:Warlock"]="Пшикс Черношквал показывает безрассудную опасность неконтролируемой преданности Скверне: он позор и угроза, которую дисциплинированные чернокнижники Орды терпеть не могут.",["faction:Horde"]="Защита сердца Дуротара от демонического подрыва позволяет зарождающейся Орде направлять оборону вовне, а не рушиться изнутри.",["race:Orc"]="Пылающий Клинок олицетворяет темное прошлое, которое орки каждый день стремятся преодолеть. Устранение культистов-лазутчиков вроде Пшикса необходимо для сохранения свободного народа Тралла."},sec={{t="Угроза в хребте",b="Пока молодые защитники Орды патрулируют границы Дуротара, у них под носом зреет внутренняя порча. Оргнил Душегрыз, ведя расследование из Колючего Холма, обнаружил, что Громовой хребет на северо-западе подпал под власть темной магии. Ущелье кишит культистами Пылающего Клинка, несущими разорение и хаос местным животным и земле."},{t="Пшикс Черношквал",b="Деятельностью культистов в хребте руководит Пшикс Черношквал, расчетливый гоблин-чернокнижник, союзник Пылающего Клинка. Он не служит торговле или интересам картелей, а напрямую использует силу Скверны ради подрывных целей культа. Убийство Пшикса и добыча его искореженной клешни докажет Оргнилу, что ближайшее руководство культа в ущелье сломлено."},{t="Искоренение культа",b="Пылающий Клинок воплощает все, что новая Орда Тралла стремится оставить позади: демоническое рабство, безрассудную порчу и кровожадное безумие. Убийство Пшикса устраняет действующего заговорщика из глубины Дуротара, но также говорит о том, что тень над родиной орков простирается гораздо глубже отдельных лагерей."}},faq={{q="Кто такой Пшикс Черношквал?",a="Пшикс Черношквал — гоблин-чернокнижник, действующий от имени культа Пылающего Клинка. Он с последователями-культистами укрылся в Громовом хребте и сеет демонический хаос в ущелье, пока Оргнил Душегрыз не требует его казни.",al={"who is fizzle","fizzle darkstorm lore","fizzle goblin","кто такой пшикс","пшикс черношквал","гоблин пшикс"}},{q="Где находится Громовой хребет?",a="Громовой хребет — суровый каньон на северо-западе Дуротара, к северу от Колючего Холма и чуть юго-западнее Оргриммара. Он известен тем, что кишит зверями, напитанными молниями, и лагерями культистов Пылающего Клинка.",al={"where is thunder ridge","thunder ridge location","how to find thunder ridge","где громовой хребет","расположение громового хребта","как найти громовой хребет"}},{q="Почему Пылающий Клинок находится в Дуротаре?",a="Пылающий Клинок стремится подорвать Орду Тралла и вернуть демоническое господство над орками. Культисты тайно действуют из скрытых ущелий, пещер и каньонов по всему Дуротару, сея порчу изнутри.",al={"burning blade in durotar","why are cultists in durotar","burning blade motives","пылающий клинок в дуротаре","почему культисты в дуротаре","мотивы пылающего клинка"}},{q="Почему Оргнилу Душегрызу нужна именно клешня Пшикса?",a="Оргнилу нужно неоспоримое доказательство, что чернокнижник уничтожен. Клешня Пшикса подтверждает, что глава культистов в Громовом хребте больше не может руководить действиями.",al={"why fizzle claw","fizzle's claw meaning","proof of death fizzle","зачем клешня пшикса","клешня пшикса значение","доказательство смерти пшикса"}},{q="Что происходит после убийства Пшикса?",a="Победа над Пшиксом устраняет непосредственную угрозу в Громовом хребте, и Оргнил Душегрыз отправляет вас к шаману Маргозу, который больше знает о порче Пылающего Клинка, чтобы вы искоренили дальнейшие заговоры Пылающего Клинка.",al={"what comes after dark storms","dark storms follow up","next quest after dark storms","что после сгущаются черные тучи","продолжение сгущаются черные тучи","следующее задание после сгущаются черные тучи"}},{q="Почему гоблин служит Пылающему Клинку?",a="Хотя многие гоблины ищут золото через торговые картели, некоторых соблазняют грубая сила, влияние и темные искусства магии тени. Пшикс принял колдовство Скверны и отдал свою безжалостную хитрость на службу культистам.",al={"goblin in burning blade","why is fizzle with the cult","fizzle warlock","гоблин в пылающем клинке","почему пшикс с культом","пшикс чернокнижник"}}},fp="11,352,21.362.0,16.385.0,20.328.1,24.237.0,31.216.0,36.211.0,57.194.0,35.221.1,46.223.0"}
P.entries["quest:808"] = {n="Череп Миншины",s="Мастера Гадрина из Деревни Сен'джин преследуют отчаянные крики его умершего брата, Миншины. Убитый и подвергнутый темной магии вероломным знахарем Залазаном на Островах Эха, дух Миншины остается заключенным в его собственном отсеченном черепе. Чтобы освободить павшего тролля, нужно проникнуть на ритуальную площадку Залазана, забрать реликвию и избавить его дух от вечных мук.",h="Мастера Гадрина из Деревни Сен'джин преследуют отчаянные крики его умершего брата, Миншины.",kw={"circle of power","darkspear","echo isles","gadrin","minshina","sen'jin village","skull","voodoo","zalazane","круг силы","черное копье","острова эха","гадрин","миншина","деревня сен'джин","череп","вуду","залазан"},ang={["class:Priest"]="Жрецы понимают глубокую святость ушедшей души и видят ужас ритуальной некромантии, которая не дает павшему брату обрести вечный покой.",["class:Shaman"]="Шаманы чтят духов предков; разрушив круг Залазана и освободив измученную душу, они восстанавливают равновесие между миром духов и миром живых.",["faction:Horde"]="Помощь Мастеру Гадрину чтит узы между новой Ордой и племенем Черного Копья и доказывает, что горе союзника разделяют все.",["race:Troll"]="Для тролля из племени Черного Копья возвращение черепа Миншины — священный долг перед семьей и племенем и удар по извращению Залазаном предковых традиций вуду."},sec={{t="Мольба из тени",b="Мастер Гадрин — один из духовных столпов племени Черного Копья в Деревне Сен'джин, но его разум терзают мрачные видения. Его брат Миншина стал жертвой предательства Залазана, когда безумный чернокнижник захватил власть над Островами Эха. Миншина погиб в этой схватке, но по тролльским обычаям и в мистике вуду физическая смерть не всегда дарует покой. Измученный голос Миншины звучит в снах Гадрина, умоляя спасти его от участи, худшей чем смерть."},{t="Круг силы Залазана",b="Залазан не просто убивает бывших собратьев — он пленяет их души, чтобы питать свое темное колдовство. Сущность Миншины была ритуально связана с его собственным черепом, который теперь лежит посреди богохульного круга силы на самом большом из Островов Эха. Череп охраняют проклятые тролли, он окружен свечами ритуала и служит средоточием извращенного моджо предателя. Пока череп в круге, Миншина остается вечным пленником воли Залазана."},{t="Свобода в смерти",b="Чтобы спасти Миншину, отважный герой должен переправиться через воды к востоку от Деревни Сен'джин на южную оконечность Островов Эха, проникнуть в ритуальный круг и вырвать череп из-под власти знахаря. Когда останки возвращены Мастеру Гадрину, темные узы рвутся, и благодарный дух Миншины ненадолго являет себя, почтительно кланяется и наконец уходит в мир предков."}},faq={{q="Кто такой Миншина?",a="Миншина был братом Мастера Гадрина, видного знахаря и старейшины Деревни Сен'джин. Он был убит во время мятежа на Островах Эха Залазаном, который затем осквернил его останки темным колдовством.",al={"minshina identity","who is minshina","gadrin brother","миншина","кто такой миншина","брат гадрина"}},{q="Почему дух Миншины заперт в его черепе?",a="Залазан использует темное вуду и магию чернокнижников, чтобы порабощать души убитых троллей Черного Копья. Связав душу Миншины с его черепом и поместив его в ритуальный круг силы, Залазан не дал ему уйти в загробный мир и подчинил его дух.",al={"why trap skull","zalazane soul trap","minshina soul","зачем запер череп","ловушка душ залазана","душа миншины"}},{q="Где находится круг силы?",a="Ритуальное место находится на холме на самом южном и самом большом из Островов Эха, у юго-восточного побережья Дуротара. Его можно узнать по ритуальным свечам, пляшущим проклятым троллям и выставленным черепам.",al={"where is skull","circle of power location","minshina skull spot","где череп","где круг силы","череп миншины"}},{q="Что происходит, когда череп возвращают в Деревню Сен'джин?",a="Как только Мастер Гадрин получает череп, некромантические узы разбиваются. Призрак Миншины появляется перед братом и героем, кланяется в знак благодарности и исчезает, чтобы обрести покой среди предков.",al={"quest turn in","what happens to minshina","does minshina appear","сдача задания","что будет с миншиной","появится ли миншина"}},{q="Кто такой Залазан и зачем он это сделал?",a="Залазан когда-то был уважаемым знахарем наряду с Гадрином и Вол'джином. Обезумев от жажды власти, он обратился против своего племени, порабощал разум своих братьев и сестер порчей и изгнал уцелевших беженцев племени Черного Копья на материк Дуротара.",al={"who is zalazane","why zalazane evil","zalazane lore","кто такой залазан","почему залазан злодей","история залазана"}},{q="Почему Гадрин не может сам забрать череп?",a="Мастер Гадрин необходим, чтобы Деревня Сен'джин держалась. Он наставляет молодых вождей племени Черного Копья, советует вождю Вол'джину и противостоит расползающимся по побережью проклятиям Залазана, поэтому Гадрин не может оставить поселение без защиты.",al={"why doesn't gadrin go","gadrin duties","почему гадрин не идет","обязанности гадрина"}}},fp="16,388,23.481.0,26.459.0,16.402.1,17.226.0,46.270.0,37.212.0,63.214.1,39.252.0,44.254.0"}
P.entries["quest:809"] = {n="Ак'Зелот",s="«Ак'Зелот» — одно из первых заданий Орды, которое дает чернокнижник Нииру Огненный Клинок из глубин Расселины Теней в Оргриммаре. Получив свидетельства сохраняющейся демонической порчи, Нииру отправляет искателей приключений в Степи на встречу с его осведомителем у границы.",h="«Ак'Зелот» — одно из первых заданий Орды, которое дает чернокнижник Нииру Огненный Клинок из глубин Расселины...",kw={"ak'zeloth","barrens","burning blade","cleft of shadow","demon seed","dreadmist peak","far watch post","neeru fireblade","ак'зелот","степи","пылающий клинок","расселина теней","демоново семя","вершина багрового тумана","дальняя застава","нииру огненный клинок"},ang={["class:Warlock"]="Чернокнижники, знакомые с учением Нииру Огненного Клинка, могут распознать тонкое двуличие своего наставника, когда его помощник ставит под сомнение призыв уничтожить демоническую реликвию.",["faction:Horde"]="Защита Дальней заставы и очистка Вершины Багрового Тумана крайне важны для безопасности зарождающихся торговых и транспортных путей между Дуротаром и Степями.",["race:Orc"]="Орки отчаянно боролись, чтобы вырваться из хватки Пылающего Легиона, поэтому любой признак культа Пылающего Клинка и демонических реликвий у их порога — неотложная угроза."},sec={{t="Теневой след",b="После находки ошейника с символикой Пылающего Клинка в Дуротаре Нииру Огненный Клинок заявляет, что выслеживает остатки демонов, угрожающие недавно обосновавшейся Орде. Выставляя себя стражем от порчи Скверны, Нииру направляет искателей приключений в сухие равнины Степей, предупреждая, что вокруг артефакта мерзкой силы, известного как Демоново семя, собирается темный культ."},{t="Контакт на заставе",b="Чтобы согласовать удар по культу, искатели приключений должны найти Ак'Зелота, помощника Нииру, находящегося у Дальней заставы на границе Дуротара и Степей. Однако по прибытии Ак'Зелот встречает задание с тихим скепсисом и вслух гадает, зачем его хозяину всерьез понадобилось уничтожить артефакт, прежде чем объяснить, как поступить с Демоновым семенем на Вершине Багрового Тумана."}},faq={{q="Кто дает это задание?",a="Задание дает Нииру Огненный Клинок, чернокнижник, обитающий в сумрачной пещере Расселины Теней под Оргриммаром, сразу после того как вы покажете ему ошейник Пылающего Клинка.",al={"quest starter","where to get ak'zeloth","neeru fireblade quest","начало задания","где взять ак'зелота","задание нииру огненный клинок"}},{q="Где находится Ак'Зелот?",a="Ак'Зелот находится сразу за Дальней заставой, у восточной границы Степей, где мост ведет из Дуротара.",al={"ak'zeloth location","where is ak'zeloth","find ak'zeloth","где ак'зелот","местонахождение ак'зелота","найти ак'зелота"}},{q="Что такое Демоново семя?",a="Демоново семя — мерзкий артефакт демонической силы, которым владеет культ Пылающего Клинка на Вершине Багрового Тумана, зловещей горе на севере Степей.",al={"demon seed lore","what is the seed","демоново семя","что за семя"}},{q="Почему Ак'Зелот считает приказы Нииру странными?",a="Ак'Зелот ничего не объясняет. Он лишь замечает, что странно, что Нииру хочет уничтожить Демоново семя, а затем соглашается рассказать вам, как его убрать.",al={"why is ak'zeloth surprised","strange reaction ak'zeloth","почему ак'зелот удивлен","странная реакция ак'зелота"}},{q="Какое задание идет следом?",a="Разговор с Ак'Зелотом сразу ведет к заданию «Демоново семя», в котором вам предстоит подняться на Вершину Багрового Тумана и обезвредить оскверняющую реликвию.",al={"next quest after ak'zeloth","ak'zeloth followup","следующее задание после ак'зелота","продолжение ак'зелота"}},{q="Входит ли это задание в сюжетную линию Пылающего Клинка?",a="Да. Оно служит важным звеном, связывающим местные заговоры культистов в Дуротаре с более широкой организованной деятельностью культа, обосновавшегося в Степях.",al={"burning blade questline","orgrimmar cult quest","цепочка пылающего клинка","задание культа оргриммар"}}},fp="9,278,17.373.0,19.390.1,21.184.0,27.143.0,23.156.0,47.152.1,28.158.0,50.161.0"}
P.entries["quest:812"] = {n="Нужда в исцелении",s="Тролль из племени Черного Копья Ринаг лежит отравленный ядохвостым скорпидом на суровых утесах северо-западного Дуротара. У него почти не остается времени до гибели от яда, и он надеется, что гонец домчится до Оргриммара и принесет лекарство от Кор'гхана.",h="Тролль из племени Черного Копья Ринаг лежит отравленный ядохвостым скорпидом на суровых утесах...",kw={"antidote","cleft of shadow","durotar","kor'ghan","need for a cure","orgrimmar","rhinag","scorpid","venomtail","противоядие","расселина теней","дуротар","кор'гхан","нужда в исцелении","оргриммар","ринаг","скорпид","ядохвост"},ang={["faction:Horde"]="Скалистая местность Дуротара сурова и беспощадна и становится непрестанным огненным испытанием для новоприбывших защитников молодого государства Тралла.",["race:Troll"]="Страх Ринага вернуться в Деревню Сен'джин подчеркивает суровую гордость племени Черного Копья, где небрежность в простом выживании в глуши навлекает жестокие насмешки сородичей."},sec={{t="Укус скорпида",b="Сухие каньоны Дуротара кишат ядохвостыми скорпидами — агрессивными хищниками, чье жало несет быстрый, изнуряющий нейротоксин. Ринаг допустил ошибку, ослабив бдительность в бою с тварями у границы. Зная, что яд в его венах убьет его меньше чем за час, он не может сам дойти до городских врат и вверяет свою жизнь тому, кто пройдет мимо его уединенного лагеря."},{t="Тайны во мраке",b="Вместо того чтобы довериться обычному аптекарю или шаману, Ринаг направляет путников глубоко под Оргриммар, в сумрачные подземные пещеры Расселины Теней. Там обитает Кор'гхан, загадочный знаток, знакомый с жестокими ядами пустошей Дуротара. Кор'гхан обладает знаниями, нужными для приготовления действенного противоядия, но редко помогает безвозмездно тем, кто не доказал свою доблесть."}},faq={{q="Кто такой Ринаг?",a="Ринаг — тролль-искатель приключений из племени Черного Копья, цепляющийся за жизнь на северо-западных утесах Дуротара. Ужаленный ядохвостым скорпидом, он боится не только скорой смерти, но и насмешек сородичей из Деревни Сен'джин, если вернется туда в таком униженном виде.",al={"rhinag lore","who is rhinag","rhinag the troll","история ринага","кто такой ринаг","тролль ринаг"}},{q="Почему Кор'гхан находится в Расселине Теней?",a="Кор'гхан живет в Расселине Теней, сумрачной пещере под Оргриммаром, где чернокнижники, разбойники и другие знатоки темных искусств занимаются своим ремеслом вдали от глаз почетных воинов Тралла. Его знание ядовитых зелий и суровых испытаний подходит подземной обстановке Расселины.",al={"where is korgan","who is korghan","kor'ghan location","где кор'гхан","кто такой кор'гхан","местонахождение кор'гхана"}},{q="Почему Ринаг не обратится к шаману или целителю в Деревне Сен'джин?",a="Ринаг признает, что его удерживает собственная гордость. Он боится, что возвращение в Деревню Сен'джин в таком небрежном, отравленном состоянии вызовет лишь насмешки сородичей-троллей, и предпочитает тайно получить средство у Кор'гхана.",al={"why not go to senjin","why rhinag avoids senjin","почему не в сен'джин","почему ринаг избегает сен'джин"}},{q="Что происходит после того, как Ринаг получает противоядие?",a="Ринаг выпивает противоядие и выздоравливает, но его беды на этом не кончаются. Зная Кор'гхана, целитель потребует от Ринага доказать себя новыми суровыми испытаниями — убивать кабанов и собирать хвосты скорпидов, — прежде чем он вернет расположение знатока.",al={"does rhinag survive","rhinag aftermath","выживет ли ринаг","что стало с ринагом"}},{q="Где можно найти Ринага?",a="Он находится на суровых утесах северо-западного Дуротара, у пограничных проходов, ведущих на запад к Степям.",al={"rhinag location","where is rhinag","где ринаг","местонахождение ринага"}},{q="Почему с этим лекарством так спешат?",a="Яд ядохвостого скорпида исключительно силен: у нелеченого пострадавшего остается меньше часа, прежде чем яд поразит жизненно важные органы.",al={"why is it timed","rhinag poison timer","почему на время","таймер яда ринага"}}},fp="15,260,17.452.0,22.425.0,14.270.0,39.310.0,67.251.0,48.282.1,26.127.0,47.148.0"}
P.entries["quest:813"] = {n="Поиски противоядия",s="«Поиски противоядия» — срочное задание Кор'гхана в Оргриммаре: нужно сварить лекарство для отравленного охотника Ринага. Времени мало, пока яд не оказался смертельным, и искателю приключений нужно собрать ядовитые мешочки скорпидов-ядохвостов за городскими стенами. Задание показывает суровость животного мира Дуротара и необходимость подготовки к жизни в глуши.",h="«Поиски противоядия» — срочное задание Кор'гхана в Оргриммаре: нужно сварить лекарство для отравленного...",kw={"antidote","durotar","kor'ghan","orgrimmar","poison","rhinag","scorpid","venomtail","противоядие","дуротар","кор'гхан","оргриммар","яд","ринаг","скорпид","ядохвост"},ang={["class:Hunter"]="Кор'гхан — строгое напоминание всем охотникам: знание яда зверя и наличие подходящих лекарств так же важны, как ваш лук и умение выслеживать.",["faction:Horde"]="Орда в Дуротаре заботится о своих: одинокие следопыты и разведчики на границах могут рассчитывать на помощь оплота — Оргриммара.",["race:Orc"]="Выживание в Дуротаре испытывает выносливость недавно поселившихся орков и показывает: даже опытный разведчик может погибнуть от местных опасностей, если будет небрежен."},sec={{t="Гонка с ядом",b="Охотясь по всему Дуротару, тролль из племени Черного Копья по имени Ринаг совершил опасную ошибку: напал на местных скорпидов-ядохвостов, не взяв с собой противоядия. Ужаленный, он быстро слабел от их сильного яда и был вынужден послать за срочной помощью. Кор'гхан, опытный охотник из Оргриммара, должен приготовить исцеляющее снадобье, пока яд не закончил свое дело."},{t="Создание лекарства",b="Чтобы создать противоядие, нужно добыть источник самой отравы: ядовитые мешочки взрослых ядохвостов, обитающих у ворот Оргриммара. Кор'гхан замечает, что упреки Ринагу за недостаток подготовки подождут, ведь дорога каждая минута. Когда мешочки быстро добыты и доставлены в город, Кор'гхан готовит снадобье, чтобы его немедленно отнесли умирающему охотнику."}},faq={{q="Кто такой Ринаг?",a="Ринаг — охотник из племени троллей Черного Копья в Дуротаре. Выслеживая зверей, он был сильно ужален местными ядохвостами. Без противоядия в пути он оказался беспомощен и зависел от гонцов, которым предстояло доставить лекарство из Оргриммара, пока яд не убил его.",al={"rhinag lore","who is poisoned","who needs the antidote","ринаг","кто отравлен","кому нужно противоядие"}},{q="Кто такой Кор'гхан?",a="Кор'гхан — опытный охотник-тролль из племени Черного Копья, живущий в Расселине Теней в Оргриммаре. Он прекрасно знает диких зверей Дуротара и обладает алхимическими знаниями, нужными, чтобы сварить действенное противоядие из сырых ядовитых мешочков ядохвостов.",al={"kor'ghan","who is korphan","korgan orgrimmar","кор'гхан","кто такой коргхан","кор'гхан оргриммар"}},{q="Откуда берутся нужные ядовитые мешочки?",a="Ядовитые мешочки добывают прямо из скорпидов-ядохвостов, которые бродят по каменистым сухим равнинам недалеко от главных южных и восточных входов в Оргриммар.",al={"where are venomtails","poison sac location","venomtail scorpid sacs","где ядохвосты","где взять ядовитые мешочки","мешочки скорпидов-ядохвостов"}},{q="Почему у этого задания есть ограничение по времени?",a="Срочность вызвана ухудшающимся здоровьем Ринага. Яд ядохвостов исключительно губителен и действует быстро, поэтому Кор'гхан должен получить ингредиенты и приготовить лекарство, пока охотник не погиб от отравления.",al={"why is there a timer","need for a cure timer","timed quest","почему таймер","нужда в исцелении таймер","задание на время"}},{q="Какой урок подчеркивает Кор'гхан во время этой охоты?",a="Кор'гхан предупреждает, что каждый охотник должен тщательно изучить повадки и смертельные опасности своей добычи, прежде чем нападать. Отправляться в глушь без должной подготовки и средств защиты — недосмотр, который легко может стоить воину жизни.",al={"kor'ghan lesson","hunting lesson","kor'ghan advice","урок кор'гхана","урок охоты","совет кор'гхана"}},{q="Как это задание связано с заданием «Нужда в исцелении»?",a="«Нужда в исцелении» — первое поручение, которое запускает чрезвычайную ситуацию и отсчет времени. «Поиски противоядия» — промежуточный шаг, на котором игрок собирает сырье, чтобы Кор'гхан сварил готовое снадобье.",al={"need for a cure connection","prerequisite quest","how does it connect","нужда в исцелении связь","предыдущее задание","как связано"}}},fp="20,368,24.397.0,17.405.0,14.266.0,16.259.0,43.165.0,47.242.0,53.250.0,46.238.0"}
P.entries["quest:816"] = {n="Пропавший, но не забытый",s="«Пропавший, но не забытый» — печальное задание, которое дает Майша Тор'крен на своей ферме к северо-западу от Колючего Холма. Отчаянно желая узнать правду, она просит путников поискать на опасных берегах Реки Строптивой хоть какие-то следы ее упрямого сына Крона.",h="«Пропавший, но не забытый» — печальное задание, которое дает Майша Тор'крен на своей ферме к северо-западу от...",kw={"amulet","crocolisk","dreadmaw","kron","misha","razor hill","southfury","tor'kren","амулет","кроколиск","крупнозубый кроколиск","крон","майша","колючий холм","строптивая","тор'крен"},ang={["class:Hunter"]="Для охотников Крон — предостерегающий пример следопыта, не оценившего свирепость добычи и ставшего ее обедом.",["faction:Horde"]="Жизнь в раннем Дуротаре сурова и беспощадна: обычные семьи борются с неумолимой землей и смертоносными хищниками, бродящими у ее границ.",["race:Orc"]="Судьба Крона — печальное напоминание: хотя гордость и воинская слава лежат в основе культуры орков, безрассудная самонадеянность и неуважение к опасным зверям ведут к негероической смерти."},sec={{t="Страх матери",b="К северо-западу от Колючего Холма, среди засушливых красных пустошей Дуротара, стоит скромная ферма Тор'крен. Здесь живет Майша Тор'крен, мать-орчиха, скованная горем и тревогой. Несколько дней назад ее сын Крон объявил, что идет на запад, к Реке Строптивой на границе Степей, охотиться на свирепых кроколисков. Несмотря на ее предостережения об опасных тварях, упрямая гордость погнала Крона прочь, чтобы доказать свою доблесть. С тех пор его никто не видел."},{t="Мрачное подтверждение",b="Майша просит проходящих мимо искателей приключений обыскать берега Реки Строптивой в поисках любых следов судьбы Крона и даже советует заглянуть в желудки кроколисков. К несчастью, худшие ее предчувствия оправдываются. Убив свирепых крупнозубых кроколисков у воды, можно найти проглоченный амулет Крона. Возвращение памятной вещи Майше лишает ее последней надежды, что сын жив, но наконец дает скорбящей матери покой, нужный, чтобы начать оплакивать его."}},faq={{q="Кто такая Майша Тор'крен?",a="Майша Тор'крен — мать-орчиха, живущая на уединенной ферме к северо-западу от Колючего Холма в Дуротаре. Измученная горем и тревогой, она просит странников найти любые следы ее пропавшего сына Крона.",al={"misha torkren","who gives lost but not forgotten","kron mother","майша тор'крен","кто дает пропавший, но не забытый","мать крона"}},{q="Кто такой Крон?",a="Крон был упрямым сыном Майши Тор'крен. Желая доказать свою силу, он проигнорировал предостережения матери и ушел охотиться на опасных кроколисков у Реки Строптивой, где и встретил безвременную смерть.",al={"who is kron","what happened to kron","misha son","кто такой крон","что случилось с кроном","сын майши"}},{q="Где пропал Крон?",a="Крон отправился на запад через Дуротар к границе Степей, чтобы охотиться на берегах Реки Строптивой.",al={"where is kron","where to look for kron","kron location","где крон","где искать крона","местонахождение крона"}},{q="Как доказать Майше судьбу Крона?",a="Вы находите проглоченный амулет Крона среди останков крупнозубых кроколисков, бродящих в водах Реки Строптивой. Возвращение этой семейной реликвии Майше подтверждает его гибель.",al={"krons amulet","sign of krons fate","crocolisk stomach","амулет крона","знак судьбы крона","желудок кроколиска"}},{q="Какую награду дает Майша?",a="Майша дает вам подарок, который изначально приготовила для Крона, чтобы отпраздновать его триумфальное возвращение с охоты. Не в силах смотреть на него после известия о смерти сына, она отдает его искателю приключений, подарившему ей покой.",al={"lost but not forgotten reward","misha gift","пропавший, но не забытый награда","подарок майши"}},{q="Почему Крон вообще ушел?",a="Крона вела упрямая гордость и желание доказать свое охотничье мастерство. Когда мать предупредила, что кроколиски слишком свирепы и опасны, он пришел в ярость и все равно ушел охотиться на них.",al={"why did kron hunt","kron pride","почему крон пошел на охоту","гордость крона"}}},fp="22,244,16.475.0,19.465.1,22.201.0,13.202.1,26.114.0,38.184.1,28.224.1,38.212.0"}
P.entries["quest:817"] = {n="Полезная добыча",s="«Полезная добыча» — охотничье задание, которое дает кожевник Вель'рин Клык в Деревне Сен'джин. Население растет, запасы тают, и племени Черного Копья нужно добывать прочные тигровые шкуры на соседних Островах Эха, чтобы делать жилища, одежду и снаряжение.",h="«Полезная добыча» — охотничье задание, которое дает кожевник Вель'рин Клык в Деревне Сен'джин.",kw={"darkspear","durotar tiger","echo isles","hunting","leatherworking","practical prey","sen'jin village","tiger fur","vel'rin fang","черное копье","тигр дуротара","острова эха","охота","кожевничество","полезная добыча","деревня сен'джин","тигровая шкура","вель'рин клык"},ang={["class:Hunter"]="Рассказ Вель'рина о целом дне молчаливого выслеживания перед тем, как захлопнуть ловушку, напрямую говорит о главных добродетелях — терпении и точности, которым учат всех молодых охотников.",["faction:Horde"]="Поддержка молодого поселения племени Черного Копья необходимыми товарами помогает укрепить южный фланг Орды вдоль Великого моря.",["race:Troll"]="Для изгнанного племени Черного Копья охота на Островах Эха — горькое напоминание об утраченном доме: чтобы кормить род, приходится ступать по земле, захваченной Залазаном."},sec={{t="Вопрос выживания",b="Жизнь на засушливом побережье Дуротара сурова, и тролли Черного Копья, изгнанные в Деревню Сен'джин, должны использовать каждый ресурс. Тигровые шкуры — один из самых универсальных материалов: из них шьют палатки, плотные одеяла и усиленные доспехи. Поселение растет за счет беженцев и вернувшихся разведчиков, запасы истощились, и ремесленники вроде Вель'рина Клыка вынуждены заказывать новые охоты."},{t="Равновесие и охота",b="Племя Черного Копья осознанно относится к хищникам своих земель. Вместо чрезмерной охоты на местных тигров Дуротара тролли обычно оставляют их в покое и бьют их, лишь когда нужно пополнить запасы племени. Переправа через воду на Острова Эха для охоты на этих хищников — и практическая необходимость, и традиционное испытание терпения, дисциплины и умения жить в глуши."}},faq={{q="Кто такой Вель'рин Клык?",a="Вель'рин Клык — тролль-ремесленник из племени Черного Копья в Деревне Сен'джин, работающий со шкурами и кожей. Он направляет охотников добывать необходимые шкуры, чтобы племя было одето, укрыто и снаряжено.",al={"vel'rin fang","who gives practical prey","velrin fang","вель'рин клык","кто дает полезная добыча","велрин клык"}},{q="Зачем Деревне Сен'джин тигровые шкуры?",a="Растущее население Деревни Сен'джин истощило прежние запасы. Тигровые шкуры дают прочный материал для теплых одеял, крепких палаток и кожаных доспехов, защищающих жителей от суровой погоды.",al={"why tiger pelts","practical prey purpose","what are furs used for","зачем тигровые шкуры","для чего полезная добыча","для чего нужны шкуры"}},{q="Где водятся тигры Дуротара?",a="Тигры бродят по дикой местности Островов Эха — архипелага у юго-восточного побережья Дуротара.",al={"where are the tigers","tiger location","echo isles tigers","где тигры","где найти тигров","тигры острова эха"}},{q="Почему тролли не истребляют всех тигров поблизости?",a="Вель'рин объясняет, что племя Черного Копья намеренно соразмеряет свои нужды с местной экологией. Тролли дают хищникам процветать, чтобы популяция оставалась устойчивой, и вмешиваются, лишь когда потребности деревни превышают запасы.",al={"why let tigers thrive","culling the flock","почему не трогать тигров","сокращение стаи"}},{q="Важна ли охота на тигров для культуры племени Черного Копья?",a="Да. Выслеживание тигра считается обрядом терпения и хитрости. Вель'рин с теплотой вспоминает, как почти целый день неподвижно ждал в листве на Островах Эха, прежде чем одержал свою первую крупную охотничью победу.",al={"tiger hunt tradition","first tiger hunt","традиция охоты на тигров","первая охота на тигра"}},{q="Почему охотникам нужно плыть на Острова Эха, если там хозяйничает Залазан?",a="Хотя предатель-знахарь Залазан и его одурманенные приспешники занимают большую часть архипелага, диких зверей на островах по-прежнему много. Добывать пищу и охотиться на внешних берегах остается необходимым риском для племени Черного Копья.",al={"tigers on echo isles","why go to echo isles","тигры на островах эха","зачем плыть на острова эха"}}},fp="14,280,20.430.0,20.432.0,20.197.0,41.219.0,35.127.0,48.256.0,51.212.0,65.231.0"}
P.entries["quest:818"] = {n="Растворитель",kw={"alchemy","crawler mucus","darkspear strand","durotar","intact makrura eye","makrura","master vornal","sen'jin village","алхимия","слизь краулера","побережье черного копья","дуротар","целый глаз макрура","макруры","мастер ворнал","деревня сен'джин"},ang={["faction:Horde"]="Прибрежный Дуротар остается опасным для молодой Орды: уничтожение агрессивных макруров и прибрежных краулеров делает безопаснее рыбацкие берега возле деревни Сен'джин.",["race:Orc"]="Ворнал открыто сомневается, что оркам хватит тихой дисциплины для алхимии, и потому задание — шанс доказать, что единство Орды включает и ученое терпение.",["race:Troll"]="Для Черного Копья, возрождающегося в деревне Сен'джин, важно проявить себя перед старейшинами вроде Мастера Ворнала, чтобы продолжить мистические и алхимические традиции племени."},sec={{t="Угасающее зрение мастера",b="Мастер Ворнал живет в деревне Сен'джин, обремененный возрастом и ослабевающим зрением. Если раньше первобытная магия сама собой текла к его пальцам, то теперь он сильно полагается на алхимию, чтобы обострять восприятие и творить свои искусства. Несмотря на растущую немощь, упрямый тролль отказывается брать ученика, утверждая, что ни среди Черного Копья, ни среди орков Дуротара не нашлось никого, достойного его наставничества."},{t="Испытание неопытных",b="Вместо прямого обучения Ворнал требует сырье с сурового побережья: целые глаза макруров и пузырьки со слизью краулеров. Добыть неповрежденные глаза у панцирных щелкающих макруров можно только точными ударами, а сбор достаточного количества слизи проверяет готовность авантюриста терпеть нудную черную работу. Для Ворнала охота на этих прибрежных тварей нужна не ради реагентов, а чтобы отсеять тех, кому не хватает сосредоточенности."},{t="Мера воли",b="Для мастера Ворнала время и терпение — высшая мера силы. Он ждет, что дерзкая молодежь поддастся раздражению или вовсе бросит поручение. Возвращение в деревню Сен'джин с безупречными ингредиентами показывает не только умение выживать среди опасных рифов пролива у Островов Эха, но и дисциплину, необходимую для овладения тонким искусством алхимии."}},faq={{q="Кто такой Мастер Ворнал?",a="Мастер Ворнал — пожилой тролль-алхимик и заклинатель, живущий в деревне Сен'джин. С возрастом его зрение слабеет, и он вынужден прибегать к алхимическим растворам и зельям, чтобы творить магию, которая раньше давалась ему легко.",al={"master vornal","who is vornal","vornal lore","мастер ворнал","кто такой ворнал","ворнал предания"}},{q="Зачем Ворналу глаза макруров и слизь краулеров?",a="Ворнал полагается на алхимические составы, чтобы поддерживать магию и возмещать слабеющее зрение. Слизь и целые глаза макруров служат реагентами для его смесей, а также вступительным испытанием для возможных учеников.",al={"why crawler mucus","why makrura eyes","what does vornal make","зачем слизь краулеров","зачем глаза макруров","что варит ворнал"}},{q="Почему Ворнал так неохотно берет ученика?",a="Ворнал предъявляет высокие требования и не терпит высокомерия. Он считает, что ни один тролль или орк не проявил подлинного усердия и терпения, нужных для обучения у него, и видит в большинстве желающих чересчур гордых и легко падающих духом учеников.",al={"vornal apprentice","why no apprentice","is vornal looking for a student","ученик ворнала","почему нет ученика","ищет ли ворнал ученика"}},{q="Где обитают эти существа возле деревни Сен'джин?",a="Краулеры и макруры бродят на мелководье вдоль Побережья Черного Копья и населяют протоки, отделяющие материк от Островов Эха неподалеку от берега.",al={"where are makrura","where are crawlers","darkspear strand beasts","где макруры","где краулеры","звери побережья черного копья"}},{q="Почему глаза макруров должны быть целыми?",a="Алхимические зелья, обостряющие восприятие, требуют неповрежденных органов чувств. Грубые удары в бою могут раздавить нежные глаза макрура, поэтому охотнику нужны точность и сдержанность.",al={"intact eye","makrura intact eyes","why intact eyes","целый глаз","целые глаза макруров","почему целые глаза"}},{q="Какому уроку хочет научить Ворнал?",a="Ворнал считает, что терпение — истинное испытание характера. Поручая однообразную и грязную работу у прибоя, он хочет увидеть, поддастся ли новичок слабости и спешке или сохранит спокойную сосредоточенность алхимика.",al={"vornal lesson","meaning of the quest","patience test","урок ворнала","смысл задания","испытание терпения"}}},fp="16,336,23.409.0,20.445.0,17.369.0,21.225.0,52.240.0,50.245.0,55.146.0,42.197.0,38.240.0"}
P.entries["quest:819"] = {n="Пустой бочонок Чэня",s="Среди глуши Степей лежит пустой бочонок с надписью Чэня Буйного Портера. Его находка начинает путь в прошлое знаменитого странствующего пивовара, который когда-то помог своим боевым мастерством основанию Дуротара.",h="Среди глуши Степей лежит пустой бочонок с надписью Чэня Буйного Портера.",kw={"barrens","brewing","brewmaster drohn","chen stormstout","empty keg","pandaren","ratchet","rexxar","степи","пивоварение","пивовар дрон","чэнь буйный портер","пустой бочонок","пандарен","кабестан","рексар"},ang={["faction:Horde"]="Чэня Буйного Портера помнят как почетного союзника, сражавшегося бок о бок с Рексаром и Рохана ради основания Дуротара и защиты Орды в первые дни.",["profession:Cooking"]="Бочонок олицетворяет наследие мастера-пивовара, чье легендарное чутье и поиски редких ингредиентов вдохновили ремесленников по всему Калимдору."},sec={{t="Странствующая реликвия",b="Среди засушливых просторов Степей путники порой натыкаются на брошенную деревянную бочку. В отличие от обычных бочонков, оставленных свинобразами Иглогривыми или кентаврами Колкар, эта сделана тщательно и несет памятную табличку: «Чэнь Буйный Портер — пусть твой дух будет поднят, а твой дух всегда поднимает». Эта необычная реликвия, томящаяся под солнцем Калимдора, заставляет любопытных искать знатока пивоварения, чтобы выяснить, как она здесь оказалась."},{t="Отголоски основания Дуротара",b="Если отнести бочонок Пивовару Дрону в Кабестан, станет ясно его происхождение. Дрон сразу узнает работу: бочонок принадлежал Чэню Буйному Портеру, легендарному страннику-пандарену, который вместе с Рексаром участвовал в решающих битвах, обеспечивших Дуротар для Орды Тралла. Хотя с тех пор, как Чэнь ступал по красной земле Калимдора, прошли годы, его легендарные рецепты и странствующий дух живы в памяти опытных пивоваров этих мест."}},faq={{q="Что такое Пустой бочонок Чэня?",a="Это брошенная пивоваренная бочка, найденная в Степях. На ней надпись, посвящающая ее странствующему пандарену-пивовару Чэню Буйному Портеру.",al={"empty keg","chens keg","what is this barrel","пустой бочонок","бочонок чэня","что за бочка"}},{q="Кто такой Чэнь Буйный Портер?",a="Чэнь Буйный Портер — неуловимый пандарен-пивовар, много путешествовавший по Калимдору. Он больше всего известен тем, что помогал могу'нату-повелителю зверей Рексару в обороне и раннем основании Дуротара.",al={"who is chen","chen lore","pandaren brewmaster","кто такой чэнь","чэнь предания","пандарен пивовар"}},{q="Кому нужно отнести бочонок?",a="Бочонок можно отнести Пивовару Дрону, орку-пивовару, стоящему на дороге возле Кабестана: он узнает клеймо Чэня и умеет воссоздавать его рецепты.",al={"where to turn in keg","who wants chens keg","keg turn in","куда сдать бочонок","кому нужен бочонок чэня","сдать бочонок"}},{q="Почему бочонок Чэня валяется в Степях?",a="Много лет назад Чэнь бродил по Калимдору в поисках необычных ингредиентов для своих напитков, особенно во время путешествий, когда помогал юной Орде отстоять новую родину от войск адмирала Праудмура.",al={"why is keg in barrens","how did keg get here","почему бочонок в степях","как бочонок сюда попал"}},{q="Появляется ли Чэнь Буйный Портер лично?",a="Нет. Чэнь покинул эти края и давно не появлялся в Калимдоре. Остались лишь его старые бочки, рецепты и теплые воспоминания таких союзников, как Дрон и Рексар.",al={"can i find chen","where is chen stormstout","is chen in classic","можно ли найти чэня","где чэнь буйный портер","есть ли чэнь в классике"}},{q="Что Пивовар Дрон делает с бочонком?",a="Дрон в восторге от реликвии и пользуется случаем, предлагая отважным странникам собрать ингредиенты из местных зверей, чтобы воссоздать мощные легендарные напитки Чэня.",al={"drohn quest line","what happens next with keg","цепочка заданий дрона","что дальше с бочонком"}}},fp="16,243,17.517.0,28.455.0,25.151.0,23.204.0,29.159.0,43.205.0,38.176.0,43.185.0"}
P.entries["quest:821"] = {n="Пустой бочонок Чэня",s="Это задание продолжает легендарную линию пандаренского пивоварения в Степях. Пивовар Дрон в Кабестане предлагает воссоздать знаменитый крепкий напиток Чэня Буйного Портера, если вы соберете дикие ингредиенты у местных зверей, бродящих по саванне.",h="Это задание продолжает легендарную линию пандаренского пивоварения в Степях.",kw={"brewmaster drohn","chen stormstout","keg","plainstrider kidney","ratchet","savannah lion tusk","the barrens","thunder lizard horn","trogg brew","пивовар дрон","чэнь буйный портер","бочонок","почки кочевника равнин","кабестан","бивень саванного льва","степи","рог громового ящера","троггская брага"},ang={["faction:Horde"]="Чэнь Буйный Портер сражался плечом к плечу с Рексаром, помогая основать Дуротар, поэтому любая память о его странствиях имеет для Орды особое культурное значение.",["profession:Cooking"]="Кулинарные авантюристы оценят смелое, хотя и тревожащее сочетание пограничного мясницкого дела и тонкого пивоварения, из которого рождаются легендарные напитки Калимдора.",["race:Orc"]="Дрон показывает, как орки приняли древние традиции пивоваров, переданные напрямую странниками, ходившими по этой земле бок о бок с ранней Ордой."},sec={{t="Наследие в бочонке",b="Когда брошенный бочонок с пандаренской надписью попадает к Пивовару Дрону в Кабестане, он вызывает теплые воспоминания о легендарном страннике Чэне Буйном Портере. Чэнь передал секреты своего именного напитка наставнику Дрона, а тот — самому Дрону. Хотя для далеких от пивоварения людей это необычно, рецепт требует сырых, мощных компонентов прямо от свирепых зверей Степей."},{t="Сбор урожая саванны",b="Для крепкого напитка Чэня нужен необычный набор компонентов: почки кочевников равнин, бивни саванных львов и рог громового ящера. Добыча требует охоты на пыльных равнинах и доказывает, что лишь самые выносливые звери дают тот самый градус для настоящего пандаренского пивоварения. Когда все собрано, Дрон исполняется ностальгии и замечает, что возрождение старой формулы греет желудок почти так же, как его прежние партии троггской браги."}},faq={{q="Кто такой Пивовар Дрон?",a="Пивовар Дрон — орк-пивовар, живущий в портовом городе Кабестан. Он освоил искусство пивоварения у наставника, лично получившего рецепты от легендарного странника Чэня Буйного Портера.",al={"brewmaster drohn","who is drohn","drohn ratchet","пивовар дрон","кто такой дрон","дрон кабестан"}},{q="Почему для рецепта пива нужны звериные почки и рога?",a="Пандаренские традиции пивоварения — и приспособления грубых пограничных пивоваров — часто опираются на мощные, особые ингредиенты из местной фауны, придающие крепким напиткам бодрость, градус и особый природный вкус.",al={"why animal parts","plainstrider kidneys brew","lion tusks beer","зачем части животных","почки кочевников равнин пиво","бивни львов пиво"}},{q="Где найти нужные ингредиенты?",a="Все три компонента добываются из коренной фауны Степей. Кочевники равнин и саванные львы бродят по открытым степям, а громовых ящеров обычно можно найти пасущимися на более сухих или каменистых участках равнин.",al={"where to find tusks","where are thunder lizards","finding brew ingredients","где найти бивни","где громовые ящеры","поиск ингредиентов для пива"}},{q="Кем был Чэнь Буйный Портер?",a="Чэнь Буйный Портер — странствующий пандарен-пивовар, путешествовавший по Калимдору во время основания Дуротара. Он помогал Орде, разыскивая экзотические редкие ингредиенты, чтобы довести до совершенства свои крепкие сорта пива.",al={"who is chen","chen stormstout lore","chen","кто такой чэнь","чэнь буйный портер предания","чэнь"}},{q="Что происходит после того, как принести ингредиенты Дрону?",a="Бивни львов, почки кочевников равнин и рог громового ящера радуют Дрона, напоминают ему о прежних днях пивоварения и ведут прямо к заключительному этапу воссоздания легендарного напитка.",al={"next quest after chens empty keg","drohn reward","whats next","следующее задание после пустого бочонка чэня","награда дрона","что дальше"}},{q="Что за троггская брага, о которой говорит Дрон?",a="Увидев дикие ингредиенты, Дрон с теплотой вспоминает прежний напиток — троггскую брагу, что говорит о его эксцентричном прошлом: он выбраживал на границе резкие и необычные составы.",al={"trogg brew","drohn trogg brew","trogg beer","троггская брага","дрон троггская брага","троггское пиво"}}},fp="16,247,17.400.0,23.473.1,24.197.0,56.232.0,44.237.0,24.202.0,53.205.0,38.191.0"}
P.entries["quest:822"] = {n="Пустой бочонок Чэня",s="После создания мощного напитка «Буйный эль» Пивовар Дрон в Кабестане предлагает сварить еще один необычный рецепт, которому его научил неуловимый странствующий пандарен Чэнь Буйный Портер. Для этого крепкого варева, известного как троггово пиво, нужны редкие органы и железы местных зверей Степей.",h="После создания мощного напитка «Буйный эль» Пивовар Дрон в Кабестане предлагает сварить еще один необычный...",kw={"barrens","brewmaster drohn","chen stormstout","chen's empty keg","kodo liver","ratchet","stormhide","thunderhawk","trogg ale","степи","пивовар дрон","чэнь буйный портер","пустой бочонок чэня","печень кодо","кабестан","бурошкурый","громовой ястреб","троггово пиво"},ang={["faction:Horde"]="Чэнь Буйный Портер сражался бок о бок с Ордой при обороне Дуротара и произвел неизгладимое впечатление на орков вроде Дрона, встретивших его в те первые дни.",["profession:Cooking"]="Кулинарные пуристы могут морщиться при виде троггова пива, но использование жирных субпродуктов и сильнодействующих желез отражает походную кулинарную традицию: ничто в добыче не должно пропадать.",["race:Orc"]="Пивовар Дрон выбрал для орка необычное занятие: он предпочел экзотические методы варки Чэня традиционному пути воина, не покидая своего дела в Кабестане."},sec={{t="Вторая формула пандарена",b="После того как вы помогли Пивовару Дрону воспроизвести первый напиток легендарного Чэня Буйного Портера, орк-пивовар рассказывает, что странствующий пандарен поделился не одним секретом. Дрон знает рецепт необычного напитка — троггова пива. В отличие от обычных спиртных напитков, перегнанных из зерна, это своеобразное варево целиком основано на мощных органических реагентах, добытых у самых свирепых зверей центрального Калимдора."},{t="Ингредиенты троггова пива",b="Чтобы сварить этот резкий и бодрящий напиток, Дрону нужны громовые компоненты: молниевые железы бурошкурых кабанов, слюнная железа большого громового ястреба и крепкая печень кодо, бродящих по равнинам. После перегонки смесь дает сильнодействующий тонизирующий напиток, созданный для выживания в дикой природе."},{t="Прочное партнерство",b="Работа Дрона не ограничивается одной партией. Зная о спросе среди странствующих искателей приключений и наемников, проходящих через нейтральный порт Кабестан, Дрон не ставит срока: он готов варить свежее троггово пиво всякий раз, когда путешественник приносит новую партию звериных органов."}},faq={{q="Кто такой Чэнь Буйный Портер?",a="Чэнь Буйный Портер — неуловимый странствующий пандарен-пивовар, который путешествовал по Калимдору во время основания Дуротара. По пути он поделился несколькими своими мощными приемами варки с Дроном в Кабестане и отправился дальше в странствия.",al={"who is chen","chen lore","pandaren chen","кто такой чэнь","предания о чэне","пандарен чэнь"}},{q="Где находится Пивовар Дрон?",a="Пивовар Дрон живет в нейтральном портовом городе Кабестан на восточном побережье Степей. Он проводит дни, совершенствуя необычные напитки, рецепты которых узнал при встрече с Чэнем.",al={"drohn location","where is brewmaster drohn","drohn npc","где дрон","местонахождение дрона","где пивовар дрон","дрон персонаж"}},{q="Что такое троггово пиво?",a="Троггово пиво — необычный и крепкий напиток, рецепту которого Чэнь научил Дрона. Вместо обычного хмеля в него добавляют звериные железы и субпродукты, отчего он славится своей убойной силой и подходит выносливым искателям приключений.",al={"trogg ale","what is this drink","what does drohn brew","троггово пиво","что это за напиток","что варит дрон"}},{q="Где добыть молниевые железы?",a="Молниевые железы добывают у бурошкурых зверей, бродящих по засушливым просторам Степей: в их телах накапливаются природные электрические заряды.",al={"lightning gland source","stormhide location","where to get lightning gland","источник молниевых желез","где бурошкурые","где добыть молниевую железу"}},{q="С каких зверей падают слюнные железы громового ястреба?",a="Эти железы добывают только у больших громовых ястребов — величественных пернатых хищников, владеющих молниями и охотящихся в открытом небе над Степями.",al={"thunderhawk saliva gland","where are greater thunderhawks","thunderhawk location","слюнная железа громового ястреба","где большие громовые ястребы","где громовые ястребы"}},{q="Можно ли сварить троггово пиво более одного раза?",a="Да. Пивовар Дрон по-прежнему готов варить новые партии напитка, когда искатели приключений приносят ему свежие железы и печень кодо.",al={"is this repeatable","can i do this again","repeat trogg ale","можно ли повторить","можно сделать снова","повторить троггово пиво"}}},fp="16,301,25.422.0,28.339.0,23.303.1,23.246.0,34.193.0,18.215.0,37.154.0,43.158.0,36.146.0"}
P.entries["quest:823"] = {n="Явиться к Оргнилу",s="«Явиться к Оргнилу» — одно из первых заданий Орды, которое выдает Мастер Гадрин из Деревни Сен'джин. Оно отправляет начинающих искателей приключений на север, в Колючий Холм, чтобы предупредить Оргнила Душегрыза о коварном влиянии культа Пылающего Клинка. Это донесение помогает согласовать разрозненную оборону Дуротара от демонической скверны, зреющей прямо на родине орков.",h="«Явиться к Оргнилу» — одно из первых заданий Орды, которое выдает Мастер Гадрин из Деревни Сен'джин.",kw={"burning blade","durotar","master gadrin","orgnil soulscar","razor hill","report to orgnil","sen'jin village","пылающий клинок","дуротар","мастер гадрин","оргнил душегрыз","колючий холм","явиться к оргнилу","деревня сен'джин"},ang={["faction:Horde"]="Это задание отмечает важную связь и сотрудничество между недавно объединившимися троллями Черного Копья и орками Дуротара перед лицом общих угроз.",["race:Orc"]="Оргнил Душегрыз олицетворяет передовую оборону вашей новой родины, не давая демонической скверне укорениться в границах Дуротара.",["race:Troll"]="Хотя Черное Копье поглощено борьбой с Залазаном, Мастер Гадрин показывает преданность троллей Орде, предупреждая орочьих вождей об опасностях региона."},sec={{t="Согласованная оборона",b="Пока Деревня Сен'джин борется со своими бедами — прежде всего с предательством Залазана на Островах Эха, — Мастер Гадрин понимает, что сведения о культе Пылающего Клинка говорят о гораздо более широкой угрозе. В Долине Испытаний обнаружили слухи о демонической скверне, и знахарь Черного Копья знает, что с такими угрозами нельзя справляться поодиночке. Он отправляет странствующих героев на север по пыльной дороге в Колючий Холм, где местные орочьи власти наблюдают за Дуротаром шире."},{t="Оргнил Душегрыз",b="Оргнил Душегрыз, расквартированный в военном лагере Колючего Холма, — орк, которому поручено искоренять внутреннее зло и охранять центральные земли. Когда искатели приключений передают предупреждение Гадрина, Оргнил без промедления сопоставляет сведения из Долины Испытаний и Деревни Сен'джин. Понимая, что тень Пылающего Клинка нависла опасно близко, он быстро собирает силы, чтобы разгромить культистов, пока их темные ритуалы не погубили молодое государство."}},faq={{q="Кто выдает задание «Явиться к Оргнилу»?",a="Мастер Гадрин, знахарь Черного Копья и духовный лидер, живущий в Деревне Сен'джин, дает вам это поручение после того, как вы помогли троллям с их первыми местными бедами.",al={"who gives report to orgnil","where to get report to orgnil","quest giver report to orgnil","кто выдает явиться к оргнилу","где взять явиться к оргнилу","персонаж, выдающий задание явиться к оргнилу"}},{q="Где находится Оргнил Душегрыз?",a="Оргнил Душегрыз находится в Колючем Холме — укрепленном поселении к северу от Деревни Сен'джин в центральной части Дуротара.",al={"where is orgnil soulscar","orgnil soulscar location","find orgnil soulscar","где оргнил душегрыз","местонахождение оргнила душегрыза","найти оргнила душегрыза"}},{q="Почему Мастер Гадрин отправляет вас в Колючий Холм?",a="Мастер Гадрин понимает, что деятельность демонического культа, обнаруженная в Долине Испытаний и вокруг Дуротара, угрожает всем, а не только троллям. Он направляет вас к Оргнилу Душегрызу, орку, отвечающему за охрану региона от Пылающего Клинка.",al={"why report to orgnil","why go to razor hill","purpose of report to orgnil","зачем являться к оргнилу","зачем идти в колючий холм","цель задания явиться к оргнилу"}},{q="Что такое Пылающий Клинок, упомянутый в задании?",a="Пылающий Клинок — коварный культ поклонников демонов, действующий в тени Дуротара и за его пределами. Его скрытое присутствие в ближайших каньонах и пещерах угрожает безопасности и стабильности молодой Орды.",al={"who are the burning blade","burning blade cult","what is burning blade","кто такие пылающий клинок","культ пылающего клинка","что такое пылающий клинок"}},{q="Какое задание идет после «Явиться к Оргнилу»?",a="Когда вы сообщаете о донесении Оргнилу Душегрызу в Колючем Холме, он сразу выдает вам задание «Сгущаются черные тучи», чтобы расследовать растущую угрозу культистов и бороться с ней.",al={"next quest after report to orgnil","report to orgnil followup","what comes after report to orgnil","следующее задание после явиться к оргнилу","продолжение явиться к оргнилу","что после явиться к оргнилу"}},{q="Что нужно выполнить до получения этого задания?",a="Оно естественно следует за вашим прибытием в Деревню Сен'джин по заданию «Деревня Сен'джин», связывая первые открытия в Долине Испытаний с более широкой кампанией в Дуротаре.",al={"prereq report to orgnil","how to unlock report to orgnil","previous quest report to orgnil","предыдущее задание явиться к оргнилу","как открыть явиться к оргнилу","требования явиться к оргнилу"}}},fp="16,347,21.502.0,15.482.0,37.175.0,33.120.0,46.258.0,49.215.0,36.165.0,64.169.0"}
P.entries["quest:824"] = {n="Дже'неу из Служителей Земли",s="Это поручение направляет искателей приключений Орды доставить Дже'неу Санкри из Служителей Земли оскверненную водяную сферу, найденную у элементалей Ясеневого леса. Шаман Дже'неу, преданный гармонии стихий, стремится понять распространяющуюся порчу на Зорамском взморье и в Непроглядной Пучине. Изучение реликвии дает надежду остановить неестественную заразу, отравляющую воды региона.",h="Это поручение направляет искателей приключений Орды доставить Дже'неу Санкри из Служителей Земли оскверненную...",kw={"befouled water globe","blackfathom deeps","earthen ring","elementals","je'neu sancrea","mastok wrilehiss","zoram strand","zoram'gar outpost","оскверненная водяная сфера","непроглядная пучина","служители земли","элементали","дже'неу санкри","масток райльшип","зорамское взморье","форт зорам'гар"},ang={["class:Shaman"]="Это задание напрямую связано с долгом шамана поддерживать равновесие стихий. Доставив оскверненную сферу, вы помогаете собрату по Служителям Земли определить опасную духовную болезнь.",["faction:Horde"]="Пока Орда возводит укрепленные лагеря вроде Форта Зорам'гар в Ясеневом лесу, выяснение темных истоков враждебности местных стихий жизненно важно для защиты побережья.",["race:Troll"]="Дже'неу Санкри демонстрирует глубокую духовную мудрость Черного Копья, используя свою родовую связь с духами от имени Служителей Земли."},sec={{t="Вестник для стихий",b="Когда по Ясеневому лесу начали появляться странные оскверненные элементали, разведчики заметили неестественную силу, оживлявшую их. Среди останков нашлась оскверненная водяная сфера — целый сосуд, пульсирующий оскверненной магией. Зная, что обычным солдатам и разведчикам не хватит духовной проницательности для такой аномалии, Масток Райльшип направил путников Орды к тому, кто глубоко знает древние легенды и учение о стихиях, — к Дже'неу Санкри."},{t="Глаза Служителей Земли",b="Дже'неу Санкри принадлежит к Служителям Земли — ордену шаманов, стремящихся сохранить равновесие первобытных сил Азерота. Пока силы Орды охраняют рубеж на Зорамском взморье, Дже'неу занят духовной раной, гноящейся в руинах храма неподалеку, в Непроглядной Пучине. Для него элементаль, черпающий силу из оскверненного сосуда, — не просто отдельная угроза, а тревожное знамение того, что невидимые древние силы извращают естественный порядок."}},faq={{q="Кто такой Дже'неу Санкри?",a="Дже'неу Санкри — тролль-шаман, представляющий Служителей Земли на севере Калимдора. Он посвятил жизнь общению со стихиями и их изучению и поселился у Зорамского взморья, чтобы исследовать темные возмущения, поднимающиеся из Непроглядной Пучины.",al={"who is jeneu","jeneu sancrea lore","what is jeneu doing here","кто такой дже'неу","предания о дже'неу санкри","чем занят дже'неу"}},{q="Кто такие Служители Земли?",a="Служители Земли — организация шаманов, стремящихся сохранить гармонию первичных стихий Азерота. Они изучают древние предания, забытых духов и старые легенды, чтобы исцелять хаос стихий и духовную порчу по всему миру.",al={"what is earthen ring","who are earthen ring","earthen ring lore","что такое служители земли","кто такие служители земли","предания о служителях земли"}},{q="Где можно найти Дже'неу Санкри?",a="Дже'неу можно найти в Форте Зорам'гар на побережье Зорамского взморья в Ясеневом лесу, где он изучает возмущения стихий, поднимающиеся из соседней Непроглядной Пучины.",al={"where is jeneu","jeneu location","find jeneu sancrea","где дже'неу","местонахождение дже'неу","найти дже'неу санкри"}},{q="Что такое Оскверненная водяная сфера?",a="Сфера — магический проводник, через который могущественные элементали воды направляют свою силу. Находка оскверненной, но целой сферы говорит о том, что темные силы в этих местах намеренно искажают и порабощают местных духов.",al={"what is the globe","befouled globe lore","water globe","что такое сфера","предания об оскверненной сфере","водяная сфера"}},{q="Кто посылает вас поговорить с Дже'неу?",a="Масток Райльшип, офицер Орды в Ясеневом лесу, поручает искателям приключений доставить оскверненную реликвию Дже'неу, поняв, что армия не может разгадать ее странную магическую природу.",al={"who starts this quest","mastok quest","кто начинает задание","задание мастока"}},{q="Что Дже'неу сделает со сферой?",a="Дже'неу забирает сосуд, чтобы Служители Земли могли изучить природу его порчи в надежде, что исследование покажет способ очистить воды и вернуть покой встревоженным элементалям региона.",al={"what happens to the globe","cure the corruption","что будет со сферой","исцелить порчу"}}},fp="26,392,28.454.0,28.469.0,22.254.0,25.242.0,34.169.0,33.219.0,35.185.0,35.207.0"}
P.entries["quest:8249"] = {n="Принести лари",s="В Поместье Черного Ворона Винстон Вульф постоянно нуждается в прочных запертых контейнерах для обучения растущих разбойников гильдии. Поскольку тренировочные замки, которые делает мастер поместья, слишком просты для продвинутых учеников, Вульф обменивает особые метательные ножи на настоящие тяжелые ларцы у всех, кто готов их доставить.",h="В Поместье Черного Ворона Винстон Вульф постоянно нуждается в прочных запертых контейнерах для обучения...",kw={"heavy junkbox","hillsbrad","junkboxes","lockpicking","pickpocket","ravenholdt","winstone wolfe","zan","тяжелый ларец","хилсбрад","лари","взлом замков","карманная кража","черный ворон","винстон вульф","зан"},ang={["class:Rogue"]="Добыча этих тяжелых ларцов целиком зависит от искусства кражи из карманов у опытных противников, что делает Черный Ворон главным центром незаконных умений разбойника.",["faction:Alliance"]="Хотя Черный Ворон скрыт на спорной территории Лордерона, он действует независимо и принимает заказы от странников Альянса, не обращая внимания на границы фракций.",["faction:Horde"]="Агенты Орды, отважившиеся на путь в горы Хилсбрада, находят Черный Ворон равнодушным к верности фракциям: там превыше всего ценят полезные незаконные товары."},sec={{t="Оттачивая когти Черного Ворона",b="В тайном оплоте Поместья Черного Ворона, укрытом в горах над Предгорьями Хилсбрада, обучение не прекращается никогда. Мастер-вор Винстон Вульф руководит подготовкой агентов гильдии и высоко ценит практическое мастерство взлома замков. Хотя Зан делает тренировочные механизмы для новобранцев, Вульф считает эту грубую работу совершенно непригодной для опытных агентов, которым в поле приходится вскрывать настоящие упрямые механизмы."},{t="Странно открытая договоренность",b="Чтобы обеспечить поместье настоящими механизмами, Вульф заказывает тяжелые ларцы, украденные у опасных целей по всему Азероту. Хотя вытащить такие ларцы у жертв в дикой местности могут только умелые воры, Вульф не ограничивает свое дело одними разбойниками. Каждый, кто доставит партии этих запертых сундуков — пусть даже уже избавленных от главных ценностей, — заслужит расположение Вульфа и запас смертоносно сбалансированных метательных клинков поместья, если внутри остается хотя бы монета, чтобы мотивировать новичков."}},faq={{q="Зачем Винстону Вульфу эти лари?",a="Ученикам-разбойникам Черного Ворона нужны реалистичные механизмы для упражнений во взломе замков. Вульф считает тренировочные сундуки Зана, местного мастера поместья, слишком простыми для всех, кто вышел из начинающих, и требует настоящие ларцы, добытые у опасных жертв.",al={"why junkboxes","junkboxes purpose","why wolfe wants boxes","зачем лари","для чего лари","зачем вульфу ларцы"}},{q="Где происходит это задание?",a="Обмен проходит в Поместье Черного Ворона — тайном убежище гильдии воров, скрытом в горах к северу от Предгорий Хилсбрада.",al={"junkboxes needed location","where is winstone wolfe","ravenholdt location","принести лари где","где винстон вульф","где черный ворон"}},{q="Только ли разбойники могут сдать это задание?",a="Хотя тяжелые ларцы изначально добываются разбойничьим искусством кражи из карманов, Винстон Вульф принимает их от любого, кто способен доставить их в поместье.",al={"is this rogue only","can anyone do junkboxes needed","other classes junkboxes","только для разбойников","может ли любой","другие классы лари"}},{q="Почему в ларцах должны оставаться монеты?",a="Вульф настаивает, чтобы в каждом сундуке оставалось несколько монет: даже разбойникам-ученикам нужен практический стимул и ощутимая награда для упражнений во взломе.",al={"why leave coins in box","do boxes need loot","empty junkboxes","зачем оставлять монеты","нужна ли добыча в ларце","пустые лари"}},{q="Что Черный Ворон предлагает взамен?",a="Вульф награждает помощников положением в гильдии и искусно сделанными метательными ножами, которые, как он саркастически желает, найдут место прямо в чьем-нибудь сердце.",al={"junkboxes needed reward","what does wolfe give","ravenholdt throwing knives","награда за лари","что дает вульф","метательные ножи черного ворона"}},{q="Кто такой Зан, на которого жалуется Вульф?",a="Зан — штатный поставщик замков Черного Ворона. Вульф считает механизмы Зана грубыми и годными только для самых зеленых новичков, а не для настоящих агентов.",al={"who is zan","zan ravenholdt","zan locks","кто такой зан","зан черный ворон","замки зана"}}},fp="16,328,30.439.0,28.518.0,45.266.0,32.151.0,35.185.0,52.167.0,39.158.0,38.167.0"}
P.entries["quest:825"] = {n="Обломки кораблекрушения",s="Га'Ток из Колючего Холма поручает разведчикам Орды собрать останки затонувшего флота верховного адмирала Праудмура у Берега Разбитых Кораблей. Достав из воды передовые инструменты гномов, Орда надеется изучить инженерию Альянса и обратить это технологическое преимущество себе на пользу.",h="Га'Ток из Колючего Холма поручает разведчикам Орды собрать останки затонувшего флота верховного адмирала...",kw={"durotar","gar'thok","gnomish tools","proudmoore","razor hill","salvage","scuttle coast","tiragarde keep","wreckage","дуротар","га'ток","инструменты гномов","праудмур","колючий холм","спасение","берег разбитых кораблей","крепость тирагард","обломки"},ang={["faction:Horde"]="Га'Ток видит в каждом обломке металла Альянса двойной приз: знания, чтобы отразить будущие вторжения, и материал для строительства молодого государства в Дуротаре.",["profession:Engineering"]="Для механиков добыча инструментов гномов показывает раннее технологическое противостояние между механической точностью Альянса и зарождающимися ремеслами Орды.",["race:Gnome"]="Хотя гномы малы ростом, они оставляют след везде, где плавает Альянс; Орда уважает их хитроумное снаряжение настолько, что снаряжает ради него особые вылазки."},sec={{t="Отголоски флота",b="Когда верховный адмирал Даэлин Праудмур привел военную мощь Кул Тираса в Калимдор, его корабли заполнили берег близ Крепости Тирагард. После его поражения разбитые корпуса осели вдоль Берега Разбитых Кораблей. Пока уцелевшие култирасские солдаты укрепляют саму крепость, остатки их армады лежат изломанные на мелях и медленно гниют под приливом."},{t="Гномьи механизмы",b="Война орков традиционно опирается на грубую силу, железо и кровь, но Орда признает опасное преимущество изобретательности Альянса. Гномьи техники сопровождали экспедиционные флоты, оснащая корабли Альянса сложными машинами и точными приспособлениями. Га'Ток стремится достать эти затонувшие инструменты, чтобы Орда могла раскрыть принципы их работы."},{t="Путь в Оргриммар",b="Добытые инструменты не должны пылиться в Колючем Холме. Га'Ток отправляет их караваном прямо в Оргриммар. Разбирая гномьи приборы, ремесленники и тактики Орды рассчитывают лучше противостоять устройствам Альянса в грядущих конфликтах и укрепить собственную зарождающуюся промышленность."}},faq={{q="Зачем Орда достает инструменты из этих обломков?",a="Орда хочет понять передовые технологии Альянса. Гномы строят сложные механизмы для войск людей, и, изучая их инструменты, тактики Орды смогут найти способы противостоять устройствам Альянса, а ремесленники — перенять полезные механизмы.",al={"why get gnomish tools","why salvage wreck","gar'thok reason for tools","зачем инструменты гномов","зачем обломки кораблей","зачем га'току инструменты"}},{q="Чьи корабли разбились у Берега Разбитых Кораблей?",a="Затонувшие суда принадлежали флоту Кул Тираса верховного адмирала Даэлина Праудмура. После высадки на берегах Дуротара для войны против молодого государства Тралла несколько кораблей были уничтожены вдоль побережья к востоку от Крепости Тирагард.",al={"whose ships are these","who wrecked ships durotar","proudmoore fleet wreckage","чьи это корабли","кто разбил корабли в дуротаре","обломки флота праудмура"}},{q="Куда отправляются найденные инструменты после Колючего Холма?",a="Га'Ток отправляет найденные инструменты гномов следующим караваном в Оргриммар. Там инженеры и ремесленники смогут тщательно изучить механизмы, чтобы укрепить оборону и промышленность столицы.",al={"what happens to tools","where do gnomish tools go","who gets the salvage","что будет с инструментами","куда идут инструменты гномов","кому достается добыча"}},{q="Почему инструменты гномов находят на военных кораблях людей?",a="Гномы — близкие союзники людей в Великом Альянсе и часто снабжают морские экспедиции механическими знаниями, осадным снаряжением и точными инструментами для обслуживания, чтобы боевые флоты оставались на ходу.",al={"why gnomes with humans","gnomes on proudmoore ships","alliance gnomish tech","почему гномы с людьми","гномы на кораблях праудмура","гномья техника альянса"}},{q="Что такое Берег Разбитых Кораблей?",a="Берег Разбитых Кораблей — восточное побережье Дуротара, тянущееся мимо Крепости Тирагард. Он назван так из-за полузатопленных и затонувших кораблей, усеявших мелководье после сражений с экспедицией Праудмура.",al={"where is scuttle coast","scuttle coast location","durotar sunken ships area","где берег разбитых кораблей","расположение берега разбитых кораблей","затонувшие корабли дуротар"}},{q="Как это задание связано с угрозой у Крепости Тирагард?",a="Когда во время штурма Крепости Тирагард култирасские морпехи были перебиты, Га'Ток пользуется случаем и забирает оставшиеся ресурсы Альянса. Обыск ближайших обломков кораблей гарантирует, что Орда извлечет выгоду из поражения врага прежде, чем все растащат мародеры или унесет приливом.",al={"tiragarde keep connection","vanquish the betrayers link","why do this after tiragarde","связь с крепостью тирагард","крепость тирагард","зачем после тирагард"}}},fp="21,302,19.363.0,20.378.0,22.336.0,51.283.0,46.249.0,49.208.0,46.210.0,26.220.0,58.272.0"}
P.entries["quest:826"] = {n="Залазан",s="Мастер Гадрин из Деревни Сен'джин поручает героям Орды отправиться на Острова Эха и положить конец предательству знахаря Залазана. Сведенный с ума темной магией, Залазан поработил соплеменников и захватил законный дом троллей Черного Копья, вынудив их уйти в изгнание на берег Дуротара.",h="Мастер Гадрин из Деревни Сен'джин поручает героям Орды отправиться на Острова Эха и положить конец...",kw={"darkspear","durotar","echo isles","hexed troll","master gadrin","sen'jin village","vol'jin","voodoo troll","zalazane","черное копье","дуротар","острова эха","околдованный тролль","мастер гадрин","деревня сен'джин","вол'джин","тролль вуду","залазан"},ang={["class:Shaman"]="Залазан извращает духовные искусства и первобытные силы, которыми владеют тролли-шаманы и знахари, обращая связывающую магию против собственных собратьев.",["faction:Horde"]="Этот конфликт — одно из первых серьезных испытаний единства молодой Орды, доказывающее, что союзники со всего Дуротара встанут на защиту изгнанного племени Черного Копья.",["race:Troll"]="Для тролля Черного Копья убийство Залазана — глубоко личный акт мести и долга: наказание предателя, укравшего законный дом вашего народа и поработившего ваших братьев."},sec={{t="Предательство на островах",b="Когда племя Черного Копья покинуло свой затонувший островной дом и последовало за Траллом через Великое море, оно основало поселение на Островах Эха у юго-восточного берега Дуротара. Залазан, уважаемый и могущественный знахарь племени, поддался жажде власти. Используя порабощающие разум проклятия, он подчинил многих сородичей и поднял жестокое восстание. Оставшиеся свободными воины Черного Копья под предводительством Вол'джина были изгнаны из родовых лагерей за водой и вынуждены построить временное убежище в Деревне Сен'джин."},{t="Мучения племени",b="Залазану было мало просто изгнать племя. Из своего оплота на вершине холма на центральном из Островов Эха он регулярно посылает отряды через пролив, чтобы схватить новых троллей Черного Копья и обратить их в рабство. Пораженные становятся безвольными вуду-рабами и околдованными слугами, навсегда потерянными для племени. Мастер Гадрин видит в этом не просто захват земли, но смертельную угрозу: пока голова Залазана не будет принесена старейшинам, никто из Черного Копья не может чувствовать себя в безопасности."}},faq={{q="Кто такой Залазан?",a="Залазан когда-то был видным знахарем среди троллей Черного Копья. Развращенный жаждой темной силы, он обратился против своих собратьев, используя подчиняющее разум вуду, чтобы поработить соплеменников и завладеть Островами Эха.",al={"zalazane lore","who is the boss on echo isles","witch doctor zalazane","залазан предания","кто главарь на островах эха","знахарь залазан"}},{q="Почему тролли Черного Копья бежали с Островов Эха?",a="Залазан устроил на островах внезапный переворот, превратив братьев и сестер в безвольных рабов с помощью гнусного колдовства. У Вол'джина и уцелевших свободных троллей Черного Копья не хватало сил выступить против околдованных сородичей, и они отступили на материк в Дуротар, основав Деревню Сен'джин как временное убежище.",al={"why are trolls in sen'jin village","echo isles backstory","how did trolls lose echo isles","почему тролли в деревне сен'джин","история островов эха","как тролли потеряли острова эха"}},{q="Что происходит с троллями под властью Залазана?",a="Разум троллей под его властью полностью разрушен мощными проклятиями. Они действуют лишь как безвольные слуги Залазана, патрулируя острова и совершая набеги на материк, чтобы захватить новых жертв. Мастер Гадрин считает их полностью потерянными для племени, и единственной милостью остается казнь.",al={"hexed trolls","voodoo trolls","can zalazane's thralls be cured","околдованные тролли","тролли вуду","можно ли исцелить рабов залазана"}},{q="Где находится Залазан?",a="Залазан устроил логово на самом большом из Островов Эха, к востоку от южного берега Дуротара. Он обходит владения от высокой вершины центрального холма до скопления хижин троллей прямо под ней.",al={"zalazane location","find zalazane","where is zalazane","где залазан","найти залазана","расположение залазана"}},{q="Кто выдает задание убить Залазана?",a="Мастер Гадрин, старейшина племени в Деревне Сен'джин на южном берегу Дуротара, предлагает это задание после того, как вы выполните вводные задания против местных угроз и придете из Долины Испытаний.",al={"who starts zalazane","where to get zalazane quest","кто дает задание залазан","где взять задание залазана"}},{q="Почему Вол'джин не возглавит нападение сам?",a="Пока Вол'джин правит племенем и координирует оборону Черного Копья вместе с вождем Траллом в Оргриммаре, Деревня Сен'джин остается под местным руководством старейшин вроде Мастера Гадрина. Гадрин организует повседневное выживание и нанимает способных искателей приключений, чтобы нанести ответный удар вероломному знахарю.",al={"where is vol'jin","why isn't vol'jin fighting zalazane","где вол'джин","почему вол'джин не сражается с залазаном"}}},fp="8,295,21.525.0,17.490.0,16.236.0,42.307.0,52.300.0,26.227.0,37.208.0,46.307.0"}
P.entries["quest:827"] = {n="Скала Черепа",s="Это задание выдает отшельник Маргоз и направляет искателей приключений из Орды в пещеру Скала Черепа к востоку от Оргриммара. Пещеру захватил культ Пылающего Клинка: его последователи используют болезненные демонические приспособления, чтобы подчинить себя темной магии. Добыв эти проклятые предметы, Маргоз сможет изучить присутствие культа у самых ворот столицы.",h="Это задание выдает отшельник Маргоз и направляет искателей приключений из Орды в пещеру Скала Черепа к...",kw={"burning blade","cultists","demonic","durotar","fel","margoz","orgrimmar","searing collar","skull rock","пылающий клинок","культисты","демонический","дуротар","скверна","маргоз","оргриммар","обжигающий ошейник","скала черепа"},ang={["class:Warlock"]="Обжигающие ошейники — грубые, но мощные путы скверны; они позволяют чернокнижникам увидеть, как культ превращает демонические жертвоприношения в необузданную силу.",["faction:Horde"]="Демонический культ, разраставшийся у самых стен Оргриммара, угрожает самому сердцу и безопасности молодой Орды.",["race:Orc"]="Пылающий Клинок — темное прошлое, которое орки каждый день стараются оставить позади; очистить скалы Дуротара от него — вопрос выживания и чести."},sec={{t="Логово теней",b="Скала Черепа — мрачная морская пещера на скалистом восточном побережье Дуротара. Хотя она кажется уединенной, она тревожно близка к могучим вратам Оргриммара. Эти пещеры служат приютом не диким зверям и не простым разбойникам, а ячейке Пылающего Клинка — теневого демонического культа, давно терзающего общество орков. В этих тусклых туннелях культисты проводят нечестивые ритуалы под носом у разведчиков Вождя."},{t="Демоническая настройка",b="Культисты в Скале Черепа носят Обжигающие ошейники — обручи, предназначенные жечь и клеймить их собственную плоть. По словам Маргоза, это самоистязание вовсе не бессмысленная жестокость: жгучая боль и скверная магия, заключенная в металле, настраивают владельцев на демоническую силу. Добыв эти предметы, Маргоз намерен разгадать заклинания и путы, дающие силу рядам Пылающего Клинка."},{t="Нависшая угроза",b="Тайна ошейников подтверждает, что присутствие культа в Дуротаре намеренное и организованное. Пылающий Клинок — не просто разрозненные разбойники: его колдовство глубоко и представляет явную, коварную угрозу для недавно основанных земель Орды. Изучение ошейников запускает цепочку расследований, которая ведет прямо в темные круги самого Оргриммара."}},faq={{q="Где находится Скала Черепа?",a="Скала Черепа — прибрежная пещера на северо-востоке Дуротара, на берегу к востоку от Оргриммара и к северу от Деревни Сен'джин. Вход отмечен скалистым утесом, обрамляющим его.",al={"skull rock location","where is skull rock","skull rock cave durotar","скала черепа где","где находится скала черепа","пещера скала черепа дуротар"}},{q="Что представляет собой Пылающий Клинок?",a="Пылающий Клинок — опасный культ орков и почитателей скверны, преданный демоническим сущностям и темной магии. Хотя нынешняя Орда избавилась от демонического рабства, отколовшиеся группы вроде Пылающего Клинка продолжают совершать запретные ритуалы, чтобы из тени развращать Орду.",al={"what is burning blade","who are burning blade cultists","burning blade lore","что такое пылающий клинок","кто такие культисты пылающего клинка","пылающий клинок предания"}},{q="Для чего культисты используют Обжигающие ошейники?",a="Культисты носят раскаленные металлические обручи на шее, чтобы жечь собственную плоть. Маргоз подозревает, что эта ритуальная боль и демонические чары позволяют им направлять темную энергию скверны и настраиваться на нее.",al={"searing collars purpose","why wear searing collars","what are searing collars","назначение обжигающих ошейников","зачем носить обжигающие ошейники","что такое обжигающие ошейники"}},{q="Кто такой Маргоз?",a="Маргоз — орк-отшельник, живущий в небольшом лагере на утесах Дуротара неподалеку от Скалы Черепа. Он следит за передвижениями культистов на побережье и стремится разрушить темные замыслы Пылающего Клинка.",al={"who is margoz","margoz durotar","margoz questgiver","кто такой маргоз","маргоз дуротар","маргоз задания"}},{q="Почему Орда допускает культ так близко к Оргриммару?",a="Они терпят его не по своей воле. Культ действует в глубокой тайне, прячась в морских пещерах и пустынных ущельях, куда редко добираются обычные патрули. Искателей приключений посылают на разведку именно потому, что культистам удается скрывать свои опорные пункты, пока не начнутся темные ритуалы.",al={"why is skull rock near orgrimmar","orgrimmar burning blade nearby","почему скала черепа рядом с оргриммаром","пылающий клинок рядом с оргриммаром"}},{q="Что происходит после того, как Маргоз осмотрит ошейники?",a="Margoz intends to examine the Searing Collars. The investigation continues with the quest Neeru Fireblade in Orgrimmar.",al={"next quest after skull rock","where do collars lead","margoz spell","следующее задание после скалы черепа","куда ведут ошейники","заклинание маргоза"}}},fp="10,347,16.438.0,18.420.0,18.403.1,28.201.0,25.286.0,49.217.0,14.217.0,56.283.0,47.119.1"}
P.entries["quest:828"] = {n="Маргоз",s="Маргоз — задание Орды: искателям приключений нужно найти уединенного орка-шамана, охраняющего северные земли Дуротара. После столкновения со скверной в каньоне Оргнил Душегрыз велит героям обратиться к Маргозу, прежде чем штурмовать ближайшую твердыню культистов. Мудрый отшельник дает важные советы о растущей тени Пылающего Клинка.",h="Маргоз — задание Орды: искателям приключений нужно найти уединенного орка-шамана, охраняющего северные земли...",kw={"burning blade","drygulch ravine","durotar","margoz","orgnil soulscar","orgrimmar","shaman","skull rock","пылающий клинок","сухая лощина","дуротар","маргоз","оргнил душегрыз","оргриммар","шаман","скала черепа"},ang={["class:Shaman"]="Маргоз воплощает древнюю, терпеливую мудрость шаманизма: он несет дозор на окраинах дикой местности, чтобы почувствовать духовную скверну, пока она не переросла в войну.",["faction:Horde"]="Предупреждение Маргоза подчеркивает уязвимость Оргриммара: демонические культы скрываются на расстоянии удара от сердца Орды.",["race:Orc"]="Встреча с Маргозом напоминает орочьим воинам о не утихшем искушении силой скверны и призывает новое поколение идти чистым и честным путем."},sec={{t="Бдение отшельника",b="Обнаружив глубину скверны на Громовом хребте, Оргнил Душегрыз понимает, что одной грубой силой Дуротар не очистить. Он направляет своих героев к Маргозу, опытному орку-шаману, живущему в одиноком лагере в скалах к северо-востоку от Колючего Холма. Между зубчатыми высотами Сухой лощины и восточным морем Маргоз следит за темными знамениями, которые шумные воины Оргриммара часто упускают."},{t="Угроза Скалы Черепа",b="Маргоз располагает важными сведениями об истинном оплоте Пылающего Клинка на севере Дуротара: скрытой системе пещер под названием Скала Черепа, вырубленной в горных утесах у южных ворот Оргриммара. Побеседовав с Маргозом, путники узнают, что культисты действуют гораздо ближе к столице Тралла, чем думают стражи Вождя. Шаман следит за тем, чтобы тот, кого отправят уничтожить шабаш, не угодил вслепую в демоническую засаду."}},faq={{q="Кто такой Маргоз?",a="Маргоз — мудрый орк-шаман, верный Орде, живущий в уединенном лагере на северо-востоке Дуротара. Он изучает движения темной магии и наблюдает за демонической скверной, распространяющейся по региону.",al={"margoz lore","who is margoz","margoz npc","маргоз предания","кто такой маргоз","маргоз персонаж"}},{q="Где найти Маргоза?",a="Маргоз разбил лагерь в суровых холмах северо-восточного Дуротара, между Сухой лощиной и восточным побережьем, к юго-востоку от Оргриммара.",al={"margoz location","find margoz","where is margoz","где находится маргоз","найти маргоза","где маргоз"}},{q="Почему Оргнил Душегрыз посылает меня к Маргозу?",a="Оргнил знает, что Маргоз долго изучал местных культистов Пылающего Клинка. Прежде чем отправить вас штурмовать их твердыню, Оргнил хочет, чтобы вы услышали духовную мудрость и практические советы Маргоза.",al={"why speak with margoz","orgnil soulscar margoz","зачем говорить с маргозом","оргнил душегрыз маргоз"}},{q="Что такое Скала Черепа?",a="Скала Черепа — скрытая горная пещера к югу от восточных стен Оргриммара. Это укрепленный шабаш Пылающего Клинка, где культисты, поклоняющиеся демонам, проводят ритуалы прямо под носом у Орды.",al={"skull rock lore","what is skull rock","скала черепа предания","что такое скала черепа"}},{q="Что происходит после встречи с Маргозом?",a="Когда вы докладываете Маргозу, он признает вашу растущую силу и сразу поручает вам войти в Скалу Черепа, убить культистов и добыть их оскверненные знаки.",al={"next quest after margoz","margoz follow up","следующее задание после маргоза","продолжение маргоза"}},{q="Состоит ли Маргоз в Пылающем Клинке?",a="Нет. Маргоз — преданный Орде шаман, стремящийся искоренить демоническое влияние и удержать молодых героев на честном, неоскверненном пути.",al={"is margoz evil","is margoz a cultist","маргоз злодей","маргоз культист"}}},fp="6,392,16.446.0,24.462.0,14.205.0,23.154.0,43.222.0,19.209.0,34.174.1,36.147.0"}
P.entries["quest:829"] = {n="Нииру Огненный Клинок",s="Это задание отправляет искателей приключений из Орды от Маргоза в Дуротаре в темные недра Оргриммара. Получив демонический Обжигающий ошейник, добытый у культа Пылающего Клинка, вы должны найти Нииру Огненного Клинка, известного чернокнижника из Расселины Теней, который утверждает, что изучает темные искусства лишь ради защиты Орды.",h="Это задание отправляет искателей приключений из Орды от Маргоза в Дуротаре в темные недра Оргриммара.",kw={"burning blade","cleft of shadow","durotar","margoz","neeru fireblade","orgrimmar","searing collar","skull rock","warlock","пылающий клинок","расселина теней","дуротар","маргоз","нииру огненный клинок","оргриммар","обжигающий ошейник","скала черепа","чернокнижник"},ang={["class:Shaman"]="Признание Маргоза четко отделяет шаманизм от демонической магии: стихии не станут общаться с предметами скверны, поэтому нужна помощь чернокнижника.",["class:Warlock"]="Визит в Расселину Теней к Нииру Огненному Клинку сводит вас с самым известным чернокнижником Оргриммара и подтверждает практическую ценность вашего запретного ремесла для Орды.",["faction:Horde"]="Это поручение показывает хрупкое перемирие в Оргриммаре: шаманам Вождя порой приходится обращаться к темным изгоям в Расселине Теней, чтобы уберечь Дуротар от гибели."},sec={{t="Пределы шамана",b="Добыв Обжигающие ошейники у культистов в Скале Черепа, шаман Маргоз понимает, что разгадать их мерзкое колдовство не под силу его древним искусствам. Шаманы общаются с духами стихий и земли, а эти предметы смердят необузданной демонической скверной. Поскольку понять устройства Пылающего Клинка может лишь знаток оккультизма, Маргоз посылает вас к чернокнижнику в столице."},{t="В Расселину Теней",b="Под красными утесами Оргриммара лежит Расселина Теней — тускло освещенная пещера, где мастера запретной магии занимаются своим ремеслом под бдительным оком Тралла. Там живет Нииру Огненный Клинок, влиятельный орк-чернокнижник, уверяющий, что его владение силой скверны целиком направлено на борьбу с демонической угрозой. Получив образец ошейника, он сразу проявляет любопытство, и расследование о культе в Дуротаре приводит прямо в сердце общины чернокнижников."}},faq={{q="Почему Маргоз посылает меня к чернокнижнику?",a="Маргоз — шаман, чья сила происходит от стихий и духов предков. Обжигающие ошейники из Скалы Черепа имеют сугубо демоническую природу, и чтобы определить их чары и происхождение, нужен тот, кто обучен магии скверны и темным искусствам.",al={"why warlock","why neeru","margoz warlock","почему чернокнижник","почему нииру","маргоз чернокнижник"}},{q="Где найти Нииру Огненного Клинка?",a="Нииру Огненный Клинок находится в Расселине Теней — подземном пещерном комплексе под Оргриммаром, где собираются чернокнижники, разбойники и повелители теней.",al={"neeru location","where is neeru fireblade","cleft of shadow neeru","где нииру","где найти нииру огненного клинка","расселина теней нииру"}},{q="Можно ли доверять Нииру Огненному Клинку?",a="Сам Маргоз сомневается: Нииру утверждает, что его оккультные исследования безвредны и служат лишь борьбе с демонами, но правда это или ложь — покажет время. Тралл допускает чернокнижников в Оргриммаре под строгим надзором, но осторожность не помешает.",al={"is neeru evil","neeru trustworthy","can i trust fireblade","нииру злой","нииру можно доверять","доверять огненному клинку"}},{q="Что такое Обжигающий ошейник?",a="Обжигающий ошейник — один из Обжигающих ошейников, снятых с культистов Пылающего Клинка в Скале Черепа. Маргоз отдает его вам, чтобы вы доставили его прямо Нииру Огненному Клинку для магического исследования.",al={"example collar","what is the collar","searing collar quest item","обжигающий ошейник","что за ошейник","предмет задания обжигающий ошейник"}},{q="Что происходит после передачи ошейника Нииру?",a="Нииру внимательно осматривает ошейник, и это ведет к заданию «Ак'Зелот», в котором он направляет вас глубже в расследование о теневом присутствии культа в Дуротаре.",al={"next quest after neeru","what does neeru do","quest chain after neeru","следующее задание после нииру","что делает нииру","цепочка заданий после нииру"}},{q="Почему Орда допускает чернокнижников в Оргриммаре?",a="Вождь Тралл терпит чернокнижников по практической необходимости, удерживая их в подземной Расселине Теней, чтобы их опасные исследования можно было наблюдать, контролировать и порой использовать для понимания демонических врагов.",al={"why are warlocks allowed","warlocks in cleft of shadow","thrall warlocks","почему разрешены чернокнижники","чернокнижники в расселине теней","тралл чернокнижники"}}},fp="15,317,17.439.0,24.451.0,37.267.0,33.151.0,31.258.0,27.185.0,46.160.0,47.234.0"}
P.entries["quest:83"] = {n="Красный лен",s="«Красный лен» — задание в Элвиннском лесу, которое выдает портниха Сара Тимберлейн на Лесопилке Восточной долины. Ей не хватает ткани, и она просит проходящих мимо искателей приключений выследить местных разбойников из Братства Справедливости и снять с них льняные банданы. Из добытой ткани она шьет полезные вещи для путников.",h="«Красный лен» — задание в Элвиннском лесу, которое выдает портниха Сара Тимберлейн на Лесопилке Восточной...",kw={"burlap","defias brotherhood","eastvale logging camp","elwynn forest","red linen bandana","red linen goods","sara timberlain","tailoring","мешковина","братство справедливости","лесопилка восточной долины","элвиннский лес","красная льняная бандана","красный лен","сара тимберлейн","портняжное дело"},ang={["faction:Alliance"]="Зачистка разбойников Братства Справедливости, наводнивших рощи Элвинна, не только дает полезную добычу для Восточной долины, но и ослабляет хватку Братства в сердце королевства.",["profession:Tailoring"]="Ремесло Сары Тимберлейн показывает суровую реальность сельского портняжного дела: из-за нехватки рулонов ткани местные портнихи вынуждены снимать материю прямо с плеч здешних бандитов."},sec={{t="Бандиты и мешковина",b="Малочисленные бандиты Братства Справедливости, дерущиеся в Долине Североземья, обходятся дешевыми масками из мешковины, а организованные разбойники, рыскающие по Элвиннскому лесу, носят более добротные багровые льняные банданы. Для местных мастеров, которым не хватает сырья, эти знаки отличия банды — на удивление удобный источник пригодной ткани."},{t="Добыча у лагеря",b="Сара Тимберлейн работает на шумной Лесопилке Восточной долины у восточной границы Элвиннского леса и всегда ищет пригодную ткань. Побуждая искателей приключений проредить лагеря Братства Справедливости, спрятанные в лесах, она обеспечивает сырьем свое ремесло и помогает сдерживать наглое вторжение Братства."}},faq={{q="Кто выдает задание «Красный лен»?",a="Это задание выдает Сара Тимберлейн, местная портниха с Лесопилки Восточной долины на востоке Элвиннского леса.",al={"who gives red linen goods","red linen goods questgiver","sara timberlain quest","кто дает красный лен","красный лен кто выдает задание","задание сары тимберлейн"}},{q="Какие предметы нужны для задания «Красный лен»?",a="Нужно собрать 6 красных льняных бандан. Их можно получить с членов банд Братства Справедливости, разбросанных по Элвиннскому лесу.",al={"what do i collect for red linen goods","items for red linen goods","bandanas needed","что собирать для красного льна","предметы для красного льна","какие банданы нужны"}},{q="Где в Элвиннском лесу найти разбойников Братства Справедливости?",a="Разбойники Братства Справедливости живут в небольших лагерях по всему Элвиннскому лесу, в том числе возле Тыквенного поля Бреквеллов, Фермы Стоунфилдов и в лесах вокруг Лагеря Джерода.",al={"defias locations elwynn","where are defias camps","where to get red bandanas","где братство справедливости в элвиннском лесу","где лагеря братства справедливости","где достать красные банданы"}},{q="Почему бандиты Братства Справедливости в Элвиннском лесу носят лен, а не мешковину?",a="По словам Сары Тимберлейн, рядовые бандиты Братства Справедливости в Североземье носят грубые маски из мешковины, а лучше снаряженные члены, действующие по всему Элвиннскому лесу, носят красный лен, что говорит о более высоком уровне организации и снабжения Братства.",al={"why red linen","burlap vs linen defias","defias mask material","почему красный лен","мешковина или лен","материал масок братства справедливости"}},{q="Зачем Саре Тимберлейн банданы разбойников?",a="У Сары заканчивается ткань для ее портняжного дела. Она перешивает отстиранный лен масок Братства Справедливости в полезные вещи для дровосеков и путников на лесопилке.",al={"why collect bandanas","what does sara do with masks","зачем собирать банданы","что сара делает с масками"}},{q="Где находится Лесопилка Восточной долины?",a="Лесопилка Восточной долины находится на крайнем востоке Элвиннского леса, к северу от главной дороги к мосту в Красногорье.",al={"eastvale location","where is eastvale","how to find sara timberlain","восточная долина","где лесопилка восточной долины","как найти сару тимберлейн"}}},fp="15,310,18.315.0,19.337.0,37.120.0,42.122.0,49.185.0,54.246.0,46.182.0,43.142.0"}
P.entries["quest:830"] = {n="Приказы адмирала",s="Эти потертые бумаги, найденные в запертом сундуке на вершине Крепости Тирагард, несут личную печать покойного верховного адмирала Даэлина Праудмура. Приказы показывают, что гарнизон култирасцев на побережье Дуротара гораздо лучше укреплен и организован, чем просто выжившие после кораблекрушения. Доставка их Га'Току в Колючий Холм раскрывает сохранившиеся военные планы, угрожающие молодой оркской нации.",h="Эти потертые бумаги, найденные в запертом сундуке на вершине Крепости Тирагард, несут личную печать покойного...",kw={"admirals orders","aged envelope","daelin proudmoore","gar'thok","kul tiras","lieutenant benedict","razor hill","tiragarde keep","приказы адмирала","старый конверт","даэлин праудмур","га'ток","кул тирас","лейтенант бенедикт","колючий холм","крепость тирагард"},ang={["faction:Horde"]="Найденные приказы Праудмура доказывают, что присутствие Альянса на берегах Дуротара было спланированной кампанией истребления, и потому Орда должна бдительно защищать свой новый дом.",["race:Orc"]="Для орков, строящих будущее в Дуротаре, эти документы — суровое напоминание о неослабевающей ненависти Даэлина Праудмура и о его последователях, все еще жаждущих их гибели."},sec={{t="Запечатанное наследие",b="В тяжелом сундуке на верхних этажах Крепости Тирагард под охраной лейтенанта Бенедикта хранится старый конверт. Пергамент, скрепленный печатью верховного адмирала Даэлина Праудмура, содержит прямые морские приказы, отданные во время кровавого вторжения Кул Тираса в Дуротар. Даже после гибели адмирала у Терамора его офицеры удерживали укрепления, упорно держась за цель уничтожить поселение Орды."},{t="Тревога в Колючем Холме",b="Доставка найденных документов Га'Току, командиру Колючего Холма, подтверждает худшие опасения местных защитников. Войска людей, окопавшиеся на восточном побережье, — не случайные уцелевшие, а настоящий плацдарм, ожидающий подкрепления. Га'Ток сразу понимает, что разгром командования Тирагарда — вопрос выживания Дуротара."}},faq={{q="Где найти приказы адмирала?",a="Приказы лежат в старом конверте в запертом сундуке на третьем этаже Крепости Тирагард в Дуротаре. Чтобы открыть сундук, вы должны сначала победить лейтенанта Бенедикта на втором этаже и забрать его ключ.",al={"orders location","where is aged envelope","find admirals orders","где приказы","где старый конверт","найти приказы адмирала"}},{q="Кем был адмирал Праудмур?",a="Верховный адмирал Даэлин Праудмур был правителем Кул Тираса и верховным командующим флотом Альянса во время Второй войны. Не веря, что орки могут жить мирно, он отплыл в Калимдор, чтобы вести войну на истребление против Дуротара, и погиб у Терамора.",al={"who is the admiral","daelin proudmoore lore","who issued orders","кто такой адмирал","даэлин праудмур предания","кто отдал приказы"}},{q="Почему култирасцы все еще находятся в Крепости Тирагард?",a="Когда Даэлин Праудмур вторгся в Дуротар, он основал укрепленные прибрежные плацдармы, такие как Крепость Тирагард. После его поражения уцелевшие офицеры и морпехи под началом лейтенанта Бенедикта удержали свои посты, решив продолжить его кампанию против Орды.",al={"why are humans in durotar","tiragarde keep soldiers","kul tiras in durotar","почему люди в дуротаре","солдаты крепости тирагард","кул тирас в дуротаре"}},{q="Почему Га'Ток так обеспокоен этими приказами?",a="Как военный командир Колючего Холма, Га'Ток отвечает за защиту центрального Дуротара. Найденные морские приказы доказывают, что Крепость Тирагард — реальная, продуманная военная угроза оркской родине, а не просто разрозненные выжившие.",al={"gar'thok reaction","why does garthok care","реакция га'тока","почему га'ток беспокоится"}},{q="У кого ключ от сундука адмирала?",a="Лейтенант Бенедикт, командующий офицер култирасцев на втором уровне Крепости Тирагард, носит ключ от сундука со старым конвертом.",al={"benedict key","who drops key","ключ бенедикта","у кого ключ"}},{q="Что происходит после передачи приказов Га'Току?",a="Изучив приказы, Га'Ток осознает непосредственную стратегическую опасность и велит действовать дальше: устранить оставшихся командиров людей и разрушить их операции в Дуротаре.",al={"admirals orders follow up","next quest","продолжение приказов адмирала","следующее задание"}}},fp="20,412,15.452.0,19.385.1,37.221.0,27.293.0,51.255.0,48.265.0,41.180.0,49.194.0"}
P.entries["quest:8311"] = {n="Тыквовинские вкусности для Джеспера!",s="Во время Тыквовина маленький сирота Джеспер болеет в приюте Штормграда и мечтает присоединиться к праздничному веселью. Он слишком болен, чтобы выйти, и просит искателей приключений из Альянса пройтись по миру за сладостями вместо него.",h="Во время Тыквовина маленький сирота Джеспер болеет в приюте Штормграда и мечтает присоединиться к...",kw={"darnassus","gumdrop","hallow's end","ironforge","jesper","marzipan","nightingale","nougat","stormwind","talvash","trick-or-treat","дарнасс","леденец","тыквовин","стальгорн","джеспер","марципан","соловей","нуга","штормград","талваш","сладость или гадость"},ang={["faction:Alliance"]="Это праздничное дело связывает далекие столицы: героям предстоит пройти от величественных улиц Штормграда до горных залов Стальгорна и ветвей Дарнасса, чтобы подарить радость осиротевшему ребенку.",["race:Gnome"]="Дом гномов потерян из-за троггов и радиации, поэтому участие гномов в празднике взял на себя Талваш де Киссель в Стальгорне, следящий, чтобы Леденцы Гномрегана по-прежнему раздавались."},sec={{t="Ребенок взаперти",b="Джеспер живет в приюте на Соборной площади Штормграда и в этот Тыквовин заболел. Лишенный простой детской радости собирать сладости по всему Азероту, он сидит дома в надежде, что проходящие мимо искатели приключений разделят праздничный дух и соберут угощения вместо него."},{t="Угощение или шалость по всему Альянсу",b="Чтобы собрать праздничное угощение, о котором мечтает Джеспер, искателю приключений придется уйти далеко за пределы Элвиннского леса. Нужно посетить трактирщиков Штормграда, Стальгорна и Дарнасса, а также изгнанника-гнома Талваша де Кисселя. Каждый взрослый требует представления, прежде чем отдать угощение: путники должны кудахтать, как куры, танцевать, показывать мускулы или пыхтеть, как поезд, в обмен на местные сладости, такие как Нуга из Штормграда и Леденец Гномрегана."}},faq={{q="Кто такой Джеспер?",a="Джеспер — маленький сирота из приюта Штормграда. Во время Тыквовина он мечтает о праздничных сладостях, но слишком болен, чтобы выйти и собрать их самому.",al={"jesper stormwind","orphan jesper","who is jesper","джеспер штормград","сирота джеспер","кто такой джеспер"}},{q="Почему Джеспер не может сам собирать сладости?",a="Джеспер болен, и болезнь не выпускает его из приюта, пока весь город празднует Тыквовин.",al={"why can't jesper leave","is jesper sick","jesper trick or treat","почему джеспер не может выйти","болен ли джеспер","джеспер сладости"}},{q="Какие угощения хочет Джеспер?",a="Он просит четыре разных местных лакомства: Нугу из Штормграда, мятные леденцы Стальгорна, Дарнасский марципан и Леденец Гномрегана.",al={"jesper treats","hallows end treats list","jesper candy needed","угощения джеспера","список угощений тыквовина","какие сладости нужны джесперу"}},{q="Где получить Леденец Гномрегана?",a="Поскольку Гномреган остается зараженным радиацией и захваченным врагами, леденец выдает гном-беженец Талваш де Киссель, который сейчас живет в Мистическом квартале Стальгорна.",al={"gnomeregan gumdrop location","who gives gumdrop","talvash candy","где леденец гномрегана","кто дает леденец","сладости талваша"}},{q="Какие трюки заставляют выполнять трактирщики?",a="Трактирщики требуют забавных выходок в обмен на сладости: показать мускулы в Штормграде, станцевать в Дарнассе, кудахтать как курица в Стальгорне и изобразить гудок поезда для Талваша.",al={"hallow's end tricks","innkeeper tricks","trick for treats alliance","трюки тыквовина","трюки трактирщиков","угощение или шалость альянс"}},{q="Что дает Джеспер взамен на сладости?",a="Получив набор из четырех праздничных сладостей, Джеспер радостно отдает путнику сохраненные тыквенные угощения.",al={"jesper reward","treats for jesper completion","награда джеспера","угощения для джеспера выполнение"}}},fp="31,240,17.293.0,37.450.0,14.156.0,46.114.0,30.127.0,43.170.0,47.187.0,50.131.0"}
P.entries["quest:832"] = {n="Пылающие тени",s="Этот таинственный светящийся кулон, снятый с культиста Пылающего Клинка Газз'уза в глубинах Скалы Черепа, шепчет в разум владельца срочные предупреждения. Голос угрожает Газз'узу гневом Нииру Огненного Клинка, орка-чернокнижника из Оргриммара.",h="Этот таинственный светящийся кулон, снятый с культиста Пылающего Клинка Газз'уза в глубинах Скалы Черепа...",kw={"burning blade","burning shadows","cleft of shadow","durotar","eye of burning shadow","gazz'uz","neeru fireblade","orgrimmar","skull rock","пылающий клинок","пылающие тени","расселина теней","дуротар","око пылающей тени","газз'уз","нииру огненный клинок","оргриммар","скала черепа"},ang={["class:Warlock"]="Для чернокнижника, обучающегося в Расселине Теней, упоминание имени другого практика Пылающим Клинком — напоминание о том, как тонка грань между разрешенным государством изучением Скверны и открытой изменой.",["faction:Horde"]="Шепот культистов у самых ворот столицы показывает, что демоническая порча Старой Орды все еще тлеет неприятно близко к сердцу Дуротара.",["race:Orc"]="Орки, сражавшиеся бок о бок с Траллом за очищение от скверны Легиона, считают присутствие Пылающего Клинка в Дуротаре недопустимым осквернением их новой родины."},sec={{t="Голос в камне",b="После убийства Газз'уза в глубинах Скалы Черепа из его останков извлекают зловещий кулон — Око Пылающей Тени. Это не безжизненная магическая безделушка: камень вибрирует психической связью. Властный голос обращается прямо к разуму того, кто его держит, требует отчетов от Газз'уза и предупреждает, что его тайные дела к востоку от Оргриммара раскрыты."},{t="Странная угроза",b="Верного разведчика Орды застает врасплох отчаянный ультиматум голоса: ответить, иначе Нииру Огненный Клинок получит приказ жестоко расправиться с Газз'узом. Нииру Огненный Клинок открыто живет в Расселине Теней в Оргриммаре и якобы занимается темными искусствами под строгим надзором Тралла. Когда талисман доставляют Нииру, тот изображает удивление и любопытство, поражаясь, что его имя использовали как пугало для культа."}},faq={{q="Что такое Око Пылающей Тени?",a="Око Пылающей Тени — зачарованный кулон, выпадающий из предводителя Пылающего Клинка Газз'уза в Скале Черепа. Он служит двусторонним телепатическим передатчиком между служителями культа и их невидимыми повелителями.",al={"eye of burning shadow","what is this pendant","gazz'uz eye","око пылающей тени","что за кулон","око газз'уза"}},{q="Кто говорит через кулон?",a="Неизвестный начальник из Совета Теней или иерархии Пылающего Клинка пытается связаться с Газз'узом, не зная, что культист уже убит в Скале Черепа.",al={"who spoke to me","voice in the pendant","who talks through eye","кто говорил со мной","голос в кулоне","кто говорит через око"}},{q="Почему голос угрожает Газз'узу Нииру Огненным Клинком?",a="Голос утверждает, что Нииру Огненный Клинок обрушится на Газз'уза с жестокой силой, если тот не отчитается. Внешне это представляет Нииру грозным верным исполнителем Тралла, однако близкое знакомство культа с Нииру намекает на скрытые течения.",al={"why mention neeru","neeru fireblade threat","neeru connection","почему упоминается нииру","угроза нииру огненного клинка","связь с нииру"}},{q="Куда отнести Око Пылающей Тени?",a="Отнесите кулон Нииру Огненному Клинку, которого можно найти склонившимся над котлами и фолиантами в глубине Расселины Теней в Оргриммаре.",al={"where to turn in burning shadows","where is neeru fireblade","куда сдать пылающие тени","где нииру огненный клинок"}},{q="Как реагирует Нииру Огненный Клинок, получив око?",a="Нииру делает вид, что ничего не знает, и изображает недоумение, что культисты используют его имя. Он берет кулон якобы изучить его магию и выяснить, почему у Пылающего Клинка имя так похоже на название его собственного клана.",al={"neeru reaction","what does neeru say","реакция нииру","что говорит нииру"}},{q="Где находится Газз'уз?",a="Газз'уз скрывается в самой глубокой части Скалы Черепа — пещеры среди скал на восточном побережье Дуротара, к востоку от Оргриммара.",al={"where is gazz'uz","gazz'uz location","skull rock boss","где газз'уз","местонахождение газз'уза","босс скала черепа"}}},fp="15,272,20.410.0,16.454.1,34.200.0,36.174.0,57.252.0,42.134.0,50.210.1,25.136.0"}
P.entries["quest:833"] = {n="Священное погребение",s="«Священное погребение» — задание, которое дает Сказитель Тотем Дождя. Оно поручает искателям приключений из Орды защитить Красные скалы на востоке Мулгора. Священные родовые захоронения заполонили грабящие свинобразы из племени Дыбогрив, оскверняющие могилы почтенных воинов-тауренов. Изгнав захватчиков, вы вернете честь и покой тем, кто отдал жизнь за основание и защиту Громового Утеса.",h="«Священное погребение» — задание, которое дает Сказитель Тотем Дождя.",kw={"a sacred burial","ancestors","bristleback interloper","lorekeeper raintotem","mulgore","quilboar","red rocks","thunder bluff","священное погребение","предки","дыбогривский захватчик","сказитель тотем дождя","мулгор","свинобраз","красные скалы","громовой утес"},ang={["class:Shaman"]="Осквернение священной земли тревожит духов почитаемых предков, поэтому ваше вмешательство необходимо, чтобы восстановить равновесие земли.",["faction:Horde"]="Помощь старейшинам тауренов в защите их священных памятников укрепляет обещание Орды защищать Мулгор вместе с союзниками.",["race:Tauren"]="Защита Красных скал — вопрос глубокой чести предков: воины, создавшие единый дом вашего народа, должны покоиться с миром."},sec={{t="Священная земля шу'хало",b="Красные скалы — одно из самых почитаемых святилищ всего Мулгора. Они укрыты в утесах под восточными горами и служат местом последнего упокоения исключительно для самых доблестных тауренов. Здесь погребены легендарные воины, проливавшие кровь, чтобы защитить свои племена, поддержать вождей и создать постоянный дом на мезах Громового Утеса. Для шу'хало потревожить их покой — оскорбление не только традиции, но и самой Матери-Земли."},{t="Осквернение Дыбогривов",b="Кочевые свинобразы племени Дыбогрив постоянно оспаривают власть тауренов над центральным Калимдором, но их недавний натиск на Красные скалы — тяжкая эскалация. Отряды дыбогривских захватчиков проникли на священную землю, разоряя почву и тревожа места упокоения. Сказитель Тотем Дождя, хранитель этих мест, слишком стар, чтобы в одиночку прогнать налетчиков, поэтому молодые герои Орды должны взяться за оружие, очистить это место от чужаков и защитить почитаемых мертвых."}},faq={{q="Что такое Красные скалы?",a="Красные скалы — священное родовое кладбище в восточных горах Мулгора. Оно предназначено специально для самых доблестных воинов-тауренов, особенно тех, кто погиб, защищая свои племена и основывая Громовой Утес.",al={"where is red rocks","red rocks mulgore","tauren burial ground","где красные скалы","красные скалы мулгор","погребальное место тауренов"}},{q="Кто такой Сказитель Тотем Дождя?",a="Сказитель Тотем Дождя — старейшина-таурен, на которого возложена забота о священной земле Красных скал и ее защита. Понимая, что его лучшие годы позади и в одиночку он не может отразить нападение Дыбогривов, он призывает способных искателей приключений защитить мертвых.",al={"raintotem","lorekeeper raintotem","who gives a sacred burial","тотем дождя","сказитель тотем дождя","кто дает священное погребение"}},{q="Почему свинобразы Дыбогрив оказались у Красных скал?",a="Племя Дыбогрив постоянно наступает на земли тауренов в Мулгоре и Степях. Нуждаясь в землях и ресурсах, отряды захватчиков проникли в утесы Красных скал и осквернили могилы.",al={"why are quilboar at red rocks","bristleback interlopers","quilboar invasion","почему свинобразы у красных скал","дыбогривские захватчики","вторжение свинобразов"}},{q="Почему это осквернение так оскорбляет тауренов?",a="Культура тауренов придает огромное значение почитанию предков и жизни в равновесии с духами павших. Позволить диким свинобразам разорять землю и тревожить кости героев, погибших за Громовой Утес, — глубокое духовное оскорбление.",al={"tauren funerary customs","why tauren care about burial","погребальные обычаи тауренов","почему тауренам важны захоронения"}},{q="Куда ведет это задание дальше?",a="«Священное погребение» — отдельное оборонительное задание от Сказителя Тотема Дождя. Когда с дыбогривскими захватчиками покончено, осквернение прекращается, хотя другие задания у Красных скал касаются духовного неспокойствия в утесах.",al={"sacred burial follow up","what comes after sacred burial","священное погребение продолжение","что после священного погребения"}},{q="Кто похоронен в Красных скалах?",a="Это место предназначено для героев-тауренов, сражавшихся за выживание своих племен и вождей, особенно тех, чьи жертвы сделали возможными основание и защиту Громового Утеса.",al={"who is buried here","red rocks graves","кто здесь похоронен","могилы красных скал"}}},fp="15,401,31.497.0,27.505.0,18.233.0,28.262.0,46.243.0,51.257.0,32.248.0,27.196.0"}
P.entries["quest:834"] = {n="Ветра пустыни",s="Резлак, инженер, нанятый по контракту Газлоу, просит помочь вернуть важные строительные материалы, украденные гарпиями в Дуротаре. Караван, направлявшийся в Оргриммар, попал в засаду в Каньоне Колючего Ветра, и мешки с припасами разбросало по скалам.",h="Резлак, инженер, нанятый по контракту Газлоу, просит помочь вернуть важные строительные материалы, украденные...",kw={"caravan","durotar","dustwind harpies","gazlowe","orgrimmar","ratchet","razorwind canyon","rezlak","supplies","караван","дуротар","гарпии пыльного ветра","газлоу","оргриммар","кабестан","каньон колючего ветра","резлак","припасы"},ang={["faction:Horde"]="Каждый груз, потерянный из-за тварей каньона, угрожает быстрому расширению и укреплению оплота Орды в Дуротаре.",["profession:Engineering"]="Резлак воплощает практичную изобретательность инженеров Картеля Хитрая Шестеренка, которых куда больше волнует соблюдение чертежей и сроков поставок, чем неприятности с местной живностью.",["race:Orc"]="Орки полагаются на опыт гоблинов и привозные припасы, чтобы превратить суровую сухую землю Дуротара в укрепленный дом."},sec={{t="Гоблин в цейтноте",b="Резлака прислал сам главный инженер Газлоу из Кабестана, чтобы помочь Орде в амбициозных стройках по всему Дуротару. Возводить укрепления на суровой, бесплодной земле и так нелегко, а тут еще логистические беды: грузы Резлака пропадают, не доходя до строек. Без нужных материалов работа встает, и раздражительный гоблин-прораб остается ни с чем."},{t="Засада в каньоне",b="Последний важный груз для Резлака перехватили гарпии Пыльного Ветра, обитающие в Каньоне Колючего Ветра. Эти крылатые падальщицы гнездятся на высоких обрывах оврагов вдоль дороги между Колючим Холмом и Оргриммаром и налетают на ничего не подозревающие повозки. Вместо того чтобы съесть или уничтожить груз, гарпии копят ящики и мешки возле гнезд, оставляя добычу целой для любого, кто осмелится пробиться на их территорию."}},faq={{q="Кто такой Резлак?",a="Резлак — рабочий-гоблин, нанятый Газлоу, боссом Кабестана. Газлоу отправил его в Дуротар помогать оркам с продолжающимся строительством у ворот Оргриммара.",al={"rezlak","who is rezlak","who gave this quest","резлак","кто такой резлак","кто дал это задание"}},{q="Почему гоблины помогают строить в Дуротаре?",a="Газлоу и Картель Хитрая Шестеренка связаны с вождем Траллом торговым и инженерным партнерством. Гоблины-инженеры и механизмы помогли заложить основы Оргриммара, а Газлоу по-прежнему поставляет Орде наемный труд и материалы.",al={"why are goblins helping orcs","gazlowe durotar","goblin horde cooperation","почему гоблины помогают оркам","газлоу дуротар","сотрудничество гоблинов и орды"}},{q="Откуда взялись припасы?",a="Резлак не называет, откуда пришла партия груза. Он говорит, что это был караван с припасами, нужными для его работы по помощи оркам в Дуротаре.",al={"where are the supplies from","caravan origin","откуда припасы","откуда караван"}},{q="Что гарпии делают в Дуротаре?",a="Гарпии Пыльного Ветра — агрессивные хищные падальщицы, наводнившие скалы и овраги центрального Дуротара. Они донимают путников, грабят торговые пути через Каньон Колючего Ветра и тащат в гнезда все яркое и полезное.",al={"why harpies in durotar","dustwind harpies lore","razorwind harpies","почему гарпии в дуротаре","гарпии пыльного ветра предания","гарпии колючего ветра"}},{q="Где находится Каньон Колючего Ветра?",a="Каньон Колючего Ветра ответвляется прямо от главного южного ущелья, соединяющего Оргриммар и Колючий Холм. Овраги прорезают восточные и западные скалы, образуя высокие гнездовья, где гарпии Пыльного Ветра прячут украденный груз.",al={"razorwind canyon location","where to find supplies","sacks of supplies location","где каньон колючего ветра","где найти припасы","где мешки с припасами"}},{q="Почему орки-стражи не защитили караван?",a="Резлак говорит, что караваны трудно уберечь и что эта партия должна была дойти до места. Он не объясняет, какая охрана ее сопровождала и почему защита не сработала против гарпий Пыльного Ветра.",al={"why failed caravan","durotar security","orc caravans","почему караван не защитили","безопасность дуротара","орочьи караваны"}}},fp="19,251,22.451.0,20.454.0,14.186.0,41.264.0,33.151.0,38.234.0,34.233.0,46.215.0"}
P.entries["quest:835"] = {n="Обеспечение безопасного сообщения",s="«Обеспечение безопасного сообщения» — задание, которое дает Резлак возле Каньона Колючего Ветра, чтобы защитить важные гоблинские торговые пути через Дуротар. Гарпии из Сухой лощины постоянно перехватывают и грабят караваны, и раздосадованный гоблин нанимает силачей, чтобы их выбить.",h="«Обеспечение безопасного сообщения» — задание, которое дает Резлак возле Каньона Колючего Ветра, чтобы...",kw={"drygulch ravine","dustwind savage","dustwind storm witch","gazlowe","ratchet","razorwind canyon","rezlak","securing the lines","сухая лощина","дикарка пыльного ветра","штормовая ведьма пыльного ветра","газлоу","кабестан","каньон колючего ветра","резлак","обеспечение безопасного сообщения"},ang={["faction:Horde"]="Уничтожение гарпий в восточной части Каньона Колючего Ветра сохраняет поток товаров и подкреплений между пограничными форпостами Дуротара и прибрежными торговыми центрами.",["profession:Engineering"]="Защита грузов Резлака позволяет передовым гоблинским деталям продолжать поступать из Кабестана к местным механикам."},sec={{t="Путь, измученный гарпиями",b="Сухие долины Дуротара и так суровы, даже без агрессивных гарпий, налетающих на ничего не подозревающих путников. Гоблин Резлак по поручению босса Газлоу следит за местными поставками. К несчастью, гарпии Пыльного Ветра из Сухой лощины превратили Каньон Колючего Ветра в опасное место: они регулярно грабят караваны и захватывают грузы, не давая им дойти до цели."},{t="Бизнес и кровопролитие",b="Резлак живет по гоблинскому правилу: все можно сделать, если цена подходящая. Вместо того чтобы самому идти в каньон, он нанимает искателей приключений, чтобы сломить гнездовье, перебив дикарок и штормовых ведьм Пыльного Ветра. Расчистка этих гарпий держит торговые пути открытыми, обеспечивает поставки инженерных устройств и направляет помощников к большим возможностям в Кабестане."}},faq={{q="На кого работает Резлак?",a="Резлак работает на Газлоу, главного инженера и босса нейтрального гоблинского портового города Кабестан. Газлоу руководит обширной торговлей и инфраструктурными проектами по всему Дуротару и Степям.",al={"rezlak boss","who does rezlak work for","rezlak employer","босс резлака","на кого работает резлак","наниматель резлака"}},{q="Почему гарпии нападают на караваны?",a="Гарпии Пыльного Ветра устроили крупное гнездовье в Сухой лощине, которая проходит вдоль главных путей Каньона Колючего Ветра. Они яростно нападают на любых чужаков и грабят проезжающие мимо повозки с товарами.",al={"why do harpies attack","dustwind harpies motive","why drygulch ravine","почему гарпии нападают","мотив гарпий пыльного ветра","почему сухая лощина"}},{q="Где находится Сухая лощина?",a="Сухая лощина лежит в глубине восточной части Каньона Колючего Ветра на севере Дуротара, вырезанная среди засушливых багровых холмов.",al={"drygulch ravine location","where is drygulch ravine","how to find drygulch","где сухая лощина","расположение сухой лощины","как найти сухую лощину"}},{q="Что будет после помощи Резлаку?",a="Когда гарпии Пыльного Ветра перебиты, а путь поставок обеспечен, Резлак отправляет искателей приключений в Кабестан, за границу в Степях, и советует найти Газлоу для новых выгодных контрактов.",al={"after securing the lines","rezlak follow up","what next after rezlak","обеспечение безопасного сообщения","продолжение резлака","что дальше после резлака"}},{q="Почему Орда сама не справляется с гарпиями вместо гоблинов?",a="Хотя Орда держит в Дуротаре форпосты, ее силы растянуты между кентаврами, свинобразами и нуждами самих поселений. Гоблины-торговцы вроде Резлака часто находят быстрее и дешевле нанять независимых искателей приключений для защиты своего частного дела.",al={"why goblins hiring","why isn't orgrimmar handling this","horde and harpies","почему гоблины нанимают","почему оргриммар не занимается этим","орда и гарпии"}},{q="Какие гарпии обитают в Сухой лощине?",a="Гнездовье в основном состоит из диких дикарок Пыльного Ветра, нападающих в ближнем бою, и штормовых ведьм Пыльного Ветра, повелевающих ветром и молниями против вторгшихся караванов.",al={"harpy types","dustwind harpy types","drygulch enemies","виды гарпий","виды гарпий пыльного ветра","враги сухой лощины"}}},fp="18,283,26.418.0,22.418.0,26.197.0,39.239.0,33.139.0,34.208.0,60.281.0,48.169.0"}
P.entries["quest:8353"] = {s="«Курочка с мятой» — веселое праздничное задание Альянса, которое выдают в Стальгорне во время Тыквовина. Чтобы получить традиционную Конфету Стальгорна для юного сироты Джеспера, искателям приключений приходится отбросить свое закаленное в боях достоинство и, махая руками, кудахтать как курица на потеху посетителям таверны. Хозяин таверны Огневар охотно награждает всякого, кто готов поступиться гордостью ради праздничной радости ребенка.",h="«Курочка с мятой» — веселое праздничное задание Альянса, которое выдают в Стальгорне во время Тыквовина.",kw={"chicken","cluck","firebrew","hallow's end","innkeeper","ironforge mint","jesper","treats","курица","кудахтать","огневар","тыквовин","хозяин таверны","конфета стальгорна","джеспер","угощения"},ang={["faction:Alliance"]="Это праздничное поручение подчеркивает дружбу столиц Альянса: гостеприимство дворфов Стальгорна напрямую связано с заботой о ребенке-сироте в Штормграде.",["race:Dwarf"]="Дворфы ценят хороший юмор, крепкие напитки и праздничные обычаи, а требование Огневара показывает, что ни один посетитель Стальгорна не относится к себе слишком серьезно."},sec={{t="Тыквовинская традиция",b="Во время Тыквовина по всему Азероту царит веселье: люди отмечают рубеж между осенним урожаем и зимой карнавальными нарядами и сезонными угощениями. Бывалым героям обычно уже не к лицу ходить от двери к двери за сладостями, но беда больных или осиротевших детей служит благородным оправданием. В Штормграде юный Джеспер мечтает о праздничных сладостях, и приезжие защитники Альянса собирают знаменитые местные лакомства у хозяев таверн в столицах Альянса."},{t="Плата Хозяина таверны Огневара",b="За стойкой шумной таверны Стальгорна стоит Хозяин таверны Огневар, хранитель знаменитых Конфет Стальгорна. Он не из тех, кто легко отпускает искателей приключений: просто так конфету не отдаст. Он требует развлечения: закаленные воины и суровые чародеи должны махать руками и квохтать, как домашняя птица, прежде чем получат награду. Все это ради праздничного веселья, чтобы посетители таверны вволю посмеялись за счет героя."}},faq={{q="Почему Хозяин таверны Огневар хочет, чтобы я кудахтал как курица?",a="Хозяин таверны Огневар поддерживает игривый дух Тыквовина. Поскольку бывалые искатели приключений слишком стары, чтобы просить сладости как положено, он требует забавного трюка, прежде чем расстаться с угощением. Считая, что зрелище могучего героя, машущего руками и кудахчущего, — хорошее развлечение для таверны, он охотно обменивает Конфету Стальгорна на небольшое публичное унижение.",al={"why chicken cluck","firebrew chicken reason","why do i have to cluck","почему кудахтать","огневар курица зачем","зачем кудахтать"}},{q="Кто такой Джеспер и зачем мне собирать для него конфеты?",a="Джеспер — больной сирота, живущий в Штормграде и не способный сам участвовать в городских празднествах Тыквовина. Чтобы порадовать его, приключенцы Альянса выполняют праздничные поручения по всему миру и собирают четыре особых праздничных угощения в каждой крупной столице Альянса, включая хрустящую Конфету Стальгорна из Дун Морога.",al={"who is jesper","why get mints","jesper orphan","кто такой джеспер","зачем собирать конфеты","джеспер сирота"}},{q="Какое место это задание занимает в Тыквовине?",a="Это задание — одно из четырех региональных поручений, входящих в общее праздничное задание «Тыквовинские вкусности для Джеспера!», наряду с просьбами хозяев таверн Штормграда и Дарнасса и Талваша де Кисселя в Стальгорне. Каждый из них требует особого смешного или театрального жеста, прежде чем отдать фирменную сладость своего города.",al={"hallows end chain","jesper candy questline","quest order","цепочка тыквовина","задания джеспера конфеты","порядок заданий"}},{q="Где найти Хозяина таверны Огневара?",a="Хозяин таверны Огневар стоит за стойкой у очага в таверне «Каменный огонь» в Общинном квартале Стальгорна: он подает напитки и принимает постояльцев в самом сердце столицы дворфов.",al={"where is firebrew","firebrew location","ironforge innkeeper","где огневар","местонахождение огневара","трактирщик стальгорна"}},{q="Что я получу за кудахтанье?",a="Когда вы покудахчете, Хозяин таверны Огневар вручит вам Конфету Стальгорна — праздничное лакомство, доступное только во время события. Ее нужно отнести в Штормград, чтобы завершить набор тыквовинских угощений для Джеспера.",al={"quest reward","what is the mint","ironforge mint","награда за задание","что за конфета","конфета стальгорна"}},{q="Могут ли игроки Орды выполнить это задание?",a="Нет, это задание только для Альянса. У искателей приключений Орды есть свой аналог — сирота Спупс, который отправляет героев по столицам Орды за лакомствами к хозяевам таверн Оргриммара, Подгорода и Громового Утеса.",al={"is this alliance only","horde chicken quest","can horde do this","только ли для альянса","курица орда задание","может ли орда это сделать"}}},fp="27,441,24.481.0,26.479.0,60.373.0,49.311.0,56.337.0,36.186.0,31.185.0,37.240.0"}
P.entries["quest:8354"] = {n="Курочка с мятой",s="Во время праздничного Тыквовина Хозяин таверны Норман из Подгорода предлагает конфету путникам, помогающим больному ребенку. Чтобы получить Конфету Подгорода, искателям приключений нужно отбросить достоинство и замахать руками, как курица.",h="Во время праздничного Тыквовина Хозяин таверны Норман из Подгорода предлагает конфету путникам, помогающим...",kw={"chicken","cluck","hallow's end","innkeeper norman","spoops","trade quarter","undercity","undercity mint","курица","кудахтать","тыквовин","хозяин таверны норман","спупс","торговый квартал","подгород","конфета подгорода"},ang={["faction:Horde"]="Искатели приключений Орды в Тыквовин путешествуют по всем столицам, храбро переносят нелепые унижения в каждой из них, чтобы порадовать ребенка-сироту.",["race:Undead"]="Найти глупый юмор в гниющих залах Подгорода непросто, поэтому требование Нормана становится странным отдыхом от повседневного некромантского прагматизма."},sec={{t="Редкая капля веселья",b="Подгород редко славится смехом и теплом: его построили под руинами Лордерона освободившиеся Отрекшиеся. Но с приходом Тыквовина даже мрачные жители Торгового квартала присоединяются к празднику. Хозяин таверны Норман хранит запас Конфет Подгорода для тех, кто собирает угощения для юного Спупса, больного сироты, нуждающегося в праздничной радости."},{t="Как заслужить угощение",b="Вместо того чтобы просто отдать угощение бывалым искателям приключений, Норман требует унизительного зрелища. Считая, что взрослые воины и чародеи должны заслужить свои лакомства, он не отдает конфету, пока проситель не изобразит домашнюю курицу прямо перед его стойкой."}},faq={{q="Почему Хозяин таверны Норман хочет, чтобы я кудахтал как курица?",a="Хозяин таверны Норман считает, что взрослые герои слишком стары, чтобы просить сладости без представления. Чтобы поднять настроение в Тыквовин, он требует нелепого выступления — махать руками и кудахтать, как курица, — прежде чем отдаст праздничное угощение.",al={"why chicken emote","why cluck norman","norman chicken dance","почему курица","зачем кудахтать норману","норман куриный танец"}},{q="Для кого предназначено угощение?",a="Конфету Подгорода собирают для Спупса, больного сироты, который лежит в Оргриммаре и не может сам ходить за угощениями во время праздника Тыквовин.",al={"who gets the mint","what is the mint for","why get undercity mint","кому конфета","для чего конфета","зачем конфета подгорода"}},{q="Где находится Хозяин таверны Норман?",a="Хозяин таверны Норман держит главную таверну в Торговом квартале Подгорода, где обслуживает Отрекшихся и приезжих путников Орды.",al={"norman location","where is undercity innkeeper","где норман","местонахождение нормана","где трактирщик подгорода"}},{q="Это сезонное праздничное задание?",a="Да. Это задание — часть ежегодных празднований Тыквовина, которые отмечают по всему Азероту и Орда, и Альянс.",al={"is this hallows end","when is this quest available","это тыквовин","когда доступно задание"}},{q="Отмечают ли Отрекшиеся Тыквовин?",a="Отрекшиеся отмечают Тыквовин с большим энтузиазмом: они сжигают огромное плетеное чучело у руин Лордерона в память о своем освобождении и разрыве с прежней смертной жизнью.",al={"forsaken hallows end","undead holiday","отрекшиеся тыквовин","праздник нежити"}},{q="Что происходит после получения Конфеты Подгорода?",a="Конфету соединяют с другими фирменными угощениями, собранными в столицах рас Орды, чтобы составить полный праздничный подарок для юного Спупса.",al={"next quest","what do i do with the mint","следующее задание","что делать с конфетой"}}},fp="27,239,19.389.0,17.301.0,58.273.0,30.167.0,34.142.0,34.125.0,44.192.0,46.146.0"}
P.entries["quest:8355"] = {n="Плата за леденцы",s="«Плата за леденцы» — сезонное задание Тыквовина в Стальгорне, которое выдает гном-ремесленник Талваш де Киссель. Чтобы получить праздничное угощение для больного ребенка в Штормграде, искателям приключений нужно сначала изобразить для восхищенного гнома поезд.",h="«Плата за леденцы» — сезонное задание Тыквовина в Стальгорне, которое выдает гном-ремесленник Талваш де...",kw={"gnomeregan gumdrop","hallow's end","incoming gumdrop","ironforge","jesper","talvash del kissel","tinker town","train emote","леденец гномрегана","тыквовин","плата за леденцы","стальгорн","джеспер","талваш де киссель","город механиков","жест поезда"},ang={["faction:Alliance"]="Погоня за праздничным леденцом отправляет героев Альянса по королевствам, чтобы больной ребенок в Штормграде тоже встретил праздник.",["race:Gnome"]="Для изгнанных гномов Города механиков леденец Гномрегана в Тыквовин — радостное напоминание о доме и механической изобретательности в годы изгнания."},sec={{t="Забавная плата",b="Во время осеннего праздника Тыквовин любители сладостей обходят главные оплоты Альянса, собирая особые местные лакомства. В Мистическом квартале Стальгорна гном Талваш де Киссель хранит желанный Леденец Гномрегана. Хотя он сочувствует юному сироте, который мечтает о нем, Талваш настаивает на праздничном духе озорства и требует убедительно изобразить поезд от каждого, кто просит угощение."},{t="Праздничная благотворительность",b="Это задание — часть большого праздничного дела, цель которого — порадовать Джеспера, больного сироту из Штормграда. Джеспер мечтает о четырех угощениях из земель Альянса: нуге из Штормграда, конфете из Стальгорна, кусочке марципана из Дарнасса и леденце из Гномрегана. Изображая пыхтящий паровоз для Талваша, герои получают гномье лакомство и исполняют праздничное желание мальчика."}},faq={{q="Что нужно сделать, чтобы выполнить «Плату за леденцы»?",a="Вам нужно изобразить поезд для Талваша де Кисселя: выберите его целью и используйте жест поезда. Услышав гудок, он охотно отдаст Леденец Гномрегана.",al={"how to do incoming gumdrop","incoming gumdrop objective","talvash gumdrop trick","как выполнить плату за леденцы","цель платы за леденцы","трюк талваша леденец"}},{q="Кто такой Талваш де Киссель?",a="Талваш де Киссель — гном-ювелир из Гномрегана, живущий в Мистическом квартале горного города дворфов Стальгорна. Во время Тыквовина он раздает от имени Альянса фирменные леденцы Гномрегана.",al={"who is talvash","talvash del kissel lore","кто такой талваш","талваш де киссель предания"}},{q="Для чего нужен Леденец Гномрегана?",a="Леденец Гномрегана — одно из четырех праздничных лакомств, собираемых для исполнения тыквовинской просьбы Джеспера, мальчика-сироты из приюта Штормграда.",al={"gnomeregan gumdrop purpose","what is the gumdrop for","назначение леденца гномрегана","для чего леденец"}},{q="Где найти Талваша де Кисселя?",a="Талваша можно найти в Мистическом квартале Стальгорна.",al={"where is talvash","talvash location","где талваш","местонахождение талваша"}},{q="Почему Талваш заставляет изображать поезд?",a="Тыквовин уходит корнями в традицию «сладость или гадость». Талваш в шутку требует безобидного трюка — изобразить паровоз, — прежде чем отдаст праздничное угощение.",al={"why train noise","why do train for talvash","почему звук поезда","зачем изображать поезд талвашу"}},{q="Доступно ли это задание круглый год?",a="Нет, это задание доступно только во время ежегодного осеннего праздника Тыквовин.",al={"can i do incoming gumdrop anytime","is this seasonal","можно ли плата за леденцы в любое время","сезонное ли это"}}},fp="16,265,16.467.0,15.447.0,50.184.0,26.222.0,40.177.0,38.53.0,42.185.0,35.83.0"}
P.entries["quest:8356"] = {n="Поиграй мускулами!",s="Во время осеннего праздника Тыквовин путешественники в Штормграде могут помочь местному сироте собрать праздничные сладости. Чтобы получить Нугу из Штормграда у Хозяйки таверны Аллисон в «Позолоченной розе», гостям в шутку предлагают принять могучую позу силача.",h="Во время осеннего праздника Тыквовин путешественники в Штормграде могут помочь местному сироте собрать...",kw={"flexing for nougat","gilded rose","hallow's end","innkeeper allison","jesper","stormwind city","stormwind nougat","trick or treat","поиграй мускулами","позолоченная роза","тыквовин","хозяйка таверны аллисон","джеспер","штормград","нуга из штормграда","сладость или гадость"},ang={["class:Warrior"]="Для крепких воинов, привыкших к кровавым полям сражений, показать мускулы по просьбе хозяйки таверны — безобидная, хотя и слегка недостойная демонстрация силы.",["faction:Alliance"]="Эта шутливая игра подчеркивает легкий общинный дух, который расцветает в Штормграде на праздниках вроде Тыквовина и собирает горожан и странствующих героев вместе для доброго смеха.",["race:Human"]="Для людей Штормграда баловать детей и обменивать проделки на угощения — любимый сезонный обычай, дающий недолгую передышку от мрачных опасностей, нависших над королевством."},sec={{t="Тыквовинская традиция",b="Тыквовин приносит на улицы Штормграда редкую легкость. Древние корни праздника связаны со сменой времен года и отпугиванием темных духов, но простой люд отмечает его переодеваниями, весельем и хождением за сладостями. Хозяева таверн по всему Альянсу участвуют, раздавая традиционные лакомства тем, кто готов показать безобидный трюк."},{t="Развлечь хозяйку таверны",b="В «Позолоченной розе» в оживленном Торговом квартале Хозяйка таверны Аллисон следит, чтобы никто не получал праздничные сладости даром — даже выполняя поручение для мальчика-сироты вроде Джеспера. Разглядывая доспехи или одежду искателя приключений, Аллисон в шутку комментирует его сложение и требует показать мускулы ей на потеху. Лишь когда герой продемонстрирует силу, она награждает его кусочком тягучей Нуги из Штормграда."}},faq={{q="Почему Хозяйка таверны Аллисон заставляет играть мускулами?",a="Тыквовин построен на традиции «сладость или гадость». Поскольку искатель приключений пришел от имени сироты, который ищет сладости, Хозяйка таверны Аллисон требует заслужить лакомство забавным трюком — показать мускулы.",al={"why flex for nougat","what does allison want","flex emote why","почему играть мускулами за нугу","чего хочет аллисон","зачем жест силы"}},{q="Где происходит это задание?",a="Просьба выдается и выполняется целиком в гостинице «Позолоченная роза» в самом сердце Торгового квартала Штормграда, где за стойкой стоит Хозяйка таверны Аллисон.",al={"where is flexing for nougat","allison location","gilded rose innkeeper","где поиграй мускулами","местонахождение аллисон","трактирщица позолоченной розы"}},{q="Для кого предназначена Нуга из Штормграда?",a="Нуга предназначена для Джеспера, мальчика-сироты, живущего в Штормграде. Он надеется попробовать традиционные праздничные угощения из каждой крупной столицы Альянса во время Тыквовина.",al={"who gets the nougat","who wants stormwind nougat","jesper candy","кому нуга","кто хочет нугу из штормграда","конфеты джеспера"}},{q="Что такое Нуга из Штормграда?",a="Нуга из Штормграда — местное лакомство, которое раздают хозяева таверн Штормграда во время Тыквовина. Среди гуляющих на празднике она известна как одна из характерных сладостей королевства людей.",al={"stormwind nougat lore","hallow's end nougat","stormwind candy","нуга из штормграда предания","нуга тыквовина","конфеты штормграда"}},{q="Могут ли игроки Орды получить это угощение у Аллисон?",a="Нет. Хозяйка таверны Аллисон живет в глубине подконтрольного Альянсу Штормграда и обслуживает только членов Альянса. Искатели приключений Орды устраивают свои праздничные проделки для хозяев таверн в собственных столицах.",al={"can horde flex for nougat","horde version of nougat","может ли орда играть мускулами за нугу","нуга для орды"}},{q="Выполняется ли это задание круглый год?",a="Нет. Хозяйка таверны Аллисон предлагает это задание только во время сезонного праздника Тыквовин, когда в городах воцаряются обычаи «сладость или гадость».",al={"when is flexing for nougat available","is this quest seasonal","hallows end timing","когда доступно поиграй мускулами","сезонное ли задание","время тыквовина"}}},fp="18,302,24.432.0,26.460.0,44.253.0,33.173.0,38.167.0,25.184.0,49.208.0,34.145.0"}
P.entries["quest:8357"] = {n="Танец за марципан",s="Во время праздничного сезона Тыквовина путешественников, проходящих через Дарнасс, просят собрать праздничные сладости для больного сироты в Штормграде. Хозяйка таверны Салиенна полностью соблюдает традицию «сладость или гадость» и требует спонтанного танцевального выступления, прежде чем расстанется со своим драгоценным дарнасским марципаном.",h="Во время праздничного сезона Тыквовина путешественников, проходящих через Дарнасс, просят собрать праздничные...",kw={"dance","darnassus","hallow's end","innkeeper","jesper","marzipan","saelienne","teldrassil","танец","дарнасс","тыквовин","хозяйка таверны","джеспер","марципан","салиенна","тельдрассил"},ang={["faction:Alliance"]="Это праздничное поручение показывает единство и непринужденное товарищество столиц Альянса: угощения из далекого Тельдрассила доходят до маленького сироты в Штормграде.",["race:NightElf"]="Для ночных эльфов участие в Тыквовине — милое перенимание сезонных обычаев Альянса, сочетающее их безмятежную лесную жизнь с игривым весельем."},sec={{t="Соблюдение традиции",b="Даже в священном лесном городе Дарнасс веселье Тыквовина приносит долгоживущим ночным эльфам легкость на душе. Когда путники приходят собрать праздничные лакомства для Джеспера, больного ребенка, который поправляется в Штормграде, хозяйка таверны Салиенна настаивает, что правила праздника нарушать нельзя. Благотворительность или нет, но за угощение сначала нужно сыграть шутку."},{t="Цена марципана",b="Чтобы получить нежный дарнасский марципан, путникам приходится забыть о своей степенности и устроить представление прямо в зале таверны. Салиенна требует не меньше чем танец и охотно награждает тех, кто готов отбросить гордость и проникнуться праздничным весельем, лакомством, нужным для праздничной посылки через континенты."}},faq={{q="В чем смысл задания «Танец за марципан»?",a="Задание входит в сезонные праздничные события Альянса на Тыквовин. Вы танцуете для хозяйки таверны Салиенны в Дарнассе, чтобы получить дарнасский марципан — одно из нескольких праздничных угощений, нужных, чтобы развеселить больного сироту по имени Джеспер в Штормграде.",al={"why dance for marzipan","what is this quest","marzipan quest","зачем танцевать за марципан","что это за задание","задание марципан"}},{q="Кто такая хозяйка таверны Салиенна?",a="Хозяйка таверны Салиенна управляет таверной в Дарнассе, предлагая приют и отдых путникам под ветвями Тельдрассила. Во время Тыквовина она следит за раздачей местных праздничных лакомств тем, кто готов поддержать традицию.",al={"who is saelienne","saelienne lore","кто такая салиенна","салиенна предания"}},{q="Почему Салиенна настаивает на танце?",a="Салиенна строго придерживается духа Тыквовина. Хотя угощение предназначено больному ребенку, она твердо хранит обычай «сладость или гадость» и в шутку требует показать танцевальное мастерство как «гадость» прежде, чем отдаст сладость.",al={"why dance","why does saelienne want me to dance","почему танцевать","почему салиенна хочет чтобы я танцевал"}},{q="Куда попадает марципан дальше?",a="Полученный дарнасский марципан присоединяют к праздничным сладостям из таверн Стальгорна и Штормграда и от Талваша де Кисселя в Стальгорне, чтобы выполнить задание и подарить праздничную радость маленькому Джесперу в Штормграде.",al={"who gets the marzipan","what to do with marzipan","кому марципан","что делать с марципаном"}},{q="Что такое дарнасский марципан?",a="Darnassus Marzipan is a sugary confection crafted in the night elven capital. It serves as Darnassus's signature festive treat for visiting trick-or-treaters during Hallow's End.",al={"darnassus marzipan lore","what kind of candy is it","дарнасский марципан предания","что это за конфета"}},{q="Могут ли игроки Орды выполнить это задание?",a="Нет. «Танец за марципан» — сезонное задание только для Альянса. Дарнасс — оплот Альянса, а марципан собирают именно для сироты Альянса, поправляющегося в Штормграде.",al={"is this quest alliance only","horde marzipan quest","только ли для альянса","марципан орда задание"}}},fp="20,314,18.375.0,21.343.0,44.247.0,27.253.0,37.261.0,38.238.0,27.178.0,38.194.0"}
P.entries["quest:8359"] = {n="Поиграй мускулами!",s="Во время праздничного осеннего торжества Тыквовина хозяйка таверны Гришка в Оргриммаре предлагает сладкие сезонные лакомства тем, кто готов подыграть. Чтобы получить кусочек нуги из Оргриммара для прикованного к постели ребенка, защитникам Орды придется забыть воинскую гордость и по команде показать мускулы.",h="Во время праздничного осеннего торжества Тыквовина хозяйка таверны Гришка в Оргриммаре предлагает сладкие...",kw={"candy","flexing","gryshka","hallow's end","nougat","orgrimmar","spoops","trick or treat","конфеты","поиграй мускулами","гришка","тыквовин","нуга","оргриммар","спупс","сладость или гадость"},ang={["class:Warrior"]="Воинам, гордящимся сокрушительными подвигами на передовой, может показаться забавным или слегка унизительным позировать, как артисты на сцене, ради кусочка праздничной сладости.",["faction:Horde"]="Даже ветераны, смотревшие в лицо смертоносным полководцам, вынуждены напрягать бицепсы перед хозяевами таверн, чтобы собрать праздничные сладости для детей Орды.",["race:Orc"]="Хозяйка таверны Оргриммара ждет впечатляющей демонстрации мускулов — истинного орочьего испытания гордости, превращенного в шутливое праздничное представление."},sec={{t="Шутки за угощения",b="Тыквовин приносит в шумные столицы Азерота веселье, розыгрыши и сбор лакомств. Хотя герои часто сражаются с драконами и темным колдовством, традиции осеннего праздника требуют куда более легкого подхода. Хозяйка таверны Гришка, заправляющая общим залом оргриммарской таверны, охотно делится запасом праздничных сладостей, но только если посетители следуют древнейшему правилу праздника: сыграй шутку или уходи с пустыми руками."},{t="Мускулы напоказ",b="Забавляясь любым нарядом или доспехом, в которых является путник, Гришка требует показать подлинную орочью силу. Прежде чем расстаться с хоть одним кусочком нуги из Оргриммара, предназначенной маленькому Спупсу, она настаивает, чтобы могучий гость принял мускулистую позу. Это шутливое напоминание, что даже самых грозных бойцов Орды можно заставить развлекать простой народ ради конфеты."}},faq={{q="Кто просит поиграть мускулами?",a="Хозяйка таверны Гришка, владелица главной таверны в Аллее Силы в Оргриммаре, требует шутку, прежде чем отдать свои праздничные сладости.",al={"who gives the quest","gryshka","innkeeper gryshka","кто дает задание","гришка","хозяйка таверны гришка"}},{q="Зачем играть мускулами ради конфеты?",a="Обычай Тыквовина требует, чтобы за угощение просящие исполняли небольшую шутку. Гришка решает подразнить путника, попросив показать чистую физическую силу, прежде чем наградить его.",al={"why flex","what is the trick","nougat condition","зачем мускулы","какая шутка","условие нуги"}},{q="Для чего нужна нуга из Оргриммара?",a="Нуга — одна из четырех разных сладостей, собираемых по столицам Орды, чтобы подбодрить Спупса, больного мальчика-сироту, который не может сам ходить за угощениями.",al={"why do i need nougat","nougat use","spoops candy","зачем нужна нуга","для чего нуга","конфеты для спупса"}},{q="Где живет хозяйка таверны Гришка?",a="Ее можно найти за стойкой главной таверны в Аллее Силы в Оргриммаре, где она обслуживает и усталых путников, и местных.",al={"where is gryshka","orgrimmar innkeeper location","где гришка","где хозяйка таверны оргриммара"}},{q="Может ли участвовать любой член Орды?",a="Да, любой член Орды может в Тыквовин зайти к хозяйке таверны Гришке, принять позу и получить сезонное лакомство.",al={"who can flex","faction restrictions","horde only","кто может","ограничения по фракции","только орда"}},{q="Частью какого праздника это является?",a="Это поручение — часть Тыквовина, осеннего праздника, отмечающего конец жатвы и непокорность смерти с помощью костюмов, розыгрышей и сладостей.",al={"which event","what holiday","hallows end quest","какое событие","какой праздник","задание тыквовина"}}},fp="18,305,17.451.0,17.396.0,27.154.0,32.213.0,38.159.0,36.136.0,41.128.0,31.155.0"}
P.entries["quest:8360"] = {n="Танец за марципан",s="«Танец за марципан» — праздничное задание Тыквовина, которое выдает хозяйка таверны Пала в Громовом Утесе. Чтобы собрать сладкое угощение для больного сироты, путникам нужно забыть о закаленном в боях достоинстве и исполнить для хозяйки радостный танец. Задание показывает игривый, общинный дух праздника даже на продуваемых ветрами плато Мулгора.",h="«Танец за марципан» — праздничное задание Тыквовина, которое выдает хозяйка таверны Пала в Громовом Утесе.",kw={"dancing for marzipan","hallow's end","innkeeper pala","marzipan","mulgore","thunder bluff","trick-or-treat","танец за марципан","тыквовин","хозяйка таверны пала","марципан","мулгор","громовой утес","сладость или гадость"},ang={["faction:Horde"]="Светлый миг в суровых буднях Орды, показывающий сердце фракции: путники ходят по столицам, чтобы подарить сироте праздничную радость.",["race:Tauren"]="Хозяйка таверны Пала приносит традиционное праздничное веселье прямо в Мулгор, доказывая, что даже величавые, сдержанные таурены любят хороший танец ради сладкого дела."},sec={{t="Танец на утесе",b="Во время осеннего праздника Тыквовин настроение поднимается по всему Азероту, даже на безмятежных высотах Громового Утеса. Хозяйка таверны Пала, ведающая гостеприимством высоких плато, проникается праздничным духом и требует шутку, прежде чем раздавать угощения. Даже когда путник пришел ради больного ребенка, традиция неколебима: Пала настаивает на праздничном танце, прежде чем расстанется со своим драгоценным марципаном Громового Утеса."},{t="Шутки за угощения",b="Праздничный обычай обменивать забаву на лакомства раскрывает редкую, легкую сторону культуры Орды. От просьбы Палы требуется лишь выйти вперед, стряхнуть дорожную усталость и показать лучшие движения. Оставшись вполне довольной, хозяйка таверны охотно отдает марципан и передает теплые пожелания больному юнцу, ждущему угощения."}},faq={{q="В чем смысл задания «Танец за марципан»?",a="В задании нужно исполнить танец для хозяйки таверны Палы в Громовом Утесе. В награду она дает кусочек марципана Громового Утеса — часть более широкого набора праздничных угощений, собираемых для больного сироты на Тыквовин.",al={"why dance for marzipan","marzipan quest goal","dancing for marzipan objective","зачем танцевать за марципан","цель задания марципан","цель танец за марципан"}},{q="Кто выдает это задание?",a="Хозяйка таверны Пала, таурен, обслуживающая гостей и местных в Громовом Утесе, выдает это задание во время праздника Тыквовин.",al={"who starts dancing for marzipan","pala quest","innkeeper pala thunder bluff","кто дает танец за марципан","задание палы","хозяйка таверны пала громовой утес"}},{q="Почему Пала настаивает на танце, если конфета для больного ребенка?",a="Пала подчеркивает, что праздничные традиции нужно уважать даже ради благородных дел. В духе «сладости или гадости» нужно сыграть шутку, чтобы заслужить сладкую награду, и тогда Тыквовин остается радостным и живым.",al={"why do i have to dance","why does pala want a dance","почему я должен танцевать","почему пала хочет танец"}},{q="Какую награду получаешь за танец?",a="Вы получаете кусочек марципана Громового Утеса — местного праздничного лакомства, нужного, чтобы завершить общий набор угощений Тыквовина для больного ребенка.",al={"marzipan reward","dancing for marzipan item","награда марципан","предмет танец за марципан"}},{q="Могут ли игроки Альянса выполнить это задание?",a="Нет. Хозяйка таверны Пала — торговка Орды, живущая в самом сердце Громового Утеса, поэтому эта остановка в сборе праздничных угощений доступна только членам Орды.",al={"is this horde only","alliance dancing for marzipan","только ли для орды","альянс танец за марципан"}},{q="Когда доступно это задание?",a="Это задание доступно только во время ежегодного осеннего праздника Тыквовин, когда хозяева таверн по всему Азероту предлагают особые сладости и праздничные игры.",al={"when can i get marzipan","hallows end marzipan quest","когда получить марципан","задание марципан тыквовин"}}},fp="20,356,20.447.0,17.386.0,44.250.0,21.137.0,65.223.0,39.160.0,41.168.0,29.156.0"}
P.entries["quest:84"] = {n="Назад к Билли",s="«Назад к Билли» — один из эпизодов затяжной вражды семей Стоунфилдов и Маклюров в центре Элвиннского леса. Собрав ингредиенты для пирога со свининой, вы относите свежеиспеченное блюдо юному Билли Маклюру, чтобы выведать у него сведения о пропавшем ожерелье Бернис Стоунфилд.",h="«Назад к Билли» — один из эпизодов затяжной вражды семей Стоунфилдов и Маклюров в центре Элвиннского леса.",kw={"back to billy","bernice stonefield","billy maclure","elwynn forest","maclure vineyards","pork belly pie","stonefield farm","stonefield necklace","назад к билли","бернис стоунфилд","билли маклюр","элвиннский лес","виноградники маклура","пирог со свининой","ферма стоунфилдов","ожерелье стоунфилдов"},ang={["faction:Alliance"]="Даже в мирном Элвиннском лесу хватает будничных споров; разбираться со ссорами человеческих усадеб — обычное дело для путников, помогающих местным жителям.",["profession:Cooking"]="Пирог со свининой — типичное домашнее блюдо Элвиннской глубинки, приготовленное из мяса диких кабанов, бродящих по лесу."},sec={{t="Горький пирог",b="Вековая ссора Стоунфилдов и Маклюров почти не оставляет места добрососедству. Тетушка Бернис Стоунфилд неохотно испекла пирог со свининой лишь потому, что юный Билли Маклюр отказался рассказать, что ему известно о ее семейной реликвии, пока не получит угощение. Протягивая теплую выпечку, она открыто выражает раздражение и просит посыльного передать мальчишке Маклюров, что надеется, что он подавится каждым куском."},{t="Взятка мальчишки",b="Через дорогу, на Виноградниках Маклура, Билли Маклюр ждет с пустым животом и очень кстати подвела его память. Эта сцена показывает упрямую мелочность, разделяющую две усадьбы, где даже дети учатся выменивать сплетни и украденные безделушки на деревенские лакомства. Когда пирог доставлен, память Билли столь же кстати проясняется, и начинаются поиски настоящего места, где лежит ожерелье."}},faq={{q="Зачем нужно доставить этот пирог?",a="Билли Маклюр заявил, что знает, где находится потерянное ожерелье тетушки Бернис Стоунфилд, но отказался говорить, пока ему не дадут домашний пирог со свининой. Доставив пирог, вы выполняете его требование, и он расскажет, куда делась реликвия.",al={"why deliver pie","what does billy want","back to billy goal","зачем доставлять пирог","чего хочет билли","цель назад к билли"}},{q="Почему тетушка Бернис так сердита на Билли?",a="Семьи Стоунфилдов и Маклюров уже много лет находятся в ожесточенной деревенской вражде. Бернис возмущена тем, что должна печь угощение для несносного ребенка Маклюров только ради того, чтобы вернуть реликвию, пропавшую на границе их владений.",al={"why does bernice hate billy","stonefield maclure fight","why tell him to choke","почему бернис ненавидит билли","вражда стоунфилдов и маклюров","почему пожелала подавиться"}},{q="Где, по словам Билли, на самом деле находится ожерелье?",a="Расправившись с пирогом, Билли признается, что ожерелье у него не осталось. Оно попало в руки Фикса, пресловутого кобольда, обитающего в Руднике Подземных Глубин.",al={"where is the necklace","who took the necklace","goldtooth connection","где ожерелье","кто взял ожерелье","фикс"}},{q="Где находится Билли Маклюр?",a="Билли Маклюр находится на Виноградниках Маклура, к югу от дороги в центре Элвиннского леса, напротив Фермы Стоунфилдов.",al={"billy maclure location","where is billy","find billy","где билли маклюр","где найти билли","местонахождение билли"}},{q="Кто испек пирог со свининой?",a="Тетушка Бернис Стоунфилд испекла пирог на Ферме Стоунфилдов после того, как вы собрали свежие куски мяса кабана в окрестных землях.",al={"who made the pie","pie cook","кто испек пирог","пирог повар"}},{q="Положит ли это задание конец вражде между семьями?",a="Нет. Доставка пирога лишь удовлетворяет личную взятку Билли. Глубокая неприязнь между взрослыми Стоунфилдами и Маклюрами остается такой же жгучей, как прежде.",al={"does the feud end","stonefield maclure peace","закончится ли вражда","мир стоунфилдов и маклюров"}}},fp="13,296,12.426.0,13.394.1,37.233.0,42.221.0,46.169.1,31.129.0,29.138.0,54.157.0"}
P.entries["quest:840"] = {n="Новобранец Орды",s="«Новобранец Орды» — вводное задание-переход, направляющее молодых искателей приключений Орды из Дуротара в обширные просторы Степей. Его выдает разведчик Такрин Торитель Путей на западной дороге от Колючего Холма, и оно отправляет новобранцев через реку Строптивую к пограничной заставе Каргала Боевого Шрама.",h="«Новобранец Орды» — вводное задание-переход, направляющее молодых искателей приключений Орды из Дуротара в...",kw={"barrens","conscript of the horde","crossroads","kargal battlescar","razor hill","recruitment letter","southfury river","takrin pathseeker","степи","новобранец орды","перекресток","каргал боевой шрам","колючий холм","рекрутское письмо","река строптивая","такрин торитель путей"},ang={["faction:Horde"]="Этот призыв отмечает превращение воина из местного защитника Дуротара в признанного защитника более широких земель Орды по всему Калимдору.",["race:Orc"]="Для молодых орков, покидающих тренировочные земли Долины Испытаний и Колючего Холма, ответ на зов Каргала Боевого Шрама — важный обряд посвящения в службу Вождю.",["race:Troll"]="Тролли Черного Копья, сражающиеся бок о бок с союзниками-орками, используют это назначение, чтобы помочь расширению Орды и обезопасить земли у Великого моря."},sec={{t="Переправа через Строптивую",b="Когда будущий воин Орды доказывает свою силу у Колючего Холма, нужды всего народа зовут его на запад. Такрин Торитель Путей наблюдает за проселочной дорогой, ведущей из Дуротара, и оценивает путников по поручению своего друга, ветерана Каргала Боевого Шрама. Получение рекрутского письма Такрина становится первым официальным поручением новобранца за пределами родной долины орков."},{t="Оборона границы",b="Пограничная застава за мостом лежит на стыке красных каньонов Дуротара и засушливых просторов Степей. Каргалу Боевому Шраму поручено собирать новобранцев для защиты рубежей, но охрана границы — лишь начало. Поскольку кентавры, свинобразы и отряды Альянса прощупывают границу, живая сила срочно направляется к поселению Перекресток."}},faq={{q="Куда отнести рекрутское письмо?",a="Следуйте по западной дороге из Колючего Холма в Дуротаре и перейдите деревянный мост через реку Строптивую. Каргал Боевой Шрам стоит на сторожевой башне заставы Орды сразу за границей, на стороне Степей.",al={"where do i go","kargal battlescar location","turn in location","куда идти","где каргал боевой шрам","где сдать задание"}},{q="Who is Takrin Pathseeker?",a="Takrin Pathseeker is a Horde scout stationed along the western road outside Razor Hill. He acts as an eye on the road and spots capable warriors to send westward to his comrade Kargal Battlescar.",al={"takrin role","who gives quest","quest giver","роль такрин","кто выдает задание","персонаж, выдающий задание"}},{q="Кто такой Каргал Боевой Шрам?",a="Каргал Боевой Шрам — суровый офицер-ветеран, командующий сторожевым постом на востоке Степей. Он осматривает прибывающих добровольцев, подписывает их призывные бумаги и направляет их вглубь саванны на помощь Перекрестку.",al={"who is kargal","battlescar lore","кто такой каргал","каргал боевой шрам предания"}},{q="Что происходит после того, как Каргал подписывает письмо?",a="Каргал принимает письмо и сразу зачисляет вас на дальнейшую службу заданием «Рекрутский набор Перекрестка», приказывая идти на запад по главной дороге и доложиться Сергре Черный Шип на Перекрестке.",al={"next quest","what after conscript of the horde","where next","следующее задание","что после новобранец орды","куда дальше"}},{q="Почему Орда набирает солдат для Степей?",a="Степи — открытый рубеж, важный для связи Оргриммара с Мулгором. Поскольку свирепые племена свинобразов, кентавры-мародеры и коварные вторжения Альянса угрожают путям снабжения, Орде нужна каждая пара рук, чтобы дороги оставались безопасными.",al={"why conscript","barrens danger","why recruit","зачем призыв","опасность степей","зачем набор"}},{q="Доступно ли это задание игрокам Альянса?",a="Нет. Это задание только для представителей Орды, переходящих из начальных цепочек заданий Дуротара в Степи.",al={"can alliance do this","is this horde only","может ли альянс выполнить","только для орды"}}},fp="22,320,22.382.0,14.392.0,39.218.0,25.195.0,25.214.0,43.215.0,53.249.0,44.121.0"}
P.entries["quest:842"] = {n="Рекрутский набор Перекрестка",s="«Рекрутский набор Перекрестка» направляет вновь зачисленных новобранцев Орды от пограничной заставы в самое сердце Степей. С подписанным письмом Каргала Боевого Шрама искатели приключений являются прямо к Сергре Черный Шип в важный стратегический узел — на Перекресток.",h="«Рекрутский набор Перекрестка» направляет вновь зачисленных новобранцев Орды от пограничной заставы в самое...",kw={"barrens","battlescar","conscription","crossroads","darkthorn","far watch","kargal","sergra","thrall","степи","боевой шрам","призыв","перекресток","черный шип","дальняя застава","каргал","сергра","тралл"},ang={["class:Shaman"]="Сергра Черный Шип показывает, что шаманы в Орде Тралла служат не только мистическими советниками, но и прямыми военными командирами и управителями важных стратегических застав.",["faction:Horde"]="Это назначение — обычный обряд посвящения для молодых воинов Орды, переходящих из безопасных родных земель в спорные дикие края Степей.",["race:Orc"]="Разговор Каргала и Сергры подчеркивает меняющиеся общественные порядки в обновленной Орде Тралла, где заслуги и духовное прозрение бросают вызов старым клановым устоям простой солдатской работы."},sec={{t="Явка на службу",b="Доказав свою ценность Каргалу Боевому Шраму на Дальней заставе у границы Дуротара, новобранцы получают подписанное рекрутское письмо и отправляются на запад. Путь идет по утоптанной грунтовой дороге через сухой кустарник Степей до центральной развилки. На этом выжженном солнцем перекрестке лежит Перекресток — важный логистический узел Орды, связывающий север Калимдора с южными дикими землями."},{t="Шаманка Перекрестка",b="Новичков ждет Сергра Черный Шип, острая на язык орчиха-шаман, лично выбранная вождем Траллом для руководства делами на Перекрестке. Несмотря на ворчание закаленных ветеранов вроде Каргала Боевого Шрама, считающего ее сварливой и излишне болтливой, Тралл высоко ценит Сергру. Свирепая и непреклонная, она спешит напомнить новобранцам, особенно самоуверенным мужчинам, что в Орде Тралла воительницы и предводительницы стоят вровень с мужчинами и не потерпят дерзости."}},faq={{q="Кто посылает меня на это задание?",a="На это задание вас отправляет Каргал Боевой Шрам, орк-ветеран с Дальней заставы к западу от моста, разделяющего Дуротар и Степи.",al={"who gives crossroads conscription","quest giver crossroads conscription","kargal quest","кто дает рекрутский набор перекрестка","персонаж, выдающий рекрутский набор перекрестка","задание каргала"}},{q="Где находится Сергра Черный Шип?",a="Сергра Черный Шип стоит прямо в центре Перекрестка, возле пересечения дорог, где встречаются караваны и гонцы.",al={"sergra darkthorn location","where is sergra","find sergra darkthorn","где сергра черный шип","где сергра","найти сергру черный шип"}},{q="Почему Каргал жалуется на Сергру?",a="Каргал считает Сергру раздражающей и называет ее вредной шаманкой, которая ходит вокруг да около, прежде чем дать кому-либо настоящую работу. Несмотря на личную досаду, он уважает приказ вождя Тралла посылать новобранцев к ней.",al={"why does kargal dislike sergra","kargal vs sergra","curse her hide","почему каргал не любит сергру","каргал против сергры","проклятая шкура"}},{q="Почему Сергра говорит по-разному с персонажами-мужчинами и женщинами?",a="Сергра Черный Шип очень гордится указом Тралла, установившим полное равенство воительниц в новой Орде. Она тепло поддерживает новобранок за их решимость, а новобранцев-мужчин предупреждает, что не потерпит неуважения и дерзости.",al={"sergra dialogue male female","sergra darkthorn dialogue","sergra equal footing","диалог сергры мужчина женщина","диалог сергры черный шип","сергра равенство"}},{q="Каким путем идти к Перекрестку?",a="Идите по главной дороге на запад от Дальней заставы до Т-образного перекрестка, затем поверните налево и следуйте по южной дороге прямо к поселению Перекресток.",al={"how to get to crossroads","directions to crossroads","crossroads path","как дойти до перекрестка","дорога к перекрестку","путь к перекрестку"}},{q="Что происходит после доклада Сергре Черный Шип?",a="Приняв вас, Сергра привлекает вас к непосредственной помощи Перекрестку: она посылает вас бороться с местными угрозами, охотиться и охранять заставы в центральных Степях.",al={"what comes after crossroads conscription","next quest sergra","barrens recruits next","что после рекрутского набора перекрестка","следующее задание сергры","следующие новобранцы степей"}}},fp="23,265,18.412.0,28.496.0,27.153.0,34.139.0,38.216.0,64.259.0,49.173.0,49.186.0"}
P.entries["quest:843"] = {n="Ответный удар Ганна",s="«Ответный удар Ганна» — задание Орды, которое выдает странствующий изгнанник-таурен Ганн Каменное Копье в южных Степях. Глубоко обиженный на археологические раскопки дворфов в Бейл Модане, из-за которых его племя лишилось дома, Ганн просит путников нанести ответный удар: перебить работников раскопок и добыть дневник их предводителя.",h="«Ответный удар Ганна» — задание Орды, которое выдает странствующий изгнанник-таурен Ганн Каменное Копье в...",kw={"bael modan","bael'dun","dwarf dig site","explorers' league","gann stonespire","khazgorm","southern barrens","бейл модан","бейл'дун","раскопки дворфов","лига исследователей","ганн каменное копье","хазгорм","южные степи"},ang={["class:Shaman"]="Взрывные работы и глубокие траншеи в Бейл Модане ранят окружающих духов земли, поэтому поход Ганна — необходимое очищение от стихийного разлада.",["faction:Horde"]="Бейл Модан — укрепленный оплот Альянса в глубине Калимдора, поэтому защита дела Ганна — одновременно дело чести и стратегическое сдерживание.",["race:Tauren"]="Для шу'хало беда Ганна — возмутительное напоминание о том, как мало Альянс уважает Мать-Землю, разрушая динамитом и железными шестернями древние места захоронений."},sec={{t="Изгнанное племя",b="Еще до того, как пушки и кирки Добытчика вспороли землю, красные утесы к югу от Степей были исконной родиной и охотничьими угодьями клана Ганна Каменного Копья. Когда Лига исследователей прибыла из Стальгорна, чтобы основать Бейл Модан, тауренов жестоко выгнали или убили, освобождая место для огромных карьеров и траншей. Мирные протесты остались без внимания, дипломатия исчерпана, и теперь Ганн в одиночестве бродит по пыльной южной дороге, замышляя кровавое возмездие за павших сородичей."},{t="Руины Бейл Модана",b="Дворфы в Бейл Модане почти не думают о земле и ее хранителях. Вскрывая склоны холмов паровыми машинами и мощной взрывчаткой, экспедиция под началом геолога Хазгорма глубоко вгрызлась в землю в поисках древних реликвий титанов. Задача Ганна проста и бескомпромиссна: проредить ряды землекопов и надсмотрщиков Бейл'дуна, оскверняющих священную землю, убить самого Хазгорма и забрать личные записи геолога, чтобы узнать, что на самом деле нужно захватчикам из Альянса."}},faq={{q="Кто такой Ганн Каменное Копье?",a="Ганн Каменное Копье — одинокий уцелевший таурен, чье племя некогда жило в южных Степях. После того как дворфы-землекопы вытеснили его народ и убили сопротивлявшихся, Ганн стал бродить по южной дороге, ища справедливости и мести наступающим раскопкам Альянса.",al={"gann","who gives gann's reclamation","gann stonespire lore","ганн","кто выдает задание ответный удар ганна","ганн каменное копье предания"}},{q="Почему дворфы в Степях?",a="Дворфы входят в экспедицию Бейл'дуна, отправленную Лигой исследователей Стальгорна. Вдохновленные недавним открытием своего наследия титанов, они основали Бейл Модан, чтобы раскапывать древние погребенные реликвии и руины, совершенно не считаясь с коренными жителями-тауренами.",al={"why are dwarves at bael modan","bael modan purpose","ironforge in barrens","почему дворфы в бейл модане","цель бейл модана","стальгорн в степях"}},{q="Кто такой геолог Хазгорм?",a="Геолог Хазгорм — предводитель дворфов, руководящий раскопками к югу от крепости Бейл Модан. Ганн считает его прямо виновным в осквернении земель предков и требует его дневник как доказательство смерти.",al={"khazgorm","prospector khazgorm","bael modan leader","хазгорм","геолог хазгорм","предводитель бейл модана"}},{q="Где найти Ганна Каменного Копья?",a="Ганн Каменное Копье бродит по дороге на дальнем юге Степей, к западу от крепости Бейл Модан и к северу от дороги, ведущей к Великому Подъемнику и в Тысячу Игл.",al={"gann location","find gann","where is gann","где ганн","найти ганна","местоположение ганна"}},{q="Пытался ли Ганн решить дело миром?",a="Да. Ганн прямо говорит, что пытался остановить разрушение земель предков дипломатией, но дворфы отмахнулись и продолжили взрывать холмы, вынудив его прибегнуть к насилию.",al={"did tauren try diplomacy","gann diplomacy","пытались ли таурены договориться","дипломатия ганна"}},{q="Что будет после этого задания?",a="Получив дневник Хазгорма, Ганн изучает записи, чтобы понять технологии и планы дворфов, и это ведет к цепочке заданий «Месть Ганна» — саботажу их тяжелой техники.",al={"next quest after gann's reclamation","gann follow up","следующее задание после ответного удара ганна","продолжение ганна"}}},fp="18,312,17.508.0,23.509.0,23.283.0,35.277.0,27.259.0,35.171.0,40.228.0,30.198.1"}
P.entries["quest:844"] = {n="Равнинные долгоноги",s="«Равнинные долгоноги» — вводное охотничье задание, которое выдает Сергра Черный Шип на Перекрестке. Новоприбывшим искателям приключений из Орды поручено истребить местных долгоногов, разоряющих торговые пути поселения, — и как борьбу с вредителями, и как первое испытание охотничьих навыков.",h="«Равнинные долгоноги» — вводное охотничье задание, которое выдает Сергра Черный Шип на Перекрестке.",kw={"barrens","beak","crossroads","darkthorn","hunt","plainstrider","sergra","supplies","степи","клюв","перекресток","черный шип","охота","долгоног","сергра","припасы"},ang={["class:Hunter"]="Для молодых охотников испытание Сергры — необходимая основа выслеживания, преследования и добычи зверя в открытой саванне.",["faction:Horde"]="Перекресток — важнейший узел снабжения, и защита его запасов еды от животных позволяет Орде удерживать позиции в Калимдоре.",["race:Orc"]="Орки чтят дисциплину охоты, и Сергра ждет, что каждый новичок проявит себя против местных зверей, прежде чем взяться за более серьезные дела."},sec={{t="Защита Перекрестка",b="Перекресток находится в логистическом сердце Калимдора и координирует караваны снабжения через суровую саванну. Но засушливая местность лишает местных животных пропитания. Стаи высоких нелетающих долгоногов к востоку от поселения принялись клевать ящики с провизией и нарушать снабжение. Чтобы защитить припасы, шаманка Сергра Черный Шип посылает путников истребить агрессивных птиц, пока они не нанесли серьезный ущерб запасам поселения."},{t="Первая охота",b="Хотя борьба с вредителями — насущная практическая цель, Сергра видит в долгоногах мерило для новичков. Она считает птиц простой добычей, на которой молодые охотники учатся выживать и выслеживать дичь на выжженных солнцем равнинах. Принесенные острые клювы доказывают, что у охотника хватает терпения и боевых навыков для схватки с более свирепыми зверями Степей."}},faq={{q="Почему охотятся на долгоногов?",a="Стаи долгоногов к востоку от Перекрестка стали настолько смелыми, что нападают на запасы еды и тревожат проходящие караваны. Сергра Черный Шип приказывает истребить их, чтобы сберечь жизненно важные припасы поселения.",al={"why kill plainstriders","plainstrider problem","what did plainstriders do","зачем убивать долгоногов","проблема с долгоногами","что натворили долгоноги"}},{q="Кто такая Сергра Черный Шип?",a="Сергра Черный Шип — опытная шаманка-орк, живущая на Перекрестке. Она руководит охотничими испытаниями поселения, обучает новоприбывших искателей приключений и направляет их против диких зверей, угрожающих Орде.",al={"who is sergra","sergra darkthorn role","quest giver crossroads","кто такая сергра","роль сергры черный шип","персонаж, выдающий задания на перекрестке"}},{q="Почему Сергре нужны именно клювы?",a="Крепкий острый клюв — главное оружие долгонога и орудие для добычи пищи. Клювы — неоспоримое доказательство того, что птицы убиты.",al={"why plainstrider beaks","plainstrider beak proof","зачем клювы долгоногов","клюв долгонога доказательство"}},{q="What comes after this hunt?",a="Когда с долгоногами покончено, Сергра испытывает вас на более быстрой и резвой добыче, отправляя охотиться на жевр, бродящих по равнинам.",al={"what is next","next quest after plainstriders","hunt sequence","что дальше","следующее задание после долгоногов","цепочка охоты"}},{q="Где обитают эти долгоноги?",a="Они бродят по травянистой саванне сразу к востоку и юго-востоку от Перекрестка, кормясь вдоль торговых дорог.",al={"where are plainstriders","plainstrider locations","hunting grounds","где долгоноги","места обитания долгоногов","охотничьи угодья"}},{q="Это часть большой охотничьей серии?",a="Да. Это задание — самое начало охотничьих испытаний Сергры Черный Шип в Степях, которые постепенно переходят ко все более опасным зверям саванны.",al={"barrens hunting chain","sergra quest chain","цепочка охоты в степях","цепочка заданий сергры"}}},fp="19,292,23.516.0,14.423.0,35.207.0,24.221.0,46.172.0,27.143.0,38.116.0,40.174.0"}
P.entries["quest:845"] = {n="Жевры",s="«Жевры» — раннее охотничье испытание, которое выдает Сергра Черный Шип на Перекрестке. В рамках нарастающей проверки боевых навыков в саваннах Степей молодым охотникам поручено выследить быстроногих жевр и добыть их мощные копыта.",h="«Жевры» — раннее охотничье испытание, которое выдает Сергра Черный Шип на Перекрестке.",kw={"barrens","crossroads","hooves","hunting trial","sergra darkthorn","zhevra","zhevra runner","степи","перекресток","копыта","охотничье испытание","сергра черный шип","жевра","жевра-бегун"},ang={["class:Hunter"]="Для стрелков и следопытов, делающих первые шаги в Степях, охота на быстрые стада жевр — важная полевая практика преследования и меткости.",["faction:Horde"]="Перекресток полагается на проходящих искателей приключений в сдерживании численности окрестных животных, чтобы пути снабжения поселения оставались свободными.",["race:Tauren"]="Сергра особо отмечает, что удар жевры может сбить с ног взрослого таурена, и это испытание напоминает: даже травоядные равнин заслуживают уважения."},sec={{t="Шаг вперед в саванне",b="После первого истребления расплодившихся долгоногов Степей Сергра Черный Шип направляет молодых воинов Орды к более грозной добыче. Полосатые жевры бродят стадами по северным и южным равнинам. Хотя они не вершина пищевой цепи саванны, это быстроногие стадные звери, известные упрямой выносливостью и мощными ударами копыт, ломающими кости."},{t="Испытания Черного Шипа",b="Для Сергры эта охота не столько про добычу товаров, сколько про проверку растущей хватки искателя приключений. Она требует четыре целых копыта как доказательство убийства и предупреждает, что удар задних ног зверя способен осадить на круп взрослого таурена. Доказав себя против этих быстрых бегунов, охотник получает доступ к еще более смертельным испытаниям против хищников равнин."}},faq={{q="Кто выдает это задание?",a="Сергра Черный Шип, опытная шаманка-орк с Перекрестка в центральных Степях, дает это испытание, чтобы проверить растущих воинов Орды.",al={"who gives the zhevra quest","quest giver zhevra","sergra darkthorn quest","кто выдает задание про жевр","персонаж, выдающий задания жевры","задание сергры черный шип"}},{q="Где водятся жевры?",a="Жевры бродят по открытым равнинам к северу и к югу от Перекрестка в центральных Степях.",al={"where are zhevra runners","zhevra location","barrens zhevra map","где жевры","местоположение жевр","карта жевр в степях"}},{q="Почему Сергре нужны копыта жевр?",a="Копыта — трофей, подтверждающий честную охоту. Ноги жевр на редкость сильны, и принесенные четыре копыта показывают, что охотник способен одолеть зверя, который может сбить с ног даже могучего таурена.",al={"why zhevra hooves","zhevra hoof proof","why hunt zhevra","зачем копыта жевр","копыто жевры доказательство","зачем охотиться на жевр"}},{q="Что будет после этого задания?",a="Когда вы докажете свои способности против жевр, Сергра испытает вас против настоящих хищников в задании «Хищники Степей».",al={"next quest after the zhevra","zhevra follow up","darkthorn next quest","следующее задание после жевр","продолжение жевр","следующее задание черного шипа"}},{q="Опасны ли жевры?",a="Хотя жевры обычно мирно пасутся, их ноги невероятно сильны. Сергра предупреждает, что один прямой удар испуганной или загнанной жевры может опрокинуть крепкого таурена на спину.",al={"how dangerous are zhevra","zhevra danger","zhevra kick","насколько опасны жевры","опасность жевр","удар жевры"}},{q="Почему до этого охотились на долгоногов?",a="Сергра выстраивает испытания с постепенным ростом сложности. Долгоноги — первая учебная мишень, а жевры требуют справиться с более быстрой и сильной добычей, прежде чем перейти к агрессивным хищникам саванны.",al={"previous quest","plainstrider menace connection","предыдущее задание","связь с равнинными долгоногами"}}},fp="10,267,24.378.0,23.404.0,22.145.0,27.102.0,35.211.0,28.123.0,22.198.0,42.235.0"}
P.entries["quest:846"] = {n="Месть Ганна",s="«Месть Ганна» — задание Орды в южных Степях, в котором скорбящий изгнанник-таурен Ганн Каменное Копье замышляет возмездие экспедиции Бейл Модана. Расправившись с геологом Хазгормом, Ганн посылает путников в дворфийскую крепость за взрывчатыми материалами для сокрушительной контратаки.",h="«Месть Ганна» — задание Орды в южных Степях, в котором скорбящий изгнанник-таурен Ганн Каменное Копье...",kw={"bael modan","barrens","dynamite","explosives","gann stonespire","ironforge","khazgorm","nitroglycerin","sodium nitrate","wood pulp","бейл модан","степи","динамит","взрывчатка","ганн каменное копье","стальгорн","хазгорм","нитроглицерин","нитрат натрия","древесная масса"},ang={["faction:Horde"]="Пресечение действий дворфов в южных Степях не дает военному плацдарму Альянса перерезать сообщение между Мулгором, Перекрестком и южными рубежами.",["profession:Engineering"]="Сочетание нитроглицерина, нитрата натрия и древесной массы — классический дворфийский рецепт промышленного динамита, на ходу приспособленный для асимметричной войны.",["race:Tauren"]="Для таурен Бейл Модан — тяжкая рана, нанесенная Матери-Земле, поэтому диверсия против дворфийских машин становится духовным и земельным долгом."},sec={{t="Тем же оружием",b="Смерть геолога Хазгорма стала ударом для раскопок Бейл Модана, но Ганн Каменное Копье знает, что это лишь временная неудача. Дворфы редко надолго прекращают работы, и скоро прибудет новый начальник, который будет управлять машинами, истязающими землю его предков. Не желая смотреть, как землю раскапывают дальше, Ганн решает ударить в ответ с помощью технологий захватчиков. Превратив их подрывное снаряжение в орудие диверсии, он намерен разрушить их оплот изнутри."},{t="Налет на крепость",b="Крепость Бейл Модана служит и раскопочной базой, и укрепленным гарнизоном: солдаты, стрелки и офицеры защищают интересы дворфов в Степях. Ганн выяснил, что защитники хранят материалы для промышленных подрывных работ: нитроглицерин, древесную массу и нитрат натрия. Он поручает союзникам из Орды проникнуть за ограду и забрать эти взрывоопасные компоненты прямо у дворфов, чтобы собрать достаточно сырья для мощного подрывного заряда."}},faq={{q="Почему Ганн Каменное Копье жаждет мести?",a="Дворфы Стальгорна из Бейл Модана захватили родные земли Ганна, осквернили почву и изгнали его народ, чтобы устроить свои раскопки. Убив главного геолога и забрав его журнал, Ганн намерен навсегда прекратить их разрушения.",al={"why gann angry","gann stonespire motive","what did dwarves do to gann","почему ганн зол","мотив ганна каменное копье","что сделали дворфы с ганном"}},{q="Где найти взрывоопасные материалы?",a="Ингредиенты носят с собой дворфы, защищающие Бейл Модан. Стрелки, солдаты и офицеры в укрепленном лагере раскопок и вокруг него в южных Степях носят флаконы с нитроглицерином, связки древесной массы и образцы нитрата натрия.",al={"where to get nitroglycerin","how to get wood pulp","where is sodium nitrate","где взять нитроглицерин","как достать древесную массу","где нитрат натрия"}},{q="Зачем Ганну древесная масса и химикаты?",a="Из дворфийских чертежей для раскопок следует, что нитроглицерин, стабилизированный древесной массой и смешанный с нитратом натрия, дает надежную промышленную взрывчатку. Ганн намерен изготовить особый подрывной заряд, чтобы разнести ключевые постройки дворфов.",al={"why wood pulp","what does gann make","gann bomb ingredients","зачем древесная масса","что делает ганн","ингредиенты бомбы ганна"}},{q="Что будет после сбора припасов?",a="Когда вы вернете сырье, Ганн соберет взрывной заряд и поручит вам взорвать им летающую машину дворфов на раскопках Бейл Модана — важную часть инфраструктуры лагеря.",al={"what next revenge of gann","after gathering ingredients","что дальше месть ганна","после сбора ингредиентов"}},{q="Почему гибель Хазгорма не устранила угрозу со стороны дворфов?",a="Хазгорм был лишь старшим геологом. Военное присутствие дворфов в Бейл Модане прочно укоренилось, его защищают стены и линии снабжения. Стальгорн просто пришлет другого начальника продолжать раскопки, если не нанести по всей базе сокрушительный удар.",al={"why didn't khazgorm death work","is bael modan stopped","почему смерть хазгорма не помогла","остановлен ли бейл модан"}},{q="Чем Бейл Модан опасен для Орды в стратегическом плане?",a="Бейл Модан строился как укрепленный лагерь раскопок для поиска древних артефактов титанов, но превратился в хорошо укомплектованный оплот Альянса. Он расположен на торговых путях южных Степей и представляет реальную военную угрозу для ближайших поселений Орды в Калимдоре.",al={"why horde care about bael modan","bael modan threat","почему орде важен бейл модан","угроза бейл модана"}}},fp="15,306,29.495.0,16.500.0,39.274.0,40.250.0,43.257.0,42.208.1,52.270.0,51.284.0"}
P.entries["quest:848"] = {n="Споры грибов",s="Аптекарь Хелбрим из Королевского фармацевтического общества поручает искателям приключений из Орды собрать споры грибов у оазисов Степей. Странные мутагенные энергии, питающие эти источники, превратили местную флору в сильные реагенты. Хелбрим хочет собрать эти редкие образцы, чтобы варить зелья для своей коллеги в Громовом Утесе.",h="Аптекарь Хелбрим из Королевского фармацевтического общества поручает искателям приключений из Орды собрать...",kw={"apothecary helbrim","apothecary zamah","barrens","crossroads","forgotten pools","fungal spores","lushwater oasis","royal apothecary society","stagnant oasis","аптекарь хелбрим","аптекарь зама","степи","перекресток","забытые пруды","споры грибов","цветущий оазис","королевское фармацевтическое общество","застывший оазис"},ang={["class:Druid"]="В оазисах бурлит неестественно мощный поток магии природы, вызывающий резкие мутации в окружающей экосистеме.",["faction:Horde"]="Исследование неспокойных вод Степей помогает защитить важные тропы, соединяющие Оргриммар, Перекресток и Громовой Утес.",["profession:Herbalism"]="Грибы-переростки у оазисов Степей показывают, как внезапный приток энергии окружающей среды превращает обычную флору в сильные реагенты.",["race:Undead"]="Даже вдали от Лордерона исследователи Отрекшихся продолжают алхимические труды, направляя природные аномалии Калимдора на цели Королевского фармацевтического общества."},sec={{t="Яркая и мутировавшая флора",b="Степи — в целом засушливая, выжженная солнцем саванна, но оазисы, такие как Забытые пруды, Цветущий оазис и Застывший оазис, полны неестественной жизненной силы. Из этих вод струится странный поток энергии жизни, изменяющий и подпитывающий растения и зверей, которые пьют из них. Грибы-переростки на илистых берегах впитывают эти мощные потоки, и их споры приобретают редкие свойства, привлекающие внимание проходящих алхимиков."},{t="Королевское фармацевтическое общество в Калимдоре",b="Хотя аптекарь Хелбрим служит на Перекрестке, вдали от Подгорода, он остается предан исследованиям Королевского фармацевтического общества. Осознав необычайную силу местных реагентов Калимдора, он собирает измененные споры, чтобы готовить мощные смеси. Собранные здесь образцы предназначены для аптекаря Замы в Громовом Утесе, что показывает, какие тонкие и далеко идущие научные усилия предпринимают Отрекшиеся в землях союзников."}},faq={{q="Где растут эти споры грибов?",a="Споры собирают с грибов-переростков, растущих у кромки воды в оазисах Степей, включая Забытые пруды, Цветущий оазис и Застывший оазис.",al={"where to find fungal spores","fungal spore location","laden mushrooms location","где найти споры грибов","где растут споры грибов","где грибы-переростки"}},{q="Почему грибы у оазисов изменились?",a="Мощный поток энергии жизни пронизывает воды оазисов Степей. Вместо того чтобы питать обычный рост растений, эта энергия яростно подпитывает и изменяет окружающих животных и растения.",al={"why are the mushrooms mutated","oases life energy","what is wrong with the oases","почему грибы мутировали","энергия жизни оазисов","что не так с оазисами"}},{q="Кто такой аптекарь Хелбрим?",a="Аптекарь Хелбрим — член Королевского фармацевтического общества Отрекшихся, служащий на Перекрестке в Степях. Он изучает необычную биологию региона и собирает местные материалы для алхимических исследований.",al={"helbrim lore","who is helbrim","apothecary at crossroads","хелбрим предания","кто такой хелбрим","аптекарь на перекрестке"}},{q="Что Хелбрим собирается делать со спорами?",a="Хелбрим использует сильные споры для приготовления особого зелья, которое он намерен отправить своему коллеге по исследованиям, аптекарю Заме, в город таурен Громовой Утес.",al={"what are the spores for","fungal spores purpose","для чего споры","зачем нужны споры грибов"}},{q="Почему аптекари Отрекшихся работают в Степях?",a="Как часть союза Орды, исследователи Отрекшихся изучают чужие края и редкую флору Калимдора, чтобы найти новые реагенты для лекарств, ядов и зелий.",al={"why are undead in barrens","royal apothecary society in kalimdor","почему нежить в степях","королевское фармацевтическое общество в калимдоре"}},{q="В каком оазисе безопаснее всего собирать споры?",a="В Забытых прудах к северо-западу от Перекрестка обитают звери более низкого уровня, чем у Цветущего оазиса или Застывшего оазиса на юге, поэтому там безопаснее всего собирать грибы.",al={"easiest oasis for spores","safest oasis barrens","легкий оазис для спор","самый безопасный оазис степей"}}},fp="13,353,25.469.0,40.448.0,34.180.0,45.206.0,26.208.0,45.173.0,55.176.0,49.213.0"}
P.entries["quest:849"] = {n="Месть Ганна",s="«Месть Ганна» — последний удар в вендетте Ганна Каменного Копья против дворфов Бейл Модана. Вооруженный особым взрывным зарядом, созданным по украденным дворфийским чертежам, посланник Орды должен взорвать главную гордость экспедиции — летающую машину — в отместку за павшее племя Каменного Копья.",h="«Месть Ганна» — последний удар в вендетте Ганна Каменного Копья против дворфов Бейл Модана.",kw={"bael modan","explosive stick of gann","flying machine","gann stonespire","khazgorm","stonespire tribe","the barrens","thunder bluff","бейл модан","взрывающаяся шашка ганна","летающая машина","ганн каменное копье","хазгорм","племя каменного копья","степи","громовой утес"},ang={["faction:Horde"]="Уничтожение летающей машины Бейл Модана лишает Альянс воздушного оружия, способного вести разведку и наносить удары вглубь южных Степей.",["profession:Engineering"]="Взрывчатка для машины создана на основе стальгорнских чертежей, обращенных против гирокоптера, — иронично удачная полевая диверсия.",["race:Tauren"]="Месть за клан Каменного Копья уничтожением дворфийских боевых машин глубоко трогает любого таурена, защищающего родные земли от осквернения."},sec={{t="Символ господства",b="Раскопки Бейл Модана — не просто навязчивая шахта, а вооруженная крепость, построенная прямо на землях предков изгнанного племени таурен Каменного Копья. Основа боевой мощи и дальности действий геологов — их гирокоптер, летающая машина. Стоя на сторожевой башне над раскопками, механический летательный аппарат осматривает окрестные Степи, охраняет линии снабжения и висит символом наглого вторжения Альянса на землю Калимдора."},{t="Против своих создателей",b="Получив чертежи геолога Хазгорма, Ганн Каменное Копье изготавливает особый заряд — «Взрывающуюся шашку Ганна». Подложив эту взрывчатку под летающую машину, Ганн добивается, чтобы технологическая гордыня дворфов обернулась их гибелью. Взрыв уничтожает важное военное средство, унижает отряд Бейл Модана и чтит духов погибшего племени."}},faq={{q="Почему Ганн хочет уничтожить именно летающую машину?",a="Летающая машина — и боевое оружие, и важная часть инфраструктуры Бейл Модана, дающая дворфам воздушную разведку. А для Ганна важнее то, что она — вызывающий символ дворфийской мощи и оскорбительное присутствие над землей, которую его перебитое племя считало домом.",al={"why destroy gyrocopter","flying machine purpose","why target flying machine","зачем уничтожать гирокоптер","назначение летающей машины","почему цель летающая машина"}},{q="Где находится летающая машина в Бейл Модане?",a="Летающая машина стоит на деревянной башенной площадке на полпути вниз по пандусу в главный котлован раскопок, а не внутри главной дворфийской крепости и не рядом с ней.",al={"where is flying machine","flying machine location","bael modan gyrocopter spot","где летающая машина","местонахождение летающей машины","гирокоптер бейл модан"}},{q="Как Ганн создал взрывное устройство?",a="Ганн изготовил «Взрывающуюся шашку Ганна» по техническим схемам и чертежам, недавно добытым у геолога Хазгорма, обратив замыслы самих дворфов против них.",al={"how made bomb","explosive stick origin","khazgorm plans explosive","как сделана бомба","происхождение взрывной шашки","чертежи хазгорма взрывчатка"}},{q="К какому племени принадлежит Ганн?",a="Ганн принадлежит к племени Каменного Копья — клану таурен, исстари жившему в южных Степях, пока дворфийские раскопки Стальгорна не изгнали его силой и не разрушили его поселение.",al={"gann tribe","what is stonespire tribe","who are stonespire tauren","племя ганна","что такое племя каменного копья","кто такие таурены каменного копья"}},{q="Прекратит ли уничтожение машины раскопки навсегда?",a="Оно сильно подорвет превосходство Бейл Модана в воздухе и его инфраструктуру и даст Ганну личное возмездие, но укрепившиеся дворфы-копатели и их крепость останутся действующим оплотом Альянса в регионе.",al={"is bael modan stopped","does bael modan fall","did gann win","остановлен ли бейл модан","падет ли бейл модан","победил ли ганн"}},{q="Какую награду предлагает Ганн за выполнение этого задания?",a="Ганн объявляет, что герой, уничтоживший машину, будет почитаться в Громовом Утесе как защитник священных земель таурен и верный заступник его утраченного племени.",al={"gann completion","gann quest end","what does gann say","завершение у ганна","конец задания ганна","что говорит ганн"}}},fp="15,303,22.481.0,22.425.1,62.298.0,50.180.0,41.183.0,31.196.0,60.226.0,61.167.1"}
P.entries["quest:85"] = {n="Потерянное ожерелье",s="Потерянное ожерелье — вводное задание на юге Элвиннского леса, которое выдает «Тетушка» Бернис Стоунфилд. Подозревая в краже озорного мальчишку из враждующего семейства, Бернис отправляет искателей приключений через дорогу, чтобы они поговорили с Билли Маклюром и вернули ее пропавшую семейную реликвию.",h="Потерянное ожерелье — вводное задание на юге Элвиннского леса, которое выдает «Тетушка» Бернис Стоунфилд.",kw={"bernice","billy","elwynn","farm","maclure","necklace","stonefield","vineyards","бернис","билли","элвиннский лес","ферма","маклюр","ожерелье","стоунфилд","виноградники"},ang={["faction:Alliance"]="Для новичков Альянса, начинающих путь в Элвиннском лесу, улаживание мелких ссор между Стоунфилдами и Маклюрами — типичное знакомство с жизнью на границе.",["race:Human"]="Вражда Стоунфилдов и Маклюров показывает, что не все раздоры в Королевстве Штормград вызваны разбойниками из Братства Справедливости или шайками гноллов: старые ссоры сельских соседей не менее глубоки."},sec={{t="Обвинение соседей",b="Семьи Стоунфилдов и Маклюров владеют соседними землями на юге Элвиннского леса, но добрых чувств между ними почти нет. Обнаружив пропажу любимого ожерелья, «Тетушка» Бернис Стоунфилд без промедления указывает на младшего из враждебного семейства. Убежденная, что юный Билли Маклюр пробрался на ее ферму и украл украшение, озлобленная вдова просит любого путника сходить на виноградники, найти мальчика и потребовать вернуть пропажу."},{t="Мальчик с хорошим аппетитом",b="Разговор с Билли Маклюром на соседних виноградниках быстро усложняет дело. Билли возмущенно отрицает кражу и заявляет, что он не вор. Однако с хитрой ухмылкой он намекает, что, возможно, знает, что на самом деле случилось с безделушкой, — но сначала кто-нибудь должен утолить его голод свежим пирогом со свининой."}},faq={{q="Кто такая Тетушка Бернис Стоунфилд?",a="Тетушка Бернис Стоунфилд — пожилая вдова, живущая на Ферме Стоунфилдов на юге Элвиннского леса. Она сильно подозревает соседей Маклюров, особенно их озорного сына Билли.",al={"who is auntie bernice","bernice stonefield","who gives lost necklace","кто такая тетушка бернис","бернис стоунфилд","кто выдает потерянное ожерелье"}},{q="Действительно ли Билли Маклюр украл ожерелье?",a="Когда его обвиняют, Билли решительно отрицает, что он вор. Он сам ожерелье не брал, но признает, что видел, кто или что это сделало, однако не раскроет тайну, пока его как следует не накормят.",al={"is billy a thief","did billy steal it","did billy take the necklace","билли вор","билли украл ожерелье","брал ли билли ожерелье"}},{q="Где найти Билли Маклюра?",a="Билли Маклюра обычно можно найти бездельничающим среди виноградных лоз на Виноградниках Маклура, к востоку от Фермы Стоунфилдов, через дорогу.",al={"billy maclure location","where is billy","find billy maclure","где билли маклюр","где билли","найти билли маклюра"}},{q="Почему Стоунфилды и Маклюры не любят друг друга?",a="Две соседние семьи уже много лет втянуты в ожесточенную деревенскую вражду. Напряжение вызвано спорами о собственности, гордостью и застарелыми личными обидами, поэтому обе стороны сразу готовы подозревать друг друга в худшем.",al={"family feud","stonefield maclure feud","why do they hate each other","семейная вражда","вражда стоунфилдов и маклюров","почему они ненавидят друг друга"}},{q="Что происходит после разговора с Билли Маклюром?",a="Билли утверждает, что слишком голоден, чтобы вспомнить, куда делось ожерелье, и отправляет вас обратно к Тетушке Бернис: пусть испечет ему пирог со свининой в обмен на сведения.",al={"what next","after lost necklace","next quest","что дальше","после потерянного ожерелья","следующее задание"}},{q="Где происходит это задание?",a="Задание целиком проходит на юге Элвиннского леса: вам предстоит ходить между Фермой Стоунфилдов и соседними Виноградниками Маклура.",al={"quest zone","where is lost necklace","зона задания","где потерянное ожерелье"}}},fp="13,264,23.485.0,22.334.1,33.211.0,46.185.1,31.146.0,55.225.0,44.171.1,33.144.0"}
P.entries["quest:850"] = {n="Главари племени Колкар",s="Задание «Главари племени Колкар» начинает кампанию орка Регтара Врата Смерти против растущего числа кентавров-военачальников в Степях. Кочевые Колкар поколениями терзали тауренов, но новые вожди сплачивают разрозненные банды в настоящую военную угрозу. Регтар поручает защитникам Орды убить Барака Кодобана у Забытых прудов, пока его влияние не распространилось.",h="Задание «Главари племени Колкар» начинает кампанию орка Регтара Врата Смерти против растущего числа...",kw={"barak","barrens","centaur","crossroads","deathgate","forgotten pools","kodobane","kolkar","regthar","барак","степи","кентавр","перекресток","врата смерти","забытые пруды","кодобан","колкар","регтар"},ang={["faction:Horde"]="Перекресток в Степях — жизненно важная артерия, соединяющая Мулгор, Дуротар и более дальние форпосты Орды. Устранение руководства Колкар защищает уязвимые караваны с припасами от разрушительных засад.",["race:Tauren"]="Для тауренов уничтожение командиров Колкар — вопрос выживания и мести. Кланы кентавров резали племена и десятилетиями гнали шу'хало с исконных пастбищ, пока Орда не закрепилась в Калимдоре."},sec={{t="Растущая угроза в засушливых землях",b="Бесчисленные годы кентавры терроризировали Калимдор и почти истребили кочевых тауренов, пока не пришла Орда Тралла и не изменила положение. В Степях преобладающее племя Колкар обычно бродит разрозненными разбойничьими отрядами. Но недавно воинственные вожди начали объединять разрозненные банды, превращая простые отряды налетчиков в сплоченную военную силу, способную оспаривать укрепленные форпосты Орды."},{t="Отсечь голову чудовищу",b="Орк-воин Регтар Врата Смерти, расквартированный в лагере к западу от Перекрестка, понимал, что Колкар держатся на одной лишь дерзости и грубой силе. Без сильных командиров налетчики погрязают в междоусобицах. Чтобы остановить их натиск, Регтар направляет приключенцев Орды отсечь змее голову, начав с Барака Кодобана, честолюбивого вожака, стоящего лагерем у зеленых вод Забытых прудов."},{t="Первый из многих",b="Убийство Барака Убийцы Кодо наносит серьезный удар по северным лагерям Колкар, но Регтар знает, что Барак — лишь авангард более широкого движения. Его гибель — первый залп целенаправленной кампании по уничтожению верховного командования Колкар, она открывает путь к охоте на других вождей — Верога Дервиша и Хэрзула Кровавую Отметину — в Степях."}},faq={{q="Кто такой Барак Кодобан?",a="Барак Кодобан — свирепый вожак кентавров Колкар, сплотивший налетчиков вокруг Забытых прудов к северу от Перекрестка. Известный умом и жестокостью, он оказался куда опаснее обычных кочевых налетчиков, объединив разрозненные кланы в наступательную силу против Орды.",al={"barak","who is barak","barak kodobane lore","барак","кто такой барак","барак кодобан предания"}},{q="Где найти Барака Кодобана?",a="Барак Кодобан держит лагерь у Забытых прудов — цветущего оазиса к северу от Перекрестка в центральной части Степей. Обычно его окружают преданные стражи Колкар.",al={"barak location","where is barak","forgotten pools barak","где барак","расположение барака","барак забытые пруды"}},{q="Кто такой Регтар Врата Смерти?",a="Регтар Врата Смерти — орк-ветеран, расположившийся в небольшом укрепленном лагере к западу от Перекрестка. Он следит за передвижениями кентавров в Степях и организует упреждающие удары, защищая поселения Орды от организованных набегов.",al={"regthar","who gives kolkar leaders","regthar deathgate lore","регтар","кто выдает главарей племени колкар","регтар врата смерти предания"}},{q="Почему Колкар — такая проблема для Орды?",a="Кентавры поколениями ведут безжалостную, почти истребительную войну против тауренов. Как полноправные члены Орды, таурены рассчитывают на союзников в защите своих исконных охотничьих угодий и торговых путей в Степях от дальнейшей экспансии кентавров.",al={"why fight kolkar","kolkar threat","centaur horde rivalry","зачем воевать с колкар","угроза колкар","кентавры и орда вражда"}},{q="Что происходит после убийства Барака?",a="Победа над Бараком Убийцей Кодо показывает, что другие вожди собирают силы в других частях Степей. Регтар сразу посылает вас убить Верога Дервиша у Застывшего оазиса, затем Хэрзула Кровавую Отметину у Цветущего оазиса, а завершается все обороной от прямого нападения Колкар.",al={"next quest after barak","kolkar leaders follow up","what comes next","следующее задание после барака","продолжение главарей колкар","что дальше"}},{q="Почему Колкар собираются вокруг оазисов?",a="Вода и плодородная земля — драгоценность в засушливом климате Степей. Захватывая природные источники вроде Забытых прудов, Колкар обеспечивают себя водой и лишают путников и охотников-тауренов удобных мест для отдыха.",al={"why are centaur at oases","kolkar water","forgotten pools centaur","почему кентавры у оазисов","вода колкар","забытые пруды кентавры"}}},fp="14,401,31.466.0,22.446.0,17.360.1,22.286.0,32.176.0,25.231.0,48.268.0,35.299.1,42.250.0"}
P.entries["quest:851"] = {n="Верог Дервиш",s="Верог Дервиш — неуловимый вожак кентавров Колкар, кочующий по южным равнинам Степей. Чтобы положить конец его набегам, Регтар Врата Смерти направляет защитников Орды разорить командный шатер кентавров у Застывшего оазиса и выманить кочевого командира.",h="Верог Дервиш — неуловимый вожак кентавров Колкар, кочующий по южным равнинам Степей.",kw={"barrens","centaur","crossroads","dervish","kolkar","regthar deathgate","stagnant oasis","verog","степи","кентавр","перекресток","дервиш","колкар","регтар врата смерти","застывший оазис","верог"},ang={["faction:Horde"]="Контроль над оазисами жизненно важен для выживания в засушливых Степях; уничтожение командиров кентавров сохраняет водные маршруты для караванов.",["race:Orc"]="Регтар Врата Смерти считает уничтожение военачальников Колкар необходимым для безопасности дороги между Перекрестком и Когтистыми горами для путников из Дуротара.",["race:Tauren"]="Колкар поколениями охотились на кочевых тауренов и донимали их на этих равнинах, поэтому казнь таких вожаков, как Верог, — долгожданное возмездие."},sec={{t="Выманить Дервиша",b="После падения Барака Кодобана орк-воин Регтар Врата Смерти обращает взор на оставшихся военачальников племени Колкар. В отличие от Барака, открыто стоявшего у северных вод Забытых прудов, Верог Дервиш бродит по выжженным солнцем равнинам и редко подолгу остается в одном лагере. Выслеживать его на огромной территории было бы бесполезно, поэтому у разведчиков Орды остается один путь: заставить командира прийти самому."},{t="Застывший оазис",b="Верог действует из командного пункта кентавров у Застывшего оазиса, к юго-востоку от Перекрестка. Регтар велит приключенцам напасть прямо на лагерь и рубить воинов Колкар у командного шатра, пока паника не вынудит протрубить в рог. Тактика обращает гордость кентавров против них самих: перебейте достаточно подчиненных Верога на их земле, и Дервиш поспешит защищать свой лагерь, прямо навстречу клинкам Орды."}},faq={{q="Кто такой Верог Дервиш?",a="Верог Дервиш — кочующий военачальник кентавров Колкар в Степях. Он руководит действиями из Застывшего оазиса, но много времени проводит в странствиях по южным пустошам, поэтому загнать его в угол непросто.",al={"who is verog","verog lore","verog the dervish","кто такой верог","верог предания","верог дервиш"}},{q="Почему Верог не сидит в своем лагере?",a="Верный своему прозвищу «Дервиш», Верог — кочевой вожак, который бродит по безлюдным просторам Степей, а не сидит на месте в одном лагере. Из-за подвижности он в безопасности от организованных отрядов Орды, и врагам приходится вынуждать его показаться.",al={"where is verog","why does verog roam","verog missing","где верог","почему верог кочует","верог пропал"}},{q="Как вызвать Верога?",a="Верог возвращается на командный пункт, когда его племени грозит опасность. Нападая на кентавров вокруг заметного командного шатра у Застывшего оазиса, приключенцы устраивают такой хаос, что уцелевшие Колкар поднимают тревогу, и Верог мчится защищать свой шатер.",al={"how to spawn verog","find verog","verog not showing up","как вызвать верога","найти верога","верог не появляется"}},{q="Кто приказывает убить Верога?",a="Убить Верога приказывает Регтар Врата Смерти, орк-ветеран, стоящий лагерем к западу от Перекрестка у главной дороги в Когтистые горы. Он стремится сломить хребет Колкар, методично истребляя каждого из их областных командиров.",al={"who gives the quest","regthar deathgate","кто выдает задание","регтар врата смерти"}},{q="Что происходит после гибели Верога?",a="Принеся Регтару отрубленную голову Верога, вы позволяете орку добавить ее в свою коллекцию рядом с головой Барака Убийцы Кодо. Затем Регтар нацеливается на Хэрзула Кровавую Отметину, кентавра-полководца, который управляет Цветущим оазисом на юге.",al={"what comes next","after verog","что дальше","после верога"}},{q="Почему кентавры Колкар — такая проблема в Степях?",a="Колкар — агрессивные, территориальные хищники, захватившие жизненно важные источники воды по всем Степям. Их частые набеги на караваны, форпосты и стада местных тауренов делают их прямой смертельной угрозой для молодого присутствия Орды в центральном Калимдоре.",al={"why fight kolkar","kolkar threat","зачем воевать с колкар","угроза колкар"}}},fp="17,270,23.494.0,18.475.0,25.225.0,35.281.0,24.287.0,25.245.0,31.231.1,57.269.0"}
P.entries["quest:852"] = {n="Хэрзул Кровавая Отметина",s="Хэрзул Кровавая Отметина — задание, которое дает орк-ветеран Регтар Врата Смерти: уничтожить верховного военачальника кентавров Колкар в Степях. Забрав голову Хэрзула у Цветущего оазиса, Орда намерена раз и навсегда разрушить командную иерархию захватчиков.",h="Хэрзул Кровавая Отметина — задание, которое дает орк-ветеран Регтар Врата Смерти: уничтожить верховного...",kw={"bloodmark","centaur","crossroads","deathgate","hezrul","kolkar","lushwater","oasis","regthar","кровавая отметина","кентавр","перекресток","врата смерти","хэрзул","колкар","цветущий оазис","оазис","регтар"},ang={["faction:Horde"]="Чтобы удержать Перекресток и Степи, нужно сломить власть кентавров над тремя крупными оазисами, на которых держатся путешествия по региону.",["race:Orc"]="Регтар Врата Смерти рассматривает бой с Колкарами через призму орочьей войны: кентавры свирепы, но их дикой ярости недостает железной дисциплины, выкованной Ордой.",["race:Tauren"]="Поколениями кочевые таурены страдали от жестоких изгнаний и кровопролития от рук кентавров; уничтожение таких военачальников, как Хэрзул, приносит заслуженное возмездие."},sec={{t="Обезглавить Колкаров",b="После гибели Барака Кодобейна и Верога Дервиша среди Колкаров Степей остался лишь один верховный вождь — Хэрзул Кровавая Отметина. Регтар Врата Смерти называет Хэрзула жестоким и хитрым предводителем, который направляет набеги кентавров по всей саванне. Убийство Хэрзула должно посеять хаос и необратимо расколоть их ряды: у и без того буйного зверя отсекают голову, прежде чем он успеет захлестнуть поселения Орды."},{t="Оплот у Цветущего оазиса",b="Хэрзул командует своими отрядами из Цветущего оазиса к югу от Перекрестка. Контроль над немногочисленными водопоями Степей необходим для выживания, поэтому оазис служит стратегическим центром и сборным пунктом набегов Колкаров. Сразившись с Хэрзулом на его земле, защитники Орды лишают кентавров главного оплота и разрывают их хватку на южных тропах региона."},{t="Опасные последствия",b="Регтар хвалит победу над Хэрзулом и замечает, что кентаврам не хватает собранной дисциплины орков, но убийство не усмирило клан. Вместо того чтобы мирно разойтись, разъяренные Колкары собирают оставшиеся силы и в отчаянии начинают полномасштабный штурм лагеря Регтара, жаждя кровавой мести."}},faq={{q="Кто такой Хэрзул Кровавая Отметина?",a="Хэрзул Кровавая Отметина — верховный вождь кентавров Колкар в Степях. Орда считает его свирепым, хитрым и жестоким: он руководит кланами и налетчиками из своего оплота у Цветущего оазиса.",al={"who is hezrul","hezrul bloodmark lore","centaur leader barrens","кто такой хэрзул","хэрзул кровавая отметина предание","предводитель кентавров степи"}},{q="Где найти Хэрзула Кровавую Отметину?",a="Хэрзул патрулирует южные Степи у берегов Цветущего оазиса к югу от Перекрестка в окружении телохранителей Колкаров.",al={"where is hezrul","hezrul location","where to find hezrul","где хэрзул","местонахождение хэрзула","где найти хэрзула"}},{q="Кто выдает задание убить Хэрзула?",a="Задание дает Регтар Врата Смерти, орк-воин, стоящий в небольшом лагере к западу от Перекрестка у дороги к Когтистым горам.",al={"who gives hezrul bloodmark","regthar deathgate quest","quest giver hezrul","кто дает хэрзул кровавая отметина","задание регтара врата смерти","кто выдает задание хэрзул"}},{q="Почему Орда хочет смерти Хэрзула?",a="Колкары постоянно угрожают торговым путям и поселениям Орды. Регтар считает, что гибель верховного вождя расколет единство клана и резко снизит его способность вести согласованную войну.",al={"why kill hezrul","hezrul bloodmark purpose","kolkar threat barrens","зачем убивать хэрзула","цель хэрзула кровавой отметины","угроза колкаров степи"}},{q="Что происходит после гибели Хэрзула?",a="Вместо того чтобы сдаться, уцелевшие Колкары в слепой ярости объединяются и сразу контратакуют аванпост Регтара Врата Смерти к западу от Перекрестка.",al={"counterattack after hezrul","what happens next","consequences of killing hezrul","контратака после хэрзула","что будет дальше","последствия убийства хэрзула"}},{q="Как Хэрзул связан с Бараком и Верогом?",a="Барак Кодобейн и Верог Дервиш были подчиненными вождями Колкаров и отвечали за отдельные оазисы и отряды, а Хэрзул Кровавая Отметина был верховным предводителем, командовавшим всем кланом в Степях.",al={"barak verog hezrul","kolkar chieftains","three centaur leaders","барак верог хэрзул","вожди колкаров","три предводителя кентавров"}}},fp="16,272,23.452.0,24.397.0,21.356.1,24.230.0,36.136.0,35.148.0,36.221.0,35.164.1,42.210.0"}
P.entries["quest:853"] = {n="Аптекарь Зама",s="Это поручение отправляет искателя приключений из засушливых Степей в Громовой Утес с нестабильной вываренной грибной эмульсией. Аптекарь Хелбрим просит быстро доставить сильнодействующую смесь своей коллеге, аптекарю Заме, скрывающейся в темных глубинах под Вершиной Духов.",h="Это поручение отправляет искателя приключений из засушливых Степей в Громовой Утес с нестабильной вываренной...",kw={"apothecary helbrim","apothecary zamah","fungal spores","pools of vision","rendered spores","royal apothecary society","spirit rise","the barrens","thunder bluff","аптекарь хелбрим","аптекарь зама","грибные споры","пруды видений","вываренные споры","королевское фармацевтическое общество","вершина духов","степи","громовой утес"},ang={["faction:Horde"]="Быстрая связь между аванпостами в Степях и высоким плато Громового Утеса поддерживает связность региональных поставок.",["race:Tauren"]="Приветствуя новых союзников, традиционные таурены нередко косо смотрят на странные булькающие снадобья, которые Отрекшиеся варят в глубине священных Прудов Видений.",["race:Undead"]="Доставка работы Хелбрима Заме укрепляет тайную сеть исследований, которую Королевское фармацевтическое общество держит на пыльной границе центрального Калимдора."},sec={{t="Хрупкий груз",b="Изучив необычные грибные образования, растущие у оазисов Степей, аптекарь Хелбрим выварил партию в тонкую эмульсию. Нестабильное варево быстро портится после приготовления. Не имея времени самому отправиться в Мулгор, Хелбрим доверяет флакон надежному посыльному, чтобы тот поднялся на утесы, пока раствор не утратил свои свойства."},{t="Под взглядами шаманов",b="Аптекарь Зама держит лабораторию вдали от открытых равнин Мулгора, уединившись в Прудах Видений. Эта подземная пещера лежит глубоко под священной Вершиной Духов, где обитают скрытные чернокнижники и погруженные в размышления провидцы. Здесь, под землей святилища тауренов, Королевское фармацевтическое общество тихо ведет исследования с сырьем, собранным по всему континенту."}},faq={{q="Почему у этой доставки есть ограничение по времени?",a="Вываренная грибная эмульсия Хелбрима химически нестабильна. Если оставить ее открытой или необработанной слишком надолго, соединения распадаются и теряют силу, и смесь становится бесполезной для работы Замы.",al={"why timed","quest timer","rendered spores timer","почему на время","таймер задания","таймер спор"}},{q="Где найти аптекаря Заму?",a="Аптекарь Зама находится в Прудах Видений в Громовом Утесе. Вход в пещеру скрыт на Вершине Духов и ведет вниз, под шатры шаманов.",al={"where is zamah","zamah location","find zamah","где зама","местонахождение замы","найти заму"}},{q="Кто такой аптекарь Хелбрим?",a="Аптекарь Хелбрим — алхимик Королевского фармацевтического общества, находящийся на Перекрестке в Степях. Он изучает местную флору и фауну, чтобы понять, как коренные организмы Калимдора могут пригодиться Отрекшимся.",al={"who is helbrim","helbrim crossroad","кто такой хелбрим","хелбрим перекресток"}},{q="Что делает Королевское фармацевтическое общество в Громовом Утесе?",a="Как союзники в Орде, Отрекшиеся размещают представителей, таких как Зама, в Громовом Утесе. Тихо работая в подземных Прудах Видений, они изучают образцы, собранные по всему Калимдору, и поддерживают связи снабжения с другими аванпостами.",al={"why forsaken in thunder bluff","apothecaries in pools of vision","почему отрекшиеся в громовом утесе","аптекари в прудах видений"}},{q="Для чего изначально использовались грибные споры?",a="Споры растут вокруг цветущих оазисов Степей, неестественно разрастаясь в пустыне. Хелбрим выварил их, чтобы изучить биологические свойства и алхимическое применение, прежде чем передать Заме.",al={"why spores","barrens fungi use","зачем споры","применение грибов степей"}},{q="Что будет, если время истечет?",a="Если время истечет, эмульсия испортится. Вам придется вернуться к аптекарю Хелбриму на Перекресток за новой партией для доставки в Громовой Утес.",al={"failed timer","spores expired","время вышло","споры испортились"}}},fp="16,277,15.372.0,30.416.0,43.195.0,34.185.0,26.219.0,60.243.0,48.214.0,35.165.0"}
P.entries["quest:854"] = {n="Путешествие в Перекресток",s="Путешествие в Перекресток — важный обряд посвящения для юных искателей приключений Орды, покидающих мирные луга Мулгора. По указанию тауренского мистика Кирджа Жесткого Рога в Лагере Таурахо путники отправляются на север, в Перекресток, чтобы помочь орку-надсмотрщику Торку. Это момент, когда новичок выходит на широкую сцену границ Калимдора.",h="Путешествие в Перекресток — важный обряд посвящения для юных искателей приключений Орды, покидающих мирные...",kw={"barrens","camp taurajo","crossroads","earthmother","kirge sternhorn","thork","thunder bluff","степи","лагерь таурахо","перекресток","мать-земля","кирдж жесткий рог","торк","громовой утес"},ang={["faction:Horde"]="Задание показывает углубляющееся сотрудничество между племенами Громового Утеса и авангардом вождя в центральном Калимдоре.",["race:Orc"]="Торк с нетерпением ждет подкреплений с юга, чтобы удержать хрупкие позиции, которые разведчики Тралла закрепили в Степях.",["race:Tauren"]="Для тауренов-искателей приключений это путешествие означает настоящий уход из-под защиты священной возвышенности Матери-Земли в более широкую борьбу Орды."},sec={{t="Покидая колыбель",b="Для многих тауренов, покидающих родной Мулгор, Лагерь Таурахо — первое настоящее знакомство с суровыми, продуваемыми ветрами равнинами Степей. Сразу за горным перевалом от Мулгора мистик Кирдж Жесткий Рог присматривает за путниками, спускающимися в эти сухие луга. Видя их растущие способности, Жесткий Рог направляет многообещающих героев дальше на север по пыльному торговому пути, а не медлить на окраине."},{t="Общая связь",b="Задание подчеркивает важную связь между тауренами Громового Утеса и новой Ордой Тралла. Кирдж отмечает, что судьбы обоих народов теперь переплетены, а оркам, отчаянно создающим аванпост на Перекрестке, нужны подкрепления. Добравшись до аванпоста, Торк тепло встречает путников, пришедших даже с высоких утесов и готовых испытать свои силы в опасностях саванны."}},faq={{q="Кто дает задание «Путешествие в Перекресток»?",a="Задание дает Кирдж Жесткий Рог, таурен из Лагеря Таурахо на юге Степей, к востоку от горного перевала из Мулгора.",al={"who gives this quest","quest giver","kirge sternhorn quest","кто дает это задание","персонаж, выдающий задания","задание кирджа жесткого рога"}},{q="Где находится Торк?",a="Торк стоит за стенами частокола Перекрестка — главного поселения Орды в Степях, расположенного к северу от Лагеря Таурахо по главной дороге.",al={"where is thork","thork location","find thork","где торк","местонахождение торка","найти торка"}},{q="Почему Кирдж Жесткий Рог отправляет путников в Перекресток?",a="Кирдж чувствует, что искатель приключений готов к более серьезным испытаниям, и понимает, что судьбы тауренов и орков теперь переплетены. Орочий гарнизон на Перекрестке постоянно находится под угрозой местных опасностей и остро нуждается в способных союзниках.",al={"why go to crossroads","crossroads purpose","why send me to orcs","зачем идти в перекресток","цель перекрестка","зачем отправлять к оркам"}},{q="Что такое Перекресток?",a="Перекресток — главный стратегический центр и торговый пост Орды в центральном Калимдоре. Он построен там, где пересекаются главные пути с севера на юг и с запада на восток, и служит плацдармом для усмирения дикого пограничья.",al={"what is the crossroads","crossroads settlement","barrens hub","что такое перекресток","поселение перекресток","центр степей"}},{q="Только ли таурены получают это задание?",a="Хотя его выдает таурен в Лагере Таурахо и в нем упоминается путь из Громового Утеса, любой юный искатель приключений Орды, пришедший из Мулгора, может отправиться с докладом к Торку.",al={"is this quest tauren only","horde breadcrumb","только ли для тауренов это задание","начальное задание орды"}},{q="Какие опасности ждут на дороге к Перекрестку?",a="Дорога на север пролегает через засушливые равнины, где обитают агрессивные страусы-бегуны, бродящие саванные львы и кочующие отряды свинобразов из племени Иглогривых. Если держаться проторенной тропы, путники смогут избежать более территориальных хищников центральной саванны.",al={"is the road dangerous","taurajo to crossroads path","опасна ли дорога","путь от таурахо до перекрестка"}}},fp="25,350,18.434.0,13.437.0,37.151.0,23.155.0,58.252.0,23.228.0,33.203.0,52.245.0"}
P.entries["quest:855"] = {n="Наручи кентавров",s="«Наручи кентавров» — боевое задание на истребление, которое выдает Регтар Врата Смерти к западу от Перекрестка. Чемпионам Орды поручено проредить ряды агрессивных кентавров Колкар, оспаривающих власть над центральными Степями.",h="«Наручи кентавров» — боевое задание на истребление, которое выдает Регтар Врата Смерти к западу от...",kw={"barrens","bounty","bracers","centaur","crossroads","horde","kolkar","regthar deathgate","степи","награда","наручи","кентавр","перекресток","орда","колкар","регтар врата смерти"},ang={["faction:Horde"]="Зачистка Колкаров защищает важные линии снабжения между Оргриммаром и Громовым Утесом.",["race:Orc"]="Для орков защита границ Дуротара от кочевых налетчиков жизненно важна для создания постоянной и устойчивой новой родины.",["race:Tauren"]="Кентавры веками приносили тауренам разрушения и геноцид; сокращение их числа в Степях — личное возмездие."},sec={{t="Защита равнин",b="Молодая Орда ведет широкую борьбу за безопасные земли по всему Калимдору, а Степи служат важнейшим перекрестком между Дуротаром и Мулгором. Однако свирепые кочевые племена кентавров Колкар оспаривают каждый водопой и каждую равнину, нападая на обозы и разведывательные отряды. Из своего бункера к западу от Перекрестка орк-воин Регтар Врата Смерти руководит обороной, чтобы сдержать их неумолимый натиск."},{t="Мрачный подсчет",b="Регтар не довольствуется пустыми донесениями и требует осязаемых доказательств действий против конных племен. Солдатам, отправляющимся на земли Колкаров, поручено вернуться с отрубленными наручами, снятыми прямо с убитых воинов-кентавров. Этот мрачный подсчет служит и подтверждением для наград Орды, и расчетливым посланием, призванным запугать уцелевших налетчиков Колкар."}},faq={{q="Кто такой Регтар Врата Смерти?",a="Регтар Врата Смерти — орк, военный командир, стоящий в укрепленном бункере к западу от Перекрестка. Он возглавляет местные усилия Орды по подавлению разбойничьих банд кентавров в Степях.",al={"who is regthar","regthar deathgate lore","who gives centaur bracers","кто такой регтар","регтар врата смерти предания","кто выдает наручи кентавров"}},{q="Почему Орде нужны наручи кентавров?",a="Наручи кентавров служат неоспоримым вещественным доказательством убитых в бою вражеских воинов. Их сбор гарантирует, что награды выплачиваются только за реально нанесенные потери враждебным племенам Колкар.",al={"why bracers","what are centaur bracers for","why collect bracers","зачем наручи","для чего нужны наручи кентавров","зачем собирать наручи"}},{q="Почему Колкары нападают на Орду?",a="Колкары — жестокий экспансионистский клан кентавров, уроженцев центрального Калимдора. Они считают Степи своими охотничьими угодьями и яростно противятся новым поселениям, лагерям и союзам орков и тауренов.",al={"why do centaur hate horde","centaur conflict","kolkar aggression","почему кентавры ненавидят орду","конфликт с кентаврами","агрессия колкаров"}},{q="Где в Степях находятся кентавры Колкар?",a="Разбойничьи лагеря Колкаров сосредоточены вокруг важных оазисов и неприступных хребтов в центральных и южных Степях и часто оспаривают доступ к воде и путям сообщения.",al={"where to find centaurs","kolkar locations","centaur camps","где найти кентавров","расположение колкаров","лагеря кентавров"}},{q="Прекратит ли сбор этих наручей нападения Колкаров?",a="Нет. Регтар надеется, что истребление послужит предупреждением для уцелевших налетчиков, но открыто сомневается, что свирепые Колкары когда-нибудь добровольно прекратят свой кровожадный натиск.",al={"did centaur bracers work","do the centaur stop","помогли ли наручи кентавров","остановятся ли кентавры"}},{q="Какова стратегическая ценность Перекрестка?",a="Перекресток — главный транспортный узел, соединяющий родину орков Дуротар, равнины тауренов Мулгор и северные пути в Ясеневый лес. Уничтожение ближайших боевых отрядов кентавров необходимо, чтобы сохранить линии снабжения Орды.",al={"why defend crossroads","crossroads importance","зачем защищать перекресток","значение перекрестка"}}},fp="15,207,19.444.0,21.381.0,25.196.0,40.215.0,39.224.0,53.175.0,54.179.0,46.235.0"}
P.entries["quest:8569"] = {n="Былые сражения в Ущелье Песни Войны",s="«Былые сражения в Ущелье Песни Войны» — военная благодарность, которую сдают офицерам в столицах в знак службы на передовой. Она чествует не полную победу, а ветеранов, доблестно сражавшихся и жертвовавших собой в спорных чащах Ясеневого леса. Городские командиры принимают эти знаки, чтобы поддерживать боевой дух и награждать преданность в обеих фракциях.",h="«Былые сражения в Ущелье Песни Войны» — военная благодарность, которую сдают офицерам в столицах в знак...",kw={"ashenvale","brigadier general","orgrimmar","past efforts","ribbon of sacrifice","stormwind","warbringer","warsong gulch","ясеневый лес","бригадный генерал","оргриммар","былые сражения","лента жертвенности","штормград","вестник войны","ущелье песни войны"},ang={["class:Warrior"]="Бойцы передовой, пережившие жестокую рукопашную в ущелье, лучше всех понимают, что истинная дисциплина — это яростно сражаться, даже когда исход битвы висит на волоске.",["faction:Alliance"]="Для сил Альянса передача лент бригадному генералу подтверждает клятву защищать древние леса и поддерживать союзников-ночных эльфов против агрессии Песни Войны.",["faction:Horde"]="Для Орды передача знаков Вестникам войны в городах доказывает, что кровь, пролитая ради древесины и выживания в Ясеневом лесу, была пролита не напрасно."},sec={{t="Честь павшим и доблестным",b="Война между Среброкрылыми Часовыми и Всадниками Песни Войны редко приносит чистые и легкие победы. На южных границах Ясеневого леса стычки жестоки, кровавы и часто заканчиваются без решающего триумфа. Понимая, что боевой дух не может зависеть только от безупречного успеха, командиры в Штормграде, Оргриммаре и других столицах учредили награды за стойкую службу. Лента Жертвенности чтит тех, кто бросался в бой вопреки любым шансам."},{t="Военные усилия в тылу",b="Столичные чины, такие как бригадные генералы Альянса и Вестники войны Орды, руководят мобилизацией далеко от линии фронта. Пока вербовщики направляют новобранцев на поля сражений вроде Ущелья Песни Войны, интенданты и тактики должны заботиться о вернувшихся бойцах, перенесших изнурительные кампании. Признавая личную храбрость и жертвы в безрезультатных боях и поражениях, руководство добивается, чтобы солдаты передовой оставались преданы делу удержания Ясеневого леса."}},faq={{q="Для чего нужна эта благодарность?",a="Благодарность отмечает бойцов передовой, отдавших все в сражениях в Ущелье Песни Войны. Столичные командиры принимают доказательства героической борьбы, чтобы вознаградить стойкость и поддерживать боевой дух по всему миру.",al={"why do past efforts","past efforts purpose","what does past efforts mean","зачем былые сражения","назначение былых сражений","что значат былые сражения"}},{q="Кто принимает эти знаки жертвы?",a="Их принимают старшие военные представители в крупных городах: бригадные генералы Альянса в таких местах, как Штормград, и Вестники войны Орды в таких городах, как Оргриммар.",al={"who takes past efforts","where to turn in past efforts","who is the brigadier general","кто принимает былые сражения","где сдать былые сражения","кто такой бригадный генерал"}},{q="Почему военные награждают за усилия, не приведшие к победе?",a="Командиры понимают, что непрерывные бои в чащах Ясеневого леса берут тяжелую дань. Награда за преданность и стойкость напоминает бойцам, что их кровь и жертвы ценят, даже если исход битвы не стал полной победой.",al={"why reward ribbon of sacrifice","why reward loss","heroic effort meaning","зачем награждать лентой жертвенности","зачем награждать за поражение","значение героических усилий"}},{q="Где происходит конфликт в Ущелье Песни Войны?",a="Ущелье Песни Войны лежит на южной границе Ясеневого леса, где орки из Всадников Песни Войны заготавливают лес, сталкиваясь с яростным сопротивлением ночных эльфов из Среброкрылых Часовых.",al={"where is warsong gulch","warsong gulch location","what is warsong gulch","где ущелье песни войны","расположение ущелья песни войны","что такое ущелье песни войны"}},{q="Могут ли выполнить это и Альянс, и Орда?",a="Да. Обе фракции имеют равноценное военное командование в своих столицах, чтобы чествовать солдат, возвращающихся из кровавых лесорубных стычек в Ясеневом лесу.",al={"is this both factions","horde or alliance past efforts","can horde turn this in","для обеих фракций","былые сражения орда или альянс","может ли орда сдать это"}},{q="Что символизирует Лента Жертвенности?",a="Лента Жертвенности — знак, который вручают бойцам, пережившим яростные схватки в Ущелье Песни Войны, или который они носят, свидетельствуя о несгибаемой готовности сражаться за свой народ.",al={"ribbon of sacrifice lore","what is ribbon of sacrifice","sacrifice ribbon","предания ленты жертвенности","что такое лента жертвенности","лента жертвы"}}},fp="29,385,35.488.0,22.456.0,41.222.0,38.174.0,66.243.0,52.191.0,58.169.0,44.199.0"}
P.entries["quest:857"] = {n="Слеза Лун",s="Высоко над южными Степями безумный дворф Фиглай Изгнанник требует вернуть таинственную реликвию, найденную в Бейл Модане. Артефакт, известный как Слеза Лун, довел Фиглая до безумия и одержимости, прежде чем генерал Двукосса запер его как проклятую вещь дурного предзнаменования.",h="Высоко над южными Степями безумный дворф Фиглай Изгнанник требует вернуть таинственную реликвию, найденную в...",kw={"bael modan","barrens","dwarf curse","feegly","feegly the exiled","general twinbraid","tear of the moons","бейл модан","степи","проклятие дворфа","фиглай","фиглай изгнанник","генерал двукосса","слеза лун"},ang={["faction:Horde"]="Налет на Бейл Модан ради возвращения реликвии дает Орде возможность сорвать операции дворфов, посягающих прямо на Степи."},sec={{t="Найдено в Бейл Модане",b="Когда дворфы-старатели из Лиги исследователей начали вгрызаться в холмы южного Калимдора, строя Бейл Модан, Слеза Лун стала их первой крупной находкой. Хотя раскопки должны были проследить древнее наследие титанов, странный артефакт сразу оказал мощное и тревожное влияние на Фиглая, одного из рабочих экспедиции."},{t="Карантин Двукоссы",b="Фиглай утверждал, что Слеза дала ему огромную личную силу, и яростно набросился на товарищей, защищая свою добычу. Поняв, что реликвия развращает, генерал Двукосса объявил ее проклятой, вырвал из рук Фиглая и спрятал в крепости. Изгнанный из лагеря раскопок, Фиглай укрылся среди утесов, изводясь горькой одержимостью и умоляя странников выкрасть ее обратно."},{t="Страшная цена",b="Предостережения Двукоссы оказались куда буквальнее, чем думал Фиглай. Едва Фиглай вернул Слезу Лун, его радость оборвалась: скрытая магия реликвии преображения поглотила его. Вместо славы артефакт жестоко превратил дворфа в дикого трогга, и жизнь его оборвалась через секунды после возвращения сокровища."}},faq={{q="Что такое Слеза Лун?",a="Это древняя могущественная реликвия, найденная дворфами-раскопщиками во время первых раскопок в Бейл Модане в южных Степях. Она оказывает опьяняющее, развращающее воздействие на тех, кто к ней прикасается.",al={"what is tear of the moons","tear of the moons relic","bael modan artifact","что такое слеза лун","реликвия слеза лун","артефакт бейл модана"}},{q="Кто такой Фиглай Изгнанник?",a="Фиглай когда-то был раскопщиком в экспедиции генерала Двукоссы в Бейл Модане. После обнаружения Слезы Лун Фиглай стал одержимым и жестоким, и Двукосса изгнал его из крепости.",al={"who is feegly","feegly lore","feegly dwarf","кто такой фиглай","фиглай предания","фиглай дворф"}},{q="Почему генерал Двукосса запирает Слезу?",a="Генерал Двукосса счел артефакт опасным проклятием, а не безобидной исторической находкой. Увидев, как Фиглай набросился на товарищей-раскопщиков, Двукосса надежно запер реликвию в крепости Бейл Модана.",al={"why twinbraid locked tear","twinbraid curse","bael modan keep relic","почему двукосса запер слезу","проклятие двукоссы","реликвия в крепости бейл модана"}},{q="Что будет, если вернуть Слезу Фиглаю?",a="Возвращение реликвии доводит одержимость Фиглая до предела. Последствия раскрываются, когда он завладевает ею.",al={"what happens to feegly","feegly ending","return the tear"}},{q="Понятна ли магия Слезы до конца?",a="Генерал Двукосса называет ее проклятой, а Фиглай жаждет силы, которую она, по его мнению, дает. Задание не объясняет, как действует магия реликвии.",al={"tear magic","tear of the moons curse","how does the tear work","магия слезы","проклятие слезы лун","как действует слеза"}},{q="Почему это задание Орды, если Фиглай — дворф?",a="Фиглай — изгой, прячущийся в Степях и презирающий силы Альянса, занявшие Бейл Модан. Поскольку искатели приключений Орды враждебны раскопкам Двукоссы, Фиглай просит их совершить набег на крепость и вернуть артефакт.",al={"why horde quest","is feegly horde","bael modan horde","почему задание орды","фиглай из орды","бейл модан орда"}}},fp="21,290,23.375.0,22.417.0,17.336.1,30.194.0,25.209.0,46.232.0,48.116.1,37.149.1,47.238.0"}
P.entries["quest:858"] = {n="Зажигание",s="Задание «Зажигание» начинается, когда искатель приключений находит агента, запертого в крошшере Торговой Компании в северных Степях. Пилот импульсивно угнал машину без ключа зажигания, и ему нужен тот, кто достанет ключ у начальника участка, пока его не раскрыли.",h="Задание «Зажигание» начинается, когда искатель приключений находит агента, запертого в крошшере Торговой...",kw={"derrick","ignition","ignition key","ratchet","shredder","sputtervalve","the barrens","venture company","wizzlecrank","буровая вышка","зажигание","ключ зажигания","кабестан","крошшер","пароклапан","степи","торговая компания","зизгаг"},ang={["faction:Horde"]="Безрассудная вырубка лесов Торговой Компанией угрожает северным границам Степей, поэтому любая диверсия или кража их тяжелой техники для Орды — желанная помеха.",["profession:Engineering"]="Механика крошшера Торговой Компании поражает изощренностью: точные органы управления манипулятором и чуткие регуляторы поворота превосходят обычные поделки Кабестана."},sec={{t="Ограбление пошло наперекосяк",b="Глубоко в оживленных буровых владениях Торговой Компании в северных Степях амбициозное ограбление наткнулось на досадную помеху. Агент, посланный от имени Пароклапана, пробрался в один из новейших крошшеров корпорации, намереваясь завладеть машиной и изучить ее устройство. Однако вор упустил важную деталь: рулевая колонка заблокирована наглухо без особого ключа зажигания."},{t="Блеф под давлением",b="Когда подозрительный коллега-гоблин спросил, почему только что занятый крошшер стоит без движения, чужак запаниковал и соврал про внезапную поломку двигателя. Запертый под стеклянным колпаком, пока рядом бродят любопытные рабочие, угонщик направляет прибывающих искателей приключений проникнуть в центральную буровую вышку. Начальник участка хранит запасные ключи зажигания в верхней диспетчерской — это единственный выход, пока блеф не раскрыт."},{t="Корпоративная зависть",b="Когда с начальником участка покончено, а ключ повернут на панели, вор не смущен, а очарован. Управление крошшера Торговой Компании — с рычагами точного движения манипулятора, поворотом и стабилизаторами — намного превосходит неуклюжие машины, работающие сейчас в Кабестане. Вернуть крошшер теперь нужно не только ради спасения: это бесценный трофей промышленного шпионажа."}},faq={{q="Кто сидит в крошшере?",a="Крошшером управляет агент, связанный с Пароклапаном, инженером, живущим в нейтральном портовом городке Кабестан. Пилот проник в хозяйство Торговой Компании, чтобы украсть одну из ее передовых машин для расчистки леса.",al={"shredder pilot","who is in wizzlecrank shredder","wizzlecrank","пилот крошшера","кто в крошшере","зизгаг"}},{q="Почему крошшер не может просто уехать?",a="Колонка управления крошшера механически заблокирована без ключа зажигания. Хотя угонщик забрался в кабину, машина не может ни маневрировать, ни скрыться, пока ключ не разблокирует управление.",al={"why need key","why stuck","shredder locked","зачем нужен ключ","почему застрял","крошшер заблокирован"}},{q="Где найти ключ зажигания?",a="Ключ зажигания у начальника участка Торговой Компании, который руководит лесозаготовкой. Он находится в диспетчерской на вершине большой деревянной буровой вышки неподалеку.",al={"ignition key location","where is supervisor","how to find key","где ключ зажигания","где начальник участка","как найти ключ"}},{q="Зачем Кабестану крошшер Торговой Компании?",a="У Торговой Компании есть инженерные разработки, значительно превосходящие обычные модели инженеров Кабестана. Захват целой машины позволит местным механикам разобрать принцип работы ее точных манипуляторов, регуляторов скорости и систем стабилизации.",al={"why steal shredder","ratchet shredder","sputtervalve shredder","зачем красть крошшер","крошшер кабестана","крошшер пароклапана"}},{q="Кто такой Пароклапан?",a="Пароклапан — гоблин-инженер и агент из Кабестана, который следит за хищнической экспансией Торговой Компании и стремится заполучить ее технические новинки.",al={"sputtervalve identity","who sent wizzlecrank","sputtervalve ratchet","кто такой пароклапан","кто послал зизгага","пароклапан кабестан"}},{q="Что происходит после запуска крошшера?",a="Поворот ключа разблокирует систему движения и сразу запускает лихорадочное сопровождение: пилот пытается вывести угнанную машину из враждебного лесозаготовительного лагеря в безопасное место.",al={"what next ignition","after ignition key","ignition follow up","что дальше после зажигания","после ключа зажигания","продолжение задания"}}},fp="8,297,21.453.0,23.447.0,18.419.1,27.234.0,41.212.0,32.204.0,49.259.0,20.170.0,43.200.1"}
P.entries["quest:86"] = {n="Пирог для Билли",s="«Пирог для Билли» — поручение, попавшее под перекрестный огонь давней вражды семей Стоунфилд и Маклюр из Элвиннского леса. Юный Билли Маклюр не выдаст сведений о пропавшем ожерелье Тетушки Бернис Стоунфилд без пирога со свиной грудинкой. Искателям приключений предстоит поохотиться на местных кабанов, чтобы добыть мясо, из которого Бернис испечет требуемую взятку.",h="«Пирог для Билли» — поручение, попавшее под перекрестный огонь давней вражды семей Стоунфилд и Маклюр из...",kw={"bernice stonefield","billy maclure","elwynn forest","lost necklace","maclure vineyards","pork belly pie","stonefield farm","tender boar meat","бернис стоунфилд","билли маклюр","элвиннский лес","пропавшее ожерелье","виноградники маклюров","пирог со свиной грудинкой","ферма стоунфилдов","нежное мясо кабана"},ang={["profession:Cooking"]="Тетушка Бернис отмечает, что мясо дикого кабана бывает жестким и пресным, но с правильными специями и медленным томлением оно становится превосходной начинкой для пирога.",["race:Human"]="Эта склока показывает упрямую замкнутую вражду, процветающую среди сельских хозяев Элвинна к югу от ворот Штормграда."},sec={{t="Взятка от мальчишки",b="Когда его спрашивают о краже фамильного ожерелья Тетушки Бернис Стоунфилд, Билли Маклюр не выказывает раскаяния, которого ждут от старших. Вместо того чтобы вернуть вещь или признаться, мальчишка пользуется случаем утолить аппетит. Он требует свежеиспеченный пирог со свиной грудинкой, прежде чем скажет хоть слово о том, у кого ожерелье, прекрасно зная, что Тетушка Бернис — лучшая кухарка в долине."},{t="Выпечка вопреки вражде",b="Маклюры и Стоунфилды поколениями обменивались оскорблениями, драками и обвинениями через тыквенные грядки. Несмотря на глубокое возмущение тем, что приходится кормить сорванца, укравшего семейные украшения, Тетушка Бернис соглашается растопить печь. За нежное мясо кабанов, бродящих по соседним пастбищам, она поступается гордостью, чтобы умилостивить буйного юнца и вернуть свое сокровище."}},faq={{q="Почему Билли хочет пирог до разговора?",a="Билли Маклюр — расчетливый деревенский мальчишка, использующий свое знание о пропавшем ожерелье Тетушки Бернис как рычаг. Зная, что Бернис печет превосходные пироги со свиной грудинкой, он отказывается назвать владельца реликвии, пока не наестся.",al={"why billy wants pie","billy bribe pie","billy pork belly pie","зачем билли пирог","взятка билли пирогом","пирог билли со свиной грудинкой"}},{q="Почему Тетушка Бернис соглашается печь для вора?",a="Тетушка Бернис в ярости от того, что приходится награждать мальчишку, которого считает похитителем ожерелья, но другого способа вернуть его не видит. Получив мясо кабана, она неохотно соглашается испечь пирог, ставя возвращение вещи выше гордости.",al={"why does bernice bake","bernice stonefield pie reason","stonefield baking for maclure","почему бернис печет","причина пирога бернис стоунфилд","стоунфилды пекут для маклюров"}},{q="Откуда берется мясо для пирога?",a="Мясо добывают у диких кабанов, которые кормятся на лугах и окраинах вокруг ферм Стоунфилдов и Маклюров в Элвиннском лесу.",al={"where to get meat","tender boar meat source","где взять мясо","источник нежного мяса кабана"}},{q="Какова история отношений между Стоунфилдами и Маклюрами?",a="Семьи Стоунфилд и Маклюр — соседи-фермеры, годами ведущие злую, мелочную вражду: они постоянно подозревают друг друга в кражах, порче имущества и недобросовестных склоках на границах участков.",al={"stonefield maclure feud","farm rivalry","maclure vs stonefield","вражда стоунфилдов и маклюров","вражда ферм","маклюры против стоунфилдов"}},{q="Действительно ли Билли украл ожерелье?",a="Тетушка Бернис прямо обвиняет Билли, и хотя он уходит от прямого признания, он явно знает, где оказалась реликвия, и меняет этот секрет на еду.",al={"did billy steal necklace","who took necklace","billy necklace thief","украл ли билли ожерелье","кто взял ожерелье","билли вор ожерелья"}},{q="Что происходит после того, как Бернис получает мясо?",a="Получив нежное мясо кабана, Тетушка Бернис печет пирог со свиной грудинкой, который вы относите Билли, чтобы он наконец рассказал, у кого ее ожерелье.",al={"next step after pie","what follows pie for billy","что после пирога","что дальше пирог для билли"}}},fp="13,365,13.436.0,24.422.0,41.237.0,50.262.0,42.126.0,57.222.0,38.174.0,41.161.0"}
P.entries["quest:860"] = {n="Сергра Черный Шип",s="Проявив в холмах Мулгора базовые навыки выслеживания и подкрадывания, молодые таурены направляются в засушливые дали Степей. Мелор Каменное Копыто отправляет начинающих охотников на север, к границе, доложиться Сергре Черный Шип на Перекрестке. Это путешествие знаменует официальный переход охотника от местных испытаний к суровой иерархии хищников на широких равнинах Калимдора.",h="Проявив в холмах Мулгора базовые навыки выслеживания и подкрадывания, молодые таурены направляются в...",kw={"crossroads","hunter's way","melor stonehoof","mulgore","plainstrider","sergra darkthorn","the barrens","thunder bluff","перекресток","путь охотника","мелор каменное копыто","мулгор","долгонога","сергра черный шип","степи","громовой утес"},ang={["class:Hunter"]="Это путешествие — выпуск из простого выслеживания местной дичи к овладению навыками борьбы с агрессивными хищниками и суровыми условиями внутренних саванн Калимдора.",["race:Tauren"]="Для тауренов, выросших на зеленых пастбищах Мулгора, явка к Сергре — первый значительный шаг за родные границы, на трудную службу в составе всей Орды."},sec={{t="Прочь от священных холмов",b="Для начинающего охотника-тауренна первые обряды в Мулгоре — лишь начало. Тучные долины родной земли защищены и знакомы, их звери испытывают скорее терпение, чем способность выжить. Мелор Каменное Копыто понимает, когда дух охотника окреп настолько, что требует более суровых испытаний. Он велит ученикам собрать снаряжение, покинуть безопасную Деревню Кровавого Копыта и отправиться на восток через горный перевал в выжженные заросли Степей."},{t="Дорога к Перекрестку",b="Путь через каньоны красных скал ведет прямо в широкую, иссушенную солнцем саванну, где молодая Орда утверждает свои права. На пересечении центральных торговых путей Калимдора лежит Перекресток — укрепленное поселение, кишащее орками, троллями и таурены. Там ждет Сергра Черный Шип, опытная орчанка-шаманка, известная своей непреклонной строгостью. Она наставляет каждого, кто осмелится охотиться на свирепых зверей Степей, обещая закалить необузданный пыл в суровую дисциплину дикой природы."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Мелор Каменное Копыто, наставник охотников-тауренов, живущий на Вершине Охотников в Громовом Утесе.",al={"who gives sergra darkthorn quest","melor stonehoof location","where to start","кто дает задание сергры черный шип","где мелор каменное копыто","с чего начать"}},{q="Где находится Сергра Черный Шип?",a="Сергра Черный Шип стоит на Перекрестке в центральных Степях, у восточной части поселения, возле сторожевых башен и загонов.",al={"sergra darkthorn location","where is sergra","find sergra","где сергра черный шип","где сергра","найти сергру"}},{q="Как добраться до Перекрестка из Мулгора?",a="Выйдите из Громового Утеса на юг мимо Деревни Кровавого Копыта, затем по восточной дороге покиньте Мулгор через каньон в Степи. Миновав пограничные ворота, идите по главной грунтовой дороге на восток до развилки, затем на север — до Перекрестка.",al={"directions to crossroads","mulgore to barrens","how to get to crossroads from thunder bluff","как пройти к перекрестку","из мулгора в степи","как добраться до перекрестка из громового утеса"}},{q="Для чего нужно это задание?",a="Это подводящее задание, направляющее игроков, начавших путь в Мулгоре, к следующему крупному центру развития на Перекрестке в Степях и связывающее их с местными цепочками заданий охотников.",al={"why do this quest","sergra darkthorn purpose","is this a breadcrumb","зачем это задание","цель сергры черный шип","это подводящее задание"}},{q="Получают ли это задание орки и тролли?",a="Орки и тролли получают параллельное подводящее задание «Новобранец Орды» в Дуротаре, которое отправляет их из Колючего Холма в Степи, хотя по прибытии они тоже могут встретить Сергру и брать у нее задания.",al={"orc version","troll version","durotar breadcrumb","версия для орков","версия для троллей","подводящее задание дуротара"}},{q="Чему Сергра Черный Шип учит охотников?",a="Sergra tests incoming hunters against the indigenous fauna of the Barrens, starting with plainstriders and prowlers, teaching that true mastery requires endurance, respect for the land, and mental resilience rather than brute force.",al={"sergra role","what does sergra do","sergra hunting","роль сергры","что делает сергра","охота сергры"}}},fp="16,405,24.484.0,26.510.0,46.110.0,34.154.0,44.263.0,34.198.0,34.217.0,41.232.0"}
P.entries["quest:861"] = {n="Путь охотника",s="Путь охотника — обряд посвящения для начинающих следопытов в Мулгоре, который предлагает старейшина Скорн Белое Облако. Чтобы доказать свое растущее мастерство и уважение к природе, странники должны убить хитрых хищников плоскогорья и принести их когти Мелору Каменному Копыту на Вершине Охотников в Громовом Утесе.",h="Путь охотника — обряд посвящения для начинающих следопытов в Мулгоре, который предлагает старейшина Скорн...",kw={"flatland prowler","flatland prowler claws","hunter rise","melor stonehoof","mulgore","skorn whitecloud","the hunter's way","thunder bluff","хищник плоскогорья","когти хищника плоскогорья","вершина охотников","мелор каменное копыто","мулгор","скорн белое облако","путь охотника","громовой утес"},ang={["class:Hunter"]="Испытание напрямую проверяет основы жизни в дикой природе: умение выследить хищника из засады прежде, чем он нападет, и читать тонкие знаки лугов.",["faction:Horde"]="Этот обряд помогает союзным странникам Орды понять благоговение тауренов перед природой и заслужить их доверие на высотах Громового Утеса.",["race:Tauren"]="Для молодых тауренов принести когти хищников на Вершину Охотников — основополагающий обряд посвящения, связывающий их с поколениями предков, охотившихся на этих же широких равнинах."},sec={{t="Традиция равнин",b="Для тауренов охота — не просто забава и не только способ прокормиться, а одна из высших почестей их народа. Она требует терпения, понимания равновесия Матери-Земли и уважения к зверям, бродящим по холмистым равнинам. Старейшина Скорн Белое Облако, отдыхающий в Мулгоре после десятилетий странствий по Калимдору, узнает это беспокойство в юных искателях приключений. Вместо того чтобы позволить им бесцельно скитаться, он направляет их стремления в традиционное испытание зрелости и дисциплины."},{t="Охотники лугов",b="Чтобы доказать, что их охотничье чутье подлинно, кандидатам поручено убить хищников плоскогорья Мулгора. Эти большие кошки быстры, скрытны и хитры; они нападают из засады и легко сливаются с высокой травой равнин. Добыв четыре набора когтей, начинающий странник доказывает, что способен заметить хищника прежде, чем станет его добычей, обратив ярость охотника против него самого."},{t="Путь к Вершине Охотников",b="Добыв трофеи, посвящаемый поднимается по высоким деревянным башням и мостам к Громовому Утесу. Там, на Вершине Охотников, когти принимает Мелор Каменное Копыто. Как опытный следопыт, ценящий древнюю мудрость Скорна Белого Облака, Каменное Копыто принимает дар как доказательство того, что у посвящаемого верный дух, чтобы идти дальше по тропам хищников Калимдора."}},faq={{q="Кто дает задание пройти Путь охотника?",a="Задание дает Скорн Белое Облако, почтенный таурен-странник равнин, отдыхающий в Мулгоре и наставляющий молодых искателей приключений, желающих постичь дикую природу.",al={"quest giver","who gives the quest","skorn whitecloud","персонаж, выдающий задания","кто дает задание","скорн белое облако"}},{q="Куда отнести когти хищников плоскогорья?",a="Отнесите когти Мелору Каменному Копыту, который живет на Вершине Охотников в столице тауренов — Громовом Утесе.",al={"where is melor stonehoof","turn in location","hunter rise","где мелор каменное копыто","где сдать задание","вершина охотников"}},{q="Почему в качестве дани выбраны когти хищников плоскогорья?",a="Хищники плоскогорья — скрытные и опасные верховные хищники лугов Мулгора. Выследив и победив их, посвящаемый доказывает, что обладает острым глазом, терпением и боевой дисциплиной, необходимыми для искусной охоты.",al={"why flatland prowlers","prowler claws lore","what are prowlers","почему хищники плоскогорья","предания о когтях хищников","кто такие хищники"}},{q="Только ли классу Охотник доступно это задание?",a="Нет. Несмотря на название, Скорн Белое Облако предлагает это испытание воли любому молодому искателю приключений из Орды, жаждущему странствовать и узнавать традиции равнин.",al={"hunters only?","can other classes do this","is it for hunters","только охотники","могут ли другие классы","для охотников ли это"}},{q="Куда ведет путь охотника после разговора с Мелором?",a="Когда Мелор Каменное Копыто признает ваш зарождающийся талант, он начнет направлять вас в более суровые края Степей и со временем отправит к опытным следопытам, таким как Сергра Черный Шип.",al={"what comes next","next quest","where to go after melor","что дальше","следующее задание","куда идти после мелора"}},{q="Какое значение имеет охота в культуре тауренов?",a="По верованиям тауренов, охота — одна из высших почестей. Она требует жить в прямой гармонии с творением Матери-Земли, брать лишь необходимое и глубоко уважать добычу, которая кормит их племена.",al={"tauren hunting lore","hunting honor tauren","why is hunting important to tauren","охота у тауренов","почет охоты таурены","почему охота важна для тауренов"}}},fp="16,291,25.509.0,30.399.0,20.391.0,45.165.0,43.105.0,53.238.0,50.170.0,61.211.1,54.224.0"}
P.entries["quest:862"] = {n="Крысиная похлебка",s="Крысиная похлебка — кулинарное задание Грязнули, орка, разбившего лагерь к востоку от Перекрестка в Степях. Чтобы утолить зверский аппетит, Грязнуля отправляет голодных искателей приключений на юг, к раскопкам дворфов в Бейл Модане, собрать упитанных землекопных крыс для сомнительной похлебки.",h="Крысиная похлебка — кулинарное задание Грязнули, орка, разбившего лагерь к востоку от Перекрестка в Степях.",kw={"bael modan","barrens","cooking","crossroads","dig rat stew","dwarves","grub","rats","бейл модан","степи","кулинария","перекресток","крысиная похлебка","дворфы","грязнуля","крысы"},ang={["faction:Horde"]="Выкрасть землекопных крыс из Бейл Модана — приятный способ поглумиться над раскопками дворфов и заодно разжиться провизией в южных Степях.",["profession:Cooking"]="Приготовление крысиной похлебки учит основам добычи пропитания в глуши, превращая досадных карьерных вредителей в сытную, хоть и дурно пахнущую еду у костра.",["race:Undead"]="Пристрастие Грязнули давать мясу гнить неделями перед варкой делает его одним из немногих живых поваров, чьи вкусы совпадают со вкусами Отрекшихся."},sec={{t="Лакомства Степей",b="Выжить в засушливых просторах Степей можно, лишь не будучи привередливым. Пока опытные охотники добывают жевр, равнинных бегунов и ящеров, орк-одиночка Грязнуля пристрастился к подземным грызунам. Утверждая, что голоден целыми днями, он обещает поделиться своим рецептом с любым путником, готовым к недостойной работе по ловле крыс."},{t="Дворфийские вредители",b="Источник этих тварей — Бейл Модан, обширные раскопки Альянса в глубине южных Степей. Пока дворфы-старатели вгрызаются в красную землю в поисках древних реликвий, их глубокие выработки невольно подняли гнезда плодовитых землекопных крыс. Дворфы видят в мелких грызунах нашествие, а Грязнуля считает кишащих тварей пиром, который нельзя упустить, прямо под носом у врага."},{t="Дело вкуса",b="Приготовление крысиной похлебки требует крепкого желудка. По словам Грязнули, грызуны вкуснее всего, если дать им гнить несколько недель, чтобы проявился резкий вкус. Хотя для голодного искателя приключений он довольствуется более свежими тушками, его приемы показывают, насколько грубой и нетребовательной бывает придорожная кухня на рубежах Калимдора."}},faq={{q="Кто такой Грязнуля?",a="Грязнуля — эксцентричный орк, живущий у тропы к востоку от Перекрестка в Степях. Он всегда голоден, известен своими странными вкусами и охотно учит путешественников готовить местных вредителей.",al={"grub","who is grub","orc east of crossroads","грязнуля","кто такой грязнуля","орк к востоку от перекрестка"}},{q="Откуда берутся землекопные крысы?",a="Землекопные крысы кишат в Бейл Модане, раскопках Альянса на дальнем юге Степей, к югу от Лагеря Таурахо и к северу от Лабиринтов Иглошкурых. Грубые горные работы дворфов потревожили землю и привлекли полчища этих мелких тварей.",al={"where are dig rats","dig rat location","find dig rats","где землекопные крысы","где найти землекопных крыс","найти крыс"}},{q="Почему Грязнуле нужны именно землекопные крысы?",a="Грязнуля считает их «любимым лакомством всех и каждого» и утверждает, что охота на вредителей — обряд посвящения для любого бывалого искателя приключений. Он использует их как основу своей сытной, хоть и резкой на вкус похлебки.",al={"why rats","why dig rats","grub motivation","почему крысы","почему землекопные крысы","мотивация грязнули"}},{q="Крысиная похлебка действительно вкусная?",a="По меркам Грязнули — восхитительна, но вкусы у него весьма крайние. Он открыто признает, что предпочитает мясо, которое несколько недель гнило ради усиления вкуса, так что блюдо — на любителя даже по суровым меркам Орды.",al={"does the stew taste good","eating dig rats","grub recipe flavor","вкусна ли похлебка","есть крыс","вкус рецепта грязнули"}},{q="Почему в Бейл Модане есть дворфы?",a="Дворфы Бейл Модана принадлежат к Лиге исследователей Альянса и роют глубокие траншеи в Степях в поисках древних артефактов титанов и подземной истории. Их присутствие усилило напряженность с Ордой и растревожило местных вредителей.",al={"dwarves in the barrens","why bael modan","alliance southern barrens","дворфы в степях","почему бейл модан","южные степи альянса"}},{q="Нужна ли особая кулинарная подготовка, чтобы приготовить похлебку?",a="Для уроков Грязнули нужно базовое знакомство с очажной готовкой и разделкой туш. Любой, кто пробовал простую готовку, освоит его способ варки грызунов в сытную еду.",al={"cooking requirement","do i need cooking skill","требования к кулинарии","нужен ли навык кулинарии"}}},fp="12,278,18.378.0,18.428.0,18.371.0,12.222.0,28.250.0,41.201.0,37.237.0,36.255.0,55.200.0"}
P.entries["quest:863"] = {n="Бегство",ang={["faction:Horde"]="Загрязняющая нефтедобыча Торговой Компании в Нефтяном болоте — бельмо на глазу Степей, поэтому любая диверсия приветствуется местными племенами.",["profession:Engineering"]="Прототип крошшера демонстрирует передовую пневматику и конструкцию кабины Торговой Компании, так что его утилизация — золотая жила промышленных знаний.",["race:Gnome"]="Готовность Зизгага пилотировать крайне неустойчивую машину Торговой Компании наугад показывает, что гоблинские мастера, как и гномьи, часто сначала мастерят, а потом задают вопросы."},sec={{t="Неуклюжий побег",b="Having ignited the stolen prototype deep within the Sludge Fen drill site, Wizzlecrank quickly discovers that commandeering Venture Company engineering is easier said than done. With only a rudimentary grasp of the control levers and switches, the goblin lurches the heavy machine across the muddy quarry floor. His erratic driving and roaring mechanical joints inevitably alert nearby laborers and armed guards, turning what should have been a stealthy extraction into a chaotic running battle up the western ramp of the excavation pit."},{t="Погоня Торговой Компании",b="Торговая Компания не прощает кражу своих прототипов. Пока машина карабкается по склону к открытой местности, отряды наемников компании выдвигаются, чтобы перехватить и вывести из строя беглую конструкцию. Хотя прототип отбивается, неуклюжая махина не выдержит согласованной диверсии без сторонней охраны. Когда край котлована пройден, машина выбирается из основной буровой впадины, но вскоре после этого выходит из строя."},{t="Спасение и расплата",b="Once out of the immediate danger zone, the prototype shredder breaks down entirely and collapses onto the savanna turf. Wizzlecrank scrambles out alive, instructing his rescuers to report to Sputtervalve in Ratchet while he stays behind with the wreckage. Sputtervalve, desperate to dissect the Venture Company's cutting-edge designs before his window of opportunity closes, immediately mobilizes a goblin salvage squad to haul whatever intact mechanisms survive back to port."}},faq={{q="Who is Wizzlecrank and why is he inside a shredder?",a="Wizzlecrank is an operative and mechanic working with Sputtervalve in Ratchet. He infiltrated the Venture Company's northern drill site to steal their latest experimental shredder prototype, but ended up trapped inside while figuring out the unfamiliar cockpit controls.",al={"who is wizzlecrank","why is goblin in shredder","wizzlecrank shredder"}},{q="Где происходит это бегство?",a="Сопровождение начинается в глубине Нефтяного болота — загрязненной промышленной буровой площадки Торговой Компании в северных Степях, к северу от сухой саванной котловины.",al={"where is the escape quest","escape location","sludge fen escort","где задание бегство","место бегства","сопровождение нефтяное болото"}},{q="Нужно ли сопровождать крошшер до самого Кабестана?",a="No. You only escort Wizzlecrank out of the drill pit depression and up the western ramp. Once safely away from the quarry rim, the machine breaks down and Wizzlecrank tells you to report back to Ratchet on your own.",al={"how far do i walk","escort path","do you go to ratchet","как далеко идти","путь сопровождения","идти ли до кабестана"}},{q="Кто такой Пароклапан?",a="Пароклапан — гоблин-техник, находящийся возле доков Кабестана. Он руководит промышленной разведкой против соперницы, Торговой Компании, и добивается ее механических разработок, чтобы нажиться на технологических новинках.",al={"who is sputtervalve","turn in npc sputtervalve","sputtervalve lore","кто такой пароклапан","пароклапан сдать задание","предания о пароклапане"}},{q="Почему крошшер в конце ломается?",a="Wizzlecrank is barely familiar with the controls and the experimental machine is pushed to its limits during the ambush. It suffered severe mechanical strain breaking through the perimeter, causing the prototype to give out as soon as it cleared the drill site.",al={"why shredder break","shredder wrecked","prototype failure","почему крошшер сломался","крошшер разбит","отказ прототипа"}},{q="Что происходит после аварии прототипа?",a="Wizzlecrank stays with the downed machine while you report to Sputtervalve in Ratchet. Sputtervalve immediately prepares a goblin salvage team to harvest the prototype's high-value components before the Venture Company can reclaim them.",al={"salvage crew","what happens next","escape quest conclusion","бригада спасателей","что дальше","завершение задания бегство"}}},fp="10,410,16.537.0,23.516.0,18.476.1,51.270.0,34.173.0,58.215.1,20.227.0,43.261.1,41.236.1"}
P.entries["quest:8642"] = {n="Старейшина Среброжил",s="Старейшина Среброжил — почитаемый дух предка, который появляется во время Лунного фестиваля на холмах над Телсамаром в Лок Модане. Путники выражают ему почтение, чтобы отдать дань древним узам между старшими народами Азерота. В благодарность за то, что его присутствие и наследие признают, он дарует свое благословение предков.",h="Старейшина Среброжил — почитаемый дух предка, который появляется во время Лунного фестиваля на холмах над...",kw={"ancestor","coin of ancestry","elder","loch modan","lunar festival","silvervein","thelsamar","предок","монета наследия","старейшина","лок модан","лунный фестиваль","среброжил","телсамар"},ang={["faction:Alliance"]="Путникам Альянса в Лок Модане подъем на хребет над Телсамаром дает тихую передышку от охоты на троггов, чтобы почтить древних умерших.",["race:Dwarf"]="Старейшина Среброжил отдыхает прямо рядом с поселением дворфов Телсамар и разделяет искреннюю связь с суровым горным народом и его почтением к древней истории."},sec={{t="Бдение над Телсамаром",b="Старейшина Среброжил стоит на пологих хребтах над Телсамаром как тихий страж и напоминание о глубокой древности. Как почитаемая во время Лунного фестиваля фигура, он олицетворяет неугасающую память минувших эпох. Даже когда окрестности Лок Модана борются с вторжениями троггов и местными распрями, Среброжил спокойно наблюдает со своего возвышения."},{t="Почитание древних народов",b="Духи вроде Среброжила помогают преодолеть разрыв между современными народами и древними родами. Когда искатели приключений приходят к нему, он выражает благодарность за то, что путники до сих пор чтят древние народы Азерота. Его приветствие несет тепло родовой признательности, а в память о встрече он дарует памятный знак тем, кто воздает ему честь."}},faq={{q="Кто такой Старейшина Среброжил?",a="Старейшина Среброжил — дух предка, который является во время Лунного фестиваля. Весь праздник он проводит на высоких утесах возле Телсамара в Лок Модане.",al={"silvervein","who is silvervein","elder silvervein loch modan","среброжил","кто такой среброжил","старейшина среброжил лок модан"}},{q="Где найти Старейшину Среброжила?",a="Он находится на травянистом холме над городком Телсамар в Лок Модане.",al={"silvervein location","where is elder silvervein","find silvervein","где среброжил","где старейшина среброжил","найти среброжила"}},{q="Зачем искать Старейшину Среброжила?",a="Во время Лунного фестиваля искатели приключений приходят к нему, чтобы выразить почтение предкам и древним народам, и получают в ответ праздничный знак и благословение.",al={"why visit silvervein","what does silvervein do","silvervein purpose","зачем идти к среброжилу","что делает среброжил","зачем нужен среброжил"}},{q="Что он имеет в виду под «древними народами»?",a="Он говорит о древних народах Азерота, которые жили и формировали мир задолго до современных конфликтов, и чтит непреходящий дух их наследия.",al={"olden races meaning","why olden races","древние народы значение","почему древние народы"}},{q="Дружелюбен ли Старейшина Среброжил к путникам из Орды?",a="Да. Старейшины предков, которых чтят во время Лунного фестиваля, приветствуют путников любого происхождения, если они приходят с миром, чтобы почтить предков.",al={"can horde talk to silvervein","horde silvervein","может ли орда говорить со среброжилом","орда среброжил"}},{q="Связан ли Старейшина Среброжил с вторжением троггов?",a="Нет. Хотя Лок Модан страдает от набегов троггов и бед, связанных с раскопками, Старейшина Среброжил остается в стороне от местных военных конфликтов и занят лишь почитанием предков.",al={"silvervein troggs","is silvervein fighting troggs","среброжил трогги","сражается ли среброжил с троггами"}}},fp="20,324,22.358.0,24.340.0,24.162.0,34.83.0,52.158.0,39.170.0,48.134.0,64.186.0"}
P.entries["quest:8646"] = {n="Старейшина Молотозвон",sec={{t="Почитание древней крови",b="During the Lunar Festival, the spirits of revered ancestors manifest across Azeroth, offering wisdom and blessings to any traveler who takes time to pay their respects. Elder Hammershout appears in the Park district of Stormwind. Though he stands near the heart of modern human civilization, his appearance reminds passing adventurers of a time when the world was shaped by the ancient races who walked the land long before the kingdoms of today rose to prominence."},{t="Знаки почитания предков",b="Чтобы поприветствовать Старейшину Молотозвона, не нужны ни воинские испытания, ни опасные клятвы — достаточно простого признания прошлого. Он тихо радуется и благодарит, когда нынешние жители королевства по-прежнему находят время почтить древние народы. В обмен на этот акт памяти и уважения старейшина дарует путникам памятный знак, символ непрерывного общения ныне живущего поколения с духами тех, кто жил прежде."}},faq={{q="Кто такой Старейшина Молотозвон?",a="Elder Hammershout is an ancestral spirit who appears during the Lunar Festival. He represents the ancient lineages of Azeroth and stands in Stormwind to offer blessings and tokens to those who honor him.",al={"hammershout","who is hammershout","elder hammershout identity","молотозвон","кто такой молотозвон","кто старейшина молотозвон"}},{q="Где найти Старейшину Молотозвона?",a="Elder Hammershout appears in the Park district of Stormwind during the Lunar Festival.",al={"hammershout location","where is hammershout","hammershout elwynn","где молотозвон","молотозвон местоположение","молотозвон элвиннский лес"}},{q="Почему Старейшина Молотозвон говорит о «древних народах»?",a="Его слова отражают то, что Лунный фестиваль славит древность и почитание предков, воздавая честь древним народам и традициям, которые формировали Азерот задолго до появления современных поселений.",al={"olden races meaning","what does hammershout mean","древние народы значение","что значит молотозвон"}},{q="Какой знак предлагает Старейшина Молотозвон?",a="Он предлагает Монету Наследия — памятный знак, который духи Лунного фестиваля даруют тем, кто разыскивает старейшин и выражает им почтение.",al={"hammershout reward","hammershout token","what does he give","награда молотозвона","знак молотозвона","что он дает"}},{q="Могут ли искатели приключений из Орды говорить со Старейшиной Молотозвоном?",a="Yes. Ancestral spirits during the Lunar Festival transcend factional warfare, though Horde travelers must tread carefully given his location inside the Alliance capital of Stormwind.",al={"can horde talk to hammershout","hammershout horde","может ли орда говорить с молотозвоном","молотозвон орда"}},{q="Связана ли эта встреча с действующим праздником?",a="Старейшина Молотозвон является только во время ежегодного Лунного фестиваля: он ненадолго появляется, чтобы даровать благословения, и вновь исчезает в мире духов.",al={"is hammershout always there","lunar festival elder","молотозвон всегда там","старейшина лунного фестиваля"}}},fp="21,329,22.465.0,29.457.0,25.203.0,37.86.0,53.199.0,40.146.0,51.182.0,44.151.0"}
P.entries["quest:8648"] = {n="Старейшина Черносерд",s="Старейшина Черносерд — сезонное задание Лунного фестиваля в Подгороде. Разыскав Старейшину Черносерда, путники выражают почтение древним духам, которых чтят по всему Азероту, и получают Монету Наследия.",h="Старейшина Черносерд — сезонное задание Лунного фестиваля в Подгороде.",kw={"ancestor","coin of ancestry","darkcore the elder","elder darkcore","elders","lunar festival","undercity","предок","монета наследия","старейшина черносерд","старейшины","лунный фестиваль","подгород"},ang={["faction:Horde"]="Старейшина Черносерд позволяет членам Орды принять участие в обрядах Лунного фестиваля, проходящих на всем континенте, прямо в безопасной столице союзников.",["race:Undead"]="Для Отрекшихся, бредущих по руинам своего бывшего королевства, Старейшина Черносерд — жуткое напоминание о давних временах до Плети и падения Лордерона."},sec={{t="Дух в Подгороде",b="Во время Лунного фестиваля по всем континентам появляются духи древних предков — ночных эльфов и земных существ, — чтобы поделиться мудростью и благословениями. Старейшина Черносерд обитает в сумрачных залах Подгорода: он свидетельствует о современном мире и вспоминает о былом с теми, кто ищет корни мира."},{t="Почитание предков",b="Подойти к Старейшине Черносерду — значит исполнить древний обычай выражать уважение почтенным мертвым и вечным стражам Азерота. В знак этого паломничества дух дарит путникам Монету Наследия как знак доброй воли и непреходящей памяти."}},faq={{q="Зачем посещать Старейшину Черносерда?",a="Посетив Старейшину Черносерда во время Лунного фестиваля, искатели приключений могут почтить древние народы Азерота. Разговор с ним завершает задание и приносит Монету Наследия.",al={"elder darkcore goal","why visit darkcore","darkcore quest purpose","цель старейшины черносерда","зачем идти к черносерду","задание черносерд"}},{q="Где найти Старейшину Черносерда?",a="Старейшина Черносерд появляется в разрушенном тронном зале Лордерона, над столицей Отрекшихся — Подгородом.",al={"elder darkcore location","where is elder darkcore","darkcore undercity spot","старейшина черносерд где","где старейшина черносерд","черносерд подгород"}},{q="Что такое Лунный фестиваль?",a="Лунный фестиваль — ежегодное время памяти и обновления по всему Азероту: им отмечают победу над Пылающим Легионом и чтят древних старейшин, направлявших смертные расы.",al={"lunar festival lore","why are elders appearing","what are the elders","лунный фестиваль предания","почему появляются старейшины","кто такие старейшины"}},{q="Что олицетворяют старейшины?",a="Старейшины — древние духи, как правило связанные с ночными эльфами или ранними земными культурами. Во время Лунного фестиваля они появляются, чтобы благословить тех, кто помнит их деяния и хранит уроки древности.",al={"who are the elders","lunar festival elders lore","ancestor spirits","кто такие старейшины","старейшины лунного фестиваля предания","духи предков"}},{q="Могут ли искатели приключений из Альянса говорить со Старейшиной Черносердом?",a="Старейшина Черносерд приветствует любого путника, которому удалось до него добраться, но игрокам Альянса для этого придется пройти через сильно охраняемую столицу Отрекшихся.",al={"alliance darkcore","can alliance get darkcore","elder darkcore alliance","альянс черносерд","может ли альянс получить черносерда","старейшина черносерд альянс"}},{q="Что такое Монета Наследия?",a="Монета Наследия — праздничный знак, который старейшины дарят во время Лунного фестиваля. Она символизирует почтение к древности, и ее можно обменять на праздничные наряды и сезонные памятные вещицы.",al={"what are coins of ancestry","coin of ancestry use","lunar festival coin","что такое монеты наследия","монета наследия применение","монета лунного фестиваля"}}},fp="18,238,25.321.0,22.257.0,47.185.0,34.109.0,27.202.0,29.211.0,49.147.0,27.173.0"}
P.entries["quest:8649"] = {n="Старейшина Штормоскал",s="Старейшина Штормоскал — один из древних духов, которых чествуют во время Лунного фестиваля. Он стоит у воды возле Златоземья. Путники, которые разыскивают этого старейшину, отдают дань древним традициям и стародавним расам Азерота. В ответ на проявленное уважение старейшина дарит небольшой памятный знак.",h="Старейшина Штормоскал — один из древних духов, которых чествуют во время Лунного фестиваля.",kw={"ancestor","elder stormbrow","elwynn forest","forge","goldshire","lunar festival","token","предок","старейшина штормоскал","элвиннский лес","кузница","златоземье","лунный фестиваль","знак"},ang={["faction:Alliance"]="Старейшина Штормоскал отдыхает в самом сердце Элвиннского леса и является одним из самых доступных духов предков для юных искателей приключений Альянса, проходящих через Златоземье.",["race:Human"]="Для людей, живущих в Элвинне, присутствие Старейшины Штормоскала напоминает о древней истории, лежащей за стенами и недавними войнами Штормграда."},sec={{t="Дух в Златоземье",b="Старейшина Штормоскал появляется у тихого пруда прямо за кузницей в Златоземье. Обычно город полон стражников в доспехах, торговцев и усталых искателей приключений, идущих в лес, но появление почтенного духа приносит тихую паузу. Стоя под мирным пологом Элвиннского леса, Штормоскал приветствует каждого, кто готов почтить долгую историю этого края."},{t="Почтение стародавним расам",b="Лунный фестиваль — время, когда духи великих предков возвращаются, чтобы пройти среди живых. Старейшина Штормоскал хвалит смертных путников за то, что они находят время вспомнить тех, кто жил до них. В обмен на признание мудрости и наследия древних народов он дарует свое благословение и памятную монету в честь праздника."}},faq={{q="Где найти Старейшину Штормоскала?",a="Старейшина Штормоскал стоит у пруда прямо за кузницей в Златоземье, в Элвиннском лесу.",al={"stormbrow location","where is elder stormbrow","goldshire elder","где штормоскал","где найти старейшину штормоскала","старейшина златоземья"}},{q="Кто такой Старейшина Штормоскал?",a="Старейшина Штормоскал — дух предков, который появляется во время Лунного фестиваля и представляет почитаемых старейшин стародавних рас Азерота.",al={"who is stormbrow","stormbrow lore","elder stormbrow identity","кто такой штормоскал","предания о штормоскале","старейшина штормоскал кто это"}},{q="Зачем посещать Старейшину Штормоскала?",a="Посетив Старейшину Штормоскала, путники могут во время фестиваля почтить древних предков. В ответ на уважение к этим традициям он передает свои приветствия и знак признательности.",al={"why visit stormbrow","elder stormbrow quest","stormbrow the elder purpose","зачем идти к штормоскалу","задание старейшины штормоскала","цель штормоскала"}},{q="Могут ли игроки Орды говорить со Старейшиной Штормоскалом?",a="Хотя старейшины Лунного фестиваля чтят всех, кто мирно приходит к ним, Златоземье — хорошо охраняемая территория Альянса, и любой визит туда для путников Орды крайне опасен.",al={"horde stormbrow","can horde visit stormbrow","орда штормоскал","может ли орда посетить штормоскала"}},{q="Какой знак дарит старейшина?",a="Старейшина Штормоскал дарит Монету Наследия — традиционный знак уважения и памяти, который старейшины раздают на протяжении фестиваля.",al={"stormbrow reward","what token","lunar coin stormbrow","награда штормоскала","какой знак","лунная монета штормоскал"}},{q="Почему Штормоскал говорит о «стародавних расах»?",a="Штормоскал хвалит путников за то, что они помнят: нынешние цивилизации живут на землях, сформированных древними народами и прочными обычаями задолго до появления современных королевств.",al={"olden races meaning","why olden races","stormbrow dialogue","значение стародавних рас","почему стародавние расы","диалог штормоскала"}}},fp="19,300,21.389.0,24.344.0,33.124.0,23.140.0,48.197.0,43.176.0,32.131.0,45.177.0"}
P.entries["quest:865"] = {n="Рога ящера",ang={["class:Hunter"]="Охотники, знакомые со стаями ящеров Калимдора, хорошо понимают их смертоносную хитрость, но вера Мебока в то, что их ум можно разлить по бутылкам, — чистое гоблинское шарлатанство.",["faction:Alliance"]="Кабестан дает искателям приключений Альянса редкую нейтральную опору в Степях, где господствует Орда, и возможность заработать монету и расположение Картеля Хитрая Шестеренка на таких поручениях, как у Мебока."},sec={{t="Гоблинское предпринимательство",b="Кабестан полон гоблинов, ищущих очередное богатство, и Мебок Миззрикс не исключение. Заметив, что ящеры Степей отличаются необычной хитростью и согласованностью действий по сравнению со зверями в других краях, Мебок пришел к странному выводу: их ум должен быть сосредоточен в рогах. Разумеется, вместо серьезного научного исследования он тут же решил извлечь из этого предполагаемого ресурса выгоду."},{t="The Sunscale Scytheclaws",b="To test his theory, Mebok needs pristine specimens from Sunscale Scytheclaws, some of the deadliest predators in the region. These raptors prowl both the southern stretches of the Barrens and the northern borders approaching Ashenvale. Slaying them and extracting their horns undamaged requires considerable martial skill, as the beasts hunt in packs and defend their territory fiercely."},{t="Рецепт богатства",b="Заполучив рога, Мебок намерен действовать просто и грубо: растереть целые рога в мелкий порошок и сварить из него напитки. Назвав получившуюся смесь «умным напитком», он мечтает продавать ее посетителям, желающим купить остроумие в бутылке, и уверен, что мгновенно разбогатеет."}},faq={{q="Зачем Мебоку Миззриксу рога ящера?",a="Мебок считает, что исключительный ум ящеров Степей хранится в их рогах. Он собирается растереть их в порошок, сварить «умные напитки» и выгодно продать.",al={"why raptor horns","mebok goal","what does mebok want","зачем рога ящера","цель мебока","что нужно мебоку"}},{q="Where are Sunscale Scytheclaws located?",a="Sunscale Scytheclaws roam two distinct parts of the Barrens: the southern regions and the northern plains up near the border of Ashenvale Forest.",al={"where are scytheclaws","sunscale scytheclaw location","raptor horn location"}},{q="Правда ли, что рога ящеров магические или усиливают разум?",a="Хотя ящеры Степей известны своей хитростью, вера Мебока в то, что их мозг или остроумие находятся в рогах на черепе, — гоблинская псевдонаука, движимая лишь выгодой, а не знанием природы.",al={"do smart drinks work","are raptors smart","raptor intelligence lore","работают ли умные напитки","умны ли ящеры","разум ящеров"}},{q="Кто такой Мебок Миззрикс?",a="Мебок Миззрикс — честолюбивый гоблин-торговец из портового города Кабестан, всегда придумывающий сомнительные затеи и снадобья, чтобы нажиться на проезжих путниках.",al={"who is mebok","mebok mizzyrix lore","mebok ratchet","кто такой мебок","мебок миззрикс предания","мебок кабестан"}},{q="Что происходит после сбора рогов?",a="Получив целые рога, Мебок принимается растирать их в порошок и подмешивать в вино, что напрямую ведет к его следующей затее — «Умному напитку».",al={"next quest after raptor horns","smart drinks quest","raptor horns chain","следующее задание после рогов ящера","задание умный напиток","цепочка рога ящера"}},{q="Могут ли игроки Альянса помочь Мебоку с этим заданием?",a="Да. Кабестан — открытый порт под управлением Картеля Хитрая Шестеренка, а Мебок — нейтральный гоблин, охотно ведущий дела и с Ордой, и с Альянсом.",al={"is this quest horde only","alliance raptor horns","can alliance do raptor horns","задание только для орды","рога ящера альянс","может ли альянс взять рога ящера"}}},fp="12,248,23.452.0,24.387.0,19.329.1,42.198.0,39.145.0,52.197.0,22.172.0,40.162.1,47.157.0"}
P.entries["quest:8652"] = {n="Старейшина Могильник",s="Старейшина Могильный Холм — встреча Лунного фестиваля возле города Брилл в Тирисфальских лесах. Во время празднования путники ищут Старейшину Могильного Холма среди оскверненных рощ, чтобы почтить древних предков Азерота. Почтение этому духу приносит его благословение и праздничный знак.",h="Старейшина Могильный Холм — встреча Лунного фестиваля возле города Брилл в Тирисфальских лесах.",kw={"brill","coin of ancestry","elder graveborn","graveborn","lunar festival","tirisfal glades","брилл","монета наследия","старейшина могильный холм","могильный холм","лунный фестиваль","тирисфальские леса"},ang={["class:Druid"]="Друиды почитают старейшин Лунного фестиваля как связь с древним миром до Раскола, не обращая внимания на неспокойные границы фракций, где те обитают.",["faction:Alliance"]="Искателям приключений Альянса, ищущим Старейшину Могильного Холма, следует осторожно идти по Тирисфальским лесам: Брилл — сильно укрепленное убежище Отрекшихся.",["race:Undead"]="Для Отрекшихся, живущих в Брилле, появление древних духов предков — резкое напоминание о более глубокой истории Азерота за пределами недавних трагедий Плети."},sec={{t="Призрачное бдение в Брилле",b="Пока Отрекшиеся обитают среди разрушенных поместий и могил Тирисфальских лесов, Лунный фестиваль приносит неожиданное общение с древними временами. Старейшина Могильный Холм предстает призрачным старцем у самого Брилла. Даже в краю, разрушенном Плетью и отвоеванном нежитью, он приветствует паломников, которые останавливаются, чтобы почтить древние обычаи."},{t="Почтение стародавним расам",b="Лунный фестиваль — время, когда великие духи давно минувших эпох возвращаются, чтобы поделиться мудростью и благодарностью. Когда путники подходят к Старейшине Могильному Холму, он замечает, как отрадно, что жители Тирисфаля все еще чтят предков, несмотря на нынешнее запустение земли, и дарует Монету Наследия тем, кто его приветствует."}},faq={{q="Где находится Старейшина Могильный Холм?",a="Старейшину Могильного Холма можно найти возле поселения Брилл в Тирисфальских лесах: он тихо стоит у дороги за городом.",al={"elder graveborn location","where is graveborn","graveborn coords","где старейшина могильный холм","где могильный холм","координаты могильного холма"}},{q="Что происходит, если поговорить со Старейшиной Могильным Холмом?",a="Когда вы приветствуете его, Старейшина Могильный Холм хвалит вас за почтение к древним народам Азерота и дарит Монету Наследия в рамках празднования Лунного фестиваля.",al={"graveborn reward","lunar festival graveborn","what does he give you","награда могильного холма","лунный фестиваль могильный холм","что он дает"}},{q="Почему древний старейшина стоит в Тирисфальских лесах?",a="Во время Лунного фестиваля духи древних предков являются по всему Азероту — от лесов кальдораев до земель, истерзанных войной и чумой. Старейшина Могильный Холм охраняет северные пределы Лордерона, чтобы его история не была целиком затмена смертью.",al={"why is he in tirisfal","graveborn lore","who is elder graveborn","почему он в тирисфале","предания о могильном холме","кто такой старейшина могильный холм"}},{q="Могут ли игроки Альянса посетить Старейшину Могильного Холма?",a="Сам Старейшина Могильный Холм — нейтральный дух мудрости и говорит с представителями и Альянса, и Орды. Однако он находится прямо у города Отрекшихся Брилл, поэтому искателям приключений Альянса следует остерегаться местной стражи.",al={"can alliance talk to graveborn","alliance graveborn the elder","graveborn hostile","может ли альянс говорить с могильным холмом","альянс старейшина могильный холм","могильный холм враждебен"}},{q="Для чего нужна Монета Наследия?",a="Монеты Наследия, собранные у старейшин вроде Могильного Холма, во время Лунного фестиваля можно обменять на Лунной поляне на праздничную одежду, рецепты фейерверков и другие памятные знаки.",al={"coin of ancestry use","what are lunar coins for","применение монеты наследия","для чего лунные монеты"}},{q="Относится ли Старейшина Могильный Холм к Отрекшимся?",a="Нет. Несмотря на имя и призрачный облик возле Брилла, Старейшина Могильный Холм — один из древних духов, которых чествуют на Лунном фестивале, и принадлежит к давнему роду старейшин Азерота, а не к Отрекшимся Сильваны.",al={"is graveborn undead","is elder graveborn forsaken","нежить ли могильный холм","отрекшийся ли старейшина могильный холм"}}},fp="19,307,24.352.0,24.344.0,33.126.0,47.165.0,52.270.0,43.233.0,38.176.0,39.218.0"}
P.entries["quest:8653"] = {n="Старейшина Златоколодезь",s="Старейшина Златокладезь — задание Лунного фестиваля, которое выдает Старейшина Златокладезь в Караносе, Дун Морог. Почтение ему отражает непреходящую традицию поиска духов предков в заснеженных землях дворфов. В обмен на ваше уважение он дарует знак благословения предков.",h="Старейшина Златокладезь — задание Лунного фестиваля, которое выдает Старейшина Златокладезь в Караносе, Дун...",kw={"ancestor","coin of ancestry","dun morogh","elder goldwell","goldwell","ironforge","kharanos","lunar festival","thunderbrew","предок","монета наследия","дун морог","старейшина златокладезь","златокладезь","стальгорн","каранос","лунный фестиваль","громоварка"},ang={["faction:Alliance"]="Расположившись на безопасной территории Альянса, Златокладезь — один из самых легких для посещения старейшин для юных героев Альянса, идущих между Холодной долиной и Стальгорном.",["faction:Horde"]="Чтобы добраться до Златокладезя, нужно пробираться вглубь Дун Морога, рискуя встретить дворфийскую стражу и лютый холод у высоких врат Стальгорна.",["race:Dwarf"]="Для дворфов, возвращающихся из Стальгорна, встреча со старейшиной древнего рода у главной таверны в Караносе соединяет вечное почтение с гордостью за родные места."},sec={{t="Горное приветствие",b="Стоя на лютом холоде возле таверны «Громоварка» в Караносе, Старейшина Златокладезь присматривает за оживленной торговой дорогой к вратам Стальгорна. Во время Лунного фестиваля этот почтенный старец приветствует усталых путников, искателей приключений и местных жителей, воплощая долгую память о древних днях, когда первые смертные ходили под звездами Азерота."},{t="Почтение предкам",b="Подход к Златокладезю дарит минуту размышлений среди суровых зимних ветров Дун Морога. Он выражает облегчение и радость от того, что смертные все еще помнят древние расы и их деяния, и благодарит каждого, кто прерывает путь, чтобы выказать уважение. В ответ он вручает священную Монету Наследия как символ своего благословения."}},faq={{q="Где найти Старейшину Златокладезя?",a="Старейшина Златокладезь стоит прямо у таверны «Громоварка» в городке Каранос, на заснеженной дороге Дун Морога к юго-западу от врат Стальгорна.",al={"elder goldwell location","where is elder goldwell","goldwell spot","где старейшина златокладезь","местонахождение старейшины златокладезя","место златокладезя"}},{q="Зачем искать Старейшину Златокладезя?",a="К Старейшине Златокладезю приходят во время Лунного фестиваля, чтобы почтить древних духов мира. Выказав ему уважение, вы доказываете, что смертные расы не забыли жертвы и мудрость древности.",al={"why visit elder goldwell","what does elder goldwell do","goldwell quest","зачем идти к старейшине златокладезю","что делает старейшина златокладезь","задание златокладезя"}},{q="Какую награду дает Старейшина Златокладезь?",a="Он награждает путников Монетой Наследия — благословенным знаком от старейшин фестиваля, который можно предъявить Кругу Кенария на Лунной поляне в обмен на праздничные товары.",al={"elder goldwell reward","what do i get from elder goldwell","coin of ancestry goldwell","награда старейшины златокладезя","что получить от старейшины златокладезя","монета наследия златокладезь"}},{q="Доступно ли это задание путникам Орды?",a="Да. Старейшины фестиваля, такие как Златокладезь, — нейтральные духи предков, приветствующие искателей приключений любой фракции, хотя путникам Орды следует быть осторожными с бдительными горными дворфами, патрулирующими Каранос.",al={"can horde talk to elder goldwell","horde elder goldwell","is elder goldwell friendly to horde","может ли орда говорить со старейшиной златокладезем","орда старейшина златокладезь","дружелюбен ли златокладезь к орде"}},{q="Почему Старейшина Златокладезь обитает в Дун Мороге?",a="Старейшины Лунного фестиваля являются во всех уголках Азерота, где смертные цивилизации создали прочные общины. Златокладезь выбрал Каранос, чтобы делиться благословением с теми, кто живет близ сердца королевства дворфов.",al={"why is goldwell in kharanos","why dun morogh","goldwell dwarven land","почему златокладезь в каранос","почему дун морог","златокладезь земля дворфов"}},{q="Можно ли выполнить это задание более одного раза?",a="Нет. Почтение Старейшине Златокладезю оказывается один раз за сезон фестиваля: каждый искатель приключений, пришедший за советом, получает единственное благословение и одну монету.",al={"is elder goldwell repeatable","elder goldwell daily","goldwell reset","повторяется ли старейшина златокладезь","старейшина златокладезь ежедневно","сброс златокладезя"}}},fp="18,282,19.365.0,22.316.0,32.177.0,50.213.0,40.183.0,43.212.0,45.227.0,43.151.0"}
P.entries["quest:867"] = {n="Гарпии-налетчики",s="«Гарпии-налетчики» — одно из первых наступательных заданий, которое выдает Дарсок Быстрый Нож на Перекрестке, чтобы обуздать агрессивную стаю Зачарованного Крыла. Искатели приключений охотятся на обычных налетчиц и воровок перьев на северо-западе Степей и собирают когти, подрывая снабженческие набеги стаи.",h="«Гарпии-налетчики» — одно из первых наступательных заданий, которое выдает Дарсок Быстрый Нож на Перекрестке...",kw={"barrens","crossroads","darsok","harpy","roguefeather","swiftdagger","talons","witchwing","степи","перекресток","дарсок","гарпия","воровка перьев","быстрый нож","когти","зачарованное крыло"},ang={["class:Rogue"]="Стратегия Дарсока Быстрого Ножа близка убийцам: разведать цель, разобрать иерархию и устранять руководство по частям.",["faction:Horde"]="Безопасные внутренние пути через Степи необходимы, чтобы вновь основанные заставы получали припасы и оставались единым целым под знаменами Оргриммара."},sec={{t="Угроза с неба",b="Караваны, ползущие по пыльным тропам Степей, постоянно страдают от нападений диких зверей и свинобразов, но гарпии Зачарованного Крыла — особенно смертоносная угроза с воздуха. Эти свирепые создания налетают со скалистых утесов на северо-западе на торговые обозы и повозки с припасами, убивают вьючных животных и грабят важные грузы, предназначенные для застав орков."},{t="План Дарсока",b="Вместо беспорядочного нападения на горные гнезда орк-разбойник Дарсок Быстрый Нож несколько дней изучал повадки и иерархию стаи. Он знает, что неслаженный удар рассеет гарпий по ветрам. Чтобы окончательно сломить Зачарованное Крыло, Дарсок намерен планомерно истреблять стаю с низших рангов, начиная с передовых налетчиков, а затем перейти к их командирам."}},faq={{q="Почему Орда охотится на гарпий Зачарованного Крыла?",a="Стая Зачарованного Крыла гнездится на северо-западных утесах Степей и регулярно налетает на караваны снабжения Орды, идущие по главным тропам.",al={"why kill harpies","witchwing problem","why attack harpies","зачем убивать гарпий","проблема зачарованного крыла","зачем нападать на гарпий"}},{q="Кто такой Дарсок Быстрый Нож?",a="Дарсок — орк-разведчик и разбойник, расквартированный на Перекрестке. Он следит за местными угрозами и выяснил цепь подчинения в местной стае гарпий, чтобы организовать расчетливое истребление.",al={"darsok","darsok swiftdagger lore","who is darsok","дарсок","дарсок быстрый нож","кто такой дарсок"}},{q="Зачем Дарсоку когти Зачарованного Крыла?",a="Дарсок требует отрубленные когти как вещественное доказательство убийства: он собирает их как мрачные трофеи и подтверждение того, что низшие налетчицы стаи редеют.",al={"why talons","harpy talons purpose","зачем когти","для чего когти гарпий"}},{q="Где обитают эти гарпии?",a="Они устраивают гнезда среди поросших колючками утесов и оврагов на дальнем северо-западе Степей, к северу от дороги в Когтистые горы.",al={"where to find harpies","witchwing location","harpy raiders location","где найти гарпий","где зачарованное крыло","где гарпии-налетчики"}},{q="Что будет после уничтожения этих налетчиц?",a="Когда обычные налетчицы и воровки перьев будут проредены, Дарсок направит вас выше по иерархии стаи — к их лейтенантам и, наконец, к матроне.",al={"next quest","after harpy raiders","what comes next","следующее задание","после гарпий-налетчиков","что дальше"}},{q="Работают ли гарпии на кого-то еще?",a="Гарпии Зачарованного Крыла — дикие территориальные падальщицы, подчиняющиеся напрямую матроне своего гнезда, Серене Кровавое Перо, а не какой-либо внешней фракции.",al={"who leads the harpies","harpy allegiance","witchwing leaders","кто предводит гарпиями","верность гарпий","вожаки зачарованного крыла"}}},fp="13,279,17.396.0,13.425.0,49.155.0,26.203.0,38.167.0,32.147.0,41.172.1,40.154.0"}
P.entries["quest:8670"] = {n="Старейшина Рунический Тотем",s="«Старейшина Рунический Тотем» — встреча с духом предка во время Лунного фестиваля в Дуротаре. Она стоит в Колючем Холме под столбом небесного света и дарует благословения и праздничные монеты путникам, пришедшим почтить прошлое.",h="«Старейшина Рунический Тотем» — встреча с духом предка во время Лунного фестиваля в Дуротаре.",kw={"durotar","elder darkhorn","elder high mountain","elder runetotem","lunar festival","razor hill","runetotem","дуротар","старейшина темный рог","старейшина высокогор","старейшина рунический тотем","лунный фестиваль","колючий холм","рунический тотем"},ang={["faction:Alliance"]="Чтобы почтить Старейшину Рунического Тотема, нужно пробраться глубоко в тыл врага, в сердце Дуротара, не навлекая гнева орочьих стражей Колючего Холма.",["faction:Horde"]="Старейшина Рунический Тотем стоит прямо внутри стен Колючего Холма — один из самых безопасных и удобных предков, которых юным путникам Орды стоит почтить в начале пути.",["race:Tauren"]="Встреча с духом, носящим почитаемое имя рода Рунический Тотем, за пределами равнин Мулгора напоминает о глубоком духовном наследии вашего народа на всем Калимдоре."},sec={{t="Дух в Колючем Холме",b="Во время Лунного фестиваля духи древних старейшин являются по всему Азероту, чтобы пообщаться с живыми. Старейшина Рунический Тотем появляется в Колючем Холме, недалеко от южного входа. Озаренная ясным лучом звездного света сверху, она присматривает за поселением орков и приветствует искателей приключений, которые сворачивают с пути, чтобы почтить мудрость тех, кто жил прежде."},{t="Наставления по всем землям",b="Обращение к Старейшине Руническому Тотему — не просто дань одному предку. В обмен на ваше почтение она награждает вас праздничной монетой удачи и сообщает, где искать других духов, направляя странников к Старейшине Темному Рогу и Старейшине Высокогору на другом континенте."}},faq={{q="Где находится Старейшина Рунический Тотем?",a="Старейшина Рунический Тотем находится в Колючем Холме в Дуротаре, справа сразу после входа через южный вход.",al={"elder runetotem location","where is elder runetotem","find elder runetotem","где старейшина рунический тотем","как найти старейшину руническиого тотема","местоположение старейшины рунического тотема"}},{q="Почему на нее падает луч света?",a="Как и всех духов предков, являющихся во время Лунного фестиваля, Старейшину Рунического Тотема выделяет небесный столб света, падающий с неба и отмечающий ее как почтенную старейшину.",al={"light beam elder","why is runetotem glowing","elder beam of light","луч света старейшина","почему рунический тотем светится","свет над старейшиной"}},{q="Что вы получите за почтение Старейшины Рунического Тотема?",a="За почтение к Старейшине Руническому Тотему вы получите праздничную монету в память об уважении к предкам, а она подскажет, как найти других блуждающих духов, например Старейшину Темного Рога и Старейшину Высокогора.",al={"runetotem reward","what does runetotem give","elder runetotem turn in","награда рунического тотема","что дает рунический тотем","сдать задание старейшине"}},{q="Могут ли игроки Альянса посетить Старейшину Рунического Тотема?",a="Старейшины Лунного фестиваля принимают почтение от всех смертных независимо от принадлежности, но Колючий Холм — хорошо охраняемая застава Орды, и путникам Альянса опасно приближаться к ней.",al={"alliance elder runetotem","can alliance talk to runetotem","альянс старейшина рунический тотем","может ли альянс говорить с руническим тотемом"}},{q="Каких старейшин упоминает Рунический Тотем?",a="Старейшина Рунический Тотем рассказывает, где искать других предков, и подсказывает, как найти Старейшину Темного Рога и Старейшину Высокогора.",al={"runetotem directions","who does runetotem tell you to find","подсказки рунического тотема","кого найти по совету рунического тотема"}},{q="Старейшина Рунический Тотем — живой таурен или призрак?",a="Старейшина Рунический Тотем — дух предка, появляющийся в период Лунного фестиваля, чтобы благословлять тех, чей дух горит жизнью.",al={"is runetotem dead","is runetotem a ghost","мертв ли рунический тотем","рунический тотем призрак"}}},fp="19,263,22.398.0,25.290.0,33.143.0,44.191.0,49.197.0,43.196.0,36.147.0,46.144.0"}
P.entries["quest:8673"] = {s="«Старейшина Кровавый Рог» — встреча с одним из почитаемых духов предков, являющихся во время Лунного фестиваля. Этот почтенный дух находится у Деревни Кровавого Копыта в Мулгоре, принимает уважение странников и дарит им в ответ памятную монету предков.",h="«Старейшина Кровавый Рог» — встреча с одним из почитаемых духов предков, являющихся во время Лунного...",kw={"ahab wheathoof","ancestor","bloodhoof village","coin of ancestry","elder bloodhoof","lunar festival","mulgore","ахаб пшеничное копыто","предок","деревня кровавого копыта","монета наследия","старейшина кровавое копыто","лунный фестиваль","мулгор"},ang={["class:Druid"]="Друиды глубоко чтят духов Лунного фестиваля и общаются со старейшинами, чтобы укрепить природную связь с землей и звездами.",["class:Shaman"]="Для шамана беседа с явившимися предками, такими как Старейшина Кровавое Копыто, напрямую укрепляет живую связь между миром смертных и духами предков.",["faction:Alliance"]="Чтобы добраться до Старейшины Кровавого Копыта, нужно проникнуть в сердце Мулгора — это смелое путешествие по враждебным равнинам Орды.",["race:Tauren"]="Приветствовать Старейшину Кровавого Копыта — священный долг на родной земле, дань наследию племени, которое помогло привести тауренов в их мирное убежище в Мулгоре."},sec={{t="Визит предков",b="Во время Лунного фестиваля духи великих героев и старейшин минувших эпох возвращаются в Азерот. Окутанный небесным сиянием, Старейшина Кровавое Копыто появляется к северу от Деревни Кровавого Копыта, возле моста. Подойти к этим почитаемым предкам — значит почтить былые жертвы, и в обмен Старейшина Кровавое Копыто дарит слова ободрения и священную Монету Наследия."},{t="Наследие Кровавого Копыта",b="Стоя на землях предков в Мулгоре, Старейшина Кровавое Копыто служит мостом между живыми племенами тауренов и памятью об их предках. Для тауренов почитание мертвых — столп духовной жизни, укрепляющий гармонию между Матерью-Землей, предками и теми, кто ныне ходит по равнинам."}},faq={{q="Где найти Старейшину Кровавого Копыта?",a="Старейшина Кровавое Копыто стоит в луче небесного света неподалеку от Деревни Кровавого Копыта в Мулгоре, возле моста и Ахаба Пшеничного Копыта.",al={"elder bloodhoof location","where is elder bloodhoof","bloodhoof elder spot","старейшина кровавое копыто где","где старейшина кровавое копыто","место старейшины кровавое копыто"}},{q="Зачем искать Старейшину Кровавого Копыта?",a="Путники ищут Старейшину Кровавого Копыта во время Лунного фестиваля, чтобы почтить предков. В благодарность за это дух награждает посетителей Монетой Наследия и мудрым словом о соседних духах, например о Старейшине Пшеничном Копыте.",al={"why talk to elder bloodhoof","bloodhoof elder purpose","what does elder bloodhoof give","зачем говорить со старейшиной кровавое копыто","цель старейшины кровавое копыто","что дает старейшина кровавое копыто"}},{q="Почему на него падает луч света?",a="Столб света отмечает присутствие духа как призрака предка, явившегося во время Лунного фестиваля, и символизирует священную связь с небесами и духами прошлого.",al={"why is elder bloodhoof glowing","light on elder bloodhoof","почему старейшина кровавое копыто светится","свет над старейшиной кровавое копыто"}},{q="Могут ли персонажи Альянса почтить Старейшину Кровавого Копыта?",a="Предки Лунного фестиваля чтят всех смертных, проявляющих почтение, независимо от фракции. Однако путникам Альянса следует быть осторожными: Старейшина Кровавое Копыто находится прямо на пороге земель Орды.",al={"can alliance do this quest","is elder bloodhoof horde only","может ли альянс выполнить задание","только ли для орды старейшина кровавое копыто"}},{q="Кто такой Старейшина Пшеничное Копыто, о котором говорит старейшина?",a="Старейшина Пшеничное Копыто — еще один дух предка, почитаемый на празднике; он находится в другой части Мулгора. Старейшина Кровавое Копыто подскажет, где его искать.",al={"elder wheathoof","who is wheathoof","старейшина пшеничное копыто","кто такой пшеничное копыто"}},{q="Что означают Монеты Наследия?",a="Монеты Наследия — знаки благосклонности почитаемых духов Азерота. Они показывают, что путник проявил уважение к прошлому, а участники праздника обменивают их на праздничные наряды, схемы и праздничные товары.",al={"what are coins of ancestry","lunar festival tokens","что такое монеты наследия","монеты лунного фестиваля"}}},fp="19,285,26.394.0,20.316.0,33.142.0,51.245.0,49.185.0,54.211.0,48.159.0,40.234.0"}
P.entries["quest:8675"] = {n="Старейшина Небесный Охотник",s="Старейшина Небесный Охотник — дух предка, являющийся во время Лунного фестиваля на вершине Сторожевой башни в Западном Крае. Почтив ее, путники пыльных равнин могут отдать дань мудрости минувших веков. В ответ старейшина признает пылающую силу живых и дарует свое благословение.",h="Старейшина Небесный Охотник — дух предка, являющийся во время Лунного фестиваля на вершине Сторожевой башни в...",kw={"coin of ancestry","elder skychaser","lunar festival","sentinel hill","sentinel tower","skychaser","westfall","монета наследия","старейшина небесный охотник","лунный фестиваль","сторожевой холм","сторожевая башня","небесный охотник","западный край"},ang={["class:Druid"]="Друиды считают Лунный фестиваль священным и видят в явлениях предков, таких как Небесный Охотник, непрерывную связь с древними традициями и глубоким благоговением перед природой.",["faction:Alliance"]="Старейшина Небесный Охотник удобно расположена в самом сердце базы Народного ополчения на Сторожевом холме, и ее легко почтить во время выполнения заданий в Западном Крае.",["faction:Horde"]="Чтобы добраться до Старейшины Небесного Охотника, нужны скрытность, скорость или грубая сила: Сторожевой холм полон враждебных стражей Альянса и разведчиков ополчения."},sec={{t="Маяк в пыли",b="Среди неспокойных пустошей Западного Края Сторожевой холм стоит как единственный укрепленный оплот против налетчиков Братства Справедливости и бродячих мародеров. Во время Лунного фестиваля дух предка по имени Старейшина Небесный Охотник занимает место на открытой площадке на вершине Сторожевой башни. Высоко над пылью и ветром она терпеливо бдит над усталыми солдатами и осажденными поселенцами внизу и приветствует каждого, кто поднимется, чтобы выразить почтение."},{t="Почитание предков",b="Лунный фестиваль — священная пора, которую отмечают по всему Азероту, прославляя мудрость, наследие и деяния древних духов, ходивших по земле до нынешних невзгод. Когда к ней подходят, Старейшина Небесный Охотник узнает в путнике животворную искру, принимает его почтение и дарует знак своей благосклонности как дар родства между живыми и почитаемыми мертвыми."}},faq={{q="Где найти Старейшину Небесного Охотника?",a="Старейшина Небесный Охотник находится на самой вершине Сторожевой башни в Сторожевом холме в Западном Крае. Поднимитесь по винтовой лестнице внутри башни на верхние смотровые стены.",al={"skychaser location","where is elder skychaser","skychaser westfall","где небесный охотник","где старейшина небесный охотник","небесный охотник западный край"}},{q="Почему Старейшина Небесный Охотник стоит на вершине Сторожевой башни?",a="Духи предков выбирают заметные и символичные места по всему Азероту во время Лунного фестиваля. Высоты Сторожевой башни дают бдительный обзор долины Западного Края, позволяя старейшине видеть путников, отважно идущих по рубежу.",al={"why is he in sentinel tower","skychaser tower","почему она на сторожевой башне","башня небесного охотника"}},{q="В чем смысл этого задания?",a="Поиск Старейшины Небесного Охотника — часть почитания старейшин-предков во время Лунного фестиваля. Выказанное уважение приносит Монету Наследия и благословение, прославляющее живой дух искателя приключений.",al={"skychaser quest reward","why honor elder skychaser","награда за задание небесного охотника","зачем чтить старейшину небесный охотник"}},{q="Могут ли игроки Орды почтить Старейшину Небесного Охотника?",a="Сама Старейшина Небесный Охотник — мирный дух, приветствующий всех паломников. Однако Сторожевой холм — хорошо защищенная застава Альянса, и добраться до нее опасно для искателей приключений Орды.",al={"can horde visit skychaser","is skychaser hostile to horde","может ли орда посетить небесного охотника","враждебен ли небесный охотник к орде"}},{q="Участвует ли Старейшина Небесный Охотник в обороне Сторожевого холма?",a="Нет. Старейшины, приходящие во время Лунного фестиваля, — духовные явления, занятые только традицией и памятью о древности. Старейшина Небесный Охотник не участвует в стычках Народного ополчения с Братством Справедливости.",al={"does skychaser fight defias","is skychaser part of the people's militia","сражается ли небесный охотник с братством справедливости","входит ли небесный охотник в народное ополчение"}},{q="Что говорит Небесный Охотник при встрече?",a="При встрече Старейшина Небесный Охотник замечает, что ваш дух ярко горит жизнью, милостиво принимает ваше почтение и дарует в ответ памятную монету предков.",al={"skychaser dialogue","what does the elder say","диалог небесного охотника","что говорит старейшина"}}},fp="19,307,20.435.0,22.380.0,33.168.0,57.243.0,34.197.0,40.186.0,65.231.0,43.167.0"}
P.entries["quest:8677"] = {kw={"ancestor","coin of ancestry","darkhorn","elder darkhorn","elders","lunar festival","orgrimmar","valley of strength","предок","монета наследия","темный рог","старейшина темный рог","старейшины","лунный фестиваль","оргриммар","аллея силы"},ang={["class:Shaman"]="Шаманы чтут связь между миром живых и древними духами, поэтому посещение старейшин-предков, таких как Темный Рог, — глубокий духовный долг.",["faction:Alliance"]="Чтобы добраться до Старейшины Темного Рога, нужно дерзко проникнуть через хорошо охраняемые ворота и улицы Оргриммара, и почтение предка превращается в опасное испытание скрытности или силы.",["faction:Horde"]="Для защитников Орды встреча со Старейшиной Темным Рогом — удобная возможность почтить традиции предков в безопасности, в самом оживленном сердце их столицы."},sec={{t="Почитание предка",b="Во время Лунного фестиваля духи почитаемых предков являются по всему Азероту, чтобы поделиться мудростью с живыми. Старейшина Темный Рог пребывает в укрепленных стенах Оргриммара и наблюдает за суетой молодого города воинов. Подойдя к ней, защитники Орды — и любой храбрый приключенец Альянса, сумевший проскользнуть через ворота, — могут воздать должное тем, кто ходил по этой земле много поколений назад."},{t="Дух фестиваля",b="Получив приветствие и знак почтения от проходящих путников, Старейшина Темный Рог признает яркую искру жизни в них. В обмен на уважение к древним обычаям она дарует Монету Наследия и свое личное благословение. Эти знаки прославляют победу над древними опасностями и напоминают живым беречь силу, переданную по непрерывным линиям крови."}},faq={{q="Кто такая Старейшина Темный Рог?",a="Старейшина Темный Рог — дух предка, появляющийся в Оргриммаре во время Лунного фестиваля. Она служит посланницей прошлого и дарует благословения и знаки путникам, которые находят время почтить старейшин.",al={"elder darkhorn","who is darkhorn","darkhorn lore","старейшина темный рог","кто такая темный рог","предания темный рог"}},{q="Где найти Старейшину Темного Рога?",a="Ее можно найти в Оргриммаре, в Аллее Мудрости у самой Крепости Громмаш, где она наблюдает за повседневной жизнью столицы Орды во время фестиваля.",al={"darkhorn location","where is darkhorn","elder darkhorn orgrimmar","где темный рог","местонахождение темного рога","старейшина темный рог оргриммар"}},{q="Для чего нужны старейшины Лунного фестиваля?",a="Старейшины являются во время Лунного фестиваля, чтобы живые могли почтить мудрость, мужество и жертвы предков. За выражение почтения старейшине дают Монету Наследия — символ наследия и общей памяти.",al={"why find elders","lunar festival elders","ancestor coins","зачем искать старейшин","старейшины лунного фестиваля","монеты предков"}},{q="Могут ли игроки Альянса почтить Старейшину Темного Рога?",a="Да, старейшины-предки принимают уважение от всех живых смертных независимо от фракции. Однако Старейшина Темный Рог находится в глубине оплота Орды — Оргриммара, поэтому посетителям из Альянса придется пробиваться мимо враждебных стражей и игроков.",al={"can alliance talk to darkhorn","alliance elder darkhorn","alliance orgrimmar elder","может ли альянс говорить с темным рогом","альянс старейшина темный рог","старейшина оргриммара альянс"}},{q="Какую награду дает Старейшина Темный Рог?",a="За почтение Старейшине Темному Рогу дают Монету Наследия и ее благословение.",al={"darkhorn reward","what does darkhorn give","coin of ancestry darkhorn","награда темный рог","что дает темный рог","монета наследия темный рог"}},{q="Можно ли выполнять это задание повторно?",a="Нет, каждого старейшину-предка можно почтить лишь один раз на персонажа во время ежегодного Лунного фестиваля.",al={"can i do darkhorn again","is darkhorn repeatable","darkhorn daily","можно ли повторить темный рог","повторяется ли темный рог","темный рог ежедневно"}}},fp="18,326,21.432.0,26.369.0,22.214.0,32.177.0,49.212.0,42.241.0,38.80.0,25.109.0"}
P.entries["quest:8678"] = {n="Предок Пшеничная Грива",s="Предок Пшеничная Грива — дух предка-тауренов, которого чтят во время Лунного фестиваля на высотах Громового Утеса. Посетить его — значит глубоко почтить мудрость предков, оберегающих Мулгор и Орду.",h="Предок Пшеничная Грива — дух предка-тауренов, которого чтят во время Лунного фестиваля на высотах Громового...",kw={"ancestor","coin of ancestry","elder","lunar festival","mulgore","spirit","thunder bluff","wheathoof","предок","монета наследия","старейшина","лунный фестиваль","мулгор","дух","громовой утес","пшеничная грива"},ang={["class:Shaman"]="Для шамана общение со старейшиной-предком — глубокий обряд единения с вечным миром духов.",["faction:Horde"]="Этот старейшина находится в сердце могущества тауренов и приветствует всех союзников Орды, поднявшихся в Громовой Утес, чтобы выразить почтение.",["race:Tauren"]="Почтить Предка Пшеничную Гриву для тауренов-защитников — священное возвращение домой, подтверждающее их вечную связь с духами, оберегающими Мулгор."},sec={{t="Дух Мулгора",b="Высоко на продуваемых ветрами плато Громового Утеса Предок Пшеничная Грива является как дух предков во время Лунного фестиваля. Таурены высоко ценят голоса своих предков и верят, что духи древних вождей и мудрецов остаются, чтобы направлять и укреплять живых."},{t="Почтение и благословение предков",b="Путников, поднявшихся на высоты, чтобы почтить Предка Пшеничную Гриву, встречают не как чужаков, а как живые огни жизни. В ответ на почтение старейшина дарует Монету Наследия — символ единения между вечным прошлым и живыми защитниками, сражающимися за будущее мира."}},faq={{q="Кто такой Предок Пшеничная Грива?",a="Это почитаемый дух предка-тауренов, являющийся на вершине Громового Утеса во время Лунного фестиваля, чтобы принимать почтение от защитников со всего Азерота.",al={"wheathoof","elder wheathoof","who is wheathoof","пшеничная грива","предок пшеничная грива","кто такой пшеничная грива"}},{q="Где найти Предка Пшеничную Гриву?",a="Предок Пшеничная Грива находится в столице тауренов, Громовом Утесе, на широких центральных плато над равнинами Мулгора.",al={"where is elder wheathoof","wheathoof location","thunder bluff elder","где предок пшеничная грива","местонахождение пшеничной гривы","старейшина громового утеса"}},{q="Зачем его посещать?",a="Посетив Предка Пшеничную Гриву, игроки могут почтить духов прошлого во время Лунного фестиваля и получить его благословение и Монету Наследия.",al={"why visit wheathoof","wheathoof quest","lunar festival elder","зачем посещать пшеничную гриву","задание пшеничная грива","старейшина лунного фестиваля"}},{q="Могут ли игроки Альянса посетить Предка Пшеничную Гриву?",a="Хотя дух дарует благословение любому почтительному путнику, войти в Громовой Утес приключенцу Альянса крайне опасно из-за бдительных стражей города и защитников Орды.",al={"can alliance talk to wheathoof","alliance thunder bluff elder","может ли альянс говорить с пшеничной гривой","старейшина громового утеса альянс"}},{q="Что такое Монета Наследия?",a="Это церемониальный знак, который дарят древние духи во время Лунного фестиваля, символ уважения и единения между живыми и предками.",al={"coin of ancestry","lunar festival coin","монета наследия","монета лунного фестиваля"}},{q="Как таурены относятся к своим старейшинам?",a="Таурены чтут предков как хранителей и учителей, чье духовное присутствие вплетено в землю и постоянно направляет тех, кто настроен на Мать-Землю.",al={"tauren ancestor worship","tauren elders lore","почитание предков тауренов","предания о старейшинах тауренов"}}},fp="19,240,19.318.0,29.314.0,27.157.0,37.136.0,36.156.0,43.195.0,27.154.0,36.176.0"}
P.entries["quest:86784"] = {n="Палки и кости",s="«Палки и кости» — местное поручение Стража смерти Бартоломью в Тирисфальских лесах. Он посылает путников собрать сухие ветки по всему оскверненному лесу и доставить их Элеоноре Шеклтон, опытной выживальщице, разбившей лагерь в западных холмах.",h="«Палки и кости» — местное поручение Стража смерти Бартоломью в Тирисфальских лесах.",kw={"collecting basket","deathguard bartholomew","dry branch","eleanor shackleton","firewood","sticks and bones","survival","tirisfal glades","корзина для сбора","страж смерти бартоломью","сухая ветка","элеонора шеклтон","дрова","палки и кости","выживание","тирисфальские леса"},ang={["faction:Horde"]="Отдаленные стоянки, как у Элеоноры, служат дружескими остановками для молодых приключенцев Орды, отправляющихся в путь по Тирисфальским лесам.",["race:Undead"]="Даже в оскверненных лесах Лордерона Отрекшиеся путники, такие как Элеонора Шеклтон, вынуждены приспосабливать старые навыки выживания к своей новой нежизни."},sec={{t="Дружеский жест",b="Хотя Стражи смерти в Тирисфальских лесах обычно поглощены патрулированием и защитой от Плети и Алого ордена, Страж смерти Бартоломью находит время позаботиться о знакомой. Зная, что Элеонора Шеклтон проводит свою нежизнь под суровыми стихиями, он просит проходящих приключенцев собрать сухие ветки для ее костра."},{t="Жизнь в глуши",b="Элеонора Шеклтон гордится тем, что в одиночку выживает в оскверненной глуши Тирисфаля. Хотя Отрекшиеся мертвы, они все равно чувствуют сырой, жгучий холод северных пустошей. Философия Элеоноры о сборе дров проста: когда вам кажется, что хвороста достаточно, соберите в пять раз больше. Благодарная за лишнее дерево, она позволяет посыльному оставить корзину Бартоломью и делится теплом своего костра."}},faq={{q="Кто дает задание «Палки и кости»?",a="Страж смерти Бартоломью в Тирисфальских лесах дает это поручение проходящим приключенцам, прося помочь его знакомой Элеоноре Шеклтон.",al={"who gives sticks and bones","sticks and bones quest starter","кто дает палки и кости","начало задания палки и кости"}},{q="Где разбила лагерь Элеонора Шеклтон?",a="Элеонора Шеклтон держит небольшой лагерь в холмах на западе Тирисфальских лесов, выживая среди стихий вдали от поселений.",al={"eleanor shackleton location","where is eleanor","where to turn in sticks and bones","где элеонора шеклтон","где элеонора","куда сдавать палки и кости"}},{q="Зачем Отрекшимся дрова, если они мертвы?",a="Хотя Отрекшиеся не замерзают насмерть, как живые, они все равно ощущают постоянную сырость и жгучий холод глуши Тирисфаля. Костер дарит уют, согревает их одеревеневшие суставы и делает лагерь в глуши пригодным для жизни.",al={"do undead get cold","why firewood for undead","forsaken cold","мерзнут ли нежить","зачем дрова нежити","отрекшиеся холод"}},{q="Какой совет дает Элеонора о сборе дров?",a="По словам Стража смерти Бартоломью, золотое правило выживания Элеоноры гласит: «Когда думаете, что дров достаточно, соберите в пять раз больше».",al={"eleanor firewood rule","eleanor advice","правило элеоноры о дровах","совет элеоноры"}},{q="Чем собирать ветки?",a="Страж смерти Бартоломью дает корзину для сбора, чтобы нести шесть сухих веток, разбросанных по лесам. Элеонора позволяет оставить ее себе после доставки.",al={"basket for dry branch","how to gather branches","корзина для сухих веток","как собрать ветки"}},{q="Ведет ли это задание к дальнейшему обучению выживанию?",a="Элеонора приветствует вас в своем лагере и делится советами о путешествиях по глуши для приключенца, становясь дружеским контактом в глуши Тирисфаля.",al={"sticks and bones followup","what does eleanor do next","палки и кости продолжение","что делает элеонора дальше"}}},fp="16,247,18.361.0,17.436.0,38.135.0,35.140.0,53.241.0,51.138.0,45.164.0,50.154.0"}
P.entries["quest:868"] = {n="Охота за яйцами",s="«Охота за яйцами» — задание Орды, которое дает ученый Корран на Перекрестке. Встревоженный появлением разумных насекомоподобных существ на юге Степей, Корран нанимает приключенцев добыть целые яйца силитидов из курганов на Полях Великанов для изучения в Оргриммаре.",h="«Охота за яйцами» — задание Орды, которое дает ученый Корран на Перекрестке.",kw={"barrens","crossroads","digging claw","egg hunt","field of giants","korran","silithid","степи","перекресток","вспарывающий коготь","охота за яйцами","поля великанов","корран","силитиды"},ang={["faction:Horde"]="Орда полагается на разведчиков вроде Коррана, наблюдающих за пустынными землями Калимдора, чтобы странные экологические угрозы были изучены до того, как они станут опасны для Дуротара и Мулгора.",["race:Troll"]="Тролли, знакомые с первобытными существами, понимают, что силитиды — не просто жуки, и разделяют настороженность Коррана к зверям с неестественным, расчетливым разумом."},sec={{t="Глаза на Перекрестке",b="Тролль Корран, расположившийся на пыльном Перекрестке в центре саванны, служит наблюдателем и докладывает хозяевам в Оргриммаре. Пока военные Орды заняты племенными конфликтами и вторжениями Альянса, Корран замечает странные нарушения в экосистеме. Главная из этих странностей — появление чуждых насекомоподобных существ с единым разумом улья, роющих норы на юге Степей."},{t="Раскопки роя",b="Чтобы узнать, откуда берутся эти насекомые и что движет ими, Корран требует биологические образцы, пока они не созрели. Вооружившись вспарывающим когтем, приключенцы отправляются на Поля Великанов и берут яйца прямо из земляных курганов силитидов. Потревоженные кладки вызывают яростную оборону окружающего выводка, намекая на неестественный разум и общую волю, объединяющие рой."}},faq={{q="Кто дает задание «Охота за яйцами»?",a="Задание дает Корран на Перекрестке в Степях. Это тролль-наблюдатель, изучающий флору, фауну и новые аномалии региона по поручению покровителей в Оргриммаре.",al={"quest giver","korran location","who starts egg hunt","персонаж, выдающий задания","где корран","кто начинает охоту за яйцами"}},{q="Где найти яйца силитидов?",a="Яйца находятся в земляных курганах силитидов на Полях Великанов, в южной части Степей. Курганы сгруппированы вокруг туннелей улья, прорытых в земле.",al={"egg location","where to find eggs","field of giants eggs","где яйца","где найти яйца","яйца поля великанов"}},{q="Какой инструмент нужен для сбора яиц?",a="Корран дает прочный Вспарывающий коготь, чтобы аккуратно вынимать целые яйца, не раздавив хрупкую скорлупу. Инструмент нужно вернуть вместе с двенадцатью неповрежденными яйцами.",al={"digging tool","digging claw","how to get eggs","инструмент для раскопок","вспарывающий коготь","как добыть яйца"}},{q="Чем эти насекомые отличаются от обычных зверей?",a="В отличие от простых паразитов или местной живности, эти существа проявляют жутковатую согласованность и высокую хитрость. Корран отмечает, что их разум намного выше, чем у обычных животных, что говорит о единой цели улья.",al={"why are silithid special","insect intelligence","silithid nature","чем особенны силитиды","разум насекомых","природа силитидов"}},{q="Зачем Оргриммару яйца силитидов?",a="Руководство Оргриммара хочет заранее получить сведения о неизвестных угрозах, укореняющихся у границ Орды. Изучение яиц помогает исследователям понять цикл роста, силы и биологию существ, пока заражение не распространилось.",al={"orgrimmar silithid study","why study eggs","korran purpose","изучение силитидов оргриммар","зачем изучать яйца","цель коррана"}},{q="Что происходит, если потревожить курган с яйцами?",a="Прикосновение к гнездовым курганам тревожит окружающий рой. Ближайшие силитиды тут же защищают выводок и нападают из засады на тех, кто разоряет гнездо.",al={"mound ambush","silithid defenders","засада у кургана","защитники силитидов"}}},fp="8,286,22.408.0,20.413.0,29.178.0,34.194.0,40.171.0,55.211.0,38.245.0,43.157.0"}
P.entries["quest:8680"] = {n="Харкен Тотем Ветра",s="Старейшина Тотем Ветра — почитаемый дух предка, который появляется во время Лунного фестиваля на утесе над гоблинским портом Кабестан. Окутанная лучом сияющего небесного света, она принимает путников, желающих почтить мудрость минувших веков. Тех, кто воздаст ей почести, она награждает благословением предков и указывает путь к другим старейшинам, обитающим в Калимдоре.",h="Старейшина Тотем Ветра — почитаемый дух предка, который появляется во время Лунного фестиваля на утесе над...",kw={"ancestor","coin of ancestry","elder windtotem","lunar festival","ratchet","the barrens","windtotem the elder","предок","монета наследия","старейшина тотем ветра","лунный фестиваль","кабестан","степи","харкен тотем ветра"},ang={["class:Druid"]="Лунный фестиваль и явления предков прославляют глубокую связь с природными и небесными циклами, которые охраняет Круг Кенария.",["class:Shaman"]="Беседа с духами предков, задержавшимися у стыков стихий, укрепляет долг шаманов — чтить мертвых и заботиться о духовном здоровье земли.",["race:Tauren"]="Род Тотема Ветра воплощает древнее наследие таурен; почитание этого предка над гоблинским портом напрямую связывает нынешних соплеменников с памятью предков о равнинах."},sec={{t="Бдение над заливом",b="Старейшина Тотем Ветра стоит на травянистом холме к северо-западу от распорядителя полетов в Кабестане и смотрит на оживленные гоблинские доки и открытое море. Пока гавань внизу торгует железом, порохом и монетами, старейшина в тихом раздумье держится особняком, и ее касаются лишь тихие ветры Степей и небесное сияние, нисходящее сверху."},{t="Мудрость Степей",b="Как и другие духи предков, призванные во время Лунного фестиваля, Старейшина Тотем Ветра служит проводником для странствующих смертных. Тот, кто разыщет ее, получает не только ее благословение и знак ее милости, но и шепот с вестями о местонахождении соседних старейшин на континенте, в том числе Старейшины Рунического Тотема и Старейшины Кровавого Копыта."}},faq={{q="Где находится Старейшина Тотем Ветра?",a="Старейшина Тотем Ветра стоит на холме прямо к северо-западу от распорядителя полетов в Кабестане и смотрит на гавань в Степях.",al={"windtotem location","where is windtotem","elder windtotem ratchet map","тотем ветра где находится","где старейшина тотем ветра","старейшина тотем ветра кабестан карта"}},{q="Зачем искать Старейшину Тотема Ветра?",a="Во время Лунного фестиваля путники ищут Старейшину Тотема Ветра, чтобы почтить почитаемого предка. В обмен на ваши почести она дарует Монету Наследия и сведения о том, где найти других духов по всей земле.",al={"why talk to windtotem","windtotem elder purpose","what does windtotem do","зачем говорить с тотем ветра","старейшина тотем ветра цель","что делает тотем ветра"}},{q="Почему на нее падает луч света?",a="Каждый предок, явившийся во время Лунного фестиваля, окутан особым столпом небесного лунного света, который знаменует его призрачное присутствие и духовную связь между миром предков и миром живых.",al={"beam of light elder","why is windtotem glowing","light shining on elder","луч света старейшина","почему тотем ветра светится","свет падает на старейшину"}},{q="Могут ли игроки Альянса и Орды говорить со Старейшиной Тотемом Ветра?",a="Да. Кабестан — нейтральный порт, которым управляет Картель Хитрая Шестеренка, и старейшины Лунного фестиваля беспристрастно встречают представителей и Альянса, и Орды.",al={"can alliance talk to windtotem","is windtotem neutral","horde and alliance elder","может ли альянс говорить с тотем ветра","тотем ветра нейтрален","старейшина орды и альянса"}},{q="О каких других старейшинах рассказывает вам Старейшина Тотем Ветра?",a="Старейшина Тотем Ветра делится слухами и указаниями о нескольких соседних предках, в том числе о Старейшине Кровавом Копыте, Старейшине Руническом Тотеме, Старейшине Утренней Росе, Старейшине Темном Роге, Старейшине Высокогоре, Старейшине Лунном Страже и Старейшине Пшеничном Копыте.",al={"elders windtotem mentions","who does windtotem point to","старейшины тотем ветра упоминает","на кого указывает тотем ветра"}},{q="Что происходит, когда вы завершаете поклонение старейшине?",a="Когда вы подходите к ней и почтительно приветствуете ее, она хвалит ваш дух, ярко горящий жизнью, принимает ваше уважение и награждает вас Монетой Наследия.",al={"elder windtotem turn in","what does elder windtotem say","старейшина тотем ветра сдать задание","что говорит старейшина тотем ветра"}}},fp="19,360,20.353.0,25.351.0,33.123.0,51.231.0,49.214.0,61.172.0,55.221.0,51.152.0"}
P.entries["quest:8682"] = {n="Старейшина Искатель Неба",s="Старейшина Искатель Неба — почитаемый дух предка, обитающий на вершине Заставы Вольного Ветра во время Лунного фестиваля. Путники ищут его высоко над Тысячей Игл, чтобы почтить предков и получить его древнее благословение.",h="Старейшина Искатель Неба — почитаемый дух предка, обитающий на вершине Заставы Вольного Ветра во время...",kw={"ancestor","coins of ancestry","elder skyseer","freewind post","lunar festival","skyseer","thousand needles","предок","монеты наследия","старейшина небесный провидец","застава вольного ветра","лунный фестиваль","небесный провидец","тысяча игл"},ang={["class:Druid"]="Общение с древними духами под лунным светом тесно связано с учением Кенария и почитанием тех, кто ходил по этой земле прежде.",["faction:Alliance"]="Старейшина Небесный Провидец пребывает в оплоте Орды — Заставе Вольного Ветра, поэтому паломникам из Альянса приходится пробираться по опасным высотам мимо враждебных стражей, чтобы выразить почтение.",["race:Tauren"]="Приветствие почтенного старейшины на вершине одной из самых узнаваемых плосковерхих скал, где обитают ваши сородичи, отражает глубокое почтение, которое Шу'хало питают к своему родовому наследию."},sec={{t="Маяк в Иглах",b="Старейшина Небесный Провидец стоит на высоких деревянных утесах Заставы Вольного Ветра, окутанный сияющим столпом небесного света. Его призрачный облик, расположенный возле мостов к огромным механическим подъемникам, дарит тихое прибежище среди продуваемых ветрами плато Тысячи Игл."},{t="Путь предков",b="Старейшина Небесный Провидец принимает искателей приключений, пришедших почтить прошлое во время Лунного фестиваля. Помимо принятия почестей, почтенный старейшина может направить путников к своим сородичам, рассеянным по Калимдору, в том числе к Старейшине Утренней Росе и Старейшине Руническому Тотему."}},faq={{q="Где находится Старейшина Небесный Провидец?",a="Старейшина Небесный Провидец стоит на верхнем плато Заставы Вольного Ветра в Тысяче Игл, возле подвесных мостов рядом с подъемниками на утесе.",al={"skyseer location","where is skyseer","freewind post elder","небесный провидец где находится","где небесный провидец","старейшина заставы вольного ветра"}},{q="Зачем искать Старейшину Небесного Провидца?",a="Во время Лунного фестиваля путники посещают духов предков, таких как Старейшина Небесный Провидец, чтобы почтить их, получить Монету Наследия и услышать указания о местонахождении других старейшин.",al={"why visit skyseer","skyseer quest objective","lunar festival skyseer","зачем идти к небесному провидцу","цель задания небесный провидец","лунный фестиваль небесный провидец"}},{q="Почему Старейшина Небесный Провидец светится?",a="Как и другие почитаемые духи, приходящие во время фестиваля, Старейшина Небесный Провидец освещен с небес ярким лучом лунного света, что отмечает его как предка, общающегося с живыми.",al={"why is skyseer in light","elder light beam","почему небесный провидец в свете","луч света старейшина"}},{q="О каких других старейшинах Небесный Провидец дает указания?",a="Старейшина Небесный Провидец подсказывает, как найти ближайших духов предков, в том числе Старейшину Утреннюю Росу, Старейшину Рунического Тотема, Старейшину Провидца Снов и Старейшину Буйногривую.",al={"other elders","who does skyseer mention","skyseer directions","другие старейшины","кого упоминает небесный провидец","указания небесного провидца"}},{q="Могут ли путники из Альянса говорить со Старейшиной Небесным Провидцем?",a="Да, хотя Застава Вольного Ветра — сильно укрепленное поселение Орды. Искателям приключений из Альянса придется осторожно обходить стражей, чтобы подойти к старейшине и не пролить кровь.",al={"can alliance talk to skyseer","alliance freewind post elder","может ли альянс говорить с небесным провидцем","старейшина заставы вольного ветра альянс"}},{q="Что происходит, когда вы говорите со Старейшиной Небесным Провидцем?",a="Когда вы приветствуете его и воздаете почести, Старейшина Небесный Провидец хвалит ваш дух и дарует знак благословения предков, на чем краткая встреча заканчивается.",al={"skyseer reward","completing skyseer the elder","награда небесный провидец","выполнить старейшина искатель неба"}}},fp="17,236,23.288.0,18.281.0,31.143.0,49.189.0,29.188.0,55.154.0,48.178.0,45.145.0"}
P.entries["quest:87"] = {n="Фикс",s="Фикс — задание в Элвиннском лесу, завершающее поиски пропавшей фамильной ценности Тетушки Бернис Стоунфилд, вызвавшие ссору. После того как юный Билли Маклюр признается, куда делось ожерелье, вам предстоит выследить вороватого кобольда возле Рудника Подземных Глубин.",h="Фикс — задание в Элвиннском лесу, завершающее поиски пропавшей фамильной ценности Тетушки Бернис Стоунфилд...",kw={"bernice","billy","fargodeep","goldtooth","kobold","maclure","necklace","stonefield","бернис","билли","подземные глубины","фикс","кобольд","маклюр","ожерелье","стоунфилд"},ang={["race:Human"]="Улаживание этой ссоры помогает сгладить местные трения между двумя старейшими фермерскими семьями Элвиннского леса, а также справиться с докучливыми кобольдами-паразитами, досаждающими королевству."},sec={{t="Шалость мальчишки",b="Поиски потерянного семейного ожерелья Тетушки Бернис Стоунфилд начались с неприятного пограничного спора между враждующими семьями Стоунфилд и Маклюр. Бернис, естественно, подозревала соперников, но виновником оказался Билли Маклюр. Дурачась возле Рудника Подземных Глубин, юный проказник потерял безделушку и поспешно скрыл вину, заявив, что лишь нашел ее, а потом какая-то тварь ее унесла."},{t="Логово над рудником",b="По словам Билли, необычно крупный кобольд с блестящими клыками схватил блестящую памятную вещицу и убежал. Билли утверждает, что он убежал в логово над рудником, но зверь по имени Фикс на самом деле скрывается на нижнем уровне Рудника Подземных Глубин. Убив его, вы вернете ожерелье Бернис, положите конец соседской ссоре и получите старую памятную вещь с военных походов покойного мужа Бернис."}},faq={{q="Кто украл ожерелье Тетушки Бернис?",a="Его взял Билли Маклюр, пока дурачился, хотя он говорит, что лишь нашел и обронил его возле Рудника Подземных Глубин. Прежде чем он успел его вернуть, кобольд Фикс схватил блестящую добычу.",al={"who stole necklace","who took the necklace","did maclures steal necklace","кто украл ожерелье","кто взял ожерелье","украли ли маклюры ожерелье"}},{q="Где можно найти Фикса?",a="Фикс скрывается на нижнем уровне Рудника Подземных Глубин, хотя Билли описывает его логово как находящееся над рудником.",al={"goldtooth location","where is goldtooth","find goldtooth","фикс где находится","где фикс","найти фикса"}},{q="Что за существо Фикс?",a="Фикс — гигантский кобольд, известный блестящим золотым клыком, за который и получил свое прозвище; как и всех его сородичей, его влекут яркие блестящие безделушки.",al={"what is goldtooth","is goldtooth a kobold","кто такой фикс","фикс кобольд ли"}},{q="Как это задание связано с враждой Маклюров и Стоунфилдов?",a="Стоунфилды и Маклюры — заклятые соперники, подозревающие друг друга в любой мелкой краже или неудаче. Тетушка Бернис решила, что Маклюры украли ожерелье из злобы, но поиски показывают, что это была просто неосторожность Билли.",al={"stonefield maclure drama","why does bernice blame billy","стоунфилды маклюры вражда","почему бернис винит билли"}},{q="Какова награда от Тетушки Бернис?",a="Тетушка Бернис дарит вам старую памятную вещь, считавшуюся счастливой и принадлежавшую ее покойному мужу, который, к несчастью, забыл взять ее в свой последний военный поход.",al={"bernice reward","what do you get","награда бернис","что вы получите"}},{q="Какое задание ведет непосредственно к заданию «Фикс»?",a="Задание «Назад к Билли» ведет прямо к заданию «Фикс»: там вы подкупаете Билли Маклюра свининой, чтобы он наконец признался, что случилось с ожерельем.",al={"goldtooth prereq","quest before goldtooth","фикс предыдущее задание","задание перед фиксом"}}},fp="9,261,16.451.0,22.411.0,36.191.1,29.111.0,35.148.0,61.240.1,39.164.0,41.152.0"}
P.entries["quest:870"] = {n="Забытые пруды",s="Тонга Рунический Тотем с Перекрестка отправляет авантюристов Орды осмотреть Забытые пруды — оазис к северо-западу от поселения. Круг Кенария подозревает, что скрытые подземные энергии заставляют буйную зелень расти в засушливой саванне.",h="Тонга Рунический Тотем с Перекрестка отправляет авантюристов Орды осмотреть Забытые пруды — оазис к...",kw={"barrens","cenarion circle","crossroads","fissure","forgotten pools","oasis","tonga runetotem","степи","круг кенария","перекресток","трещина","забытые пруды","оазис","тонга рунический тотем"},ang={["class:Druid"]="Для друидов это поручение — первое знакомство с таинственными силами, которые искажают и изменяют природный рост в Степях под присмотром Круга Кенария.",["faction:Horde"]="Перекресток — важнейший узел между Дуротаром, Мулгором и Ясеневым лесом, поэтому защита ближайших источников воды от аномальной порчи для Орды — насущная необходимость.",["race:Tauren"]="Земля Степей дорога кочевым племенам Матери-Земли, поэтому сохранение и понимание ее источников воды жизненно важны для путников-тауренов."},sec={{t="Волнения в саванне",b="Давным-давно Степи были плодородным, цветущим краем, пока века войн и Раскол не разрушили континент и не превратили область в выжженную солнцем пустошь. Но недавно в сухой котловине чудесным образом начали появляться пышные оазисы. Друидам Круга Кенария это внезапное цветение кажется неестественным. Они ощущают не обычные источники, а подземные силы, давящие вверх сквозь землю и пробуждающие растения и животных к жизни в необычных местах по всей пустоши."},{t="Мутные глубины",b="Стремясь понять причины этого возрождения, Тонга Рунический Тотем отправляет путников нырнуть в Забытые пруды, расположенные к северо-западу от Перекрестка. Под поверхностью воды обнаруживается тревожная находка: вулканическая трещина, тихо выпускающая в воду странные пузырящиеся газы. Эта трещина доказывает, что нестабильные первородные силы проникают в грунтовые воды, и это первая явная зацепка в разгадке неестественных перемен в Степях."}},faq={{q="Кто такой Тонга Рунический Тотем?",a="Тонга Рунический Тотем — таурен-друид из Круга Кенария, находящийся на Перекрестке. Он изучает экологические аномалии Степей и надеется выяснить, почему на выжженных солнцем равнинах вдруг возникают пышные оазисы.",al={"tonga runetotem","who gives the quest","quest giver crossroads","тонга рунический тотем","кто выдает задание","персонаж, выдающий задание, перекресток"}},{q="Почему Круг Кенария исследует Забытые пруды?",a="Возвращение зелени на сухую землю кажется добрым знаком, но друиды чувствуют, что жизнь на поверхность выталкивает необычная, сконцентрированная энергия. Они хотят выяснить, какая первичная сила питает новые оазисы, пока она не вышла из-под контроля.",al={"why investigate oases","druids barrens oases","what is wrong with the pools","почему исследовать оазисы","друиды оазисы степей","что не так с прудами"}},{q="Что находится на дне Забытых прудов?",a="В оазисе под водой скрыта трещина, выпускающая в пруд пузырящиеся подземные газы. Она подтверждает, что внутренние энергии земли прорываются в поверхностные воды.",al={"what is in the water","forgotten pool fissure","what bubbles in the pool","что в воде","трещина забытых прудов","что пузырится в пруду"}},{q="Где находятся Забытые пруды?",a="Забытые пруды лежат неподалеку к северо-западу от Перекрестка, в центральной части Степей. Их легко узнать по внезапному кольцу пышных пальм и воды посреди сухой земли.",al={"forgotten pools location","where is forgotten pools","забытые пруды расположение","где забытые пруды"}},{q="Степи всегда были пустыней?",a="Согласно преданиям друидов, Степи когда-то были цветущим краем, полным жизни. Катаклизмы и древние войны выжгли землю и превратили ее в засушливую саванну, какой она предстает сегодня.",al={"was barrens always dry","ancient barrens","barrens history","всегда ли степи были сухими","древние степи","история степей"}},{q="Что дальше после осмотра Забытых прудов?",a="Tonga Runetotem takes your findings about the bubbling fissure and sends you to inspect another oasis in the Barrens: the Stagnant Oasis to the southeast.",al={"next quest","what to do after forgotten pools","следующее задание","что делать после забытых прудов"}}},fp="19,251,25.487.0,16.473.1,23.231.0,61.244.0,51.196.0,38.173.0,32.189.0,51.154.0"}
P.entries["quest:871"] = {n="Прекратить набеги",s="«Прекратить набеги» — раннее оборонительное задание, которое выдает Торк на Перекрестке в Степях. Свирепые свинобразы из племени Иглогривых перерезали пути снабжения, связывающие Дуротар с оплотом, и этим угрожают существованию поселения. Авантюристов Орды посылают проредить силы свинобразов, пока разведчики пытаются найти предводителя их отряда.",h="«Прекратить набеги» — раннее оборонительное задание, которое выдает Торк на Перекрестке в Степях.",kw={"barrens","crossroads","durotar","quilboar","razormane","thork","thornweaver","water seeker","степи","перекресток","дуротар","свинобраз","иглогривые","торк","шипоплет","искатель воды"},ang={["class:Hunter"]="Охота на Иглогривых охотников в зарослях проверяет навыки выслеживания на местных застрельщиках, прекрасно знающих местность.",["faction:Horde"]="Путь снабжения между Дуротаром и Перекрестком — главная артерия Орды в центральном Калимдоре; если позволить свинобразам перекрыть его, весь оплот рискует умереть от голода.",["race:Orc"]="Для орков, осваивающих Дуротар, Степи — необходимое пространство для расширения, поэтому неустанные засады свинобразов — препятствие, которое нужно устранить силой."},sec={{t="Перерезанная нить жизни",b="Перекресток — важнейший узел всех путей Орды через центральный Калимдор. Его выживание целиком зависит от грузовых повозок и караванов, везущих на запад из Дуротара пищу, железо и снаряжение. Когда Иглогривые устроили жестокие засады на северо-восточных тропах, эти важные поставки внезапно прекратились. Запасы тают, оборонные склады пустеют, и Торк не может позволить себе ждать мирных переговоров."},{t="Подрезка колючек",b="Не дожидаясь, пока свинобразы пойдут на прямой штурм стен города, Торк приказывает нанести упреждающие удары по их колючим логовам к северо-востоку от поселения. Удары по их искателям воды, шипоплетам и охотникам ослабляют разведывательный периметр и лишают отряды налетчиков магической и снабженческой поддержки. Эти первые стычки выигрывают драгоценное время, пока следопыты Орды прочесывают заросли, чтобы выяснить, кто организует набеги."}},faq={{q="Почему Иглогривые грабят караваны?",a="Племя Иглогривых считает засушливые равнины Степей своей родиной предков. Постройка Перекрестка и регулярные караваны Орды, пересекающие их охотничьи угодья, кажутся им недопустимым вторжением, и это толкает их на засады против обозов.",al={"why quilboar attack","razormane motivation","why attack durotar road","почему свинобразы нападают","мотивы иглогривых","почему нападают на дорогу в дуротар"}},{q="Кто такой Торк?",a="Торк — орк-командир, находящийся на Перекрестке. Он руководит повседневной обороной оплота, координирует разведчиков и поручает воинам защищать торговые дороги от враждебных кентавров, гарпий и свинобразов.",al={"who is thork","thork lore","crossroads leader","кто такой торк","торк предания","глава перекрестка"}},{q="Где находятся эти свинобразы?",a="Нужные стоянки Иглогривых лежат к востоку и северо-востоку от Перекрестка, у подножия гор, отделяющих Степи от Дуротара. Их легко узнать по высоким зарослям терновых лоз вокруг лагерей.",al={"where are razormane","razormane location","where are thornweavers","где иглогривые","расположение иглогривых","где шипоплеты"}},{q="Что дальше после прекращения набегов?",a="Сокращение рядов — лишь временная мера. Когда первый отряд будет разбит, а разведчики выяснят, кто командует налетчиками, Торк сразу поручит вам выследить их вождя в следующем задании — «Конец бесчинствам».",al={"what next after disrupt attacks","next quest after disrupt the attacks","что дальше после прекратить набеги","следующее задание после прекратить набеги"}},{q="Какую роль в племени играют искатели воды?",a="Вода — самый редкий и ценный ресурс в Степях. Искатели воды — важные снабженцы: они находят природные колодцы, оазисы и скрытые подземные источники, чтобы племя и его отряды не страдали от жажды в раскаленной пустоши.",al={"what is a water seeker","razormane water seeker lore","кто такой искатель воды","искатель воды иглогривых предания"}},{q="Кто такие шипоплеты?",a="Шипоплеты — геоманты и заклинатели свинобразов: они управляют землей и растят огромные непроходимые колючие заросли, охраняющие их логова. В бою они используют против чужаков местную магию природы.",al={"what is a thornweaver","quilboar thornweaver","что такое шипоплет","шипоплет свинобразов"}}},fp="19,357,18.459.0,20.455.0,39.258.0,13.219.0,33.244.0,42.241.1,45.241.0,22.211.0"}
P.entries["quest:8717"] = {s="Старейшина Лунный Страж — почитаемый дух предка, которого посещают во время Лунного фестиваля. Он стоит под небесным лучом света на Перекрестке в Степях. Беседа с ним дарит путникам древнюю мудрость и указывает путь к другим старейшинам, разбросанным по континенту.",h="Старейшина Лунный Страж — почитаемый дух предка, которого посещают во время Лунного фестиваля.",kw={"ancestor","crossroads","elder","elder moonwarden","elders","lunar festival","moonwarden","the barrens","предок","перекресток","старейшина","старейшина лунный страж","старейшины","лунный фестиваль","лунный страж","степи"},ang={["class:Druid"]="Друиды, настроенные на природу и лунные циклы, находят особый отклик в интересе Лунного Стража к небесным тайнам и звездным знамениям.",["faction:Alliance"]="Чтобы навестить Старейшину Лунного Стража, нужно отправиться прямо в сильно укрепленный оплот Орды на Перекрестке, и тихий миг почтения превращается в опасное проникновение.",["faction:Horde"]="Для странников Орды, пересекающих центральный перекресток Калимдора, почтить Старейшину Лунного Стража — удобная и важная часть празднования традиции предков."},sec={{t="Небесное присутствие в Степях",b="Посреди пыльной дороги Перекрестка стоит Старейшина Лунный Страж, окутанный сияющим столбом небесного света. Он представляет древних духов, которых чтят во время Лунного фестиваля, когда смертные прекращают вражду, чтобы отдать дань мудрости прошлых поколений."},{t="Путь к предкам",b="Старейшина Лунный Страж размышляет о звездном небе и о том, как оно способно раскрывать земные тайны тем, кто смотрит вверх в поисках истины. Помимо собственного благословения предков, он указывает ищущим путь к другим старейшинам Калимдора, среди которых Старейшина Кровавое Копыто, Старейшина Высокогор, Старейшина Утренняя Роса и Старейшина Рунический Тотем."}},faq={{q="Где найти Старейшину Лунного Стража?",a="Старейшина Лунный Страж стоит на Перекрестке в Степях; его легко заметить по яркому столбу звездного света, падающему сверху.",al={"elder moonwarden location","where is moonwarden","moonwarden crossroads","старейшина лунный страж где","где лунный страж","лунный страж перекресток"}},{q="Зачем посещать Старейшину Лунного Стража?",a="Путники посещают его во время Лунного фестиваля, чтобы почтить духов предков, получить знаки наследия и узнать дорогу к другим почитаемым старейшинам этих земель.",al={"why talk to moonwarden","moonwarden quest","lunar festival moonwarden","зачем говорить с лунным стражем","задание лунного стража","лунный фестиваль лунный страж"}},{q="К каким другим старейшинам Лунный Страж может вас направить?",a="Старейшина Лунный Страж сообщает, где находятся несколько соседних духов, в частности Старейшина Кровавое Копыто, Старейшина Высокогор, Старейшина Утренняя Роса и Старейшина Рунический Тотем.",al={"other elders","moonwarden elder directions","who does moonwarden mention","другие старейшины","куда направляет лунный страж","кого упоминает лунный страж"}},{q="Могут ли искатели приключений из Альянса говорить со Старейшиной Лунным Стражем?",a="Старейшины предков чтят любого храброго паломника независимо от принадлежности, но поскольку Лунный Страж стоит прямо в поселении Орды на Перекрестке, путникам из Альянса следует быть осторожными с местной стражей.",al={"can alliance talk to moonwarden","crossroads elder alliance","может ли альянс говорить с лунным стражем","старейшина перекрестка альянс"}},{q="Почему на Старейшину Лунного Стража падает луч света?",a="Как и все духи, являющиеся во время Лунного фестиваля, Старейшина Лунный Страж озарен небесным столбом лунного света, означающим связь со звездами и миром предков.",al={"light beam elder","pillar of light moonwarden","луч света старейшина","столб света лунный страж"}},{q="Что Старейшина Лунный Страж говорит о звездах?",a="Лунный Страж размышляет о том, что бесчисленные звезды на небесах хранят ответы на земные загадки, и спрашивает, не взглянут ли мудрые и удачливые вверх, чтобы найти истину.",al={"moonwarden dialogue","moonwarden quote","слова лунного стража","цитата лунного стража"}}},fp="20,276,35.288.0,25.338.0,34.133.0,49.163.0,48.156.0,53.213.0,57.181.0,47.162.0"}
P.entries["quest:8718"] = {n="Старейшина Быстрый Клинок",s="Старейшина Быстрый Клинок — дух предка, которого чтят во время Лунного фестиваля в столице ночных эльфов Дарнассе. Эта древняя фигура находится в Анклаве Кенария и делится с путниками мудростью звездных небес. Его благословение напрямую приобщает искателей приключений к почитаемым традициям Круга Кенария и народа ночных эльфов.",h="Старейшина Быстрый Клинок — дух предка, которого чтят во время Лунного фестиваля в столице ночных эльфов...",kw={"ancestors","bladeswift","coin of ancestry","craftsmen's terrace","darnassus","elder bladeswift","lunar festival","teldrassil","предки","быстрый клинок","монета наследия","терраса ремесленников","дарнасс","старейшина быстрый клинок","лунный фестиваль","тельдрассил"},ang={["class:Druid"]="Друиды, хранители природы, связанные с Кругом Кенария, несут глубокий культурный и духовный долг почитать древних духов, таких как Быстрый Клинок.",["faction:Alliance"]="Старейшина Быстрый Клинок находится в безопасности внутри Дарнасса и дарит героям Альянса легкое и мирное паломничество во время Лунного фестиваля.",["race:NightElf"]="Встреча со Старейшиной Быстрым Клинком в Дарнассе — прямое приобщение к небесному наследию вашего народа и его преданности небесам."},sec={{t="Дух ветвей",b="Во время Лунного фестиваля духи почитаемых предков являются по всему Азероту, чтобы поделиться мудростью и благословить путников. Старейшина Быстрый Клинок стоит среди безмятежных ветвей Анклава Кенария в Дарнассе. В отличие от нынешних жителей, поглощенных заботами настоящего, этот призрачный предок обращает взор к космосу, размышляя о тайнах, вплетенных в ночное небо."},{t="Звездный свет и древние истины",b="Культура ночных эльфов издавна чтит небесные тела как отражения Элуны и глубинных тайн бытия. Старейшина Быстрый Клинок напоминает подходящим, что бесчисленные звезды хранят ответы на земные трудности, и призывает мудрых и удачливых взглянуть вверх. Почтив его, искатели приключений получают Монету Наследия и участвуют в вечной церемонии, соединяющей мир смертных с духами прошлого."}},faq={{q="Кто такой Старейшина Быстрый Клинок?",a="Старейшина Быстрый Клинок — дух предка-ночного эльфа, которого чтят во время праздника Лунного фестиваля. Он появляется в Дарнассе, чтобы дать философское наставление и благословение путникам, желающим почтить своих предков.",al={"who is bladeswift","elder bladeswift lore","bladeswift identity","кто такой быстрый клинок","старейшина быстрый клинок предания","личность быстрого клинка"}},{q="Где найти Старейшину Быстрого Клинка?",a="Он стоит в Анклаве Кенария в столице ночных эльфов Дарнассе, глядя на тихие пруды и деревянные мостки города-дерева.",al={"bladeswift location","where is elder bladeswift","bladeswift darnassus","быстрый клинок где","где старейшина быстрый клинок","быстрый клинок дарнасс"}},{q="Зачем искать старейшин?",a="Посещение старейшин — основная традиция Лунного фестиваля. Отдавая дань уважения этим древним духам по всему миру, искатели приключений чтят мудрость прошлого и получают Монеты Наследия и праздничное благоволение.",al={"why find elders","lunar festival elders purpose","visiting elders","зачем искать старейшин","смысл старейшин лунного фестиваля","посещение старейшин"}},{q="Чему учит Быстрый Клинок тех, кто с ним говорит?",a="Старейшина Быстрый Клинок призывает ищущих смотреть на небеса. Он говорит, что бесчисленные звезды хранят глубокие истины и ответы на земные тайны для тех, кто достаточно терпелив и мудр, чтобы наблюдать за ними.",al={"bladeswift message","what does bladeswift say","послание быстрого клинка","что говорит быстрый клинок"}},{q="Могут ли представители Орды посетить Старейшину Быстрого Клинка?",a="Хотя Старейшина Быстрый Клинок находится в глубине Дарнасса — столицы Альянса, охраняемой бдительными Часовыми, — сам праздничный дух рад любому уважительному путнику, однако посетителям из Орды придется миновать враждебную стражу.",al={"can horde talk to bladeswift","horde bladeswift elder","bladeswift alliance only","может ли орда говорить с быстрым клинком","орда старейшина быстрый клинок","быстрый клинок только альянс"}},{q="Почему старейшина присутствует в Тельдрассиле, если это новое Мировое Древо?",a="Хотя Тельдрассил был выращен лишь недавно, после Третьей войны, духи предков кальдорай тянутся к живому сердцу своего народа и появляются рядом с сородичами, чтобы наблюдать за праздником.",al={"why is bladeswift in darnassus","teldrassil elder lore","почему быстрый клинок в дарнассе","старейшина тельдрассила предания"}}},fp="20,360,22.406.0,28.429.0,24.210.0,36.160.0,46.219.0,52.195.0,48.224.0,64.203.0"}
P.entries["quest:872"] = {n="Конец бесчинствам",s="Получив свидетельства целенаправленных набегов на линии снабжения Орды, Торк приказывает казнить Кринига Грознорыла, предводителя отряда Иглогривых свинобразов, организующего нападения на караваны из Дуротара. Сломив их оборону и добыв клык Крининга, Орда стремится привести воинственное племя в смятение.",h="Получив свидетельства целенаправленных набегов на линии снабжения Орды, Торк приказывает казнить Кринига...",kw={"barrens","caravans","crossroads","defender","durotar","geomancer","kreenig snarlsnout","quilboar","razormane","thork","степи","караваны","перекресток","защитник","дуротар","геомант","криниг грознорыл","свинобраз","иглогривые","торк"},ang={["faction:Horde"]="Путь снабжения между Дуротаром и Перекрестком — жизненно важная опора ранней экспансии Орды в Калимдоре; пока он открыт, внутренние форпосты выживут.",["race:Orc"]="Военная философия Торка отражает традиционную боевую доктрину орков: сломить волю врага, сразив его вождя на глазах у воинов."},sec={{t="Удар по голове",b="Важный торговый путь между Дуротаром и Перекрестком терпел непрерывные засады, угрожая поставкам провизии и подкреплений на севере Степей. Разведчики определили виновных: воинственный отряд Иглогривых свинобразов, организованный и возглавляемый вождем по имени Криниг Грознорыл. Понимая, что разрозненные стычки никогда не обезопасят дорогу, Торк приказал нанести прямой удар по предводителю, чтобы разрушить тактическую слаженность племени."},{t="Прорыв в лагерь",b="Крининг укрепил свой отряд в скалистых холмах к северо-востоку от Перекрестка, под защитой выносливых Иглогривых защитников и геомантов, управляющих иссушенной землей. Уничтожение его стражи и убийство Грознорыла в собственной твердыне должны были послать суровое послание всей равнине. Отрубленный клык Крининга стал неоспоримым доказательством того, что Орда не потерпит нападений на свои жизненные пути."}},faq={{q="Кто такой Криниг Грознорыл?",a="Криниг Грознорыл — известный предводитель набегов Иглогривых свинобразов, обосновавшийся к северо-востоку от Перекрестка. Он организовал согласованные нападения на караваны Орды на главной дороге из Дуротара, из-за чего Торк приказал его казнить.",al={"who is kreenig","kreenig snarlsnout lore","who leads the razormane raiders","кто такой крининг","криниг грознорыл предания","кто возглавляет налетчиков иглогривых"}},{q="Где находится Криниг Грознорыл?",a="Его можно найти в лагерях свинобразов к северо-востоку от Перекрестка, у подножия гор, чуть южнее главной дороги из Дуротара.",al={"where is kreenig","kreenig location","find kreenig snarlsnout","где крининг","местонахождение крининга","найти криниг грознорыл"}},{q="Зачем Торку клык Крининга?",a="Трофеи имеют культурное значение и для орков, и для свинобразов. Клык Крининга служит неоспоримым доказательством гибели предводителя и добавляет к поражению публичное унижение, лишая духа оставшихся бойцов Иглогривых.",al={"why kreenigs tusk","why take the tusk","thork tusk trophy","зачем клык крининга","зачем брать клык","торк клык трофей"}},{q="Чем убийство Крининга помогает Перекрестку?",a="Стратегия Торка основана на убеждении, что отряды свинобразов впадают в хаос без сильного предводителя. Убийство Крининга разрушает их тактическую организацию, сокращает согласованные засады на караваны и делает большую дорогу из Дуротара безопаснее для путников.",al={"why kill kreenig","strategic value of killing kreenig","crossroads caravan defense","зачем убивать крининга","стратегическая ценность убийства крининга","защита караванов перекрестка"}},{q="What role do Razormane Geomancers play in the tribe?",a="Геомант — заклинатель свинобразов, общающийся с духами земли и камня; он использует магию природы, чтобы воздвигать зазубренные терновые преграды и изменять суровую местность вокруг колючих лагерей для отражения захватчиков.",al={"what are geomancers","razormane geomancer lore","quilboar earth magic","кто такие геоманты","иглогривый геомант предания","магия земли свинобразов"}},{q="Какое задание предшествует этому поручению?",a="Это поручение непосредственно следует за заданием «Прекратить набеги», в котором разведчики впервые выяснили, насколько племя Иглогривых причастно к налетам на караваны на восточной границе.",al={"prerequisite quest","what comes before the disruption ends","previous quest","предыдущее задание","что перед концом бесчинствам","задание-предшественник"}}},fp="19,315,16.511.0,24.410.0,26.235.0,36.170.0,35.222.0,45.256.0,52.220.0,36.179.0"}
P.entries["quest:8721"] = {s="Старейшина Звездная Пряжа — задание Лунного фестиваля, которое встречается на Темных берегах. Искатели приключений находят Старейшину Звездную Пряжу в поселении Аубердин, чтобы почтить духов предков Калимдора. В ответ на уважение к древним традициям она дарит небесную мудрость и свое благословение.",h="Старейшина Звездная Пряжа — задание Лунного фестиваля, которое встречается на Темных берегах.",kw={"ancestor","auberdine","darkshore","elder bladeswift","elder starweave","lunar festival","starweave","предок","аубердин","темные берега","старейшина быстрый клинок","старейшина звездная пряжа","лунный фестиваль","звездная пряжа"},ang={["class:Druid"]="Друиды глубоко чтят духов предков и небесное равновесие, поэтому общение со Старейшиной Звездной Пряжей естественно отражает их убеждения.",["faction:Horde"]="Чтобы добраться до Старейшины Звездной Пряжи, странникам Орды приходится осторожно проникнуть в удерживаемые Альянсом доки Аубердина и почтить ее, не вызвав гнева местных часовых.",["race:NightElf"]="Почтив Старейшину Звездную Пряжу в Аубердине, ночные эльфы напрямую приобщаются к древним духам своих предков и почитаемым тайнам Элуны и звезд."},sec={{t="Маяк в Аубердине",b="Во время Лунного фестиваля духи почитаемых предков являются на континентах Азерота в столпах сияющего небесного света. Старейшина Звездная Пряжа занимает свое место среди ночных эльфов Аубердина — важного портового города на окутанном туманом побережье Темных берегов. Путники, чтящие праздник, совершают паломничество к ней, ища вечного наставления минувших веков."},{t="Шепот небес",b="Старейшина Звездная Пряжа созерцает космический гобелен над Калимдором и напоминает всем подходящим, что звезды хранят ответы на сомнения смертных и мирские загадки. Тем, кто находит время обратиться к ней за советом, она велит искать истину в небесах и дарует милость предков, а также вести о других странствующих духах диких рубежей."}},faq={{q="Где найти Старейшину Звездную Пряжу?",a="Старейшина Звездная Пряжа находится в прибрежном городе ночных эльфов Аубердине на Темных берегах. Она стоит в сиянии яркого лунного луча, спускающегося прямо с небес.",al={"starweave location","where is elder starweave","elder starweave darkshore","звездная пряжа где","где старейшина звездная пряжа","старейшина звездная пряжа темные берега"}},{q="В чем смысл этого задания?",a="Задание — часть ежегодного празднования Лунного фестиваля. Посещение и почитание старейшин предков, разбросанных по Азероту, приносит признание, праздничную валюту и благоволение предков.",al={"why do elder starweave","starweave the elder purpose","what does starweave do","зачем делать старейшина звездная пряжа","смысл звездной пряжи","что делает звездная пряжа"}},{q="Кто такая Старейшина Звездная Пряжа?",a="Это древний дух ночных эльфов, чтущий Лунный фестиваль. Озаренная звездным светом, она делится философской мудростью о созвездиях и направляет паломников к другим почитаемым старейшинам, например к Старейшине Быстрому Клинку.",al={"who is starweave","starweave lore","elder starweave backstory","кто такая звездная пряжа","звездная пряжа предания","старейшина звездная пряжа история"}},{q="Могут ли игроки Орды посетить Старейшину Звездную Пряжу?",a="Да. Старейшины фестиваля нейтральны и рады уважительным путникам обеих фракций. Однако поскольку Старейшина Звездная Пряжа находится в гавани Альянса Аубердине, искателям приключений из Орды следует быть осторожными с местной стражей ночных эльфов.",al={"can horde talk to starweave","horde elder starweave","starweave hostile horde","может ли орда говорить со звездной пряжей","орда старейшина звездная пряжа","звездная пряжа враждебна орде"}},{q="Что Старейшина Звездная Пряжа говорит путникам?",a="Встречая посетителей, она напоминает им, что бесконечные звезды наверху хранят ответы на загадки смертных, и спрашивает, не взглянут ли мудрые и удачливые вверх, чтобы раскрыть истину.",al={"starweave dialogue","what does elder starweave say","слова звездной пряжи","что говорит старейшина звездная пряжа"}},{q="На какого старейшину указывает Звездная Пряжа?",a="Старейшина Звездная Пряжа сообщает, где находится Старейшина Быстрый Клинок, и вести о нем, направляя путников дальше в праздничном путешествии по северному Калимдору.",al={"who does starweave mention","elder after starweave","next elder darkshore","кого упоминает звездная пряжа","старейшина после звездной пряжи","следующий старейшина темные берега"}}},fp="19,290,21.400.0,23.337.0,33.177.0,34.189.0,23.222.0,40.247.0,41.170.0,36.149.0"}
P.entries["quest:8724"] = {n="Старейшина Утренняя Роса",s="Старейшина Утренняя Роса — почитаемый дух предка, которого посещают во время Лунного фестиваля в Тысяче Игл. Озаренная сияющим лучом звездного света, она делится древней мудростью и направляет паломников к другим старейшинам, разбросанным по Калимдору.",h="Старейшина Утренняя Роса — почитаемый дух предка, которого посещают во время Лунного фестиваля в Тысяче Игл.",kw={"ancestor","elder morningdew","elders","lunar festival","morningdew the elder","shimmering flats","starlight","thousand needles","предок","старейшина утренняя роса","старейшины","лунный фестиваль","мерцающие равнины","звездный свет","тысяча игл"},ang={["class:Druid"]="Лунный фестиваль и его небесные старейшины воплощают глубокую связь с Элуной, природой и общением с предками, священную для кругов Кенария.",["class:Shaman"]="Общение с почитаемыми духами, такими как Старейшина Утренняя Роса, — основа понимания равновесия предков и стихий в мире.",["race:NightElf"]="Старейшины, озаренные звездным светом, напоминают о древних традициях почитания небес и о древней мудрости, вплетенной в историю Калимдора.",["race:Tauren"]="Почитание мудрости старейшин-предков — опора культуры тауренов, поэтому паломничество к таким духам, как Утренняя Роса, глубоко значимо."},sec={{t="Небесное присутствие в каньонах",b="Во время Лунного фестиваля духи древних предков являются по всему Азероту, чтобы поделиться благословением с путниками. Старейшина Утренняя Роса предстает купающейся в столбе лунного света, резко выделяясь на фоне пыльного красного камня и шумной промышленной суеты Тысячи Игл. Она напоминает смертным путникам смотреть за пределы земных забот — на звездный простор над головой."},{t="Мудрость небес",b="Когда к ней подходят, Утренняя Роса призывает ищущих обратиться к бесчисленным звездам за ответами на земные тайны. Помимо созерцательных приветствий, она служит проводником для паломников фестиваля и сообщает, где находятся другие почитаемые духи, бродящие по землям: Старейшина Высокогор, Старейшина Зловещий Тотем, Старейшина Странница Туманов, Старейшина Лунный Страж и Старейшина Тотем Ветра."}},faq={{q="Кто такая Старейшина Утренняя Роса?",a="Старейшина Утренняя Роса — дух предка, являющийся во время Лунного фестиваля. Озаренная звездным светом, она дарует мудрость и наставления проходящим мимо искателям приключений, желающим почтить старейшин.",al={"elder morningdew","morningdew lore","who is morningdew","старейшина утренняя роса","утренняя роса предания","кто такая утренняя роса"}},{q="Где найти Старейшину Утреннюю Росу?",a="Она находится в Тысяче Игл; ее место отмечено сияющим столбом света, нисходящим с неба.",al={"morningdew location","where is elder morningdew","find elder morningdew","утренняя роса местоположение","где старейшина утренняя роса","найти старейшину утренняя роса"}},{q="Зачем посещать Старейшину Утреннюю Росу?",a="Путники приходят к ней во время Лунного фестиваля, чтобы почтить предков, получить благословение предков и узнать, где находятся другие старейшины в этом краю.",al={"why visit morningdew","morningdew purpose","lunar festival elder","зачем посещать утреннюю росу","цель утренней росы","старейшина лунного фестиваля"}},{q="О каких других старейшинах знает Утренняя Роса?",a="Старейшина Утренняя Роса указывает путь к пяти другим почитаемым духам: Старейшине Высокогору, Старейшине Зловещему Тотему, Старейшине Страннице Туманов, Старейшине Лунному Стражу и Старейшине Тотему Ветра.",al={"morningdew other elders","elders list morningdew","who does morningdew mention","другие старейшины утренней росы","список старейшин утренняя роса","кого упоминает утренняя роса"}},{q="Почему на нее падает столб света?",a="Каждый дух предка во время Лунного фестиваля освещен лучом небесного звездного света, подчеркивающим его неземное присутствие и связь с небесами.",al={"morningdew light beam","shaft of light elder","why does elder glow","луч света утренняя роса","столб света старейшина","почему старейшина светится"}},{q="Чему Утренняя Роса учит паломников?",a="Утренняя Роса учит, что небеса и их бесчисленные звезды хранят ответы на земные тайны, и призывает мудрых и удачливых смотреть вверх, чтобы найти истину.",al={"morningdew advice","morningdew dialogue","what does morningdew say","совет утренней росы","диалог утренней росы","что говорит утренняя роса"}}},fp="20,244,35.371.0,21.382.0,24.184.0,36.104.0,49.179.0,46.162.0,51.171.0,36.171.0"}
P.entries["quest:8725"] = {n="Старейшина Речная Песня",kw={"ancestor","ashenvale","astranaar","elder","lunar festival","riversong","shrine","starweave","предок","ясеневый лес","астранаар","старейшина","лунный фестиваль","речная песня","святилище","звездная пряжа"},ang={["class:Druid"]="Лунный фестиваль и его небесные старейшины воплощают древнюю связь Кенария с природой, духами и ночным небом.",["faction:Alliance"]="Астранаар — один из главных оплотов Альянса в центральном Калимдоре, поэтому посетить Старейшину Речную Песню во время Лунного фестиваля для паломников Альянса легко и приятно.",["race:NightElf"]="Для ночных эльфов почтить Старейшину Речную Песню под святилищем Астранаара — глубоко личный акт общения с долгой историей их народа под звездами Ясеневого леса."},sec={{t="Маяк в Астранааре",b="Среди древних ветвей и деревянных мостков Астранаара Старейшина Речная Песня является под открытым святилищем ночных эльфов. Ее неземное присутствие, отмеченное ярким столбом небесного света, пронзающим кроны Ясеневого леса, становится центром притяжения для участников Лунного фестиваля, ищущих общения с прошлыми поколениями."},{t="Взгляд на небеса",b="Старейшина Речная Песня напоминает паломникам о древней традиции ночных эльфов читать истину и тайну в звездном небе. Ее слова призывают путников искать мудрость в терпении и размышлении и направляют почитающих этот праздник к другим духам, в том числе к Старейшине Звездной Пряже."}},faq={{q="Где найти Старейшину Речную Песню?",a="Старейшина Речная Песня стоит в поселении Астранаар в Ясеневом лесу. Она находится под небольшим святилищем ночных эльфов, озаренная ярким лучом звездного света, спускающимся сквозь лесной полог.",al={"riversong location","where is riversong","elder riversong loc","речная песня местоположение","где речная песня","старейшина речная песня"}},{q="Зачем посещать Старейшину Речную Песню?",a="Посещение Старейшины Речной Песни — часть почитания предков во время Лунного фестиваля. Беседа с ней дарует благословение предков и монеты предков, а также подсказывает, где искать других старейшин Калимдора.",al={"why visit riversong","what does riversong do","зачем посещать речную песню","что дает речная песня"}},{q="К какому старейшине направляет вас Речная Песня?",a="Старейшина Речная Песня направляет ищущих к Старейшине Звездной Пряже — другому почитаемому духу ночных эльфов, наблюдающему за праздником.",al={"next elder after riversong","who does riversong mention","следующий старейшина после речной песни","кого упоминает речная песня"}},{q="Могут ли игроки Орды говорить со Старейшиной Речной Песней?",a="Поскольку Старейшина Речная Песня находится прямо в Астранааре, центре Альянса, игрокам Орды придется иметь дело со стражниками и часовыми города, чтобы подойти к ней, хотя сами старейшины фестиваля не отказывают в общении по принадлежности к фракции.",al={"can horde visit riversong","is riversong alliance only","может ли орда посетить речную песню","речная песня только для альянса"}},{q="Почему Старейшину Речную Песню окружает луч света?",a="Столб небесного света означает благосклонность Элуны и небес и освещает каждого духа предка, являющегося во время Лунного фестиваля.",al={"why does riversong glow","light on riversong","почему речная песня светится","свет на речной песне"}},{q="Что говорит Старейшина Речная Песня, когда ее почтили?",a="Старейшина Речная Песня размышляет о космосе, замечая, что бесчисленные звезды на небесах хранят ответы на земные тайны, и спрашивает, не взглянут ли мудрые и удачливые вверх, чтобы найти истину.",al={"riversong quote","riversong dialogue","цитата речной песни","диалог речной песни"}}},fp="19,284,21.317.0,21.282.0,33.194.0,48.226.0,45.111.0,43.226.0,53.152.0,43.188.0"}
P.entries["quest:873"] = {n="Иша Авак",s="Иша Авак — священный обряд охоты, который дает мистик Марен Небесная Провидица на Торговом побережье. Отважным странникам Орды поручено нырнуть в Великое море, выследить и убить грозного морского хищника, известного как Глубинная Погибель. Забрав сердце зверя, охотник вступает в древнюю связь духа и уважения.",h="Иша Авак — священный обряд охоты, который дает мистик Марен Небесная Провидица на Торговом побережье.",kw={"deep doom","heart of isha awak","isha awak","mahren skyseer","merchant coast","ratchet","sea beast","глубинная погибель","сердце иша авака","иша авак","марен небесная провидица","торговое побережье","кабестан","морской зверь"},ang={["class:Hunter"]="Выслеживание легендарного морского зверя в глубинах Великого моря — высшее испытание терпения, хитрости и меткости против создания, властвующего в своих владениях.",["faction:Horde"]="Победа над Глубинной Погибелью доказывает воинское превосходство Орды на Торговом побережье: убит левиафан, терроризировавший местные заставы Альянса.",["race:Tauren"]="Охота на Ишу Авак отражает традиционные духовные обычаи тауренов: добычу уважают, а не презирают, и отнятая жизнь дарует единение с духом существа."},sec={{t="Глубинная Погибель",b="У побережья к югу от Кабестана, скрываясь под волнами, бродит Иша Авак. Известное как Глубинная Погибель, это огромное морское создание властвует над прибрежными водами с грозной силой и хищной торжественностью. Люди-захватчики, расположившиеся вдоль берега, научились бояться этих вод: они потеряли множество разведчиков и солдат из-за неутомимого голода чудовища."},{t="Охота духа",b="В отличие от напуганных людей на берегу, Марен Небесная Провидица глубоко чтит левиафана. Для тауренской мистика Иша Авак — не проклятие и не простая досада, а дар: достойный и честный противник, чья мощь испытывает решимость истинных охотников. Убить зверя — значит не просто истребить хищника, а совершить акт духовного единения: забрать сердце, в котором обитает сущность зверя, и унести дальше его необузданный дух."}},faq={{q="Кто такой Иша Авак?",a="Иша Авак, носящий титул Глубинная Погибель, — могучий морской зверь, рыщущий в водах у восточного побережья Степей, к югу от Кабестана. Его считают владыкой этих прибрежных вод, и он известен тем, что охотится на людей — моряков и солдат, расквартированных поблизости.",al={"what is isha awak","isha awak lore","deep doom","что такое иша авак","иша авак предания","глубинная погибель"}},{q="Почему Марен Небесная Провидица хочет убить Ишу Авак?",a="Марен охотится на Ишу Авак не из злобы или страха. Она видит в этом великом хищнике достойного, благородного противника и духовное испытание. По мнению Марен, победа над таким зверем позволяет охотнику впитать его силу и соединиться с его диким духом.",al={"why kill isha awak","mahren skyseer motivation","зачем убивать иша авака","мотивация марен небесная провидица"}},{q="Где можно найти Ишу Авак?",a="Зверь плавает в Великом море у Торгового побережья в восточных Степях, к югу от гоблинского порта Кабестан и рядом с берегами, где живут люди.",al={"isha awak location","where to find isha awak","isha awak spawn","иша авак местоположение","где найти иша авака","иша авак появление"}},{q="Что происходит, когда вы приносите сердце?",a="Марен Небесная Провидица считает, что сущность и судьба существа заключены в его сердце. Преподнеся его мистику, вы духовно связываете себя с павшим левиафаном и несете с собой частицу силы и хищного зрения Иши Авак.",al={"heart of isha awak purpose","why heart of isha awak","сердце иша авака назначение","зачем сердце иша авака"}},{q="О каких людях говорит Марен?",a="Речь идет о силах Терамора и Кул Тираса, действующих на побережье Степей, особенно вокруг Крепости Северной Стражи и соседних застав. Они потеряли множество моряков и жителей побережья в пасти морского зверя.",al={"which humans","humans on the coast","who fears isha awak","какие люди","люди на побережье","кто боится иша авака"}},{q="Иша Авак — элементаль или обычное животное?",a="Иша Авак — природный, хотя и исключительно крупный и сильный водный зверь Великого моря, которого местные таурены чтят за первозданный дух и охотничье мастерство.",al={"is isha awak a beast","isha awak creature type","иша авак зверь","тип существа иша авак"}}},fp="9,333,13.371.0,16.429.0,17.266.0,45.251.0,29.158.0,43.250.0,39.242.0,57.163.0"}
P.entries["quest:874"] = {n="Марен Небесная Провидица",s="Марен Небесная Провидица — путь Орды, направляющий проверенных охотников из Лагеря Таурахо к восточным берегам Степей. Овладев охотой на хищников равнин, искатели приключений получают от Джорна Заклинателя Небес задание научиться у его сестры прибрежному выслеживанию. Чтобы найти ее, нужно преодолеть воды и лагеря людей на Торговом побережье.",h="Марен Небесная Провидица — путь Орды, направляющий проверенных охотников из Лагеря Таурахо к восточным...",kw={"camp taurajo","hunting trial","isha awak","jorn skyseer","mahren skyseer","sergra darkthorn","the barrens","лагерь таурахо","охотничье испытание","иша авак","джорн заклинатель небес","марен небесная провидица","сергра темный шип","степи"},ang={["class:Hunter"]="Для охотников это задание означает переход от преследования привычной дичи саванн к охоте на свирепых водных зверей под руководством опытных тауренских следопытов.",["faction:Horde"]="Путешествие к восточному побережью приводит разведчиков Орды в опасную близость к враждебным опорным пунктам Альянса, наступающим со стороны Терамора.",["race:Tauren"]="Брат и сестра Небесные Провидцы воплощают традиционную охотничью философию тауренов, проверяя, смогут ли дети Матери-Земли выдержать испытания в любой среде."},sec={{t="Охота за пределами равнин",b="Через испытания, устроенные Джорном Заклинателем Небес в Лагере Таурахо, охотники доказывают свою стойкость против самых опасных зверей, рыскающих по красным равнинам южных Степей. Но Джорн учит, что истинный хищник никогда не ограничивает себя сухой землей и холмистыми саваннами. Чтобы по-настоящему овладеть ремеслом, следопыт должен быть готов выслеживать добычу в болотах, на отвесных скалах и среди бурных волн Великого моря."},{t="Восточный берег",b="Сестра Джорна, Марен Небесная Провидица, разбила лагерь далеко на востоке, на побережье. Пока Джорн изучает духов громовых ястребов и равнинных охотников, Марен посвятила себя неуловимым созданиям, обитающим в соленых брызгах. Путь к ней опасен: морпехи Кул Тираса и экспедиционные силы Терамора держат укрепленные заставы и сторожевые башни на прибрежных низменностях."}},faq={{q="Кто дает задание «Марен Небесная Провидица»?",a="Джорн Заклинатель Небес дает это задание в Лагере Таурахо в южных Степях после того, как вы успешно завершите его охоту на громовых ястребов.",al={"who starts mahren skyseer","jorn skyseer quest giver","кто начинает марен небесная провидица","джорн заклинатель небес выдает задание"}},{q="Где находится Марен Небесная Провидица?",a="Марен Небесная Провидица разбила лагерь на восточном побережье Степей, к югу от Кабестана, рядом с берегами, где бродят прибрежные животные и войска Терамора.",al={"where is mahren skyseer","mahren skyseer location","find mahren","где марен небесная провидица","марен небесная провидица местоположение","найти марен"}},{q="Какова цель этого задания?",a="Это связующее задание, соединяющее охотничьи испытания Джорна Заклинателя Небес в Лагере Таурахо с прибрежными охотничьими испытаниями Марен против морских созданий.",al={"why do i need to find mahren","mahren skyseer objective","зачем искать марен","цель марен небесная провидица"}},{q="Почему Джорн посылает охотников к Марен?",a="Джорн считает, что настоящий охотник должен овладеть всеми средами, включая море. Его сестра Марен специализируется на выслеживании водных зверей и схватках с ними, поэтому она — идеальный наставник.",al={"why does jorn send me to his sister","lore behind mahren skyseer","почему джорн посылает меня к сестре","предыстория марен небесная провидица"}},{q="Какие опасности ждут на пути к Марен?",a="Восточное побережье Степей плотно занято враждебными экспедиционными силами людей из Терамора и Кул Тираса, а также агрессивными прибрежными ящерами-хищниками и морскими хищниками.",al={"dangers reaching mahren","who holds the coast","опасности на пути к марен","кто держит побережье"}},{q="Что будет после встречи с Марен Небесной Провидицей?",a="Когда вы представитесь и заслужите ее доверие, Марен поручит вам выследить Ишу Авак — огромное свирепое морское существо, обитающее в этих водах.",al={"next quest after mahren","what does mahren give you","следующее задание после марен","что дает марен"}}},fp="14,334,24.399.0,17.397.0,35.131.0,32.158.0,34.148.0,37.184.0,41.176.0,40.152.0"}
P.entries["quest:875"] = {n="Лейтенанты гарпий",s="«Лейтенанты гарпий» — задание Орды, которое выдает Дарсок Быстрый Нож на Перекрестке. В ходе военной кампании против ковена Зачарованного Крыла на севере Степей защитников посылают в Сухие холмы убить офицеров передовой стаи и разрушить цепочку командования.",h="«Лейтенанты гарпий» — задание Орды, которое выдает Дарсок Быстрый Нож на Перекрестке.",kw={"barrens","crossroads","darsok swiftdagger","dry hills","harpy lieutenant ring","harpy lieutenants","serena bloodfeather","witchwing slayer","степи","перекресток","дарсок быстрый нож","сухие холмы","кольцо лейтенанта гарпий","лейтенанты гарпий","серена кровавое перо","убийца зачарованного крыла"},ang={["class:Rogue"]="Дарсок Быстрый Нож делает ставку на точечные убийства ценных офицеров, а не на дорогостоящую открытую войну, что напрямую соответствует умениям разбойников.",["faction:Horde"]="Защита северных проходов Степей необходима для создания устойчивой связи между Дуротаром, Мулгором и лесозаготовительными лагерями Ясеневого леса."},sec={{t="Охота на офицеров",b="После первых стычек с рядовыми налетчицами Зачарованного Крыла Дарсок Быстрый Нож усиливает наступление на гарпий, гнездящихся в Сухих холмах. Вместо того чтобы и дальше прореживать рядовых, Дарсок поручает разведчикам Орды выследить убийц Зачарованного Крыла, служащих лейтенантами. Эти офицеры поддерживают дисциплину среди низших в стае и координируют набеги на пути снабжения Орды, поэтому их уничтожение крайне важно для защиты северных подступов к Степям."},{t="Знаки отличия",b="Убийцы Зачарованного Крыла ведут сородичей жестокой силой и господством, и лишь самые свирепые из них носят украшенные кольца, означающие власть в их матриархате. Эти кольца служат доказательством смерти, нарушают тактическое взаимодействие стаи и посылают ковену прямое, безжалостное сообщение: нападения на земли Орды повлекут решительное возмездие."},{t="Путь к матриарху",b="Убийство этих офицеров приводит низших в смятение, но служит и более широкой стратегической цели. Лишив гнездовье Зачарованного Крыла полевых командиров, вы ослабляете оборону на высотах Сухих холмов и открываете путь к убежищу их матриарха, Серены Кровавое Перо."}},faq={{q="Где найти лейтенантов гарпий?",a="Лейтенанты гарпий обитают в Сухих холмах — изрезанной каньонами области на дальнем севере Степей, к северо-западу от Перекрестка. Ищите убийц Зачарованного Крыла, патрулирующих холмы.",al={"lieutenant location","where are witchwing slayers","harpy lieutenant rings location","где лейтенанты","где убийцы зачарованного крыла","где кольца лейтенантов гарпий"}},{q="Как отличить этих лейтенантов среди стаи?",a="В ковене Зачарованного Крыла лейтенантами служат только убийцы Зачарованного Крыла. Они носят особые кольца гарпий, означающие власть над младшими разведчицами и налетчицами.",al={"which harpies have rings","witchwing slayer identification","у каких гарпий есть кольца","как опознать убийцу зачарованного крыла"}},{q="Кто выдает это задание на охоту?",a="Дарсок Быстрый Нож, орк-разведчик и координатор на Перекрестке в Степях, поручает этот контракт, чтобы защитить интересы Орды и покарать набеги гарпий.",al={"who gives harpy lieutenants","darsok swiftdagger role","кто дает лейтенантов гарпий","дарсок быстрый нож роль"}},{q="Why does the Horde want to kill the lieutenants instead of just regular harpies?",a="Лейтенанты направляют младших подчиненных и организуют хищные налеты. Их уничтожение разрушает руководство матриархата и оставляет прочих гарпий разрозненными и уязвимыми.",al={"why kill lieutenants","harpy chain of command","зачем убивать лейтенантов","командование гарпий"}},{q="Что будет после уничтожения лейтенантов?",a="Когда лейтенанты убиты, Дарсок Быстрый Нож посылает защитников выследить саму матриарха стаи, Серену Кровавое Перо, на самых высоких утесах Сухих холмов.",al={"next quest after lieutenants","what to do next","следующее задание после лейтенантов","что делать дальше"}},{q="Чем гарпии Зачарованного Крыла угрожают Перекрестку?",a="Ковен Зачарованного Крыла наводнил северные перевалы Степей и охотится на путников, торговые караваны и патрули, пытающиеся пройти между Перекрестком, Дуротаром и Ясеневым лесом.",al={"why fight harpies","witchwing threat","зачем сражаться с гарпиями","угроза зачарованного крыла"}}},fp="17,291,22.478.0,14.395.0,23.287.1,38.194.0,53.172.0,23.169.0,80.191.0,45.180.1,57.185.0"}
P.entries["quest:876"] = {n="Серена Кровавое Перо",s="Это задание на охоту поручает приключенцам Орды убить Серену Кровавое Перо, матриарха, которая ведет набеги гарпий на пути снабжения Перекрестка. Ее поход — личная кровная месть за сестру, убитую героем Орды Рексаром. Смерть Серены призвана разрушить согласованность действий стаи гарпий на севере Степей.",h="Это задание на охоту поручает приключенцам Орды убить Серену Кровавое Перо, матриарха, которая ведет набеги...",kw={"barrens","bloodfeather","crossroads","darsok","harpy","rexxar","serena","swiftdagger","степи","кровавое перо","перекресток","дарсок","гарпия","рексар","серена","быстрый нож"},ang={["class:Rogue"]="Дарсок Быстрый Нож ценит хладнокровную эффективность и призывает быстро перерезать Серене горло, а не затевать долгую драку.",["faction:Horde"]="Северные торговые пути через Перекресток жизненно важны для снабжения застав орков и связи Дуротара с Мулгором и Когтистыми горами; разгром организованных налетчиц-гарпий держит эти артерии открытыми.",["race:Orc"]="Эта охота завершает незаконченное дело, уходящее корнями в подвиги Рексара, и пробуждает яростный дух ранних пограничных битв Дуротара."},sec={{t="Наследие мести",b="Гарпии Зачарованного Крыла, наводнившие скалы к северо-западу от Перекрестка, нападают не только из звериного голода. Их предводительница, Серена Кровавое Перо, ведет открытую кровную войну против Орды. Много лет назад, при основании Дуротара, странствующий укротитель Рексар убил сестру Серены, известную матриарха по имени Кровавое Перо. Охваченная ненавистью к молодой Орде, Серена сплотила свою стаю в организованную напасть, стремящуюся истреблять обозы, разведчиков и торговцев на засушливых тропах."},{t="Отсечь голову",b="Дарсок Быстрый Нож на Перекрестке руководил систематическим истреблением гарпий — от мелких налетчиц до опытных лейтенантов. Смерть Серены станет последним, решающим ударом по угрозе. Дарсок прямо требует ее отсеченную голову не только как доказательство, но и как жуткий трофей, который будет закреплен на следующем уходящем караване. Подняв голову матриарха перед уцелевшими гарпиями, Орда надеется устрашить стаю и заставить ее отказаться от нападений на жизненные пути Степей."}},faq={{q="Почему Серена Кровавое Перо нападает на караваны Орды?",a="Серена жаждет мести Орде. Ее сестру, матриарха гарпий Кровавое Перо, убил защитник из народа мок'натал Рексар при основании Дуротара. Серена направляет свою стаю против обозов и путников Орды в отместку за смерть сестры.",al={"why do harpies attack caravans","serena motivation","why serena mad","почему гарпии нападают на караваны","мотив серены","почему серена злится"}},{q="Кем была Кровавое Перо?",a="Кровавое Перо была известной предводительницей гарпий, много лет назад терроризировавшей окраины Дуротара и Степей. Рексар выследил и убил ее во время службы вождю Траллу. Серена — ее уцелевшая сестра, которая приняла ее власть и обиду.",al={"serena sister","original bloodfeather","rexxar bloodfeather","сестра серены","первая кровавое перо","рексар кровавое перо"}},{q="Почему Дарсок Быстрый Нож хочет ее голову?",a="Помимо подтверждения ее гибели, Дарсок намерен закрепить отсеченную голову Серены на повозке уходящего каравана. Он уверен, что судьба матриарха станет суровым предупреждением для уцелевших гарпий, которые вздумают нападать на пути снабжения Орды.",al={"why darsok wants head","darsok swiftdagger head caravan","зачем дарсоку голова","дарсок быстрый нож голова караван"}},{q="Где можно найти Серену Кровавое Перо?",a="Серена гнездится высоко на неровных утесах и выветренных скалах к северо-западу от Перекрестка в окружении элитных лейтенантов и стражей ковена Зачарованного Крыла.",al={"serena bloodfeather location","where is serena","serena spawn","где серена кровавое перо","где серена","появление серены"}},{q="Что происходит после победы над Сереной?",a="Когда угроза гарпий устранена, Дарсок посылает надежных наемников помочь другим союзникам, вручая им письмо для знахаря Джин'Зила в Когтистых горах.",al={"what next after serena","quest chain after serena","что после серены","цепочка заданий после серены"}},{q="Кто выдал это задание на охоту?",a="Дарсок Быстрый Нож, орк-разведчик и оперативник на Перекрестке, следит за подавлением диких угроз торговым путям и выдает это задание, когда низшие ряды стаи Серены уничтожены.",al={"who gives serena quest","darsok role","кто дает задание про серену","роль дарсока"}}},fp="19,354,21.528.0,20.514.1,52.269.0,21.244.0,42.251.0,39.160.0,38.190.1,25.212.0"}
P.entries["quest:878"] = {n="Воюющие племена",s="«Воюющие племена» — задание Орды, которое выдает плененный свинобраз Кривозуб в Лагере Таурахо. Таурены заперли Кривозуба за решеткой, и он выменивает важные сведения о вторжениях свинобразов на убийство вражеских духовных вождей Дыбогривов.",h="«Воюющие племена» — задание Орды, которое выдает плененный свинобраз Кривозуб в Лагере Таурахо.",kw={"barrens","bristleback","camp taurajo","geomancer","mangletooth","razormane","thork","thornweaver","tribes at war","water seeker","степи","дыбогрив","лагерь таурахо","геомант","кривозуб","иглогривые","торк","ткач шипов","воюющие племена","искатель воды"},ang={["class:Shaman"]="Геоманты-свинобразы повелевают землей и камнем через первобытные договоры с древними духами, показывая шаманам грубое, но мощное искажение почитания стихий.",["faction:Horde"]="Лагерь Таурахо окружен враждебными зарослями, поэтому любая возможность натравить диких свинобразов друг на друга — тактическая победа для линий снабжения Орды.",["race:Tauren"]="Как хранители Лагеря Таурахо, таурены терпят присутствие Кривозуба в лагере, лишь пока его обиды приносят безопасность южному рубежу."},sec={{t="Сделка пленника",b="Запертый в клетке в Лагере Таурахо, свинобраз из Иглогривых Кривозуб доказывает, что плен не притупляет старую ненависть. Степи давно оспаривают два главных племени свинобразов: Иглогривые и Дыбогривы. Пока Орда пытается защитить свои поселения и линии снабжения от внезапных засад, Кривозуб предлагает ценные сведения о том, кто на самом деле терзает форпост Торка, — но сначала герой Орды должен перебить самых почитаемых заклинателей Дыбогривов."},{t="Охота на ткачей земли",b="Кривозуб направляет искателей приключений на север, к мистическому ядру Дыбогривов: их искателям воды, ткачам шипов и геомантам. Оба племени чтят землю и черпают силу из древней магии, связанной с их прародителем-полубогом Агамагганом. Уничтожив их заклинателей, Орда наносит сокрушительный удар по ритуальной мощи Дыбогривов, оставляя их уязвимыми перед соперниками Иглогривыми и ослабляя давление на ближние тропы."},{t="Горькие откровения",b="Когда задание выполнено, месть не приносит Кривозубу покоя. Вместо радости от потерь Дыбогривов пленник впадает в ярость из-за собственной брошенности. Хотя он из-за железных прутьев устраивал удары на благо своего племени, Иглогривые не прислали отряд спасения в Лагерь Таурахо. Отвергнутый и забытый, Кривозуб обращает взор к еще более глубоким тайнам свинобразов, открывая путь к силе крови Агамаггана."}},faq={{q="Почему Кривозуб сидит в клетке в Лагере Таурахо?",a="Кривозуб — свинобраз из Иглогривых, захваченный силами Орды в Лагере Таурахо. Таурены держат его в плену, чтобы предотвратить набеги и выведать у него сведения о вторжениях свинобразов в южные Степи.",al={"why is mangletooth caged","who captured mangletooth","mangletooth cage","почему кривозуб в клетке","кто поймал кривозуба","клетка кривозуба"}},{q="Из-за чего вражда между Иглогривыми и Дыбогривами?",a="Иглогривые и Дыбогривы — соперничающие племена свинобразов, яростно борющиеся за земли, скудную воду и священные поросшие шипами места Степей. Несмотря на общее духовное происхождение от Великого Вепря Агамаггана, они ненавидят друг друга и постоянно сражаются за власть над равнинами.",al={"bristleback vs razormane","why do quilboar fight each other","quilboar war","дыбогривы и иглогривые","почему свинобразы воюют друг с другом","война свинобразов"}},{q="Почему Кривозуб хочет смерти именно их духовных вождей?",a="Война свинобразов сильно зависит от их связи с землей и магии крови. Геоманты, ткачи шипов и искатели воды поддерживают жизнь племени, призывают в бою камень и терновник и направляют воинов. Удар по заклинателям подрывает боевой дух и лишает племя боевой силы.",al={"why kill geomancers","bristleback casters","water seekers and thornweavers","зачем убивать геомантов","заклинатели дыбогривов","искатели воды и ткачи шипов"}},{q="Кто такой Торк и почему о нем упоминает Кривозуб?",a="Торк — орочий офицер, отвечающий за действия и безопасность Орды на Перекрестке и по всем Степям. Его отряды терпят неослабный натиск военных отрядов свинобразов, поэтому сведения об их передвижениях крайне ценны.",al={"who is thork","thork camp taurajo","thork horde","кто такой торк","торк лагерь таурахо","торк орда"}},{q="Что происходит после выполнения этого задания?",a="Озлобленный тем, что племя не спасло его, Кривозуб предлагает раскрыть тайну Кровавых осколков. Это открывает задание «Кровавые осколки Агамаггана», позволяющее в итоге обменивать осколки, найденные на свинобразах, на различные благословения племенных духов.",al={"tribes at war follow up","what unlocks after tribes at war","next quest after mangletooth","воюющие племена продолжение","что открывается после воюющих племен","следующее задание после кривозуба"}},{q="Где найти духовников Дыбогривов?",a="Искатели воды, ткачи шипов и геоманты Дыбогривов обитают в колючих зарослях, лагерях и оврагах, принадлежащих племени Дыбогривов в южных Степях, к северу от Лагеря Таурахо.",al={"bristleback water seeker location","where are thornweavers","bristleback geomancers location","где искатели воды дыбогривов","где ткачи шипов","где геоманты дыбогривов"}}},fp="13,264,20.484.0,26.422.0,18.443.1,52.225.0,59.302.0,68.295.0,51.234.0,41.253.1,46.186.0"}
P.entries["quest:879"] = {n="Предан своими",s="«Предатель в наших рядах» — задание, которое дает Кривозуб, заключенный в клетке свинобраз в Лагере Таурахо. Отвергнутый и брошенный на смерть собственными сородичами, Кривозуб жаждет кровавой мести трем полководцам Иглогривых, которые вышли из Лабиринтов Иглошкурых и организуют нападения по всем Степям.",h="«Предатель в наших рядах» — задание, которое дает Кривозуб, заключенный в клетке свинобраз в Лагере Таурахо.",kw={"barrens","camp taurajo","kraul","kuz","lok orcbane","mangletooth","nak","razormane","thork","степи","лагерь таурахо","лабиринты","каз","лок губитель орков","кривозуб","нак","иглогривые","торк"},ang={["faction:Horde"]="Остановив Лока Губителя Орков и его приспешников, Орда бьет прямо по вождям, повинным в жестоких нападениях на караваны и форпосты Орды по всем южным Степям.",["race:Orc"]="Полководец Лок носит прозвище «Губитель Орков» за свое мастерство и ненависть, с которыми он убивал орков-путников на этих землях.",["race:Tauren"]="Лагерь Таурахо стоит на южном коридоре, где агрессия Иглогривых особенно сильна, поэтому уничтожение этих полководцев критически важно для местной безопасности."},sec={{t="Обида в клетке",b="Изнывая в плену под солнцем Лагеря Таурахо, свинобраз Кривозуб больше не хранит верности своим сородичам Иглогривым. Брошенный после поражения и ожидая неминуемой казни, он стремится лишь отомстить вождям, бросившим его. Для этого он предлагает путникам Орды важные сведения о настоящих организаторах жестоких набегов на равнины."},{t="Полководцы Лабиринтов",b="Пока вожди Орды на Перекрестке, такие как Торк, пытаются обуздать постоянную агрессию свинобразов, Кривозуб раскрывает суть проблемы: три опытных командира из глубин Лабиринтов Иглошкурых. Их возглавляет грозный воин Лок Губитель Орков, с ним следопыт Каз и заклинатель Нак; эти трое направляют набеги Иглогривых из лагерей далеко на юге. Кривозуб требует их отсеченные черепа как доказательство того, что предатели пали до его собственного конца."}},faq={{q="Почему свинобраз помогает Орде?",a="Кривозубом движет только месть, а не дружба к Орде. Сородичи отвернулись от него и бросили умирать в клетке в Лагере Таурахо. Раз его собственная гибель неизбежна, он охотно помогает Орде лишь затем, чтобы предатели умерли первыми.",al={"why mangletooth helps","mangletooth motive","why quilboar betraying kin","почему кривозуб помогает","мотив кривозуба","почему свинобраз предает сородичей"}},{q="Кто такие Нак, Каз и Лок Губитель Орков?",a="Это трое видных вождей Иглогривых, вышедших из Лабиринтов Иглошкурых, чтобы организовывать набеги по всем Степям. Лок Губитель Орков — свирепый воин и предводитель, с ним мистик-заклинатель Нак и следопыт Каз.",al={"who are the targets","razormane leaders","lok orcbane lore","кто цели","вожди иглогривых","лок губитель орков предания"}},{q="Где найти этих троих?",a="Их лагеря находятся далеко на юге Степей, в укрепленных землях Иглогривых у границы южных зарослей.",al={"where is lok orcbane","where are nak and kuz","target locations","где лок губитель орков","где нак и каз","местонахождение целей"}},{q="Что Кривозуб имеет в виду, говоря, что Торк ошибается?",a="Торк, руководя обороной с Перекрестка, считает, что знает, кто направляет нападения свинобразов на линии снабжения Орды. Кривозуб утверждает, что Торк ошибается насчет истинных вдохновителей, и настаивает, что разрушительные нападения на самом деле организуют Лок Губитель Орков, Нак и Каз.",al={"thork mistake","what did thork get wrong","thork and mangletooth","ошибка торка","в чем ошибся торк","торк и кривозуб"}},{q="Принесет ли гибель этих вождей настоящий мир с Иглогривыми?",a="Кривозуб хвастает, что гибель этих троих избавит Перекресток и большую часть Степей от набегов Иглогривых. Хотя это разрушит их ближайшее южное руководство, глубокая враждебность свинобразов во всех Степях далеко не угаснет.",al={"will barrens have peace","end of razormane","razormane defeated","будет ли мир в степях","конец иглогривых","иглогривые разбиты"}},{q="Что станет с Кривозубом после этого?",a="Кривозуб понимает, что его смерть неизбежна, пока он заперт в лагере Орды. Он не ищет ни побега, ни пощады — лишь удовлетворения от расправы над предавшими его соплеменниками до собственного конца.",al={"does mangletooth go free","mangletooth fate","is mangletooth executed","освободят ли кривозуба","судьба кривозуба","казнят ли кривозуба"}}},fp="20,298,18.403.0,25.482.0,36.274.0,34.220.0,34.140.0,51.287.0,64.262.0,39.202.0"}
P.entries["quest:88"] = {n="Принцесса должна умереть!",s="«Принцесса должна умереть!» — местное поручение от Мамаши Стоунфилд с Фермы Стоунфилдов на юге Элвиннского леса. Она хочет покончить с Принцессой, огромной призовой свиньей с расположенного рядом Тыквенного поля Бреквеллов, которая постоянно разоряет ее драгоценные огороды. Устранение бесчинствующей свиньи позволит Стоунфилдам спокойно собрать урожай.",h="«Принцесса должна умереть!» — местное поручение от Мамаши Стоунфилд с Фермы Стоунфилдов на юге Элвиннского...",kw={"boar","brackwell pumpkin patch","brass collar","elwynn","ma stonefield","princess","sow","stonefield farm","вепрь","тыквенное поле бреквеллов","латунный ошейник","элвиннский лес","мамаша стоунфилд","принцесса","свинья","ферма стоунфилдов"},ang={["faction:Alliance"]="Помогая местным фермерам вроде Мамаши Стоунфилд справляться с одичавшими зверями, Альянс поддерживает работу южной житницы Штормграда, несмотря на отсутствие регулярной армии королевства.",["profession:Cooking"]="Расправа над огромной свиньей Принцессой — легендарная история среди местных поваров, ведь крупные вепри Элвиннского леса дают много сытного мяса для жарки на открытом огне."},sec={{t="Угроза урожаю",b="Ферма Стоунфилдов сильно зависит от своих посевов, но ненасытная угроза поставила урожай под удар. Принцесса, знаменитая призовая свинья Бреквеллов, выросла до чудовищных размеров, забредая на участки Стоунфилдов и пожирая их овощи. Мамаше Стоунфилд надоело, что наглая свинья лакомится плодами ее труда, и она хочет прикончить зверя, пока он не погубил весь урожай сезона."},{t="Свиная свита",b="Принцесса редко бродит без спутников. На Тыквенном поле Бреквеллов, к востоку за усадьбой Маклюров, ее окружает верная свита охранников-вепрей. Чтобы убить огромную свинью, нужно прорваться через стражу и снять с ее шеи приметный латунный ошейник в доказательство того, что обжора больше не потревожит поля Стоунфилдов."}},faq={{q="Кто такая Принцесса?",a="Принцесса — огромная призовая свинья семьи Бреквеллов. Она выросла до таких размеров главным образом потому, что тайком пробиралась на Ферму Стоунфилдов и объедалась драгоценными овощами Мамаши Стоунфилд.",al={"what is princess","princess elwynn","who is the pig princess","что такое принцесса","принцесса элвинн","кто свинья принцесса"}},{q="Почему Мамаша Стоунфилд хочет убить Принцессу?",a="Мамаше Стоунфилд надоело, что Принцесса забредает на ее поля и пожирает овощи. Опасаясь, что огромная свинья съест весь урожай семьи до сбора, она нанимает путников убить зверя и принести ее латунный ошейник в доказательство.",al={"why kill princess","ma stonefield pig quest","why does princess must die","зачем убивать принцессу","задание мамаши стоунфилд про свинью","почему принцесса должна умереть"}},{q="Где можно найти Принцессу?",a="Принцесса живет на Тыквенном поле Бреквеллов на юго-востоке Элвиннского леса, к востоку от Виноградников Маклура. Она бродит среди разоренных тыкв, которые охраняет свита кабанов.",al={"princess location","where is princess","princess spawn","где принцесса","местонахождение принцессы","появление принцессы"}},{q="Кому принадлежит Тыквенное поле Бреквеллов?",a="Поле принадлежит семье Бреквеллов, местных фермеров, чьи земли пришли в упадок из-за бандитов и нашествий диких зверей на юге Элвиннского леса. Хотя поле забросили, Принцесса осталась и доедала то, что уцелело.",al={"who are the brackwells","brackwell farm lore","brackwell owners","кто такие бреквеллы","ферма бреквеллов","владельцы бреквеллов"}},{q="Как доказать, что Принцесса мертва?",a="You must take the Brass Collar from around the sow's neck after defeating her and bring it back to Ma Stonefield at the Stonefield Farm.",al={"princess proof","what item for princess","brass collar","доказательство смерти принцессы","какой предмет нужен для принцессы","латунный ошейник"}},{q="Принцесса сражается в одиночку?",a="Нет, Принцессу сопровождает Свиная свита — защитные вепри, которые нападут на любого, кто попытается убить призовую свинью.",al={"princess adds","princess entourage","princess guards","свита принцессы","охрана принцессы","помощники принцессы"}}},fp="18,353,23.426.0,21.383.0,16.219.0,44.265.0,28.186.0,37.258.0,34.136.0,26.135.0"}
P.entries["quest:880"] = {n="Измененные существа",s="«Измененные существа» — задание Орды, которое выдает Тонга Рунический Тотем на Перекрестке в Степях. После обнаружения таинственных трещин, питающих местные источники воды, Тонга поручает искателям приключений собрать панцири измененных щелкунов, чтобы выяснить, как неестественные воды влияют на местных животных.",h="«Измененные существа» — задание Орды, которое выдает Тонга Рунический Тотем на Перекрестке в Степях.",kw={"altered beings","altered snapjaw shell","crossroads","lushwater oasis","snapjaws","stagnant oasis","the barrens","tonga runetotem","измененные существа","панцирь измененного щелкуна","перекресток","цветущий оазис","щелкуны","застывший оазис","степи","тонга рунический тотем"},ang={["class:Druid"]="Для друидов изучение щелкунов показывает хрупкую границу между природной жизненной силой и порченой мутацией и дает взгляд из первых рядов на возмущение, зреющее под Степями.",["faction:Horde"]="Безопасность и чистота источников воды вокруг Перекрестка крайне важны, чтобы защитить сердце земель Орды от неожиданных магических угроз.",["race:Tauren"]="Равновесие Матери-Земли в Степях заметно нарушено, поэтому усилия Тонги Рунического Тотема глубоко личные для таурен, ищущих гармонию на своих исконных землях."},sec={{t="Неестественные воды",b="Засушливые саванны Степей усеяны несколькими плодородными оазисами, однако их жизненная сила не вполне естественна. Исследование этих водоемов, проведенное друидом Тонгой Руническим Тотемом, выявило странные подземные трещины, излучающие необычную мощную энергию. Подозревая, что неизвестный источник силы — привнесенный извне или поднимающийся из глубин земли — изменяет экосистему, Тонга обращает внимание на существ, которые пьют из этих вод и обитают в них."},{t="Знаки на панцире",b="Чтобы оценить влияние трещин на природу, Тонга направляет охотников к Цветущему оазису и Застывшему оазису. Местные щелкуны, обитающие на мелководье, впитали таинственную сущность с пищей и водой, из-за чего их панцири заметно мутировали. Изучая эти измененные панцири, Тонга надеется определить, какое именно магическое или природное возмущение действует на земли, пока оно не распространилось дальше по Калимдору."}},faq={{q="Кто выдает задание «Измененные существа»?",a="Задание выдает Тонга Рунический Тотем, таурен-друид, которого можно найти на Перекрестке в центральных Степях.",al={"quest giver","where to get altered beings","who starts altered beings","персонаж, выдающий задание","где взять измененные существа","кто начинает измененные существа"}},{q="What creatures need to be hunted for this task?",a="Нужно охотиться на оазисных щелкунов, обитающих у вод Цветущего оазиса и Застывшего оазиса в Степях.",al={"which mobs drop shells","altered snapjaw targets","what to kill","каких существ убивать за панцири","цели измененные щелкуны","что убивать"}},{q="Почему щелкуны изменились?",a="Таинственные трещины под оазисами просачиваются странной энергией в воду. У животных, обитающих в водоемах или пьющих из них, появились мутации, из-за которых их панцири заметно изменились.",al={"why are snapjaws mutated","what altered the turtles","what is wrong with the oasis beasts","почему щелкуны мутировали","что изменило черепах","что не так с животными оазиса"}},{q="Где находятся Цветущий и Застывший оазисы?",a="Оба оазиса лежат к югу от Перекрестка в Степях. Застывший оазис находится на юго-востоке, ближе к границе Пылевых топей, а Цветущий оазис — на юго-западе, недалеко от входа в Пещеры Стенаний.",al={"oasis locations barrens","lushwater location","stagnant oasis location","оазисы в степях","где цветущий оазис","где застывший оазис"}},{q="Что происходит после выполнения задания «Измененные существа»?",a="Тонга Рунический Тотем понимает, что загадка глубже, чем просто дикие звери, и направляет искателей приключений сообщить о находках старшим друидам — к Хамуулу Руническому Тотему или Муре Руническому Тотему.",al={"next quest after altered beings","where does the chain go","altered beings follow up","следующее задание после измененных существ","куда ведет цепочка","продолжение измененных существ"}},{q="Почему Тонга Рунический Тотем изучает оазисы?",a="Как друид, Тонга стремится понять равновесие природы в Степях. Внезапный неестественный рост вокруг оазисов намекает на действие глубинных подземных сил, которые, как опасаются друиды, могут нарушить хрупкую экосистему саванны.",al={"tonga runetotem motive","why investigate the oasis","cenarion circle barrens","мотив тонги рунический тотем","зачем исследовать оазис","круг кенария степи"}}},fp="14,302,16.492.0,18.449.0,35.103.0,47.131.0,29.204.0,43.217.0,45.211.1,42.227.0"}
P.entries["quest:882"] = {n="Ишамухал",s="«Ишамухал» — обряд охоты, который назначает Джорн Заклинатель Небес в Лагере Таурахо. Чтобы испытать ваше мастерство и уважение к самым опасным хищникам природы, вам предстоит приманить и убить свирепейшего солнечного ящера в Степях.",h="«Ишамухал» — обряд охоты, который назначает Джорн Заклинатель Небес в Лагере Таурахо.",kw={"camp taurajo","ishamuhale","jorn skyseer","ratchet","speartooth","sunscale raptor","the barrens","zhevra carcass","лагерь таурахо","ишамухал","джорн заклинатель небес","кабестан","копьезуб","солнечный ящер","степи","туша жевры"},ang={["class:Hunter"]="Приманивание неуловимого верховного хищника свежей наживкой и местностью — традиционное искусство выслеживания, чтящее терпение и хитрость мастеров-следопытов.",["faction:Horde"]="Уничтожение легендарных угроз вроде Ишамухала доказывает ценность новичка и делает дороги между Кабестаном и Таурахо немного безопаснее для путников Орды.",["race:Tauren"]="Для охотников-таурен встреча с Ишамухалом — важный урок равновесия: он показывает, что отнять жизнь могучего хищника можно, лишь обладая дисциплиной, чтобы обуздать унаследованный свирепый дух."},sec={{t="Природа Копьезуба",b="Среди хищников Степей солнечных ящеров боятся за хитрость и жестокую стайную тактику, но никто не внушает такого ужаса, как Ишамухал. Известный как Копьезуб, он бродит по саванне не просто ради пищи или территории. Как объясняет Джорн Заклинатель Небес, Ишамухал охотится из чистого инстинкта и страсти — он убивает просто потому, что такова его природа. Встреча с таким существом проверяет, способен ли охотник выдержать чистую, необузданную звериную злобу."},{t="Приманка для зверя",b="Ишамухала нельзя просто застать спящим в гнезде. Чтобы выманить огромного ящера, охотник должен подражать естественному ритму равнин. Джорн велит испытуемому убить свежую жевру — любимую добычу ящера — и притащить тушу к одинокому засохшему дереву к северо-западу от Кабестана. Привлеченный запахом свежей крови в сухом ветре, Ишамухал быстро появляется, чтобы забрать добычу."},{t="Бремя силы",b="Возвращение клыка Ишамухала в Лагерь Таурахо — больше чем демонстрация боевой победы. Джорн Заклинатель Небес видит в трофее важную духовную веху. По верованиям таурен, одолев такого свирепого верховного хищника, получаешь долю его первозданной силы. Настоящее испытание после этого происходит внутри: нести эту хищную мощь с умеренностью, честью и сдержанностью, не поддаваясь слепой жажде крови."}},faq={{q="Кто такой Ишамухал?",a="Ишамухал, носящий титул Копьезуб, — исключительно свирепый солнечный ящер, бродящий по Степям. В отличие от обычных зверей, движимых лишь голодом, он неутомимо охотится из чистой хищной природы и страсти.",al={"what is ishamuhale","who is speartooth","ishamuhale raptor lore","кто такой ишамухал","что такое ишамухал","кто такой копьезуб","ишамухал ящеры предания"}},{q="Как призвать Ишамухала?",a="Ишамухала нужно выманить свежеубитой добычей. Нужно добыть свежую тушу жевры и повесить ее на указанное засохшее дерево к северо-западу от гоблинского порта Кабестан. Запах быстро выманивает его из укрытия.",al={"how to spawn ishamuhale","where is ishamuhale","bait ishamuhale","как призвать ишамухала","где ишамухал","приманка для ишамухала"}},{q="Где это задание начинается и заканчивается?",a="Задание выдает Джорн Заклинатель Небес, таурен-охотник из Лагеря Таурахо в южных Степях. Когда Ишамухал убит, вы возвращаете его клык Джорну в лагере.",al={"ishamuhale quest giver","who gives ishamuhale","where to turn in ishamuhale","кто выдает задание ишамухал","кто дает ишамухала","где сдать ишамухала"}},{q="Почему Джорн Заклинатель Небес хочет смерти Ишамухала?",a="Джорн стремится не к истреблению из злобы. Выслеживание и победа над Ишамухалом — духовное испытание, проверяющее охотника против самой необузданной агрессии природы и учащее умеренности при принятии такой свирепости.",al={"why kill ishamuhale","jorn skyseer motivation","зачем убивать ишамухала","мотив джорна заклинателя небес"}},{q="Что происходит после выполнения задания «Ишамухал»?",a="Доказав себя в схватке с Ишамухалом, вы получаете от Джорна Заклинателя Небес направление к более крупным угрозам равновесию Степей: далее следуют задания о Разъяренных рокочущих ящерицах на юге.",al={"quest after ishamuhale","next quest after raptor","задание после ишамухала","следующее задание после ящера"}},{q="Как это задание вписывается в цепочку Сергры Черный Шип?",a="Оно продолжает великие охотничьи испытания, начатые Сергрой Черный Шип на Перекрестке. После того как вы проявили мастерство на северных равнинах, Сергра отправляет вас на юг к Джорну Заклинателю Небес в Лагерь Таурахо, чтобы сразиться с верховными хищниками.",al={"sergra darkthorn connection","crossroads hunting chain","связь с сергрой черный шип","охотничья цепочка перекрестка"}}},fp="10,220,24.454.0,17.423.0,22.421.0,18.207.0,29.222.0,36.169.0,43.219.0,41.204.0,54.227.0"}
P.entries["quest:8827"] = {n="Подарки Дедушки Зимы",s="«Подарки Дедушки Зимы» — праздничное вводное задание Альянса, посвященное Зимнему Покрову в Стальгорне. Веселые гуляки и операторы «Чудо-формы PX-238» призывают путников посетить Дедушку Зиму у прилавков Пастбищ Дымного Леса. Там, под большой праздничной елью, выносливых искателей приключений ждут подарки.",h="«Подарки Дедушки Зимы» — праздничное вводное задание Альянса, посвященное Зимнему Покрову в Стальгорне.",kw={"feast of winter veil","greatfather winter","holiday enthusiast","ironforge","smokywood pastures","winter veil","winter's presents","wonderform operator","зимний покров","праздник зимнего покрова","дедушка зима","любитель праздника","стальгорн","пастбища дымного леса","подарки дедушки зимы","оператор чудо-формы"},ang={["faction:Alliance"]="Зимой Стальгорн служит главным местом сбора всех рас Альянса: эльфов, людей и гномов привлекают теплые подземные залы дворфов, где можно разделить праздничную радость.",["race:Dwarf"]="Для дворфов встретить путников на празднике Зимнего Покрова в Великой кузне означает оживить родной горный дом песнями, теплым огнем очагов и холодным элем.",["race:Gnome"]="Гномы-механики восхищаются изобретательными праздничными устройствами, привезенными на это время года, например «Зимними вольтоматами PX-238», работающими по всему городу."},sec={{t="Время радости",b="Когда зимняя стужа охватывает вершины Каз Модана, Стальгорн становится центром праздничных торжеств Альянса в честь Зимнего Покрова. Гуляки и любители праздника по всему городу разносят весть о радости и с воодушевлением направляют прохожих к большой наряженной ели возле торговцев Пастбищ Дымного Леса."},{t="Пастбища Дымного Леса и Дедушка Зима",b="За щедрой раздачей упакованных свертков стоит гоблинское предприятие «Пастбища Дымного Леса», сотрудничающее с самим Дедушкой Зимой. Пока добродушный старец тепло приветствует гостей, гоблины-торговцы не упускают случая напомнить счастливым получателям подарков, что их праздничные лакомства и сезонные товары — прекрасные подарки для друзей и родных."}},faq={{q="Кто посылает меня поговорить с Дедушкой Зимой?",a="Либо любитель праздника, либо оператор «Чудо-формы», обслуживающий машины «Зимний вольтомат PX-238» в Стальгорне, пригласит вас посетить Дедушку Зиму у наряженной ели.",al={"quest giver","who starts winter's presents","who gives the quest","персонаж, выдающий задания","кто начинает подарки дедушки зимы","кто дает задание"}},{q="Где найти Дедушку Зиму в Стальгорне?",a="Он сидит рядом с праздничной елью и прилавками Пастбищ Дымного Леса в Стальгорне и приветствует гостей праздника из всех рас Альянса.",al={"where is greatfather winter","greatfather winter location ironforge","find greatfather winter","где дедушка зима","дедушка зима стальгорн","найти дедушку зиму"}},{q="Что такое «Зимний вольтомат PX-238», о котором говорит оператор?",a="«Зимний вольтомат PX-238» — причудливое праздничное изобретение, которым управляют гоблины-операторы. Оно на время превращает искателей приключений на празднике в веселых маленьких помощников.",al={"px-238","winter wondervolt","wondervolt machine","зимний вольтомат","вольтомат"}},{q="Почему Пастбища Дымного Леса участвуют в Зимнем Покрове?",a="«Пастбища Дымного Леса» — предприимчивая гоблинская торговая организация, которая спонсирует сезонные лакомства, праздничные безделушки и пиршества по всему Азероту, сочетая искренний праздничный дух с выгодной сезонной торговлей.",al={"smokywood pastures role","why goblins winter veil","goblin holiday","роль пастбищ дымного леса","почему гоблины зимний покров","гоблины праздник"}},{q="Могут ли игроки Орды выполнить это задание?",a="Нет, это приглашение предназначено только для Альянса в Стальгорне. Орда отмечает свои обычаи Зимнего Покрова под руководством Дедушки Зимы в Оргриммаре.",al={"is this alliance only","horde winter presents","can horde turn this in","только ли для альянса","подарки дедушки зимы орда","может ли орда сдать задание"}},{q="Что происходит после разговора с Дедушкой Зимой?",a="Дедушка Зима приветствует вас, подтверждает, что не забыл о вас, и советует осмотреть яркие свертки под окружающей праздничной елью.",al={"what comes next","opening presents","after quest turn in","что дальше","открыть подарки","после сдачи задания"}}},fp="17,323,17.339.0,41.382.0,46.178.0,49.150.0,63.172.0,50.211.0,32.172.0,50.164.0"}
P.entries["quest:8828"] = {n="Подарки Дедушки Зимы",s="«Подарки Дедушки Зимы» — приглашение, адресованное искателям приключений в Оргриммаре во время Зимнего Покрова. По указанию праздничных организаторов и гоблинов-механиков герои Орды идут к Дедушке Зиме под наряженной елью, чтобы забрать приготовленные для них подарки.",h="«Подарки Дедушки Зимы» — приглашение, адресованное искателям приключений в Оргриммаре во время Зимнего...",kw={"great-father winter","holiday enthusiast","orgrimmar","presents","smokywood pastures","winter veil","winter's presents","wonderform operator","дедушка зима","любитель праздника","оргриммар","подарки","пастбища дымного леса","зимний покров","подарки дедушки зимы","оператор чудо-формы"},ang={["faction:Horde"]="Для Орды шумный праздничный лагерь в Оргриммаре — радостное, теплое место для встреч вдали от непрекращающихся приграничных конфликтов в Калимдоре.",["race:Orc"]="Даже в суровой обители Вождя орки прерывают дела, чтобы разделить зимние пиры и принять гостеприимство под ветвями ели Зимнего Покрова."},sec={{t="Время щедрости",b="Когда холодные ветры конца года проносятся над Дуротаром, Зимний Покров приносит суровым красным камням Оргриммара редкие мгновения мира и праздника. Агенты Пастбищ Дымного Леса вместе с любителями праздника следят, чтобы каждый воин, охотник и странник в столице знал: под наряженной елью его ждут подарки."},{t="Покровитель и торговцы",b="Среди праздничных лент и упакованных коробок у прилавков Пастбищ Дымного Леса сидит сам Дедушка Зима. Пока древний старец воплощает обновление природы, ушлые гоблины-торговцы не упускают случая напомнить гостям, что праздничный дух прекрасно сочетается с их сезонными товарами и лакомствами."}},faq={{q="Кому сдать «Подарки Дедушки Зимы»?",a="Это задание сдается Дедушке Зиме, который сидит у праздничной зоны Пастбищ Дымного Леса и наряженной ели в Аллее Силы в Оргриммаре.",al={"where is great father winter","turn in location","presents hand in","где дедушка зима","где сдать задание","сдать подарки"}},{q="Кто посылает вас к Дедушке Зиме?",a="Либо любитель праздника, либо гоблин, оператор «Чудо-формы», обслуживающий машины «Зимний вольтомат PX-238» у праздничных построек, направит вас к ели.",al={"who gives quest","quest starter","holiday enthusiast","кто дает задание","кто начинает задание","любитель праздника"}},{q="Что такое Пастбища Дымного Леса?",a="«Пастбища Дымного Леса» — предприимчивая гоблинская торговая организация, которая спонсирует и снабжает празднества, еду, лакомства и подарки в главных столицах во время Зимнего Покрова.",al={"smokywood pastures lore","who are smokywood pastures","пастбища дымного леса предания","кто такие пастбища дымного леса"}},{q="Что делает Дедушка Зима, когда вы с ним заговорите?",a="Дедушка Зима лично приветствует вас на Зимнем Покрове, указывает на упакованные свертки под елью и тепло советует заглянуть к товарам Пастбищ Дымного Леса для ваших спутников.",al={"great-father winter greeting","quest completion dialogue","приветствие дедушки зимы","диалог при завершении задания"}},{q="Почему Орда отмечает Зимний Покров в Оргриммаре?",a="Хотя праздник уходит корнями в древние легенды об обновлении зимой, нынешний праздник принят Ордой как время отдыха, пиршеств и единения среди борьбы за новый дом в Калимдоре.",al={"horde winter veil lore","why orcs celebrate winter veil","зимний покров орда предания","почему орки отмечают зимний покров"}},{q="Что такое «Зимний вольтомат PX-238», о котором говорит оператор?",a="Это причудливое гоблинское устройство возле места празднования, которое на время превращает добровольцев в празднично одетых маленьких помощников.",al={"winter wondervolt","px 238 wondervolt","зимний вольтомат","вольтомат px 238"}}},fp="17,287,20.355.0,27.358.0,37.155.0,41.163.0,27.184.0,57.216.0,54.200.0,63.147.0"}
P.entries["quest:883"] = {n="Лакота'мани",s="«Лакота'мани» — обряд охоты, начинающийся с добычи копыта Лакота'мани, огромного кодо, бродящего по Степям. Принеся этот трофей Джорну Заклинателю Небес в Лагерь Таурахо, охотник чтит дух могучего зверя и становится равным его громовой силе.",h="«Лакота'мани» — обряд охоты, начинающийся с добычи копыта Лакота'мани, огромного кодо, бродящего по Степям.",kw={"camp taurajo","earthshaker","hoof of lakota'mani","jorn skyseer","kodo","lakota'mani","the barrens","лагерь таурахо","землетрясущий","копыто лакота'мани","джорн заклинатель небес","кодо","лакота'мани","степи"},ang={["class:Hunter"]="Выследить легендарного одинокого кодо в бескрайней саванне — высшее испытание мастерства следопыта, выносливости и полевого боя в сердце Калимдора.",["faction:Horde"]="Лагерь Таурахо — важный охотничий центр Орды, и добыча с равнин помогает вам заслужить репутацию среди племен.",["race:Tauren"]="Для тауренов-охотников победа над Лакота'мани исполняет древние охотничьи традиции и приносит духовное почтение и гордое звание Землетрясущего от ваших старейшин."},sec={{t="Землетрясущий",b="На языке тауренов Лакота'мани означает «Землетрясущий». Среди стад, бродящих по выжженным солнцем равнинам Степей, он стоит особняком — кодо огромного размера и выносливости, чьи шаги гремят, как собранный воедино гром. Для тауренов-охотников выследить и победить такого зверя — не бессмысленное убийство, а священное единение с первозданной мощью дикой природы Калимдора."},{t="Почтенная охота в Лагере Таурахо",b="Принеся копыто павшего зверя Джорну Заклинателю Небес в Лагерь Таурахо, охотник духовно завершает охоту. Джорн сразу замечает перемену: в каждом вернувшемся с этой схватки охотнике чувствуются новая сила и поступь. Получив трофей, охотник принимает благословение Джорна, признающего, что стойкая отвага и первобытный дух Лакота'мани теперь идут рядом с ним."}},faq={{q="Что означает имя Лакота'мани?",a="По словам Джорна Заклинателя Небес, на языке тауренов Лакота'мани означает «Землетрясущий». Имя отражает огромный размер зверя и его шаги, грохочущие по равнинам, как собранный воедино гром.",al={"meaning of lakotamani","lakota'mani translation","what does lakotamani mean in taurahe","значение лакота'мани","перевод лакота'мани","что значит лакота'мани на языке тауренов"}},{q="Кто такой Джорн Заклинатель Небес?",a="Джорн Заклинатель Небес — таурен, духовный наставник и старейшина, живущий в Лагере Таурахо на юге Степей. Он толкует знамения, наставляет молодых охотников и чтит великих зверей, убитых на равнинах.",al={"who is jorn","jorn skyseer role","where is jorn skyseer","кто такой джорн","джорн заклинатель небес","где джорн заклинатель небес"}},{q="Почему тауренам нужны копыта великих зверей?",a="Для тауренов копыто зверя вроде Лакота'мани — вещественный знак его огромной силы. Когда охотник приносит его старейшине, дух и стойкость павшего зверя получают признание и соединяются с духом самого охотника.",al={"why take the hoof","hoof of lakota'mani meaning","kodo hoof trophy","зачем брать копыто","значение копыта лакота'мани","трофей копыто кодо"}},{q="Где бродит зверь Лакота'мани?",a="Лакота'мани бродит по открытой саванне в центре и на юге Степей среди стад обычных кодо, пока его не выследит внимательный охотник.",al={"where is lakotamani","lakota'mani location","how to find lakotamani","где лакота'мани","местонахождение лакота'мани","как найти лакота'мани"}},{q="Почему Джорн называет охотника Землетрясущим?",a="Джорн Заклинатель Небес верит, что победа над Лакота'мани навсегда соединяет дух и отвагу зверя с духом охотника. Одолев Землетрясущего, охотник наследует его имя и идет вперед с такой же громовой решимостью.",al={"why am i called earthshaker","earthshaker title lore","почему меня зовут землетрясущий","титул землетрясущий предания"}},{q="Имеет ли эта охота духовное значение за пределами Лагеря Таурахо?",a="Да. Она отражает основополагающую веру тауренов в Мать-Землю и природное равновесие. Охотник доказывает свою силу не покорением природы, а испытанием себя против ее величайших воплощений и принимает их духовную силу в будущие сражения.",al={"lakotamani spiritual meaning","is this a tauren rite","духовное значение лакота'мани","это обряд тауренов"}}},fp="11,271,15.390.0,30.384.0,36.200.0,20.196.0,49.259.0,38.152.0,44.223.0,63.261.0"}
P.entries["quest:884"] = {n="Оватанка",s="Оватанка — легендарный громовой ящер, известный тауренам как Синяя Молния, бродящий по южным равнинам Степей. Убийство этого быстрого, заряженного электричеством зверя дает потрескивающий хвостовой зубец, несущий заключенную в нем молнию старейшинам лагеря. Доставка этого трофея Джорну Заклинателю Небес в Лагерь Таурахо чтит традицию учиться у первозданных зверей Калимдора.",h="Оватанка — легендарный громовой ящер, известный тауренам как Синяя Молния, бродящий по южным равнинам Степей.",kw={"barrens","bluebolt","camp taurajo","jorn skyseer","owatanka","tailspike","thunder lizard","степи","синяя молния","лагерь таурахо","джорн заклинатель небес","оватанка","хвостовой зубец","громовой ящер"},ang={["class:Hunter"]="Победа над Оватанкой — главное испытание выслеживания и скорости, доказывающее, что охотник способен обогнать и победить быстрейших великанов природы.",["class:Shaman"]="Остаточная молния в хвостовом зубце оватанки показывает, как стихийные силы неба могут навсегда изменить живых существ Калимдора.",["faction:Horde"]="Истребление столь непредсказуемого хищника, заряженного молниями, защищает уязвимые торговые тропы близ Лагеря Таурахо.",["race:Tauren"]="Охота на Синюю Молнию чтит древние традиции тауренов — уважение к диким духам и обретение жизненной силы самых стойких зверей Степей."},sec={{t="Зверь по имени Синяя Молния",b="По засушливым просторам юга Степей бродит Оватанка, редкий громовой ящер, о котором тауренские охотники говорят с почтением. Хотя большинство его сородичей огромны и неповоротливы, Оватанка обладает внезапной, ослепляющей быстротой. Тауренам он известен как Синяя Молния — существо, коренным образом изменившееся от бури."},{t="Питаемый яростью небес",b="По преданиям, хранимым Джорном Заклинателем Небес, давным-давно в Оватанку прямо ударила молния. Громовой ящер не погиб, а поглотил небесный удар, обретя бесконечный источник яростной энергии. Даже после смерти хвостовой зубец зверя при прикосновении яростно потрескивает искрами — осязаемый след мощи бури."},{t="Трофей Таурахо",b="Принести Хвостовой зубец оватанки в Лагерь Таурахо — обряд доблести и духа. Джорн Заклинатель Небес сразу узнает след схватки во взгляде любого охотника, сумевшего превзойти зверя в скорости. Вручая трофей, охотник символически обретает неутомимую быстроту Синей Молнии."}},faq={{q="Кто такой Оватанка?",a="Оватанка — легендарный громовой ящер, обитающий в Степях. Местным тауренам он известен как Синяя Молния и славится необычайной быстротой и потрескивающей энергией молний.",al={"who is owatanka","what kind of beast is owatanka","owatanka lore","кто такой оватанка","что за зверь оватанка","оватанка предания"}},{q="Почему Оватанка искрит молниями?",a="Легенда тауренов гласит, что в давнем прошлом в Оватанку ударила молния. Вместо смерти удар наполнил зверя бесконечной энергией и яростью, питаемой прямо с небес.",al={"why is owatanka electric","bluebolt lore","why sparks fly","почему оватанка электрический","предания о синей молнии","почему летят искры"}},{q="Кто такой Джорн Заклинатель Небес?",a="Джорн Заклинатель Небес — старейшина тауренов и духовный наставник, живущий в Лагере Таурахо на юге Степей. Он чувствует скрытую силу великих зверей края и принимает трофеи, такие как хвостовой зубец оватанки.",al={"where do i turn in owatanka","who is jorn","camp taurajo questgiver","где сдать оватанку","кто такой джорн","лагерь таурахо персонаж, выдающий задания"}},{q="Где бродит Оватанка?",a="Оватанка бродит по засушливым равнинам юга Степей, обычно среди кустарника и пыльных троп к югу от Лагеря Таурахо.",al={"owatanka location","where is owatanka","where to find bluebolt","где оватанка","местонахождение оватанки","где найти синюю молнию"}},{q="Что происходит, когда вы приносите Хвостовой зубец оватанки?",a="Джорн Заклинатель Небес хвалит вас за победу над быстрым громовым ящером и отмечает, что бег наравне с таким существом оставляет в охотнике надолго искру энергии и силы.",al={"owatanka turn in","what does jorn say","owatanka reward lore","сдать оватанку","что говорит джорн","награда оватанки предания"}},{q="Опасен ли Оватанка по сравнению с обычными громовыми ящерами?",a="Да. Помимо обычной выносливости громовых ящеров, Оватанка обладает обманчивой быстротой и врожденной электрической силой, порожденной легендарным ударом молнии.",al={"is owatanka hard","bluebolt danger","owatanka fight","сложен ли оватанка","опасность синей молнии","бой с оватанкой"}}},fp="8,366,25.320.0,21.344.0,17.316.0,17.177.0,39.189.0,20.208.0,27.137.0,51.171.0,57.167.0"}
P.entries["quest:8846"] = {n="Пять жетонов в обмен на припасы",s="Фельдмаршал Снегопад в Стальгорне руководит сбором провизии и снаряжения для военных усилий Великого Альянса. Герои, пополняющие запасы, могут обменять свои жетоны за заслуги прямо на полевые пайки, бинты и важнейшие боевые припасы. Так те, кто неутомимо трудится в тылу, остаются обеспеченными всем необходимым для грядущих сражений.",h="Фельдмаршал Снегопад в Стальгорне руководит сбором провизии и снаряжения для военных усилий Великого Альянса.",kw={"commendation","ironforge","materiel","rations","signets","snowfall","war supplies","заслуги","стальгорн","снаряжение","пайки","жетоны","снегопад","военные припасы"},ang={["faction:Alliance"]="Это снабженческое требование — прямая опора для героев Альянса, готовящихся к крупным кампаниям по всему Азероту: оно обеспечивает войска бинтами и пайками.",["race:Dwarf"]="Поскольку шумный город кузниц служит распределительным центром Альянса, дворфы-защитники гордятся тем, что их залы вооружают все союзные расы."},sec={{t="Помощь фронту",b="Развертывание огромных армий требует не только отваги, но и бесперебойного снабжения. Фельдмаршал Снегопад — один из главных интендантов Альянса в Стальгорне и организует поток материалов, предназначенных для действующих фронтов. Когда курьеры и герои приносят жетоны за заслуги, полученные за службу обществу, Снегопад выдает взамен пайки и боевое снаряжение."},{t="Практичный обмен",b="Хотя похвальные жетоны часто сдают королевским глашатаям ради публичной чести и гражданского положения, Снегопад предлагает им будничную альтернативу. Обмен пяти жетонов на комплект полевого снаряжения не приносит ни пышности, ни славы, ни официального признания. Зато он дает ощутимые, спасающие жизнь припасы, чтобы солдаты и добровольцы оставались живы, отправляясь в походы по вражеским землям."}},faq={{q="Кто такой фельдмаршал Снегопад?",a="Фельдмаршал Снегопад — старший военный офицер Альянса, расквартированный в столице дворфов Стальгорне. Он занимается сбором сырья и раздачей припасов солдатам и искателям приключений, помогающим военным усилиям.",al={"snowfall ironforge","field marshal snowfall","who is snowfall","снегопад стальгорн","фельдмаршал снегопад","кто такой снегопад"}},{q="Что такое жетоны за заслуги Альянса?",a="Жетоны за заслуги Альянса — официальные знаки, которые выдают гражданам и искателям приключений, передающим важные товары, бинты, травы и руду для поддержки широкой мобилизации Альянса.",al={"commendation signets","alliance signets","what are signets","жетоны за заслуги","жетоны альянса","что такое жетоны"}},{q="Почему менять жетоны на припасы, а не на престиж?",a="Обмен жетонов на ящики с припасами обходит гражданскую репутацию ради немедленных практических ресурсов. Бойцам на передовой, которым сразу нужны расходуемые предметы, пайки и бинты, практичное снаряжение часто важнее церемониального положения.",al={"why do this quest","signets for supplies worth it","snowfall supplies trade","зачем это задание","жетоны на припасы стоит ли","обмен припасов снегопад"}},{q="Где проходит этот обмен?",a="Обмен проходит в Стальгорне, где фельдмаршал Снегопад стоит у военных сборных пунктов и складов снабжения и координирует поставки по всему Каз Модану и за его пределы.",al={"where is snowfall","quest location","snowfall ironforge location","где снегопад","место задания","снегопад стальгорн где найти"}},{q="Можно ли повторить этот обмен?",a="Да. Фельдмаршал Снегопад готов постоянно выдавать новые наборы припасов, пока вы каждый раз приносите необходимые пять жетонов за заслуги.",al={"is this repeatable","can i do this again","turn in more signets","можно ли повторять","можно ли сделать снова","сдать еще жетоны"}},{q="Дает ли эта сдача репутацию?",a="Нет. Фельдмаршал Снегопад прямо предупреждает, что обмен жетонов на личные припасы не приносит ни гражданского признания, ни престижа у фракций Альянса, так как ценность возвращается материальными товарами.",al={"does this give rep","ironforge rep signets","recognition for signets","дает ли репутацию","репутация стальгорна жетоны","признание за жетоны"}}},fp="29,372,19.422.0,17.374.0,30.225.0,39.195.0,52.243.0,36.175.0,27.165.0,35.207.0"}
P.entries["quest:885"] = {n="Ваште Пауни",s="Это задание начинается после получения пера Ваште Пауни — редкого и почитаемого громового ястреба, парящего в небе над югом Степей. Его оперение излучает неестественное жжение и побуждает охотников принести реликвию Джорну Заклинателю Небес в Лагерь Таурахо. Для тауренов убийство этой легендарной птицы — не простая охота за трофеем, а глубокое духовное испытание болью и сожалением.",h="Это задание начинается после получения пера Ваште Пауни — редкого и почитаемого громового ястреба, парящего в...",kw={"barrens","camp taurajo","feather","jorn skyseer","spirit biter","taurahe","thunderhawk","washte pawne","степи","лагерь таурахо","перо","джорн заклинатель небес","кусающий дух","таурахе","громовой ястреб","ваште пауни"},ang={["class:Hunter"]="Встреча с Ваште Пауни проверяет мотивы охотника и показывает, что лишение зверя жизни значит гораздо больше, чем простой трофей.",["class:Shaman"]="Неземное жжение на пере громового ястреба показывает необузданный духовный отклик дикой природы — резонанс, понятный каждому, кто изучает гармонию стихий.",["faction:Horde"]="Лагерь Таурахо — важный духовный и охотничий перекресток для Орды, где молодых воинов проверяют не только в воинском мастерстве, но и в совести.",["race:Tauren"]="Для Шу'хало убийство Кусающего Дух — священный урок уважения к равновесию природы: он учит охотников, что сожаление можно выковать во внутреннюю мудрость."},sec={{t="Кусающий Дух",b="Громовые ястребы — неуловимые создания Степей, к которым кочевые племена относятся с суеверным почтением. Среди них особое и роковое место занимает Ваште Пауни, что на языке тауренов означает «Кусающий Дух». В отличие от обычной добычи, его гибель не воспринимается легко: шаманы шепчут, что убийство такого создания несет знамения, опасно колеблющиеся между триумфом и бедой."},{t="Урок сожаления",b="Те, кто убивает Ваште Пауни, быстро обнаруживают, что выпавшее перо при касании жжет пронзительной, не проходящей болью. Когда его приносят Джорну Заклинателю Небес в Лагерь Таурахо, провидец объясняет, что эта боль — не физический яд, а духовное жало сожаления. Лишить жизни великолепное существо — тяжкое бремя, и испытание спрашивает, поддастся ли охотник угрызениям совести или обратит скорбь в непреходящую мудрость."}},faq={{q="Что означает имя Ваште Пауни?",a="На языке тауренов Ваште Пауни означает «Кусающий Дух». Так называют величественного редкого громового ястреба, парящего над южными равнинами Степей.",al={"washte pawne meaning","what is washte pawne","taurahe meaning spirit biter","значение ваште пауни","что такое ваште пауни","кусающий дух значение"}},{q="Почему перо Ваште Пауни причиняет боль?",a="По словам Джорна Заклинателя Небес, жгучая боль при прикосновении к перу — это острая боль сожаления. Она воплощает душевную и духовную цену убийства великолепного существа.",al={"why does feather hurt","washte pawne feather sting","почему перо болит","перо ваште пауни жжет"}},{q="Кому нужно принести Перо Ваште Пауни?",a="Перо приносят Джорну Заклинателю Небес, старейшине тауренов, живущему в Лагере Таурахо на юге Степей.",al={"who takes washte pawne feather","feather turn in","кто принимает перо ваште пауни","сдать перо"}},{q="Какое знамение несет убийство громового ястреба?",a="По традиции тауренов, смерть громового ястреба может предвещать как великую удачу, так и огромную беду. Однако Джорн объясняет, что Ваште Пауни уникален: его убийство не влечет автоматически ни одной из судеб, и охотнику предстоит самому выковать мудрость из собственного раскаяния.",al={"thunderhawk omen","is killing thunderhawks bad","знамение громового ястреба","плохо ли убивать громовых ястребов"}},{q="Где найти Ваште Пауни?",a="Ваште Пауни парит в небе над югом Степей, и его часто видят кружащим над саванной близ Лагеря Таурахо.",al={"washte pawne location","where does spirit biter spawn","где ваште пауни","где появляется кусающий дух"}},{q="Что думает о вас Джорн Заклинатель Небес после убийства ястреба?",a="Джорн вас не осуждает. Он замечает, что вынесенная вами боль от пера доказывает, что вы совладали с сожалением и превратили духовную скорбь в силу и глубокое понимание.",al={"jorn skyseer reaction","does jorn get mad","реакция джорна заклинателя небес","злится ли джорн"}}},fp="12,378,16.412.0,18.429.0,28.193.0,43.203.0,41.118.0,43.260.0,28.119.0,53.183.0"}
P.entries["quest:8851"] = {n="Пять жетонов в обмен на припасы",s="Пять жетонов в обмен на припасы — снабженческий обмен, который организует полководец Горчук в Оргриммаре. Сдавая жетоны за заслуги, полученные во время массовой мобилизации Орды, герои получают личные припасы, чтобы быть готовыми к грядущему конфликту.",h="Пять жетонов в обмен на припасы — снабженческий обмен, который организует полководец Горчук в Оргриммаре.",kw={"commendation","gorchuk","materiel","orgrimmar","requisition","signets","supplies","war effort","заслуги","горчук","снаряжение","оргриммар","требование","жетоны","припасы","военные усилия"},ang={["class:Warrior"]="Бойцы передовой, ценящие практичное выживание выше церемониального признания, найдут, что ящики с припасами Горчука стоят накопленных жетонов.",["faction:Horde"]="Каждый ящик и тюк, собранный в Оргриммаре, обеспечивает Орду всем необходимым против катастрофических угроз, таящихся на горизонте."},sec={{t="Усилия всего континента",b="По всему Калимдору Орда собирает огромные запасы сырья, боеприпасов и провизии для крупной кампании. Пока простые сборщики и торговцы свозят в города ящики с бинтами, металлами и травами, военные надзиратели выдают жетоны за заслуги в знак признания их службы. Эти жетоны означают прямой вклад в общий запас, копящийся на центральных улицах Оргриммара."},{t="Снаряжение для передовой",b="Полководец Горчук понимает, что сбор припасов для общих военных усилий важен, но отдельным воинам тоже нужны снаряжение и провизия, чтобы выжить в походе на битву. Благодаря этому требованию бойцы могут отказаться от личного признания и обменять жетоны за заслуги обратно военной машине на готовые к бою припасы и излишки снаряжения."}},faq={{q="Зачем сдавать пять жетонов?",a="Это позволяет солдатам, помогающим мобилизации Орды, обменять заслуженные жетоны прямо на личное снаряжение для выживания и полевые припасы, а не копить их ради политического признания.",al={"why turn in 5 signets","signet turn in purpose","what do i get for 5 signets","зачем сдавать 5 жетонов","цель сдачи жетонов","что я получу за 5 жетонов"}},{q="Кто такой полководец Горчук?",a="Полководец Горчук — военный координатор Орды, расквартированный в Оргриммаре. Он отвечает за управление припасами и одобрение требований воинов, готовящихся к надвигающемуся конфликту.",al={"gorchuk identity","who is gorchuk","кто такой горчук","личность горчука"}},{q="Как получить жетоны за заслуги Орды?",a="Жетоны выдают интенданты и офицеры снабжения Орды, когда искатели приключений передают сырье, еду, бинты и ремесленные материалы для военных усилий фракции.",al={"get signets","where do signets come from","commendation signet source","получить жетоны","откуда жетоны","источник жетонов за заслуги"}},{q="Можно ли повторить это требование?",a="Да. Полководец Горчук готов одобрять повторные обмены, пока вы продолжаете приносить нужные партии жетонов для поддержки войск.",al={"is this repeatable","can i do this again","можно ли повторять","можно ли сделать снова"}},{q="Почему Горчук говорит, что я не получу признания за этот обмен?",a="Траты жетонов за заслуги прямо на личные припасы берут из запасов интенданта, а не вносят ваши деяния в летопись. То есть вы отказываетесь от официальных почестей ради немедленного практического полевого снаряжения.",al={"no recognition meaning","why no rep","что значит нет признания","почему нет репутации"}},{q="Где проходит этот обмен?",a="Требование выполняется прямо в Оргриммаре, где собираются запасы и координаторы снабжения, готовящие Орду к военным усилиям.",al={"where is this quest","turn in location","где это задание","где сдавать"}}},fp="29,274,23.405.0,27.380.0,47.206.0,23.181.0,45.188.0,33.153.0,67.225.0,36.141.0"}
P.entries["quest:8852"] = {n="Десять жетонов в обмен на припасы",s="Десять жетонов в обмен на припасы — снабженческий обмен, который организует полководец Горчук в Оргриммаре. Герои Орды могут обменять лишние жетоны за заслуги на практичное боевое снаряжение и припасы. Хотя такая сделка лишает официальной славы и признания, она напрямую снаряжает бойцов передовой для грядущих сражений.",h="Десять жетонов в обмен на припасы — снабженческий обмен, который организует полководец Горчук в Оргриммаре.",kw={"commendation","gorchuk","logistics","orgrimmar","signets","supplies","war effort","warlord gorchuk","заслуги","горчук","снабжение","оргриммар","жетоны","припасы","военные усилия","полководец горчук"},ang={["class:Warrior"]="Бойцы передовой знают, что холодная сталь и обильные пайки выигрывают затяжные войны так же надежно, как воинская отвага.",["faction:Horde"]="Каждый ящик припасов, собранный в Оргриммаре, напрямую питает готовность Орды к жестоким битвам на горизонте."},sec={{t="Снаряжение для фронта",b="Пока Орда мобилизует легионы на войну, сбор припасов так же важен, как и сбор воинов. Полководец Горчук руководит снабжением в Аллее Духов и следит, чтобы ящики с оружием, пайками и доспехами шли к линии фронта. Те, кто доказал свою преданность, могут сдать жетоны за заслуги и получить полезное снаряжение из армейских запасов."},{t="Практичное выживание вместо славы",b="Жетоны за заслуги Орды обычно сдают как доказательство службы, и солдат получает престиж и известность среди командования. Обмен их прямо на снаряжение обходит это формальное признание ради простого выживания. Горчук понимает, что лишняя сумка припасов или крепкое оружие могут решить исход, когда начнется столкновение армий."}},faq={{q="Что такое жетоны за заслуги Орды?",a="Жетоны за заслуги Орды — официальные знаки, которые выдают героям, собирающим важное сырье и ресурсы для военной мобилизации Орды.",al={"commendation signet","horde signets","war signets","жетон за заслуги","жетоны орды","военные жетоны"}},{q="Кто такой полководец Горчук?",a="Полководец Горчук — офицер снабжения Орды, расквартированный в Оргриммаре. Он отвечает за сбор военных ресурсов и раздачу боевого провианта мобилизованным войскам.",al={"gorchuk","warlord gorchuk location","who is gorchuk","горчук","где полководец горчук","кто такой горчук"}},{q="Почему сдавать жетоны за припасы, а не за репутацию фракции?",a="Обмен жетонов на припасы жертвует политическим весом и официальным признанием ради практичных предметов, бинтов и снаряжения, помогающих выжить на передовой.",al={"signets vs supplies","why supplies","commendation rewards","жетоны или припасы","почему припасы","награды за заслуги"}},{q="Можно ли повторить этот обмен?",a="Да. Полководец Горчук продолжит обменивать полевые припасы, пока у вас есть нужные партии жетонов за заслуги.",al={"is this repeatable","repeat signets","turn in again","можно ли повторять","повторить жетоны","сдать снова"}},{q="Где проходит этот обмен?",a="Обмен проходит в столице Оргриммаре, где сосредоточены военные приготовления и запасы Орды.",al={"where to turn in signets","signet turn in location","gorchuk location","где сдавать жетоны","место сдачи жетонов","где горчук"}},{q="К какой войне готовится Орда?",a="Орда копит огромные запасы металла, ткани, трав и пайков, чтобы вооружить экспедиционные силы, способные противостоять надвигающейся катастрофической угрозе.",al={"what war","why gathering supplies","war effort","какая война","зачем собирают припасы","военные усилия"}}},fp="28,340,22.370.0,29.379.0,36.149.0,23.170.0,63.181.0,30.133.0,36.122.0,44.158.0"}
P.entries["quest:886"] = {n="Оазисы Степей",s="Высоко на Вершине Старейшин Громового Утеса верховный друид Хамуул Рунический Тотем ощущает тревожный всплеск силы, вливающийся в сухую почву Степей. Чтобы узнать правду, он отправляет перспективных путников на восток, за ворота Мулгора, на встречу со своим сородичем Тонгой Руническим Тотемом на Перекресток. Это задание открывает расследование о неестественных водах, появляющихся на выжженных солнцем равнинах.",h="Высоко на Вершине Старейшин Громового Утеса верховный друид Хамуул Рунический Тотем ощущает тревожный всплеск...",kw={"bloodhoof village","cenarion circle","crossroads","elder rise","hamuul runetotem","mulgore","oases","the barrens","thunder bluff","tonga runetotem","деревня кровавого копыта","круг кенария","перекресток","вершина старейшин","хамуул рунический тотем","мулгор","оазисы","степи","громовой утес","тонга рунический тотем"},ang={["class:Druid"]="Как первые ученики Хамуула Рунического Тотема, молодые друиды получили от Верховного друида наказ внимать шепоту земли и исцелять раны в хрупком равновесии природы.",["faction:Horde"]="Перекресток — жизненно важная связь западных владений Орды с побережьем, поэтому любое магическое возмущение поблизости вызывает глубокую стратегическую и духовную тревогу.",["race:Tauren"]="Для таурен, впервые покидающих священные луга Мулгора, это задание становится обрядом посвящения в более широкие обязанности по защите равновесия Калимдора."},sec={{t="Тревога среди засухи",b="Пока равнины Мулгора процветают под бдительным взором Матери-Земли, обширные саванны Степей на востоке на протяжении поколений остаются суровыми, выжженными и сухими. Однако недавно таурены-друиды, медитирующие на Вершине Старейшин Громового Утеса, почувствовали странные потоки энергии, пробуждающиеся глубоко под иссохшими равнинами. Жизнь пробуждается там, где ей быть не должно, и Круг Кенария опасается, что сила, вызвавшая этот всплеск, может таить скрытую угрозу для земли и ее обитателей."},{t="На восток, за Великие врата",b="Чтобы разобраться в этих странных событиях, верховный друид Хамуул Рунический Тотем отправил Тонгу Рунический Тотем в поход. Понимая, что обширные дикие земли таят слишком много опасностей для одного разведчика, Хамуул привлекает путников, покидающих Мулгор, чтобы они поспешили вслед за Тонгой. Дорога на восток мимо Деревни Кровавого Копыта и через горные перевалы ведет прямо к Перекрестку — пыльному, шумному сердцу земель Орды в Степях, где Тонга ждет ответов."}},faq={{q="Почему Хамуул Рунический Тотем обеспокоен из-за Степей?",a="Хамуул и друиды Громового Утеса почувствовали неестественный всплеск силы, просачивающийся в почву Степей. Внезапное оживление жизни в таком сухом и суровом климате говорит о том, что под поверхностью действуют необычные силы.",al={"why barrens oases","hamuul concern","why send to cross roads","почему оазисы степей","беспокойство хамуула","зачем отправляют на перекресток"}},{q="Где найти Тонгу Рунический Тотем?",a="Тонга Рунический Тотем находится на Перекрестке в центральных Степях. Чтобы найти его, следуйте по главной восточной дороге из Мулгора, пересеките границу Степей и держитесь северной ветки тропы, пока не дойдете до поселения.",al={"tonga runetotem location","where is tonga","tonga crossroads","где тонга рунический тотем","где тонга","тонга перекресток"}},{q="Доступно ли это задание только таурен?",a="Верховный друид Хамуул Рунический Тотем выдает это задание в основном путникам, покидающим Мулгор. Однако искатели приключений любой расы Орды могут встретиться с Тонгой прямо на Перекрестке и помочь в расследовании истории с оазисами.",al={"can non tauren get barrens oases","who gives the barrens oases","может ли не таурен взять оазисы степей","кто выдает оазисы степей"}},{q="Что ждет в конце дороги от Деревни Кровавого Копыта?",a="Если покинуть Деревню Кровавого Копыта на восток, дорога ведет мимо Великих врат, отделяющих Мулгор от Степей. Миновав горы, поверните на север у развилки, и вы благополучно пройдете через суровые дикие земли к Перекрестку.",al={"road to crossroads","mulgore to barrens path","дорога на перекресток","путь из мулгора в степи"}},{q="Какие странные силы ощущает Хамуул?",a="Друиды ощущают магические потоки, создающие зеленые оазисы с родниками посреди пустыни, известной своей жестокой засухой. Тонгу Рунический Тотем отправили выяснить, благо этот рост или опасная порча.",al={"what powers in barrens","oases mystery","unnatural energy barrens","какие силы в степях","тайна оазисов","неестественная энергия степей"}},{q="Почему Степи считаются такими опасными для молодых искателей приключений?",a="Степи — обширная пограничная земля, кишащая хищниками: по ней рыскают ящеры-разведчики, топтуны и враждебные племена кентавров. Хамуул предупреждает путников, чтобы они строго держались патрулируемых торговых троп и суровая глушь не одолела их.",al={"barrens danger","why stay on road","опасность степей","почему держаться дороги"}}},fp="17,423,28.514.0,26.469.0,52.244.0,33.233.0,39.210.0,58.219.0,42.214.0,66.240.0"}
P.entries["quest:8866"] = {n="Старейшина Бронзобород",s="Старейшина Бронзобород — встреча Лунного фестиваля со Старейшиной Бронзобородом в горном городе дворфов Стальгорне. Почтение, оказанное ему во время этого праздника предков, приносит путникам мудрость и знак его уважения. Это отражает глубокое почитание, с которым жители Каз Модана относятся к своим предкам и долгому наследию.",h="Старейшина Бронзобород — встреча Лунного фестиваля со Старейшиной Бронзобородом в горном городе дворфов...",kw={"ancestors","bronzebeard","coin of ancestry","elder","ironforge","lunar festival","предки","бронзобород","монета наследия","старейшина","стальгорн","лунный фестиваль"},ang={["faction:Alliance"]="Старейшина мирно живет в столице — Стальгорне, радушно принимая членов Альянса, желающих отпраздновать древние традиции под горой.",["faction:Horde"]="Добраться до Старейшины Бронзоборода — значит опасно проникнуть в укрепленное сердце Стальгорна, где требуется скрытность или дерзость, чтобы выразить приветствие.",["race:Dwarf"]="Для дворфов почтение к Старейшине Бронзобороду — прямое общение с благородными предками, построившими их горное королевство из камня и железа."},sec={{t="Дань уважения горному клану",b="Во время Лунного фестиваля по всему Азероту появляются духи и почтенные старейшины, чтобы поделиться мудростью с путниками, чтящими прошлое. В Стальгорне Старейшина Бронзобород олицетворяет стойкую выносливость клана Бронзобородов. Когда искатели приключений приходят выразить почтение, он тихо радуется, что жители этих земель по-прежнему помнят и чтят род древних рас."},{t="Знаки уважения предков",b="Эта встреча не требует великих испытаний или опасных походов: путникам нужно лишь остановиться, признать присутствие старейшины и поприветствовать его. В ответ Старейшина Бронзобород шлет добрые пожелания и вручает Монету Наследия. Эти священные праздничные знаки — осязаемое напоминание о живой связи современных героев с поколениями, выковавшими Каз Модан из камня и огня."}},faq={{q="Кто такой Старейшина Бронзобород?",a="Старейшина Бронзобород — дворф-предок, которого чтят во время Лунного фестиваля. Он отдыхает в подземной крепости Стальгорна, встречая гостей и празднуя их наследие.",al={"elder bronzebeard","who is the elder","ironforge elder","старейшина бронзобород","кто такой старейшина","старейшина стальгорна"}},{q="Что означает почтение к Старейшине Бронзобороду?",a="Приветствие его — акт почитания предков во время Лунного фестиваля. Он хвалит путников за то, что они помнят корни и древние жертвы первых рас Азерота.",al={"why honor bronzebeard","bronzebeard elder purpose","зачем почтить бронзоборода","цель старейшины бронзоборода"}},{q="Где в Стальгорне найти Старейшину Бронзоборода?",a="Его можно найти в Стальгорне: он стоит там, доступный тем, кто исследует горный город, ища праздничных старейшин, чтобы выразить почтение.",al={"elder bronzebeard location","where is bronzebeard the elder","ironforge elder spot","где старейшина бронзобород","где старейшина бронзобород стальгорн","место старейшины в стальгорне"}},{q="Могут ли игроки Орды поговорить со Старейшиной Бронзобородом?",a="Старейшина Бронзобород поприветствует любого, кто захочет его поприветствовать, но искателям приключений из Орды придется пробраться в укрепленные глубины Стальгорна и избегать стражи дворфов, чтобы добраться до него.",al={"can horde do this quest","horde elder bronzebeard","может ли орда выполнить задание","орда старейшина бронзобород"}},{q="Какую награду дает старейшина?",a="Он дарует свое благословение предков и праздничную монету — знак доброй воли и подтверждение того, что вы почтили древние поколения.",al={"elder bronzebeard reward","what token does he give","награда старейшины бронзоборода","какой знак он дает"}},{q="Нужны ли в этом задании сражения?",a="Чтобы поговорить с ним, сражаться не нужно: достаточно почтительно подойти к старейшине, хотя на пути может встретиться опасность во вражеских землях.",al={"do i have to fight","bronzebeard the elder fight","нужно ли сражаться","бой со старейшиной бронзобородом"}}},fp="21,329,27.426.0,26.399.0,25.184.0,45.179.0,46.138.0,47.173.0,34.137.0,35.164.0"}
P.entries["quest:887"] = {n="Флибустьеры Южных морей",s="Флибустьеры Южных морей — вводное задание на поимку, которое дает Газлоу в Кабестане, чтобы обуздать местное пиратство. Разъяренный набегами пиратов на торговые суда гоблинов, главный инженер нанимает искателей приключений для нападения на лагерь пиратов Южных морей на Торговом побережье к югу от города.",h="Флибустьеры Южных морей — вводное задание на поимку, которое дает Газлоу в Кабестане, чтобы обуздать местное...",kw={"barrens","brigands","cannoneers","freebooters","gazlowe","grezzlik","pirates","ratchet","southsea","steamwheedle","степи","разбойники","канониры","флибустьеры","газлоу","грезлик","пираты","кабестан","южные моря","хитрая шестеренка"},ang={["class:Rogue"]="Лагерь Флибустьеров Южных морей полон возможностей для карманников, если вам удастся проскользнуть мимо бдительных дозорных и тяжелой береговой артиллерии.",["faction:Horde"]="Кабестан служит важным коридором снабжения Орды в Калимдоре; очистка морских путей от морских разбойников защищает линии снабжения, идущие вглубь Степей."},sec={{t="Заноза для Газлоу",b="Кабестан — главный нейтральный торговый порт в центральном Калимдоре, живущий за счет постоянного потока торговых судов между восточными континентами и Калимдором. Однако Флибустьеры Южных морей разбили укрепленный лагерь на берегу прямо к югу, на Торговом побережье. С этой базы пираты нападают на входящие и выходящие гоблинские грузовые суда, истощая прибыли и подрывая местные морские пути."},{t="Пренебрежение со стороны Подкопья",b="Гнев Газлоу вызван не только самими пиратами, но и мнимой некомпетентностью флотского руководства Картеля Хитрая Шестеренка. Несмотря на огромные суммы, вложенные торговыми принцами в содержание оборонительных флотов, вице-адмирал Грезлик не сумел эффективно охранять воды. Недовольный вялой реакцией Подкопья, Газлоу обходит флотские каналы и нанимает независимых наемников, чтобы проредить пиратских разбойников и канониров."}},faq={{q="Кто такие Флибустьеры Южных морей?",a="Флибустьеры Южных морей — известный синдикат пиратов-людей, дворфов и гномов, действующий в южных океанах и на Великом море. В Степях они удерживают вооруженный плацдарм к югу от Кабестана, нападая на торговые суда и грабя товары, направляющиеся в Калимдор.",al={"southsea pirates","who are southsea freebooters","freebooters lore","пираты южных морей","кто такие флибустьеры южных морей","предания о флибустьерах"}},{q="Почему Газлоу так беспокоят эти пираты?",a="Газлоу управляет портом Кабестан от имени Картеля Хитрая Шестеренка. Каждое судно, перехваченное или разграбленное Флибустьерами, напрямую сокращает доходы картеля и подрывает репутацию Кабестана как безопасной торговой гавани.",al={"why gazlowe want pirates dead","gazlowe motivation","ratchet pirate problem","зачем газлоу смерть пиратов","мотивы газлоу","проблема пиратов кабестана"}},{q="Где находится лагерь пиратов?",a="Лагерь Южных морей лежит прямо вдоль берега к югу от Кабестана, на Торговом побережье. В нем есть укрепленные палатки, вытащенные на берег шлюпки и артиллерийские позиции, которые занимают канониры Южных морей.",al={"where are southsea brigands","cannoneer location","where is pirate camp","где разбойники южных морей","где канониры","где лагерь пиратов"}},{q="Кто такой вице-адмирал Грезлик?",a="Вице-адмирал Грезлик — офицер, отвечающий за торговые флоты Картеля Хитрая Шестеренка и защиту их морских путей. Газлоу считает его по большей части бесполезным из-за наглой пиратской деятельности прямо у берегов Степей.",al={"who is grezzlik","vice admiral grezzlik lore","steamwheedle admiral","кто такой грезлик","вице-адмирал грезлик","адмирал хитрой шестеренки"}},{q="Что будет после зачистки лагеря?",a="Сокращение числа защитников лагеря решает лишь часть проблемы. Когда разбойники и канониры разбиты, Газлоу принимается искать ценный груз, который они похитили, что напрямую ведет к расследованию пропажи его поставок.",al={"what comes next","southsea freebooters follow up","missing shipment","что дальше","продолжение флибустьеров южных морей","пропавший груз"}},{q="Связаны ли Флибустьеры Южных морей с Альянсом или Ордой?",a="Нет. Флибустьеры Южных морей действуют полностью вне обеих фракций и без разбора нападают на суда Альянса, грузовые корабли Орды и нейтральные гоблинские транспорты.",al={"are freebooters horde","are pirates alliance","southsea faction","флибустьеры орда","пираты альянс","фракция южных морей"}}},fp="20,287,25.442.0,22.467.0,33.283.0,50.240.0,33.218.0,29.259.0,36.239.1,67.171.0"}
P.entries["quest:888"] = {n="Украденное добро",s="«Украденное добро» завершает усилия Газлоу по возвращению ценного груза, захваченного Флибустьерами Южных морей у берегов Кабестана. Вместо того чтобы пытаться вернуть каждый потерянный ящик, гоблинский вождь сосредоточивается на двух важнейших предметах: партии сапожных ботинок и хрупкой телескопической линзе, необходимой для завершения его обсерватории.",h="«Украденное добро» завершает усилия Газлоу по возвращению ценного груза, захваченного Флибустьерами Южных...",kw={"barrens","booty bay","drizzlik","gazlowe","ratchet","southsea freebooters","stolen booty","telescopic lens","степи","пиратская бухта","дризлик","газлоу","кабестан","флибустьеры южных морей","украденное добро","телескопическая линза"},ang={["profession:Engineering"]="Проект обсерватории Газлоу демонстрирует точность гоблинской оптики: для создания практичной прибрежной инфраструктуры необходимо сочетать тяжелое строительство и тонкую работу со стеклом.",["profession:Tailoring"]="Ввоз ботинок из Пиратской бухты от самого Дризлика показывает, как широка торговая сеть готовых кожаных изделий и сапожного ремесла между портами Картеля Хитрая Шестеренка."},sec={{t="Пиратский захват",b="Флибустьеры Южных морей давно терроризировали торговые пути Великого моря, но создание укрепленного лагеря к югу от Кабестана привело их к прямому конфликту с Газлоу. Когда торговые суда, шедшие в порт, перехватывали и грабили, Картель Хитрая Шестеренка терял значительные запасы. Малоценные товары можно было списать на обычные риски перевозки, но дорогой специализированный груз стоил того, чтобы нанять наемников для штурма пиратской твердыни."},{t="Недостающие части",b="Приоритеты Газлоу были предельно практичными. Первым предметом была важная партия ботинок, отправленная Дризликом из Пиратской бухты и остро необходимая местным рабочим. Второй был куда более специализированным: шлифованная телескопическая линза для заметной башни обсерватории над Кабестаном. Ее парная линза благополучно прибыла сухопутным караваном через Дуротар, а морскую половину украли прямо с воды. Без нее обсерватория оставалась пустым каркасом."}},faq={{q="Почему Газлоу так важны именно эти два предмета?",a="Газлоу признает, что вернуть весь захваченный груз невозможно, но партия ботинок от Дризлика из Пиратской бухты и телескопическая линза незаменимы. Ботинки нужны местным рабочим, а точная линза необходима для завершения обсерватории над Кабестаном.",al={"why boots and lens","gazlowe items","what was stolen","почему ботинки и линза","предметы газлоу","что было украдено"}},{q="Откуда взялись две линзы для обсерватории?",a="Для правильной работы обсерватории нужны две линзы. Большая линза благополучно прибыла сухопутным караваном через Дуротар. Меньшую отправили морем, но ее перехватили, когда Флибустьеры Южных морей напали на судно у берегов Степей.",al={"telescopic lens origin","observatory lenses","how did gazlowe get the lenses","происхождение линзы","линзы обсерватории","как газлоу получил линзы"}},{q="Кто такой Дризлик?",a="Дризлик — гоблин-сапожник из Пиратской бухты на юге Восточных королевств. Он изготовил и отправил партию обуви для рабочих Газлоу в Кабестане, прежде чем пираты перехватили грузовое судно.",al={"drizzlik booty bay","who sent the boots","drizzlik","дризлик пиратская бухта","кто прислал ботинки","дризлик"}},{q="Где спрятаны украденные предметы?",a="И ящики с ботинками, и телескопическая линза спрятаны в лагере пиратов Южных морей на Торговом побережье, к югу от Кабестана.",al={"where are the boots","pirate camp location","where is the lens","где ботинки","расположение лагеря пиратов","где линза"}},{q="Что происходит после этого задания?",a="«Украденное добро» — последнее звено в этой цепочке расследования о пиратах Южных морей. Когда предметы возвращены, Газлоу выражает благодарность, хвалит вашу надежность и предлагает вам и дальше работать на его торговое предприятие в Кабестане.",al={"stolen booty followup","next quest","what is next after stolen booty","продолжение украденного добра","следующее задание","что после украденного добра"}},{q="Зачем в Кабестане обсерватория?",a="Гоблинская инженерия сильно зависит от наблюдения, навигации и изучения окружающей суши и морских путей. Достроенная башня обсерватории позволит руководству Кабестана следить за приближением торговых флотов, судов соперников и надвигающихся угроз на Торговом побережье.",al={"ratchet telescope","gazlowe observatory","why does gazlowe want a telescope","телескоп кабестана","обсерватория газлоу","зачем газлоу телескоп"}}},fp="12,322,16.494.0,18.474.0,61.282.0,47.273.0,16.220.0,34.144.0,30.249.1,37.278.0"}
P.entries["quest:889"] = {n="Дух Ветра",s="«Дух Ветра» — повторяемый ритуал, который предлагает пленный свинобраз Кривозуб в Лагере Таурахо. Направляя остаточную силу кровавых осколков Агамаггана, Кривозуб наделяет путников быстротой, чтобы они могли обогнать ветер на огромных саваннах Степей.",h="«Дух Ветра» — повторяемый ритуал, который предлагает пленный свинобраз Кривозуб в Лагере Таурахо.",kw={"agamaggan","barrens","blood shards","camp taurajo","mangletooth","quilboar","speed","spirit of the wind","агамагган","степи","кровавые осколки","лагерь таурахо","кривозуб","свинобраз","скорость","дух ветра"},ang={["class:Druid"]="Друиды, изучающие Степи, часто находят в этих обрядах остаточную силу Дикого бога Агамаггана — увлекательное, пусть и грубое проявление первобытной природы.",["class:Shaman"]="Общение с духом ветра через кристаллизованную божественную сущность перекликается с шаманскими традициями почитания стихий и сил предков.",["faction:Horde"]="Стражи Лагеря Таурахо пристально следят за Кривозубом, но разведчики Орды регулярно пользуются его знанием магии кровавых осколков, чтобы быстрее пересекать южные равнины."},sec={{t="Дар кровавых осколков",b="В засушливых просторах Степей быстрое пересечение открытой местности может стать разницей между выживанием и гибелью от хищных зверей или бродячих отрядов кентавров. Пленный свинобраз Кривозуб, заточенный в Лагере Таурахо, знает о скрытой силе красных кристаллических кровавых осколков, разбросанных по региону. Получив десять таких реликвий, он обращается к их первобытному резонансу и дарует Дух Ветра, придающий путникам стремительность, чтобы опередить завывающие степные ветры."},{t="Древнее дыхание Агамаггана",b="Традиции свинобразов чтят Агамаггана, Великого Вепря, пролившего свою кровь по центральному Калимдору во время древней Войны Древних. Даже в плену Кривозуб хранит глубокие знания об обрядах дикого бога. Направление пролитой крови бога не просто изменяет плоть, но пробуждает дикую силу, позволяя бегуну сравняться в скорости со скачущими стадами жевр. Хотя свинобразы — заклятые враги Орды, Кривозуб готов даровать благословения Агамаггана любому, кто подпитает его ритуалы свежими осколками."}},faq={{q="Что такое Дух Ветра?",a="Это временное благословение, которое дарует Кривозуб в Лагере Таурахо. В обмен на десять кровавых осколков он повышает скорость бега, помогая путникам пересечь Степи.",al={"what is spirit of the wind","spirit of the wind buff","speed buff mangletooth","что такое дух ветра","бонус дух ветра","бонус скорости кривозуб"}},{q="Кто предлагает Дух Ветра?",a="Кривозуб, свинобраз, которого Орда держит в плену в Лагере Таурахо, проводит ритуал, когда вы заслужите его содействие.",al={"who gives spirit of the wind","mangletooth","who turns in blood shards for speed","кто дает дух ветра","кривозуб","кому сдавать кровавые осколки за скорость"}},{q="Зачем Кривозубу нужны кровавые осколки?",a="Кровавые осколки — кристаллические фрагменты, образовавшиеся из пролитой крови Агамаггана. Кривозуб черпает из них скрытую первобытную силу древнего полубога, чтобы творить свои благословения.",al={"why blood shards","blood shard purpose","what does mangletooth do with shards","зачем кровавые осколки","назначение кровавых осколков","что кривозуб делает с осколками"}},{q="Можно ли получить это благословение более одного раза?",a="Да. Пока вы приносите Кривозубу по десять кровавых осколков каждый раз, он будет снова дарить благословение, когда бы вы к нему ни вернулись.",al={"is spirit of the wind repeatable","can i do this quest again","repeatable buff","повторяется ли дух ветра","можно ли повторить задание","повторяемый бонус"}},{q="Почему свинобраз помогает членам Орды?",a="Кривозуб находится в плену в Таурахо и выторговал себе жизнь, предложив родовые знания о магии Агамаггана: он имеет дело с путниками, которые собирают ценные для него священные осколки.",al={"why does mangletooth help","friendly quilboar","why help horde","почему кривозуб помогает","дружелюбный свинобраз","почему помогать орде"}},{q="Как долго длится благословение?",a="Кривозуб замечает, что чары действуют недолго, но дают достаточно быстроты, чтобы заметно облегчить путь по Степям, прежде чем исчезнут.",al={"how long is the buff","spirit of the wind duration","does speed buff last","сколько длится бонус","длительность духа ветра","долго ли держится бонус скорости"}}},fp="18,258,24.545.0,26.545.0,31.173.0,34.118.0,42.194.0,43.140.0,47.180.0,32.157.0"}
P.entries["quest:89"] = {n="Мост Безмолвия",s="«Мост Безмолвия» — восстановительные работы под руководством штейгера Ослоу в Приозерье по ремонту поврежденного каменного моста города. Работы остановились, потому что железо, предназначенное для проекта, во время последнего вторжения орков пошло на оружие, а замещающий караван из Штормграда попал в засаду гноллов Красногорья.",h="«Мост Безмолвия» — восстановительные работы под руководством штейгера Ослоу в Приозерье по ремонту...",kw={"everstill bridge","foreman oslow","iron pikes","iron rivets","lakeshire","redridge","redridge gnolls","мост безмолвия","штейгер ослоу","железные колья","железные заклепки","приозерье","красногорье","гноллы красногорья"},ang={["faction:Alliance"]="Оборванные линии снабжения Приозерья — еще один яркий признак пренебрежения Штормграда своими дальними землями: местным штейгерам приходится полагаться на наемные клинки для охраны торговли на дорогах.",["profession:Blacksmithing"]="Нехватка показывает, насколько отчаянным было положение защитников Приозерья: ковка оружия из строительных кольев и заклепок была последней мерой, которая спасла жизни ценой жизненно важной инфраструктуры."},sec={{t="Город отрезан",b="Каменный мост через Озеро Безмолвия — жизненная артерия Приозерья: он соединяет западные дороги в сторону Элвиннского леса с дальним берегом и северными перевалами. Во время недавних вторжений орков город был на грани гибели. Когда на кону стояло выживание, Приозерье переплавило запасы строительного железа на боеприпасы, клинки и латные доспехи, чтобы отразить захватчиков из клана Черной Горы, оставив мост недостроенным и уязвимым."},{t="Украденные грузы",b="Штейгер Ослоу обратился к Дому знати и Штормграду за новыми строительными материалами для завершения ремонта. Караван с железом отправили, но он так и не прибыл. Отряд гноллов Красногорья устроил засаду на дороге и утащил жизненно важные железные колья и заклепки в свои лагеря в северных холмах. Пока нет отважных путников, готовых вернуть украденное, проект моста стоит, а гноллы и орки сильнее сжимают горы в своей хватке."}},faq={{q="Почему Мост Безмолвия не достроен?",a="Приозерью пришлось переплавить строительное железо на оружие, пули и доспехи, чтобы пережить недавнее вторжение орков. Замещающий груз, посланный из Штормграда, затем попал в засаду и был разграблен местными гноллами, и у штейгера Ослоу не осталось материалов для завершения работ.",al={"why broken bridge","who broke everstill bridge","lakeshire bridge broken","почему сломан мост","кто сломал мост безмолвия","сломан мост приозерья"}},{q="Кто такой штейгер Ослоу?",a="Штейгер Ослоу — мастер-строитель, руководящий восстановлением моста через Озеро Безмолвия. Оставшись без поддержки и материалов из столицы, он рассчитывает на странствующих героев, которые вернут украденные стройматериалы из холмов.",al={"foreman oslow","who is oslow","штейгер ослоу","кто такой ослоу"}},{q="Кто украл припасы для моста?",a="Гноллы Красногорья устроили засаду на караван с припасами из Штормграда и унесли железные колья и заклепки в свои лагеря в холмах за Приозерьем.",al={"who stole iron rivets","who took the bridge iron","кто украл железные заклепки","кто забрал железо для моста"}},{q="Почему Штормград не отправил стражу охранять караван?",a="Пока король Вариан Ринн пропал, Дом знати Штормграда в основном отказывает дальним землям в военной помощи. Красногорье оставлено сражаться с гноллами и орками Черной Горы самостоятельно, лишь с минимальной поддержкой городских ополчений.",al={"stormwind help lakeshire","why no guards","штормград помощь приозерью","почему нет стражи"}},{q="Почему Приозерье переплавило свое железо?",a="Во время последнего вторжения орков защитникам Приозерья отчаянно не хватало военного снаряжения. Чтобы пережить натиск, город переплавил запасы строительного железа в доспехи, мечи и боеприпасы.",al={"why melt iron","orc invasion redridge","зачем переплавили железо","вторжение орков красногорье"}},{q="Какие припасы нужны для ремонта моста?",a="Штейгеру Ослоу нужны именно тяжелые железные колья и железные заклепки, чтобы надежно укрепить и закрепить пролеты моста через Озеро Безмолвия.",al={"bridge materials","what does oslow need","материалы для моста","что нужно ослоу"}}},fp="20,319,14.449.0,16.491.0,39.292.0,21.244.0,30.165.0,56.254.0,39.212.0,46.137.0"}
P.entries["quest:890"] = {n="Пропавший груз",s="Газлоу ожидает задержавшийся груз товаров, отправленный через Великое море из Пиратской бухты. Подозревая либо ошибки в портовой отчетности, либо Флибустьеров Южных морей, он отправляет курьеров на причалы Кабестана, чтобы сверить записи Управляющего пристанью Головокружилкинса.",h="Газлоу ожидает задержавшийся груз товаров, отправленный через Великое море из Пиратской бухты.",kw={"booty bay","dizzywig","drizzlek","freebooters","gazlowe","ledger","ratchet","shipment","пиратская бухта","головокружилкинс","дризлек","флибустьеры","газлоу","книга учета","кабестан","груз"},ang={["faction:Horde"]="Кабестан сохраняет нейтралитет и служит важным портом для путников Орды между Калимдором и Тернистой долиной, поэтому торговля в доках — предмет общих интересов.",["profession:Engineering"]="Постоянная потребность Газлоу в запчастях, редких импортных товарах и особых механизмах из Пиратской бухты показывает логистические трудности поддержания работы механизмов Кабестана вдали от гоблинских промышленных центров."},sec={{t="Жизненно важная артерия Кабестана",b="Кабестан процветает как торговый плацдарм Картеля Хитрая Шестеренка в Калимдоре. Корабли регулярно пересекают Великое море из Пиратской бухты, привозя промышленные товары, редкие припасы и тяжелые грузы, необходимые для быстрого строительства и торговли порта. Когда входящий груз пропадает, это нарушает дела главного инженера Газлоу, который тщательно учитывает каждый ящик, попадающий в порт."},{t="Сверка груза",b="Хотя Флибустьеры Южных морей наводняют побережье к югу от города и регулярно перехватывают торговые суда, Газлоу знает, что не стоит действовать, не проверив собственные книги. Прежде чем обвинять пиратов или посылать наемников в схватку, он отправляет свои личные записи об имуществе прямо Управляющему пристанью Головокружилкинсу на причалы. Головокружилкинс следит за фактической выгрузкой и хранением корабельных грузов, а потому только он из гоблинов может определить, потерян ли груз в море или просто положен не на тот склад."}},faq={{q="Что находится в пропавшем грузе?",a="Хотя Газлоу говорит в целом о важных товарах из Пиратской бухты, Управляющий пристанью Головокружилкинс замечает, что главный инженер, скорее всего, переживает из-за особого заказа на сапоги от Дриззлека.",al={"gazlowe cargo","what was stolen","missing shipment goods","груз газлоу","что было украдено","товары пропавшего груза"}},{q="Кто такой Управляющий пристанью Головокружилкинс?",a="Управляющий пристанью Головокружилкинс заведует входящими и исходящими судовыми декларациями на причалах Кабестана. От имени Картеля Хитрая Шестеренка он управляет передачей грузов между заморскими судами и местными складами.",al={"dizzywig","who is dizzywig","ratchet dockmaster","головокружилкинс","кто такой головокружилкинс","начальник порта кабестана"}},{q="Почему Газлоу подозревает Флибустьеров Южных морей?",a="Флибустьеры Южных морей устроили лагеря на Торговом побережье к югу от Кабестана. Они регулярно нападают на торговые пути между Калимдором и Восточными королевствами, поэтому становятся главными подозреваемыми, когда пропадает торговый груз.",al={"freebooters role","pirate thieves","why pirates","роль флибустьеров","пираты-воры","почему пираты"}},{q="Откуда пришел груз?",a="Груз пришел из Пиратской бухты — главного гоблинского портового города на южной оконечности Тернистой долины в Восточных королевствах.",al={"shipment origin","where did it come from","booty bay cargo","происхождение груза","откуда он пришел","груз пиратской бухты"}},{q="Что происходит после передачи книги учета Головокружилкинсу?",a="Головокружилкинс сверяет свои грузовые манифесты с книгой учета Газлоу, чтобы выяснить, был ли груз ошибочно направлен на склады Кабестана или захвачен до выгрузки.",al={"dizzywig next steps","ledger follow up","головокружилкинс дальнейшие действия","книга учета дальше"}},{q="Почему Газлоу сам не проверит доки?",a="Как главный инженер и глава Кабестана, Газлоу руководит работой города и проектами расширения из своего центрального кабинета. Он предпочитает платить странствующим героям за беготню с бумагами по поселению.",al={"why send me","gazlowe laziness","почему я","лень газлоу"}}},fp="20,265,24.406.0,27.524.0,32.185.0,28.212.0,50.258.0,33.138.0,49.163.0,44.201.0"}
P.entries["quest:891"] = {n="Пушки крепости Северной Стражи",s="Капитан Тало'тас Сияющий из Кабестана устал от того, что его торговые суда разносят в щепки артиллеристы Альянса из Крепости Северной Стражи. Он нанимает героев Орды, чтобы они прошли по Торговому побережью, заставили замолчать артиллерийских офицеров крепости и забрали знаки отличия у павших пехотинцев.",h="Капитан Тало'тас Сияющий из Кабестана устал от того, что его торговые суда разносят в щепки артиллеристы...",ang={["faction:Horde"]="Удар по Крепости Северной Стражи напрямую устраняет агрессивное укрепление Альянса, вторгшееся в Степи, и обеспечивает Орде границы Калимдора.",["race:Human"]="Трагическая паранойя в Крепости Северной Стражи показывает, какое напряжение испытывают приграничные гарнизоны Терамора, оторванные от дома и склонные к безрассудной враждебности."},sec={{t="Угроза на побережье",b="Крепость Северной Стражи возвышается над южным побережьем Степей. Она была построена как укрепленный оплот людей Терамора. Крепость призвана охранять интересы Альянса и следить за действиями Орды в Калимдоре, но засевшими в ней солдатами овладела жестокая паранойя. Принимая любой незнакомый парус за вражеский, их батареи на стенах открывают огонь без разбора, угрожая мирным торговым судам и каперским кораблям Кабестана."},{t="Молчание бастионов",b="Captain Brightsun refuses to let his ships be sunk without consequence. The strike against Northwatch targets its command: Captain Fairmount and her chief cannoneers, Whessan and Smythe. Striking them down and stripping Theramore medals from the garrison's soldiers leaves the hold's artillery disarrayed, granting Ratchet's maritime operations breathing room along the Merchant Coast."}},faq={{q="Почему Крепость Северной Стражи стреляет по кораблям из Кабестана?",a="Солдаты-люди, стоящие в Крепости Северной Стражи, охвачены лихорадочной паранойей. Опасаясь нападений Орды и местных пиратов, их стрелки палят почти по каждому судну, проходящему мимо Торгового побережья, не разбирая, под нейтральным или враждебным флагом оно идет.",al={"why are they shooting ships","why northwatch attacking ratchet","northwatch cannons firing","почему стреляют по кораблям","почему северная стража атакует кабестан","пушки северной стражи стреляют"}},{q="Кто такой капитан Тало'тас Сияющий?",a="Капитан Тало'тас Сияющий — эльф крови, капитан каперского судна, базирующийся в гоблинском порту Кабестан. Он командует торговым флотом и защищает местные торговые интересы от агрессивных соперников, включая излишне рьяные силы Альянса в Крепости Северной Стражи.",al={"who gives this quest","thalo'thas brightsun","quest giver ratchet","кто дает это задание","тало'тас сияющий","персонаж, выдающий задания, кабестан"}},{q="Who are Captain Fairmount, Cannoneer Whessan, and Cannoneer Smythe?",a="Captain Fairmount commands the garrison at Northwatch Hold, while Whessan and Smythe are the senior cannoneers directing the artillery batteries overlooking the sea. Slaying them disrupts the fortress's chain of command and takes their heavy cannons out of action.",al={"fairmount whessan smythe","northwatch officers","gun targets northwatch"}},{q="Что такое тераморские медали?",a="Тераморские медали — военные знаки отличия, которые носят пехотинцы и стражи Крепости Северной Стражи. Капитан Сияющий требует их как весомое доказательство того, что гибель его каперов отомщена, а гарнизон крепости разгромлен.",al={"theramore medal","why collect medals","what drops medals","тераморская медаль","зачем собирать медали","с кого падают медали"}},{q="Где находится Крепость Северной Стражи?",a="Крепость Северной Стражи стоит на юго-восточных утесах Степей, прямо к югу от Кабестана, на берегу, известном как Торговое побережье.",al={"where is northwatch","northwatch location","where are the guns of northwatch","где северная стража","расположение северной стражи","где пушки северной стражи"}},{q="Является ли Крепость Северной Стражи официальной частью Терамора?",a="Да. Крепость Северной Стражи — форпост, основанный королевством Терамор, чтобы закрепиться на материке Калимдора. Однако ее изолированный гарнизон действует крайне агрессивно и с глубоким подозрением относится ко всем, кто проходит через Степи.",al={"is northwatch theramore","alliance faction northwatch","jaina northwatch","северная стража терамор","северная стража альянс","джайна северная стража"}}},fp="22,293,24.434.0,22.385.0,54.304.0,36.255.0,67.264.0,26.246.0,33.149.0,48.252.0"}
P.entries["quest:892"] = {n="Пропавший груз",kw={"barrens","dizzywig","freebooters","gazlowe","ledger","pirates","ratchet","shipment","undermine","степи","головокружилкинс","флибустьеры","газлоу","гроссбух","пираты","кабестан","груз","подкопье"},ang={["class:Rogue"]="Разбор портовых бумаг показывает, как легко товары исчезают между морем и берегом — классический прием контрабандистов.",["faction:Alliance"]="Действовать в Степях нужно, тщательно выбирая союзников, а помощь руководству Кабестана помогает закрепиться в центре Калимдора.",["faction:Horde"]="Кабестан нейтрален, но расположение Газлоу обеспечивает стабильные торговые пути и гоблинский нейтралитет, выгодный Орде."},sec={{t="Учет сведен в доках",b="Ratchet thrives on trade, but running a bustling port alongside the Barrens brings constant logistical headaches. When an expected cargo shipment goes missing, Gazlowe assumes an error in harbor accounting or foul play on the piers. Upon examining the manifest, Wharfmaster Dizzywig insists his books are clean and the intake records fully accounted for, meaning the missing merchandise never even made it onto the dock."},{t="Взгляд на флибустьеров",b="With Dizzywig clearing the port's internal operations of embezzlement, only one plausible culprit remains: the Southsea Freebooters camped just down the coast. Dizzywig hands back the ledger along with a mention of separate crates waiting from Undermine, directing the adventurer back to Ratchet's chief engineer. Convinced of his wharfmaster's loyalty, Gazlowe pivots from managing supply ledgers to organizing an expedition to reclaim his stolen booty."}},faq={{q="Что записано в гроссбухе Газлоу?",a="Gazlowe's ledger contains shipping manifests, cargo inventories, and port intake logs detailing goods arriving in Ratchet. Wharfmaster Dizzywig reviews it to verify whether the missing crates were ever checked in off the ships.",al={"what is the ledger","gazlowes ledger","dock manifest","что за гроссбух","гроссбух газлоу","манифест доков"}},{q="Кто на самом деле украл груз Газлоу?",a="Газлоу подозревает Флибустьеров Южных морей, местную банду пиратов, раскинувшую лагерь на побережье к югу от Кабестана. Записи Головокружилкинса не выявляют на причалах расхождений, поэтому Газлоу обращает внимание на налетчиков.",al={"who stole the shipment","who took the cargo","who has the shipment","кто украл груз","кто забрал товар","у кого груз"}},{q="Почему Газлоу доверяет Управляющему пристанью Головокружилкинсу?",a="Газлоу доверяет Головокружилкинсу, потому что начальник причала у него на жалованье и зарекомендовал себя надежной службой. Босс считает, что Головокружилкинс не посмеет его обмануть, и принимает его слова о чистоте бухгалтерии.",al={"is dizzywig lying","does gazlowe trust dizzywig","dizzywig honest","головокружилкинс лжет","доверяет ли газлоу головокружилкинсу","головокружилкинс честен"}},{q="Что за товары из Подкопья упоминает Головокружилкинс?",a="Головокружилкинс упоминает, что получил отдельные товары из Подкопья, гоблинской столицы на острове Кезан. Они ждут, пока Газлоу выберет минутку, свободную от управления городом.",al={"undermine shipment","what is coming from undermine","undermine goods","груз из подкопья","что идет из подкопья","товары подкопья"}},{q="Куда ведет это расследование дальше?",a="Возвращение гроссбуха Газлоу ведет прямо к заданию «Украденное добро», в котором вас нанимают проникнуть в лагеря Флибустьеров Южных морей на южном побережье Степей и вернуть утраченный груз.",al={"what quest is next","next step after missing shipment","where to go next","какое задание следующее","что после пропавшего груза","куда идти дальше"}},{q="Где находится Управляющий пристанью Головокружилкинс?",a="Управляющий пристанью Головокружилкинс заведует причалами Кабестана и стоит у пирсовых площадок, где торговые суда швартуются для погрузки и разгрузки.",al={"where is dizzywig","dizzywig location","find wharfmaster","где головокружилкинс","местонахождение головокружилкинса","найти начальника причала"}}},fp="20,318,27.420.0,23.454.1,28.227.0,38.218.0,44.222.0,57.194.0,40.209.1,38.145.0"}
P.entries["quest:893"] = {n="Предпочитаемое оружие",s="Таттернак Стальной Горн, кузнец Орды в Лагере Таурахо, проверяет сообщения о том, что южные свинобразы-Иглогривые изготавливают необычайно прочное вооружение. Получив от Вождя задание оценить эту угрозу, он привлекает путников, чтобы те добыли оружие у свинобразов за Полями Великанов. Изучение образцов показывает, что свинобразы гораздо опаснее и искуснее, чем сначала считала Орда.",h="Таттернак Стальной Горн, кузнец Орды в Лагере Таурахо, проверяет сообщения о том, что южные...",kw={"backstabber","barrens","quilboar","razormane","steelforge","tatternack","taurajo","wand","war shield","стилет","степи","свинобраз","иглогривые","стальной горн","таттернак","таурахо","жезл","боевой щит"},ang={["faction:Horde"]="Лагерь Таурахо остается уязвимым на южной границе, поэтому сведения о военных достижениях Иглогривых жизненно важны для защиты торговых путей через Степи.",["profession:Blacksmithing"]="Для кузнеца оценка добытого оружия показывает, как качество материалов врага напрямую определяет его боевую готовность на границе.",["race:Orc"]="Честь орков требует уважать воинскую силу, а долг Таттернака перед Траллом требует признавать, когда противник становится по-настоящему опасным."},sec={{t="Любопытный прогресс",b="Свинобразов Степей обычно считают дикими грубыми тварями, орудующими примитивными предметами из дерева, кости и камня. Однако в Лагерь Таурахо дошли слухи, что племя Иглогривых далеко на юге начало применять на удивление прочное боевое снаряжение. Таттернак Стальной Горн, орк-кузнец, действующий по приказу вождя Тралла, заинтересовался этими слухами. Хотя он сомневался, что свинобразы способны постичь настоящую металлургию, он искал доказательства того, что они освоили новые приемы или нашли лучшие материалы."},{t="Вооружение Иглогривых",b="Чтобы изучить их ремесло, Таттернаку требовался разнообразный срез арсенала племени. Он отправил разведчиков на юг, мимо колоссальных скелетов Полей Великанов, к военным лагерям Иглогривых. Там воинам предстояло отобрать стилеты у свинобразов-охотников, обугленные жезлы у провидцев и тяжелые боевые щиты у неистовых штурмовиков. Каждый предмет давал представление о военном и магическом искусстве, питающем нынешнее наступление Иглогривых на земли Орды."},{t="Недооценка врага",b="Взяв в руки добытые образцы, Таттернак из скептика превратился в обеспокоенного. Оружие демонстрировало такой уровень мастерства и прочности, который опровергал представления Орды о возможностях свинобразов. Признав, что Орда опасно недооценила племя, кузнец оставил работу в кузне, чтобы подробнее изучить материалы, подозревая, что Иглогривым помогает некий посторонний фактор или новый ресурс."}},faq={{q="Кто такой Таттернак Стальной Горн?",a="Таттернак Стальной Горн — орк-кузнец и оружейник из Лагеря Таурахо на юге Степей. Выполняя приказ вождя Тралла укреплять приграничную оборону Орды, он изучает вражеское оружие и изготавливает снаряжение для местных отрядов.",al={"tatternack steelforge","who gives weapons of choice","taurajo blacksmith","таттернак стальной горн","кто дает предпочитаемое оружие","кузнец таурахо"}},{q="Зачем Таттернаку оружие свинобразов?",a="Судя по сообщениям, южное племя Иглогривых начало использовать на удивление прочное оружие, хотя о традиции искусной ковки у них ничего не известно. Таттернак хочет изучить их кинжалы, жезлы и щиты, чтобы понять, как те изготавливаются и не представляют ли они возросшую угрозу.",al={"why collect quilboar weapons","reason for weapons of choice","tatternack motives","зачем собирать оружие свинобразов","причина предпочитаемого оружия","мотивы таттернака"}},{q="Где находятся свинобразы-Иглогривые для этого задания?",a="Нужные свинобразы живут в лагерях на дальнем юге Степей, за Полями Великанов и к западу от дороги, ведущей к Великому Подъемнику и в Тысячу Игл.",al={"where are the quilboar","weapons of choice location","where to find razormane","где свинобразы","предпочитаемое оружие расположение","где найти иглогривых"}},{q="У каких свинобразов находится нужное оружие?",a="Стилеты Иглогривых носят Охотники Иглогривых, обугленные жезлы Иглогривых держат Провидцы Иглогривых, а прочные боевые щиты Иглогривых — Неистовые Иглогривые.",al={"who drops backstabber","who drops wand","who drops war shield","с кого падает стилет","с кого падает жезл","с кого падает боевой щит"}},{q="Что Таттернак узнает из оружия?",a="Осмотрев предметы, Таттернак убеждается, что оружие сделано на удивление хорошо и намного превосходит ожидания Орды от свинобразов. Это заставляет его изучить сырье, которое они используют, в следующем задании «Образец новой руды».",al={"what does tatternack find out","weapons of choice outcome","are quilboar smiths","что выяснил таттернак","итог предпочитаемого оружия","есть ли кузнецы у свинобразов"}},{q="Почему Орду тревожит производство оружия свинобразами?",a="Орда полагается на превосходную металлообработку и дисциплинированную силу, чтобы удерживать обширные Степи от множества местных угроз. Если плодовитые свинобразы-Иглогривые смогут наладить массовое производство прочного железного или стального оружия, они легко сокрушат приграничные форпосты вроде Лагеря Таурахо.",al={"why do quilboar weapons matter","quilboar threat level","почему важно оружие свинобразов","уровень угрозы свинобразов"}}},fp="17,455,21.538.0,26.476.0,25.450.1,29.245.0,42.298.0,55.174.0,42.176.0,47.265.1,62.279.0"}
P.entries["quest:894"] = {n="Самофланж",s="По заказу гоблина-инженера Пароклапана из Кабестана искатели приключений отправляются на север, в исследовательский форпост Торговой Компании к юго-западу от Нефтяного болота. Их цель — найти загадочное устройство, известное лишь как самофланж. Вооружившись украденным руководством по эксплуатации, любознательный исследователь должен справиться с капризной панелью управления и извлечь устройство.",h="По заказу гоблина-инженера Пароклапана из Кабестана искатели приключений отправляются на север, в...",kw={"barrens","control console","goblin engineering","samophlange","sludge fen","sputtervalve","venture company","степи","панель управления","гоблинская инженерия","самофланж","нефтяное болото","пароклапан","торговая компания"},ang={["faction:Horde"]="Агрессивная эксплуатация и химические стоки Торговой Компании угрожают хрупкой экосистеме Степей, поэтому для местных защитников Орды сорвать работу ее объектов — насущная необходимость.",["profession:Engineering"]="Инженеры оценят одержимость Пароклапана чертежами конкурентов — она показывает беспощадный характер гоблинского промышленного шпионажа."},sec={{t="Странное устройство",b="Гоблины славятся тягой к новшествам, любопытством и жаждой прибыли, но даже механик Пароклапан озадачен последней новинкой, появившейся на раскопках Торговой Компании на севере Степей. Конкурирующая организация, работающая к юго-западу от Нефтяного болота, возится с устройством под названием самофланж. Не зная ни его точного назначения, ни возможной выгоды, Пароклапан стремится заполучить аппарат и изучить его устройство прежде, чем коммерческие соперники извлекут из него пользу."},{t="Проникновение на установку",b="Заполучить устройство непросто. Торговая Компания ревностно охраняет свои объекты: вокруг сооружения стоят вооруженные надсмотрщики, лесорубы и сложные механизмы. Пароклапан передает перехваченное руководство по эксплуатации, чтобы помочь безопасно отключить капризную установку. Добравшись до центрального пульта управления, исследователь обнаруживает хаотичное скопление рычагов, лампочек и датчиков, поддерживающих оптимальное давление в трех важнейших клапанах; пульт закрыт на замок."}},faq={{q="Что такое самофланж?",a="Даже Пароклапан не знает в точности, что это и для чего оно нужно. Это секретный экспериментальный механический узел, созданный Торговой Компанией на своем объекте к юго-западу от Нефтяного болота.",al={"what is a samophlange","samophlange purpose","what does a samophlange do","что такое самофланж","назначение самофланжа","что делает самофланж"}},{q="Кто такой Пароклапан?",a="Пароклапан — гоблин-инженер и механик, живущий в Кабестане. Заинтересовавшись коммерческими тайнами Торговой Компании, он нанимает искателей приключений, чтобы сорвать ее работы и завладеть ее технологическими достижениями.",al={"who is sputtervalve","sputtervalve location","quest giver","кто такой пароклапан","где пароклапан","персонаж, выдающий задание"}},{q="Где находится панель управления?",a="Панель находится внутри исследовательского объекта Торговой Компании к северу от Перекрестка, к юго-западу от загрязненного Нефтяного болота в Степях.",al={"console location","where is console","where to find samophlange","где панель управления","где консоль","где найти самофланж"}},{q="Почему Торговая Компания находится в Степях?",a="Торговая Компания — беспринципный картель, одержимый прибылью и эксплуатирующий природные ресурсы Калимдора. В Степях она вырубает леса, добывает нефть и строит экспериментальные установки, подобные тем, что стоят у Нефтяного болота.",al={"venture co barrens","why are venture co here","sludge fen operation","торговая компания степи","зачем здесь торговая компания","нефтяное болото установка"}},{q="Как безопасно отключить самофланж?",a="На панели управления есть три открытых клапана и замочная скважина. Следуя добытому руководству Пароклапана, можно обойти защитные замки и с помощью клапанов отсоединить модуль.",al={"how to use console","control console operating manual","manual instructions","как пользоваться панелью","руководство по эксплуатации","инструкция"}},{q="Работает ли Пароклапан на Торговую Компанию?",a="Нет. Пароклапан действует как независимый агент или соперник, стремящийся перехватить инженерные открытия Торговой Компании и присвоить их для собственного изучения.",al={"is sputtervalve venture co","sputtervalve faction","пароклапан торговая компания","фракция пароклапана"}}},fp="11,373,22.541.0,20.487.0,22.190.0,20.194.0,37.155.0,42.210.0,44.216.0,47.160.0"}
P.entries["quest:895"] = {n="РАЗЫСКИВАЕТСЯ: Барон Дольноберег",s="РАЗЫСКИВАЕТСЯ: Барон Дольноберег — контракт на награду за голову, вывешенный на пристани Кабестана главным инженером Газлоу. Цель — барон Дольноберег, известный пиратский капитан родом из Гилнеаса, командующий судами Флибустьеров Южных морей. Присутствие Дольноберега у Торгового побережья прямо угрожает торговому судоходству гоблинов во всем регионе.",h="РАЗЫСКИВАЕТСЯ: Барон Дольноберег — контракт на награду за голову, вывешенный на пристани Кабестана главным...",kw={"baron longshore","gazlowe","gilneas","heedless","merchant coast","pirate bounty","ratchet","southsea freebooters","барон дольноберег","газлоу","гилнеас","беспечный","торговое побережье","награда за пиратов","кабестан","флибустьеры южных морей"},ang={["faction:Alliance"]="Хотя Дольноберег родом из Гилнеаса, его пиратство мешает нейтральному судоходству между Калимдором и Восточными королевствами, на которое полагаются путники Альянса.",["faction:Horde"]="Разгром Флибустьеров Южных морей близ Кабестана сохраняет порт открытым и дружественным для снабжения Орды, идущего в Степи.",["race:Human"]="Гилнеасский барон, командующий головорезами в Калимдоре, напоминает о том, как далеко по морям разбросало дезертиров и изгоев Восточных королевств."},sec={{t="Пиратство у Торгового побережья",b="Воды у Степей — жизненно важные морские пути Картеля Хитрая Шестеренка, соединяющие Кабестан с Пиратской бухтой и дальше. К несчастью, Флибустьеры Южных морей укрепили лагеря на побережье к югу от города. Под началом таких фигур, как барон Дольноберег, эти головорезы грабят торговые суда, нарушают торговлю и истощают местную гоблинскую администрацию."},{t="Капитан из Гилнеаса",b="Дольноберег родом из уединенного человеческого королевства Гилнеас, поэтому его появление в Калимдоре — необычная и опасная странность. Капитан пиратского судна «Беспечный», он высаживает команды на берег чуть севернее Крепости Северной Стражи. Вместо большой дипломатии Газлоу решает проблему по-гоблински, практично: объявляет открытую награду за опознаваемую голову пирата."}},faq={{q="Кто такой барон Дольноберег?",a="Барон Дольноберег — пиратский капитан родом из Гилнеаса, который командует судном «Беспечный» на службе Флибустьеров Южных морей. Он действует на побережье к югу от Кабестана, нападая на морские пути.",al={"baron longshore","who is longshore","captain longshore","барон дольноберег","кто такой дольноберег","капитан дольноберег"}},{q="Почему Газлоу хочет его смерти?",a="Пиратство Дольноберега напрямую угрожает торговым судам Газлоу, выходящим из Кабестана. Чтобы торговля шла безопасно, а прибыль Хитрой Шестеренки была защищена, Газлоу назначил награду за голову Дольноберега.",al={"why kill longshore","gazlowe bounty reason","why is longshore wanted","зачем убивать дольноберега","причина награды газлоу","почему разыскивается дольноберег"}},{q="Где можно найти барона Дольноберега?",a="Он часто бывает в лагерях Флибустьеров Южных морей на Торговом побережье к югу от Кабестана, чуть севернее Крепости Северной Стражи.",al={"longshore location","where is longshore","baron longshore spot","где дольноберег","местонахождение дольноберега","где барон дольноберег"}},{q="Каким кораблем командует барон Дольноберег?",a="Он капитан «Беспечного» — грозного пиратского корабля, известного морякам в открытых водах у Торгового побережья.",al={"longshore ship","name of longshore boat","heedless ship","корабль дольноберега","название корабля дольноберега","беспечный корабль"}},{q="Дворянин ли барон Дольноберег из Альянса?",a="Хотя он носит титул барона и родом из Гилнеаса, он действует исключительно как корсар-изгой, возглавляющий Флибустьеров Южных морей, и не связан с нынешним руководством Альянса.",al={"is longshore alliance","gilneas noble pirate","longshore gilneas","дольноберег альянс","гилнеас дворянин пират","дольноберег гилнеас"}},{q="Где находится объявление о награде?",a="Объявление о розыске висит на доске возле банка в портовом городе Кабестан.",al={"where is wanted poster","longshore poster location","how to start longshore quest","где объявление о розыске","где объявление дольноберега","как начать задание дольноберега"}}},fp="23,350,28.382.0,22.405.0,23.193.0,31.209.0,35.129.0,39.116.0,37.188.0,35.84.0"}
P.entries["quest:896"] = {n="Удача шахтера",s="Управляющий пристанью Головокружилкинс из Кабестана узнает о необычайной находке в Каменном карьере Торговой Компании: изумруде размером с кулак. Не желая, чтобы безжалостный горнодобывающий синдикат нажился на нем, Головокружилкинс нанимает искателя приключений, чтобы тот похитил Изумруд «Кошачий Глаз» у надзирателей карьера за долю прибыли.",h="Управляющий пристанью Головокружилкинс из Кабестана узнает о необычайной находке в Каменном карьере Торговой...",kw={"boulder lode mine","cats eye emerald","dizzywig","enforcer","overseer","ratchet","sludge fen","venture co","каменный карьер","изумруд кошачий глаз","головокружилкинс","громила","надсмотрщик","кабестан","нефтяное болото","торговая компания"},ang={["class:Rogue"]="Пробраться во вражеский лагерь шахтеров и избавить жадных надсмотрщиков от тщательно охраняемого самоцвета — задача, где пригодятся все уловки разбойника.",["faction:Horde"]="Удар по руководству Торговой Компании в Каменном карьере подрывает работу напористого промышленного картеля, вторгшегося прямо в земли Степей, которые удерживает Орда.",["profession:Mining"]="Шахтеры оценят редкость целого изумруда размером с кулак — такой образец почти никогда не переживает добычу, не расколовшись и не треснув."},sec={{t="Глаза на пристани",b="Как портовый чиновник, управляющий оживленной гаванью между Кабестаном и Пиратской бухтой, Управляющий пристанью Головокружилкинс слышит почти все секреты, которые шепчут на торговых путях. Когда дошли слухи об огромном самоцвете размером с кулак, найденном глубоко в Каменном карьере, Головокружилкинс сразу увидел выгодную возможность. Безрассудная открытая добыча Торговой Компании на севере Степей не прибавляет ей друзей, а значит, мало кто стал бы задавать вопросы, если бы их лучшая недавняя находка тихо исчезла из их хранилища."},{t="Доля от добычи",b="Шахта с валунами к северо-востоку от Нефтяного болота кишит рабочими, но Головокружилкинс знал, что обычному копателю не позволят оставить такую редкую находку. Изумруд «Кошачий Глаз» быстро конфисковали надсмотрщики и громилы Торговой Компании, охраняющие это место. Чтобы вернуть самоцвет, нужно напрямую столкнуться с этими хорошо вооруженными начальниками, забрать камень и доставить его Головокружилкинсу, чтобы оценить по выгодным расценкам Подкопья."}},faq={{q="Кто такой Управляющий пристанью Головокружилкинс?",a="Управляющий пристанью Головокружилкинс — гоблин-портовый чиновник в Кабестане. Он следит за грузовым и пассажирским движением через море в Пиратскую бухту и обратно, а свое выгодное положение использует, чтобы торговать ценными сплетнями, слухами и сведениями купцов.",al={"dizzywig","who gives miners fortune","ratchet wharfmaster","головокружилкинс","кто дает удачу шахтера","начальник причала кабестана"}},{q="Где находится Каменный карьер?",a="Каменный карьер находится на севере Степей, в холмах к северо-востоку от пропитанного нефтью промышленного объекта у Нефтяного болота.",al={"boulder lode mine location","where is the emerald","venture co mine barrens","где каменный карьер","где изумруд","шахта торговой компании степи"}},{q="У кого в шахте находится Изумруд «Кошачий Глаз»?",a="Самоцвет забрали начальники этого места, а не рядовые рабочие. Его можно добыть, победив надсмотрщиков и громил Торговой Компании, которые руководят добычей и охраняют ее в Каменном карьере и вокруг него.",al={"who drops cats eye emerald","cats eye emerald drop","where is cats eye emerald","у кого изумруд кошачий глаз","изумруд кошачий глаз добыча","где изумруд кошачий глаз"}},{q="Чем интересны Степи Торговой Компании?",a="Торговая Компания — агрессивный, бесконтрольный гоблинский торговый синдикат, нацеленный лишь на быструю эксплуатацию ресурсов. На севере Степей она ведет разрушительное бурение у Нефтяного болота и интенсивные раскопки в Каменном карьере, добывая древесину, нефть и минералы без оглядки на местную экологию.",al={"why is venture co in barrens","venture company barrens","почему торговая компания в степях","торговая компания степи"}},{q="Почему Головокружилкинс упоминает Подкопье?",a="Подкопье — подземный островной мегаполис и древняя столица гоблинских картелей. Как главный экономический и торговый центр гоблинов, его рынки определяют текущие цены на драгоценные камни и редкие товары по всему Азероту.",al={"undermine mention","gem rates undermine","подкопье","цены на самоцветы подкопье"}},{q="Делится ли Головокружилкинс прибылью на самом деле?",a="Верный своему гоблинскому понятию о деловой этике, Головокружилкинс выполняет уговор и выплачивает вам обещанные пятьдесят процентов от оценочной стоимости на рынке Подкопья после доставки Изумруда «Кошачий Глаз».",al={"does dizzywig split 50 50","dizzywig payout","делит ли головокружилкинс пополам","выплата головокружилкинса"}}},fp="15,333,17.524.0,17.472.0,28.262.0,39.168.0,43.248.0,54.326.0,38.241.0,41.196.1"}
P.entries["quest:897"] = {n="Жнец",s="Жнец — задание, которое начинается с находки отрубленной головы странного чужеродного хищника-насекомого на юге Степей. Доставка этого тревожного образца Джорну Заклинателю Небес в Лагере Таурахо раскрывает пугающие последствия для духовного и экологического равновесия этих земель.",h="Жнец — задание, которое начинается с находки отрубленной головы странного чужеродного хищника-насекомого на...",kw={"barrens","camp taurajo","harvester","harvester's head","insectoid","jorn skyseer","silithid","степи","лагерь таурахо","жнец","голова жнеца","насекомое","джорн заклинатель небес","силитид"},ang={["class:Druid"]="Друиды, изучающие возрождение Калимдора, сразу замечают порчу и паразитическую природу этих чужеродных землероев, вторгшихся в саванну.",["class:Shaman"]="Шаманы отметят досаду Джорна Заклинателя Небес из-за того, что дух покинул голову: это не позволило пообщаться со стихиями и узнать истинное происхождение существа.",["faction:Horde"]="Лагерь Таурахо служит южным щитом Орды в Степях, поэтому любой хищник-чужак на окрестных утесах — серьезная угроза безопасности.",["race:Tauren"]="Для Шу'хало поддержание гармонии Матери-Земли превыше всего; встреча с существом, нарушающим природный порядок, говорит о глубоком духовном разладе."},sec={{t="Неестественный пришелец",b="Среди саванн южных Степей путники порой натыкаются на тревожное зрелище: отрубленную голову силитида, известного как Жнец. В отличие от местных львов, ящеров и кодо, бродящих по равнинам, это хитиновое насекомое кажется совершенно чуждым природному порядку Калимдора. Его появление говорит о наступлении чужеродной экологии, которой нет места на открытых равнинах."},{t="Предчувствие Джорна Заклинателя Небес",b="Получив голову существа в Лагере Таурахо, мистик-таурен Джорн Заклинатель Небес осматривает останки. Дух твари уже покинул ее, поэтому он не может определить ее происхождение, но сразу понимает, что она представляет серьезную угрозу. Джорн опасается, что вторжение этого существа в Степи может предвещать мрачное будущее для Орды, и предупреждает, что под песками зреют более темные тайны."}},faq={{q="Что такое Жнец?",a="Жнец — крупный силитид-насекомое, бродящее по югу Степей. Его хитиновое чужеродное строение полностью отличается от местной фауны.",al={"who is the harvester","what kind of bug is the harvester","harvester creature","кто такой жнец","что за жук жнец","существо жнец"}},{q="Кто такой Джорн Заклинатель Небес?",a="Джорн Заклинатель Небес — уважаемый старейшина и духовный наставник таурен в Лагере Таурахо. Он следит за духовным здоровьем равнин и дает советы, когда что-либо угрожает равновесию земли.",al={"jorn skyseer","who is the turn in npc","jorn taurajo","джорн заклинатель небес","кому сдавать задание","джорн таурахо"}},{q="Откуда взялся Жнец?",a="Хотя Джорн Заклинатель Небес не может определить его точное происхождение по одной отрубленной голове, это отпрыск ульев силитидов, расползающихся вверх из глубоких пустынь на юге.",al={"where do silithid come from","harvester origin","silithid source","откуда берутся силитиды","происхождение жнеца","источник силитидов"}},{q="Почему существо тревожит Джорна Заклинателя Небес?",a="Неестественный облик и чуждый дух существа глубоко тревожат Джорна. Он чувствует, что его появление в Степях не случайно, а является зловещим предупреждением о надвигающейся неестественной угрозе.",al={"why is jorn worried","jorn skyseer reaction","grim future","почему джорн встревожен","реакция джорна заклинателя небес","мрачное будущее"}},{q="Как начать это задание?",a="Задание начинается с убийства редкого силитида по имени Жнец на юге Степей и добычи его отрубленной головы, после чего вы отправляетесь за советом к старейшинам Лагеря Таурахо.",al={"how to get quest","harvester head drop","start harvester","как получить задание","голова жнеца добыча","начать жнеца"}},{q="Что Джорн велит вам делать дальше?",a="Джорн не предлагает немедленного ответного удара: он понимает, что Орде сначала нужно подготовиться и сохранять бдительность, пока тайна наступающих силитидов медленно раскрывается.",al={"follow up quest","what after harvester head","jorn next step","следующее задание","что после головы жнеца","дальнейшие действия джорна"}}},fp="13,277,21.396.0,26.406.1,22.183.0,20.203.0,35.172.0,43.195.0,28.188.0,35.176.0"}
P.entries["quest:898"] = {n="Свобода!",s="Свобода! — сопровождение в Степях: авантюристы Орды спасают Гилтареса Огненного Цветка из плена у людей в Крепости Северной Стражи. Эльф-матрос, захваченный после того, как его транспорт перехватили и потопили, ищет дерзкого побега, чтобы воссоединиться со своим капитаном в Кабестане.",h="Свобода!",kw={"booty bay","captain brightsun","escort","gilthares firebough","moonshine","northwatch hold","privateers","ratchet","smuggler","theramore","пиратская бухта","капитан сияющий","сопровождение","гилтарес огненный цветок","самогон","крепость северной стражи","каперы","кабестан","контрабандист","терамор"},ang={["faction:Horde"]="Глубокий удар по Крепости Северной Стражи ради освобождения пленного контрабандиста — еще один приятный выпад против военного плацдарма Терамора на побережье Степей."},sec={{t="В плену у Северной Стражи",b="Крепость Северной Стражи — военный авангард Терамора на побережье Степей, бдительный и агрессивный к любой предполагаемой угрозе. Эта подозрительность коснулась и Гилтареса Огненного Цветка. Его корабль, перевозивший самогон по торговому пути между Кабестаном и Пиратской бухтой, был обстрелян силами Альянса и отправлен на дно. Как единственного выжившего, поднятого из обломков, Гилтареса бросили в темницы Северной Стражи, обвинив в том, что он вражеский агент, злоумышляющий против Альянса."},{t="Побег контрабандиста",b="Хотя тюремщики выставляют его опасным диверсантом, Гилтарес уверяет, что он всего лишь скромный матрос, которого поймали с запрещенным спиртным. С помощью сил Орды, готовых ударить по Северной Страже, он отчаянно рвется на свободу: прорывается из крепости и бежит на север вдоль побережья в Кабестан. Там капитан Тало'тас Сияющий принимает вернувшегося члена команды обратно в ряды каперов Тало'дана."}},faq={{q="Кто такой Гилтарес Огненный Цветок?",a="Гилтарес Огненный Цветок — эльф-матрос под началом капитана Тало'таса Сияющего. Он служил на транспорте, перевозившем самогон между Кабестаном и Пиратской бухтой, пока войска Терамора не потопили его судно и не заковали его в цепи.",al={"gilthares","who is gilthares firebough","who is the prisoner in northwatch hold","гилтарес","кто такой гилтарес огненный цветок","кто пленник в крепости северной стражи"}},{q="Почему силы Терамора арестовали Гилтареса?",a="Солдаты Альянса из Крепости Северной Стражи перехватили его корабль у побережья Степей и потопили. Из крайней настороженности ко всем судам возле их твердыни гарнизон счел корабль с самогоном враждебным, а Гилтареса объявил лазутчиком, враждебным Альянсу.",al={"why did theramore arrest him","why is gilthares in jail","why was the ship sunk","почему терамор арестовал его","почему гилтарес в тюрьме","почему потопили корабль"}},{q="Куда направляется Гилтарес после освобождения?",a="Гилтарес бежит на север из Крепости Северной Стражи вдоль восточного побережья Степей, пока не достигает нейтрального гоблинского порта Кабестан. Там он вновь встречается с капитаном Сияющим у причалов.",al={"where to escort gilthares","gilthares destination","where does the escort go","куда сопровождать гилтареса","цель гилтареса","куда идти в сопровождении"}},{q="Кто такие каперы Тало'дана?",a="Каперы Тало'дана — морская команда под началом капитана Тало'таса Сияющего, действующая из Кабестана. Они занимаются перевозками и незаконной контрабандой, в том числе провозят самогон через море между Калимдором и Восточными королевствами.",al={"thalodan privateers","captain brightsun crew","who does brightsun lead","каперы тало'дана","команда капитана сияющего","кем командует сияющий"}},{q="Почему Крепость Северной Стражи нападает на гражданские и контрабандистские суда?",a="Крепость Северной Стражи служит оплотом Терамора в Степях и расположена прямо между землями Орды и важными морскими путями. Повышенная подозрительность и строгие военные приказы заставляют ее командиров видеть почти в любом небоевом судне не из Альянса вражескую операцию Орды или угрозу пиратов.",al={"why is northwatch hostile","theramore aggression barrens","northwatch hold purpose","почему северная стража враждебна","агрессия терамора в степях","назначение крепости северной стражи"}},{q="Какой груз вез затонувший корабль?",a="Судно везло партию запрещенного самогона для распространения между Кабестаном и Пиратской бухтой, а не оружие или военные припасы.",al={"what was on the ship","gilthares cargo","what were they transporting","что было на корабле","груз гилтареса","что они перевозили"}}},fp="18,279,24.492.0,19.448.0,27.223.0,47.318.0,35.200.1,33.246.0,60.290.0,40.148.0"}
P.entries["quest:899"] = {n="Огонь ненависти",s="Огонь ненависти — мрачное задание, которое дает Манкрик на Перекрестке в Степях. Терзаемый яростной засадой, разлучившей его с женой, скорбящий орк направляет свою мучительную неизвестность в неустанную месть свинобразам-дыбогривам. Он призывает путников Орды истреблять этих тварей толпами и принести огромное количество их бивней.",h="Огонь ненависти — мрачное задание, которое дает Манкрик на Перекрестке в Степях.",kw={"barrens","bristleback","consumed by hatred","crossroads","mankrik","quilboar","taurajo","tusks","степи","дыбогрив","огонь ненависти","перекресток","манкрик","свинобраз","таурахо","бивни"},ang={["class:Warrior"]="Воин знает, что рану в сердце не всегда можно перевязать, и единственное средство Манкрика — встречать сталь сталью на колючих равнинах.",["faction:Horde"]="Свинобразы угрожают важным путям между Дуротаром, Мулгором и Южными степями, поэтому личный поход Манкрика напрямую служит защите земель Орды.",["race:Orc"]="Горе Манкрика и неукротимое стремление отомстить за павших сородичей глубоко созвучны традиционной орочьей чести и суровой действительности устройства дома в Калимдоре."},sec={{t="Отец мщения",b="Под палящим солнцем Перекрестка Манкрик — воин, одержимый горем. Пережив жестокий налет свинобразов, после которого он остался изувеченным, а жена пропала, он проводит дни, высматривая на засушливом горизонте хоть какой-то след свиноликих. Его жажда их крови остается неутоленной, хотя он лично убил многих, и это побуждает его просить помощи у соратников по Орде."},{t="Бивни дыбогривов",b="Вместо мира или утешения Манкрик требует трофеев чистой резни: шестьдесят бивней свинобразов-дыбогривов. Для него каждый сломанный бивень — мера страдания, возвращенного чудовищам, разрушившим его жизнь. Груды костей не излечат его горе и не утолят жажду возмездия, но вид кровоточащих дыбогривов приносит раненому воину мимолетное горькое удовлетворение."}},faq={{q="Почему Манкрик хочет шестьдесят бивней свинобразов?",a="Манкрика целиком поглотили горе и гнев после жестокой засады свинобразов, разлучившей его с женой. Шестьдесят бивней — намеренно жестокое число, призванное нанести племени дыбогривов тяжелые потери и принести ему хоть малое утешение при виде страданий мучителей.",al={"why 60 tusks","mankrik tusks quest","why so many tusks","почему 60 бивней","задание манкрика про бивни","почему так много бивней"}},{q="Где происходит это задание?",a="Манкрик выдает это задание на Перекрестке в центральных Степях и посылает авантюристов против свинобразов-дыбогривов, обитающих в окрестных зарослях и колючих укреплениях.",al={"where is consumed by hatred","consumed by hatred location","где огонь ненависти","огонь ненависти местонахождение"}},{q="Утоляет ли месть Манкрика сдача бивней?",a="Не совсем. Манкрик признает, что хотя жажда мести остается неутоленной, вид тяжелых потерь свинобразов вызывает у него мрачную улыбку: они наконец ощутили его боль.",al={"does mankrik stop hating quilboar","mankrik quest ending","перестанет ли манкрик ненавидеть свинобразов","конец задания манкрика"}},{q="Почему Манкрик упоминает Лагерь Таурахо?",a="В горьких раздумьях Манкрик гадает, не следовало ли после засады бежать на юг, к Лагерю Таурахо, а не на север, к Перекрестку, и задается вопросом, были бы исход битвы и его поиски иными.",al={"why taurajo","camp taurajo mankrik","почему таурахо","лагерь таурахо манкрик"}},{q="Кто такие дыбогривы?",a="Дыбогривы — агрессивное племя свинобразов, коренных жителей Степей. Крайне территориальные и враждебные к чужакам, они постоянно сражаются с Ордой и нападают на путников на равнинах из своих окруженных колючками лагерей.",al={"what are bristlebacks","bristleback tribe","кто такие дыбогривы","племя дыбогривов"}},{q="Связано ли это с поисками жены Манкрика?",a="Yes. Mankrik's burning hatred stems directly from the ambush where he and his wife were overwhelmed. While adventurers scour the plains trying to discover her fate in the companion quest 'Lost in Battle', this mission represents his sheer desire to retaliate against her attackers.",al={"lost in battle connection","mankriks wife quest","связь с потерянной в бою","задание о жене манкрика"}}},fp="18,377,21.412.0,24.400.0,43.295.0,33.179.0,52.216.0,38.229.0,25.226.0,44.281.0"}
P.entries["quest:9"] = {n="Поля смерти",s="Поля смерти — задание Альянса, которое дает фермер Сальден в Западном Крае. Сальден поручает авантюристам уничтожить взбесившихся Стражей урожая, наводнивших его поля и соседние фермы. Оно показывает упадок местного земледелия после смуты, устроенной Братством Справедливости.",h="Поля смерти — задание Альянса, которое дает фермер Сальден в Западном Крае.",kw={"clockwork","defias","farmer saldean","harvest watchers","killing fields","saldean's farm","scarecrows","westfall","заводные","братство справедливости","фермер сальден","стражи урожая","поля смерти","ферма сальдена","пугала","западный край"},ang={["faction:Alliance"]="Для путников Альянса помощь Сальдену — прямое усилие по защите одного из немногих уцелевших источников продовольствия на земле, брошенной штормградской короной.",["profession:Engineering"]="Инженеры узнают в Стражах урожая автоматические заводные чудеса, сошедшие с ума без должного обслуживания."},sec={{t="Осажденная усадьба",b="Пока многие фермеры Западного Края бросили свои земли, когда по региону прокатились бандиты и преступники, фермер Сальден с семьей решил остаться. Но не одни воры-захватчики губят ферму Сальдена. Механические Стражи урожая, призванные ухаживать за зерном и охранять его, взбесились, бродят по бороздам и нападают на всех, кто приближается."},{t="Очистка земли",b="Чтобы сохранить ферму, Сальден нанимает проходящих путников разобрать двадцать враждебных автоматонов на его полях и соседних участках. Уничтожение этих созданий дает урожаю Сальдена временную передышку и сохраняет редкий островок упрямой надежды, что житница Западного Края когда-нибудь будет возвращена."}},faq={{q="Кто дает задание «Поля смерти»?",a="Фермер Сальден дает задание на Ферме Сальдена, расположенной у дороги в центральной части Западного Края.",al={"quest giver killing fields","who gives the killing fields","saldean quest","выдающий задание поля смерти","кто дает поля смерти","задание сальдена"}},{q="Кто такие Стражи урожая?",a="Стражи урожая — заводные пугала, созданные ухаживать за посевами и охранять поля от вредителей. После смуты и запустения Западного Края многие из этих механизмов остались без присмотра или были перепрограммированы и яростно обратились против самих фермеров, которым должны были служить.",al={"what are harvest watchers","harvest watcher lore","mechanical scarecrows westfall","что такое стражи урожая","стражи урожая предания","механические пугала западный край"}},{q="Почему фермер Сальден не бежал из Западного Края, как остальные?",a="В отличие от соседей, бросивших усадьбы ворам и разбойникам, Сальден отказывается сдавать свой источник жизни. Он упрямо удерживает участок с помощью нанятых авантюристов, отражая взбесившиеся механизмы.",al={"why is saldean still here","farmer saldean lore","saldean staying","почему сальден остался","фермер сальден предания","сальден не уходит"}},{q="Каковы цели задания «Поля смерти»?",a="Вам поручено уничтожить двадцать Стражей урожая, бродящих по полям Сальдена и окрестным заброшенным фермам.",al={"killing fields objective","how many harvest watchers","what to kill for killing fields","цель поля смерти","сколько стражей урожая","кого убивать для поля смерти"}},{q="Кто такие «воры», о которых говорит Сальден?",a="Сальден имеет в виду воров и разбойников, свободно объединенных в Братство Справедливости, чьи набеги и вымогательство вынудили большинство поселенцев покинуть свои земли.",al={"who are the thieves","saldean thieves","who drove farmers out westfall","кто такие воры","воры сальдена","кто прогнал фермеров из западного края"}},{q="Решает ли выполнение этого задания проблемы земледелия Западного Края?",a="Уничтожение двадцати Стражей урожая дает ферме Сальдена немедленную передышку, но общая угроза бандитов и сломанные механизмы по всему региону остаются нерешенными.",al={"does westfall recover","killing fields ending","saldean outcome","оправится ли западный край","конец поля смерти","исход сальдена"}}},fp="18,302,23.401.0,17.315.0,40.96.0,26.284.0,57.217.0,46.122.0,39.162.0,59.192.0"}
P.entries["quest:90"] = {kw={"chef grual","darkshire","duskwood","felicia gump","fragrant flowers","lean wolf flank","scarlet raven tavern","stormwind","wolf kabobs","шеф-повар груаль","темнолесье","сумеречный лес","фелиция гамп","благоуханные цветы","постное волчье мясо","таверна алый ворон","штормград","котлеты из волчатины"},ang={["class:Hunter"]="Выслеживание голодных волчьих стай Сумеречного леса требует классических навыков следопыта и истребления, чтобы защитить деревушку и пополнить кладовую таверны.",["faction:Alliance"]="Поездка между Темнолесьем и Штормградом показывает, как изолированные поселения королевства зависят от рынков столицы, даже когда гарнизоны не присылают.",["profession:Cooking"]="Рецепт Шеф-повара Груаля учит искателей приключений, как охотники глуши используют жесткое мясо хищников, маскируя дикий привкус дичи изысканными городскими пряностями."},sec={{t="Блюдо для Темнолесья",b="Темнолесье — изолированное поселение, окруженное ползучими ужасами Сумеречного леса, куда торговые караваны заглядывают редко, а обычное земледелие полностью пришло в упадок. Несмотря на постоянный мрак и подстерегающую нежить, жителям города по-прежнему нужна пища. Шеф-повар Груаль, заведующий кухней таверны «Алый ворон», с пользой применяет опасную лесную фауну: превращает мясо диких волков в сытные шашлычки. Поскольку местная древесина и почва не позволяют растить нежные культуры, Груаль полагается на особые пряности, привозимые из столицы, чтобы сделать дичину съедобной."},{t="Дорога в Штормград",b="Чтобы завершить рецепт Груаля, путникам нужно добыть постное мясо свирепых волков, рыскающих по Сумеречному лесу, и отправиться на север, в Штормград. Пряные травы продает травница и цветочница Фелиция Гамп, чья лавка «Благоуханные цветы» стоит у канала на границе Торгового квартала и Старого города. Это поручение подчеркивает хрупкую связь Темнолесья с остальным королевством: хотя военная помощь короны иссякла, небольшие гражданские связи и поставки между городскими торговцами и дальними деревушками все еще едва держатся."}},faq={{q="Кто такой Шеф-повар Груаль?",a="Шеф-повар Груаль — городской повар таверны «Алый ворон» в Темнолесье. Он кормит посетителей, местных жителей и бойцов Ночного Дозора, готовя сытные блюда из любой дичи, которую можно добыть в окрестных лесах.",al={"chef grual","grual darkshire","who gives seasoned wolf kabobs"}},{q="Где взять штормградские пряные травы?",a="Пряные травы продает Фелиция Гамп, хозяйка лавки «Благоуханные цветы» в Штормграде. Ее лавка стоит на пути вдоль канала между Торговым кварталом и Старым городом.",al={"stormwind herbs location","felicia gump location","where are seasoning herbs","где штормградские травы","где фелиция гамп","где пряные травы"}},{q="Где найти волков для волчьего мяса?",a="Дикие волки бродят по темным чащам Сумеречного леса, особенно возле рощ и троп неподалеку от Темнолесья. Мясо любого местного волка подойдет Шеф-повару Груалю.",al={"lean wolf flank location","wolf flanks duskwood","where to hunt wolves","постное волчье мясо","волки сумеречный лес","где охотиться на волков"}},{q="Почему Темнолесью нужно волчье мясо?",a="Пашни Сумеречного леса разорены и отрезаны чудовищами, поэтому скотоводство и земледелие там практически невозможны. Местные выживают охотой на опасных зверей за пределами поселения, в том числе на вездесущих волков.",al={"why eat wolves","darkshire food supply","why wolf kabobs","зачем есть волков","еда темнолесья","зачем волчьи шашлычки"}},{q="Почему Груаль не может найти травы в Сумеречном лесу?",a="Всепроникающее проклятие Сумеречного леса извратило большую часть местных растений, и съедобных или ароматных кулинарных трав почти не осталось. Груалю приходится полагаться на культурные сорта, привозимые из Штормграда, чтобы приправлять блюда.",al={"why buy herbs in stormwind","duskwood herbs","почему травы в штормграде","травы сумеречного леса"}},{q="Связано ли это задание с большим сюжетом?",a="Это самостоятельное местное задание, а не часть большого повествования. Однако оно наглядно показывает простой, независимый уклад жителей Темнолесья и их непрочную связь со Штормградом.",al={"wolf kabobs lore significance","is seasoned wolf kabobs important","значение пряных котлет из волчатины","важно ли задание про волчатину"}}},fp="20,399,20.603.0,21.527.0,18.221.0,47.194.0,47.192.0,43.244.0,46.232.0,44.221.0"}
P.entries["quest:900"] = {n="Самофланж",s="Это задание требует остановить сложный механизм, питающий буровые работы Торговой Компании на севере Степей. Перекрыв три отдельных клапана, искатели приключений смогут безопасно отключить главный аппарат. Закрытие клапанов прекращает опасный поток топлива и давления, поддерживающий работу машины.",h="Это задание требует остановить сложный механизм, питающий буровые работы Торговой Компании на севере Степей.",kw={"barrens","control console","fuel valve","regulator valve","samophlange","sludge fen","venture company","степи","пульт управления","топливный клапан","регуляторный клапан","самофланж","нефтяное болото","торговая компания"},ang={["faction:Horde"]="Остановка машин Торговой Компании защищает север Степей от безудержной промышленной эксплуатации.",["profession:Engineering"]="Инженеры узнают классическую гоблинскую конструкцию: мощные, нестабильные топливные магистрали с минимумом автоматической защиты, требующие ручного отключения, чтобы избежать катастрофического обратного удара давления."},sec={{t="Укрощение аппарата",b="Механизмы Торговой Компании в Нефтяном болоте так же опасны, как и сложны. Перед главным пультом управления по шкалам и индикаторам ясно, что основной механизм нельзя просто выключить щелчком переключателя. Чтобы избежать взрыва или поломки, сначала нужно вручную перекрыть питающие магистрали."},{t="Три клапана",b="Поток в установку регулируют три клапана: главный управляющий клапан, топливный управляющий клапан и регуляторный клапан. Каждый нужно вручную закрыть против высокого давления. По мере закрытия клапанов светящиеся индикаторы на пульте меняют цвет с зеленого на желтый, и наконец центральный выключатель можно безопасно задействовать."}},faq={{q="Зачем нужно перекрывать эти клапаны?",a="Пульт следит за давлением и топливными магистралями, идущими к машине. Попытка выключить аппарат при открытых магистралях могла бы повредить установку или привести к катастрофе, поэтому топливную, регуляторную и главную линии нужно предварительно перекрыть.",al={"why shut valves","samophlange valves purpose","what do valves do","зачем закрывать клапаны","назначение клапанов самофланж","что делают клапаны"}},{q="Что происходит, когда все три клапана закрыты?",a="Закрытие трех клапанов снижает внутреннее давление и отсекает топливо. Мигающие индикаторы на пульте тускнеют и меняют цвет с зеленого на желтый, и главный выключатель наконец начинает двигаться свободно.",al={"console lights","valves closed what next","огни пульта","клапаны закрыты что дальше"}},{q="Кто построил эту машину?",a="Аппарат построила Торговая Компания — безжалостный торговый картель гоблинов, добывающий нефть и сырье на севере Степей.",al={"who made the samophlange","venture co machine","кто сделал самофланж","машина торговой компании"}},{q="Где находятся клапаны?",a="Три клапана расположены вокруг главного пульта управления и основного оборудования на месте раскопок Торговой Компании в Степях.",al={"valve location","where are the valves","расположение клапанов","где клапаны"}},{q="Почему Орда интересуется этим устройством?",a="Тяжелая промышленность Торговой Компании вредит Степям и посягает на земли Орды. Изучение и саботаж их технологий помогает обуздать их разрушительную эксплуатацию.",al={"why does horde care","horde samophlange","почему орду это волнует","орда самофланж"}},{q="Что такое самофланж?",a="Самофланж — малопонятная техническая гоблинская деталь, точное внутреннее назначение которой редко понимают не инженеры, хотя она, судя по всему, необходима для буровой техники высокого давления.",al={"samophlange meaning","what is a samophlange","значение самофланж","что такое самофланж"}}},fp="11,332,20.338.0,16.339.0,49.249.0,46.213.0,23.146.0,29.146.0,43.176.0,22.189.0"}
P.entries["quest:901"] = {n="Самофланж",s="Это задание — ключевой шаг в остановке механизмов Торговой Компании в Нефтяном болоте на севере Степей. Уже перекрыв окружающие клапаны, исполнитель должен получить ключ от терминала у ремонтника Угрелова, чтобы открыть главный блок управления и извлечь загадочный самофланж.",h="Это задание — ключевой шаг в остановке механизмов Торговой Компании в Нефтяном болоте на севере Степей.",kw={"barrens","console key","samophlange","sludge fen","sniggles","venture company","степи","ключ от терминала","самофланж","нефтяное болото","угрелов","торговая компания"},ang={["faction:Horde"]="Саботаж оборудования Торговой Компании в Нефтяном болоте помогает замедлить их эксплуатацию и токсичные стоки на севере Калимдора.",["profession:Engineering"]="Тонкий процесс успокоения датчиков установки перед вскрытием корпуса демонстрирует привычные, хотя и странные, гоблинские правила механической безопасности."},sec={{t="Отпирание механизма",b="Прежде чем основную деталь можно будет извлечь, механизм нужно полностью обесточить и отпереть. Когда вспомогательные клапаны закрыты, а давление сброшено, шкалы и датчики терминала переходят в состояние покоя. Однако сам корпус остается плотно запертым для защиты от саботажа, и нужен физический ключ, который хранит главный гоблин-инженер, надзирающий за местом буровых работ."},{t="Ремонтник Угрелов",b="Торговая Компания поручает ремонтнику Угрелову следить за хрупким равновесием промышленного оборудования в Нефтяном болоте. Угрелов держит ключ от терминала при себе в ближайшей хижине к северо-востоку от главной установки. Победа над инженером — последнее препятствие между исполнителем и самофланжем внутри корпуса."},{t="Сброс питания",b="Поворот ключа Угрелова в пульте отпирает запертый корпус. С последним щелчком красный сигнальный маяк на раме гаснет, а затихающий электрический гул полностью смолкает. Защитные механизмы пульта отключаются, и внутренняя деталь становится доступной для извлечения."}},faq={{q="Где находится ремонтник Угрелов?",a="Ремонтник Угрелов находится в небольшой гоблинской хижине к северо-востоку от главного пульта управления в Нефтяном болоте на севере Степей.",al={"find sniggles","sniggles location","where is tinkerer sniggles","найти угрелова","где угрелов","где ремонтник угрелов"}},{q="Для чего нужен Ключ от терминала?",a="Ключ от терминала отпирает главный терминал управления в Нефтяном болоте и выводит из системы остаточное питание, чтобы можно было извлечь самофланж.",al={"console key use","what does key open","how to use console key","применение ключа от терминала","что открывает ключ","как использовать ключ от терминала"}},{q="Почему пульт нужно было отключить перед использованием ключа?",a="Сначала механизм нужно было перевести в состояние покоя, стравив давление через клапаны аппарата. Отпирать и трогать механизм под полным рабочим давлением было бы опасно.",al={"why shut down first","valves before key","почему сначала отключить","клапаны перед ключом"}},{q="На кого работает ремонтник Угрелов?",a="Ремонтник Угрелов — инженер на службе Торговой Компании, безжалостного торгового и добывающего конгломерата, разоряющего север Степей.",al={"sniggles faction","is sniggles venture co","фракция угрелова","угрелов торговая компания"}},{q="Что такое самофланж?",a="Самофланж — малопонятная сложная инженерная деталь, жизненно важная для работы тяжелой бурильной и насосной техники Торговой Компании.",al={"what does samophlange mean","what is a samophlange","что значит самофланж","что такое самофланж"}},{q="Что происходит после использования ключа на пульте?",a="Отпирание терминала полностью обесточивает пульт, предупредительные огни гаснут, и вы можете извлечь сам самофланж.",al={"what happens next","after console key","что дальше","после ключа от терминала"}}},fp="11,304,23.388.0,17.362.0,11.283.1,35.140.0,33.155.0,62.185.0,36.154.0,22.145.0,48.138.0"}
P.entries["quest:903"] = {n="Хищники Степей",s="«Хищники Степей» — охотничье испытание, которое выдает Сергра Черный Шип на Перекрестке. В рамках цепочки заданий, проверяющих боевое мастерство искателя приключений, охотникам поручено выслеживать хищников саванны, прячущихся в высокой траве прерий. Принесенные когти доказывают, что охотник достоин сразиться с величайшими зверями равнин.",h="«Хищники Степей» — охотничье испытание, которое выдает Сергра Черный Шип на Перекрестке.",kw={"crossroads","echeyakee","hunting","prowler claws","prowlers","savannah prowler","sergra darkthorn","the barrens","перекресток","ичияки","охота","когти хищника саванны","хищники","хищник саванны","сергра черный шип","степи"},ang={["class:Hunter"]="Выслеживание хищников саванны в высоких зарослях дает необходимую подготовку в отслеживании, обнаружении скрытых целей и усмирении агрессивных хищных кошек.",["faction:Horde"]="Усмирение дикой природы вокруг Перекрестка обеспечивает безопасный проход обозам со снабжением между Дуротаром, Мулгором и южными форпостами.",["race:Tauren"]="Пусть это и кровавое дело, истребление взбесившихся хищников чтит природное равновесие и защищает уязвимые караваны, идущие по исконным охотничьим землям."},sec={{t="Настоящий хищник",b="Проявив себя в схватках с пугливыми бегунами и упрямыми жеврами равнин, охотники, ищущие одобрения Сергры Черный Шип, сталкиваются с более опасным испытанием. Хищники саванны — высшие охотники центральных Степей, сливающиеся с золотисто-охристыми зарослями к юго-западу от Перекрестка. В отличие от пасущихся стадных животных, эти большие кошки охотятся расчетливо: нападают на добычу из высокой травы и превращают неосторожных путников в жертв."},{t="Хищник или добыча",b="Сергра Черный Шип подчеркивает риск охоты на зверей, для которых охота — ремесло. Чтобы добыть лапы и когти, искатель приключений должен научиться читать траву и наносить удар раньше, чем кошка прыгнет. Семь когтей хищника доказывают, что охотник обладает хитростью и реакцией, необходимыми, чтобы выжить при встречах с самыми опасными зверями Калимдора."},{t="На пути к чемпиону",b="Возвращение с горстью когтей подтверждает, что охотник освоил основы выживания в открытой саванне. Довольная проявленным боевым мастерством, Сергра готовит охотника к испытанию истинной доблести: призвать и убить Ичияки, белого льва, почитаемого как чемпион среди хищников Степей."}},faq={{q="Кто дает это задание на охоту?",a="Сергра Черный Шип, опытная орчанка-охотница, служащая на Перекрестке в Степях, дает это задание в рамках традиционной череды охотничьих испытаний.",al={"quest giver","who gives prowlers quest","sergra darkthorn","персонаж, выдающий задания","кто дает задание хищники","сергра черный шип"}},{q="Где находятся хищники саванны?",a="Они выслеживают добычу в высокой траве к юго-западу от Перекрестка, сливаясь с прериями, где охотятся на жевр и неосторожных путников.",al={"where are prowlers","prowler locations","where to find savannah prowler","где хищники","где найти хищника саванны","расположение хищников"}},{q="Какие трофеи требует Сергра?",a="Охотники должны добыть и принести семь когтей хищника саванны, чтобы доказать, что победили кошек в открытом бою.",al={"what do i need","prowler quest items","claws","что нужно принести","предметы задания хищники","когти"}},{q="К чему приводит эта охота?",a="Убийство хищников доказывает вашу готовность бросить вызов Ичияки, знаменитому белому льву Степей.",al={"next quest","what comes after prowlers","echeyakee","следующее задание","что после хищников","ичияки"}},{q="Почему Сергра посылает путников охотиться на хищников?",a="Помимо истребления опасных зверей, угрожающих дорогам, испытания Сергры проверяют, понимает ли охотник равновесие между хищником и добычей, и отсеивают безрассудных до встречи с более серьезными угрозами.",al={"why hunt prowlers","purpose of hunt","lore reason","зачем охотиться на хищников","цель охоты","причина"}},{q="Опасны ли хищники саванны для поселения?",a="Хищники редко нападают прямо на укрепленные лагеря вроде Перекрестка, но подстерегают у южных дорог и охотятся на путников, гонцов и вьючных животных.",al={"do prowlers attack crossroads","threat to crossroads","нападают ли хищники на перекресток","угроза перекрестку"}}},fp="23,350,15.447.0,16.349.0,28.322.1,21.161.0,40.131.0,37.102.0,28.106.1,46.204.0,50.177.0"}
P.entries["quest:905"] = {n="Разъяренные смертехваты",s="Сергра Черный Шип посылает честолюбивых охотников к югу от Перекрестка сразиться со свирепыми смертехватами, рыскающими по Степям. Добыв перья солнечных ящеров и подложив их прямо в гнезда этих зверей, охотники доказывают свою храбрость и завоевывают уважение в суровой глуши.",h="Сергра Черный Шип посылает честолюбивых охотников к югу от Перекрестка сразиться со свирепыми смертехватами...",kw={"crossroads","eggs","gold road","nests","raptor grounds","raptors","scytheclaws","sergra darkthorn","stagnant oasis","sunscale","перекресток","яйца","золотой путь","гнезда","земли ящеров","ящеры","смертехваты","сергра черный шип","застывший оазис","солнечные"},ang={["class:Hunter"]="Проникнуть в логово территориального хищника и бросить вызов его господству — одно из самых прямых применений мастерства выживания в дикой природе Калимдора.",["faction:Horde"]="Стаи ящеров вдоль Золотого Пути постоянно угрожают важным караванам и одиноким гонцам, идущим между Перекрестком и южными форпостами.",["race:Orc"]="Испытание себя в схватке с суровой дикой природой отражает основное убеждение орков: чтобы выжить в Дуротаре и Степях, нужны сила, стойкость и непоколебимая выдержка."},sec={{t="Проверка выдержки",b="Для Сергры Черный Шип охота в Степях — это не просто убийство, а давний обряд посвящения. Уже испытав путников на менее опасных зверях, она поручает охотникам найти свирепых солнечных ящеров к югу от Перекрестка. Добыть их перья — лишь первое испытание. Чтобы по-настоящему доказать доблесть, охотники должны отнести трофеи в самое сердце владений ящеров к юго-западу от Застывшего оазиса и осквернить их гнезда, показав полное бесстрашие."},{t="Гнезда смертехватов",b="К юго-западу от Застывшего оазиса, рядом с Золотым Путем, находятся три гнезда — с яйцами красного, синего и желтого цвета, — служащие общими землями агрессивных смертехватов. Входить в эти места крайне опасно: ящеры яростно защищают кладки от всего, что приближается. Перья павших сородичей, положенные прямо в кладки, — неоспоримое заявление о господстве над зверями."},{t="Закаленные саванной",b="Возвращение на Перекресток после вылазки к гнездам доказывает не только боевое мастерство, но и то, что засушливые равнины меняют охотника. Как отмечает Сергра по завершении, выйти живым из логова ящеров — для этого нужна немалая доля настоящей отваги. В суровой экосистеме Степей каждая схватка либо закаляет будущего воина, либо оставляет его кости среди ребер кодо, разбросанных по земле."}},faq={{q="Почему Сергра Черный Шип хочет, чтобы я положил перья в гнезда ящеров?",a="Сергра Черный Шип хочет, чтобы вы продемонстрировали полное превосходство и отвагу. Убивая солнечных ящеров и подкладывая их перья прямо в цветные кладки, вы доказываете их стае и сородичам, что не боитесь их.",al={"why scytheclaw nests","purpose of feathers in nests","why defile nests","зачем гнезда смертехватов","зачем перья в гнездах","зачем осквернять гнезда"}},{q="Где находятся гнезда смертехватов?",a="Гнезда лежат к югу от Перекрестка и юго-западу от Застывшего оазиса, рядом с Золотым Путем. Они находятся возле небольшого холма с огромными костями кодо, чуть восточнее придорожной канавы.",al={"where are nests","scytheclaw nest location","blue yellow red nest location","где гнезда","расположение гнезд смертехватов","расположение синего желтого красного гнезда"}},{q="Какие ящеры обитают в этой части Степей?",a="Эту местность населяют солнечные смертехваты и их сородичи. Это хитрые, агрессивные пресмыкающиеся хищники, охотящиеся стаями и яростно защищающие кладки вокруг Золотого Пути и соседних Земель Ящеров.",al={"barrens raptor types","sunscale raptors","what are scytheclaws","виды ящеров степей","солнечные ящеры","кто такие смертехваты"}},{q="Где добыть перья солнечных ящеров?",a="Перья солнечных ящеров выпадают из ящеров и смертехватов, бродящих по равнинам к югу от Перекрестка и по соседним Землям Ящеров в сторону восточных холмов.",al={"where to get feathers","sunscale feather drops","how to get raptor feathers","где взять перья","добыча перьев солнечных ящеров","как получить перья ящеров"}},{q="Кто такая Сергра Черный Шип?",a="Сергра Черный Шип — опытная орчанка-охотница, служащая на Перекрестке. Она оценивает прибывающих искателей приключений Орды, отправляя их на испытания по Степям, чтобы проверить их инстинкты выживания и боевую дисциплину.",al={"who is sergra","sergra darkthorn lore","кто такая сергра","сергра черный шип предания"}},{q="Ведет ли это задание к другим охотам?",a="Да. Это поручение входит в более длинную цепочку охот Сергры Черный Шип по Степям и завершается охотой на Ишу Авак, легендарное морское чудовище у побережья Степей.",al={"what comes after angry scytheclaws","hunt chain crossroad","next quest after nests","что после разъяренных смертехватов","цепочка охот перекресток","следующее задание после гнезд"}}},fp="21,296,15.502.0,20.463.0,23.435.0,70.244.0,39.184.0,55.215.0,41.176.0,24.220.0,36.177.1"}
P.entries["quest:906"] = {n="Предатель в наших рядах",s="«Предатель в наших рядах» — задание Орды, завершающее охоту на предводителя агрессивных набегов Иглогривых в центральных Степях. Принеся Торку на Перекресток отрубленную голову Лока Губителя Орков, игроки показывают, что опаснейший тактик свинобразов наконец пал.",h="«Предатель в наших рядах» — задание Орды, завершающее охоту на предводителя агрессивных набегов Иглогривых в...",kw={"agamaggan","barrens","camp taurajo","crossroads","lok orcbane","mangletooth","quilboar","razormane","thork","агамагган","степи","лагерь таурахо","перекресток","лок губитель орков","кривозуб","свинобраз","иглогривые","торк"},ang={["faction:Horde"]="Смерть Лока Губителя Орков обеспечивает безопасные пути между Лагерем Таурахо и Перекрестком, ослабляя угрозу Иглогривых для новых поселений Калимдора.",["race:Orc"]="Фамилия Лока, Губитель Орков, прямо говорит о его давней истории истребления орочьих поселенцев и обозов со снабжением на засушливых равнинах."},sec={{t="Голова предателя",b="Плененный иглогривый свинобраз Кривозуб, сидящий в клетке в Лагере Таурахо, сообщает, что Лок Губитель Орков направляет жестокие нападения свинобразов на караваны Орды. Когда вожак убит в глубине южных терновых лабиринтов, Кривозуб отдает череп Лока, забавляясь тем, что орки получат выгоду от предательства внутри племени, даже не догадываясь, что им помог пленный свинобраз."},{t="Защита Перекрестка",b="Доставка жуткого трофея Лока на север, к Торку на Перекрестке, снимает сильное давление с линий снабжения Орды по всей центральной саванне. Торк выражает недоверие, что одинокий путник сумел сразить столь грозного предводителя, признаваясь, что ожидал совсем другого вдохновителя организованных нападений. Смерть Лока разрушает наступление Иглогривых, и их утесы остаются в беспорядке."}},faq={{q="Кто такой Кривозуб?",a="Кривозуб — плененный иглогривый свинобраз, которого держат в деревянной клетке в Лагере Таурахо. Озлобленный тем, что собственное племя бросило его, он помогает искателям приключений Орды убивать военачальников своего племени из мести.",al={"mangletooth","captive quilboar","taurajo prisoner","кривозуб","пленный свинобраз","пленник таурахо"}},{q="Кем был Лок Губитель Орков?",a="Лок Губитель Орков был видным вождем племени Иглогривых, который координировал жестокие засады на форпосты и линии снабжения Орды, проходящие через Степи.",al={"lok","lok orcbane","razormane leader","лок","лок губитель орков","предводитель иглогривых"}},{q="Почему Торка волнует смерть Лока?",a="Как командир, обороняющий Перекресток, Торк координирует защиту от постоянных набегов обитателей зарослей. Устранение Лока Губителя Орков убирает главного тактика, организующего нападения вдоль Золотого Пути.",al={"why thork wants lok dead","crossroads supply raids","почему торк хочет смерти лока","набеги на снабжение перекрестка"}},{q="Почему Кривозуб помог убить собственного вождя?",a="Кривозуб питает глубокую горечь к руководству своего племени и уважает грубую силу выше родства. Помогая чемпионам Орды казнить Лока, он тешит свою ненависть, сохраняя из-за решетки мистическую связь с Агамагганом.",al={"why did mangletooth betray","mangletooth motive","почему кривозуб предал","мотив кривозуба"}},{q="К чему ведет эта цепочка заданий?",a="Это сдача задания завершает ближайшую цепочку убийств, хотя Кривозуб продолжает обменивать стихийные благословения Агамаггана на Кровавые осколки, собранные со свинобразов по всем Степям.",al={"next quest after betrayal from within","what follows betrayal from within","следующее задание после предателя в наших рядах","что после предателя в наших рядах"}},{q="Где находится Торк?",a="Торк стоит на страже в поселении Перекресток на севере центральных Степей и руководит оборонительными действиями и снабжением.",al={"thork location","where is thork","где торк","местонахождение торка"}}},fp="20,279,16.387.0,23.402.1,19.211.0,20.169.0,38.208.0,53.241.0,33.207.0,23.134.0"}
P.entries["quest:907"] = {n="Разъяренные рокочущие ящерицы",s="Разъяренные рокочущие ящерицы — охотничье испытание Орды, которое дает Джорн Заклинатель Небес в Лагере Таурахо. В рамках большого обряда посвящения в Степях охотникам нужно сразиться с огромными рокочущими ящерицами, бродящими по южным равнинам, и вернуться с их кровью.",h="Разъяренные рокочущие ящерицы — охотничье испытание Орды, которое дает Джорн Заклинатель Небес в Лагере...",kw={"barrens","camp taurajo","enraged thunder lizards","jorn skyseer","stormhide","stormsnout","thunderhead","степи","лагерь таурахо","разъяренные рокочущие ящерицы","джорн заклинатель небес","штормошкур","шторморыл","громоголов"},ang={["class:Hunter"]="Бой с рокочущей ящерицей проверяет вашу подвижность: нужно держать дистанцию от сокрушительных ударов, изматывая противника с огромной шкурой.",["faction:Horde"]="Уничтожение разъяренных зверей обеспечивает безопасность дорог вокруг Лагеря Таурахо и защищает караваны и странствующих воинов в южных Степях.",["race:Tauren"]="Для шу'хало охота на великих рокочущих ящериц вокруг Лагеря Таурахо — традиционное проявление уважения, стойкости и равновесия на их исконных равнинах."},sec={{t="Испытание южных равнин",b="Доказав свою доблесть в схватке с ящером Ишамухалом, охотники возвращаются в Лагерь Таурахо. Там старейшина-таурен Джорн Заклинатель Небес проверяет, справится ли охотник с огромной массой и яростью самых крупных травоядных этих земель. Рокочущие ящерицы, от которых содрогаются южные Степи, — от шторморылов до громоголовов — грозные противники, чья тяжелая поступь способна раздавить неосторожного."},{t="Путь хищника",b="Для охотников-тауренов и орков убить рокочущую ящерицу — не просто истребление, а проявление выдержки, умения занять позицию и силы. Джорн требует образцы их могучей крови как вещественное доказательство того, что охотник встал на пути грохочущих громадин и вышел целым. Добыв этот трофей, охотник открывает путь к последней добыче Джорна — в небесах."}},faq={{q="Где найти рокочущих ящериц для этой охоты?",a="Рокочущие ящерицы бродят по равнинам вокруг Лагеря Таурахо в южных Степях. Шторморылов, штормошкуров и громоголовов можно встретить на пастбищах к северу, востоку и югу от лагеря.",al={"thunder lizard location","where are stormsnouts","where to find thunder lizards","где рокочущие ящерицы","где найти шторморылов","где найти рокочущих ящериц"}},{q="Кто посылает меня на эту охоту?",a="Это задание дает Джорн Заклинатель Небес, старейшина-охотник из тауренов, живущий в Лагере Таурахо. Оно следует сразу за охотой на быстрого ящера Ишамухала.",al={"quest giver","who gives enraged thunder lizards","jorn skyseer","персонаж, выдающий задания","кто дает разъяренные рокочущие ящерицы","джорн заклинатель небес"}},{q="Чем рокочущие ящерицы особенно опасны?",a="Серьезную угрозу несут их огромная масса и электрическая природа. Они легко могут растоптать неосторожного охотника или оглушить его сотрясающими, заряженными бурей ударами лап.",al={"why are they dangerous","thunder lizard combat","почему они опасны","бой с рокочущими ящерицами"}},{q="Что Джорн делает с собранной кровью?",a="Кровь служит прежде всего неоспоримым доказательством того, что вы сошлись с этими существами лицом к лицу и одолели их в ближнем бою. Джорн осматривает ее, чтобы убедиться, что вы пережили натиск топчущих зверей и остались целы.",al={"why thunder lizard blood","blood purpose","зачем кровь рокочущих ящериц","для чего кровь"}},{q="Что идет после этого задания?",a="Если отнести кровь Джорну Заклинателю Небес, вы перейдете к заданию «Крик грозового змея» — следующему этапу южных охотничьих испытаний, где вам предстоит выследить крылатых хищников равнин.",al={"next quest","what after enraged thunder lizards","следующее задание","что после разъяренных рокочущих ящериц"}},{q="Как это связано с испытаниями Сергры Черный Шип?",a="Сергра Черный Шип начинает ваше охотничье обучение на севере Степей близ Перекрестка, где вы охотитесь на равнинных бегунов, жевр и ящеров, а затем отправляет вас на юг, в Таурахо, учиться у Джорна Заклинателя Небес охоте на более крупную дичь.",al={"crossroads hunting trials","sergra darkthorn questline","охотничьи испытания перекрестка","цепочка заданий сергры черный шип"}}},fp="23,263,29.400.0,23.401.0,51.187.0,26.143.0,50.176.0,43.214.0,28.173.0,49.218.0"}
P.entries["quest:90902"] = {n="Повторное обретение Света",s="Это задание дает Арамис Молоторук в Могильнике. Оно призывает недавно восставших паладинов из числа Отрекшихся вновь принять Свет. Обращение к священным силам причиняет мучительную боль мертвой плоти, и начинающим паладинам приходится направлять исцеление на раненых Стражей смерти, несмотря на жгучую муку.",h="Это задание дает Арамис Молоторук в Могильнике.",kw={"aramis hammerhand","deathguard","deathknell","forsaken paladin","holy light","rediscovering the light","tirisfal glades","undead paladin","арамис молоторук","страж смерти","могильник","паладин отрекшихся","свет","повторное обретение света","тирисфальские леса","паладин-нежить"},ang={["class:Paladin"]="Для паладина-нежити воссоединение со Светом — горнило веры и стойкости, доказывающее, что священные обеты переживают даже смерть, несмотря на обжигающую муку.",["race:Undead"]="Этот обряд показывает яростную стойкость Отрекшихся, которые обращают даже палящую муку Света в дисциплинированное оружие ради выживания."},sec={{t="Болезненное воссоединение",b="Для бывших защитников Серебряной Длани и павших рыцарей Лордерона пробуждение в нежизни означает столкновение с ужасной правдой: Свет по-прежнему отвечает на их зов, но жжет их иссохшие тела изнутри. Арамис Молоторук объясняет восставшим паладинам из числа Отрекшихся, что умения, некогда привычные, как дыхание, теперь причиняют нестерпимую боль. Поскольку священная энергия противоречит скверной магии, поддерживающей нежизнь, направлять Свет можно лишь силой воли и мучительным упорством."},{t="Очищение страданием",b="Отрекшиеся паладины не позволяют этим мучениям остановить их, а видят в боли непреходящее свидетельство веры. Стражи смерти по всему Могильнику получают тяжелые раны в боях с безмозглыми зомби, и исцелять их выпадает на долю этих мертвых рыцарей. Арамис учит, что преодоление жгучей боли подобно упражнению для атрофированной мышцы: сама мука считается знаком отличия и живым доказательством того, что Свет не покинул их."}},faq={{q="Почему использование Света причиняет боль паладинам из числа Отрекшихся?",a="Свет в корне противоположен некротической энергии, поддерживающей нежизнь. Воля и убежденность Отрекшегося позволяют направлять силу Света, но движение этой священной энергии через мертвую плоть причиняет мучительную жгучую боль.",al={"why does light hurt undead","holy light burning undead","why pain when healing","почему свет жжет нежить","свет жжет отрекшихся","почему больно исцелять"}},{q="Кто такой Арамис Молоторук?",a="Арамис Молоторук — паладин-нежить, учитель паладинов в Могильнике. Он направляет недавно восставших паладинов из числа Отрекшихся, пока те заново обретают разбитую связь со Светом.",al={"who is aramis hammerhand","aramis hammerhand lore","quest giver","кто такой арамис молоторук","арамис молоторук предания","персонаж, выдающий задания"}},{q="Почему Стражи смерти в Могильнике ранены?",a="Стражи смерти — воины, защищающие Могильник от безмозглой нежити, одичавших остатков Плети и враждебных животных, окружающих поселение, пока из могил встают новые Отрекшиеся.",al={"why are deathguards hurt","injured deathguard lore","deathknell defenders","почему стражи смерти ранены","раненые стражи смерти","защитники могильника"}},{q="Может ли нежить владеть Светом от природы?",a="Да, если сохранила веру, силу воли и память о прежних обетах. Свет откликается на искреннюю убежденность, хотя и взимает жестокую телесную плату с мертвых тел.",al={"can forsaken be paladins","undead using the light","forsaken paladin lore","могут ли отрекшиеся быть паладинами","нежить использует свет","паладин отрекшихся предания"}},{q="Что имеет в виду Арамис, называя боль знаком чести?",a="Арамис видит в жгучей муке не проклятие, а неоспоримое доказательство того, что Свет все еще слышит. Паладины из числа Отрекшихся терпят палящий жар своих заклинаний, показывая непоколебимую верность и цель.",al={"pain purifying property","badge of honor meaning","aramis speech","очищающая боль","значение знака чести","речь арамиса"}},{q="Где происходит это задание?",a="It takes place entirely within Deathknell, the secluded starter haven in southwestern Tirisfal Glades where newly raised Forsaken first emerge into their undead existence.",al={"where is this quest","quest location","deathknell quest","где это задание","место задания","задание в могильнике"}}},fp="23,301,17.508.0,30.452.0,48.258.0,25.173.0,46.193.0,42.180.0,58.211.0,33.171.0"}
P.entries["quest:91"] = {n="Закон Соломона",s="Закон Соломона — местный указ, оглашаемый Помощником судьи Конах в Ратуше Приозерья. Он приговаривает гноллов Темношкуров из Красногорья к смерти за сговор с Моргантом, врагом Штормграда. Авантюристам поручено осуществить суровое пограничное правосудие города и принести подвески, снятые с гноллов.",h="Закон Соломона — местный указ, оглашаемый Помощником судьи Конах в Ратуше Приозерья.",kw={"conacher","gnolls","lakeshire","morganth","pendants","redridge","shadowhide","solomon","town hall","конах","гноллы","приозерье","моргант","подвески","красногорье","темношкуры","соломон","ратуша"},ang={["class:Mage"]="Моргант воплощает извращение тайных знаний, обращенных к темному ужасу, поэтому его приспешники — первоочередная цель для дисциплинированных заклинателей.",["class:Paladin"]="Наказание мерзких гноллов, добровольно служащих темному чародею, отвечает призыву нести священное правосудие и защиту осажденным пограничным городам.",["faction:Alliance"]="Исполнение указа Соломона укрепляет верховенство закона на восточной границе, где регулярные войска Штормграда заметно отсутствуют."},sec={{t="Пограничное правосудие в Приозерье",b="Приозерье почти лишено непосредственной военной поддержки Штормграда, поэтому Мировой судья Соломон и городские чиновники управляют Красногорьем с суровой пограничной властью. Помощник судьи Конах, работающий в ратуше, служит рукой местного суда. Когда поселению грозит внешняя опасность, суду остается лишь назначать награды за головы нарушителей, полагаясь на вольных наемников и странствующих защитников, которые отстаивают законы королевства."},{t="Помощь врагу короны",b="Юридическое обоснование истребления клана Темношкуров — их союз с Моргантом, отступником-чародеем, засевшим в восточных холмах. По законам Приозерья и Королевства Штормград прямая помощь объявленному врагом государства карается обязательной смертной казнью. Поскольку гноллы исполняют волю Морганта, суд считает их не просто дикими падальщиками, а изменниками-врагами, подлежащими казни."}},faq={{q="Кто такой Соломон и в чем его закон?",a="Соломон — это Мировой судья Соломон, гражданский глава Приозерья. «Закон Соломона» отражает его местные указы и законы Штормграда, согласно которым помощь объявленному преступнику королевства является изменой и карается смертью.",al={"who is solomon","solomon law meaning","what is solomons law","кто такой соломон","значение закона соломона","что такое закон соломона"}},{q="Кто такой Моргант и почему он важен для Приозерья?",a="Моргант — отступник, владеющий тайной магией, живущий в восточных предгорьях Красногорья. Объявленный врагом Штормграда, он при помощи скверной магии терроризирует местных жителей и подчинил гноллов Темношкуров своей темной воле.",al={"who is morganth","morganth backstory","why morganth dangerous","кто такой моргант","история морганта","чем опасен моргант"}},{q="Почему охота идет именно на гноллов Темношкуров?",a="Хотя гноллы всегда опасны для местных поселенцев, клан Темношкуров поступил на прямую службу к темному чародею Морганту. Этот действующий союз делает их законной мишенью для казни по указу города.",al={"why kill shadowhides","shadowhide gnolls redridge","why gnolls targeted","зачем убивать темношкуров","гноллы темношкуры красногорье","почему гноллы мишень"}},{q="Для чего нужны подвески?",a="Подвески, которые носят гноллы Темношкуры, служат доказательством их смерти. Помощник судьи Конах требует от авантюристов сдать десять таких подвесок, чтобы подтвердить исполнение приговора суда, прежде чем выплатить награду.",al={"why shadowhide pendants","purpose of pendants","pendants proof","зачем подвески темношкуров","назначение подвесок","подвески как доказательство"}},{q="Где Помощник судьи Конах ведет свои дела?",a="Помощник судьи Конах находится в Ратуше Приозерья вместе с Мировым судьей Соломоном и другими гражданскими чиновниками, ведающими делами Красногорья.",al={"conacher location","where is bailiff conacher","lakeshire court","где конах","где помощник судьи конах","суд приозерья"}},{q="Почему Штормград не посылает королевских солдат?",a="Королевство Штормград растянуто до предела и охвачено политическим параличом и волнениями на своих землях. Просьбы Приозерья об официальном военном подкреплении раз за разом остаются без внимания, и Мировому судье Соломону приходится нанимать авантюристов.",al={"where is stormwind army","why no guards for gnolls","lakeshire abandoned by stormwind","где армия штормграда","почему нет стражи против гноллов","штормград бросил приозерье"}}},fp="13,319,29.490.0,28.461.0,35.248.0,54.227.0,56.212.0,26.220.0,49.150.0,60.260.0"}
P.entries["quest:91208"] = {n="Примирение",s="Это задание выдает Арамис Молоторук в Могильнике: новообращенным паладинам предстоит отыскать собрата по ордену, который не может смириться с нежизнью. Охваченная ужасом, вернувшаяся воительница бежала в холмы и мучительно осознает, что стала тем, с чем некогда сражалась.",h="Это задание выдает Арамис Молоторук в Могильнике: новообращенным паладинам предстоит отыскать собрата по...",kw={"aramis hammerhand","coming to terms","deathknell","frightened paladin","holy light","paladin","tirisfal glades","undead paladin","арамис молоторук","примирение","могильник","напуганная паладин","свет","паладин","тирисфальские леса","паладин нежити"},ang={["class:Paladin"]="Это задание затрагивает суть дилеммы паладина в нежизни: необходимость взглянуть в лицо ужасу от того, что вы стали тем, что поклялись искоренять.",["race:Undead"]="Душевные муки пробуждения в Тирисфале ломают многих; необходимость иметь дело с теми, кто лишился рассудка от паники, — печальная реальность первых дней жизни Отрекшихся."},sec={{t="Горькое воскрешение",b="Пробуждение после смерти в рядах Отрекшихся потрясает любого, но для бывших паладинов Серебряной Длани этот шок особенно тяжел. Всю земную жизнь они посвятили уничтожению нежити во имя Света, и вдруг их души оказываются вновь привязаны к разлагающейся плоти. Одни приспосабливаются под руководством Арамиса Молоторука, других захлестывают ужас и смятение, и они бегут в глушь Тирисфаля, лишь бы не встречаться лицом к лицу с мрачным новым существованием."},{t="Милосердное избавление",b="Арамис Молоторук надеется, что собрат по ордену сумеет с состраданием и пониманием найти подход к охваченной паникой паладину, спрятавшейся в холмах к западу от часовни. Увы, бремя превращения довело ее до полного безумия. Когда к ней приближаются, она вслепую бросается в атаку от страха и ярости, и выбора не остается — ее приходится сразить. Для тех Отрекшихся, чей разум раскалывается на могиле, быстрый конец — единственное оставшееся милосердие."}},faq={{q="Кто такая напуганная паладин?",a="Это недавно восставшая Отрекшаяся, которая при жизни была паладином. Охваченная ужасом при пробуждении в облике нежити, она в полной панике бежала из Могильника в ближайшие холмы на западе.",al={"frightened paladin","who is the paladin in the hills","who do i find in coming to terms","напуганная паладин","кто такая паладин в холмах","кого искать в задании примирение"}},{q="Почему напуганная паладин нападает?",a="Пробудившись существом того самого рода, с которым она сражалась, она охвачена ужасом и не может принять новое существование. Арамис предупреждает, что некоторые новообращенные паладины становятся агрессивными, и просит вас подойти к ней с состраданием.",al={"why does she turn hostile","why attack","can you save the frightened paladin","почему она становится враждебной","почему нападает","можно ли спасти напуганного паладина"}},{q="Кто выдает задание «Примирение»?",a="Арамис Молоторук, наставник паладинов при церкви в Могильнике, поручает это задание новым рыцарям, которым нужно понять хрупкое душевное состояние воскрешенных собратьев.",al={"quest giver coming to terms","aramis hammerhand quest","where to start coming to terms","кто выдает задание примирение","задание арамиса молоторука","с чего начать примирение"}},{q="Могут ли Отрекшиеся по-прежнему владеть Светом?",a="Да. Восставшие паладины, такие как Арамис Молоторук, по-прежнему служат Свету, и он надеется вернуть к Свету и новообращенных паладинов.",al={"undead paladins light","do forsaken paladins use the light","undead use light","паладины нежити свет","используют ли отрекшиеся паладины свет","нежить использует свет"}},{q="Где находится напуганная паладин?",a="Она бежала прямо на запад от церкви в Могильнике и спряталась в лесистых холмах над поселением.",al={"frightened paladin location","where is she","where in deathknell","где напуганная паладин","где она","где в могильнике"}},{q="Что происходит после выполнения задания «Примирение»?",a="Вы возвращаетесь к Арамису Молоторуку и докладываете о попытке помочь напуганной паладину. Затем он направляет вас на дальнейшее обучение, чтобы закалить вашу дисциплину как паладина из числа Отрекшихся.",al={"next quest coming to terms","after coming to terms","следующее задание примирение","после примирения"}}},fp="15,283,21.505.0,18.425.1,30.189.0,39.223.1,36.188.0,35.129.0,40.111.0,46.180.1"}
P.entries["quest:91209"] = {n="Продолжение обучения",s="Это задание отправляет новообращенных паладинов из числа Отрекшихся покинуть Могильник и отправиться в Брилл для углубленного обучения. Путь, порученный Арамисом Молоторуком, знакомит начинающего святого воина с опасностями Тирисфальских лесов. Он также служит суровым предупреждением о глубоком недоверии, с которым нежить относится к служителям Света.",h="Это задание отправляет новообращенных паладинов из числа Отрекшихся покинуть Могильник и отправиться в Брилл...",kw={"aramis hammerhand","brill","continue your training","deathknell","forsaken paladin","holy light","shari stilwell","tirisfal glades","арамис молоторук","брилл","продолжение обучения","могильник","паладин отрекшихся","свет","шари стилвелл","тирисфальские леса"},ang={["class:Paladin"]="Для паладина-нежити этот переход — отрезвляющее напоминание: владение священной силой делает вас чужим даже среди собратьев-Отрекшихся.",["race:Undead"]="Задание показывает внутренние противоречия в обществе Отрекшихся, где верность земле Лордерона сталкивается с застарелой травмой, связанной со Светом."},sec={{t="Уход из Могильника",b="Когда только что пробудившаяся душа овладевает основами боевого искусства и направляет священную силу на закрытом кладбище Могильника, Арамис Молоторук отправляет ее на восток, в обширные Тирисфальские леса. Цель — Брилл, оживленный местный поселок, административный центр центральной части Тирисфаля. Там Шари Стилвелл руководит продвижением тех, кто осмелился встать на путь паладина в нежизни."},{t="Опасное призвание",b="Арамис дает прощальный совет, подчеркивающий нелегкую долю паладина-нежити. Хотя Лордерону по-прежнему нужны защитники от внешних угроз, владение Светом под знаменем Сильваны Ветрокрылой вызывает горькое недоверие. Бесчисленные Отрекшиеся страдали или погибли от рук фанатиков Света, и само присутствие Света порождает недоверие среди их собратьев-нежити."}},faq={{q="Кто выдает это задание и где его найти?",a="Задание выдает Арамис Молоторук, наставник паладинов в Могильнике в Тирисфальских лесах.",al={"quest giver","where to start","aramis hammerhand location","кто выдает задание","с чего начать","где арамис молоторук"}},{q="Где сдать задание «Продолжение обучения»?",a="Задание сдается Шари Стилвелл, наставнице паладинов в городке Брилл, к востоку от Могильника по главной дороге.",al={"where to turn in","shari stilwell location","turn in spot","где сдать","где шари стилвелл","место сдачи"}},{q="Почему Отрекшиеся не доверяют паладинам?",a="Многие Отрекшиеся глубоко затаили злобу на Свет — как из-за мучений, которые он причиняет телам нежити, так и из-за жестоких преследований со стороны священных орденов, таких как Алый орден. Путь паладина неприятно сближает с силами, которых большинство нежити боится или ненавидит.",al={"why do undead hate paladins","forsaken paladin prejudice","proximity to light","почему нежить ненавидит паладинов","предубеждение к паладинам отрекшихся","близость к свету"}},{q="Может ли это задание взять любой класс Отрекшихся?",a="Нет. Это задание — вводное переходное задание для паладинов из числа Отрекшихся, отправляющихся из стартовой зоны Могильника в большой мир, в Брилл.",al={"is this quest paladin only","class requirement","только ли для паладинов","требование к классу"}},{q="Что такое Брилл?",a="Брилл — важный город в центре Тирисфальских лесов, главный узел для путников, стражей и торговцев Отрекшихся, к северу от руин Подгорода.",al={"what is brill","brill town lore","что такое брилл","предания о городе брилл"}},{q="Какие угрозы нависают над Лордероном по словам Арамиса?",a="Хотя Лордерон разрушен, ему по-прежнему постоянно угрожают бесчинствующие остатки Плети, враждебные дикие звери и мстительные живые фракции, например Алый орден.",al={"threats to lordaeron","why protect lordaeron","угрозы лордерону","зачем защищать лордерон"}}},fp="22,342,18.436.0,20.392.0,46.111.0,42.137.0,38.288.0,39.160.0,14.155.0,53.166.0"}
P.entries["quest:913"] = {n="Крик грозового змея",s="Крик грозового змея — завершение охотничих испытаний Джорна Заклинателя Небес в южных Степях. По поручению старейшин Лагеря Таурахо охотник должен найти крылатого змея, парящего над кустарниками, и принести его крылья как доказательство своего мастерства над самыми свирепыми зверями саванны.",h="Крик грозового змея — завершение охотничих испытаний Джорна Заклинателя Небес в южных Степях.",kw={"barrens hunt","camp taurajo","cry of the thunderhawk","jorn skyseer","thunderhawk","thunderhawk wings","winged serpent","охота в степях","лагерь таурахо","крик грозового змея","джорн заклинатель небес","грозовой змей","крылья грозового змея","крылатый змей"},ang={["class:Hunter"]="Убийство воздушного змея, такого как грозовой змей, проверяет вашу дисциплину дальнего боя и терпение и служит формальным обрядом посвящения в истинное мастерство равнин.",["faction:Horde"]="Усмирение и защита опасной окраины вокруг Лагеря Таурахо обеспечивает безопасность путников Орды, идущих по большой дороге через Степи.",["race:Tauren"]="Для Шу'хало выслеживание парящего грозового змея — священное испытание уважения и чести, доказывающее способность охотника общаться с самыми быстрыми детьми Матери-Земли и испытывать себя против них."},sec={{t="Завершение испытания",b="Проявив доблесть в схватках с крадущимися долгоногами, песчаными охотниками и разъяренными громовыми ящерами, охотники в Степях получают от Джорна Заклинателя Небес последнее, главное испытание. Грозовой змей считается одним из самых свирепых воздушных хищников в кустарниках вокруг Лагеря Таурахо. Чтобы убить его, нужны терпение, меткость и чувство неба, которым мало кто из наземных хищников обладает."},{t="Путь охотника",b="Возвращение с крыльями грозового змея знаменует конец обучения новичка под бдительным взором Лагеря Таурахо. Для тауренов охота — это не простое убийство, а непрерывный духовный путь в согласии с Матерью-Землей и природной иерархией дикой природы. Победа над столь гордым существом показывает, что охотник действует с силой, отвагой и честью — а эти добродетели необходимы, прежде чем отправиться в более суровые края за пределами центральных равнин."}},faq={{q="Что такое грозовой змей?",a="Грозовые змеи — крылатые змееподобные хищники, обитающие в Степях. Они парят над засушливыми равнинами, высматривая добычу помельче сверху, и благодаря молниеносным атакам и воздушной маневренности властвуют в небесах вокруг Лагеря Таурахо.",al={"what are thunderhawks","thunderhawk creature","flying serpent barrens","что такое грозовые змеи","существо грозовой змей","летающий змей степи"}},{q="Кто выдает это задание?",a="Джорн Заклинатель Небес, уважаемый охотник-таурен в Лагере Таурахо в южных Степях, назначает это испытание, когда вы проявите себя в схватках с разъяренными громовыми ящерами региона.",al={"who starts cry of the thunderhawk","quest giver","кто начинает крик грозового змея","кто выдает задание"}},{q="Где обитают грозовые змеи?",a="Они парят в открытом небе и над скалистыми утесами по всем южным Степям, в основном над равнинами вдоль дорог к северу и западу от Лагеря Таурахо.",al={"where to find thunderhawks","thunderhawk location","где найти грозовых змеев","где обитают грозовые змеи"}},{q="Что значит для тауренов добыча крыльев?",a="Предъявление отсеченных крыльев служит ощутимым доказательством чистой и честной победы. В культуре тауренов добыча трофеев у опасной дичи показывает мастерство над зверем и одновременно признание гордости и свирепости павшего существа.",al={"why bring wings","thunderhawk wings meaning","зачем приносить крылья","значение крыльев грозового змея"}},{q="Куда ведет это охотничье испытание дальше?",a="Завершение испытаний Джорна Заклинателя Небес заканчивает ваше обучение в Лагере Таурахо, и Джорн направляет вас к своей родственнице Марен Небесной Провидице, которая присматривает за неровными берегами южных Степей.",al={"what comes after cry of the thunderhawk","next quest after thunderhawk","что после крика грозового змея","следующее задание после грозового змея"}},{q="Как это связано с Сергрой Черный Шип на Перекрестке?",a="Это испытание — южная глава общих охотничьих обрядов, начавшихся у Сергры Черный Шип на Перекрестке. Одолев северных зверей, многообещающие охотники отправляются на юг, в Лагерь Таурахо, продолжать обучение у Джорна Заклинателя Небес.",al={"sergra darkthorn connection","crossroads hunting chain","связь с сергрой черный шип","цепочка охотников перекресток"}}},fp="22,295,28.413.0,15.441.0,22.232.0,21.184.0,29.153.0,51.246.0,40.196.0,60.256.0"}
P.entries["quest:914"] = {n="Повелители Змей",s="«Повелители Змей» — важное задание Орды, которое дает Нара Буйногривая с высот Громового Утеса. Оно направляет искателей приключений в Пещеры Стенаний, чтобы уничтожить четырех предводителей павших Друидов Клыка и забрать их искаженные самоцветы снов. Остановить этих отступников-друидов необходимо, чтобы их змеиный кошмар не поглотил Степи навсегда.",h="«Повелители Змей» — важное задание Орды, которое дает Нара Буйногривая с высот Громового Утеса.",kw={"anacondra","barrens","cobrahn","dream gems","leaders of the fang","nara wildmane","pythas","serpentis","wailing caverns","анакондра","степи","кобран","самоцветы снов","повелители змей","нара буйногривая","питонас","серпентис","пещеры стенаний"},ang={["class:Druid"]="Для друидов-тауренов это задание глубоко личное. Видеть, как собратья по служению природе обращают Изумрудный Сон в ядовитую порчу, — невыносимое оскорбление принципов Кенария.",["faction:Horde"]="Степи — важный перекресток, соединяющий Оргриммар, Громовой Утес и острова Черного Копья. Если позволить фанатичной секте змеепоклонников изменять землю, это поставит под угрозу устойчивость всей Орды.",["race:Tauren"]="Здоровье Матери-Земли занимает центральное место в вере тауренов, поэтому неестественная порча, сочащаяся из источников Степей, — прямое кощунство против земли, по которой они кочуют."},sec={{t="Искаженное видение",b="Ночной эльф, верховный друид Наралекс, отправился в подземные источники Пещер Стенаний с самоотверженной целью: с помощью Изумрудного Сна вернуть засушливым Степям буйную жизненную силу. Но когда его сон обрел силу, он обернулся кошмаром наяву. Сопровождавшие его служители утратили преданность гармонии природы, поддались злобным змеиным духам и приняли имя Друидов Клыка."},{t="Четыре самоцвета снов",b="Чтобы превратить Степи в собственный змеиный Эдем, предводители расколотой секты направляют искаженную энергию снов через особые накопители — самоцветы снов. Лорд Кобран, Повелительница Анакондра, лорд Питонас и лорд Серпентис носят по одному такому самоцвету. Пока эти артефакты остаются в их руках, их оскверняющее влияние будет просачиваться в почву и воды Калимдора."},{t="Облегчение для Громового Утеса",b="Нара Буйногривая, оберегающая природное равновесие в Громовом Утесе, чувствует, как духовная мука из пещер отзывается прямо в ее разуме. Выследив четырех змеиных лордов и отняв у них самоцветы, воины Орды разрушат командную цепь секты, избавят друида-тауренку от неотступных кошмаров и спасут окрестные равнины от неестественной порчи."}},faq={{q="Кто предводители Друидов Клыка?",a="Секту ведут четыре павших друида: Повелительница Анакондра, лорд Кобран, лорд Питонас и лорд Серпентис. Каждый из них отказался от первоначальных учений о природе, принял змеиный облик и направляет магию кошмара в Пещерах Стенаний.",al={"leaders of the fang names","wailing caverns bosses","who leads druids of the fang","имена повелителей змей","боссы пещер стенаний","кто возглавляет друидов клыка"}},{q="Что такое самоцветы снов?",a="Самоцветы снов — накопители, которые носит каждый из четырех предводителей в Пещерах Стенаний. Они фокусируют искаженную, отравленную кошмаром энергию, исходящую от сна Наралекса, и питают попытки секты изменить Степи.",al={"what are the gems","gem of cobrahn","dream gems lore","что за самоцветы","самоцвет кобрана","предания о самоцветах снов"}},{q="Зачем Наре Буйногривой самоцветы?",a="Нара Буйногривая — друид-тауренка из Громового Утеса, которая ощущает психические и духовные волны кошмара. Лица павших предводителей преследуют ее во снах, и их силу необходимо сломить, чтобы защитить ее рассудок и будущее Степей.",al={"who is nara wildmane","why kill the leaders","nara wildmane motive","кто такая нара буйногривая","зачем убивать повелителей змей","мотив нары буйногривой"}},{q="Были ли Друиды Клыка злом всегда?",a="Нет. Изначально это были благородные друиды-ночные эльфы, которые последовали за Наралексом в пещеры, надеясь исцелить сухую саванну. Когда Наралекс погрузился в кошмар, энергии исказили их разум и превратили их в фанатичный змеиный культ.",al={"druids of the fang origin","why did the druids turn bad","naralex disciples","происхождение друидов клыка","почему друиды стали злыми","ученики наралекса"}},{q="Где сдается это задание?",a="Задание начинается и заканчивается у Нары Буйногривой на Вершине Старейшин в Громовом Утесе. Собрав все четыре самоцвета в глубинах Пещер Стенаний, вы должны вернуться в Мулгор и передать их ей.",al={"leaders of the fang turn in","where is nara wildmane","hand in leaders of the fang","сдать повелителей змей","где нара буйногривая","повелители змей сдача задания"}},{q="Исцелит ли убийство предводителей Наралекса?",a="Гибель четырех предводителей разрушает верхушку секты и останавливает распространение их ритуала, но сама по себе не пробуждает Наралекса. Чтобы разбудить спящего наставника, нужны другие обряды друидов в глубине пещер.",al={"does this save naralex","killing leaders effect","спасет ли это наралекса","эффект убийства предводителей"}}},fp="19,380,18.437.0,19.391.0,32.382.1,46.237.0,24.222.0,37.254.0,40.233.0,30.207.0,38.231.0"}
P.entries["quest:916"] = {n="Яд чащобного паука",s="«Яд чащобного паука» — задание Альянса в Тенистой долине, Тельдрассил. Ученый Гилшалан Буйный Ветер поручает юным ночным эльфам собрать ядовитые железы гигантских чащобных тенетников, чтобы изучить, как рост нового Мирового Древа повлиял на местных животных.",h="«Яд чащобного паука» — задание Альянса в Тенистой долине, Тельдрассил.",kw={"aldrassil","gilshalan","shadowglen","shadowthread","spiders","teldrassil","venom","webwood","windwalker","альдрассил","гилшалан","тенистая долина","паучье логово","пауки","тельдрассил","яд","чащобный тенетник","буйный ветер"},ang={["class:Druid"]="Друиды живо заинтересованы выводами Гилшалана: понимание того, исцеляет ли Тельдрассил окрестных животных или искажает их, — основа бдительности Круга Кенария.",["race:NightElf"]="Для юных ночных эльфов, взрослеющих в Тенистой долине, это задание — ранний урок того, насколько хрупкой и непредсказуемой стала природа под ветвями Тельдрассила."},sec={{t="Любопытство натуралиста",b="Гилшалан Буйный Ветер прибыл в Тенистую долину, чтобы изучить неестественные размеры и агрессию местных чащобных тенетников, наводнивших Паучье логово. Он отмечает, что эти твари родственны гораздо более мелким видам в других местах. Подозревая, что огромные магические энергии Тельдрассила вызывают быстрые и тревожные мутации местной фауны, он просит принести ядовитые железы, чтобы сравнить их свойства с обычными пауками."},{t="Нависшая угроза в Тенистой долине",b="Чащобные тенетники, обитающие вокруг Паучьего логова и внутри него, становятся все опаснее для юных послушников-ночных эльфов в долине. Сбор их яда служит двойной цели: он сокращает опасное местное скопление пауков и дает дарнасским исследователям прямые биологические свидетельства того, как нестабильно Тельдрассил влияет на дикую природу."}},faq={{q="Кто такой Гилшалан Буйный Ветер?",a="Гилшалан Буйный Ветер — ночной эльф, исследователь, расквартированный в Альдрассиле в Тенистой долине. Он изучает местную живую природу Тельдрассила, чтобы выяснить, как быстрый рост Мирового Древа влияет на местную экологию.",al={"gilshalan","who gives webwood venom","quest giver webwood venom","гилшалан","кто дает яд чащобного паука","кто выдает задание яд чащобного паука"}},{q="Почему чащобные тенетники такие большие?",a="Они родственны гораздо более мелким видам пауков. Гилшалан Буйный Ветер полагает, что быстрый рост и скрытые магические силы Тельдрассила неестественно увеличили их и исказили их поведение.",al={"giant spiders teldrassil","why are spiders big shadowglen","webwood mutations","гигантские пауки тельдрассила","почему пауки большие тенистая долина","мутации чащобных тенетников"}},{q="Где находится Паучье логово?",a="Паучье логово лежит на северных рубежах Тенистой долины, в скалистых грядах за тренировочными площадками Альдрассила.",al={"shadowthread cave location","where find webwoods","webwood spider cave","где паучье логово","где найти чащобных тенетников","пещера чащобных тенетников"}},{q="Что Гилшалан сделает с ядовитыми железами?",a="Он планирует отправить яд в Дарнасс, чтобы сравнить его химические и магические свойства с ядом обычных лесных пауков и найти аномалии, вызванные Мировым Древом.",al={"why venom sacs","gilshalan venom study","venom research darnassus","зачем ядовитые железы","изучение яда гилшалана","исследование яда дарнасс"}},{q="Есть ли в Паучьем логове другие задания?",a="Да. Собирая яд, искатели приключений часто помогают находящейся неподалеку Дирании Серебряному Сиянию спасти Иверрона, эльфа, отравленного теми же самыми пауками в Паучьем логове.",al={"other spider quests shadowglen","shadowthread cave quests","iverron quest","другие задания про пауков тенистая долина","задания паучьего логова","задание иверрон"}},{q="Какое задание идет после «Яда чащобного паука»?",a="Изучив яд, Гилшалан просит искателей приключений добыть яйцо чащобного паука из глубин Паучьего логова, чтобы изучить их жизненный цикл.",al={"next quest webwood venom","what comes after webwood venom","gilshalan followup","следующее задание яд чащобного паука","что после яда чащобного паука","продолжение гилшалана"}}},fp="13,247,24.442.0,32.357.0,28.207.0,37.205.0,27.131.0,43.185.0,44.162.0,33.152.0"}
P.entries["quest:917"] = {n="Яйцо чащобного паука",s="Гилшалан Буйный Ветер поручает юным защитникам Тенистой долины добыть неразвившееся паучье яйцо из глубин Паучьего логова. Собрав образцы яда, он нуждается в живых образцах, чтобы изучить неестественную агрессию, поразившую животных Тельдрассила. Неразвившаяся кладка позволяет исследователям безопасно изучать этих существ, не усмиряя взрослых пауков.",h="Гилшалан Буйный Ветер поручает юным защитникам Тенистой долины добыть неразвившееся паучье яйцо из глубин...",kw={"aldrassil","gilshalan windwalker","shadowglen","shadowthread cave","spider egg","teldrassil","webwood","webwood egg","альдрассил","гилшалан буйный ветер","тенистая долина","паучье логово","паучье яйцо","тельдрассил","чащобный тенетник","яйцо чащобного паука"},ang={["class:Druid"]="Изучение яиц и яда дает исследователям Кенария возможность определить, можно ли очистить порчу, изменяющую этих тварей, или скверна проникла глубже.",["race:NightElf"]="Для юных ночных эльфов добыча этого яйца показывает, какая коварная порча овладевает Тельдрассилом, вынуждая ученых изучать живую природу собственной родины как враждебную угрозу."},sec={{t="Безопасный образец",b="Добыв сырой яд агрессивных чащобных тенетников, бродящих по окраинам Тенистой долины, Гилшалан Буйный Ветер нуждается в живых образцах, чтобы лучше понять их неестественную порчу. Зная, что вытащить бьющегося гигантского паука из подземных глубин было бы смертельно для любого новичка, Гилшалан выбирает более практичное решение: неразвившееся яйцо, взятое прямо из выводка в Паучьем логове."},{t="Дорога в столицу",b="Паучье логово служит подземным гнездовьем для все более враждебных лесных пауков. Проникнув в пещеру и добыв целое яйцо, ученые получат подконтрольный образец, который сможет вылупиться в заключении. Гилшалан намерен отправить яйцо вместе с образцами яда прямо в Дарнасс для дальнейшего изучения. Это завершит его местное полевое исследование и направит новобранцев к более высоким обязанностям на ветвях Альдрассила."}},faq={{q="Почему Гилшалану нужно яйцо, а не взрослый паук?",a="Гилшалан признает, что поймать живого гигантского паука слишком опасно для неопытного новобранца и слишком трудно для него одного. Целое неразвившееся яйцо позволяет исследователям безопасно перевозить живые образцы и подготовить содержание до появления выводка.",al={"why an egg","why not catch a live spider","why webwood egg","зачем яйцо","почему не поймать живого паука","зачем яйцо чащобного паука"}},{q="Где находится яйцо чащобного паука?",a="Яйцо лежит в паутинном гнезде в глубине Паучьего логова, которое врезается в ветви и корни на северной окраине Тенистой долины в Тельдрассиле.",al={"egg location","where to find webwood egg","shadowthread cave nest","где яйцо","где найти яйцо чащобного паука","гнездо паучьего логова"}},{q="Кто такой Гилшалан Буйный Ветер?",a="Гилшалан Буйный Ветер — ночной эльф, исследователь, расквартированный в Альдрассиле в Тенистой долине. Он изучает внезапные губительные недуги, толкающие местных существ Тельдрассила к жестокому поведению.",al={"who is gilshalan","gilshalan lore","кто такой гилшалан","предания о гилшалане"}},{q="Что происходит с яйцом после сдачи?",a="Гилшалан готовит яйцо и собранные флаконы с ядом к отправке в столицу, Дарнасс, где ученые и друиды смогут изучить их в контролируемых условиях, когда его работа в Тенистой долине завершится.",al={"what does gilshalan do with the egg","where does the egg go","что гилшалан делает с яйцом","куда отправляется яйцо"}},{q="Что идет после этого задания?",a="Получив яйцо, Гилшалан направляет вас наверх по Альдрассилу ответить на «Зов Тенарона», где вы познакомитесь со старшими друидами, наставляющими сердце Тенистой долины.",al={"next quest after webwood egg","what to do after egg","следующее задание после яйца чащобного паука","что делать после яйца"}},{q="Почему чащобные тенетники так агрессивны?",a="Пауки Тельдрассила, как и многие его животные, поддаются неестественной порче, укореняющейся в молодом Мировом Древе, и превращают некогда мирных или нейтральных тварей в агрессивных хищников.",al={"why are spiders mad","spider corruption","почему пауки злые","порча пауков"}}},fp="11,383,15.437.0,23.476.0,58.293.0,31.150.0,28.194.0,46.214.0,38.156.0,42.204.0"}
P.entries["quest:918"] = {s="«Саженцы древесника» — одно из первых заданий, которое выдает ботаник Деналан у озера Аль'Амет в Тельдрассиле. Встревоженный растущей враждебностью местных природных элементалей, Деналан хочет собрать их семена, чтобы проверить, можно ли на обогащенной почве вырастить более спокойное и гармоничное потомство. Это задание дает представление о тихих усилиях травников среди ночных эльфов, которые пытаются понять скрытые недуги Мирового Древа.",h="«Саженцы древесника» — одно из первых заданий, которое выдает ботаник Деналан у озера Аль'Амет в Тельдрассиле.",kw={"botany","denalan","elementals","lake al'ameth","seeds","teldrassil","timberling","ботаника","деналан","элементали","озеро аль'амет","семена","тельдрассил","древесник"},ang={["class:Druid"]="Друиды питают глубокое родство с духами природы. Помогая изысканиям Деналана, они помогают сохранить равновесие стихий, не прибегая только к насильственному истреблению.",["profession:Herbalism"]="Собиратели, чувствующие флору Тельдрассила, оценят ботанические опыты Деналана, исследующие тонкую связь между семенами растений и обогащенной почвой.",["race:NightElf"]="Для кальдораев древесники — прямой барометр благополучия Тельдрассила. Видеть, как эти кроткие духи дичают, — тревожный знак того, что их новый дом нездоров."},sec={{t="Беспокойная природа",b="Древесники — природные элементали, обитающие на ветвях Тельдрассила и тесно связанные со здоровьем и жизненной силой окружающей флоры. Обычно они мирно отражают равновесие леса, но их недавняя необъяснимая враждебность встревожила местных ночных эльфов. Вместо того чтобы просто истреблять древесников, ботаник Деналан надеется понять источник их возбуждения."},{t="Семена нового роста",b="Деналан подозревает, что изъян таится глубоко в самой земле, и хочет вырастить новых древесников в обогащенной, тщательно обработанной почве. Собрав семена у бродячих древесников возле озера Аль'Амет, он надеется взрастить более кроткое поколение элементалей и выяснить, можно ли побороть порчу земли, начав с корней."}},faq={{q="Кто такие древесники?",a="Древесники — небольшие растительные природные элементали, обитающие в Тельдрассиле. Они отражают естественный порядок и жизненный цикл флоры и фауны великого дерева.",al={"timberling lore","what are timberlings","nature elementals teldrassil","древесники","кто такие древесники","природные элементали тельдрассила"}},{q="Почему древесники стали агрессивными?",a="Деналан подозревает скрытый изъян или заражение почвы Тельдрассила. Будучи элементальными воплощениями экологии дерева, древесники отражают растущую порчу, распространяющуюся по острову.",al={"why are timberlings angry","timberling hostility","angry timberlings","почему древесники злые","враждебность древесников","злые древесники"}},{q="Кто такой Деналан?",a="Деналан — ночной эльф, натуралист и ботаник, который ухаживает за небольшим садом-убежищем на восточном берегу озера Аль'Амет и изучает необычную флору и почвы Тельдрассила.",al={"denalan lore","who is denalan","lake al'ameth botanist","деналан","кто такой деналан","ботаник озера аль'амет"}},{q="Где можно собрать семена древесников?",a="Древесники бродят по тенистым зарослям, берегам и лесным полянам вокруг озера Аль'Амет в центральной части Тельдрассила.",al={"where to find timberling seeds","timberling locations","lake al'ameth seeds","где найти семена древесников","где живут древесники","семена озера аль'амет"}},{q="Что Деналан собирается делать с семенами?",a="Деналан намерен вырастить семена в особых очищенных почвенных смесях собственной разработки, надеясь получить кротких древесников, свободных от лесного возбуждения.",al={"what happens to seeds","denalan plan","planting timberling seeds","что будет с семенами","план деналана","посадка семян древесников"}},{q="Как это связано с общими бедами Тельдрассила?",a="Агрессия этих простых духов природы — один из первых признаков того, что Тельдрассил страдает от неестественной порчи, что подталкивает исследователей к более глубоким изысканиям в Дарнассе.",al={"teldrassil corruption","why is teldrassil sick","tree corruption","порча тельдрассила","почему тельдрассил болен","порча дерева"}}},fp="16,418,15.378.0,21.341.0,21.153.0,43.202.0,15.165.0,39.112.0,44.172.0,53.190.0"}
P.entries["quest:91859"] = {n="Странная парочка",s="«Странная парочка» начинается, когда Треван Рол замечает необычную пару, проходящую через Гробницу в Серебряном бору. Под знаменем Служителей Земли таурен путешествовал вместе с высшим эльфом — союз, настолько редкий на землях Орды, что сразу вызвал подозрения.",h="«Странная парочка» начинается, когда Треван Рол замечает необычную пару, проходящую через Гробницу в...",kw={"curious pair","deathguard baldren","earthen ring","high elf","sepulcher","silverpine forest","tauren","trevan rol","странная парочка","страж смерти балдрен","служители земли","высший эльф","гробница","серебряный бор","таурен","треван рол"},ang={["class:Shaman"]="Упоминание о Служителях Земли, путешествующих с эльфом, необычно даже для опытных шаманов, знающих, что традиции Служителей редко связаны с кель'дорай.",["race:Tauren"]="Искателям приключений из тауренов может быть не по себе при виде соплеменника, идущего с чужаком-эльфом через Лордерон под острыми взглядами дозорных Отрекшихся.",["race:Undead"]="Для Отрекшихся, охраняющих Гробницу, любой чужак, проникающий в Серебряный бор, заслуживает пристального внимания, особенно учитывая шаткую политическую обстановку в Лордероне."},sec={{t="Глаза в Гробнице",b="Гробница — мрачный перевалочный пункт, где к чужакам внимательно присматриваются, особенно к тем, кто заявляет о дипломатических делах. Когда по дороге прошли двое представителей, называвших себя Служителями Земли, местный разведчик Тревана Рол заметил их. Таурен под покровом шаманского ордена никого не удивил, но его закутанный спутник показался Отрекшимся крайне странным: это был несомненно высший эльф."},{t="Необычный союз",b="Появление квел'дорей, открыто путешествующего рядом с членом шаманских кругов Орды, естественно вызывает вопросы у часовых Отрекшихся. Служители Земли обычно заняты равновесием стихий и редко выставляют высших эльфов в Лордероне, не говоря уже о спутниках тауренских посланников. Чтобы узнать, куда направилась эта необычная пара и какие дела у нее в лесу, путникам советуют обратиться к Стражу смерти Болдрену на окраине города."}},faq={{q="Кто эти двое путников, о которых говорится в задании?",a="По словам Тревана Рола, путники представились сановниками Служителей Земли. Один был тауреном, что типично для шаманской организации, но его спутник оказался закутанным высшим эльфом.",al={"who is the curious pair","who passed through sepulcher","who were the travelers","кто такая странная парочка","кто прошел через гробницу","кто были путники"}},{q="Почему так необычно, что высший эльф путешествует с тауреном?",a="Высшие эльфы исторически связаны с Альянсом и тайной магией, а таурены — преданные члены Орды и глубокие знатоки шаманизма. Видеть представителей этих двух народов вместе в подконтрольном Орде Серебряном бору под знаменем Служителей Земли — крайне редкое и подозрительное зрелище.",al={"why is high elf with tauren weird","tauren and high elf lore","почему высший эльф с тауреном странно","таурен и высший эльф"}},{q="Кто выдает задание «Странная парочка»?",a="Задание выдает Треван Рол в Гробнице — форпосте в Серебряном бору.",al={"quest giver","where to pick up a curious pair","персонаж, выдающий задание","где взять странную парочку"}},{q="Где найти Стража смерти Балдрена?",a="Страж смерти Балдрен несет дозор у входа в Гробницу в Серебряном бору, наблюдая за путниками на дороге.",al={"baldren location","where is baldren","где балдрен","местонахождение балдрена"}},{q="Что такое Служители Земли?",a="Служители Земли — древняя организация шаманов, посвятившая себя сохранению равновесия стихий и исцелению духовного разлада во всем мире. Хотя в основном в нее входят шаманы-таурены и орки, их дипломаты порой отправляются в дальние края.",al={"earthen ring lore","what is earthen ring","служители земли","кто такие служители земли"}},{q="Является ли высший эльф врагом Отрекшихся?",a="Это неясно. Треван Рол отмечает, что эльф был закутан и путешествовал под дипломатическим предлогом вместе с тауреном, поэтому Отрекшиеся задались вопросом об их цели, а не напали сразу.",al={"are they hostile","is elf an enemy","они враждебны","эльф враг"}}},fp="14,275,21.425.0,22.473.0,50.210.0,53.314.0,36.91.0,35.136.0,25.270.0,41.206.0"}
P.entries["quest:919"] = {n="Ростки древесника",s="«Ростки древесника» — задание, которое выдает хранитель природы Деналан возле озера Аль'Амет в центральном Тельдрассиле. Встревоженный внезапным неестественным разрастанием лесных ростков у берегов озера, Деналан просит путников вырвать их, пока они не превратились во враждебных древесников. Это задание указывает на ранние признаки того, что подкрадывающаяся порча нарушает равновесие молодого Мирового Древа.",h="«Ростки древесника» — задание, которое выдает хранитель природы Деналан возле озера Аль'Амет в центральном...",kw={"corruption","denalan","lake al'ameth","taint","teldrassil","timberling sprouts","timberlings","weeding","порча","деналан","озеро аль'амет","скверна","тельдрассил","ростки древесника","древесники","прополка"},ang={["class:Druid"]="Друиды отвечают за сохранение хрупкого равновесия природы; удаление пораженных ростков — печальный, но необходимый долг ради защиты всей экосистемы.",["profession:Herbalism"]="Травники хорошо знают, как должна расти здоровая растительность, и сразу видят, что эти ростки больны и неестественно искривлены.",["race:NightElf"]="Для кальдораев Тельдрассил должен быть новым убежищем, поэтому испорченная поросль у священных вод, таких как озеро Аль'Амет, — глубоко тревожное предзнаменование."},sec={{t="Прополка у озера Аль'Амет",b="На тихих берегах озера Аль'Амет странные растительные существа — древесники — начали размножаться угрожающими темпами. Вместо того чтобы жить в гармонии с лесом, молодые ростки древесников несут признаки порчи с самого момента укоренения. Деналан, преданный ученик природы, живущий у озера, понимает, что эти ростки не поддаются исцелению. Если их не трогать, они быстро вырастают в агрессивных существ, покрытых корой, которые угрожают местным животным и неосторожным путникам. Сбор и уничтожение ростков — первая линия обороны, позволяющая сохранить рощу чистой."},{t="Признаки более глубокой порчи",b="Хотя вырывание ростков помогает справиться с местной угрозой, Деналан с ужасом отмечает, как быстро они появляются. Их безудержное разрастание неестественно для Тельдрассила. Это не изолированное заражение: испорченные ростки — симптом более глубокого недуга, угрожающего корням и почве самого Мирового Древа, — загадки, которую Деналан и друиды Дарнасса спешат разгадать."}},faq={{q="Что такое ростки древесника?",a="Ростки древесников — зарождающиеся, юные формы древесников, небольших растительных элементалей, обитающих на ветвях Тельдрассила. К несчастью, те, что прорастают у озера Аль'Амет, испорчены и быстро превращаются во враждебных, агрессивных существ.",al={"what are timberlings","timberling sprout lore","what is a sprout","что такое древесники","ростки древесника","что такое росток"}},{q="Кто такой Деналан?",a="Деналан — травник и хранитель природы, живущий в тихом лагере у берегов озера Аль'Амет. Он следит за флорой ветви и изучает экологические перемены и странную порчу, охватывающую Тельдрассил.",al={"who gives timberling sprouts","denalan lore","lake al'ameth questgiver","кто дает ростки древесника","деналан","персонаж озера аль'амет"}},{q="Почему эти ростки нельзя просто исцелить или очистить?",a="Деналан замечает, что к моменту появления ростки уже безнадежно испорчены. Пытаться их исцелить бесполезно, поэтому единственный практичный способ не дать им превратиться в опасную угрозу — истребление.",al={"can sprouts be saved","why destroy timberlings","are sprouts beyond help","можно ли спасти ростки","зачем уничтожать древесников","ростки безнадежны"}},{q="Где встречаются эти ростки?",a="Ростки укореняются на илистых берегах, мелководье и поросших берегах вокруг озера Аль'Амет в центральном Тельдрассиле.",al={"timberling sprout location","where to find sprouts","lake al'ameth sprouts","где ростки древесника","где найти ростки","ростки озера аль'амет"}},{q="Что заставляет древесников так агрессивно прорастать?",a="Неестественный всплеск числа враждебных древесников вызван порочным влиянием, проникающим в почву и воды Тельдрассила. Даже молодые побеги портятся, не успев расцвести, что указывает на болезнь, поражающую молодое Мировое Древо.",al={"why are timberlings mad","what taints the sprouts","timberling corruption","почему древесники злятся","что портит ростки","порча древесников"}},{q="Что будет после уничтожения этих ростков?",a="Деналан продолжает исследовать природу недуга озера, изучая образцы почвы, семян и воды, чтобы найти первопричину порчи.",al={"next quest after sprouts","what follows timberling sprouts","следующее задание после ростков","что после ростков древесника"}}},fp="18,402,21.618.0,23.414.0,28.245.0,15.222.0,53.227.0,28.119.0,54.251.0,42.159.0"}
P.entries["quest:92"] = {n="Гуляш по-красногорски",s="Гуляш по-красногорски — местная кулинарная традиция, которую хранит шеф-повар Брианна в прибрежном поселке Приозерье. Истратив все запасы на кормежку штормградского гарнизона во время недавних набегов орков Черной горы, Брианна обращается к странствующим искателям приключений, чтобы пополнить запас сытных горных ингредиентов.",h="Гуляш по-красногорски — местная кулинарная традиция, которую хранит шеф-повар Брианна в прибрежном поселке...",kw={"blackrock orcs","chef breanna","condor meat","goretusk snout","lakeshire","redridge goulash","redridge mountains","spider meat","орки черной горы","шеф-повар брианна","мясо кондора","рыло секача","приозерье","гуляш по-красногорски","красногорье","паучье мясо"},ang={["faction:Alliance"]="Скудное состояние запасов Приозерья — наглядное напоминание о том, какой урон вторжение орков Черной горы нанесло местным гарнизонам Альянса и гражданской инфраструктуре.",["profession:Cooking"]="Для кулинаров, исследующих Восточные королевства, гуляш шеф-повара Брианны показывает, как находчивые пограничные повара превращают свирепых горных зверей в сытную и вкусную еду."},sec={{t="Пустая горная кладовая",b="Приозерье постоянно находится в осаде орков Черной горы, гноллов и свирепых диких зверей. Когда недавно на хребтах вспыхнуло восстание орков, шеф-повар Брианна взяла на себя заботу о том, чтобы накормить весь отряд штормградских солдат, расквартированных в городке. Содержание действующего гарнизона быстро опустошило ее шкафы: у городской поварихи осталось множество голодных ртов и пустые кладовые."},{t="Дары гор",b="С пустыми шкафами шеф-повар Брианна обращается к опасным диким землям за воротами Приозерья. Фирменный гуляш требует грубоватого сочетания местного мяса: жесткие куски горных кондоров, наперченные рыла грозных больших кабанов-секачей и хрустящее мясо ног гигантских тарантулов, бродящих по холмам."}},faq={{q="Почему у шеф-повара Брианны закончились запасы еды?",a="Во время недавнего восстания орков Черной горы Брианне пришлось кормить весь отряд штормградских солдат, посланных защищать Приозерье, и ее шкафы полностью опустели.",al={"why empty pantry","breanna pantry","why no food","почему пустая кладовая","кладовая брианны","почему нет еды"}},{q="Какие ингредиенты используются для приготовления гуляша по-красногорски?",a="Для настоящего гуляша по-красногорски нужны пять кусков жесткого мяса кондора, пять рыл больших кабанов-секачей и пять порций хрустящего паучьего мяса — все это добывается у существ, обитающих в окрестных горах.",al={"goulash ingredients","what is in redridge goulash","goulash meat","ингредиенты гуляша","что входит в гуляш по-красногорски","мясо для гуляша"}},{q="Где находится шеф-повар Брианна?",a="Шеф-повара Брианну можно найти у очага и котлов в городке Приозерье, расположенном на северном берегу Озера Безмолвия в Красногорье.",al={"breanna location","where is chef breanna","lakeshire chef","где брианна","где шеф-повар брианна","повар приозерья"}},{q="Почему Приозерье просто не ввозит еду из Штормграда?",a="Орки, налетчики Черной горы и гноллы перекрыли горные перевалы, а ресурсы Штормграда на исходе, поэтому Приозерью часто приходится полагаться на местную живность и заезжих искателей приключений.",al={"stormwind supplies","why not trade with stormwind","lakeshire food shortage","припасы штормграда","почему не торговать со штормградом","нехватка еды в приозерье"}},{q="Считается ли гуляш по-красногорски деликатесом?",a="Хотя сочетание паучьего мяса, кабаньих рыл и жесткой плоти кондора чужакам кажется грубым, шеф-повар Брианна и жители пограничного Приозерья считают готовое блюдо сытным горным деликатесом.",al={"is goulash good","tasty goulash","redridge delicacy","вкусный ли гуляш","вкусный гуляш","деликатес красногорья"}},{q="Какой отряд пришлось кормить Брианне?",a="Брианна готовила для штормградских солдат, расквартированных в Приозерье, чтобы отразить натиск орков Черной горы, наступавших с северных хребтов.",al={"stormwind brigade","who defended lakeshire","troops in lakeshire","штормградский отряд","кто защищал приозерье","войска в приозерье"}}},fp="16,322,22.403.0,15.316.0,41.165.0,51.203.0,30.169.0,59.197.0,42.206.0,38.150.0"}
P.entries["quest:920"] = {n="Зов Тенарона",s="Зов Тенарона отмечает важный переход для юных ночных эльфов в Тенистой долине. Помогнув Гилшалану Буйному Ветру справиться с местными лесными угрозами, вы призваны подняться на огромные ветви Альдрассила, чтобы встретиться с Тенароном Хваткой Бури. Этот зов знаменует момент, когда новичок оставляет мелкие местные дела и сталкивается с более глубокими духовными недугами, поражающими Тельдрассил.",h="Зов Тенарона отмечает важный переход для юных ночных эльфов в Тенистой долине.",kw={"aldrassil","gilshalan","shadowglen","stormgrip","summons","teldrassil","tenaron","windwalker","альдрассил","гилшалан","тенистая долина","хватка бури","зов","тельдрассил","тенарон","буйный ветер"},ang={["class:Druid"]="Доклад Тенарону Хватке Бури — важный шаг к пониманию того, как отслеживается и поддерживается друидический баланс Тельдрассила.",["race:NightElf"]="Этот зов знаменует ваше взросление среди кальдораев: переход от простой защиты лесов к непосредственному служению старейшинам, пекущимся о Мировом Древе."},sec={{t="Зов на ветви",b="Вы доказали свою способность справляться с ядовитыми пауками и оскверненными животными, тревожащими долину, и ваши усилия не остались незамеченными. Гилшалан Буйный Ветер передает, что сам Тенарон Хватка Бури просил вас прийти. Даже среди ночных эльфов, наделенных исключительно долгой жизнью, заставлять старшего друида ждать на вершине великого древа Альдрассил считается дурным тоном."},{t="Восхождение на Альдрассил",b="Тенарон ждет в самой верхней палате Альдрассила, глядя на зеленые ветви Тенистой долины. Ответ на этот зов ведет прямо к более важным делам попечения: очищению лунных колодцев Тельдрассила и расследованию неестественной порчи, проникающей в юную экосистему Мирового Древа."}},faq={{q="Кто такой Тенарон Хватка Бури?",a="Тенарон Хватка Бури — влиятельный друид из ночных эльфов, обитающий в самой верхней палате Альдрассила в Тенистой долине. Он следит за духовным благополучием долины и координирует усилия по наблюдению за священными водами Тельдрассила и их очищению.",al={"who is tenaron","tenaron stormgrip lore","кто такой тенарон","тенарон хватка бури предания"}},{q="Где найти Тенарона Хватку Бури?",a="Он находится в самой верхней комнате Альдрассила — огромного полого города-ствола в Тенистой долине. Чтобы добраться до его наблюдательного пункта возле кроны, вы должны подняться по извилистым пандусам внутри дерева.",al={"find tenaron","tenaron location","where is tenaron","найти тенарона","где тенарон","местонахождение тенарона"}},{q="Почему Тенарон вызывает меня?",a="Когда вы доказываете свою ценность в борьбе с зараженной живностью внизу, Тенарон поручает вам более серьезные дела — исследовать священные лунные колодцы и проверять их воду на признаки порчи.",al={"why summons","what does tenaron want","зачем зов","чего хочет тенарон"}},{q="Что происходит после этого задания?",a="Ответ на зов сразу ведет к цепочке заданий «Венец Земли», где Тенарон поручает вам собрать пробы воды из лунных колодцев по всему Тельдрассилу, чтобы проверить состояние дерева.",al={"next quest","what comes after tenaron's summons","следующее задание","что после зова тенарона"}},{q="Кто посылает вас к Тенарону?",a="Гилшалан Буйный Ветер дает вам этот зов, когда вы заканчиваете помогать ему с обезумевшими от яда пауками Паучьего леса, угрожающими нижним дуплам Тенистой долины.",al={"who gives the quest","gilshalan windwalker","кто дает задание","гилшалан буйный ветер"}},{q="Что такое Альдрассил?",a="Альдрассил — огромное дерево с ветвями-жилищами, расположенное в уединенной Тенистой долине; оно служит главным поселением и учебным убежищем для юных ночных эльфов-искателей приключений в Тельдрассиле.",al={"aldrassil lore","what is aldrassil","предания альдрассила","что такое альдрассил"}}},fp="17,375,20.370.0,19.317.0,25.231.0,34.182.0,27.224.0,30.200.0,25.155.0,18.189.0"}
P.entries["quest:921"] = {n="Венец Земли",s="Венец Земли — вводный обряд, который дает Тенарон Хватка Бури высоко в Альдрассиле. Готовясь покинуть Тенистую долину, юные ночные эльфы отправляются набрать священной воды из ближайшего лунного колодца и столкнуться с мучительной историей Горы Хиджал и утраченного бессмертия их народа.",h="Венец Земли — вводный обряд, который дает Тенарон Хватка Бури высоко в Альдрассиле.",kw={"aldrassil","crown of the earth","crystal phial","hyjal","moonwell","nordrassil","shadowglen","teldrassil","tenaron stormgrip","альдрассил","венец земли","хрустальный флакон","хиджал","лунный колодец","нордрассил","тенистая долина","тельдрассил","тенарон хватка бури"},ang={["class:Druid"]="Лунные колодцы — важнейшие инструменты Круга Кенария, дающие очищенные проводники энергии природы, необходимые для поддержания равновесия леса.",["class:Priest"]="Лунные колодцы, посвященные Элуне, служат отражающими святилищами, где воды освящаются под взором Матери-Луны.",["race:NightElf"]="Этот обряд знаменует ваш уход из Тенистой долины, связывая вашу личную судьбу с жертвой, принесенной на Горе Хиджал, и с обязанностью оберегать Тельдрассил."},sec={{t="Урок недавней истории",b="Прежде чем любой начинающий искатель приключений покинет защищенные ветви Тенистой долины, старейшины следят, чтобы он понимал, какую высокую цену недавно заплатили кальдораи. В битве на Горе Хиджал Мировое Древо Нордрассил было принесено в жертву, чтобы победить Архимонда и изгнать Пылающий Легион. После этого катастрофического взрыва ночные эльфы потеряли нетленное бессмертие и свой священный щит. Тенарон Хватка Бури выступает наставником и историком, поручая новичкам этот ритуал, чтобы привить смирение и целеустремленность перед лицом меняющегося мира."},{t="Воды колодца",b="Задание требует набрать воды из лунного колодца к северу от Альдрассила с помощью хрустального флакона. Эти лунные колодцы — не обычные источники: их воды насыщены остатками древнего Источника Вечности. Пока друиды направляют их исцеляющую силу в природу, а Часовые почитают их как безмятежные святилища богини Элуны, кальдораи остаются крайне осторожными. Тайное колдовство строго запрещено во всем обществе ночных эльфов, ведь источник, питающий их земли, напоминает и о безрассудной магии, которая однажды едва не разрушила мир."}},faq={{q="Кто такой Тенарон Хватка Бури?",a="Тенарон Хватка Бури — ночной эльф, находящийся высоко в верхних ветвях Альдрассила в Тенистой долине. Он наставляет юных ночных эльфов на исходе базового обучения, поручая обряды, которые учат серьезной истории их народа, прежде чем отправить их дальше в Тельдрассил.",al={"tenaron stormgrip","who gives crown of the earth","aldrassil druid npc","тенарон хватка бури","кто дает венец земли","друид альдрассила"}},{q="Зачем собирать воду из лунного колодца?",a="Набор воды в хрустальный флакон — первый шаг церемониального и практического путешествия по острову. Воды лунного колодца хранят древнюю магию, которую друиды используют, чтобы питать землю, а сам ритуал учит юных кальдораев священным обязанностям их общества.",al={"why get moonwell water","filled crystal phial use","moonwell purpose","зачем вода лунного колодца","наполненный хрустальный флакон","назначение лунного колодца"}},{q="Почему ночные эльфы потеряли бессмертие?",a="Во время Третьей войны ночные эльфы взорвали древнюю силу, вплетенную в Мировое Древо Нордрассил, чтобы уничтожить властителя демонов Архимонда на вершине Горы Хиджал. Эта жертва уничтожила авангард Легиона, но лишила ночных эльфов вечной молодости и иммунитета к болезням.",al={"why are night elves mortal","what happened to immortality","nordrassil destruction","почему ночные эльфы смертны","что случилось с бессмертием","гибель нордрассила"}},{q="Считаются ли лунные колодцы опасными?",a="Лунные колодцы содержат разбавленные сущности, прослеживаемо связанные с Источником Вечности. Хотя друиды и жрицы безопасно направляют их энергии на исцеление, благословение и единение с природой, кальдораи строго запрещают использовать их для тайного колдовства из-за катастроф, вызванных безрассудной магией в древности.",al={"are moonwells arcane","is moonwell water safe","well of eternity danger","тайны ли лунные колодцы","безопасна ли вода лунного колодца","опасность источника вечности"}},{q="Куда ведет эта цепочка заданий дальше?",a="Возвращение наполненного флакона завершает первый урок цепочки «Венец Земли». Тенарон направит вас в Доланаар и дальше по Тельдрассилу, поручая очищать и оберегать различные священные места на огромных ветвях нового Мирового Древа.",al={"what comes after crown of the earth","crown of the earth questline","next quest after tenaron","что после венца земли","цепочка заданий венец земли","следующее задание после тенарона"}},{q="Где находится лунный колодец для этого задания?",a="Лунный колодец расположен совсем недалеко к северу от великих ветвей Альдрассила, мирно укрывшись среди лесов Тенистой долины.",al={"where is the moonwell","shadowglen moonwell location","find crystal phial well","где лунный колодец","лунный колодец тенистой долины","найти колодец для флакона"}}},fp="18,298,26.527.0,18.561.0,25.270.0,49.294.0,47.286.0,35.305.0,38.266.0,45.132.0"}
P.entries["quest:92124"] = {n="Опись книг",s="«Опись книг» — вводное задание в Аббатстве Североземья, которое выдает Брат Пакстон. Раздосадованный потерянными и неверно расставленными томами, библиотекарь аббатства посылает юных искателей приключений найти его помощника Даниэля и провести опись архивов библиотеки аббатства. Однако привычка Даниэля грезить о местных ремеслах очень затрудняет получение прямого ответа — куда сильнее, чем хотелось бы Пакстону.",h="«Опись книг» — вводное задание в Аббатстве Североземья, которое выдает Брат Пакстон.",kw={"book inventory","brother paxton","daniel","elwynn forest","library","northshire abbey","professions","tradeskills","опись книг","брат пакстон","даниэль","элвиннский лес","библиотека","аббатство североземья","профессии","ремесла"},ang={["class:Priest"]="Жрецы, изучающие священные архивы Североземья, полагаются на порядок в библиотеке, чтобы сберечь священные писания и традиции Церкви.",["race:Human"]="Для юных людей, начинающих службу в Аббатстве Североземья, знакомая трудность — совмещать монашеские научные обязанности с практической жизнью деревни."},sec={{t="Досада библиотекаря",b="В Аббатстве Североземья хранятся одни из древнейших научных трудов, духовных сочинений и исторических записей, уцелевших в Королевстве Штормград после Первой войны. Заботы об этих томах лежат на Брате Пакстоне, дотошном монахе, гордящемся собранием аббатства. В последнее время с полок стали пропадать книги, нарушая архивный покой Североземья. Пакстону нужна точная опись, чтобы понять, насколько велика потеря, но у него нет терпения гоняться за своим мечтательным помощником."},{t="Увлечения Даниэля",b="Даниэль служит помощником Брата Пакстона в библиотеке аббатства, но мысли юноши редко задерживаются на пергаментах и каталожных номерах. Его увлекают практические ремесла Элвиннского леса — кузнечное дело, кожевничество, портняжное дело и травничество. Это безмерно раздражает Пакстона: любое задание по описи заканчивается тем, что помощник рассуждает о местных мастерах вместо поисков пропавших рукописей."}},faq={{q="Кто такой Брат Пакстон?",a="Брат Пакстон — монах Аббатства Североземья, который заботится об обширном собрании книг, священных писаний и исторических свитков аббатства. Он быстро выходит из себя, когда пропадают книги или когда помощники отлынивают от обязанностей.",al={"brother paxton","who gives book inventory","paxton elwynn","брат пакстон","кто выдает опись книг","пакстон элвиннский лес"}},{q="Кто такой Даниэль?",a="Даниэль — юный помощник Брата Пакстона, работающий в библиотеке Аббатства Североземья. Хотя ему поручено расставлять книги и проводить описи, его легко отвлекает увлечение ремеслами и профессиями по всему Элвиннскому лесу.",al={"who is daniel","paxton assistant","daniel northshire","кто такой даниэль","помощник пакстона","даниэль североземье"}},{q="Почему в Аббатстве Североземья пропадают книги?",a="Brother Paxton says books have gone missing but does not explain why. He asks Daniel to inventory the collection and determine the extent of the loss.",al={"why are books missing","missing books northshire","lost books abbey","почему пропадают книги","пропавшие книги североземье","потерянные книги аббатство"}},{q="Где можно найти Даниэля?",a="Даниэль находится в Аббатстве Североземья и занимается среди полок и столов библиотеки аббатства.",al={"where is daniel","daniel location","find daniel","где даниэль","местонахождение даниэля","найти даниэля"}},{q="Почему Пакстон называет Даниэля бесполезным?",a="Пакстон считает Даниэля бесполезным, потому что юноша постоянно пренебрегает архивными обязанностями. Вместо того чтобы каталогизировать и расставлять книги, Даниэль часами грезит и рассуждает о практических ремеслах.",al={"why does paxton hate daniel","daniel useless","почему пакстон ненавидит даниэля","даниэль бесполезный"}},{q="Какие ремесла интересуют Даниэля?",a="Даниэля увлекают разные ремесла Элвиннского леса, такие как кузнечное дело, кожевничество и портняжное дело: практический труд ему милее пыльных томов.",al={"daniel tradeskills","what professions does daniel like","ремесла даниэля","какие профессии нравятся даниэлю"}}},fp="14,399,25.520.0,27.451.0,22.229.0,14.245.0,44.150.0,26.114.0,36.207.0,41.176.0"}
P.entries["quest:922"] = {n="Релиан Зеленый Костер",s="Это поручение отправляет вас из приозерного убежища Деналана в Тельдрассиле в столицу — Дарнасс. Передав семя древесного дитя друиду Релиану Зеленому Костру, вы узнаете тревожные вести о распространяющейся порче в ветвях Мирового Древа.",h="Это поручение отправляет вас из приозерного убежища Деналана в Тельдрассиле в столицу — Дарнасс.",kw={"cenarion enclave","corruption","darnassus","denalan","rellian greenspyre","teldrassil","timberling seed","анклав кенария","порча","дарнасс","деналан","релиан зеленый костер","тельдрассил","семя древесного дитя"},ang={["class:Druid"]="Для последователей Кенария это поручение показывает, насколько глубоко неожиданный недуг проник в новую экосистему Тельдрассила, и подчеркивает острую необходимость сохранить местную стихийную жизнь.",["race:NightElf"]="Древесные дети должны были процветать вместе с ростом Тельдрассила, поэтому открытие Релианом наследственной порчи — тревожный знак для нового дома кальдораев."},sec={{t="Гонец в столицу",b="Деналан приложил немало усилий, выращивая и изучая растения и стихийную жизнь вокруг Озера Аль'Амет. Собрав семена у местных древесных детей, он отправляет вас в Дарнасс, чтобы передать образец своему коллеге Релиану Зеленому Костру. Релиан, друид, гуляющий по тихим террасам Анклава Кенария, ранее интересовался исследованиями Деналана и надеется вырастить собственное древесное дитя."},{t="Оскверненный рост",b="Получив семя, Релиан приносит мрачные вести вместо научного оптимизма. Его недавние исследования подтвердили, что древесные дети по всему Тельдрассилу становятся жертвами агрессивной, всепроникающей порчи. Хуже того, семена, собранные с зараженных существ, уже несут скверну родителей. Релиан признает, что очистить их не в его силах, и полагает, что лишь глубокая связь Деналана с живыми существами оставляет надежду восстановить равновесие."}},faq={{q="Кто такой Релиан Зеленый Костер?",a="Релиан Зеленый Костер — друид из ночных эльфов, которого можно встретить на тропах Анклава Кенария в Дарнассе. Его связывает с Деналаном тесная научная дружба: оба интересуются экологией и стихийными духами Тельдрассила.",al={"rellian greenspyre lore","who is rellian","rellian greenspyre location","предания релиан зеленый костер","кто такой релиан","где релиан зеленый костер"}},{q="Почему Деналан посылает семя древесного дитя Релиану?",a="Деналан собрал семена древесных детей у Озера Аль'Амет с вашей помощью. Вспомнив, что Релиан интересовался биологией древесных детей и имел собственные теории, Деналан предлагает ему семя, чтобы тот попытался вырастить одно в столице.",al={"why send timberling seed","denalan's errand","зачем отправлять семя","поручение деналана"}},{q="Какую проблему обнаруживает Релиан?",a="Релиан обнаруживает, что древесных детей поразила неестественная порча. Поэтому собранные с них семена уже искажены скверной родителей, и вырастить здоровые ростки невозможно, пока не найдено средство исцеления.",al={"what is wrong with the timberling seed","timberling corruption","что не так с семенем древесного дитя","порча древесных детей"}},{q="Куда это задание ведет дальше?",a="Релиан не может сам исцелить оскверненные семена, поэтому направляет вас исследовать моховые опухоли, поражающие древесных детей, в надежде, что Деналан сумеет создать лекарство из новых образцов.",al={"what comes after rellian greenspyre","next quest after rellian","что после релиана зеленого костра","следующее задание после релиана"}},{q="Где можно найти Релиана Зеленого Костра?",a="Релиан гуляет по открытым тропам Анклава Кенария, расположенного в северо-западной части Дарнасса.",al={"where is rellian","rellian map location","где релиан","релиан на карте"}},{q="Почему Релиан не может сам очистить семена?",a="Глубоко укоренившаяся порча превосходит особые таланты Релиана. Он полагается на выдающееся мастерство Деналана в ботанике и выращивании живых существ и считает друга лучшей надеждой на исцеление будущих поколений древесных детей.",al={"why cant rellian cure them","rellian druid powers","почему релиан не может вылечить","силы друида релиана"}}},fp="18,254,24.438.0,14.491.1,26.237.0,51.250.0,35.249.0,31.206.1,38.111.0,44.241.0"}
P.entries["quest:924"] = {n="Демоново семя",s="Выполняя приказы, переданные через Нииру Огненного Клинка, Ак'Зелот поручает путникам Орды уничтожить Демоново семя на Вершине Багрового Тумана. Применив нестабильный треснувший камень силы на огненном алтаре, искатели приключений разрушают мощный проводник Пылающего Легиона, пока его темное влияние не распространилось дальше по Степям.",h="Выполняя приказы, переданные через Нииру Огненного Клинка, Ак'Зелот поручает путникам Орды уничтожить...",kw={"ak'zeloth","altar of fire","barrens","burning legion","demon seed","dreadmist peak","flawed power stone","neeru fireblade","ак'зелот","огненный алтарь","степи","пылающий легион","демоново семя","вершина багрового тумана","треснувший камень силы","нииру огненный клинок"},ang={["class:Warlock"]="Чернокнижники понимают, как тонка работа по созданию камней силы, разрывающих связи Легиона и не вызывающих при этом катастрофический демонический взрыв.",["faction:Horde"]="Уничтожение оплотов Легиона в Степях защищает важный караванный перекресток и торговые пути, поддерживающие молодую Орду.",["race:Orc"]="Пережив гибель Дренора от демонической порчи, орки почти не терпят алтарей Легиона, гниющих у границ Дуротара."},sec={{t="Маяк среди утесов",b="В зазубренной пещере высоко на Вершине Багрового Тумана находится Демоново семя, подвешенное над демоническим огненным алтарем. Артефакт служит мощным устройством Пылающего Легиона и направляет демонические частоты в пыльное сердце Степей. Чтобы противостоять этой угрозе, чернокнижник Ак'Зелот готовит особые камни силы, способные нарушить связь артефакта с Круговертью Пустоты, но кто-то должен донести такой камень до вершины, пока его неустойчивая энергия не иссякла."},{t="Разрыв связи",b="Доставка хрупкого камня по скалистым склонам Вершины Багрового Тумана — гонка со временем: камень постепенно расходует собственную силу. Попав на огненный алтарь, катализатор перегружает Демоново семя и разрывает его связь. Однако уничтожение проводника имеет зловещее последствие: внезапный разрушительный взрыв рассылает мощные ударные волны по эфиру и сообщает могущественным невидимым хозяевам, что их драгоценное устройство выведено из строя."}},faq={{q="Что такое Демоново семя?",a="Демоново семя — артефакт Пылающего Легиона, расположенный в пещере на Вершине Багрового Тумана. Он находится над огненным алтарем и служит проводником, который напрямую направляет демоническую силу и влияние в Степи.",al={"demon seed purpose","what is demon seed","demon seed lore","назначение демонова семени","что такое демоново семя","предания о демоновом семени"}},{q="Кто приказывает уничтожить Демоново семя?",a="Задание поручает чернокнижник Ак'Зелот, действующий по указаниям Нииру Огненного Клинка, который также присылает награду. Это известный чернокнижник, обитающий под Оргриммаром в Расселине Теней.",al={"who wants demon seed destroyed","neeru demon seed","akzeloth questgiver","кто хочет уничтожить демоново семя","нииру демоново семя","ак'зелот задание"}},{q="Почему у треснувшего камня силы есть ограничение по времени?",a="Треснувший камень силы, созданный Ак'Зелотом, по своей природе нестабилен. Магическая защита несовершенна, поэтому разрушительная энергия выгорает и уничтожает камень, если не доставить его к демоническому алтарю за короткое время.",al={"flawed power stone timer","why does stone expire","stone disappearing","таймер треснувшего камня силы","почему камень исчезает","камень пропадает"}},{q="Где находится огненный алтарь?",a="Демонический огненный алтарь находится в пещере у вершины Вершины Багрового Тумана — зловещей горы к северо-западу от Перекрестка в северных Степях.",al={"altar of fire location","demon seed cave","dreadmist peak cave","местонахождение огненного алтаря","пещера демонова семени","пещера вершины багрового тумана"}},{q="Что происходит при уничтожении Демонова семени?",a="Разрушение семени обрывает его связь с Пылающим Легионом, но бурный выброс магии рождает мощную рябь в эфире. Ак'Зелот предупреждает, что могущественные демонические существа почувствуют возмущение и выяснят, кто испортил их орудие.",al={"demon seed shockwave","consequences of demon seed","waves of power","ударная волна демонова семени","последствия уничтожения демонова семени","волны силы"}},{q="Как это связано с Нииру Огненным Клинком?",a="Нииру Огненный Клинок действует совместно с Ак'Зелотом, нацеливаясь на соперничающие или мешающие демонические артефакты в Степях. Нииру предоставляет деньги и снаряжение в качестве награды за уничтожение Демонова семени.",al={"neeru connection","is neeru good","neeru involvement","связь с нииру","нииру хороший","участие нииру"}}},fp="14,331,21.467.0,21.460.1,23.215.0,45.194.0,50.230.0,35.161.0,46.259.1,41.209.0"}
P.entries["quest:92415"] = {n="Помни, что я люблю тебя",s="«Помни, что я люблю тебя» начинается с рваного запятнанного пергамента, найденного среди могил, где бродит нежить, в Руинах Лордерона. Письмо рассказывает трагическую историю потерянного ребенка из семьи Плетущих Сердце. Чтобы найти ответы, нужно отнести эту хрупкую реликвию на юг, в приют Штормграда.",h="«Помни, что я люблю тебя» начинается с рваного запятнанного пергамента, найденного среди могил, где бродит...",kw={"blood-stained letter","capital city","heartweaver","orphan matron nightingale","remember that i love you","ruins of lordaeron","stormwind orphanage","окровавленное письмо","столица","плетущие сердце","попечительница сирот найтингейл","помни, что я люблю тебя","руины лордерона","приют штормграда"},ang={["faction:Alliance"]="Благополучная доставка письма в Штормград чтит память северных семей, разрушенных падением Лордерона.",["race:Human"]="Для людей из Лордерона этот пергамент — болезненное напоминание о семьях, разрушенных, когда Столица пала перед принцем Артасом и Плетью."},sec={{t="Мольба из руин",b="Среди оскверненной земли и бродящей нежити в руинах Столицы выжившие и мародеры порой находят напоминания об опустошении Третьей войны. Этот рваный, пропитанный кровью пергамент едва уцелел на земле кладбища, истоптанной нежитью. В нем упоминается пропавший ребенок рода Плетущих Сердце — свидетельство судеб, разбитых, когда принц Артас и Плеть прошли по королевству."},{t="Путь к приюту",b="После падения Лордерона и захвата катакомб под ним Подгородом немногие беженцы, спасшиеся на юг, рассеялись по королевствам Альянса. В Штормграде о детях, потерявших родителей на войнах, заботится Попечительница сирот Найтингейл. Передав ей окровавленное письмо, можно надеяться, что уцелевшего ребенка из семьи Плетущих Сердце удастся найти и обрести покой."}},faq={{q="Где найти окровавленное письмо?",a="Рваный запятнанный пергамент находится на территории кладбища в Руинах Лордерона — в местности, где теперь бродят неупокоенные мертвецы и силы Отрекшихся.",al={"where to find letter","parchment location","where does this quest start","где найти письмо","местонахождение пергамента","где начинается задание"}},{q="Кто такие Плетущие Сердце?",a="О семье Плетущих Сердце пока известно мало. В письме, найденном на кладбище в Руинах Лордерона, упоминается пропавший ребенок семьи, и это вселяет надежду, что юный наследник бежал на юг, в приют Альянса.",al={"heartweaver","who are the heartweavers","heartweaver lore","плетущие сердце","кто такие плетущие сердце","предания о плетущих сердце"}},{q="Кто такая Попечительница сирот Найтингейл?",a="Попечительница сирот Найтингейл заведует приютом Штормграда на Соборной площади Штормграда и обеспечивает едой, кровом и заботой детей, оставшихся без родителей после недавних войн.",al={"nightingale","matron nightingale","orphan matron","найтингейл","попечительница найтингейл","попечительница сирот"}},{q="Зачем нести память о Лордероне аж в Штормград?",a="Когда Плеть захватила Лордерон, многих осиротевших детей эвакуировали на юг, в Королевство Штормград. Сам пергамент подсказывает, что больше знает попечительница сирот в Штормграде, которая заведует городским приютом.",al={"why stormwind","why send it to nightingale","почему штормград","почему отнести найтингейл"}},{q="Могут ли игроки Орды выполнить это задание?",a="Задание направляет к Попечительнице сирот Найтингейл в глубине Соборной площади Штормграда, поэтому это путешествие остается за Альянсом.",al={"horde version","can horde do this","версия для орды","может ли орда выполнить"}},{q="В каком состоянии сейчас Руины Лордерона?",a="Наземные руины Столицы по большей части пусты, разрушаются и охраняются бродящей нежитью, а леди Сильвана Ветрокрылая и Отрекшиеся укрепили свою подземную столицу — Подгород — в склепах внизу.",al={"ruins of lordaeron status","who controls lordaeron ruins","статус руин лордерона","кто контролирует руины лордерона","кто управляет руинами лордерона"}}},fp="24,315,21.438.0,24.424.0,40.170.0,30.212.0,33.184.0,55.229.0,38.161.0,51.226.0"}
P.entries["quest:92460"] = {n="Время пришло",s="«Время пришло» — первый обряд посвящения для молодых Небожителей, делающих первые шаги за пределы Деревни Тендал на Острове Зефрис. Под руководством Айли Дальнее Сердце новички являются к главе деревни Рориану Искателю Дня, получают родовую реликвию и торжественно обещают помощь шен'дорай.",h="«Время пришло» — первый обряд посвящения для молодых Небожителей, делающих первые шаги за пределы Деревни...",kw={"ailee farheart","coming of age","rorian the dayseeker","shen'dorei","skyborne","thendal grove","thendal village","zephras isle","айли дальнее сердце","время пришло","рориан искатель дня","шен'дорай","небожители","тендалская роща","деревня тендал","остров зефрис"},ang={["race:Skyborne"]="Этот обряд определяет ваш вход во взрослую жизнь и дарует священную семейную реликвию, которую вы понесете туда, куда дуют ветры."},sec={{t="Обряд посвящения",b="Для каждого молодого Небожителя, вступающего во взрослую жизнь, путь начинается в Деревне Тендал. По указанию Айли Дальнее Сердце птенцы идут на запад к древу великого отца, где их ждет старейшина деревни. Взросление среди шен'дорай — не просто социальная веха, но торжественное обязательство служить общине в условиях растущих местных бед."},{t="Родовая реликвия",b="У входа в древо великого отца Рориан Искатель Дня руководит церемонией. Он торжественно вручает посвящаемому родовую реликвию — наследие, переходившее через поколения шен'дорай. Ее носили многие предшественники, и она остается вечным символом ветров родины, которая вернется к народу, только когда прах владельца развеют по ветру."}},faq={{q="Для чего нужна церемония «Время пришло»?",a="Это формальный переход молодых Небожителей во взрослую жизнь: их официально принимают на активную службу шен'дорай и вручают родовую реликвию.",al={"why coming of age","coming of age purpose","skyborne rite of passage","зачем время пришло","назначение время пришло","обряд небожителей"}},{q="Кто начинает это задание?",a="Айли Дальнее Сердце, присматривающая за новичками в Деревне Тендал на Острове Зефрис, приветствует вас и отправляет к руководству деревни.",al={"who gives coming of age","where does coming of age start","ailee farheart location","кто дает время пришло","где начинается время пришло","где айли дальнее сердце"}},{q="Кому вы докладываете для обряда?",a="Рориану Искателю Дня, главе Деревни Тендал, который стоит у входа в древо великого отца к западу от поселения.",al={"who is rorian","where is rorian","rorian the dayseeker location","кто такой рориан","где рориан","где рориан искатель дня"}},{q="Какая реликвия вручается во время церемонии?",a="Рориан вручает унаследованную реликвию совершеннолетия, которую носили поколения шен'дорай до вас. По традиции она остается у вас до смерти, а затем переходит к следующему поколению.",al={"what is the relic","skyborne relic","what do you get","что за реликвия","реликвия небожителей","что вы получите"}},{q="Что в этом контексте означает «шен'дорай»?",a="Рориан называет «шен'дорай» Небожителей, напоминая об их непростой истории, общих испытаниях и неугасающей самобытности на Острове Зефрис.",al={"who are the shendorei","shendorei meaning","skyborne shendorei","кто такие шен'дорай","значение шен'дорай","небожители шен'дорай"}},{q="Куда ведет ваш путь сразу после этого?",a="После завершения обряда Рориан обращает ваше внимание на местные дела, угрожающие острову, начиная с заданий «Гармония в равновесии» и «Расследование заражения».",al={"what quest is next","next steps after coming of age","after rorian","какое задание дальше","что делать после время пришло","после рориана"}}},fp="13,290,17.370.0,19.382.0,50.175.0,24.147.0,36.140.0,43.202.0,44.135.0,52.189.0"}
P.entries["quest:92461"] = {n="Гармония в равновесии",s="«Гармония в равновесии» — раннее задание долга, которое Рориан Искатель Дня дает начинающим искателям приключений на Острове Зефрис. Игроку поручено истребить молодых вулдренов в Тендалской роще, чтобы сохранить природное равновесие острова. На этой будничной необходимости новички узнают, насколько местные звери чувствительны к меняющимся магическим потокам.",h="«Гармония в равновесии» — раннее задание долга, которое Рориан Искатель Дня дает начинающим искателям...",kw={"harmony in balance","juvenile vuldren","rorian the dayseeker","thendal grove","vuldren","zephras","zephras isle","гармония в равновесии","молодые вулдрены","рориан искатель дня","тендалская роща","вулдрены","зефрис","остров зефрис"},ang={["class:Druid"]="Веление сократить перенаселенных вулдренов созвучно философии друидов, где истребление порой необходимо ради здоровья всей экосистемы.",["class:Hunter"]="Контроль численности стад и наблюдение за реакцией местных зверей на нарушения среды — основа подготовки любого следопыта в Тендалской роще."},sec={{t="Забота о роще",b="Даже в эпоху неопределенного будущего и растущей опасности ежедневное выживание на Острове Зефрис требует скромного усердия. В Тендалской роще местная популяция вулдренов выросла до неприемлемых размеров и угрожает хрупкой гармонии природы, на которой держится жизнь острова. Рориан Искатель Дня поручает молодым защитникам нелегкую задачу сократить их число, чтобы предотвратить масштабный экологический ущерб."},{t="Ветры тревоги",b="Истребление диких зверей может казаться обычной охотой, но всплеск числа вулдренов отражает более глубокие тревоги. Хотя эти создания обычно спокойны, дикая природа Зефриса чутко связана с атмосферой острова и резко реагирует, когда магия, несомая ветрами, выходит из равновесия. Раннее исправление нарушений не дает спокойным созданиям превратиться в непредсказуемых и опасных вредителей."}},faq={{q="Почему вулдренов нужно истреблять?",a="Популяция вулдренов в Тендалской роще выросла сверх допустимого. Если ее не сдерживать, они могут истощить местные ресурсы и нарушить хрупкий экологический баланс, на котором держатся остальные обитатели рощи.",al={"why kill vuldren","vuldren overpopulation","thendal grove vuldren","зачем убивать вулдренов","перенаселение вулдренов","вулдрены тендалской рощи"}},{q="Кто такой Рориан Искатель Дня?",a="Рориан Искатель Дня — старший проводник и наставник на Острове Зефрис. Он руководит обучением молодых искателей приключений и напоминает им, что защита дома требует внимания и к великим кризисам, и к повседневной заботе о природе.",al={"rorian lore","who is rorian","предания о рориане","кто такой рориан"}},{q="Отчего вулдрены начинают вести себя странно?",a="Вулдрены обычно спокойны, но местная фауна Зефриса чувствует, когда разлитая в ветрах острова магия выходит из равновесия, и это вызывает внезапные перемены в поведении.",al={"why are vuldren aggressive","vuldren behavior","почему вулдрены агрессивные","поведение вулдренов"}},{q="Где выполняется это задание?",a="Задание выполняется в Тендалской роще, к востоку и юго-востоку от поселения на Острове Зефрис.",al={"thendal grove location","where is thendal grove","где тендалская роща","местонахождение тендалской рощи"}},{q="Какому уроку учит Рориан?",a="Рориан учит, что защита родной земли часто требует трудных, неприятных мер. Твердой рукой восстанавливать природный порядок — важная обязанность любого будущего стража.",al={"rorian lesson","meaning of harmony in balance","урок рориана","смысл гармонии в равновесии"}},{q="Что нужно сделать во время охоты на вулдренов?",a="Находящаяся неподалеку Элатрелл Легкое Перо просит искателей приключений разобраться с роем назойливых перистых мух, так что удобно заодно расследовать заражение рощи насекомыми.",al={"other quests nearby","infestation investigation","другие задания рядом","расследование заражения"}}},fp="18,356,17.414.0,15.396.0,37.226.0,28.236.0,30.198.0,32.114.0,38.201.0,46.177.0"}
P.entries["quest:92462"] = {n="Расследование заражения",s="Расследование заражения — начальное задание для молодых искателей приключений в Тендалской роще на Острове Зефрис. Следопыт Элатрелл Легкое Перо приказывает истребить назойливых перистых мух, которые начали роиться в восточных рощах. Если их не остановить, быстро размножающиеся насекомые могут нарушить покой рощи и угрожать местным поселениям.",h="Расследование заражения — начальное задание для молодых искателей приключений в Тендалской роще на Острове...",kw={"cirrusfly","elatrell featherlight","infestation","investigation","pesky cirrusfly","thendal grove","zephras","перистая муха","элатрелл легкое перо","заражение","расследование","назойливая перистая муха","тендалская роща","зефрис"},ang={["class:Druid"]="Сохранить Тендалскую рощу — значит устранять природные нарушения равновесия, пока агрессивные рои не оголили лес.",["class:Hunter"]="Для начинающих стрелков и следопытов выслеживание мелких, юрких перистых мух среди деревьев — ценная практика стрельбы по быстрым целям в густых зарослях."},sec={{t="Рой в кронах",b="Тендалская роща долгое время хранила хрупкое равновесие, но недавние донесения местных следопытов говорят о внезапном росте числа назойливых перистых мух на восточной окраине леса. Поодиночке перистые мухи — мелкие вредители, но когда их становится слишком много, рои быстро делаются агрессивными и разрушительными. Следопыт Элатрелл Легкое Перо без промедления отправляет способную молодежь истреблять летающих насекомых, пока они не захватили рощу целиком."},{t="Первые шаги службы",b="После первого совершеннолетия молодые защитники сразу вовлекаются в повседневную заботу об Острове Зефрис. Истребление вредителей может показаться черной работой, но защита лесов от вспышек численности животных жизненно важна для безопасности ближайших поселений. Обилие внутренностей и насекомых на вернувшихся охотниках доказывает, что рой намного опаснее, чем опасались вначале."}},faq={{q="Что такое перистая муха?",a="Перистые мухи — крылатые насекомые-вредители, обитающие в буйной природе Острова Зефрис. Поодиночке они малы, но быстро размножаются и могут образовать опасные рои, если их численность не сдерживать, например в Тендалской роще.",al={"cirrusfly","cirrusflies","what are cirrusflies","перистая муха","перистые мухи","что такое перистые мухи"}},{q="Кто выдает задание «Расследование заражения»?",a="Задание выдает Элатрелл Легкое Перо, следопыт, находящийся в Тендалской роще и следящий за местной дикой природой и окрестными лесами.",al={"quest giver","who starts it","elatrell featherlight","персонаж, выдающий задания","кто дает задание","элатрелл легкое перо"}},{q="Где обитают перистые мухи?",a="Назойливые перистые мухи скапливаются в восточной и юго-восточной частях Тендалской рощи на Острове Зефрис и жужжат в листве рядом с молодыми вулдренами.",al={"where to find flies","cirrusfly location","thendal grove flies","где найти мух","где перистые мухи","мухи тендалская роща"}},{q="Почему важно истреблять перистых мух?",a="Одиночное насекомое почти не опасно, но рои перистых мух быстро становятся достаточно плотными, чтобы угрожать путникам, истощать местные растения и нарушать покой Тендалской рощи.",al={"why kill flies","why cull cirrusflies","cirrusfly threat","зачем убивать мух","зачем истреблять перистых мух","угроза перистых мух"}},{q="Что идет после задания «Расследование заражения»?",a="Проредив рой и доложив Элатреллу Легкое Перо, искатели приключений отправляются в сердце заражения, чтобы сразиться с Королевой перистых мух.",al={"next quest","what next","investigation follow up","следующее задание","что дальше","продолжение расследования"}},{q="Какое место это задание занимает в начале пути на Зефрис?",a="Задание выдается сразу после испытания «Время пришло» и является одним из первых боевых поручений для вновь признанных защитников Острова Зефрис.",al={"quest chain","when do i get this","level requirement","цепочка заданий","когда получить","требуемый уровень"}}},fp="25,344,21.452.0,22.419.0,20.237.0,46.158.0,34.160.0,41.188.0,43.163.1,60.174.0"}
P.entries["quest:92463"] = {n="Королева перистых мух",s="Королева перистых мух — охота на матку агрессивного роя, обитающего в Тендалской роще на Острове Зефрис. После первой разведки заражения Элатрелл Легкое Перо направляет новобранцев в сердце рощи, чтобы убить королеву и истребить рой в самом источнике. Конец ее правления приносит немедленное облегчение местным следопытам, стремящимся удержать дикую природу под контролем.",h="Королева перистых мух — охота на матку агрессивного роя, обитающего в Тендалской роще на Острове Зефрис.",kw={"cirrusfly","elatrell featherlight","hive","queen","soldier","thendal grove","zephras","перистая муха","элатрелл легкое перо","улей","королева","солдат","тендалская роща","зефрис"},ang={["class:Hunter"]="Победа над агрессивной королевой улья и обход ее солдат-защитников — раннее испытание в выслеживании и истреблении зверей, за которое местные следопыты лично хвалят.",["race:Skyborne"]="Очистка Тендалской рощи от вторгшихся роев помогает сохранить природное равновесие и безопасные пути по вашей родине — Острову Зефрис."},sec={{t="Удар по улью",b="Первые действия против перистых мух показали, что простое отгонение отбившихся рабочих особей не остановит заражение, расползающееся по Тендалской роще. Элатрелл Легкое Перо поручает способным странникам проникнуть глубже в юго-восточную часть рощи, где находится главный улей. Там королева управляет колонией под бдительной охраной крупных особей-солдат."},{t="Бремя следопыта",b="Обычные перистые мухи издали могут показаться мелкими вредителями, но их крупные разновидности представляют серьезную угрозу для всякого, кто проходит под ветвями Зефриса. Выследив матку и выстояв против ее стражей, новички доказывают боевую доблесть и получают высокую похвалу и уважительный кивок от следопытов Легкого Пера."}},faq={{q="Где находится Королева перистых мух?",a="Королева перистых мух устроила гнездо в юго-восточном углу Тендалской рощи на Острове Зефрис, неподалеку от сердца улья.",al={"queen location","where is cirrusfly queen","find the queen","где королева","где королева перистых мух","найти королеву"}},{q="Почему недостаточно убивать рабочих мух?",a="Элатрелл Легкое Перо понимает, что истребление бродячих рабочих особей лишь прореживает края роя. Пока королева жива, она будет выводить агрессивных солдат и пополнять улей, поддерживая угрозу Тендалской роще.",al={"why kill the queen","culling the hive","зачем убивать королеву","истребление улья"}},{q="Кто выдает охоту на Королеву перистых мух?",a="Элатрелл Легкое Перо предлагает задание, когда первые донесения из леса подтверждают серьезность нашествия перистых мух.",al={"who gives this quest","quest giver queen","кто выдает задание","персонаж, выдающий задание королевы"}},{q="Чем королева опаснее обычных перистых мух?",a="В отличие от простых рабочих особей, бродящих по роще, королеву окружают более крупные и гораздо более агрессивные солдаты, защищающие ее улей.",al={"queen danger","cirrusfly soldiers","опасность королевы","солдаты перистых мух"}},{q="Какое задание предшествует этому?",a="Это поручение напрямую следует за заданием «Расследование заражения», которое впервые показало, насколько широко насекомые распространились в роще.",al={"prerequisite quest","what comes before","предыдущее задание","что было раньше"}},{q="Какую роль Элатрелл Легкое Перо играет в этой местности?",a="Элатрелл Легкое Перо отвечает за безопасность дикой местности на Острове Зефрис: следит за угрозами в регионе и обучает новых искателей приключений выслеживанию в лесу и обязанностям следопыта.",al={"featherlight role","who is featherlight","роль легкого пера","кто такой легкое перо"}}},fp="19,408,17.391.0,17.339.0,37.134.0,43.244.0,44.122.0,61.148.0,36.149.0,55.165.0"}
P.entries["quest:92464"] = {n="Волнения элементалей",s="Волнения элементалей — вводное задание, которое выдает Рориан Искатель Дня на Острове Зефрис. После ухода разумных элементалей-покровителей острова низшие духи ветра возле Тендалских монолитов стали возбужденными и непредсказуемыми. Вас посылают в Тендалскую рощу найти ученицу Рориана, Ялу Ветростраж, и выяснить, что тревожит местный ветер.",h="Волнения элементалей — вводное задание, которое выдает Рориан Искатель Дня на Острове Зефрис.",kw={"elemental unrest","rorian the dayseeker","thendal grove","thendal standing stones","wind sprites","yala windwatcher","zephras isle","волнения элементалей","рориан искатель дня","тендалская роща","тендалские монолиты","духи ветра","яла ветростраж","остров зефрис"},ang={["class:Shaman"]="Духи ветра Зефриса, как зеркало, отражают эмоциональный климат острова, и это беспокойство служит явным предупреждением о более глубоком нарушении в природе.",["race:Skyborne"]="Уход элементалей-покровителей сделал ветра непредсказуемыми, и те, кто зависит от небес Острова Зефрис, должны быть бдительны."},sec={{t="Перемена ветра",b="На протяжении поколений жители Зефриса жили рядом с могущественными разумными духами ветра, которые направляли и оберегали их. С уходом элементалей-покровителей остров погрузился в постоянное нарушение равновесия. За воздухом больше не присматривают доброжелательные разумы, и остались лишь простые духи, отражающие переменчивые чувства и силы, витающие над местностью."},{t="Тендалские монолиты",b="К северо-востоку от поста Рориана, возле древних Тендалских монолитов, воздух стал резко враждебным. Поскольку у этих низших проявлений нет настоящего самосознания, их буйство рождено не злобой, а реакцией. Рориан отправил свою ученицу, Ялу Ветростраж, наблюдать за их беспорядочным поведением с опушки рощи и понять, какое скрытое напряжение их тревожит."}},faq={{q="Почему духи ветра возбуждены?",a="В отличие от прежних элементалей-покровителей острова, эти духи ветра лишены настоящего самосознания. Они инстинктивно отражают чувства, намерения и окружающие магические силы существ и событий вокруг, становясь буйными, когда местная среда выходит из равновесия.",al={"why are elementals mad","wind unrest cause","sprites angry","почему элементали злятся","причина волнений ветра","духи злые"}},{q="Кто такие элементали-покровители, о которых говорит Рориан?",a="Это были разумные доброжелательные духи ветра, когда-то жившие бок о бок с обитателями Зефриса. После их ухода остров без их стабилизирующего влияния непрерывно страдает от волнений.",al={"elemental benefactors","who left zephras","wind spirits zephras","элементали-покровители","кто покинул зефрис","духи ветра зефрис"}},{q="Где найти Ялу Ветростраж?",a="Яла Ветростраж находится в Тендалской роще на северо-востоке, откуда видны Тендалские монолиты, где собираются возбужденные духи ветра.",al={"yala windwatcher location","where is yala","thendal grove apprentice","где яла ветростраж","где яла","ученица в тендалской роще"}},{q="Кто такой Рориан Искатель Дня?",a="Рориан Искатель Дня — старейший проводник на Острове Зефрис, который следит за духовным равновесием острова и изучает продолжающиеся возмущения среди местных элементалей.",al={"who is rorian","rorian dayseeker","кто такой рориан","рориан искатель дня"}},{q="Что происходит после встречи с Ялой?",a="Разговор с Ялой ведет прямо к расследованию истинной причины беспокойства у монолитов, начиная с задания «Смутьяны».",al={"next quest","what comes after elemental unrest","yala follow up","следующее задание","что после волнений элементалей","продолжение с ялой"}},{q="Опасны ли духи ветра?",a="Хотя по природе они просты, возбужденное состояние делает их непредсказуемыми и враждебными. Они агрессивно реагируют на вторжение, пока сохраняется причина волнений.",al={"are sprites hostile","elemental danger","враждебны ли духи","опасность элементалей"}}},fp="16,384,20.361.0,27.381.0,34.281.0,50.197.0,34.148.0,28.167.0,32.150.0,31.163.0"}
P.entries["quest:92465"] = {n="Смутьяны",s="Смутьяны — раннее задание на Острове Зефрис, которое выдает Яла Ветростраж. Агрессивный культ Ал'акет проник в Тендалскую рощу и растревожил мирных местных духов ветра, превратив их во враждебных элементалей. Искателей приключений посылают развеять бурлящие ветра и уничтожить последователей культа, угрожающих округе.",h="Смутьяны — раннее задание на Острове Зефрис, которое выдает Яла Ветростраж.",kw={"agitators","al'aketh","al'aketh convert","roiling winds","shen'dorei","thendal grove","yala windwatcher","zephras isle","смутьяны","ал'акет","последователь ал'акет","бурлящие ветра","шен'дорей","тендалская роща","яла ветростраж","остров зефрис"},ang={["class:Druid"]="Осквернение природной гармонии Тендалской рощи мятежными культистами делает защиту ее местных духов неотложной задачей.",["class:Shaman"]="Вид природных духов ветра, доведенных вмешательством культистов до яростного неистовства, — оскорбление равновесия стихий, требующее вмешательства."},sec={{t="Тревога в роще",b="Тендалская роща оказалась в тени культа Ал'акет. Культисты, известные тревожными замыслами на Острове Зефрис, вторглись в рощу и намеренно растревожили обитающих там чутких духов ветра. Прежде мирные духи стали жестокими и образовали бурлящие ветра, угрожающие всем, кто проходит по этой местности."},{t="Мучительная необходимость",b="Яла Ветростраж поручает проходящим мимо героям усмирить и разъяренных элементалей, и последователей Ал'акет, разжигающих волнения. Усмирение ветряных существ возвращает роще хрупкое спокойствие, а расправа с культистами — печальный долг: Яла скорбит о пролитой крови шен'дорей среди своего же народа, но признает, что культ не оставляет выбора."}},faq={{q="Кто выдает задание «Смутьяны»?",a="Яла Ветростраж предлагает задание неподалеку от Тендалской рощи на Острове Зефрис.",al={"quest giver","who starts agitators","yala windwatcher","персонаж, выдающий задания","кто начинает смутьянов","яла ветростраж"}},{q="Что делает культ Ал'акет в Тендалской роще?",a="Культ Ал'акет проник в рощу и растревожил местных духов ветра, доведя мирных существ до враждебного, яростного неистовства.",al={"what are cultists doing","why are alaketh here","alaketh convert purpose","что делают культисты","зачем здесь ал'акет","цель последователей ал'акет"}},{q="Что такое бурлящие ветра?",a="Это простые местные духи ветра Острова Зефрис, которых культисты Ал'акет растревожили и превратили в агрессивные элементальные вихри.",al={"roiling winds","wind spirits","wind elementals in thendal grove","бурлящие ветра","духи ветра","ветряные элементали в тендалской роще"}},{q="Почему Яла Ветростраж печалится из-за убийства последователей?",a="Яла скорбит, что приходится проливать кровь шен'дорей в роще: последователи Ал'акет — ее же соплеменники, поддавшиеся опасным учениям культа.",al={"why does yala regret killing","shedding shendorei blood","yala completion quote","почему яла сожалеет","кровь шен'дорей","слова ялы при завершении"}},{q="Какое задание следует за «Смутьянами»?",a="Выполнив «Смутьянов» для Ялы Ветростраж, вы направляетесь продолжать службу в задании «Возвращение к Рориану».",al={"what quest is next","agitators follow up","where do i go after agitators","какое задание дальше","продолжение смутьянов","куда идти после смутьянов"}},{q="Где происходит этот конфликт?",a="Конфликт сосредоточен в Тендалской роще на Острове Зефрис.",al={"agitators location","thendal grove zone","where is thendal grove","где смутьяны","тендалская роща","где находится тендалская роща"}}},fp="9,306,20.341.0,19.371.0,30.83.0,49.143.0,27.155.0,57.170.0,29.119.0,36.81.0"}
P.entries["quest:92469"] = {n="Возвращение к Рориану",kw={"al'aketh","cult","rorian","standing stones","thendal grove","wind spirits","yala windwatcher","zephras isle","ал'акет","культ","рориан","древние камни","тендалская роща","духи ветра","яла ветростраж","остров зефрис"},ang={["class:Druid"]="Защита Тендалской рощи и сохранение мирной гармонии на священных землях острова Зефрис естественно созвучны обетам друидов.",["class:Shaman"]="Известие о том, что Ал'акет намеренно тревожат духов ветра, бьет в самую суть долга шамана — поддерживать стихийное равновесие."},sec={{t="Тревожное донесение",b="После разгрома смутьянов, досаждавших острову Зефрис, Яла Ветростраж остается зачищать оставшихся врагов, а вам поручает важное дело: доставить сведения. Тендалская роща должна узнать, что загадочный Ал'акет больше не действует лишь в тени."},{t="Обострение у древних камней",b="Получив донесение, Рориан Искатель Дня признает, что руководство Тендалской рощи уже некоторое время наблюдало за действиями культа издали. Однако то, что культисты тревожат местных духов ветра у древних камней, — дерзкое и тревожное обострение, за которым руководство рощи больше не может наблюдать пассивно."}},faq={{q="Кто посылает вас поговорить с Рорианом?",a="Яла Ветростраж посылает вас доложить Рориану после того, как вы помогли подавить враждебных смутьянов, угрожавших окрестностям.",al={"quest giver","who starts return to rorian","yala windwatcher","выдающий задания","кто начинает возвращение к рориану","яла ветростраж"}},{q="Где находится Рориан Искатель Дня?",a="Рориана Искателя Дня можно найти в Тендалской роще — поселении, где руководители рощи ведут дела острова Зефрис.",al={"where is rorian","rorian location","thendal grove rorian","где рориан","местонахождение рориана","тендалская роща рориан"}},{q="Кто такие Ал'акет?",a="Ал'акет — культ, действующий на острове Зефрис. Раньше за ними тихо наблюдали издали, но недавние попытки растревожить стихийных духов ветра у древних камней сделали их активной угрозой.",al={"what is the cult","who are al'aketh","al'aketh cult","что за культ","кто такие ал'акет","культ ал'акет"}},{q="Почему Рориан не удивился новостям?",a="Рориан и руководство рощи уже знали о передвижениях культа по острову, но раньше предпочитали тихо наблюдать за ним, а не противостоять напрямую.",al={"did rorian know","rorian reaction","why unsurprising","знал ли рориан","реакция рориана","почему не удивился"}},{q="Что происходит после доклада Рориану?",a="Приняв ваш доклад и поблагодарив за помощь Тендалской роще, Рориан посылает вас к Этину Бурь, члену Совета старейшин, который наблюдал за вами.",al={"next quest","what follows return to rorian","after return to rorian","следующее задание","что после возвращения к рориану","после возвращения к рориану"}},{q="Почему Яла осталась?",a="Яла Ветростраж решила остаться на месте схватки, чтобы добить уцелевших врагов, а вас отправила вперед со срочными сведениями.",al={"why yala stays","where did yala go","yala windwatcher role","почему яла осталась","куда ушла яла","роль йалы ветростраж"}}},fp="16,323,13.301.0,33.337.1,35.120.0,38.125.0,21.215.0,41.185.0,44.177.1,25.158.0"}
P.entries["quest:92470"] = {n="Нечистая матриарх",s="«Нечистая матриарх» — испытание на выживание, которое Этин Бурь дает начинающим посвященным в деревне Тендал. Нужно спуститься в южные пещеры, перебить падальщиков урсера и убить их свирепую мать-вожачиху Урс'ану. Выполнив охоту, искатель приключений доказывает, что у него хватит решимости встретить большие опасности острова Зефрис.",h="«Нечистая матриарх» — испытание на выживание, которое Этин Бурь дает начинающим посвященным в деревне Тендал.",kw={"aetheen of the gales","foul matriarch","thendal cave","thendal grove","thendal village","urs'anah","ursera","zephras isle","этин бурь","нечистая матриарх","тендалская пещера","тендалская роща","деревня тендал","урс'ана","урсера","остров зефрис"},ang={["class:Hunter"]="Выследить свирепую пещерную матриарха вроде Урс'аны — суровое испытание знания зверей и боевой решимости для начинающих охотников.",["race:Skyborne"]="Для посвященных Небожителей победа над наземными хищниками вроде Урс'аны демонстрирует самостоятельность на земле и готовность выйти за пределы своего уединенного начала."},sec={{t="Испытание решимости",b="Этин Бурь приглядывает за новичками, осваивающимися у деревни Тендал. Когда посвященный показывает первые успехи, Этин назначает опасный обряд посвящения: прямое нападение на хищных зверей, угрожающих окраинам. Посвященного отправляют не просто сражаться на открытых тропах, а в темные пещеры на юге, чтобы проредить стаи урсера и сразиться с их маткой."},{t="Угроза Урс'аны",b="The local rangers have long noted the ferocity of the ursera, but none poses a greater threat to the haven than Urs'anah, their formidable matriarch. Sheltered deep within Thendal Cave, she directs her scavengers and aggressively defends her lair. Bringing back her severed head serves as definitive proof that an adventurer is capable of handling ferocious beasts and is ready to push beyond the borders of the starting grove."}},faq={{q="Кто поручает убить Урс'ану?",a="Этин Бурь предлагает испытание в деревне Тендал. Она присматривает за многообещающими новичками, привлекшими внимание местных вроде Рориана, прежде чем проверить их доблесть этой опасной охотой.",al={"who gives foul matriarch","foul matriarch quest giver","who is aetheen of the gales","кто дает нечистая матриарх","выдающий задание нечистая матриарх","кто такая этин бурь"}},{q="Где найти Урс'ану и падальщиков урсера?",a="Урс'ана и падальщики урсера обитают в пещерах к югу и юго-западу от деревни Тендал, в холмах Тендалской рощи. Сама матриарх устроила логово в глубине пещеры.",al={"urs'anah location","where is ursanah","ursera cave zephras","thendal cave location","местонахождение урс'аны","где урсана","пещера урсера зефрис","местонахождение тендалской пещеры"}},{q="Что такое урсера?",a="Урсера — агрессивные хищники, похожие на медведей, обитающие в диких скалах острова Зефрис. Если их не сдерживать, их стаи падальщиков устраивают логова опасно близко к населенным поселениям вроде деревни Тендал.",al={"what is an ursera","ursera lore","are ursera bears","что такое урсера","предания об урсера","урсера медведи"}},{q="Что значит выполнение этой охоты для искателя приключений?",a="Убийство Урс'аны — важнейший обряд посвящения. Одолев и пришлых культистов, и самых опасных зверей рощи, охотник доказывает, что готов покинуть убежище деревни Тендал и взять на себя более широкую ответственность на острове Зефрис.",al={"why kill ursanah","importance of foul matriarch","зачем убивать урсану","важность нечистая матриарх"}}},fp="14,358,17.444.0,22.427.0,38.202.0,54.220.0,18.209.0,57.267.0"}
P.entries["quest:92471"] = {n="Этин Бурь",kw={"aetheen of the gales","council of elders","rorian the dayseeker","shen'dorei","thendal grove","zephras isle","этин бурь","совет старейшин","рориан искатель дня","шен'дор","тендалская роща","остров зефрис"},sec={{t="Мера потенциала",b="Первые поручения новичкам на острове Зефрис — не просто будничные дела, а неформальные проверки того, есть ли у растущей молодежи стойкость и дух, нужные для защиты родины. Понимая, что жизнь на острове сталкивается с растущими испытаниями, наставники вроде Рориана Искателя Дня приглядывают за кандидатами, способными нести большую ответственность."},{t="Читающая ветра из Тендалской рощи",b="В глубине Тендалской рощи пребывает Этин Бурь, уважаемый член Совета старейшин, управляющего островом Зефрис. Она проводит время, читая течения воздуха и оценивая молодых шен'дор, достигающих зрелости. Предстать перед ней — значит, что посвященный перерос мелкие дозорные обязанности и готов встретить прямые угрозы общине."}},faq={{q="Кто такая Этин Бурь?",a="Этин Бурь — руководительница на острове Зефрис и действующий член Совета старейшин. Она следит за ветрами в Тендалской роще и лично оценивает молодых шен'дор, достигших зрелости, чтобы убедиться, что они готовы защищать свой дом.",al={"who is aetheen","aetheen of the gales role","aetheen zephras","кто такая этин","роль этин бурь","этин зефрис"}},{q="Why does Rorian send players to meet Aetheen?",a="Rorian the Dayseeker evaluates novice adventurers through their early duties. Once an adventurer proves their capability and resilience, Rorian directs them to Aetheen so their skills can be judged and directed toward higher-level challenges facing the island.",al={"why meet aetheen","rorian sends to aetheen","purpose of this quest","зачем встречаться с этин","рориан посылает к этин","цель задания"}},{q="Где найти Этин Бурь?",a="Ее можно найти в Тендалской роще на острове Зефрис, где она изучает течение ветров и руководит испытаниями зрелости местной молодежи.",al={"aetheen location","where is aetheen","thendal grove aetheen","местонахождение этин","где этин","тендалская роща этин"}},{q="Что такое Совет старейшин?",a="Совет старейшин — управляющий орган, направляющий шен'дор на острове Зефрис. Лидеры вроде Этин входят в этот совет, чтобы заботиться о выживании, руководстве и готовности своей общины.",al={"council of elders zephras","who rules zephras","совет старейшин зефрис","кто правит зефрисом"}},{q="Что происходит после доклада Этин?",a="Upon confirming a young adventurer's willingness to serve Zephras Isle, Aetheen assigns serious tasks to address local wilderness dangers, beginning with threats like aggressive wildlife and foul matriarchs.",al={"next quest after aetheen","what does aetheen want","следующее задание после этин","чего хочет этин"}},{q="Что значит «достичь зрелости» для шен'дор на острове Зефрис?",a="Для молодежи острова Зефрис достижение зрелости — это доказательство себя в физических и магических испытаниях. Это не просто церемония: молодые шен'дор должны показать практические способности старейшине острова вроде Этин, прежде чем вступить на службу.",al={"shen'dorei coming of age","zephras coming of age","зрелость шен'дор","зрелость зефрис"}}},fp="20,339,22.384.0,32.371.0,28.241.0,45.260.0,40.155.0,30.195.0,40.207.0,62.260.0"}
P.entries["quest:92472"] = {n="Следующий шаг",s="Когда непосредственные угрозы со стороны зверей около деревни Тендал устранены, старейшина Этин Бурь направляет путников на юг, в деревню Шен'дар. Это путешествие знаменует переход от истребления диких зверей к борьбе с организованным фанатизмом культа Ал'акет, почитающего Повелителя ветра Ал'акира.",h="Когда непосредственные угрозы со стороны зверей около деревни Тендал устранены, старейшина Этин Бурь...",kw={"aetheen of the gales","al'aketh cult","al'akir","constable aonda","shen'dar village","skywall","thendal village","zephras isle","этин бурь","культ ал'акет","ал'акир","констебль аонда","деревня шен'дар","небесная высь","деревня тендал","остров зефрис"},ang={["class:Shaman"]="Шаманы поймут опасность слепого поклонения смертных стихийным владыкам вроде Ал'акира, чья переменчивая натура часто требует рабства, а не равновесия.",["race:Skyborne"]="Для Небожителей борьба с Ал'акет — прямое противостояние стихийному фанатизму, угрожающему безопасности их родных поселений на острове Зефрис."},sec={{t="Уход из деревни Тендал",b="Показав себя против местных хищников и матриархов, терзающих северную глушь острова Зефрис, искатели приключений призываются к более широким обязанностям. Старейшина Этин Бурь понимает, что простое истребление вредителей вторично по сравнению с настоящей опасностью, пускающей корни по всему острову. Чтобы защитить жителей острова, способных защитников нужно отправить на помощь дальним поселениям."},{t="Нависшая тень культа",b="Главная опасность южного Зефриса — культ Ал'акет. Эти беспощадные фанатики посвящают себя Ал'акиру, Повелителю ветра, правителю стихийного мира Небесной выси. Их растущая сила — прямая угроза деревне Шен'дар. В ответ Этин посылает путников на юг по дороге, мимо притаившихся в нагорье засадников, усилить местную стражу констебля Аонды."}},faq={{q="Куда ведет это путешествие?",a="Дорога ведет на юг от деревни Тендал в Шен'дарское нагорье и заканчивается в деревне Шен'дар, где констебль Аонда руководит местной обороной.",al={"where do i go","next hub","destination","куда идти","следующий узел","пункт назначения"}},{q="Кто такая констебль Аонда?",a="Констебль Аонда — гражданская и военная власть, поддерживающая порядок в деревне Шен'дар; сейчас ей поручено защищать поселение от растущих угроз культистов.",al={"constable aonda","who is aonda","констебль аонда","кто такая аонда"}},{q="Что такое культ Ал'акет?",a="Ал'акет — жестокие фанатики на острове Зефрис, поклоняющиеся Ал'акиру, Повелителю ветра, стихийному владыке Небесной выси. Их агрессивный рост — прямая угроза поселениям острова.",al={"who are the al'aketh","al'aketh cult lore","cultists","кто такие ал'акет","предания о культе ал'акет","культисты"}},{q="Кто такой Ал'акир?",a="Ал'акир, Повелитель ветра, — стихийный правитель небес и владыка Небесной выси, почитаемый воздушными элементалями и фанатично обожаемый культом Ал'акет.",al={"who is alakir","windlord","skywall ruler","кто такой ал'акир","повелитель ветра","правитель небесной выси"}},{q="Почему старейшина Этин отправляет путников из Тендала?",a="Когда непосредственные угрозы у Тендала устранены, Этин направляет проверенных защитников в деревню Шен'дар, где агрессивное наступление культа Ал'акет представляет куда большую опасность для всего острова.",al={"why leave thendal","aetheen's goal","зачем уходить из тендала","цель этин"}},{q="Какие опасности ждут на дороге в деревню Шен'дар?",a="Тропа на юг проходит через Шен'дарское нагорье, где засадники Ал'акет и отбившиеся головорезы культа донимают путников, идущих между поселениями острова.",al={"road hazards","traveling south","highland danger","опасности дороги","путь на юг","опасность нагорья"}}},fp="13,301,23.394.0,30.408.0,29.148.0,23.168.0,26.187.0,15.153.0,56.201.0,52.161.0"}
P.entries["quest:92473"] = {n="Агрессивное вторжение",s="«Агрессивное вторжение» — задание, которое выдает Валрея Долинный Ветер, чтобы защитить местное поселение от обезумевших от голода животных. Урсеры из ближайшего логова становятся все смелее: они забредают в деревню и угрожают ее жителям.",h="«Агрессивное вторжение» — задание, которое выдает Валрея Долинный Ветер, чтобы защитить местное поселение от...",kw={"claws","elder tree","encroachment","scrawny ursera","thendal grove","ursera","valreaa valewind","когти","древнее дерево","вторжение","тощие урсеры","тендалская роща","урсеры","валрея долинный ветер"},ang={["class:Druid"]="Друиды распознают нарушение хрупкого равновесия рощи: внезапная агрессия и истощение местных урсер указывают на незримое возмущение в местной экосистеме.",["class:Hunter"]="Охотники сразу поймут опасность голодающих хищников: гонимые голодом, отчаявшиеся звери теряют природную осторожность перед поселениями гуманоидов."},sec={{t="Отчаявшиеся хищники",b="Популяция урсер, гнездящаяся к юго-западу от деревни, стала серьезной угрозой безопасности. Недавно голодный молодой зверь подошел прямо к главному древнему дереву деревни и едва не растерзал играющего рядом маленького ребенка. Следопытам поселения пришлось убить зверя, прежде чем случилась беда."},{t="Отстрел в роще",b="Понимая, что голод толкает этих хищников нападать на обитаемые земли, следопыты приказали отстрелять самых тощих урсер в Тендалской роще. Уничтожив изможденных и отчаявшихся зверей, бродящих у логовищ, Стражи рощи надеются остановить дальнейшее вторжение, пока не выяснят, что тревожит местных животных."}},faq={{q="Кто выдает задание «Агрессивное вторжение»?",a="Задание выдает Валрея Долинный Ветер, одна из предводителей следопытов, которая присматривает за рощей и защищает ближайшее поселение от хищных зверей.",al={"who gives aggressive encroachment","quest giver","valreaa valewind quest","кто выдает агрессивное вторжение","персонаж, выдающий задания","задание валреи долинный ветер"}},{q="Почему урсеры забредают так близко к деревне?",a="Урсеры страдают от голода и отчаяния, и это гонит их далеко за пределы привычных охотничьих угодий, в самое сердце поселения.",al={"why ursera attack","ursera aggression","why are ursera mad","почему урсеры нападают","агрессия урсер","почему урсеры злые"}},{q="Где можно найти тощих урсер?",a="Тощие урсеры бродят по Тендалской роще к юго-западу от деревни, задерживаясь снаружи у входов в свое логово, а не в глубине пещеры.",al={"where are scrawny ursera","ursera location","thendal grove bears","где тощие урсеры","где урсеры","медведи тендалской рощи"}},{q="Какая едва не случившаяся беда стала причиной отстрела?",a="Молодая урсера подошла прямо к древнему дереву в центре деревни и попыталась напасть на играющего рядом мальчика. Следопыты убили зверя в последний момент и спасли мальчику жизнь.",al={"ursera attack boy","what happened in the village","boy near elder tree","урсера напала на мальчика","что случилось в деревне","мальчик у древнего дерева"}},{q="Почему урсеры ведут себя так странно?",a="Следопыты заметили, что в последнее время урсеры стали необычно агрессивными, но первопричина внезапной нехватки пищи и перемены в поведении остается неясной.",al={"what changed with ursera","why ursera starving","что изменилось с урсерами","почему урсеры голодают"}},{q="Какое доказательство требует Валрея Долинный Ветер?",a="Валрея просит принести шесть когтей тощей урсеры, взятых у изможденных зверей, бродящих по роще, чтобы убедиться, что опасные хищники истреблены.",al={"what do I collect","aggressive encroachment objective","что собирать","цель агрессивного вторжения"}}},fp="23,232,19.322.0,17.371.0,35.155.0,53.155.0,38.150.0,37.189.0,43.186.0,41.151.0"}
P.entries["quest:92481"] = {n="Ученик тайной магии",s="«Ученик тайной магии» — вводное испытание и призыв для начинающих заклинателей на Острове Зефрис. Его начинает Рориан Искатель Дня, когда новички доказывают свою базовую выдержку; юным магам предстоит изучить Сияющий кристалл возвращения и доложить местному наставнику, Дории Яркий Шепот.",h="«Ученик тайной магии» — вводное испытание и призыв для начинающих заклинателей на Острове Зефрис.",kw={"dorii brightwhisper","glowing recall crystal","mage quest","rorian the dayseeker","student of the arcane","thendal grove","vuldren","zephras isle","дория яркий шепот","сияющий кристалл возвращения","задание мага","рориан искатель дня","ученик тайной магии","тендалская роща","вульдрены","остров зефрис"},ang={["class:Mage"]="Это задание знаменует официальное начало обучения мага у Дории Яркий Шепот и представляет ваш магический путь как усилие по возрождению давно утраченных тайн магии облаков.",["race:Skyborne"]="Дория подчеркивает, что тысячелетия изоляции среди облаков привели к упадку традиций тайной магии, и потому молодые ученики играют главную роль в возрождении культурного наследия."},sec={{t="Послание в кристалле",b="Помогнув справиться с докучливыми вульдренами возле Тендалской рощи, начинающим магам доверяют любопытный артефакт — Сияющий кристалл возвращения. Кристалл, оставленный Дорией Яркий Шепот, местным наставником по тайной магии, служит магически записанным посланием, призванным проверить способности новичка и приобщить его к более глубокому изучению магии."},{t="Заново открывая тайную магию",b="По словам Дории Яркий Шепот, мастерство в тайной магии постепенно угасало среди ее народа за долгие тысячелетия уединения высоко в облаках. Дория считает каждого нового ученика не просто студентом, а важным первопроходцем, призванным вернуть утраченные знания и восстановить былое могущество магического наследия своего народа."}},faq={{q="Что такое Сияющий кристалл возвращения?",a="Сияющий кристалл возвращения — небольшой магический фокус, который Дория Яркий Шепот доверила Рориану Искателю Дня. В нем хранится записанное послание, призванное познакомить юных учеников с основами тайной связи.",al={"recall crystal","crystal message","what does the crystal do","кристалл возвращения","послание в кристалле","что делает кристалл"}},{q="Кто такая Дория Яркий Шепот?",a="Дория Яркий Шепот — местный учитель магов, чье жилище находится в здании позади Рориана Искателя Дня в Тендалской роще на Острове Зефрис. Дория наставляет молодых магов, стремящихся вернуть древние традиции тайной магии своего народа.",al={"who is dorii","mage trainer zephras","dorii location","кто такая дория","учитель магов зефрис","где дория"}},{q="Почему тайная магия ослабла среди жителей Зефрис?",a="Как объясняет Дория, тайные искусства постепенно пришли в упадок за тысячи лет, пока ее народ жил уединенно в облаках. Поэтому наставники вроде Дории охотно обучают новичков, чтобы те искали и возвращали утраченное.",al={"why did magic fade","skyborne arcane lore","lost arcane magic","почему угасла магия","тайные знания небожителей","утраченная тайная магия"}},{q="Кто выдает это задание?",a="Рориан Искатель Дня выдает это задание в Тендалской роще на Острове Зефрис, когда начинающий маг выполнит предварительное задание «Гармония в равновесии».",al={"quest giver","who starts a student of the arcane","rorian quest","персонаж, выдающий задания","кто начинает ученика тайной магии","задание рориана"}},{q="Где найти Дорию Яркий Шепот?",a="Дория Яркий Шепот живет в здании прямо позади Рориана Искателя Дня в Тендалской роще.",al={"dorii brightwhisper location","where is the mage trainer","find dorii","где дория яркий шепот","где учитель магов","найти дорию"}},{q="Что нужно выполнить перед началом этого задания?",a="Сначала необходимо выполнить задание «Гармония в равновесии», в котором нужно разобраться с местной проблемой вульдренов для Рориана Искателя Дня.",al={"prereq","prerequisites","what quest comes before","предыдущее задание","требования","какое задание раньше"}}},fp="23,290,20.366.0,24.333.0,35.224.0,27.223.0,55.245.0,21.150.0,37.103.0,63.121.0"}
P.entries["quest:92482"] = {n="Путь охотника",s="«Путь охотника» — вводное учебное задание для начинающих охотников в Тендалской роще на Острове Зефрис. Доказав свою доблесть в борьбе с местной угрозой вульдренов, юные следопыты получают от Рориана Искателя Дня указание явиться к Тай'ри Дальнозоркой, чтобы начать официальное обучение.",h="«Путь охотника» — вводное учебное задание для начинающих охотников в Тендалской роще на Острове Зефрис.",kw={"hunter trainer","rorian the dayseeker","scribbled note","tai'ree farsight","the way of the hunter","thendal grove","vuldren","zephras","учитель охотников","рориан искатель дня","нацарапанная записка","тай'ри дальнозоркая","путь охотника","тендалская роща","вульдрены","зефрис"},ang={["class:Hunter"]="Это задание служит важнейшим обрядом посвящения для начинающих охотников на Острове Зефрис, закрепляя их обучение у Тай'ри Дальнозоркой."},sec={{t="Призыв на охоту",b="Вернувшись после сокращения числа докучливых вульдренов, бродивших на окраинах Тендалской рощи, юные охотники обнаруживают, что их практические навыки привлекли внимание местных. Рориан Искатель Дня передает нацарапанный призыв от Тай'ри Дальнозоркой, местной наставницы охотников. Для начинающих следопытов, выходящих в дикие края Острова Зефрис, это стало переходом от простой обороны острова к настоящему боевому обучению и урокам выживания."},{t="Наставничество Тай'ри",b="Тай'ри Дальнозоркая, которую можно найти в центре деревни, встречает многообещающих учеников суровым реализмом. Подчеркивая, что для жизни в дикой природе нужны острые чувства и молниеносные рефлексы, она делится советами, рожденными ее долгим опытом. Ее наставничество — основа для любого островного следопыта, желающего отточить меткость и навыки выживания."}},faq={{q="Кто выдает это задание?",a="Рориан Искатель Дня выдает это задание в Тендалской роще на Острове Зефрис после того, как вы поможете ему справиться с нашествием вульдренов в задании «Гармония в равновесии».",al={"who gives the way of the hunter","quest starter","rorian quest","кто выдает путь охотника","начало задания","задание рориана"}},{q="Кто такая Тай'ри Дальнозоркая?",a="Тай'ри Дальнозоркая — местная наставница охотников в Тендалской роще, находящаяся в центре деревни. Она руководит обучением и дисциплиной начинающих стрелков и островных следопытов.",al={"where is tai'ree","hunter trainer thendal grove","tai'ree farsight location","где тай'ри","учитель охотников тендалская роща","где тай'ри дальнозоркая"}},{q="Для чего нужна Нацарапанная записка?",a="Нацарапанная записка — послание, оставленное Тай'ри Дальнозоркой, пока вы расправлялись с вульдренами. В ней сказано найти ее лично на деревенской площади, чтобы начать углубленное обучение.",al={"scribbled note","what does the note say","hunter note","нацарапанная записка","что в записке","записка охотника"}},{q="Где происходит это задание?",a="Это задание целиком проходит в Тендалской роще — форпосте-поселении на Острове Зефрис.",al={"quest zone","hunter quest location","where is thendal grove","зона задания","где задание охотника","где тендалская роща"}},{q="Что нужно выполнить перед этим заданием?",a="Сначала необходимо выполнить для Рориана Искателя Дня задание «Гармония в равновесии», доказав свою начальную пригодность борьбой с агрессивными вульдренами возле рощи.",al={"prereq for the way of the hunter","how to unlock","previous quest","требования к пути охотника","как открыть","предыдущее задание"}},{q="Чему Тай'ри Дальнозоркая учит новых охотников?",a="Тай'ри Дальнозоркая — ваш учитель класса. Беседа с ней знакомит с основной философией островного следопытства и открывает доступ к базовым способностям и боевым приемам охотника.",al={"what does tai'ree do","why talk to tai'ree","чему учит тай'ри","зачем говорить с тай'ри"}}},fp="21,298,21.442.0,23.374.0,21.161.0,24.190.0,42.192.0,33.101.0,54.157.0,45.185.0"}
P.entries["quest:92483"] = {n="Как дома в тени",s="«Как дома в тени» — вводное задание разбойников на острове Зефрис. Помогнув Рориану Искателю Дня в Тендалской роще, начинающие разбойники получают указание прочитать вызов и встретиться со своим наставником класса, Акери Темным Клинком. Это задание знаменует переход юных разбойников от обычных деревенских дел к серьезному обучению скрытности и бою.",h="«Как дома в тени» — вводное задание разбойников на острове Зефрис.",kw={"akeri duskblade","at home in the shadows","rogue quest","rogue trainer","rorian the dayseeker","simple note","thendal grove","zephras isle","акери темный клинок","как дома в тени","задание разбойника","учитель разбойников","рориан искатель дня","простая записка","тендалская роща","остров зефрис"},ang={["class:Rogue"]="Это задание начинает ваше официальное обучение разбойника на острове Зефрис и знакомит вас с Акери Темным Клинком в сторожевой башне Тендалской рощи."},sec={{t="Подозрительное приглашение",b="Пока юные разбойники справляются с обычными угрозами вокруг Тендалской рощи, они привлекают внимание Акери Темного Клинка, местного учителя разбойников. Вместо того чтобы открыто появляться в поселении, Акери передает простую записку через Рориана Искателя Дня. Рориан понимает, что, несмотря на подозрительные манеры, наставник знает практические навыки, необходимые для выживания за пределами защищенных границ рощи."},{t="Уроки в сторожевой башне",b="Акери Темный Клинок, обосновавшийся в сторожевой башне деревни, не любит тратить слова впустую. Он сразу оценивает походку и внимательность каждого новичка и предупреждает, что неуклюжая поступь за пределами Тендалской рощи ведет прямиком в могилу. Пройдя проверку Акери, разбойник делает первый официальный шаг к овладению скрытностью, точностью и выживанием на острове Зефрис."}},faq={{q="Кто выдает задание «Как дома в тени»?",a="Рориан Искатель Дня предлагает задание в Тендалской роще на острове Зефрис после того, как вы выполните «Гармонию в равновесии».",al={"who starts at home in the shadows","quest giver at home in the shadows","rorian quest","кто начинает как дома в тени","персонаж, выдающий задание как дома в тени","задание рориана"}},{q="Где найти Акери Темного Клинка?",a="Акери Темный Клинок находится в сторожевой башне деревни в Тендалской роще на острове Зефрис.",al={"akeri duskblade location","where is akeri duskblade","find akeri","где акери темный клинок","акери темный клинок местонахождение","найти акери"}},{q="Что такое «Простая записка», которую дают во время задания?",a="Простая записка — это послание Акери Темного Клинка с просьбой о встрече с многообещающими разбойниками. Чтобы выполнить задачу, прочитайте ее до разговора с Акери.",al={"simple note zephras","what is the note","read simple note","простая записка зефрис","что за записка","прочитать простую записку"}},{q="Доступно ли это задание всем классам?",a="Нет, это задание предназначено только для разбойников, осваивающих ремесло в Тендалской роще.",al={"can non rogues do this quest","is at home in the shadows rogue only","class requirement","могут ли не разбойники выполнить задание","как дома в тени только для разбойников","требования к классу"}},{q="Чему учит Акери Темный Клинок?",a="Акери Темный Клинок — местный учитель разбойников в Тендалской роще. Он обучает новичков, начинающих путь по острову Зефрис, скрытности, хитрости и владению клинком.",al={"akeri duskblade role","who is akeri","rogue trainer thendal grove","роль акери темного клинка","кто такой акери","учитель разбойников тендалская роща"}},{q="Какое предыдущее задание нужно выполнить?",a="Сначала нужно выполнить для Рориана Искателя Дня задание «Гармония в равновесии», и только потом он передаст вам записку Акери.",al={"at home in the shadows prerequisite","previous quest","unlock at home in the shadows","как дома в тени предыдущее задание","предыдущее задание","открыть как дома в тени"}}},fp="22,341,18.406.0,25.391.0,43.111.0,33.90.0,47.168.0,39.89.0,32.182.0,48.103.0"}
P.entries["quest:92484"] = {n="Единение со стихиями",s="«Единение со стихиями» — вводное задание шаманов в Тендалской роще на острове Зефрис. Его выдает Рориан Искатель Дня и направляет юных последователей к Ветроводу Боро, местному учителю шаманов. Оно раскрывает безмолвный разлад между местными жителями и духами стихий ветров.",h="«Единение со стихиями» — вводное задание шаманов в Тендалской роще на острове Зефрис.",kw={"embracing the elements","humming recall crystal","rorian the dayseeker","shaman","spirits of the four winds","thendal grove","windshaper boro","zephras isle","единение со стихиями","гудящий кристалл возвращения","рориан искатель дня","шаман","духи четырех ветров","тендалская роща","ветровод боро","остров зефрис"},ang={["class:Shaman"]="Это задание — первое официальное знакомство новичка с Ветроводом Боро. Оно рассказывает о трагическом молчании стихийных ветров и о пожизненном стремлении восстановить единение.",["faction:Horde"]="Для путешественников из Орды на острове Зефрис это задание раскрывает особые трудности местных заклинателей стихий в сравнении с привычными традициями земли и духов на материке."},sec={{t="Призыв стихий",b="После того как начинающие шаманы помогают справиться с вульдренами, досаждающими деревне, к ним обращается Рориан Искатель Дня. Пока они были в отлучке, Ветровод Боро оставил гудящий кристалл возвращения — знак того, что пора начинать официальное обучение стихиям в центре рощи."},{t="Безмолвные ветры",b="При встрече Ветровод Боро рассказывает о тяжелом положении местного шаманизма. Духи четырех ветров внезапно прервали общение много лет назад, оставив прежнее единение. Теперь шаманы Зефриса посвящают себя глубокому изучению природы и строгими тренировками стремятся преодолеть тишину и вновь склонить духов к диалогу."}},faq={{q="Кто выдает задание «Единение со стихиями»?",a="Задание выдает Рориан Искатель Дня в Тендалской роще на острове Зефрис сразу после того, как вы поможете справиться с местными вульдренами.",al={"embracing the elements quest giver","who starts embracing the elements","единение со стихиями персонаж, выдающий задание","кто начинает единение со стихиями"}},{q="Где находится Ветровод Боро?",a="Ветровод Боро находится возле центра Тендалской рощи на острове Зефрис и служит учителем шаманов поселения.",al={"windshaper boro location","where is boro","find windshaper boro","ветровод боро местонахождение","где боро","найти ветровода боро"}},{q="Почему духи стихий перестали говорить с местными жителями?",a="По словам Ветровода Боро, духи стихий внезапно прекратили всякое общение и покинули людей много лет назад. Местные шаманы до конца не понимают, почему произошел разрыв, но продолжают учиться в надежде восстановить утраченную связь.",al={"why are the winds silent","spirits of the four winds silent","what happened to the wind spirits","почему ветры молчат","духи четырех ветров молчат","что случилось с духами ветра"}},{q="Что такое «Гудящий кристалл возвращения»?",a="Гудящий кристалл возвращения — предмет, который оставил Ветровод Боро, пока вы помогали поселению. Осмотрев его, вы показываете готовность начать обучение стихиям под руководством Боро.",al={"humming recall crystal","recall crystal zephras","гудящий кристалл возвращения","кристалл возвращения зефрис"}},{q="Какое задание предшествует «Единению со стихиями»?",a="Оно следует за заданием «Гармония в равновесии», в котором вы разбираетесь с вульдренами, тревожащими окрестности.",al={"embracing the elements prequest","what comes before embracing the elements","единение со стихиями предыдущее задание","что перед единением со стихиями"}},{q="Какую роль играет Ветровод Боро в Тендалской роще?",a="Ветровод Боро — учитель шаманов общины. Он наставляет новичков в единении со стихиями и изучении природы.",al={"what does boro do","windshaper boro role","чем занимается боро","роль ветровода боро"}}},fp="22,301,25.298.0,16.367.0,43.140.0,33.129.0,63.252.0,35.199.0,56.105.0,53.138.0"}
P.entries["quest:92485"] = {n="Ученик природы",s="«Ученик природы» — первое знакомство начинающего друида с официальным обучением на острове Зефрис. После восстановления местной гармонии новичков вызывает Ксайтон Серебряный Ветер под сенью Тендалской рощи. Это начало пути к пониманию глубокого равновесия между растительным и животным миром острова.",h="«Ученик природы» — первое знакомство начинающего друида с официальным обучением на острове Зефрис.",kw={"druid","folded parchment","rorian the dayseeker","thendal grove","vuldren","xyton silverwind","zephras isle","друид","сложенный пергамент","рориан искатель дня","тендалская роща","вульдрен","ксайтон серебряный ветер","остров зефрис"},ang={["class:Druid"]="Этот обряд посвящения напрямую связывает вас с Ксайтоном Серебряным Ветром и начинает ваше пожизненное обучение искусству дикой природы, клыка и ветви."},sec={{t="Зов рощи",b="Когда беспокойство, вызванное слишком ретивыми зверями, улажено, Рориан Искатель Дня передает юным новичкам личный вызов. Сложенный пергамент, оставленный местным наставником Ксайтоном Серебряным Ветром, приглашает начинающих друидов выйти вперед и посвятить себя глубоким тайнам природы. Это знак того, что природные таланты новичка привлекли внимание старейшин рощи."},{t="Хранители гобелена",b="Встреча с Ксайтоном Серебряным Ветром на нижнем уровне большого дерева в Тендалской роще укрепляет новичка в его призвании. Серебряный Ветер видит в пышной флоре и фауне острова Зефрис сложный живой гобелен, требующий постоянной охраны и бдительного равновесия. Чтобы идти путем клыка, когтя, пера и ветви, нужно долгое наставничество, и эта встреча становится истинным началом такого пожизненного служения."}},faq={{q="Кто направляет игрока к Ксайтону Серебряному Ветру?",a="Рориан Искатель Дня передает сложенный пергамент, который направляет вас к Ксайтону Серебряному Ветру, после того как вы поможете разобраться с вульдренами вокруг рощи.",al={"who gives a student of nature","quest giver","rorian","кто дает ученик природы","персонаж, выдающий задание","рориан"}},{q="Где находится Ксайтон Серебряный Ветер?",a="Ксайтон Серебряный Ветер живет на первом этаже большого дерева в Тендалской роще, прямо позади Рориана Искателя Дня на острове Зефрис.",al={"xyton silverwind location","where is xyton","druid trainer location","ксайтон серебряный ветер местонахождение","где ксайтон","учитель друидов"}},{q="Для чего нужно это задание?",a="Это задание знакомит начинающих друидов с их учителем класса, Ксайтоном Серебряным Ветром, главным наставником и проводником в поддержании природного равновесия острова Зефрис.",al={"why do this quest","quest goal","druid training start","зачем выполнять задание","цель задания","начало обучения друида"}},{q="Чему Ксайтон Серебряный Ветер учит начинающих друидов об острове Зефрис?",a="Серебряный Ветер учит, что растения и животные острова образуют хрупкий взаимосвязанный гобелен, требующий активной заботы и равновесия через дисциплину клыка, когтя, пера и ветви.",al={"what does xyton say","zephras nature balance","druid role zephras","чему учит ксайтон","природное равновесие зефрис","роль друида зефрис"}},{q="Что нужно выполнить перед получением этого вызова?",a="Новички должны сначала выполнить для Рориана Искателя Дня задание «Гармония в равновесии» и усмирить буйных вульдренов, после чего получат записку Серебряного Ветра.",al={"prereq quest","prior quest","before student of nature","предыдущее задание","прошлое задание","перед ученик природы"}},{q="Что написано в сложенном пергаменте?",a="Сложенный пергамент — личная записка Ксайтона Серебряного Ветра, в которой он просит многообещающего юного друида найти его для дальнейшего обучения под кроной большого дерева.",al={"folded parchment note","silverwind note","what is on parchment","сложенный пергамент записка","записка серебряного ветра","что на пергаменте"}}},fp="19,323,24.408.0,23.428.0,41.149.0,34.139.0,34.175.0,66.196.0,66.153.0,46.175.0"}
P.entries["quest:92532"] = {n="Путь воина",s="«Путь воина» — вводное боевое задание для начинающих бойцов на острове Зефрис. Следуя указаниям Рориана Искателя Дня, юные воины направляются к Мастеру клинка Рен в сторожевой башне деревни Тендал. Рен готова дать боевую подготовку и воспитать дисциплину в тех, кто готов защищать свой народ.",h="«Путь воина» — вводное боевое задание для начинающих бойцов на острове Зефрис.",kw={"blademaster ren","crumpled note","rorian the dayseeker","thendal village","warrior's path","watchtower","zephras isle","мастер клинка рен","мятая записка","рориан искатель дня","деревня тендал","путь воина","сторожевая башня","остров зефрис"},ang={["class:Warrior"]="Это задание знаменует официальное начало вашего боевого обучения в деревне Тендал и знакомит вас с Мастером клинка Рен как с вашим наставником."},sec={{t="Вызов в сторожевую башню",b="Когда начинающие бойцы, восстановив равновесие поблизости, возвращаются к Рориану Искателю Дня в деревню Тендал, они узнают, что мастер клинка поселения заметила их. Рориан передает мятую записку, написанную самой Рен, с просьбой найти ее лично. Находясь высоко над поселением, в сторожевой башне деревни, Рен внимательно следит и за границами острова, и за новобранцами, которые однажды смогут их защищать."},{t="Мантия защиты",b="Достигнув сторожевой башни, воин знакомится с философией боя Мастера клинка Рен. Для Рен боевое мастерство — не просто грубая сила, а жизненно важный долг вести, выстаивать и защищать в мире, который становится все неопределеннее. Она обещает новобранцу наставничество по мере совершенствования его навыков и суровую подготовку, пока он не окрепнет настолько, чтобы встретить великие опасности, грозящие его дому."}},faq={{q="Кто посылает меня к Мастеру клинка Рен?",a="Рориан Искатель Дня направляет вас к Мастеру клинка Рен после того, как вы выполните поручения в деревне Тендал. Пока вас не было, Рен специально попросила Рориана отправить вас в ее сторожевую башню по возвращении.",al={"who starts this","quest giver","rorian role","кто начинает это","персонаж, выдающий задание","роль рориана"}},{q="Где найти Мастера клинка Рен?",a="Мастер клинка Рен находится в сторожевой башне деревни Тендал на острове Зефрис, откуда она присматривает за деревней и обучает начинающих бойцов.",al={"where is blademaster ren","ren location","thendal watchtower","где мастер клинка рен","рен местонахождение","сторожевая башня тендал"}},{q="Что такое «Мятая записка»?",a="Мятая записка — личный вызов, который Рориан передает вам от имени Мастера клинка Рен. В нем сказано прочитать записку и явиться в сторожевую башню деревни Тендал для официальной боевой подготовки.",al={"crumpled note","what does note say","ren note","мятая записка","что в записке","записка рен"}},{q="Чему Мастер клинка Рен учит юных воинов?",a="Мастер клинка Рен делает упор на бдительность, лидерство и защиту. Она напоминает ученикам, что по мере перемен в мире и роста опасностей воины должны обладать волей встать между опасностью и своим народом.",al={"ren teaching","what does ren train","warrior purpose","учение рен","чему учит рен","предназначение воина"}},{q="Обязательно ли это задание для обучения воинов на острове Зефрис?",a="Оно служит официальным знакомством с учителем вашего класса в деревне Тендал и указывает на Мастера клинка Рен, чтобы вы знали, куда возвращаться за новыми боевыми приемами.",al={"do i have to do this","warrior trainer intro","is it mandatory","обязательно ли это делать","знакомство с учителем воинов","обязательно ли"}},{q="Что имеет в виду Рен, говоря «пусть ветры ведут вас»?",a="Это традиционное благословение отражает культуру острова Зефрис: оно желает путникам безопасного пути, сосредоточенности и удачи при выходе в незнакомые и опасные земли.",al={"may the winds guide you meaning","wind quote","ren farewell","значение пусть ветры ведут вас","цитата о ветре","прощание рен"}}},fp="18,343,27.444.0,24.412.0,37.201.0,33.145.0,26.197.0,47.202.0,60.178.0,48.180.0"}
P.entries["quest:92544"] = {n="Головорезы из Ал'акета",s="Мирным дорогам вокруг Тендалской рощи угрожает жестокая банда культистов Ал'акета, засевшая в руинах храма неподалеку. Эти фанатики, посланные из Святилища Акира с приказом донимать странников и силой вербовать новичков, представляют непосредственную опасность для местных путников. Ханаа Ночной Ветер поручает искателям приключений сломить их власть и убить их грубого предводителя.",h="Мирным дорогам вокруг Тендалской рощи угрожает жестокая банда культистов Ал'акета, засевшая в руинах храма...",kw={"al'aketh brute","al'aketh neophyte","al'aketh thugs","hanaa nightwind","high priestess lorthuna","malduko cloudcrush","shrine of akir","thendal grove","громила ал'акета","неофит ал'акета","головорезы из ал'акета","ханаа ночной ветер","верховная жрица лортуна","малдуко сокрушитель облаков","святилище акира","тендалская роща"},sec={{t="Культисты-хулиганы в руинах",b="К юго-западу от Тендалской рощи лежат древние руины храма, которые должны были бы служить тихим приютом для странников. Вместо этого территорию захватил Ал'акет — агрессивный культ, движимый фанатичными амбициями. Эти культисты — вовсе не мирные поклонники: они действуют как разбойники и вышибалы и нападают на тех, кто идет по окраинам рощи. Стоящие неподалеку следопыты подозревают, что этих головорезов прислала верховная жрица Лортуна из Святилища Акира, чтобы запугать и принудить местных жителей склониться перед влиянием культа."},{t="Малдуко Сокрушитель Облаков",b="Сбродом в руинах храма заправляет Малдуко Сокрушитель Облаков — жестокий вожак, который насилием и страхом держит в повиновении и своих посвященных, и ничего не подозревающих странников. Под его началом ходят громилы и недавно обращенные неофиты, и Малдуко устроил агрессивный форпост прямо у порога Тендалской рощи. Убив Сокрушителя Облаков и рассеяв его подручных, Ханаа Ночной Ветер надеется подорвать уверенность культа и ясно дать понять, что фанатизм и принуждение в этих землях терпеть не станут."}},faq={{q="Кто такие Ал'акет?",a="Ал'акет — фанатичный культ, действующий на острове Зефрис. Под руководством таких фигур, как верховная жрица Лортуна из Святилища Акира, они силой, запугиванием и насилием вынуждают местных путников и жителей вступать в их ряды.",al={"what is the al'aketh","al'aketh cult","who are alaketh","кто такие ал'акет","культ ал'акет","ал'акет"}},{q="Почему культисты нападают на Тендалскую рощу?",a="Они устроили лагерь в руинах храма к юго-западу от Тендалской рощи, чтобы устраивать засады на путников, покидающих эту местность. Терроризируя странников на дороге, они надеются надавить на местных жителей и принудить их подчиниться культу.",al={"why are cultists here","why thendal grove","cultist motive","почему здесь культисты","почему тендалская роща","мотив культистов"}},{q="Кто такой Малдуко Сокрушитель Облаков?",a="Малдуко Сокрушитель Облаков — жестокий громила, возглавляющий лагерь Ал'акета в руинах храма. Ханаа Ночной Ветер называет его чудовищем; он командует громилами и неофитами, которые грабят путников на ближних дорогах.",al={"malduko","cloudcrush","who is malduko cloudcrush","малдуко","сокрушитель облаков","кто такой малдуко сокрушитель облаков"}},{q="Кто такая Ханаа Ночной Ветер?",a="Ханаа Ночной Ветер — одна из следопытов, охраняющих Тендалскую рощу. Она остается на своем посту у дороги, чтобы предупреждать путников о засаде культистов, и рассчитывает на способных искателей приключений, которые устранят угрозу.",al={"hanaa","hanaa nightwind","quest giver","ханаа","ханаа ночной ветер","персонаж, выдающий задания"}},{q="Кто послал этих культистов в руины?",a="Ханаа подозревает, что их направила верховная жрица Лортуна, которая руководит деятельностью культа из Святилища Акира.",al={"who commands them","cult leader","who sent malduko","кто ими командует","глава культа","кто послал малдуко"}},{q="Что еще можно найти возле руин храма?",a="Помимо лагеря Ал'акета, в древних руинах на юго-западном краю местности находится действующая линия силы.",al={"ruins ley line","temple ruins secret","ruins southwest","линия силы в руинах","тайна руин храма","юго-запад руин"}}},fp="14,388,29.542.0,18.527.0,21.243.0,45.230.0,26.195.0,23.212.0,37.117.0,45.124.0"}
P.entries["quest:92597"] = {n="Чтение линий силы",s="Чтение линий силы — обряд посвящения для молодых небожителей, открывающих свое наследие высокорожденных. По поручению Фалорна Падающего Ветра на острове Зефрис послушники отправляются к монолитам в Тендалской роще, чтобы почувствовать сырые потоки тайной магии, пронизывающие стихийную землю.",h="Чтение линий силы — обряд посвящения для молодых небожителей, открывающих свое наследие высокорожденных.",kw={"al'aketh","falorne fallwind","highborne","ley lines","reading the ley lines","skyborne","thendal grove","thendal standing stones","windshapers","zephras isle","ал'акет","фалорн падающий ветер","высокорожденные","линии силы","чтение линий силы","небожители","тендалская роща","тендалские монолиты","ваятели ветра","остров зефрис"},ang={["class:Mage"]="Для практиков тайных искусств открытые линии силы — бесценный источник необузданной мощи среди стихийных бурь.",["race:Skyborne"]="Этот обряд пробуждает ваше врожденное наследие высокорожденных и учит вас направлять подземную энергию линий силы прямо в заклинания."},sec={{t="Тайные потоки Элементального Плана",b="Даже в продуваемых ветрами пределах Элементального Плана под землей пролегают скрытые тайные каналы. Пока по острову Зефрис бродят странные элементали и враждебные культисты Ал'акета, подземные линии силы начали подниматься к поверхности. Для владеющих магией эти разрывы открывают прямой доступ к необузданным тайным источникам, дающим силу всякому, кто обладает нужной кровью и знаниями, чтобы направлять ее."},{t="Наследие высокорожденных",b="Фалорн Падающий Ветер призывает посвящаемых принять свое происхождение от высокорожденных, а не молить о милости духов ветра, подобно местным Ваятелям ветра или фанатикам Ал'акета. По мнению Падающего Ветра, выжить среди суровых сил Элементального Плана помогает не мольба о пощаде, обращенная к чуждым созданиям, а овладение тайной силой, текущей под ногами."},{t="Тендалские монолиты",b="К северо-востоку от поселения лежит Тендалская роща, где древние монолиты отмечают мощное слияние линий силы. Среди бушующих ветров и последователей Ал'акета эта открытая точка магического потока позволяет посвящаемым настроить чувства, войти в лад с пульсом линии силы и раскрыть весь потенциал своих природных расовых способностей."}},faq={{q="Кто выдает задание «Чтение линий силы»?",a="Задание выдает Фалорн Падающий Ветер на острове Зефрис молодым небожителям, которые учатся направлять доставшиеся им от предков тайные способности.",al={"quest giver","falorne fallwind","who starts reading the ley lines","персонаж, выдающий задания","фалорн падающий ветер","кто дает чтение линий силы"}},{q="Где находится линия силы?",a="Линия силы находится на северо-востоке, у Тендалских монолитов в Тендалской роще, среди враждебных элементалей и последователей Ал'акета.",al={"ley line location","where is thendal grove","thendal standing stones location","местонахождение линии силы","где тендалская роща","где тендалские монолиты"}},{q="Почему в Элементальном Плане есть линии силы?",a="Скрытые тайные каналы пронизывают землю даже здесь, в Элементальном Плане. Недавно эти линии силы начали прорываться на поверхность, давая небожителям прямой доступ к мощным потокам силы.",al={"arcane in elemental plane","ley lines elemental plane lore","тайная магия в элементальном плане","линии силы элементальный план"}},{q="Как Фалорн Падающий Ветер относится к Ваятелям ветра?",a="Фалорн презирает Ваятелей ветра: он считает их поклонение духам воздуха слабым вымаливанием у равнодушных стихийных существ, ничем не лучше поклонения Ал'акета.",al={"falorne on windshapers","windshapers lore","windshapers vs highborne","фалорн о ваятелях ветра","ваятели ветра","ваятели ветра и высокорожденные"}},{q="Какая способность нужна, чтобы направлять линию силы?",a="Для задания нужно применить расовую способность небожителей «Чтение линии силы», находясь в точке схождения энергии у монолитов.",al={"read ley line ability","how to read ley line","racial ability used","способность чтение линии силы","как читать линию силы","расовая способность"}},{q="Какую пользу дает обращение к линиям силы?",a="Единение с открытыми линиями силы направляет сырую тайную энергию в того, кто к ним обращается, усиливая его магическое могущество и давая разные эффекты в зависимости от природы источника.",al={"what do ley lines do","benefits of ley lines","что делают линии силы","польза линий силы"}}},fp="21,298,38.429.0,16.379.0,24.352.0,42.128.0,30.149.0,49.203.0,47.180.0,49.137.0,49.178.0"}
P.entries["quest:92598"] = {n="Дар небесного зрения",s="Дар небесного зрения — ранний обряд посвящения для молодых Ваятелей ветра, учащихся использовать свою врожденную связь с миром духов. Под руководством Вентаари Светлого Желания посвящаемые отправляются к Слиянию стихий, чтобы пробудить восприятие и напрямую слушать шепот духов.",h="Дар небесного зрения — ранний обряд посвящения для молодых Ваятелей ветра, учащихся использовать свою...",kw={"elemental convergence","elemental spirits","skysight","standing stones","thendal grove","ventaari brightwish","windshaper","zephras","слияние стихий","духи стихий","небесное зрение","монолиты","тендалская роща","вентаари светлое желание","ваятель ветра","зефрис"},ang={["class:Shaman"]="Шаманы распознают Слияние стихий как священную землю, где грань между волей смертных и планами стихий истончается сильнее всего.",["faction:Horde"]="Как союзница на острове Зефрис, Орда полагается на сверхъестественное предвидение Ваятелей ветра, чтобы избегать неизведанных опасностей острова.",["race:Skyborne"]="Для небожителей небесное зрение — не просто странный трюк, а право по рождению, дарованное покровителями-стихиями, на котором держится их культурная и духовная самобытность."},sec={{t="Священное восприятие",b="Ваятели ветра обладают врожденной связью со стихиями, формирующими их мир, воплощенной в священной способности, известной как небесное зрение. Этот дар позволяет смертным чувствам настроиться на духовные волны, соединяя живых и незримое. Ваятель ветра может призвать это внутреннее зрение где угодно, но возле средоточий силы связь крепнет, открывая отзывчивые блага и скрытую мудрость, шепчущую на ветру."},{t="Слияние стихий в Тендалской роще",b="К северо-востоку от поселения, среди древних монолитов, в Тендалской роще находится Слияние стихий. Такие места служат средоточиями, где собираются сырые энергии и задерживаются духи. Вентаари Светлое Желание посылает новичков к этому священному месту не просто ради выполнения задания, а чтобы испытать их духовную стойкость. Как и любая способность тела или разума, небесное зрение требует осознанных упражнений для развития, чтобы растущий Ваятель ветра мог толковать переменчивые знамения стихий, от которых зависит выживание его народа."}},faq={{q="Для чего нужно это задание?",a="Задание учит начинающих Ваятелей ветра практическому применению небесного зрения. Вентаари Светлое Желание направляет посвящаемых к Слиянию стихий, чтобы они узнали, как мощь окружения усиливает их духовные чувства.",al={"gift of skysight purpose","why do this quest","skysight training","цель дара небесного зрения","зачем это задание","обучение небесному зрению"}},{q="Кто такая Вентаари Светлое Желание?",a="Вентаари Светлое Желание — духовная наставница, которая руководит начальным обучением Ваятелей ветра на острове Зефрис и учит их уважать и развивать свое стихийное наследие.",al={"ventaari","who is ventaari brightwish","brightwish","вентаари","кто такая вентаари светлое желание","светлое желание"}},{q="Что такое Слияние стихий?",a="Слияние стихий — средоточие усиленной духовной энергии, часто отмеченное древними монолитами. Такие места естественным образом привлекают духов стихий и усиливают способности, например небесное зрение.",al={"what is elemental convergence","elemental convergence lore","thendal grove convergence","что такое слияние стихий","слияние стихий предания","слияние в тендалской роще"}},{q="Где находится Слияние стихий?",a="Слияние находится среди монолитов в Тендалской роще, к северо-востоку от поселения на острове Зефрис.",al={"where is the convergence","thendal grove location","standing stones location","где слияние","местонахождение тендалской рощи","где монолиты"}},{q="Можно ли использовать небесное зрение где угодно?",a="Да. Ваятель ветра может призвать небесное зрение где угодно, но в Слиянии стихий оно дает куда более мощное благо и позволяет услышать больше подсказок от близких духов.",al={"can i use skysight anywhere","skysight outside convergence","where to use skysight","можно ли использовать небесное зрение где угодно","небесное зрение вне слияния","где использовать небесное зрение"}},{q="Почему небесное зрение считается необходимым для выживания?",a="Небесное зрение соединяет смертных и духов стихий. По словам Вентаари, умение воспринимать предостережения стихий и прислушиваться к ним крайне важно, чтобы избегать надвигающихся опасностей и сохранить свой народ.",al={"why is skysight important","skysight survival","elements survival","почему важно небесное зрение","небесное зрение и выживание","выживание и стихии"}}},fp="20,306,19.463.0,32.541.0,34.233.0,27.175.0,33.203.0,43.126.0,30.178.0,50.219.0"}
P.entries["quest:926"] = {n="Треснувший камень силы",s="Глубоко в засушливых просторах Степей на тайных столах покоятся загадочные камни, наполненные тайной энергией. Эти нестабильные реликвии намеренно созданы со смертельными изъянами и быстро расходуют собственную силу, стоит их отделить от источника.",h="Глубоко в засушливых просторах Степей на тайных столах покоятся загадочные камни, наполненные тайной энергией.",kw={"arcane","barrens","flawed power stone","power stones","ritual table","volatile magic","тайная магия","степи","треснувший камень силы","камни силы","ритуальный стол","нестабильная магия"},ang={["faction:Horde"]="Орда настороженно следит за тайными диковинами, разбросанными по Степям, оберегаясь от безответственного колдовства, способного угрожать ее путям снабжения."},sec={{t="Опасное мастерство",b="Треснувшие камни силы, разбросанные по Степям, — любопытные магические аномалии. Хотя они несомненно заряжены тайной сущностью, их структуру намеренно нарушили при создании. Те, чьи руки их создали, позаботились о том, чтобы они оставались крайне нестабильными и превращались в инертную материю спустя считаные мгновения после того, как их взяли в руки."},{t="Самопоглощающая энергия",b="Вместо того чтобы служить устойчивыми хранилищами или катализаторами, эти камни начинают сжигать заключенную в них силу сразу, как только их забирают с ритуальных столов, на которых они лежат. Из-за этого свойства их никто не может унести далеко."}},faq={{q="Что такое треснувший камень силы?",a="Треснувший камень силы — нестабильный предмет, заряженный сырой магической мощью. Он намеренно создан с изъянами, из-за которых после перемещения быстро сжигает свою энергию и поглощает сам себя.",al={"flawed power stone","what is this stone","power stone lore","треснувший камень силы","что это за камень","предания о камнях силы"}},{q="Можно ли сохранить камни навсегда?",a="Нет. Стоит оторвать их от столов, дающих им устойчивость, как магические матрицы рушатся и быстро исчерпывают собственные запасы энергии.",al={"keep flawed stone","can i store it","preserving stone","сохранить треснувший камень","можно ли его хранить","сохранение камня"}},{q="Кто использует эти камни?",a="Камни готовит чернокнижник Ак'Зелот: он поручает приключенцам Орды относить их к алтарю огня на Вершине Багрового Тумана, чтобы нарушить связь Демонова семени с Пылающим Легионом.",al={"who made power stones","who crafted them","stone creators","кто создал камни силы","кто их изготовил","создатели камней"}},{q="Почему Орда интересуется ими?",a="Эти камни — оружие Орды против Пылающего Легиона в этих краях. Ак'Зелот, действуя по поручению Нииру Огненного Клинка, подготовил их так, чтобы камень, принесенный к алтарю огня на Вершине Багрового Тумана, разорвал связь Демонова семени с Легионом.",al={"horde interest","why does horde want this","интерес орды","зачем это орде"}}},fp="18,246,22.336.0,21.259.0,29.197.0,40.137.0,22.187.0,35.233.0"}
P.entries["quest:9260"] = {n="Что делает Плеть в Штормграде?",s="Вторжение Плети принесло ужасы Короля-лича прямо к вратам Штормграда. За стенами столицы над землей нависают некрополи, а нежить-чудовища и сектанты творят темную магию. Лейтенант Оррин собирает способных защитников, чтобы истребить захватчиков, собрать некротические камни и расшифровать зловещие рунные круги, пульсирующие у их лагерей.",h="Вторжение Плети принесло ужасы Короля-лича прямо к вратам Штормграда.",kw={"argent dawn","invasion","lich king","lieutenant orrin","necropolis","necrotic stones","runic circles","scourge","stormwind","серебряный рассвет","вторжение","король-лич","лейтенант оррин","некрополь","некротические камни","рунные круги","плеть","штормград"},ang={["class:Paladin"]="Столкновение с Плетью прямо у Штормграда возлагает на паладинов неотложный долг обрушить священный гнев на некромантские круги и защитить жителей королевства.",["class:Priest"]="Искаженный шепот в рунах вторжения дает жрецам прямое представление об оскверняющей магии Тьмы, подчиняющей передовые силы Плети.",["faction:Alliance"]="Оборона врат Штормграда от вторжения Плети для Альянса — вопрос выживания: она доказывает, что даже его южный оплот находится в пределах досягаемости Короля-лича."},sec={{t="Нежить у порога столицы",b="Присутствие сил Плети так близко от Штормграда стало тревожным потрясением для королевства. Парящие некрополи нависают над головой, а бредущая нежить и зловещие сектанты закрепляются прямо у порога величайшего оплота людей. Лейтенант Оррин собирает защитников за городом, чтобы отбросить захватчиков, пока они не захлестнули оборону столицы."},{t="Шепчущие руны",b="Помимо борьбы с ходячими мертвецами, задание требует изучить светящиеся рунные круги, выжженные в земле вокруг вражеских лагерей. Эти оккультные круги потрескивают той же скверной магией, что исходит от некрополей в небе. В их сиянии слышен жуткий шепот — неестественные голоса, указывающие, что круги служат проводниками темной связи, координирующей вторжение."}},faq={{q="Кто такой лейтенант Оррин?",a="Лейтенант Оррин — офицер, координирующий оборону за стенами Штормграда. Действуя вместе с Серебряным Рассветом, он организует местных бойцов, чтобы они собирали сведения и уничтожали оплоты Плети, угрожающие городу.",al={"orrin","lieutenant orrin","who gives this quest","оррин","лейтенант оррин","кто выдает это задание"}},{q="Почему Плеть нападает на Штормград?",a="Король-лич разослал по всему Азероту летающие некрополи и войска вторжения, чтобы сеять ужас и пополнять ряды нежити. Штормград как главный оплот сопротивления живых — первоочередная цель для таких нападений.",al={"why scourge here","scourge invasion stormwind","why attack stormwind","почему плеть здесь","вторжение плети штормград","зачем нападать на штормград"}},{q="Что такое светящиеся рунные круги?",a="Рунные круги — ритуальные построения, созданные Плетью возле ее передовых лагерей. Они пульсируют темной силой некромантии и шепчут неестественными голосами, служа захватчикам магическими ретрансляторами для оккультной связи.",al={"runic circles","glowing runes","what do circles do","рунные круги","светящиеся руны","для чего нужны круги"}},{q="Что такое тусклые некротические камни?",a="Тусклые некротические камни — магические фокусы, которые носят младшие силы вторжения Плети. Они излучают остаточную некротическую энергию и служат и доказательством уничтожения захватчиков, и предметом интереса для Серебряного Рассвета.",al={"dim necrotic stone","necrotic stones","what are necrotic stones","тусклый некротический камень","некротические камни","что такое некротические камни"}},{q="Какую роль в этом задании играет Серебряный Рассвет?",a="Серебряный Рассвет — независимый орден, посвятивший себя истреблению Плети везде, где она появляется. Лейтенант Оррин действует от его имени, добывая сведения и камни для более широкой войны против армий Короля-лича.",al={"argent dawn","argent dawn connection","серебряный рассвет","связь с серебряным рассветом"}},{q="Опасно ли приближаться к рунным кругам?",a="Хотя круги излучают тревожную энергию и издают диссонирующий шепот, разведчики, подходящие к ним осторожно, могут получить важные сведения о связи Плети, не лишившись рассудка.",al={"are runes safe","whispers in runes","безопасны ли руны","шепот в рунах"}}},fp="36,373,33.391.0,20.431.0,24.217.0,39.231.0,35.241.0,29.228.0,52.227.0,44.197.0"}
P.entries["quest:9264"] = {n="Что делает Плеть в Громовом Утесе?",s="Что делает Плеть в Громовом Утесе? — оборонительное задание Серебряного Рассвета у столицы таурен. Пока парящие некрополи Короля-лича угрожают небу Калимдора, защитникам поручено истреблять вторгшуюся нежить и выяснить назначение странных светящихся рунических кругов на утесах внизу.",h="Что делает Плеть в Громовом Утесе?",kw={"argent dawn","lich king","lisande","mulgore","necrotic stone","runic circle","scourge","thunder bluff","серебряный рассвет","король-лич","лисанд","мулгор","некротический камень","рунический круг","плеть","громовой утес"},ang={["class:Shaman"]="Мерзкие некромантические круги извращают природных духов земли, и шаманы-защитники должны очистить скверну, распространяющуюся по почве.",["faction:Horde"]="Поскольку линия фронта дошла до Мулгора, защитники Орды должны показать, что их земли не рухнут под внезапным натиском Короля-лича."},sec={{t="Мор на мезах",b="Вторжение Плети не делает различий между расколотыми королевствами Лордерона и мирными равнинами Мулгора. Когда Король-лич отправляет некрополи нависать над крупными поселениями мира, Громовой Утес оказывается под прямой угрозой. Лейтенант Лисанд из Серебряного Рассвета призывает способных бойцов Орды сразиться с наступающими ужасами, расположившимися под тенью великого города."},{t="Рунический шепот",b="Помимо того, чтобы косить ряды марширующих трупов и собирать тусклые некротические камни как трофеи, исследователям нужно осмотреть светящиеся рунические круги, гудящие мерзкой силой возле вражеских лагерей. Рядом с этими магическими каналами в сознание проникают жуткие голоса, доносящиеся с огромных расстояний: круги служат темными телепатическими ретрансляторами, связывающими полевые войска с мрачными разумами, направляющими вторжение."}},faq={{q="Кто выдает это задание?",a="Лейтенант Лисанд, офицер Серебряного Рассвета, расположившийся возле Громового Утеса, поручает это задание, чтобы помочь отразить окружающие силы Плети.",al={"quest giver","who gives quest","lieutenant lisande","персонаж, выдающий задания","кто дает задание","лейтенант лисанд"}},{q="Почему Плеть атакует Громовой Утес?",a="Король-лич поднял парящие некрополи, чтобы одновременно ударить по населенным центрам Азерота, стремясь сокрушить и истребить живых на каждом континенте, включая оплоты Орды в Калимдоре.",al={"why mulgore","why attack tauren","scourge in thunder bluff","почему мулгор","почему атакуют таурен","плеть в громовом утесе"}},{q="Для чего нужны светящиеся рунические круги?",a="Светящиеся рунические круги — темные магические ретрансляторы, с помощью которых Плеть связывается с дальними некрополями или некромантами и надсмотрщиками, командующими штурмом.",al={"runic circles","what do circles do","glowing runes purpose","рунические круги","что делают круги","назначение светящихся рун"}},{q="Что такое тусклые некротические камни?",a="Тусклые некротические камни — осколки, которые носят низшие захватчики Плети; они пульсируют некромантической энергией. Серебряный Рассвет собирает их как доказательство уничтожения мертвецов и для изучения мерзкой магии, поддерживающей их.",al={"necrotic stones","dim necrotic stone","what are stones","некротические камни","тусклый некротический камень","что за камни"}},{q="Почему Серебряный Рассвет здесь, в Мулгоре?",a="Серебряный Рассвет — нейтральная организация, всецело посвятившая себя борьбе с Плетью. Поскольку вторжение угрожает всем живым смертным, офицеры Серебряного Рассвета координируют оборону вместе с Ордой и Альянсом.",al={"argent dawn mulgore","argent dawn horde","серебряный рассвет мулгор","серебряный рассвет орда"}},{q="Нужно ли подниматься на парящий некрополь ради этого задания?",a="Нет. Расследование проходит целиком на земле возле лагерей под парящим некрополем, где собрались рунические круги и пехотинцы.",al={"go inside necropolis","enter necropolis","войти в некрополь","проникнуть в некрополь"}}},fp="40,320,21.430.0,14.433.1,22.156.0,43.220.0,44.185.0,29.212.0,39.226.0,60.166.0"}
P.entries["quest:9265"] = {n="Что делает Плеть в Подгороде?",s="Лейтенант Рукаг посылает защитников Орды сразиться с силами Плети, посмевшими разбить лагерь у Подгорода. Бойцам поручено исследовать зловещие светящиеся рунические круги, связанные с грозным некрополем над головой, и добыть тусклые некротические камни как доказательство уничтожения врагов.",h="Лейтенант Рукаг посылает защитников Орды сразиться с силами Плети, посмевшими разбить лагерь у Подгорода.",kw={"dim necrotic stone","lordaeron","necropolis","rukag","runic circle","scourge","undercity","тусклый некротический камень","лордерон","некрополь","рукаг","рунический круг","плеть","подгород"},ang={["faction:Horde"]="Честь требует прийти на защиту Отрекшихся и отстоять важный плацдарм Орды в Восточных королевствах против Плети.",["race:Undead"]="Плеть — ваш прежний хозяин и вечный поработитель; отбросить ее с земель Лордерона — вопрос выживания и мести."},sec={{t="На пороге",b="Вторжение Плети докатилось до ворот павшей столицы Лордерона. Вместо того чтобы прятаться за укрепленными воротами Подгорода, командиры Орды, такие как лейтенант Рукаг, организуют немедленное контрнаступление, чтобы истребить наступающих мертвецов до начала штурма."},{t="Некротические реликвии",b="За стенами цитадели Плеть возвела светящиеся рунические круги, пульсирующие мерзкой некромантической энергией, которая созвучна парящим некрополям, затмевающим небо. С побежденных нарушителей из рядов Плети выпадают тусклые некротические камни — темные накопители, питающие их жуткие ритуалы и неестественный поход."}},faq={{q="Кто приказывает исследовать окрестности Подгорода?",a="Лейтенант Рукаг, офицер Орды, поставленный защищать Подгород, приказывает воинам исследовать растущее присутствие Плети за воротами и уничтожить ее силы.",al={"who gives investigate the scourge","lieutenant rukag","rukag undercity","кто дает задание что делает плеть","лейтенант рукаг","рукаг подгород"}},{q="Что такое тусклые некротические камни?",a="Тусклые некротические камни — темные магические артефакты, которые носят вторгшиеся воины Плети. Они гудят мерзкой некромантией и служат доказательством их гибели, когда их приносят офицерам Орды.",al={"what are necrotic stones","dim necrotic stone","scourge stones","что такое некротические камни","тусклый некротический камень","камни плети"}},{q="Что такое светящиеся рунические круги?",a="Это ритуальные круги, начертанные на земле лагерями Плети; они излучают ту же темную магию, что защищает и питает нависающий над ними некрополь.",al={"runic circles outside undercity","glowing circle scourge","scourge runes","рунические круги у подгорода","светящийся круг плеть","руны плети"}},{q="Почему Плеть атакует за стенами Подгорода?",a="Король-лич стремится уничтожить мятежных Отрекшихся и завоевать руины Лордерона, направляя некрополи и наземные войска, чтобы напрямую осадить столицу.",al={"why is scourge at undercity","scourge invasion undercity","undercity under attack","почему плеть у подгорода","вторжение плети подгород","нападение на подгород"}},{q="Почему это важно для Отрекшихся?",a="Отрекшиеся неустанно боролись, чтобы освободиться от железной воли Короля-лича. Высадка Плети на самом их пороге угрожает свободе и суверенитету их юного государства.",al={"forsaken scourge threat","undead defending undercity","отрекшиеся угроза плети","нежить защищает подгород"}},{q="Могут ли взять это задание члены Орды, не являющиеся Отрекшимися?",a="Да. Все члены Орды призваны помочь в обороне Лордерона, ведь угроза Подгороду угрожает безопасности всего союза.",al={"can orcs do this quest","horde defense undercity","могут ли орки это задание","оборона орды подгород"}}},fp="40,295,15.288.0,15.322.0,51.175.0,29.180.0,35.169.0,51.164.0,37.183.0,49.150.0"}
P.entries["quest:927"] = {n="Сердце, поросшее мхом",s="«Сердце, поросшее мхом» — странное оскверненное ядро, добытое у чудовищного древня Черномшеца злосмрадного. Покрытое маслянистым темным мхом сердце жутковато продолжает биться само по себе, что побуждает ботаника Деналана у Озера Аль'Амет заняться исследованием.",h="«Сердце, поросшее мхом» — странное оскверненное ядро, добытое у чудовищного древня Черномшеца злосмрадного.",kw={"blackmoss the fetid","blight","corruption","denalan","lake al'ameth","moss-twined heart","teldrassil","timberling","черномшец злосмрадный","порча","скверна","деналан","озеро аль'амет","сердце поросшее мхом","тельдрассил","древень"},ang={["class:Druid"]="Друиды Круга Кенария живо интересуются подобными аномалиями, как это бьющееся оскверненное сердце, стремясь понять, можно ли очистить порчу или она знаменует более глубокую гниль.",["profession:Herbalism"]="Любой знаток растений видит, что маслянистый нарост на этом ядре совершенно неестественен: он нарушает обычные законы ботаники, поддерживая жизнь в вырезанном сердце.",["race:NightElf"]="Для кальдораев то, что молодое Мировое Древо Тельдрассил порождает оскверненных, агрессивных древней вроде Черномшеца, — отрезвляющий знак того, что их новый дом поражен расползающейся болезнью."},sec={{t="Бьющееся ядро",b="Это сердце древня, вырезанное из останков Черномшеца злосмрадного, почти неузнаваемо под слоем темного маслянистого мха. Единственное, что выдает его истинную природу, — медленный ритмичный пульс, не прекращающийся даже после отделения от существа. Такая неестественная живучесть намекает, что порча, расползающаяся по диким растениям Тельдрассила, гораздо глубже обычной гнили."},{t="Исследование Деналана",b="Деналан, внимательный исследователь местной флоры, живущий у Озера Аль'Амет, сразу понимает зловещую суть находки. Древни должны быть мирными существами, связанными с ветвями Мирового Древа, но это сердце источает губительное тлетворное влияние. Заинтригованный и встревоженный, Деналан решает посадить и изучить оскверненный орган, чтобы понять природу мерзкого мха, пускающего корни в почве острова."}},faq={{q="Откуда берется сердце, поросшее мхом?",a="Сердце добывают у Черномшеца злосмрадного — крупного, сильно оскверненного древня, бродящего по дебрям Тельдрассила.",al={"where do i get the heart","moss-twined heart drop","blackmoss the fetid heart","где взять сердце","сердце поросшее мхом добыча","сердце черномшеца злосмрадного"}},{q="Почему сердце все еще бьется?",a="Темный маслянистый мох, поразивший древня, судя по всему, поддерживает его неестественной жизненной силой. Даже будучи вырезанным из существа, сердце сохраняет медленный, упорный ритм.",al={"why does heart pulse","still beating heart","timberling heart beat","почему сердце пульсирует","бьющееся сердце","сердце древня бьется"}},{q="Кто такой Деналан?",a="Деналан — ночной эльф-натуралист, ухаживающий за питомником у берегов Озера Аль'Амет. Он посвятил себя изучению флоры Тельдрассила, побегов и расползающейся порчи, поражающей древней острова.",al={"who is denalan","where is denalan","denalan location","кто такой деналан","где деналан","расположение деналана"}},{q="Что Деналан сделает с сердцем?",a="Деналан решает посадить сердце в зачарованную кадку, чтобы оно проросло и выделило мерзкий мох, надеясь найти первопричину губительного роста.",al={"what happens to the heart","planting the heart quest","denalan heart research","что будет с сердцем","задание посадить сердце","исследование сердца деналаном"}},{q="Какими должны быть древни?",a="Древни от природы мирные растительные элементали, рожденные лесом. Однако по всему Тельдрассилу темные силы и неестественная скверна свели многих из них с ума и сделали агрессивными.",al={"what are timberlings","timberling lore","are timberlings evil","кто такие древни","предания о древнях","злые ли древни"}},{q="Порча на сердце магическая или природная?",a="Мох выглядит мерзким и маслянистым, а не здоровым, что указывает на неестественную порчу, заражающую местную экосистему Тельдрассила, а не на обычное увядание дикой природы.",al={"is the moss magic","source of foul moss","teldrassil moss blight","магический ли мох","источник мерзкого мха","порча мха тельдрассил"}}},fp="21,262,14.391.0,21.417.0,43.125.0,31.174.0,15.214.0,36.152.0,36.180.0,50.162.0"}
P.entries["quest:92706"] = {n="Разыскивается: Бруз",s="«Разыскивается: Бруз» — объявление о награде, вывешенное Газлоу в гоблинском порту Кабестан. Огромная хищная акула поселилась у портовых доков и угрожает морскому сообщению и прибрежной торговле, пока кто-нибудь не положит ей конец.",h="«Разыскивается: Бруз» — объявление о награде, вывешенное Газлоу в гоблинском порту Кабестан.",kw={"barrens","bounty","bruuz","dorsal fin","gazlowe","ratchet","shark","steamwheedle","степи","награда","бруз","спинной плавник","газлоу","кабестан","акула","хитрая шестеренка"},ang={["class:Hunter"]="Победа над верховным водным хищником вроде Бруза — уникальное испытание терпения и меткости.",["profession:Cooking"]="Газлоу нужен лишь спинной плавник как доказательство убийства, но акула таких размеров — это гора свежего прибрежного мяса для предприимчивых поваров."},sec={{t="Ужас в бухте",b="Кабестан живет за счет торговых перевозок и служит главными нейтральными воротами между Калимдором и Восточными королевствами. Этот постоянный поток торговли делает воды у доков шумными и беспорядочными, но недавно он привлек гораздо более опасного гостя. Гигантская акула, прозванная перепуганными портовыми рабочими «Бруз», стала рыскать по бухте. Вместо глубин чудовище агрессивно нападает на небольшие лодки, местных моряков и разгружаемые грузы, нарушая работу порта."},{t="Награда Газлоу",b="Газлоу не может позволить, чтобы суда обходили его порт из страха перед морскими тварями. Поэтому он вывесил публичное объявление, призывая всех рыболовов и обещая щедрую награду. Чтобы получить ее, охотник должен убить Бруза и принести спинной плавник хищника как доказательство."}},faq={{q="Кто такой Бруз?",a="Бруз — печально известная огромная агрессивная акула, облюбовавшая охотничьи угодья у торговых доков Кабестана. Портовые рабочие дали чудовищу это прозвище после нескольких нападений на моряков и небольшие суда.",al={"what is bruuz","bruuz shark","who is bruuz the shark","что такое бруз","акула бруз","кто такой бруз акула"}},{q="Почему Газлоу объявил награду за Бруза?",a="Бруз нарушает морское сообщение, питающее экономику Кабестана. Газлоу зависит от стабильной торговли и работающих доков, поэтому огромная акула, нападающая на моряков и разбивающая лодки, вредит делу настолько, что оправдывает денежную награду за ее тушу.",al={"why kill bruuz","gazlowe shark quest","why want bruuz fin","зачем убивать бруза","задание газлоу акула","зачем плавник бруза"}},{q="Где обычно можно найти Бруза?",a="Бруз охотится в водах прямо у побережья Кабестана в Степях, часто кружа возле главных торговых причалов и входа в гавань.",al={"bruuz location","where is bruuz","find bruuz","где бруз","местонахождение бруза","найти бруза"}},{q="Какое доказательство убийства требует Газлоу?",a="Газлоу требует спинной плавник Бруза как вещественное доказательство того, что огромный хищник действительно убит, прежде чем расстаться с деньгами.",al={"bruuz turn in","what do you bring gazlowe","bruuz dorsal fin","сдать бруза","что принести газлоу","спинной плавник бруза"}},{q="Могут ли взять это задание и искатели приключений Альянса, и Орды?",a="Да. Кабестан находится под нейтральным управлением Картеля Хитрая Шестеренка, поэтому Газлоу рад любому способному искателю приключений из любой фракции, готовому решить его проблему с акулой.",al={"is wanted bruuz neutral","can horde do wanted bruuz","can alliance do bruuz","нейтральное ли задание бруз","может ли орда бруза","может ли альянс бруза"}},{q="Почему в объявлении особо нужны рыболовы?",a="В объявлении этого не объясняется. Оно просто начинается словами «Всем рыболовам!» и обещает щедрую награду тому, кто принесет Газлоу плавник акулы.",al={"calling all anglers bruuz","is this a fishing quest","всем рыболовам бруз","это рыбацкое задание"}}},fp="13,226,19.503.0,16.291.0,13.212.0,39.239.0,29.143.0,45.141.0,57.198.0,50.142.0"}
P.entries["quest:92742"] = {n="Проверка колодцев",s="«Проверка колодцев» — задание по расследованию, данное Альбой Светлой Луной, чтобы выяснить источник яда, просачивающегося в почву Западного Края. Искателей приключений отправляют с наборами для взятия проб, чтобы собрать грунтовую воду из колодцев Владения Янсена и Фермы Мольсена.",h="«Проверка колодцев» — задание по расследованию, данное Альбой Светлой Луной, чтобы выяснить источник яда...",kw={"alba fairmoon","groundwater","jansen stead","molsen farm","poison","testing the wells","water sample","westfall","альба светлая луна","грунтовые воды","владение янсена","ферма мольсена","яд","проверка колодцев","проба воды","западный край"},ang={["class:Druid"]="Неестественные токсины, просачивающиеся сквозь почву и свежие грунтовые воды, — признак тяжелой раны в равновесии земли, требующей исцеления.",["faction:Alliance"]="Восстановление производства продовольствия в Западном Крае критически важно для выживания Королевства Штормград, и потому здоровье колодцев этих ферм — вопрос безопасности всего королевства."},sec={{t="Порча в водоносном слое",b="Открытые равнины Западного Края сильно пострадали от запустения и разбоя, но коварное заражение под землей грозит уничтожить и то сельское хозяйство, что осталось. Чтобы понять, как портятся пашни, Альба Светлая Луна поручает исследователям напрямую проверить грунтовые воды. Беря пробы воды на обжитых фермах, исследователи надеются определить природу токсинов, поражающих почву и жизнь региона."},{t="Фермы на границе",b="Исследование сосредоточено на двух важных местах: Владении Янсена и Ферме Мольсена. Оба участка находятся среди разбросанных усадеб, уязвимых для бродячих разбойников из Братства Справедливости и диких зверей. Пробы из их колодцев дают основу для выводов: возникает ли губительное вещество естественно, вызвано ли магией или намеренно подброшено в водоносный слой, питающий регион."}},faq={{q="Для чего нужна «Проверка колодцев»?",a="Альба Светлая Луна стремится выяснить источник и состав яда, поражающего Западный Край. Свежие пробы грунтовой воды из колодцев ферм — необходимый материал для анализа заражения.",al={"why test the wells","testing the wells goal","what is this quest for","зачем проверять колодцы","цель проверки колодцев","для чего это задание"}},{q="Кто дает это задание?",a="Задание выдает Альба Светлая Луна, расследующая распространяющуюся порчу и неестественные яды, поражающие земледельческий край Западный Край.",al={"who gives testing the wells","alba fairmoon quest","quest giver","кто дает проверку колодцев","задание альбы светлой луны","персонаж, выдающий задание"}},{q="В каких местах нужно брать пробы?",a="Пробы воды нужно взять из действующих колодцев во Владении Янсена и на Ферме Мольсена в Западном Крае.",al={"where do i go","which wells","well locations","куда идти","какие колодцы","расположение колодцев"}},{q="Что угрожает воде и почве Западного Края?",a="Неизвестная порча или яд активно оскверняет землю. Проверка воды местных колодцев — первый шаг к выяснению, не заражен ли водоносный слой под здешними усадьбами.",al={"why is westfall poisoned","what is poisoning the land","poison source","почему отравлен западный край","что отравляет землю","источник яда"}},{q="Заражение естественное или искусственное?",a="Это остается главным вопросом расследования. Пробы из Владения Янсена и Фермы Мольсена должны показать, происходит ли гниль от естественной порчи грунтовых вод или от намеренной диверсии.",al={"is the water poisoned on purpose","who poisoned the wells","отравлена ли вода намеренно","кто отравил колодцы"}},{q="Почему внимание на Владении Янсена и Ферме Мольсена?",a="Эти две усадьбы — давно действующие бытовые колодцы, берущие воду из подземного водоносного слоя под равнинами, что делает их лучшими кандидатами для проверки, как далеко распространилась порча.",al={"why jansen and molsen","why these farms","почему янсен и мольсен","почему эти фермы"}}},fp="17,250,21.416.0,21.376.0,41.207.0,22.144.0,35.111.0,46.187.0,43.206.0,42.186.0"}
P.entries["quest:92744"] = {n="Жабры мурлока",s="Жабры мурлока — задание Альянса в Западном Крае, которое выдает Альба Светлая Луна. Из-за опасений, что гниль на полях может отравить прибрежные рыбные угодья, искателей приключений отправляют на Бескрайний берег собрать жабры мурлоков для экологического анализа. Физиология мурлоков крайне чувствительна к морским загрязнениям, поэтому по их жабрам можно понять, проникли ли токсины в море.",h="Жабры мурлока — задание Альянса в Западном Крае, которое выдает Альба Светлая Луна.",kw={"alba fairmoon","blight","famine","longshore","murloc gills","seawater","stormwind","toxins","westfall","альба светлая луна","гниль","голод","бескрайний берег","жабры мурлока","морская вода","штормград","токсины","западный край"},ang={["class:Druid"]="Распространение гнили с полей на прибрежные экосистемы грозит исказить местную живность, поэтому биологический мониторинг видов-индикаторов, таких как мурлоки, — необходимая мера защиты.",["faction:Alliance"]="Пока король Вариан пропал, а нехватка еды уже разжигает недовольство, защита оставшихся запасов пищи в Западном Крае жизненно важна для стабильности Штормграда.",["race:Human"]="Для жителей Штормграда упадок Западного Края — прямая угроза существованию их домов, полей и обеденных столов."},sec={{t="Угроза побережью",b="Западный Край и так на грани гибели из-за повсеместного неурожая, беженцев-фермеров и бандитизма. Альба Светлая Луна опасается еще более страшного: порча, поразившая урожай вглубь страны, начала стекать в Великое море. Если прибрежные воды Западного Края отравлены, рыба, которая кормит крестьян и пополняет столы Штормграда, может исчезнуть совсем, и без того напряженное королевство погрузится в настоящий голод."},{t="Стражи чистоты воды",b="Мурлоки — известные своим упрямством и жестокостью существа, но их земноводная биология делает их чуткими природными биоиндикаторами. Дыхательная система мурлоков постоянно фильтрует морскую воду, поэтому ткань их жабр исключительно восприимчива к посторонним ядам, порче и неестественным загрязнителям. Изучая свежие жабры обитателей приливов, бродящих по Бескрайнему берегу, Светлая Луна надеется определить точную степень надвигающегося заражения."}},faq={{q="Зачем Альбе Светлой Луне жабры мурлока?",a="Альба Светлая Луна выясняет, не просочилась ли гниль, губящая урожай Западного Края, в океан. Мурлоки очень чувствительны к загрязнению воды, поэтому их жабры служат биологическими фильтрами, быстро показывающими любые следы токсинов или загрязнений в морской воде.",al={"why murloc gills","alba fairmoon murlocs","purpose of quest","зачем жабры мурлока","альба светлая луна мурлоки","цель задания"}},{q="Где находятся мурлоки для этого задания?",a="Мурлоки обитают на Бескрайнем берегу — длинной полосе пляжа на западном побережье Западного Края. Они бродят на мелководье и приливных отмелях сразу за утесами.",al={"where are murlocs","longshore murloc location","murloc gill spot","где мурлоки","где мурлоки на бескрайнем берегу","где взять жабры мурлока"}},{q="Какая опасность грозит, если океан будет заражен?",a="Западный Край — главная житница королевства Штормград. Раз урожай вглубь страны уже гибнет, прибрежная рыбалка дает жизненно важное пропитание. Если токсины отравят морскую живность вдоль берега, королевство может погрузиться в неизбежный голод.",al={"why does this matter","westfall famine danger","threat to stormwind","почему это важно","голод в западном крае","угроза штормграду"}},{q="Склонны ли мурлоки к болезням?",a="Мурлоки — выносливые бойцы, способные выжить в суровых условиях, но их земноводная дыхательная система мгновенно реагирует на химические или магические примеси в воде, поэтому они идеально подходят для изучения загрязнения воды.",al={"murloc physiology","do murlocs get sick","физиология мурлоков","болеют ли мурлоки"}},{q="Связано ли это задание с Братством Справедливости?",a="Хотя Братство Справедливости виновно в значительной части хаоса и заброшенных полей в Западном Крае, это расследование посвящено именно экологической порче и сохранению источников пищи для королевства.",al={"defias connection","is this defias","связь с братством справедливости","это братство справедливости"}},{q="Кто такая Альба Светлая Луна?",a="Альба Светлая Луна — исследовательница Альянса, находящаяся в Западном Крае и следящая за порчей и упадком окружающей среды, которые угрожают сельскому хозяйству региона.",al={"who is fairmoon","alba fairmoon lore","кто такая светлая луна","альба светлая луна предыстория"}}},fp="12,361,25.442.0,26.453.0,41.278.0,44.161.0,53.248.0,42.233.0,50.220.0,21.158.0"}
P.entries["quest:92747"] = {n="Шпионаж в Луноречье",s="Шпионаж в Луноречье — задание Альянса, которое выдает Альба Светлая Луна, чтобы разведать захваченное поселение Луноречье. Полагая, что загадочный токсин происходит не из мелких разработок Западного Края, исследователи обращают внимание на древние давно заброшенные Мертвые копи под городом, чтобы найти доказательства действующего промышленного производства.",h="Шпионаж в Луноречье — задание Альянса, которое выдает Альба Светлая Луна, чтобы разведать захваченное...",kw={"alba fairmoon","deadmines","espionage","industrial supplies","mines","moonbrook","poison","westfall","альба светлая луна","мертвые копи","шпионаж","промышленные припасы","рудники","луноречье","яд","западный край"},ang={["class:Rogue"]="Незаметное проникновение в Луноречье дает разбойникам образцовую возможность собрать сведения о деятельности Братства Справедливости, не поднимая тревоги.",["faction:Alliance"]="Обнаружение активного производства в Луноречье — прямая угроза житнице Западного Края и безопасности самого Штормграда.",["profession:Mining"]="Шахтеры понимают лучше всех, какое богатство и какой логистический размах скрыты в глубоких штольнях под Луноречьем."},sec={{t="Токсичный след",b="Изучив местные рудники Западного Края, исследователи зашли в тупик: яд, поражающий регион, судя по всему, не исходит ни из одной известной наземной разработки. Остается лишь одна крупная неисследованная выработка — огромные разветвленные штольни Мертвых копей прямо под разрушенным поселением Луноречье."},{t="Тайны Мертвых копей",b="По официальной версии, Мертвые копи были заброшены после Первой войны, когда Орда захватила регион. Однако обнаруженные в Луноречье современное промышленное снаряжение и припасы убедительно говорят о том, что кто-то тайно ведет масштабную добычу и производство за фасадом разрушенного города-призрака."}},faq={{q="Кто выдает задание «Шпионаж в Луноречье»?",a="Задание выдает Альба Светлая Луна, которая расследует подозрительные токсины и промышленную деятельность на спорной территории Западного Края.",al={"quest giver","who gives moonbrook espionage","alba fairmoon","персонаж, выдающий задания","кто выдает шпионаж в луноречье","альба светлая луна"}},{q="Почему Альба расследует дела в Луноречье?",a="Другие местные рудники не показали признаков производства исследуемого яда. Поскольку Луноречье стоит прямо над Мертвыми копями, Альба подозревает, что под городом кто-то ведет незаконную деятельность.",al={"why moonbrook","what is in moonbrook","investigate moonbrook","почему луноречье","что в луноречье","расследование в луноречье"}},{q="Что такое Мертвые копи?",a="Мертвые копи — самые глубокие и обширные золотые рудники региона. Заброшенные со времен Первой войны, после падения Штормграда, они давно считались пустыми руинами, где обитают паразиты и бандиты.",al={"deadmines lore","what are deadmines","history of deadmines","мертвые копи предыстория","что такое мертвые копи","история мертвых копей"}},{q="Какие предметы собирают во время этой разведки?",a="Разведчиков посылают собрать подозрительные промышленные припасы, разбросанные по Луноречью, что докажет: рядом со штольнями идут активные промышленные работы и переработка.",al={"suspicious industrial supplies","quest items moonbrook espionage","подозрительные промышленные припасы","предметы задания шпионаж в луноречье"}},{q="Какие угрозы сейчас засели в Луноречье?",a="Сейчас Луноречье захвачено Братством Справедливости, которое использует заброшенные здания как передовую базу и охраняет наземный вход, ведущий в подземную сеть.",al={"moonbrook enemies","who controls moonbrook","враги в луноречье","кто контролирует луноречье"}},{q="Что доказывает находка этих припасов?",a="Наличие современного тяжелого промышленного оборудования в якобы заброшенном городе подтверждает, что слаженная группировка ведет крупномасштабное производство, скрытое от глаз властей Штормграда.",al={"what do the supplies mean","defias industry","что значат припасы","промышленность братства справедливости"}}},fp="19,335,13.336.0,24.345.1,32.154.0,36.209.0,23.207.0,53.178.0,40.191.0,39.218.0"}
P.entries["quest:92748"] = {n="Взрывная консультация",s="«Взрывная консультация» — задание Альянса, начинающееся в Западном Крае и направленное против опасной промышленной деятельности, скрытой глубоко в Мертвых копях. После находок, указывающих на то, что тяжелое оборудование отравляет местные поля, герои отправляются в Квартал Дворфов Штормграда, чтобы привлечь специалиста по инженерному делу, способного поставить мощную взрывчатку.",h="«Взрывная консультация» — задание Альянса, начинающееся в Западном Крае и направленное против опасной...",kw={"alba fairmoon","deadmines","dwarven district","engineering","explosive consultation","sprite jumpsprocket","stormwind","toxins","westfall","альба светлая луна","мертвые копи","квартал дворфов","инженерное дело","взрывная консультация","спрайт прыгозубчик","штормград","токсины","западный край"},ang={["faction:Alliance"]="Это задание показывает взаимозависимость бедствующих приграничных общин Западного Края и оживленных мастерских Квартала Дворфов Штормграда.",["profession:Engineering"]="Инженеры оценят, что грубая сила не решит экологическую беду Западного Края: для вывода из строя крупных подземных механизмов нужны особые боеприпасы и тщательные технические знания.",["race:Gnome"]="Технологическая изобретательность гномов жизненно важна для устранения подземных промышленных угроз, с которыми не справляются регулярные войска Альянса."},sec={{t="Ядовитый источник",b="Пока Западный Край борется с бездомными беженцами и бандитизмом Братства Справедливости, собранные по всему региону свидетельства указывают на куда более организованную и механизированную угрозу, зреющую под землей. Промышленные отходы и едкие токсины, просачивающиеся в окрестную почву, удалось проследить до запутанных туннелей Мертвых копей, а значит, под землей неустанно работает организованное предприятие."},{t="В поисках знаний Штормграда",b="Обычное оружие не способно разрушить укрепленные подземные сооружения. Чтобы прекратить отравление Западного Края, нужны промышленные подрывные работы, поэтому срочно требуется отправиться в Квартал Дворфов Штормграда. Там, среди ревущих горнов, механиков и торговцев порохом, необходимо найти инженерный ум по имени Спрайт Прыгозубчик, который придумает взрывное решение."}},faq={{q="Зачем нужна взрывчатка в Мертвых копях?",a="Свидетельства, найденные в Западном Крае, говорят о том, что скрытое в Мертвых копях крупное промышленное предприятие производит токсины, загрязняющие окрестные поля. Разбивать укрепленные механизмы вручную нецелесообразно, для их вывода из строя нужны мощные боеприпасы.",al={"why explosives deadmines","why do we need bombs","deadmines toxins reason","зачем взрывчатка мертвые копи","зачем нужны бомбы","причина токсинов в мертвых копях"}},{q="Кто выдает это задание?",a="Альба Светлая Луна поручает это задание героям, расследующим неестественные загрязнения и беспорядки, угрожающие Западному Краю.",al={"who gives explosive consultation","explosive consultation start","кто дает взрывную консультацию","взрывная консультация начало"}},{q="Кто такая Спрайт Прыгозубчик?",a="Спрайт Прыгозубчик — гномка-инженер, живущая в Квартале Дворфов Штормграда. Она известна работой со сложными механизмами и нестабильными составами, и к ней обращаются, чтобы создать мощную взрывчатку.",al={"sprite jumpsprocket location","who is jumpsprocket","спрайт прыгозубчик где находится","кто такая прыгозубчик"}},{q="Почему за помощью нужно идти в Квартал Дворфов?",a="Квартал Дворфов — промышленное сердце Штормграда, где работают лучшие кузнецы королевства, механики и поставщики пороха и инженерных деталей.",al={"why dwarven district","stormwind dwarven district connection","почему квартал дворфов","штормград квартал дворфов связь"}},{q="Помогает ли в этом правительство Штормграда?",a="Поскольку король Вариан Ринн пропал, а Дом знати не хочет направлять в Западный Край официальные военные гарнизоны, местным защитникам приходится рассчитывать на независимых добровольцев и частных мастеров столицы, а не на регулярные армейские полки.",al={"does the army help","why stormwind engineer","помогает ли армия","почему инженер штормграда"}}},fp="22,361,14.433.0,29.390.0,43.266.0,22.113.0,27.211.0,44.180.0,52.238.0"}
P.entries["quest:92749"] = {n="Динамитный план",s="«Динамитный план» — задание, которое дает изобретательная механик Спрайт Прыгозубчик в Квартале Дворфов Штормграда. Воодушевленная разговорами о промышленной диверсии, она ищет большой запас грубого динамита, чтобы начать осуществление плана. Приключенцам нужно изготовить или раздобыть взрывчатку для ее замыслов.",h="«Динамитный план» — задание, которое дает изобретательная механик Спрайт Прыгозубчик в Квартале Дворфов...",kw={"coarse dynamite","dwarven district","engineering","explosives","sabotage","sprite jumpsprocket","stormwind","грубый динамит","квартал дворфов","инженерное дело","взрывчатка","диверсия","спрайт прыгозубчик","штормград"},ang={["faction:Alliance"]="Спрайт осуществляет свой взрывной замысел из Квартала Дворфов, прямо в стенах столицы Альянса.",["profession:Engineering"]="Инженеры могут изготовить грубый динамит из грубого пороха и льняной ткани, так что это задание служит простой проверкой начальных навыков механика.",["race:Gnome"]="Спрайт Прыгозубчик воплощает классический гномий порыв: отвечать на сложные промышленные проблемы хитроумными горючими устройствами."},sec={{t="Искры в Квартале Дворфов",b="Среди грохота и дыма Квартала Дворфов Штормграда гном-инженер Спрайт Прыгозубчик редко отказывается от радикальных решений. Когда заходит речь о промышленной диверсии, она проявляет не осторожность, а энтузиазм. Для начала она нанимает проходящих мимо наемников, чтобы они принесли ей связку грубого динамита."},{t="Планы гномов",b="Чтобы добыть взрывчатку, нужны умелые руки за инженерным верстаком или умение торговаться с городскими мастерами. Десяти шашек грубого динамита более чем достаточно, чтобы сорвать любые промышленные замыслы в окрестных землях, — это показывает практичные, хотя и опасные методы, к которым гномы прибегают, решая и механические, и политические проблемы."}},faq={{q="Кто такая Спрайт Прыгозубчик?",a="Спрайт Прыгозубчик — инженер, работающая среди кузниц и мастерских Квартала Дворфов города Штормград. Она известна дерзкими и опасными инженерными проектами.",al={"sprite jumpsprocket","who is sprite","quest giver","спрайт прыгозубчик","кто такая спрайт","персонаж, выдающий задание"}},{q="Что нужно Спрайт для этого задания?",a="Ей нужно десять шашек грубого динамита. Их можно изготовить с помощью инженерного дела или получить в обмен либо на аукционе у других мастеров.",al={"dynamite plan items","what do i need","items needed","предметы динамитного плана","что мне нужно","нужные предметы"}},{q="Зачем Спрайт нужен грубый динамит?",a="Перспектива промышленной диверсии привлекла внимание Спрайт, и она намерена начать дело с надежного запаса простых подрывных зарядов.",al={"why dynamite","dynamite purpose","sabotage motive","зачем динамит","назначение динамита","мотив диверсии"}},{q="Где сдать задание?",a="Спрайт Прыгозубчик находится в Квартале Дворфов в стенах города Штормград.",al={"where to turn in","hand in location","sprite location","где сдать","место сдачи","где спрайт"}},{q="Нужно ли инженерное дело для выполнения этого задания?",a="Нет, строго говоря, не нужно. Инженеры могут сами изготовить грубый динамит, но любой герой может выменять его у игроков или купить на аукционе.",al={"do i need engineering","engineering requirement","can non engineers do this","нужно ли инженерное дело","требование инженерного дела","можно ли без инженерного дела"}},{q="Как это связано с более широкими бедами вокруг Штормграда?",a="Спрайт никогда не говорит, против чего направлена ее диверсия. Она лишь выдает свое рвение: как только заходит речь о промышленной диверсии, она хочет начать с динамита.",al={"stormwind troubles","westfall sabotage","industrial sabotage lore","беды штормграда","диверсия западный край","предание о промышленной диверсии"}}},fp="15,300,30.336.0,17.397.0,27.195.0,36.167.0,37.152.0,29.90.0,47.190.0,58.157.0"}
P.entries["quest:92750"] = {n="Взрыв на расстоянии",s="«Взрыв на расстоянии» отправляет героя на поиски специальных знаний о взрывчатке по всей столице, Штормграду. По просьбе эксцентричной гномки-механика Спрайт Прыгозубчик вас направляют в Штормградскую разведку за дистанционным детонатором.",h="«Взрыв на расстоянии» отправляет героя на поиски специальных знаний о взрывчатке по всей столице, Штормграду.",kw={"detonation at a distance","jasper fel","remote detonator","si:7","sprite jumpsprocket","stormwind intelligence","westfall","взрыв на расстоянии","джаспер скверн","дистанционный детонатор","шру","спрайт прыгозубчик","штормградская разведка","западный край"},ang={["class:Rogue"]="Визит к Джасперу Скверну означает шаг в самый центр операций ШРУ в Старом городе, сердце человеческого шпионского ремесла.",["profession:Engineering"]="Хотя инженеры часто сами делают запалы и динамит, добыча дистанционных пусковых устройств военного образца нередко требует контактов с мастерами тихих диверсий.",["race:Gnome"]="Спрайт Прыгозубчик воплощает классический гномий интерес к инженерным задачам, даже если за особыми шпионскими боеприпасами она обращается к человеческой разведке."},sec={{t="Управляемый взрыв",b="Гоблины и гномы известны безрассудным обращением с нестабильными веществами, но не всякая подрывная работа требует стоять рядом с зарядом. Когда обычные запалы грозят жизни и здоровью, дистанционный подрыв становится абсолютной необходимостью. Спрайт Прыгозубчик понимает, что для управляемого взрыва нужны особые механизмы запуска, которых нет в обычных запасах рядовых механиков."},{t="Обращение к ШРУ",b="Вместо местных дворфийских подрывников и обычных инженерных припасов Спрайт направляет поиски в Штормградскую разведку, действующую в Старом городе. Эта тайная сеть королевства, в просторечии ШРУ, регулярно занимается деликатными диверсиями, скрытным проникновением и точечными подрывами. Джаспер Скверн, агент в столице, — именно тот теневой контакт, который распоряжается таким скрытным и опасным снаряжением."}},faq={{q="Кто отправляет вас на это задание?",a="Задание выдает Спрайт Прыгозубчик, лояльная Альянсу гномка-механик из Квартала Дворфов Штормграда.",al={"quest giver","who starts detonation at a distance","sprite jumpsprocket quest","персонаж, выдающий задание","кто дает взрыв на расстоянии","задание спрайт прыгозубчик"}},{q="С кем нужно поговорить в Штормграде?",a="Вас направляют поговорить с Джаспером Скверном, сотрудником Штормградской разведки, находящимся в столице, Штормграде.",al={"where to turn in","stormwind intelligence contact","jasper fel location","где сдать","контакт штормградской разведки","где джаспер скверн"}},{q="Зачем Спрайт Прыгозубчик нужен дистанционный детонатор?",a="Спрайт замечает, что дистанционному подрыву, возможно, не хватает хаотичного азарта неуправляемого взрыва, но уцелевшие конечности делают пусковое устройство на расстоянии куда практичнее для опасных взрывных работ.",al={"why remote detonator","purpose of detonation","зачем дистанционный детонатор","назначение подрыва"}},{q="Почему обращаться в Штормградскую разведку, а не к инженеру?",a="У Штормградской разведки есть тайные запасы и специальное диверсионное снаряжение, которое обычные городские торговцы или полевые механики не держат в открытой продаже.",al={"why si7","why stormwind intelligence","почему шру","почему штормградская разведка"}},{q="Где в Штормграде находится Джаспер Скверн?",a="Джаспер Скверн находится в Старом городе, в штаб-квартире ШРУ, где действуют шпионы и тайные агенты Штормграда.",al={"jasper fel stormwind","jasper fel room","джаспер скверн штормград","комната джаспера скверна"}},{q="Какая фракция может выполнить это задание?",a="Задание доступно строго членам Альянса, так как опирается на сотрудничество с королевской разведкой Штормграда.",al={"is this alliance only","can horde do this","только ли для альянса","может ли орда выполнить"}}},fp="24,266,18.413.0,21.461.0,30.126.0,40.125.0,53.202.0,59.163.0,41.135.0,37.139.0"}
P.entries["quest:92751"] = {n="Взрыв на расстоянии",s="«Взрыв на расстоянии» — задание Альянса, которое дает Джаспер Скверн в кругу штормградской разведки. Узнав об опасных работах под Луноречьем, глава шпионов выдает специальный дистанционный детонатор, чтобы безопасно проводить подрывы, не взорвав своих агентов.",h="«Взрыв на расстоянии» — задание Альянса, которое дает Джаспер Скверн в кругу штормградской разведки.",kw={"deadmines","dwarven district","jasper fel","moonbrook","remote detonator","si:7","sprite jumpsprocket","westfall","мертвые копи","квартал дворфов","джаспер скверн","луноречье","дистанционный детонатор","шру","спрайт прыгозубчик","западный край"},ang={["class:Rogue"]="Работа напрямую с Джаспером Скверном показывает разветвленную тайную сеть ШРУ и то, как шпионы королевства следят за полевыми агентами и тихо снабжают их нужными средствами.",["faction:Alliance"]="Задание отражает борьбу Штормграда за возвращение Западного Края с помощью тайной инженерии и разведки, а не открытого развертывания войск.",["profession:Engineering"]="Инженеры оценят опытный дистанционный детонатор, призванный заменить рискованные ручные запалы при сложных подрывах в пещерах.",["race:Gnome"]="Доставка Спрайт Прыгозубчик показывает гномью изобретательность в Штормграде, снабжающую шпионов королевства передовыми опытными образцами."},sec={{t="Глаза в тени",b="Джаспер Скверн и агенты ШРУ следят почти за всем, что происходит на землях Штормграда, особенно в неспокойных пограничных краях вроде Западного Края. Когда до Скверна доходят вести о взрывных работах в Луноречье, он уже хорошо знает, что назревает в заброшенных шахтных туннелях под сельской местностью."},{t="Опытное решение",b="Взрывы большой мощности в замкнутых пещерных системах сопряжены с очевидной опасностью. Фел передает прототип комплекта «Дистанционный детонатор (комплект)», разработанный инженерами, лояльными Альянсу, — он позволяет безопасно запустить любой взрыв под Западным Краем снаружи. Он поручает курьеру доставить оборудование Спрайт Прыгозубчик в Квартале Дворфов и между делом напоминает не упоминать об участии ШРУ перед их соратниками-эльфами."}},faq={{q="Кто такой Джаспер Скверн?",a="Джаспер Скверн — агент штормградской разведки, ШРУ. Действуя из тени, он следит за тайными угрозами по всему королевству и предоставляет специальные средства для борьбы с ними.",al={"jasper fel","who gives detonation at a distance","quest giver","джаспер скверн","кто дает взрыв на расстоянии","персонаж, выдающий задание"}},{q="Почему ШРУ интересуется Луноречьем?",a="Луноречье оказалось в руках бандитов и преступников и служит наземным входом в Мертвые копи. Любая деятельность или подрывные работы глубоко под Западным Краем сразу привлекают внимание внутренней разведки Штормграда.",al={"why moonbrook","defias connection","westfall caves"}},{q="Кто такая Спрайт Прыгозубчик?",a="Спрайт Прыгозубчик — гномка-агент, расположившаяся в Квартале Дворфов Штормграда и отвечающая за специальное техническое оборудование и опытные образцы.",al={"sprite jumpsprocket","who receives the detonator","turn in npc","спрайт прыгозубчик","кто получает детонатор","персонаж для сдачи"}},{q="Кто такой «друг-эльф», о котором говорит Джаспер Скверн?",a="Джаспер Скверн имеет в виду эльфийского помощника, содействующего вашим усилиям против мятежников Западного Края. ШРУ предпочитает действовать скрытно, с возможностью отрицать свою причастность, не сообщая внешним союзникам о прямой поддержке.",al={"elf friend","dont tell elf","jasper fel elf","друг эльф","не говори эльфу","джаспер скверн эльф"}},{q="Для чего нужен «Дистанционный детонатор (комплект)»?",a="Это инженерный опытный образец, позволяющий запускать подрывные заряды с безопасного расстояния, чтобы агенты могли обрушивать или расчищать подземные проходы, не оказавшись в ловушке.",al={"remote detonator","detonator kit","what does the kit do","дистанционный детонатор","комплект детонатора","для чего комплект"}},{q="Куда ведет это задание?",a="По заданию нужно доставить комплект детонатора прямо Спрайт Прыгозубчик в Квартал Дворфов города Штормград.",al={"where do i go","quest route","turn in location","куда идти","маршрут задания","место сдачи"}}},fp="24,289,19.312.0,20.438.1,18.200.0,35.236.0,27.147.0,44.230.0,42.183.0,31.126.0"}
P.entries["quest:92752"] = {n="Взрывная консультация",s="«Взрывная консультация» — задание в Западном Крае, связанное с гномом-изобретателем Спрайт Прыгозубчик и Альбой Светлой Луной. Раздобыв необычайно нестабильный заряд, Спрайт поручает посыльному доставить взведенную взрывчатку в целости, не приведя случайно в действие детонатор.",h="«Взрывная консультация» — задание в Западном Крае, связанное с гномом-изобретателем Спрайт Прыгозубчик и...",kw={"alba fairmoon","detonator","explosive consultation","explosives","gnome engineering","sprite jumpsprocket","westfall","альба светлая луна","детонатор","взрывная консультация","взрывчатка","гномья инженерия","спрайт прыгозубчик","западный край"},ang={["faction:Alliance"]="Бойцы Альянса в Западном Крае полагаются на нетрадиционное вооружение, чтобы противостоять укрепившимся лагерям бандитов и взбесившимся механизмам.",["profession:Engineering"]="Любой практикующий инженер узнает привычные риски гномьих боеприпасов: максимальная мощность в сочетании с чувствительным детонатором.",["race:Gnome"]="Спрайт Прыгозубчик воплощает взрывной подход Гномрегана к решению задач, принося мощные технологические решения на беспокойный фронт Западного Края."},sec={{t="Опасная доставка",b="Гномья инженерия редко отличается умеренностью, и работа Спрайт Прыгозубчик в Западном Крае подтверждает репутацию этого ремесла. Закончив смесь, Спрайт передает связку особо разрушительной взрывчатки для Альбы Светлой Луны. Работа посыльного в Западном Крае военного времени опасна и без того, когда приходится уходить от бандитов Братства Справедливости и диких зверей, но перевозка заряженного боеприпаса с чувствительным спуском добавляет особый риск."},{t="Осторожное обращение",b="Передавая груз, Спрайт Прыгозубчик дает простой, но важный совет: берегите детонатор. Будь то расчистка препятствий, разрушение укрепленных сооружений или подрыв действий Братства Справедливости на спорных равнинах, опасный груз должен прибыть целым, прежде чем Альба Светлая Луна сможет им воспользоваться."}},faq={{q="Кто выдает задание «Взрывная консультация»?",a="Задание выдает Спрайт Прыгозубчик, гном-изобретатель из Квартала Дворфов Штормграда, поставляющий особую взрывчатку.",al={"who gives explosive consultation","quest giver explosive consultation","sprite jumpsprocket quest","кто дает взрывная консультация","персонаж, выдающий задание взрывная консультация","задание спрайта прыгозубчика"}},{q="Кто получает взрывчатку в конце задания?",a="Готовую особо разрушительную взрывчатку нужно доставить прямо Альбе Светлой Луне в Западном Крае.",al={"where do i take the explosives","who turns in explosive consultation","alba fairmoon explosive","куда отнести взрывчатку","кто принимает взрывная консультация","альба светлая луна взрывчатка"}},{q="Какой предмет вам поручено перевезти?",a="Спрайт вверяет вам связку особо разрушительной взрывчатки с активным и хрупким детонатором.",al={"what is sprite handing over","explosive consultation item","what bomb is this","что передает спрайт","предмет взрывная консультация","что это за бомба"}},{q="Зачем в Западном Крае нужна взрывчатка?",a="Западный Край охвачен борьбой с Братством Справедливости и наводнен враждебными механизмами и мародерами. Тяжелые боеприпасы часто нужны, чтобы разрушать баррикады, расчищать путь или обезвреживать укрепленные угрозы на полях.",al={"why do they need bombs","westfall explosives purpose","why blow things up in westfall","зачем им бомбы","назначение взрывчатки в западном крае","зачем взрывать в западном крае"}},{q="Доступно ли это задание искателям приключений из Орды?",a="Нет. Спрайт Прыгозубчик и Альба Светлая Луна действуют в поддержку операций Альянса, поэтому задание доступно только игрокам Альянса.",al={"can horde do explosive consultation","horde explosive consultation","может ли орда взять взрывная консультация","орда взрывная консультация"}},{q="Предупреждает ли Спрайт Прыгозубчик о какой-либо опасности?",a="Спрайт прямо предупреждает, что бомба взведена и что в пути с детонатором нужно обращаться предельно осторожно.",al={"sprite warning","bomb warning westfall","предупреждение спрайта","предупреждение о бомбе западный край"}}},fp="22,272,19.431.0,18.319.0,44.133.0,52.98.0,43.115.0,38.246.0,45.132.0,60.123.0"}
P.entries["quest:928"] = {n="Венец Земли",s="«Венец Земли» — переходное путешествие, выводящее юных ночных эльфов из Тенистой долины в более широкие земли Тельдрассила. Неся священную воду лунного колодца, освященную на вершине Альдрассила, путники направляются на юг по лесной дороге к Коритрасу Лунному Гневу в Доланаар. Это переход от уединенного обучения к неотложной защите природы великого Мирового Древа.",h="«Венец Земли» — переходное путешествие, выводящее юных ночных эльфов из Тенистой долины в более широкие земли...",kw={"aldrassil","corithras moonrage","crown of the earth","dolanaar","moonwell","partially filled vessel","shadowglen","teldrassil","tenaron stormgrip","альдрассил","коритрас лунный гнев","венец земли","доланаар","лунный колодец","наполовину полный сосуд","тенистая долина","тельдрассил","тенарон хватка бури"},ang={["class:Druid"]="Перенос освященной воды связывает юных друидов с непрекращающимися, хрупкими усилиями по поддержанию и уравновешиванию растущей экосистемы Тельдрассила.",["class:Priest"]="Перенос воды лунного колодца, освященной милостью Элуны, олицетворяет священный долг ее жречества заботиться о духовном здоровье общины.",["race:NightElf"]="Шаг за пределы Тенистой долины — важнейший обряд перехода для каждого юного кальдорая, отправляющегося служить своему народу."},sec={{t="Уход из долины",b="Доказав преданность, отведав зачарованной воды лунного колодца Тенистой долины, новички призываются к Тенарону Хватке Бури на вершину Альдрассила. Видя их готовность, Тенарон переливает собранную воду в сосуд побольше и велит им отправиться за пределы укромной рощи. Дорога на юг к Доланаару — главный путь из Тенистой долины, она вьется через леса, ставшие все более непредсказуемыми и враждебными."},{t="Дорога в Доланаар",b="Доланаар — первая крупная деревня, которую встречают путники, покинув начальную долину. Поселение лежит у мощеных дорожек, огибающих центральный Тельдрассил, и оживленно кипит вокруг собственного чистого лунного колодца. Здесь ждет Коритрас Лунный Гнев, старейшина, ответственный за более широкие усилия по сохранению природы среди ветвей. Сосуд, вверенный его заботе, связывает начинающего искателя приключений с общей, тревожной судьбой Мирового Древа."}},faq={{q="Что я несу в Доланаар?",a="Вы несете наполовину полный сосуд с освященной водой, набранной из лунного колодца в Тенистой долине. Тенарон Хватка Бури слил ваше первое подношение в этот сосуд, чтобы Коритрас Лунный Гнев мог продолжить ритуальную работу по всему Тельдрассилу.",al={"what is the vessel","partially filled vessel lore","what water is this","что за сосуд","наполовину полный сосуд предания","что за вода"}},{q="Кто такой Коритрас Лунный Гнев?",a="Коритрас Лунный Гнев — старейшина ночных эльфов, живущий у лунного колодца в Доланаар. Он направляет прибывающих искателей приключений в продолжении важных обрядов и исследований, необходимых для поддержания недавно выросшего Мирового Древа.",al={"who is corithras","corithras moonrage role","where is corithras","кто такой коритрас","роль коритраса лунного гнева","где коритрас"}},{q="Почему Тенарон отправляет меня из Тенистой долины?",a="Тенистая долина дает основы подготовки, но угрозы, стоящие перед Тельдрассилом, требуют помощи по всей ветви. Вы доказали, что способны справляться с местными угрозами и почитать лунные колодцы, и Тенарон отправляет вас в Доланаар, где ждут более широкие задачи.",al={"why leave shadowglen","why go to dolanaar","tenaron sending me away","зачем покидать тенистую долину","зачем идти в доланаар","тенарон отправляет меня"}},{q="Где находится дорога в Доланаар?",a="Идите по мощеной дорожке на юг от Альдрассила и мимо ворот Тенистой долины. Продолжайте идти по камням, пока тропа поворачивает на юг и запад, и вы не придете в деревню Доланаар.",al={"how to get to dolanaar","path to dolanaar","road out of shadowglen","как добраться до доланаара","путь в доланаар","дорога из тенистой долины"}},{q="Почему Тенарон предупреждает об опасных зверях?",a="Даже среди священных ветвей Тельдрассила дикие животные стали неестественно агрессивными и возбужденными. Если сойти с мощеной тропы, можно подвергнуться нападению территориальных пауков, оскверненных ночных саблезубов и агрессивных древоходов.",al={"why are beasts dangerous","corrupted beasts teldrassil","stay on the road warning","почему звери опасны","оскверненные звери тельдрассил","предупреждение держаться дороги"}},{q="Что происходит после прибытия в Доланаар?",a="Коритрас Лунный Гнев принимает сосуд и поручает вам новые задачи: осмотреть и благословить другие лунные колодцы по всему Тельдрассилу, выявляя более глубокие проблемы леса.",al={"what next after crown of the earth","dolanaar next quest","what does corithras do","что дальше после венец земли","следующее задание в доланаар","что делает коритрас"}}},fp="18,388,17.462.0,20.460.0,31.243.0,26.209.0,46.250.0,30.199.0,45.223.0,37.178.0"}
P.entries["quest:92819"] = {n="Разрушение в Мертвых копях",s="«Разрушение в Мертвых копях» — тайное задание, которое выдает Альба Светлая Луна в Западном Крае. Исполнителю поручено привести в действие взрывной заряд: его отправляют глубоко под землю, чтобы взорвать устройство и подорвать деятельность Братства Справедливости в лабиринте туннелей.",h="«Разрушение в Мертвых копях» — тайное задание, которое выдает Альба Светлая Луна в Западном Крае.",kw={"alba fairmoon","deadmines","defias","destruction in deadmines","detonator","explosives","sabotage","westfall","альба светлая луна","мертвые копи","братство справедливости","разрушение в мертвых копях","детонатор","взрывчатка","диверсия","западный край"},ang={["class:Rogue"]="Проникнуть на вражескую территорию, заложить заряды и скрыться до взрыва — классический пример тайной диверсии, как раз для разбойника.",["faction:Alliance"]="Каждый удар по оплоту Братства Справедливости в Мертвых копях помогает защитить бедствующие фермы Западного Края и южную границу Штормграда.",["profession:Engineering"]="Подрывные работы и детонаторы с дистанционным управлением — основа этого задания, и оно придется по душе инженерам, ценящим искусство управляемых обрушений."},sec={{t="Диверсия под Западным Краем",b="Мертвые копи давно скрывают главную силу Братства Справедливости: это и оплот, и промышленный центр прямо под Западным Краем. Вместо того чтобы прорываться с боем по каждому укрепленному коридору, Альба Светлая Луна отдает приказ о решительной диверсии. Закладывая взрывчатку и подрывая ее в подземном комплексе, лазутчики Альянса стремятся обрушить важнейшие сооружения и сорвать любые замыслы братства, которые оно вынашивает во тьме."},{t="Детонатор",b="Для выполнения этого поручения нужны твердая рука и точный расчет времени. Альба вручает детонатор, который должен привести в действие подрывные заряды, заложенные в оплоте. Удар по уязвимым местам конструкции шахты нанесет Братству Справедливости долговременный ущерб: пострадают его линии снабжения, механизмы и оборонительные сооружения, а защитники Западного Края наверху выиграют ценное время."}},faq={{q="Кто выдает задание «Разрушение в Мертвых копях»?",a="Это задание выдает Альба Светлая Луна, лазутчица, находящаяся в Западном Крае, которая направляет искателей приключений из Альянса для прямого удара по оплоту Братства Справедливости.",al={"who gives destruction in deadmines","quest giver deadmines detonation","alba fairmoon quest","кто выдает разрушение в мертвых копях","персонаж, выдающий задания, детонатор мертвые копи","задание альбы светлой луны"}},{q="Какова главная цель этого задания?",a="Вам нужно привести в действие детонатор внутри комплекса Мертвых копей, чтобы взорвать заряды и подорвать деятельность Братства Справедливости, скрытую под землей региона.",al={"what do i do in destruction in deadmines","destruction in deadmines goal","how to complete destruction in deadmines","что делать в разрушении в мертвых копях","цель разрушения в мертвых копях","как выполнить разрушение в мертвых копях"}},{q="Зачем взрывать Мертвые копи?",a="Мертвые копи — не просто заброшенный золотой рудник: там расположены главные мастерские, склады и сборочные цеха Братства Справедливости. Обрушение ключевых мест взрывчаткой лишает братство возможности вести подземную кампанию против Западного Края и Штормграда.",al={"why blow up deadmines","deadmines sabotage lore","why use detonator in deadmines","зачем взрывать мертвые копи","диверсия в мертвых копях","зачем нужен детонатор в мертвых копях"}},{q="Где происходит это задание?",a="Задание начинается у Альбы Светлой Луны в Западном Крае и приводит вас в обширные подземные туннели Мертвых копей под Луноречьем.",al={"destruction in deadmines location","where is destruction in deadmines","deadmines detonator location","разрушение в мертвых копях где","где разрушение в мертвых копях","детонатор мертвые копи где"}},{q="Доступно ли это задание игрокам Орды?",a="Нет. Альба Светлая Луна работает только с лазутчиками Альянса, защищающими Западный Край от растущей угрозы Братства Справедливости.",al={"is destruction in deadmines alliance only","can horde do destruction in deadmines","разрушение в мертвых копях только для альянса","может ли орда взять разрушение в мертвых копях"}},{q="Чем Братство Справедливости угрожает Западному Краю?",a="Братство Справедливости прогнало фермеров, грабило поселения и захватило заброшенные шахты Западного Края. Действуя из глубин Мертвых копей, оно готовит вооруженное восстание, которое напрямую угрожает королевству Штормград.",al={"defias lore westfall","why fight defias","what are defias doing in deadmines","предания братство справедливости западный край","зачем сражаться с братством справедливости","что делает братство справедливости в мертвых копях"}}},fp="24,262,25.499.0,13.386.0,46.165.0,46.154.0,41.268.0,33.139.0,43.132.0,57.242.0"}
P.entries["quest:929"] = {n="Венец Земли",s="«Венец Земли» — священное поручение Коритраса Лунного Гнева в Доланааре: набрать освященной воды из лунного колодца у Деревни Звездного Ветра. За то, что молодые ночные эльфы пополняют воды Дарнасса, они узнают трагическую историю, из-за которой их народ вырастил огромные ветви Тельдрассила.",h="«Венец Земли» — священное поручение Коритраса Лунного Гнева в Доланааре: набрать освященной воды из лунного...",kw={"corithras moonrage","crown of the earth","dolanaar","jade phial","moonwell","nordrassil","starbreeze village","teldrassil","коритрас лунный гнев","венец земли","доланаар","нефритовый флакон","лунный колодец","нордрассил","деревня звездного ветра","тельдрассил"},ang={["class:Druid"]="Лунные колодцы — жизненно важные проводники природной и астральной магии, живые хранилища, связывающие обязанности вашего ордена в Дарнассе с корнями Тельдрассила.",["race:NightElf"]="Каждому ночному эльфу приходится смириться с утратой бессмертия и исчезновением Малфуриона Ярость Бури, и этот священный ритуал сбора воды становится важным уроком недавней скорби вашего народа."},sec={{t="Поддержание лунных колодцев",b="Великий центральный лунный колодец Дарнасса нуждается в постоянной связи с малыми источниками, разбросанными по кроне Мирового Древа. Друиды изготавливают особые нефритовые флаконы, чтобы набирать и переносить эти светящиеся воды, не нарушая их чистоты. Отправляя посвящаемых пешком в Деревню Звездного Ветра, старейшины следят и за тем, чтобы городские фонтаны были полны благодати Элуны, и за тем, чтобы молодежь понимала, какого труда требует забота о Тельдрассиле."},{t="Отголоски Третьей войны",b="За выполнение этого поручения посвящаемый получает устный рассказ. Коритрас Лунный Гнев повествует об отчаянии, охватившем кальдораев сразу после битвы на горе Хиджал. Жертва древнего Мирового Древа Нордрассила лишила ночных эльфов драгоценного бессмертия, и среди разрухи на свободу вырвался Иллидан Ярость Бури, а Шан'до Малфурион Ярость Бури исчез в Изумрудном Сне. Эта атмосфера скорби и отчуждения подготовила почву для спорного решения вырастить Тельдрассил."}},faq={{q="Для чего нужно набирать воду из лунного колодца?",a="Друиды Дарнасса регулярно пополняют главный лунный колодец города водой, собранной в окрестных лесных святилищах, и тем самым поддерживают священную сеть по всему Тельдрассилу.",al={"why get moonwell water","moonwell water use","purpose of jade phial","зачем набирать воду лунного колодца","применение воды лунного колодца","для чего нефритовый флакон"}},{q="Где находится лунный колодец для этого задания?",a="Лунный колодец находится сразу за Деревней Звездного Ветра, к востоку от Доланаара, у лесной тропы.",al={"where is the moonwell","starbreeze moonwell location","starbreeze village well","где лунный колодец","лунный колодец деревни звездного ветра","колодец деревни звездного ветра"}},{q="Кто такой Коритрас Лунный Гнев?",a="Коритрас Лунный Гнев — ночной эльф-друид, находящийся в Доланааре. Он наставляет молодых искателей приключений в ритуальных обязанностях и рассказывает им о событиях, связанных с благополучием Тельдрассила.",al={"who gives the quest","corithras moonrage lore","кто выдает задание","коритрас лунный гнев предания"}},{q="Какую историю рассказывает Коритрас после возвращения?",a="Он рассказывает о катастрофических последствиях битвы на горе Хиджал: как был сожжен Нордрассил, как исчезло бессмертие кальдораев, как был освобожден Иллидан и как пропал Шан'до Малфурион Ярость Бури.",al={"what does corithras say","crown of the earth lore text","что говорит коритрас","текст предания венец земли"}},{q="Почему ночные эльфы чувствуют себя потерянными после горы Хиджал?",a="Нордрассил дарил ночным эльфам вечную жизнь и защиту. Пожертвовав силой Древа ради уничтожения Архимонда, они лишились вневременного существования и стали смертными, потерянными и крайне уязвимыми.",al={"why did elves lose immortality","what happened after hyjal","почему эльфы потеряли бессмертие","что случилось после хиджала"}},{q="Что такое Шан'до?",a="Шан'до — почетное обращение на дарнасском языке эльфов, означающее «почтенный учитель»; здесь оно относится к Малфуриону Ярость Бури, верховному предводителю друидов.",al={"what does shando mean","shando meaning","что значит шан'до","значение шан'до"}}},fp="18,313,24.463.0,23.498.0,46.189.0,44.106.0,26.168.0,46.200.0,47.222.0,18.146.0"}
P.entries["quest:93"] = {n="Темные пирожки с крабами",s="У Шеф-повара Груаля из таверны «Алый ворон» в Темнолесье есть секрет знаменитых Темных пирожков с крабами: крабов в них нет вовсе. Искателям приключений поручено помочь голодному и издерганному Трясунчику: они добывают паучьи лапки у смертоносных паукообразных на севере Сумеречного леса, чтобы приготовить любимое лакомство горожан.",h="У Шеф-повара Груаля из таверны «Алый ворон» в Темнолесье есть секрет знаменитых Темных пирожков с крабами...",kw={"chef grual","darkshire","duskwood","dusky crab cakes","jitters","scarlet raven tavern","spider legs","venom web spider","шеф-повар груаль","темнолесье","сумеречный лес","темные пирожки с крабами","трясунчик","таверна алый ворон","паучьи лапки","ядовитый паук"},ang={["faction:Alliance"]="Это блюдо показывает шаткое положение южного рубежа Альянса, где такие города, как Темнолесье, вынуждены питаться гигантскими вредителями из-за заброшенной инфраструктуры и разорванных путей снабжения.",["profession:Cooking"]="Шеф-повар Груаль показывает, какая выдержка нужна поварам на границе: даже жуткие хищники глуши, например гигантские ядовитые пауки, можно превратить в любимый деликатес города."},sec={{t="Сомнительный деликатес",b="Сумеречный лес давно страдает от изоляции, темной магии и разорванных торговых путей, и жителям Темнолесья пришлось приспосабливать свою кухню. Шеф-повар Груаль, повар таверны «Алый ворон», решил проблему нехватки мяса, придумав Темные пирожки с крабами. Хотя название наводит на мысль о морепродуктах из дальних краев, Груаль охотно признает, что особая кисловатая нотка блюда целиком берется от вязких лапок местных гигантских пауков."},{t="Охота на ядовитых пауков",b="Чтобы выполнить заказ, Груаль отправляет охотников на север, к предгорьям и берегам реки, где ядовитые пауки плетут свои сети. В мрачном лесу, кишащем нежитью и дикими зверями, добывать свежее паучье мясо опасно, но это один из немногих доступных источников белка в зараженных лесах. Груаль жарит приправленные паучьи лапки на горячей сковороде до хруста."},{t="Утешение для проклятой души",b="Кулинарное поручение возникло из заботы о Трясунчике, взволнованном бродяге, укрывшемся в заброшенной деревне Вороний Холм на западе Сумеречного леса. Терзаемый виной и дрожащий от ужаса после того, как случайно выпустил на волю кошмары, он почти ни о чем не может думать, кроме голодного желудка. Горячая порция вкусных паучьих пирожков Груаля становится редким, пусть и странным утешением в его жалком изгнании."}},faq={{q="Правда ли, что Темные пирожки с крабами сделаны из краба?",a="Нет. Шеф-повар Груаль откровенно признается искателям приключений, что Темные пирожки с крабами целиком сделаны из вязких паучьих лапок. В Темнолесье нет ни моря, ни свежих крабов, поэтому Груаль использует местных гигантских пауков, чтобы повторить текстуру и получить острую кисловатую закуску.",al={"is it real crab","crab cakes secret","what are crab cakes made of","настоящий краб ли","секрет пирожков с крабами","из чего сделаны пирожки с крабами"}},{q="Где Шеф-повар Груаль берет паучьи лапки?",a="Груаль полагается на искателей приключений, которые добывают вязкие лапки у ядовитых пауков. Эти агрессивные паукообразные гнездятся в основном на севере Сумеречного леса, между лесными предгорьями и рекой.",al={"where to find spider legs","spider locations duskwood","venom web spiders location","где найти паучьи лапки","где пауки в сумеречном лесу","где ядовитые пауки"}},{q="Для кого готовят эти пирожки с крабами?",a="Груаль подает их посетителям в Темнолесье, но эту порцию заказал Трясунчик. Он — запуганный отшельник, умирающий от голода в городе-призраке Вороний Холм на западе Сумеречного леса и отчаянно желающий чем-нибудь наполнить урчащий живот.",al={"who wants the crab cakes","who eats the crab cakes","why make crab cakes","кто хочет пирожки с крабами","кто ест пирожки с крабами","зачем готовить пирожки с крабами"}},{q="Научит ли меня Шеф-повар Груаль готовить Темные пирожки с крабами?",a="Шеф-повар Груаль строго хранит точный рецепт Темных пирожков с крабами и отказывается делиться своей фирменной смесью специй. Однако полезных искателей приключений он награждает другим рецептом из своего кулинарного репертуара.",al={"can i learn crab cakes recipe","crab cake recipe cooking","можно ли выучить рецепт пирожков с крабами","рецепт пирожков с крабами кулинария"}},{q="Почему Темнолесье полагается на пауков как на еду?",a="Дороги Сумеречного леса осаждены нежитью, воргенами Ночной Погибели и враждебными тварями, что сильно нарушает торговлю караванов и земледелие. Поскольку свежий скот и привозные товары редки, жители Темнолесья изобретательно используют любую дичь, которую удается поймать.",al={"why eat spiders in darkshire","duskwood food shortages","почему в темнолесье едят пауков","нехватка еды в сумеречном лесу"}},{q="Знает ли Трясунчик, что пирожки сделаны из пауков?",a="Трясунчик жаждет именно знаменитых пирожков с крабами Груаля, и ингредиенты его мало волнуют. Парализованный страхом и голодом в лесу, он рад любой привычной еде из Темнолесья, какой бы жуткой ни была ее основа.",al={"does jitters know about the spiders","jitters reaction to spider meat","знает ли трясунчик о пауках","реакция трясунчика на паучье мясо"}}},fp="16,310,23.436.0,22.409.0,25.412.1,43.254.0,42.185.0,40.245.0,54.229.0,44.258.0,48.228.0"}
P.entries["quest:930"] = {n="Светящийся плод",s="Светящийся плод — задание в Тельдрассиле, которое начинается с находки странного растения с плодами, дико растущего в лесу. Заподозрив неладное, юные искатели приключений относят светящийся образец травнику Деналану у Озера Аль'Амет для изучения.",h="Светящийся плод — задание в Тельдрассиле, которое начинается с находки странного растения с плодами, дико...",kw={"boglings","denalan","glowing fruit","herbalism","lake al'ameth","strange fruited plant","teldrassil","timberlings","болотники","деналан","светящийся плод","травничество","озеро аль'амет","странное растение с плодами","тельдрассил","древолазы"},ang={["class:Druid"]="Для друидов, стремящихся сохранить равновесие природы, чужеземные нестабильные растения, неестественно разросшиеся на священных ветвях Тельдрассила, — тревожный знак.",["profession:Herbalism"]="Травники оценят ботанические познания Деналана о том, как чужеземные семена пересекают континенты и мутируют в зачарованной почве.",["race:NightElf"]="Молодые кальдораи узнают от Деналана, что даже молодая почва их нового дома, Тельдрассила, подвержена непредсказуемой чужеземной заразе."},sec={{t="Неестественный урожай",b="Пробираясь по туманным ветвям Тельдрассила, путники время от времени натыкаются на необычные светящиеся растения с крупными круглыми плодами. Учитывая хрупкое равновесие Мирового Древа и недавнее странное поведение местных животных, необычные растения требуют тщательного изучения. Убежденные, что странный росток нельзя оставлять без внимания, искатели приключений срывают сияющие плоды, чтобы отнести их тому, кто разбирается в диких растениях."},{t="Исследование Деналана",b="У Озера Аль'Амет сведущий садовод и травник Деналан принимает светящийся плод с любопытством и тревогой. Он отмечает, что образец выглядит экзотическим, и предполагает, что его семена могли попасть сюда из далеких земель за морем, возможно, даже из Восточных королевств. Еще больше Деналана беспокоит то, как чужеземное семя отреагировало на почву самого Тельдрассила: стоит взять плод в руки, как враждебные болотники тут же яростно нападают."}},faq={{q="Где находится странное растение с плодами?",a="Странное растение с плодами дико растет в глуши Тельдрассила, среди подлеска вдали от крупных поселений. Если взаимодействовать с растением, вы получите светящийся плод, и задание начнется.",al={"where do i find the plant","strange fruited plant location","how to start the glowing fruit","где найти растение","странное растение с плодами где находится","как начать задание светящийся плод"}},{q="Кто такой Деналан?",a="Деналан — ночной эльф, травник и ботаник, живущий на берегах Озера Аль'Амет. Он проводит дни, ухаживая за почвой, изучая местные растения и наблюдая за странными переменами в природе, затрагивающими Тельдрассил.",al={"where is denalan","denalan npc","who turns in glowing fruit","где деналан","деналан нпс","кому сдавать светящийся плод"}},{q="Почему плод светится?",a="The cause of the fruit's glow is not established. Denalan considers it an unusual specimen and plans to study it.",al={"why is the fruit glowing","what is wrong with the fruit","почему плод светится","что не так с плодом"}},{q="Что произойдет, если отдать плод Деналану?",a="Bring the glowing fruit to Denalan at Lake Al'Ameth for examination. His findings and the result of the delivery are revealed when you return.",al={"what spawns after quest","bogling ambush","кто появляется после задания","засада болотников"}},{q="Откуда, по мнению Деналана, взялось это растение?",a="Деналан полагает, что семена растения могли попасть сюда издалека, из-за Великого моря, и быть принесены в Калимдор с далекого восточного континента — Азерота.",al={"where did seeds come from","fruit origin","откуда семена","происхождение плода"}},{q="Связано ли это задание с другими экологическими проблемами Тельдрассила?",a="Да. Оно связано с более широким исследованием Деналана: почему ветви Тельдрассила и местные лесные существа, например древолазы и болотные звери, становятся все более беспокойными и неестественными.",al={"teldrassil corruption","lake al'ameth problems","порча тельдрассила","проблемы озера аль'амет"}}},fp="17,255,20.451.0,23.495.1,41.204.0,15.228.0,24.113.0,48.142.1,46.152.0,67.199.0"}
P.entries["quest:931"] = {n="Мерцающий росток",s="Среди корней и крон Тельдрассила обнаружено необычное растение, излучающее неземное мерцание. Поняв его редкость, путники приносят образец ботанику Деналану у Озера Аль'Амет, чтобы выяснить его происхождение.",h="Среди корней и крон Тельдрассила обнаружено необычное растение, излучающее неземное мерцание.",kw={"botany","denalan","lake al'ameth","shimmering frond","sprouted fronds","strange fronded plant","swamp of sorrows","teldrassil","ботаника","деналан","озеро аль'амет","мерцающий росток","проросшие ростки","странное растение с листьями","болото печали","тельдрассил"},ang={["class:Druid"]="Друиды, заботящиеся о равновесии Великого Древа, обращают внимание на нездешние растения, появившиеся в хрупкой молодой кроне Тельдрассила.",["profession:Herbalism"]="Травники и любители растений оценят ботаническую загадку болотного растения, процветающего за тысячи миль от родной экосистемы.",["race:NightElf"]="Для ночных эльфов, обживающих новый дом, опыты Деналана дают важное представление о том, насколько устойчива почва Тельдрассила."},sec={{t="Странное свечение",b="Блуждая по зеленым ветвям Тельдрассила, внимательные путники могут наткнуться на странное растение с длинными листьями. В отличие от обычной лесной листвы, его листья ловят свет и мерцают пульсирующим, закручивающимся сиянием. Такое неестественное явление привлекает внимание каждого, кто заботится о хрупкой, только зарождающейся экосистеме острова."},{t="Открытие Деналана",b="Когда черенок попадает к ботанику Деналану у Озера Аль'Амет, открывается неожиданная правда. Деналан определяет растение как экзотический вид, не встречающийся на севере Калимдора: в последний раз он видел подобное десятилетия назад, путешествуя по далекому Болоту Печали в Восточных королевствах. Пораженный тем, как такое семя могло пересечь океан и вырасти до столь внушительных размеров на Мировом Древе, Деналан немедленно принимается выращивать и испытывать образец."}},faq={{q="Откуда изначально родом странное растение?",a="По словам ботаника Деналана, растение родом с Болота Печали — мрачных топей далеко на юго-востоке Восточных королевств. Живого образца он не видел с тех пор, как десятилетия назад побывал в тех болотах.",al={"frond origin","where is frond from","swamp plant","происхождение ростка","откуда росток","болотное растение"}},{q="Кто такой Деналан?",a="Деналан — любознательный ночной эльф, ботаник и травник, живущий у берегов Озера Аль'Амет в Тельдрассиле. Он посвящает время изучению и выращиванию буйной растительности Тельдрассила, часто экспериментируя с чужеземными семенами и кадками.",al={"denalan lore","who is denalan","предания о деналане","кто такой деналан"}},{q="Почему это растение растет в Тельдрассиле?",a="Это остается экологической загадкой. Деналан удивляется, как семя могло преодолеть весь путь из Восточных королевств через Великое море и все же прижиться и вырасти в такой крупный образец в богатой почве Тельдрассила.",al={"how did it get to teldrassil","why is frond here","как оно попало в тельдрассил","почему росток здесь"}},{q="Что произойдет после передачи ростка Деналану?",a="Деналан сразу помещает образец в свою кадку у Озера Аль'Амет, чтобы провести испытания. Благодаря его уходу вскоре распускаются несколько проросших ростков, что ведет к дальнейшему изучению экзотического растения.",al={"next quest","denalan test","sprouted fronds","следующее задание","испытание деналана","проросшие ростки"}},{q="Вызывает ли это растение порчу в Тельдрассиле?",a="Нет. Хотя многие животные Тельдрассила подвержены тонкой порче от скверных влияний, это растение, судя по всему, просто необычный экзотический вид не на своем месте, а не источник порчи.",al={"is frond corrupted","corrupted plant","испорчен ли росток","зараженное растение"}}},fp="20,224,14.334.0,19.478.1,50.222.0,15.252.0,40.225.0,47.204.1,47.188.0"}
P.entries["quest:932"] = {n="Извращенная ненависть",s="Извращенная ненависть — тайное поручение Таллонкай Гибкий Корень в Тельдрассиле. Он просит доверенных защитников проникнуть в Пещеру Бесов и убить лорда Меленаса, сатира, который собирает местных греллов в организованную, оскверняющую силу опасно близко к поселениям ночных эльфов.",h="Извращенная ненависть — тайное поручение Таллонкай Гибкий Корень в Тельдрассиле.",kw={"fel rock","grell","lord melenas","satyr","tallonkai swiftroot","teldrassil","twisted hatred","пещера бесов","греллы","лорд меленас","сатир","таллонкай гибкий корень","тельдрассил","извращенная ненависть"},ang={["class:Druid"]="Мерзкое присутствие Меленаса и его оскверненных греллов в Пещере Бесов отравляет хрупкое равновесие недавно выросших земель Тельдрассила.",["race:NightElf"]="Каждый сатир — древнее напоминание о падении ваших предков, поддавшихся демоническим амбициям; убить лорда Меленаса — долг перед Мировым Древом и акт покаяния за предков."},sec={{t="Горький позор",b="Для ночных эльфов сатиры — живая память о древнем предательстве. Рожденные из высокорожденных, отдавшихся Пылающему Легиону во время Войны Древних, эти козлоногие демоны остаются мучительным несмываемым пятном на истории кальдораев. То, что сатир обосновался прямо в Тельдрассиле, молодом Мировом Древе, которое должно быть убежищем, местные защитники, такие как Таллонкай Гибкий Корень, считают жестоким позором."},{t="Угроза в Пещере Бесов",b="К северу от ближайших троп лежит Пещера Бесов — оскверненная система пещер, кишащая дикими греллами. Лорд Меленас собрал этих по природе хаотичных существ во враждебную организованную силу, подчиненную его темной воле. Опасаясь того, что сатир намерен обрушить на ветви Мирового Древа, Таллонкай требует устранить Меленаса быстро, тихо и решительно, принеся его отрубленную голову."}},faq={{q="Кто такой лорд Меленас?",a="Лорд Меленас — сатир, завладевший пещерой Пещера Бесов на севере Тельдрассила. Он командует выводком агрессивных воинов-греллов и замышляет распространить порчу по всему Мировому Древу.",al={"lord melenas","who is melenas","fel rock boss","лорд меленас","кто такой меленас","босс пещеры бесов"}},{q="Где найти лорда Меленаса?",a="Он скрывается в глубине Пещеры Бесов — зазубренной системы пещер к северу от Доланаара в Тельдрассиле, в окружении греллов и других оскверненных существ.",al={"melenas location","where is melenas","how to find fel rock","где меленас","где найти меленаса","как найти пещеру бесов"}},{q="Почему Таллонкай Гибкий Корень хочет сохранить это в тайне?",a="Сатиры — ужасная древняя глава в истории ночных эльфов: они предали свой народ во время Войны Древних. Присутствие такого существа в самом сердце недавно посаженного Мирового Древа считается полным позором, и Таллонкай предпочитает решить вопрос без всеобщей паники.",al={"why secret","why must this stay between us","tallonkai secret","почему тайна","почему это должно остаться между нами","тайна таллонкай"}},{q="Какова связь между сатирами и греллами?",a="Греллы — мелкие, проказливые и по природе оскверненные дикие существа, встречающиеся по всему Тельдрассилу. Сатиры, хитрые и по сути демонические, легко запугивают или подчиняют таких низших существ, заставляя служить своим мерзким замыслам.",al={"grell and satyrs","why are grell following melenas","satyr grell connection","греллы и сатиры","почему греллы следуют за меленасом","связь сатиров и греллов"}},{q="Откуда вообще в Тельдрассиле сатиры?",a="Тельдрассил был выращен всего несколько лет назад без благословения Аспектов драконов. Несмотря на надежды друидов на чистое убежище, порча и темные существа быстро проникли на остров, а сатиры пробрались туда, чтобы обосноваться в мрачных местах вроде Пещеры Бесов.",al={"satyrs on teldrassil","how did satyrs get here","teldrassil corruption","сатиры в тельдрассиле","как сатиры сюда попали","порча тельдрассила"}},{q="Who is Tallonkai Swiftroot?",a="Таллонкай Гибкий Корень — ночной эльф-страж, живущий близ Доланаара, который следит за возникающими угрозами Тельдрассилу и поручает искателям приключений уничтожать ближайшие очаги порчи.",al={"tallonkai","who gives twisted hatred","таллонкай","кто выдает задание извращенная ненависть"}}},fp="14,280,17.452.0,22.395.0,20.193.0,30.143.0,51.299.0,50.218.0,54.273.0,27.189.0"}
P.entries["quest:933"] = {n="Венец Земли",s="Венец Земли — задание Альянса, которое выдает Коритрас Лунный Гнев в Доланааре. Он поручает вам набрать воды из лунного колодца у Прудов Арлитриэна — местности, которой все сильнее угрожают обезумевшие фурболги из племени Скрюченной Сосны. Выполнив его, вы узнаете, как верховный друид Фэндрал Олений Шлем призвал ночных эльфов вырастить Тельдрассил после исчезновения Малфуриона Ярость Бури.",h="Венец Земли — задание Альянса, которое выдает Коритрас Лунный Гнев в Доланааре.",kw={"corithras moonrage","dolanaar","fandral staghelm","gnarlpine","malfurion stormrage","pools of arlithrien","tourmaline phial","коритрас лунный гнев","доланаар","фэндрал олений шлем","скрюченная сосна","малфурион ярость бури","пруды арлитриэна","турмалиновый фиал"},ang={["class:Druid"]="Раскол Круга Кенария при руководстве Фэндрала Оленьего Шлема становится понятнее, когда Коритрас рассказывает об отчаянном стремлении вернуть древнее бессмертие.",["race:NightElf"]="Этот этап вашего пути объясняет спорный политический порыв, приведший к появлению Тельдрассила после внезапного исчезновения Малфуриона."},sec={{t="Опасный лунный колодец",b="Коритрас Лунный Гнев поручает вам отнести турмалиновый фиал к лунному колодцу к юго-востоку от входа в Дарнасс, на берегу Прудов Арлитриэна. Путь далеко не спокоен. Некогда мирные фурболги из племени Скрюченной Сосны внезапно впали в неистовую ярость, нападают из засад на путников и тревожат патрули Часовых по всей округе. То, что ранние сообщения списывали на отдельные стычки, переросло во всеобщую угрозу, нависшую над новым домом ночных эльфов."},{t="Честолюбие Фэндрала Оленьего Шлема",b="Получив наполненный фиал, Коритрас рассказывает важную историю создания Тельдрассила. После Третьей войны Шан'до Малфурион Ярость Бури исчез, оставив друидов Кенария без лидера и раздробленными. В его отсутствие верховный друид Фэндрал Олений Шлем взял на себя руководство. Олений Шлем убедил Круг Древних на Темных берегах, что ночные эльфы не могут позволить себе праздный траур: им нужно вернуть утраченное бессмертие и исцелить свою цивилизацию, посадив огромное новое Мировое Древо."}},faq={{q="Где находится лунный колодец для этого задания?",a="Лунный колодец находится к юго-востоку от главного входа в Дарнасс, на южном берегу Прудов Арлитриэна.",al={"arlithrien moonwell","moonwell location","where to fill phial","лунный колодец арлитриэна","где лунный колодец","где наполнить фиал"}},{q="Почему фурболги из племени Скрюченной Сосны нападают?",a="Племя Скрюченной Сосны традиционно было мирным родом медведелюдей, но недавно в Тельдрассиле их охватила темная безрассудная ярость. Часовые сначала считали первые нападения единичными случаями, но порча быстро распространилась, и фурболги превратились в постоянную угрозу для соседних поселений и патрулей.",al={"furbolgs mad","gnarlpine aggressive","why furbolgs attack","безумные фурболги","скрюченная сосна агрессия","почему фурболги нападают"}},{q="Что случилось с Малфурионом Ярость Бури?",a="Шан'до Малфурион Ярость Бури бесследно исчез после Третьей войны. Даже сегодня ни друиды Кенария, ни руководство ночных эльфов не знают, что с ним стало и где он спит.",al={"where is malfurion","what happened to stormrage","malfurion missing","где малфурион","что случилось с ярость бури","малфурион пропал"}},{q="Кто решил вырастить Тельдрассил?",a="Когда Малфурион пропал, верховный друид Фэндрал Олений Шлем взял на себя руководство друидами. Он убедил Круг Древних на Темных берегах поддержать выращивание нового Мирового Древа, утверждая, что это необходимо кальдораям, чтобы восстановиться и вернуть бессмертие, утраченное при разрушении Нордрассила.",al={"who made teldrassil","staghelm world tree","why was teldrassil grown","кто создал тельдрассил","олений шлем мировое древо","почему вырастили тельдрассил"}}},fp="18,377,19.474.0,27.513.0,37.131.0,41.317.0,37.210.0,32.292.0"}
P.entries["quest:934"] = {n="Венец Земли",s="«Венец Земли» — важный этап цепочки заданий Доланаара, посвященной недугам Тельдрассила. Коритрас Лунный Гнев поручает искателям приключений набрать воды из священного лунного колодца на Поляне Оракула; это путешествие раскрывает тревожную правду о создании Мирового Древа.",h="«Венец Земли» — важный этап цепочки заданий Доланаара, посвященной недугам Тельдрассила.",kw={"alexstrasza","amethyst phial","corithras moonrage","fandral staghelm","immortality","moonwell","nozdormu","oracle glade","oracle tree","teldrassil","алекстраза","аметистовый фиал","коритрас лунный гнев","фэндрал олений шлем","бессмертие","лунный колодец","ноздорму","поляна оракула","древо оракула","тельдрассил"},ang={["class:Druid"]="Для Круга Кенария посещение Древа Оракула подчеркивает идейный раскол между напористыми амбициями Фэндрала Оленьего Шлема и природным равновесием, которое издавна хранил Малфурион Ярость Бури.",["faction:Alliance"]="Понимание хрупкого состояния Тельдрассила объясняет неотступную порчу и безумие существ, тревожащие новейшую столичную территорию Альянса.",["race:NightElf"]="Это путешествие затрагивает надежды ночных эльфов на Тельдрассил после жертвы Нордрассила во время Третьей войны."},sec={{t="Поляна Оракула",b="Коритрас Лунный Гнев отправляет путников далеко на северо-запад Тельдрассила, под величественный полог Поляны Оракула. Прямо под огромными ветвями Древа Оракула находится первый и самый мощный лунный колодец, созданный на острове. Набрав Аметистовый фиал воды из его мерцающих глубин, искатели оказываются в главном святилище, откуда друиды и само древо следят за состоянием своей новой родины."},{t="Отказ в благословении",b="Когда фиал возвращается в Доланаар, Коритрас раскрывает мрачный изъян в великом замысле верховного друида Фэндрала Оленьего Шлема. После жертвы Нордрассила на горе Хиджал Олений Шлем стремился вернуть ночным эльфам бессмертие, посадив Тельдрассил и попросив благословения у Аспектов драконов. Однако Ноздорму, Вневременный, отказал, упрекнув Оленьего Шлема в непомерной гордыне. Королева Алекстраза последовала его примеру, отказав в животворном благословении Аспекта Жизни, и рост Тельдрассила стал неустойчивым, несовершенным и уязвимым для глубокой порчи."}},faq={{q="Где находится лунный колодец на Поляне Оракула?",a="Лунный колодец находится на северо-западе Тельдрассила, прямо к северу от главной дороги, ведущей в Дарнасс. Он лежит под огромными ветвями Древа Оракула.",al={"where is oracle glade","oracle glade moonwell location","oracle well","где поляна оракула","лунный колодец поляны оракула","колодец оракула"}},{q="Кто такой Коритрас Лунный Гнев?",a="Коритрас Лунный Гнев — ночной эльф, хранитель, находящийся в Доланааре. Он водит молодых защитников по ветвям Тельдрассила, чтобы они отведали воды его лунных колодцев, и рассказывает об истории несовершенного рождения древа.",al={"corithras","who is corithras moonrage","коритрас","кто такой коритрас лунный гнев"}},{q="Вернул ли Тельдрассил бессмертие ночных эльфов?",a="Нет. Хотя Тельдрассил стал для ночных эльфов новым домом, их бессмертие не вернулось после жертвы Нордрассила во время Третьей войны.",al={"are night elves immortal","teldrassil immortality","do elves live forever again","бессмертны ли ночные эльфы","бессмертие тельдрассил","живут ли эльфы вечно"}},{q="Для чего нужно собирать воду на Поляне Оракула?",a="Лунный колодец под Древом Оракула — первый и самый мощный колодец острова. Набрав его воды, Коритрас может оценить духовное и природное состояние Тельдрассила.",al={"why get oracle water","amethyst phial purpose","зачем брать воду оракула","аметистовый фиал зачем"}}},fp="18,298,16.444.0,19.546.1,43.172.0,26.202.0,45.164.0,62.186.0"}
P.entries["quest:935"] = {n="Венец Земли",s="«Венец Земли» знаменует завершение обрядов очищения у священных лунных колодцев Тельдрассила. Передача собранной воды верховному друиду Фэндралу Оленьему Шлему в Дарнассе подчеркивает растущую тревогу из-за несовершенного, неблагословенного существования Мирового Древа.",h="«Венец Земли» знаменует завершение обрядов очищения у священных лунных колодцев Тельдрассила.",kw={"alexstrasza","cenarion enclave","corithras moonrage","crown of the earth","darnassus","fandral staghelm","moonwell","nozdormu","teldrassil","алекстраза","анклав кенария","коритрас лунный гнев","венец земли","дарнасс","фэндрал олений шлем","лунный колодец","ноздорму","тельдрассил"},ang={["class:Druid"]="Доставка воды из лунных колодцев Верховному друиду Круга Кенария приводит вас прямо к Фэндралу Оленьему Шлему и показывает ожесточенный политический и духовный раскол, охвативший руководство друидов в отсутствие Малфуриона.",["faction:Alliance"]="Для всего Альянса Дарнасс — внушительная столица древней тайны, но оскверненные земли вокруг нее доказывают, что даже ночные эльфы сталкиваются с внутренними опасностями на собственной священной земле.",["race:NightElf"]="Этот обряд раскрывает тихую тревогу под основанием вашего нового дома: Тельдрассил посадили из гордыни, без благословения Аспектов драконов, и растущая болезнь напоминает о хрупкости нового начала вашего народа."},sec={{t="Изъян при рождении",b="Тельдрассил вырос после Третьей войны, чтобы дать ночным эльфам новый дом и вернуть утраченное бессмертие. Однако Великие Аспекты Алекстраза и Ноздорму отказали в благословении, не одобрив создание древа. Лишившись их божественной защиты, Тельдрассил стал жертвой ползущей болезни: из его ветвей лезут странные создания, а прежде мирные племена фурболгов впадают в безумие."},{t="Доставка Верховному друиду",b="Коритрас Лунный Гнев поручает юным искателям приключений собирать воду из лунных колодцев острова, чтобы следить за недугами ветвей и облегчать их. Слив образцы в один сосуд, Коритрас отправляет посыльного вглубь Дарнасса, в Анклав Кенария. Там сидит верховный друид Фэндрал Олений Шлем, создатель Тельдрассила, который видит в ползущей порче не знак гордыни, а досадное бремя, которое должен разрешить только он."}},faq={{q="Зачем Фэндралу Оленьему Шлему вода из лунных колодцев?",a="Фэндрал Олений Шлем поручил собрать образцы из лунных колодцев Тельдрассила, чтобы изучить и устранить порчу, просачивающуюся в Мировое Древо. Как лидер, настоявший на посадке древа, он отвечает за поиск решения проблемы странных зверей и обезумевших фурболгов, тревожащих крону.",al={"fandral water purpose","why does fandral need the vessel","what is the water for","зачем фэндралу вода","зачем фэндралу сосуд","для чего нужна вода"}},{q="Почему Тельдрассил страдает от порчи и обезумевших зверей?",a="В отличие от древнего Мирового Древа Нордрассила, Тельдрассил посадили без благословения Алекстразы, Хранительницы Жизни, и Ноздорму Вневременного. Лишенный защиты этих изначальных Аспектов драконов, рост нового древа изначально изъянен, и странные язвы укореняются в почве, искажая местных животных и фурболгов.",al={"why is teldrassil sick","teldrassil corruption","why are furbolgs mad","почему тельдрассил болен","порча тельдрассила","почему фурболги безумны"}},{q="Где находится верховный друид Фэндрал Олений Шлем?",a="Верховный друид Фэндрал Олений Шлем живет в Дарнассе, в Анклаве Кенария. Вы найдете его на вершине центрального павильона друидов, с которого открывается вид на священные рощи анклава.",al={"where is fandral","fandral staghelm location","how to find fandral","где фэндрал","где найти фэндрала оленьего шлема","как найти фэндрала"}},{q="Кто такой Коритрас Лунный Гнев?",a="Коритрас Лунный Гнев — друид из Доланаара, который координирует очищение лунных колодцев по всему Тельдрассилу. Он собирает очищенные фиалы, принесенные странниками, сливает их в один сосуд и отправляет посыльных доставить его верховному друиду Оленьему Шлему в Дарнасс.",al={"who gives crown of the earth","corithras role","corithras moonrage","кто дает венец земли","роль коритраса","коритрас лунный гнев"}},{q="Что происходит после выполнения этого задания?",a="Доставка наполненного сосуда Фэндралу Оленьему Шлему завершает основную цепочку заданий «Венец Земли» в Тельдрассиле. Олений Шлем принимает воду довольно сухо и снова обращает внимание на более широкие угрозы, стоящие перед родиной ночных эльфов.",al={"crown of the earth follow up","what comes after crown of the earth 6","next quest after crown of the earth","продолжение венца земли","что после венца земли","следующее задание после венца земли"}},{q="Почему Фэндрал Олений Шлем так пренебрежителен, получая сосуд?",a="Фэндрал Олений Шлем известен своей гордостью и нетерпением, а также бременем тяжкой задачи — руководить Кругом Кенария, пока Малфурион Ярость Бури отсутствует. Он с презрением относится к организационным неудачам и медлительным посыльным, чувствуя, что тяжкое ярмо выживания Тельдрассила лежит только на его плечах.",al={"why is fandral rude","fandral personality","is fandral always grumpy","почему фэндрал груб","характер фэндрала","всегда ли фэндрал угрюм"}}},fp="18,263,16.435.0,26.439.1,51.316.0,58.332.0,45.167.0,26.282.0,41.251.1,64.307.0"}
P.entries["quest:93552"] = {n="Сбор камней ветра",s="«Сбор камней ветра» — задание, которое дает Далия Вымогатель в Тендалской роще на острове Зефрис. Древние стихийные силы, поддерживающие остров, медленно угасают, и необработанные камни ветра стали важным источником магической энергии. Искателей приключений отправляют по роще собрать кристаллические скопления камней ветра, пока их сила не иссякла.",h="«Сбор камней ветра» — задание, которое дает Далия Вымогатель в Тендалской роще на острове Зефрис.",kw={"anchor pylons","dalia","dalia the collector","thendal grove","wind elementals","windstone cluster","windstones","zephras isle","якорные пилоны","далия","далия вымогатель","тендалская роща","элементали ветра","скопление камней ветра","камни ветра","остров зефрис"},ang={["class:Mage"]="Для практиков тайной магии сконцентрированная стихийная сила камней ветра наглядно напоминает, насколько хрупкими становятся магические экосистемы, когда исчезают их стихийные источники.",["profession:Mining"]="Сбор необработанных камней ветра — знакомство с добычей ценных минералов и кристаллов в диких землях острова Зефрис."},sec={{t="Угасающий остров",b="Остров Зефрис в значительной мере держится на остаточной магии ветра, но его природная защита слабеет. Столетия назад исчезли местные элементали ветра, делившие остров с местными эльфами. С их уходом окружающая магия, поддерживающая землю и великие якорные пилоны, медленно и неуклонно слабеет. Жителям Тендалской рощи для выживания нужно обеспечить любой возможный запас необработанной энергии."},{t="Ценность камней ветра",b="Камни ветра — яркие синие кристаллические образования, естественным образом разбросанные по Тендалской роще. В их хрупкой оболочке заключена плотная, сконцентрированная магия ветра, оставшаяся с давних времен. Хотя это не бесконечное решение, они дают эльфам острова надежный и ценный источник тайной подпитки и пользы, поэтому сбор необработанных скоплений — важное ежедневное дело."}},faq={{q="Что такое камни ветра?",a="Камни ветра — синие кристаллические залежи в Тендалской роще, содержащие сконцентрированную необработанную энергию ветра. Эльфы острова Зефрис собирают их как важный источник магической энергии.",al={"raw windstone","windstone cluster","blue crystals","необработанный камень ветра","скопление камней ветра","синие кристаллы"}},{q="Кто такая Далия Вымогатель?",a="Далия — эльфийка-сборщица, живущая в Тендалской роще на острове Зефрис. Она организует добычу важных сырьевых ресурсов, в частности камней ветра, чтобы поддержать убывающие магические запасы острова.",al={"dalia","dalia zephras","collector dalia","далия","далия зефрис","далия вымогатель"}},{q="Почему магия на острове Зефрис угасает?",a="Столетия назад исчезли элементали ветра, жившие бок о бок с местными эльфами. Без их постоянного присутствия чары, которыми великие якорные пилоны наполнили остров, медленно иссякают.",al={"zephras losing magic","fading magic zephras","anchor pylons","зефрис теряет магию","угасающая магия зефрис","якорные пилоны"}},{q="Куда ушли элементали ветра?",a="Их точная судьба остается загадкой. Известно лишь, что они исчезли несколько столетий назад, и остров медленно истощает оставшиеся запасы стихийной силы.",al={"missing elementals","where are wind elementals","elementals vanished","пропавшие элементали","где элементали ветра","элементали исчезли"}},{q="Что такое якорные пилоны?",a="Великие якорные пилоны — древние сооружения на острове Зефрис, наделенные мощной магией для поддержания земли. Без элементалей их поддерживающая энергия постепенно слабеет.",al={"great anchor pylons","anchor pylon lore","великие якорные пилоны","предания о якорных пилонах"}},{q="Где найти необработанные камни ветра?",a="Необработанные камни ветра можно найти разбросанными по всей Тендалской роще на острове Зефрис; они выглядят как светящиеся синие кристаллические выходы породы.",al={"windstone location","thendal grove crystals","где камни ветра","кристаллы тендалской рощи"}}},fp="21,334,15.455.0,23.384.0,20.187.0,27.205.0,40.210.0,33.169.0,27.187.0,33.148.0"}
P.entries["quest:937"] = {n="Зачарованная поляна",s="На Поляне Оракула на северо-западе Тельдрассила Часовой Арания Проблеск Солнца пытается защитить древнее Древо Оракула от агрессивных гарпий клана Кровавое Перо. После того как посланный в Дарнасс гонец убит, защитников призывают нанести ответный удар по гнездам гарпий и принести их пояса в качестве доказательства.",h="На Поляне Оракула на северо-западе Тельдрассила Часовой Арания Проблеск Солнца пытается защитить древнее...",kw={"arynia cloudsbreak","bloodfeather","darnassus","harpies","oracle glade","oracle tree","sentinel","teldrassil","the enchanted glade","арания проблеск солнца","кровавое перо","дарнасс","гарпии","поляна оракула","древо оракула","часовой","часовые","тельдрассил","зачарованная поляна"},ang={["class:Druid"]="Друиды глубоко почитают разумных древних; истребление гарпий, угрожающих Древу Оракула, помогает защитить природное равновесие поляны.",["faction:Alliance"]="Помощь Часовым в защите священных рощ Тельдрассила укрепляет связи Альянса с руководством ночных эльфов в соседнем Дарнассе.",["race:NightElf"]="Защита древних духов Мирового Древа и охрана Часовых от осквернения гарпиями — священный долг любого кальдорая."},sec={{t="Осажденная поляна",b="Поляна Оракула — одно из священных мест уединения Тельдрассила, в центре которого находится колоссальное древнее дерево, известное как Древо Оракула. Часовой Арания Проблеск Солнца была направлена с отрядом воинов охранять эти почтенные ветви. К несчастью, свирепые гарпии Кровавое Перо проникли в дупла и яростно гнездятся по всему окружающему пологу, угрожая каждому, кто подходит близко."},{t="Разорванная связь с Дарнассом",b="Напряжение достигло предела, когда Древо Оракула попыталось отправить гонца со срочным донесением в столицу, Дарнасс. Посланник так и не покинул ветви: гарпии устроили засаду и убили гонца, прежде чем донесение вышло за пределы поляны. В ответ Арания поручила местным искателям приключений истребить стаю и собрать пояса Кровавого Пера, чтобы отбросить наступающих гарпий."},{t="Зов Древа",b="Когда непосредственная угроза со стороны ближайших гнезд ослабевает, откликается само древнее дерево. Древо Оракула роняет кусочек своей зачарованной коры, ища посланника, который передаст его весть в руки высшего руководства кальдораев."}},faq={{q="Почему гарпии нападают на Поляну Оракула?",a="Клан Кровавое Перо плотно заселяет север Тельдрассила. На Поляне Оракула гарпии окружили Древо Оракула, яростно охраняя свои насесты и нападая на всех, кто пытается дойти до священного места или покинуть его.",al={"harpies in oracle glade","why bloodfeather attack","oracle tree harpies","гарпии на поляне оракула","почему нападает кровавое перо","гарпии древа оракула"}},{q="Кто такая Часовой Арания Проблеск Солнца?",a="Арания Проблеск Солнца — офицер Часовых, размещенная на Поляне Оракула вместе с небольшим авангардом. Ее главная задача — защищать Древо Оракула от окрестных гарпий и восстановить связь с Дарнассом.",al={"arynia cloudsbreak","who gives the enchanted glade","cloudsbreak lore","арания проблеск солнца","кто дает задание зачарованная поляна","проблеск солнца предания"}},{q="Что случилось с гонцом, посланным в Дарнасс?",a="Гонец, отправленный с донесением от Древа Оракула в Дарнасс, попал в засаду и был убит гарпиями Кровавого Пера на тропах поляны, не добравшись до безопасного места.",al={"oracle tree messenger","dead runner darnassus","гонец древа оракула","убитый гонец дарнасс"}},{q="Что такое Древо Оракула?",a="Древо Оракула — огромный разумный древень, укорененный на Поляне Оракула. Он наблюдает за ветвями Мирового Древа и передает свою мудрость и предостережения руководству ночных эльфов.",al={"oracle tree teldrassil","who is the oracle tree","древо оракула тельдрассил","кто такое древо оракула"}},{q="Какое доказательство нужно Часовому Проблеску Солнца?",a="Часовому Проблеску Солнца нужны шесть поясов Кровавого Пера, снятых с убитых гарпий, как веское доказательство того, что их насесты вокруг поляны поредели.",al={"bloodfeather belt quest","how many belts","quest proof","задание пояса кровавого пера","сколько поясов","доказательство задания"}},{q="Что происходит после истребления гарпий?",a="Когда ближайшие окрестности очищены, Древо Оракула роняет кусочек своей коры, открывая прямой путь связи, чтобы искатель приключений отнес его давно задержанную весть в Дарнасс.",al={"next quest after enchanted glade","what does oracle tree do next","следующее задание после зачарованной поляны","что делает древо оракула дальше"}}},fp="19,311,19.405.0,26.391.0,23.248.1,43.222.0,35.216.0,46.163.0,24.185.0,45.153.0,39.192.1"}
P.entries["quest:93746"] = {n="Твердый ответ",s="«Твердый ответ» — задание Орды на острове Зефрис, которое выдает Айесса Певица Рассвета. Напряжение нарастает: загадочный Высший орден вторгается на территорию и в дела местных Ваятелей ветра. Айесса приказывает нанести упреждающий удар по Белатаану Яркому Желанию на дороге к Святилищу Акира, чтобы силой четко обозначить границы.",h="«Твердый ответ» — задание Орды на острове Зефрис, которое выдает Айесса Певица Рассвета.",kw={"a firm response","ayessa dawnsinger","belathaan brightwish","high order","living storms","shrine of akir","windshapers","zephras isle","твердый ответ","айесса певица рассвета","белатаан яркое желание","высший орден","живые бури","святилище акира","ваятели ветра","остров зефрис"},ang={["class:Shaman"]="Схватка с Живыми бурями на дороге подчеркивает бурную, неукрощенную магию стихии воздуха, пронизывающую весь остров Зефрис.",["faction:Horde"]="Присутствие Орды на острове Зефрис опирается на создание надежных позиций и недопущение вторжения соперничающих фракций, таких как Высший орден, в интересы союзников."},sec={{t="Проведение черты",b="Ваятели ветра острова Зефрис не терпят непрошеного внимания, особенно со стороны такой скрытной и расчетливой организации, как Высший орден. Прежние предупреждения остались без внимания, и Айесса Певица Рассвета вынуждена обострить ситуацию. Чтобы защитить свои интересы, она решает перехватить Белатаана Яркое Желание на безлюдном участке дороги, ведущей на север к Святилищу Акира, чтобы стычка прошла вдали от посторонних глаз в городке."},{t="Бури на дороге",b="Поход Белатаана на север к древнему Святилищу Акира сразу вызывает подозрения, хотя его истинные мотивы неясны. Когда его настигают на пустынной дороге, встреча быстро перерастает во вражду, и в схватку вступают Живые бури. Победа над этими неистовыми элементалями и усмирение Белатаана посылают Высшему ордену недвусмысленное сообщение: вмешательство в дела Ваятелей ветра встретит силовой ответ."}},faq={{q="Кто такая Айесса Певица Рассвета?",a="Айесса Певица Рассвета — персонаж, выдающий задания, связанный с Ордой и Ваятелями ветра на острове Зефрис. Она оберегает их владения и беспощадна к чужакам, вмешивающимся в их дела.",al={"ayessa dawnsinger","who gives a firm response","ayessa","айесса певица рассвета","кто дает твердый ответ","айесса"}},{q="Кто такой Белатаан Яркое Желание?",a="Белатаан Яркое Желание — агент, связанный с Высшим орденом. Его замечают одного на пути к Святилищу Акира, и он становится мишенью Айессы Певицы Рассвета, пытающейся запугать его организацию.",al={"belathaan brightwish","belthaan","who is belathaan","белатаан яркое желание","белатан","кто такой белатаан"}},{q="Что такое Высший орден?",a="Высший орден — фракция, действующая на острове Зефрис, чья деятельность противоречит интересам местных Ваятелей ветра. Несмотря на недвусмысленные предупреждения, они продолжают совать нос в чужие дела.",al={"high order","the high order lore","what is the high order","высший орден","предания высшего ордена","что такое высший орден"}},{q="Где находится Святилище Акира?",a="Святилище Акира лежит к северу от городка на острове Зефрис. Белатаана перехватывают на безлюдной дороге, ведущей к этому месту.",al={"shrine of akir","where is shrine of akir","shrine akir zephras","святилище акира","где святилище акира","святилище акира зефрис"}},{q="Почему Айесса хочет, чтобы Белатаана избили, а не убили?",a="Айесса прямо стремится послать сообщение, а не начать полномасштабную войну. Избив Белатаана и позволив ему вернуться к начальству, она надеется внушить страх и уважение к границам Ваятелей ветра.",al={"kill belathaan","why spare belathaan","why just bruises","убить белатаана","почему пощадить белатаана","почему только синяки"}},{q="Что за Живые бури встречаются во время этого задания?",a="Живые бури — стихийные существа, возникающие во время схватки с Белатааном на дороге и отражающие переменчивые энергии стихий, свойственные острову Зефрис.",al={"living storms","what are living storms","живые бури","что такое живые бури"}}},fp="15,343,16.443.0,18.419.1,25.193.0,28.200.0,23.198.0,36.140.0,57.210.0,56.172.0"}
P.entries["quest:94"] = {n="Недремлющее Око",s="«Недремлющее Око» — задание Альянса, которое выдает волшебник Теокрит из Башни Азоры в Элвиннском лесу. Установив простую связь ясновидения против своего соперника Морганта, Теокрит направляет искателей приключений на восток, в Красногорье, чтобы закрепить зачарованный фокус на древней статуе льва, наблюдающей за Башней Илгалара.",h="«Недремлющее Око» — задание Альянса, которое выдает волшебник Теокрит из Башни Азоры в Элвиннском лесу.",kw={"elwynn","glyph of azora","morganth","old lion statue","redridge","theocritus","tower of azora","tower of ilgalar","элвинн","амулет азоры","моргант","старая статуя льва","красногорье","теокрит","башня азоры","башня илгалара"},ang={["class:Mage"]="Для знатоков тайных искусств это задание демонстрирует дальнее ясновидение и ретрансляторы, противопоставляя упорядоченные методы Теокрита из Элвиннской академии незаконному колдовству отступника Морганта.",["faction:Alliance"]="Обезвреживание мятежных заклинателей-людей вроде Морганта жизненно важно для защиты границы между Элвиннским лесом и осажденными поселениями Красногорья."},sec={{t="Соперничество через границу",b="Из своей башни на востоке Элвиннского леса маг Теокрит неусыпно следит за темным колдовством, зреющим в соседних холмах. Его главный враг — Моргант, жестокий чародей огромной силы, захвативший Башню Илгалара в скалах Красногорья. Стремясь раскрыть зловещие замыслы Морганта прежде, чем они выйдут за границу, Теокрит создал Око Азоры, чтобы наблюдать за вероломным волшебником издалека."},{t="Дозор льва",b="Зрительное ясновидение дает некоторые сведения, но их недостаточно, чтобы разгадать глубинные замыслы Морганта. Теокрит доверяет путникам Амулет Азоры и велит им дойти до тени Башни Илгалара. Там десятилетиями несет одинокий дозор Старая статуя льва. Если вставить амулет в стертое углубление у основания статуи, пробуждается тайный проводник, связывающий камень с Азорой и позволяющий Теокриту проникнуть прямо в разум соперника."}},faq={{q="Кто такой Теокрит?",a="Теокрит — могущественный волшебник Альянса, живущий на вершине Башни Азоры на востоке Элвиннского леса. Он посвящает свои тайные изыскания защите края от вероломных магических угроз, главная из которых — мятежный чародей Моргант.",al={"theocritus","tower of azora mage","who gives a watchful eye","теокрит","маг башни азоры","кто дает недремлющее око"}},{q="Кто такой Моргант?",a="Моргант — злобный волшебник-отступник из людей, устроивший себе оплот в Башне Илгалара в Красногорье. Он заклятый соперник Теокрита, который опасается темных замыслов, которые Моргант плетет против окрестных земель.",al={"morganth","who is morganth","rival mage","моргант","кто такой моргант","маг-соперник"}},{q="Где находится Старая статуя льва?",a="Старая статуя льва, обветренная, стоит на хребтах над Башней Илгалара, в северо-восточных холмах Красногорья. У ее основания есть неглубокое углубление, предназначенное для магических фокусов, таких как Амулет Азоры.",al={"lion statue location","where is the statue","where to put glyph of azora","где статуя льва","где находится статуя","куда положить амулет азоры"}},{q="Что делает Амулет Азоры?",a="Амулет Азоры — зачарованный камень, созданный Теокритом. Если вставить его в статую льва возле Башни Илгалара, он служит тайным прослушивающим постом и ретранслятором для проникновения в разум, позволяя Теокриту общаться через камень и изучать мысли Морганта.",al={"glyph of azora","what is the glyph","амулет азоры","что такое амулет"}},{q="Что такое Башня Илгалара?",a="Башня Илгалара — высокий уединенный каменный шпиль в скалах северо-востока Красногорья. Это башня магов, которую сейчас занимают и обороняют Моргант и его приспешники.",al={"tower of ilgalar","ilgalar","башня илгалара","илгалар"}},{q="Что происходит после установки амулета?",a="Once the Glyph of Azora is fixed to the statue, Theocritus speaks through the stone and immediately offers the follow-up quest, Looking Further, as he begins unraveling Morganth's machinations.",al={"next quest","what after a watchful eye","следующее задание","что после недремлющего ока"}}},fp="14,324,27.449.0,16.474.0,18.237.0,16.241.0,37.230.0,32.265.0,29.193.0,35.193.0"}
P.entries["quest:940"] = {n="Тельдрассил",s="После изгнания обезумевших гарпий у Древа Оракула Часовой Арания Проблеск Солнца поручает вам доставить в Дарнасс отчет о положении дел. Исписанная кора адресована верховному друиду Фэндралу Оленьему Шлему и содержит вести о состоянии ветвей и не прекращающейся порче, терзающей Мировое Древо.",h="После изгнания обезумевших гарпий у Древа Оракула Часовой Арания Проблеск Солнца поручает вам доставить в...",kw={"arynia cloudsbreak","cenarion enclave","darnassus","fandral staghelm","immortality","inscribed bark","kaldorei","oracle tree","teldrassil","арания проблеск солнца","анклав кенария","дарнасс","фэндрал олений шлем","бессмертие","исписанная кора","кальдораи","древо оракула","тельдрассил"},ang={["class:Druid"]="Доставка вести от древнего Древа Оракула прямо главе Круга Кенария подчеркивает непрекращающуюся борьбу за очищение природного равновесия Тельдрассила.",["faction:Alliance"]="Для героев Альянса, завершающих первые обязанности на острове, это поручение становится официальным знакомством со столицей ночных эльфов и ее суровым руководством.",["race:NightElf"]="Доставка этого отчета сводит вас лицом к лицу с верховным друидом Оленьим Шлемом и раскрывает его личную одержимость возвращением бессмертия кальдораев через израненные ветви Тельдрассила."},sec={{t="Посланник в каменный город",b="Глубоко в ветвях Тельдрассила Древо Оракула охраняет лес. После того как гарпии были изгнаны из своих гнезд в Зачарованной поляне, Часовой Арания Проблеск Солнца решает, что наконец можно безопасно отправить весть руководству кальдораев. Вручив вам кусок исписанной коры, она отправляет вас через дикие земли в Дарнасс — великий «каменный лес», — чтобы вы передали отчет Древа Оракула лично верховному друиду Фэндралу Оленьему Шлему."},{t="Честолюбие и разочарование Оленьего Шлема",b="Получив отчет, Фэндрал Олений Шлем воспринимает его со смешанными чувствами. Хотя он рад вести об отступлении гарпий, отчет подчеркивает более глубокую истину: стоит одной угрозе на Тельдрассиле ослабнуть, как на ее месте начинает гнить другая. Для Оленьего Шлема, отстаивавшего посадку нового Мирового Древа ради возвращения утраченного бессмертия ночных эльфов, непрекращающиеся недуги ветвей — горькое напоминание о том, что его великий труд далек от завершения."}},faq={{q="Каково назначение задания «Тельдрассил»?",a="Это задание служит сюжетным мостом, связывающим ваши приключения в глуши у Древа Оракула со столицей. Часовой Арания Проблеск Солнца поручает вам доставить верховному друиду Фэндралу Оленьему Шлему в Дарнасс исписанную кору с отчетом Древа Оракула.",al={"teldrassil quest objective","what does this quest do","teldrassil delivery","цель задания тельдрассил","что дает это задание","доставка тельдрассил"}},{q="Кто такая Часовой Арания Проблеск Солнца?",a="Арания Проблеск Солнца — часовой из числа ночных эльфов, расквартированная у Древа Оракула в глуши Тельдрассила. Она следит за местными угрозами, такими как гарпии Кровавого Пера, и согласует с Дарнассом оборону леса.",al={"arynia cloudsbreak lore","who starts teldrassil quest","арания проблеск солнца","кто выдает задание тельдрассил"}},{q="Почему Арания называет Дарнасс «каменным лесом»?",a="Хотя ночные эльфы живут в кроне Мирового Древа, город Дарнасс построен из величественных мраморных и каменных храмов, мостов и павильонов. По сравнению с нетронутой глушью вокруг Древа Оракула столица — рукотворный каменный лес.",al={"forest of stone meaning","why forest of stone","значение каменный лес","почему каменный лес"}},{q="Почему Фэндрала Оленьего Шлема так беспокоит отчет Древа Оракула?",a="Олений Шлем возглавил создание Тельдрассила в надежде вернуть кальдораям бессмертие после того, как Нордрассил был поврежден в Третьей войне. Вести от Древа Оракула подтверждают, что Тельдрассил продолжает страдать от распространяющейся порчи и смятения среди животных, что ставит под угрозу его замыслы.",al={"fandral staghelm reaction","why is staghelm worried","реакция фэндрала оленьего шлема","почему олений шлем обеспокоен"}},{q="Какое задание предшествует этому и какое идет следом?",a="Это задание идет сразу после «Зачарованной поляны», где вы разбираетесь с гарпиями, угрожающими Древу Оракула. После передачи отчета верховному друиду Оленьему Шлему он отправляет вас дальше, на Темные берега, с продолжением — заданием «Роща Древних».",al={"teldrassil quest chain","what quest next","цепочка заданий тельдрассил","какое задание дальше"}},{q="Где можно найти верховного друида Фэндрала Оленьего Шлема?",a="Верховный друид Фэндрал Олений Шлем живет в Дарнассе, на вершине Анклава Кенария, где он надзирает за друидами Круга Кенария и направляет управление кальдораями.",al={"where is fandral","fandral staghelm location","где фэндрал","где найти фэндрала оленьего шлема"}}},fp="10,307,29.453.0,35.481.0,46.270.0,35.212.0,51.265.0,68.291.0,48.246.0,47.191.0"}
P.entries["quest:941"] = {kw={"blackmoss the fetid","cleansed heart","denalan","lake al'ameth","planter","tainted heart","teldrassil","timberling","черномшец злосмрадный","очищенное сердце","деналан","озеро аль'амет","грядка","оскверненное сердце","тельдрассил","древень"},ang={["class:Druid"]="Для друида зрелище того, как сердцевина оскверненного древня очищается богатой землей, — обнадеживающий знак: неестественную порчу, поражающую ветви Мирового Древа, все еще можно обратить вспять естественной заботой.",["profession:Herbalism"]="Мастерство Деналана в работе с питательной почвой и восстановлении растений показывает важную связь между изучением земли и исцелением поврежденных растений.",["race:NightElf"]="Возрождение живой древесины и пробуждение жизни в павших лесных духах отражает стремление кальдораев оберегать природу даже перед лицом тревожных недугов Тельдрассила."},sec={{t="Второй шанс на жизнь",b="While examining the strange wooden organ recovered from the corrupted timberling known as Blackmoss the Fetid, Denalan manages to scrape away the foul moss strangling its surface. Yet despite his efforts, a deeper, unnatural taint still pulses within the wood. Rather than burn or discard it, Denalan relies on his lifelong craft of botany and soil tending. He instructs travelers to bury the heart directly into his personal planter box, trusting the rich nutrients he blended to coax whatever natural vitality remains back toward health."},{t="Чудо обогащенной земли",b="Помещение почерневшего деревянного сердца в грядку Деналана приводит к неожиданной реакции. Едва коснувшись плодородной почвы, сердце зарывается в землю, словно ведомое первобытным инстинктом. Спустя мгновения оно снова появляется на поверхности, очищенное от мерзкой порчи и пульсирующее мягким, дружелюбным теплом. Очистив семя павшего оскверненного создания, Деналан показывает, что даже когда дикие обитатели Тельдрассила становятся жертвами неестественных напастей, бережный уход и священная земля все же способны восстановить гармонию."}},faq={{q="Откуда взялось это оскверненное сердце?",a="Сердце изначально принадлежало Черномшецу злосмрадному, оскверненному древню, обитавшему на берегах озера Аль'Амет. Его нашли задушенным спутанным мерзким мхом, пока Деналан не очистил его.",al={"heart origin","where did the heart come from","blackmoss heart","происхождение сердца","откуда взялось сердце","сердце черномшеца"}},{q="Кто такой Деналан?",a="Деналан — ночной эльф, ботаник и травник, обитающий в уединенном лагере на восточном берегу озера Аль'Амет. Он проводит дни за изучением растений Тельдрассила, исследованием странной порчи, расползающейся по ветвям, и составлением обогащенных почв.",al={"who is denalan","denalan lore","кто такой деналан","деналан предания"}},{q="Почему сердце сажают в грядку, а не уничтожают?",a="Деналан считает, что природу нужно понимать и исцелять, а не просто уничтожать оскверненные существа. Он надеется, что приготовленная им питательная почва сможет изгнать порчу и вернуть сердцу его первоначальную чистую жизненную силу.",al={"why plant the heart","why heal the heart","зачем сажать сердце","зачем исцелять сердце"}},{q="Что происходит, когда вы закапываете сердце?",a="Сердце тут же зарывается в почву. Через несколько секунд оно выползает обратно на поверхность, полностью очищенное от мерзкой порчи, и мягко пульсирует, словно живой спутник.",al={"what happens in the planter","heart burrows","что происходит в грядке","сердце зарывается"}},{q="Исцеляет ли это порчу древней?",a="Исцеляется лишь это одно спасенное сердце. Оно доказывает, что отдельных духов растений можно очистить заботой и богатой почвой, но общая порча, распространяющаяся по Тельдрассилу, остается реальной опасностью.",al={"are timberlings cured","curing timberlings","исцелены ли древни","лечение древней"}},{q="Чем особенна почва в грядке Деналана?",a="Деналан немало времени экспериментировал с компостом и питательными смесями почвы у озера Аль'Амет, создавая землю, достаточно сильную, чтобы оживлять больные растения и останавливать подкрадывающееся гниение.",al={"denalan soil","planter soil","почва деналана","почва в грядке"}}},fp="18,318,23.539.0,29.534.1,40.198.0,15.256.0,56.209.0,37.184.1,49.213.0,45.192.0"}
P.entries["quest:942"] = {n="Рассеянный геолог",s="Это задание переносит загадку раскопок с Темных берегов через Великое море в Болотину. Главный археолог Седоус вручает вам странное ископаемое из Калимдора и направляет к Археологу Бутылопузу в Гавани Менетилов, чтобы раскрыть его тайны.",h="Это задание переносит загадку раскопок с Темных берегов через Великое море в Болотину.",kw={"absent minded prospector","archaeologist flagongut","chief archaeologist greywhisker","darkshore","deepwater tavern","explorers' league","menethil harbor","mysterious fossil","рассеянный геолог","археолог бутылопуз","главный археолог седоус","темные берега","таверна большая вода","лига исследователей","гавань менетилов","загадочное ископаемое"},ang={["faction:Alliance"]="Это задание требует воспользоваться морскими маршрутами Альянса и отправиться морем из Калимдора в Гавань Менетилов, чтобы поддерживать связь между отделениями Лиги.",["race:Dwarf"]="Для дворфов-приключенцев это поручение показывает размах Лиги исследователей, связывающей полевую работу в далеком Калимдоре с коллегами-учеными в Каз Модане."},sec={{t="Любопытная находка",b="Осматривая странное ископаемое, найденное на Темных берегах, Главный археолог Седоус замечает поразительное сходство с реликвией, показанной на конференции Лиги исследователей в Стальгорне. Ту вещь представил Археолог Бутылопуз, убежденный, что такие окаменелости таят скрытые силы, ждущие пробуждения. Седоус считает, что Бутылопуз — единственный дворф, способный понять, чем так необычна эта находка из Калимдора."},{t="Путешествие через море",b="Доставка загадочной реликвии означает долгий путь из Калимдора в Восточные королевства. Бутылопуза в последний раз видели в Таверне «Большая вода» в Гавани Менетилов, где он ждал вооруженного сопровождения до Раскопок Вельгара. Передача ископаемого ему в руки — переломный момент, когда местное исследование на Темных берегах смыкается с археологическим поиском, охватывающим целые континенты."}},faq={{q="Почему Седоус отправляет меня так далеко, в Гавань Менетилов?",a="Главный археолог Седоус помнит, что Археолог Бутылопуз показывал точно такую же реликвию на ежегодной конференции Лиги исследователей в Стальгорне. Полагая, что Бутылопуз обладает знаниями, чтобы раскрыть ее скрытую силу, Седоус посылает вас найти его там, где его видели в последний раз, — в Гавани Менетилов.",al={"why go to menethil","greywhisker fossil errand","why wetlands","зачем идти в менетилов","поручение седоуса с ископаемым","зачем в болотину"}},{q="Кто такой Археолог Бутылопуз?",a="Археолог Бутылопуз — исследователь из Лиги исследователей, находящийся в Болотине. Пережидая задержки в Таверне «Большая вода» в Гавани Менетилов, он готовится к экспедиции на опасные Раскопки Вельгара.",al={"who is flagongut","archaeologist flagongut lore","кто такой бутылопуз","археолог бутылопуз предания"}},{q="Что это за загадочное ископаемое?",a="Это древний любопытный образец, найденный на Темных берегах. Бутылопуз ранее утверждал, что изученный им точно такой же образец обладал скрытой магической или исторической силой, ждущей пробуждения.",al={"what is the fossil","mysterious fossil origin","remtravel fossil","что за ископаемое","происхождение загадочного ископаемого","ископаемое сомнамбулера"}},{q="Что говорит Бутылопуз, когда вы передаете ископаемое?",a="Бутылопуз поражен, узнав, что реликвия, идентичная его собственному образцу, происходит с далекого континента Калимдор, а значит, древняя история связывает две земли.",al={"flagongut reaction","handing in the fossil","реакция бутылопуза","передача ископаемого"}},{q="Куда Бутылопуз хочет отправиться дальше?",a="Бутылопуз ждет в Гавани Менетилов сопровождения, чтобы отправиться вглубь суши к Раскопкам Вельгара — крупному месту раскопок в Болотине.",al={"where is flagongut going","flagongut excavation","куда идет бутылопуз","раскопки бутылопуза"}},{q="Как это задание вписывается в цепочку «Рассеянный геолог»?",a="It serves as the transit leg of the questline. After escorting and rescuing Prospector Remtravel in Darkshore and analyzing his excavated relic with Greywhisker, the inquiry shifts from northern Kalimdor directly to League experts in the Eastern Kingdoms.",al={"absent minded prospector part 4","quest chain context","рассеянный геолог часть 4","контекст цепочки заданий"}}},fp="28,253,19.451.0,23.391.0,60.307.0,31.223.0,30.190.0,52.202.0,37.159.0,68.255.0"}
